import { useState, useEffect, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';

interface PersistOptions<T extends string> {
  paramName?: string;
  defaultTab: T;
  storageKey?: string;
  validTabs?: T[];
}

/**
 * Custom hook to persist active tab/sub-tab across browser refresh,
 * direct URL links, and browser back/forward navigation.
 */
export function usePersistedTab<T extends string>({
  paramName = 'tab',
  defaultTab,
  storageKey,
  validTabs,
}: PersistOptions<T>): [T, (tab: T) => void] {
  const [searchParams, setSearchParams] = useSearchParams();

  // Determine initial tab from URL, then Storage, then default
  const getInitialTab = (): T => {
    // 1. Check URL query param
    const paramVal = searchParams.get(paramName) as T | null;
    if (paramVal && (!validTabs || validTabs.includes(paramVal))) {
      return paramVal;
    }

    // 2. Check URL hash (e.g. #identity)
    if (typeof window !== 'undefined' && window.location.hash) {
      const hashVal = window.location.hash.replace('#', '') as T;
      if (hashVal && (!validTabs || validTabs.includes(hashVal))) {
        return hashVal;
      }
    }

    // 3. Check sessionStorage
    if (storageKey && typeof sessionStorage !== 'undefined') {
      const sessionVal = sessionStorage.getItem(storageKey) as T | null;
      if (sessionVal && (!validTabs || validTabs.includes(sessionVal))) {
        return sessionVal;
      }
    }

    // 4. Check localStorage
    if (storageKey && typeof localStorage !== 'undefined') {
      const localVal = localStorage.getItem(storageKey) as T | null;
      if (localVal && (!validTabs || validTabs.includes(localVal))) {
        return localVal;
      }
    }

    return defaultTab;
  };

  const [activeTab, setActiveTabState] = useState<T>(getInitialTab);

  // Sync tab changes to URL and browser storage
  const setTab = useCallback(
    (newTab: T) => {
      setActiveTabState(newTab);

      // Update storage
      if (storageKey) {
        try {
          sessionStorage.setItem(storageKey, newTab);
          localStorage.setItem(storageKey, newTab);
        } catch {}
      }

      // Update URL query parameter without full page reload
      setSearchParams(
        (prev) => {
          const next = new URLSearchParams(prev);
          next.set(paramName, newTab);
          return next;
        },
        { replace: true }
      );
    },
    [paramName, storageKey, setSearchParams]
  );

  // Listen to browser Back/Forward navigation
  useEffect(() => {
    const currentUrlParam = searchParams.get(paramName) as T | null;
    if (currentUrlParam && currentUrlParam !== activeTab) {
      if (!validTabs || validTabs.includes(currentUrlParam)) {
        setActiveTabState(currentUrlParam);
        if (storageKey) {
          sessionStorage.setItem(storageKey, currentUrlParam);
        }
      }
    }
  }, [searchParams, paramName, activeTab, storageKey, validTabs]);

  return [activeTab, setTab];
}

import { useState, useMemo, useEffect } from 'react';
import { useSearchParams, useNavigate, Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { AuthLayout } from '@/components/layouts/AuthLayout';
import { FormField } from '@/components/ui/composed/FormField';
import { Input } from '@/components/ui/primitives/Input';
import { Button } from '@/components/ui/primitives/Button';
import { showToast } from '@/components/ui/composed/Toast.utils';
import {
  validateInvitation,
  acceptInvitation,
  type InvitationRecord,
} from '@/services/auditService';
import { ensureEmployeeProfileExists } from '@/services/employeeProfileService';
import {
  ShieldCheck,
  Eye,
  EyeOff,
  Check,
  X,
  AlertTriangle,
  UserCheck,
  CheckCircle2,
} from 'lucide-react';

export default function OnboardingPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();

  const tokenParam = searchParams.get('token');
  const emailParam = searchParams.get('email');

  // Step 1: Security, Step 2: Personal & Contact, Step 3: Work & Org, Step 4: Review & Confirmation, Step 5: Success
  const [currentStep, setCurrentStep] = useState<1 | 2 | 3 | 4 | 5>(1);

  // Invitation Verification State
  const [verifying, setVerifying] = useState(true);
  const [invitationStatus, setInvitationStatus] = useState<{
    valid: boolean;
    reason?:
      | 'missing_token'
      | 'not_found'
      | 'expired'
      | 'revoked'
      | 'already_accepted'
      | 'duplicate_account';
    invitation?: InvitationRecord;
  }>({ valid: false });

  // Form Fields State
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);

  // Profile Details
  const [fullName, setFullName] = useState('');
  const [contactNo, setContactNo] = useState('');
  const [streetAddress, setStreetAddress] = useState('');
  const [city, setCity] = useState('');
  const [stateRegion, setStateRegion] = useState('');
  const [postalCode, setPostalCode] = useState('');
  const [country, setCountry] = useState('United States');

  // Work Details
  const [designation, setDesignation] = useState('');
  const [department, setDepartment] = useState('Engineering');
  const [workLocation, setWorkLocation] = useState('Headquarters');
  const [company, setCompany] = useState('AetherAdix Technologies');

  // Policies
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [acceptedSecurityPolicy, setAcceptedSecurityPolicy] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Verify invitation on mount or param change
  useEffect(() => {
    setVerifying(true);
    const result = validateInvitation(tokenParam, emailParam);
    setInvitationStatus(result);

    if (result.invitation) {
      setFullName(result.invitation.name || '');
      setDepartment(result.invitation.department || 'Engineering');
      setDesignation(result.invitation.role || 'Team Member');
    }

    setVerifying(false);
  }, [tokenParam, emailParam]);

  // Password rules check
  const passwordChecks = useMemo(() => {
    return {
      minLength: password.length >= 8,
      hasUpper: /[A-Z]/.test(password),
      hasLower: /[a-z]/.test(password),
      hasNumber: /[0-9]/.test(password),
      hasSpecial: /[!@#$%^&*(),.?":{}|<>]/.test(password),
      matches: password.length > 0 && password === confirmPassword,
    };
  }, [password, confirmPassword]);

  const isPasswordValid =
    passwordChecks.minLength &&
    passwordChecks.hasUpper &&
    passwordChecks.hasLower &&
    passwordChecks.hasNumber &&
    passwordChecks.hasSpecial &&
    passwordChecks.matches;

  // Strength score
  const strengthScore = useMemo(() => {
    let score = 0;
    if (passwordChecks.minLength) score++;
    if (passwordChecks.hasUpper) score++;
    if (passwordChecks.hasLower) score++;
    if (passwordChecks.hasNumber) score++;
    if (passwordChecks.hasSpecial) score++;
    return score;
  }, [passwordChecks]);

  // Validation per step
  const isStep2Valid =
    fullName.trim().length >= 2 &&
    contactNo.trim().length >= 7 &&
    streetAddress.trim().length >= 3 &&
    city.trim().length >= 2;

  const isStep3Valid = designation.trim().length >= 2 && department.trim().length >= 2;

  const isStep4Valid = acceptedTerms && acceptedSecurityPolicy;

  // Final submission handler
  const handleCompleteOnboarding = async () => {
    if (!isStep4Valid || !invitationStatus.invitation) return;

    setIsSubmitting(true);
    try {
      const email = invitationStatus.invitation.email;
      const fullAddress =
        `${streetAddress}, ${city}, ${stateRegion} ${postalCode}, ${country}`.replace(
          /,\s*,/g,
          ','
        );

      // Mark invitation accepted in audit log
      acceptInvitation(invitationStatus.invitation.token, {
        name: fullName,
        email,
        role: invitationStatus.invitation.role,
        department,
        address: fullAddress,
        contactNo,
      });

      // Save user record to local store so they can log in seamlessly
      const newUser = {
        id: Date.now(),
        username: fullName,
        email,
        role: invitationStatus.invitation.role,
        department,
        designation,
        work_location: workLocation,
        company,
        country,
        contact_number: contactNo,
        address: fullAddress,
        join_date: new Date().toISOString().split('T')[0],
      };

      // Add to mock staff list in localStorage
      try {
        const savedStaff = JSON.parse(localStorage.getItem('aether_staff_list') || '[]');
        const updatedStaff = [newUser, ...savedStaff.filter((s: any) => s.email !== email)];
        localStorage.setItem('aether_staff_list', JSON.stringify(updatedStaff));
      } catch {
        // Ignore
      }

      // Initialize/Update employee profile so Hiring Team can monitor onboarding progress
      ensureEmployeeProfileExists(
        newUser.id,
        email,
        fullName,
        invitationStatus.invitation.role,
        department,
        {
          contactNumber: contactNo,
          currentAddress: fullAddress,
          permanentAddress: fullAddress,
        }
      );

      showToast({
        severity: 'success',
        summary: 'Account Activated',
        detail: 'Welcome aboard! Your profile and credentials have been established.',
        life: 4000,
      });

      setCurrentStep(5);
    } catch {
      showToast({
        severity: 'error',
        summary: 'Onboarding Failed',
        detail: 'An error occurred while finalizing your account. Please try again.',
        life: 4000,
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  // 1. Loading State
  if (verifying) {
    return (
      <AuthLayout title="Account Setup" subtitle="VERIFYING INVITATION SECURITY CREDENTIALS...">
        <div className="py-20 flex flex-col items-center justify-center gap-4 animate-pulse">
          <div className="w-12 h-12 rounded-2xl bg-primary/20 flex items-center justify-center text-primary">
            <i className="pi pi-spin pi-spinner text-2xl" />
          </div>
          <span className="text-xs font-black uppercase tracking-widest text-muted">
            Validating Security Token...
          </span>
        </div>
      </AuthLayout>
    );
  }

  // 2. Expired Invitation Screen
  if (!invitationStatus.valid && invitationStatus.reason === 'expired') {
    return (
      <AuthLayout title="Invitation Expired" subtitle="SECURITY VALIDATION NOTICE">
        <div className="bg-white rounded-3xl p-8 border border-border-subtle shadow-soft flex flex-col items-center text-center gap-6">
          <div className="w-16 h-16 rounded-2xl bg-warning/10 text-warning flex items-center justify-center">
            <AlertTriangle size={32} />
          </div>

          <div className="space-y-2">
            <h3 className="text-xl font-black text-foreground">This invitation link has expired</h3>
            <p className="text-xs text-muted leading-relaxed max-w-sm">
              For security compliance, user invitation tokens expire after 7 days. This invitation
              was sent on{' '}
              <strong>
                {invitationStatus.invitation?.invitedAt
                  ? new Date(invitationStatus.invitation.invitedAt).toLocaleDateString()
                  : 'earlier'}
              </strong>{' '}
              and is no longer valid.
            </p>
          </div>

          <div className="w-full p-4 rounded-xl bg-surface-subtle border border-border-subtle text-left text-xs space-y-1">
            <div className="flex justify-between">
              <span className="text-muted font-semibold">Invited Email:</span>
              <span className="font-bold text-foreground">
                {invitationStatus.invitation?.email || emailParam || 'Unknown'}
              </span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted font-semibold">Invited By:</span>
              <span className="font-bold text-foreground">
                {invitationStatus.invitation?.invitedBy?.name || 'Administrator'}
              </span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted font-semibold">Status:</span>
              <span className="font-black text-error uppercase text-[10px]">EXPIRED</span>
            </div>
          </div>

          <p className="text-xs text-muted">
            Please contact your organization administrator or HR department to request a new
            invitation link.
          </p>

          <div className="flex flex-col sm:flex-row gap-3 w-full">
            <Link to="/auth/login" className="flex-1">
              <Button variant="ghost" label="Return to Login" className="w-full rounded-xl!" />
            </Link>
            <Button
              variant="primary"
              label="Contact Support"
              onClick={() => {
                showToast({
                  severity: 'info',
                  summary: 'Support Notified',
                  detail: 'An automatic renewal request has been flagged for your administrator.',
                  life: 3500,
                });
              }}
              className="flex-1 rounded-xl! shadow-md shadow-primary/20"
            />
          </div>
        </div>
      </AuthLayout>
    );
  }

  // 3. Revoked Invitation Screen
  if (!invitationStatus.valid && invitationStatus.reason === 'revoked') {
    return (
      <AuthLayout title="Invitation Revoked" subtitle="ACCESS RESTRICTION NOTICE">
        <div className="bg-white rounded-3xl p-8 border border-border-subtle shadow-soft flex flex-col items-center text-center gap-6">
          <div className="w-16 h-16 rounded-2xl bg-error/10 text-error flex items-center justify-center">
            <AlertTriangle size={32} />
          </div>

          <div className="space-y-2">
            <h3 className="text-xl font-black text-foreground">Invitation Revoked</h3>
            <p className="text-xs text-muted leading-relaxed max-w-sm">
              This invitation was cancelled or revoked by an administrator on{' '}
              <strong>
                {invitationStatus.invitation?.revokedAt
                  ? new Date(invitationStatus.invitation.revokedAt).toLocaleDateString()
                  : 'a previous date'}
              </strong>
              . Access via this link is disabled.
            </p>
          </div>

          <Link to="/auth/login" className="w-full">
            <Button variant="primary" label="Back to Login" className="w-full rounded-xl!" />
          </Link>
        </div>
      </AuthLayout>
    );
  }

  // 4. Already Accepted / Duplicate Account Screen
  if (!invitationStatus.valid && invitationStatus.reason === 'already_accepted') {
    return (
      <AuthLayout title="Account Already Active" subtitle="ONBOARDING ALREADY COMPLETED">
        <div className="bg-white rounded-3xl p-8 border border-border-subtle shadow-soft flex flex-col items-center text-center gap-6">
          <div className="w-16 h-16 rounded-2xl bg-success/10 text-success flex items-center justify-center">
            <UserCheck size={32} />
          </div>

          <div className="space-y-2">
            <h3 className="text-xl font-black text-foreground">Welcome Back!</h3>
            <p className="text-xs text-muted leading-relaxed max-w-sm">
              An account associated with{' '}
              <strong className="text-foreground">
                {invitationStatus.invitation?.email || emailParam}
              </strong>{' '}
              has already been successfully activated. You can sign in immediately using your
              established password.
            </p>
          </div>

          <Link to="/auth/login" className="w-full">
            <Button
              variant="primary"
              label="Proceed to Login"
              icon="pi pi-sign-in"
              className="w-full rounded-xl! shadow-md shadow-primary/20"
            />
          </Link>
        </div>
      </AuthLayout>
    );
  }

  // 5. Missing / Invalid Token Screen
  if (!invitationStatus.valid) {
    return (
      <AuthLayout title="Invalid Invitation Link" subtitle="AUTHENTICATION ERROR">
        <div className="bg-white rounded-3xl p-8 border border-border-subtle shadow-soft flex flex-col items-center text-center gap-6">
          <div className="w-16 h-16 rounded-2xl bg-error/10 text-error flex items-center justify-center">
            <AlertTriangle size={32} />
          </div>

          <div className="space-y-2">
            <h3 className="text-xl font-black text-foreground">Missing or Invalid Token</h3>
            <p className="text-xs text-muted leading-relaxed max-w-sm">
              We could not verify the security token provided in this URL. Please verify that you
              clicked the complete link sent in your invitation email.
            </p>
          </div>

          <Link to="/auth/login" className="w-full">
            <Button variant="ghost" label="Return to Login" className="w-full rounded-xl!" />
          </Link>
        </div>
      </AuthLayout>
    );
  }

  // 6. Success Screen (Step 5)
  if (currentStep === 5) {
    return (
      <AuthLayout title="Onboarding Complete" subtitle="ACCOUNT ACTIVATED SUCCESSFULLY">
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="bg-white rounded-3xl p-8 border border-border-subtle shadow-soft flex flex-col items-center text-center gap-6">
          <div className="w-20 h-20 rounded-full bg-success/10 text-success flex items-center justify-center animate-bounce">
            <CheckCircle2 size={40} />
          </div>

          <div className="space-y-2">
            <h3 className="text-2xl font-black text-foreground">Welcome to AetherERP!</h3>
            <p className="text-xs text-muted leading-relaxed max-w-sm">
              Your password has been securely configured and your employee profile is now active.
              You may now sign in to access your workspace.
            </p>
          </div>

          <div className="w-full p-4 rounded-xl bg-surface-subtle border border-border-subtle text-left text-xs space-y-2">
            <div className="flex justify-between">
              <span className="text-muted font-semibold">User:</span>
              <span className="font-bold text-foreground">{fullName}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted font-semibold">Work Email:</span>
              <span className="font-bold text-foreground">
                {invitationStatus.invitation?.email}
              </span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted font-semibold">Assigned Role:</span>
              <span className="font-bold text-primary">{invitationStatus.invitation?.role}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted font-semibold">Department:</span>
              <span className="font-bold text-foreground">{department}</span>
            </div>
          </div>

          <Button
            variant="primary"
            label="Sign In to Dashboard"
            icon="pi pi-arrow-right"
            onClick={() => navigate('/auth/login')}
            className="w-full h-12 rounded-xl! font-bold! shadow-lg shadow-primary/20"
          />
        </motion.div>
      </AuthLayout>
    );
  }

  const role = invitationStatus.invitation?.role || 'Employee';
  const email = invitationStatus.invitation?.email || '';

  // 7. Interactive Multi-Step Onboarding Form
  return (
    <AuthLayout
      title="Complete Your Onboarding"
      subtitle={`STEP ${currentStep} OF 4 — SECURE ACCOUNT ACTIVATION`}>
      {/* Progress Bar */}
      <div className="mb-8">
        <div className="flex items-center justify-between text-[10px] font-extrabold uppercase tracking-wider text-muted mb-2">
          <span className={currentStep >= 1 ? 'text-primary font-black' : ''}>1. Security</span>
          <span className={currentStep >= 2 ? 'text-primary font-black' : ''}>2. Profile</span>
          <span className={currentStep >= 3 ? 'text-primary font-black' : ''}>3. Organization</span>
          <span className={currentStep >= 4 ? 'text-primary font-black' : ''}>4. Review</span>
        </div>
        <div className="h-1.5 w-full bg-surface-subtle rounded-full overflow-hidden flex gap-1">
          {[1, 2, 3, 4].map((step) => (
            <div
              key={step}
              className={`h-full flex-1 rounded-full transition-all duration-300 ${
                currentStep >= step ? 'bg-primary' : 'bg-border-subtle/40'
              }`}
            />
          ))}
        </div>
      </div>

      {/* Recipient Header Badge */}
      <div className="mb-6 p-4 rounded-2xl bg-primary/5 border border-primary/10 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-primary/10 text-primary flex items-center justify-center font-bold text-sm">
            {fullName ? fullName.charAt(0).toUpperCase() : 'U'}
          </div>
          <div>
            <div className="text-xs font-black text-foreground">{fullName || 'Invited User'}</div>
            <div className="text-[11px] text-muted">{email}</div>
          </div>
        </div>
        <span className="px-3 py-1 rounded-lg bg-primary/10 text-primary text-[10px] font-extrabold uppercase tracking-wider">
          {role}
        </span>
      </div>

      <AnimatePresence mode="wait">
        {/* STEP 1: PASSWORD & SECURITY SETUP */}
        {currentStep === 1 && (
          <motion.div
            key="step1"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="flex flex-col gap-6">
            <div className="space-y-1">
              <h3 className="text-base font-black text-foreground">Set Account Password</h3>
              <p className="text-xs text-muted">
                Choose a strong master password to safeguard your access to AetherERP.
              </p>
            </div>

            <FormField label="Create New Password" required id="onboarding-password">
              <div className="relative">
                <input
                  id="onboarding-password"
                  type={showPassword ? 'text' : 'password'}
                  placeholder="Enter strong password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pr-11 pl-4 py-3 rounded-xl bg-surface-subtle border border-border-subtle text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted hover:text-foreground p-1 cursor-pointer">
                  {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </FormField>

            {/* Dynamic Strength Meter */}
            {password.length > 0 && (
              <div className="flex flex-col gap-1.5 -mt-2">
                <div className="flex items-center justify-between text-xs">
                  <span className="text-[10px] font-extrabold uppercase text-muted tracking-wider">
                    Strength:
                  </span>
                  <span
                    className={`text-[10px] font-black uppercase px-2 py-0.5 rounded-full ${
                      strengthScore <= 2
                        ? 'bg-error/10 text-error'
                        : strengthScore <= 4
                          ? 'bg-warning/10 text-warning'
                          : 'bg-success/10 text-success'
                    }`}>
                    {strengthScore <= 2
                      ? 'Weak'
                      : strengthScore <= 4
                        ? 'Moderate'
                        : 'Strong & Compliant'}
                  </span>
                </div>
                <div className="h-1.5 w-full bg-surface-subtle rounded-full overflow-hidden flex gap-1">
                  {[1, 2, 3, 4, 5].map((s) => (
                    <div
                      key={s}
                      className={`h-full flex-1 rounded-full transition-all duration-300 ${
                        s <= strengthScore
                          ? strengthScore <= 2
                            ? 'bg-error'
                            : strengthScore <= 4
                              ? 'bg-warning'
                              : 'bg-success'
                          : 'bg-border-subtle/50'
                      }`}
                    />
                  ))}
                </div>
              </div>
            )}

            <FormField label="Confirm Password" required id="onboarding-confirm">
              <div className="relative">
                <input
                  id="onboarding-confirm"
                  type={showConfirm ? 'text' : 'password'}
                  placeholder="Re-enter password to confirm"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="w-full pr-11 pl-4 py-3 rounded-xl bg-surface-subtle border border-border-subtle text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20"
                />
                <button
                  type="button"
                  onClick={() => setShowConfirm(!showConfirm)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted hover:text-foreground p-1 cursor-pointer">
                  {showConfirm ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </FormField>

            {/* Checklist */}
            <div className="p-4 rounded-xl bg-surface-subtle/60 border border-border-subtle flex flex-col gap-2 text-xs">
              <span className="font-bold text-foreground text-[11px] uppercase tracking-wider flex items-center gap-1.5">
                <ShieldCheck size={14} className="text-primary" /> Password Requirements
              </span>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 pt-1 text-[11px]">
                <div
                  className={`flex items-center gap-1.5 ${
                    passwordChecks.minLength ? 'text-success font-semibold' : 'text-muted'
                  }`}>
                  {passwordChecks.minLength ? <Check size={13} /> : <X size={13} />}
                  <span>8+ characters</span>
                </div>
                <div
                  className={`flex items-center gap-1.5 ${
                    passwordChecks.hasUpper ? 'text-success font-semibold' : 'text-muted'
                  }`}>
                  {passwordChecks.hasUpper ? <Check size={13} /> : <X size={13} />}
                  <span>Uppercase (A-Z)</span>
                </div>
                <div
                  className={`flex items-center gap-1.5 ${
                    passwordChecks.hasLower ? 'text-success font-semibold' : 'text-muted'
                  }`}>
                  {passwordChecks.hasLower ? <Check size={13} /> : <X size={13} />}
                  <span>Lowercase (a-z)</span>
                </div>
                <div
                  className={`flex items-center gap-1.5 ${
                    passwordChecks.hasNumber ? 'text-success font-semibold' : 'text-muted'
                  }`}>
                  {passwordChecks.hasNumber ? <Check size={13} /> : <X size={13} />}
                  <span>Number (0-9)</span>
                </div>
                <div
                  className={`flex items-center gap-1.5 ${
                    passwordChecks.hasSpecial ? 'text-success font-semibold' : 'text-muted'
                  }`}>
                  {passwordChecks.hasSpecial ? <Check size={13} /> : <X size={13} />}
                  <span>Special symbol (!@#$)</span>
                </div>
                <div
                  className={`flex items-center gap-1.5 ${
                    passwordChecks.matches ? 'text-success font-semibold' : 'text-muted'
                  }`}>
                  {passwordChecks.matches ? <Check size={13} /> : <X size={13} />}
                  <span>Passwords match</span>
                </div>
              </div>
            </div>

            <Button
              type="button"
              variant="primary"
              label="Continue to Profile Details"
              icon="pi pi-arrow-right"
              disabled={!isPasswordValid}
              onClick={() => setCurrentStep(2)}
              className="w-full h-12 rounded-xl! font-bold! shadow-lg shadow-primary/20"
            />
          </motion.div>
        )}

        {/* STEP 2: PROFILE & CONTACT INFORMATION */}
        {currentStep === 2 && (
          <motion.div
            key="step2"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="flex flex-col gap-6">
            <div className="space-y-1">
              <h3 className="text-base font-black text-foreground">Personal & Contact Profile</h3>
              <p className="text-xs text-muted">
                Complete your identity information and verified communication address.
              </p>
            </div>

            <FormField label="Full Name" required id="onboarding-name">
              <Input
                id="onboarding-name"
                placeholder="e.g. Marcus Vance"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                className="h-12 rounded-xl!"
              />
            </FormField>

            <FormField label="Contact / Phone Number" required id="onboarding-phone">
              <Input
                id="onboarding-phone"
                placeholder="+1 (555) 012-3456"
                value={contactNo}
                onChange={(e) => setContactNo(e.target.value)}
                className="h-12 rounded-xl!"
              />
            </FormField>

            <FormField label="Street Address" required id="onboarding-street">
              <Input
                id="onboarding-street"
                placeholder="100 Innovation Way, Suite 400"
                value={streetAddress}
                onChange={(e) => setStreetAddress(e.target.value)}
                className="h-12 rounded-xl!"
              />
            </FormField>

            <div className="grid grid-cols-2 gap-4">
              <FormField label="City" required id="onboarding-city">
                <Input
                  id="onboarding-city"
                  placeholder="San Francisco"
                  value={city}
                  onChange={(e) => setCity(e.target.value)}
                  className="h-12 rounded-xl!"
                />
              </FormField>

              <FormField label="State / Province" id="onboarding-state">
                <Input
                  id="onboarding-state"
                  placeholder="California"
                  value={stateRegion}
                  onChange={(e) => setStateRegion(e.target.value)}
                  className="h-12 rounded-xl!"
                />
              </FormField>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <FormField label="Postal / ZIP Code" id="onboarding-zip">
                <Input
                  id="onboarding-zip"
                  placeholder="94107"
                  value={postalCode}
                  onChange={(e) => setPostalCode(e.target.value)}
                  className="h-12 rounded-xl!"
                />
              </FormField>

              <FormField label="Country" required id="onboarding-country">
                <Input
                  id="onboarding-country"
                  placeholder="United States"
                  value={country}
                  onChange={(e) => setCountry(e.target.value)}
                  className="h-12 rounded-xl!"
                />
              </FormField>
            </div>

            <div className="flex items-center gap-3 pt-2">
              <Button
                type="button"
                variant="ghost"
                label="Back"
                icon="pi pi-arrow-left"
                onClick={() => setCurrentStep(1)}
                className="rounded-xl! h-12"
              />
              <Button
                type="button"
                variant="primary"
                label="Continue to Organization"
                icon="pi pi-arrow-right"
                disabled={!isStep2Valid}
                onClick={() => setCurrentStep(3)}
                className="flex-1 rounded-xl! h-12 font-bold! shadow-lg shadow-primary/20"
              />
            </div>
          </motion.div>
        )}

        {/* STEP 3: WORK & ORGANIZATIONAL DETAILS */}
        {currentStep === 3 && (
          <motion.div
            key="step3"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="flex flex-col gap-6">
            <div className="space-y-1">
              <h3 className="text-base font-black text-foreground">
                Organization & Role Placement
              </h3>
              <p className="text-xs text-muted">
                Review your assigned department, office hub, and operational title.
              </p>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <FormField label="Job Title / Designation" required id="onboarding-designation">
                <Input
                  id="onboarding-designation"
                  placeholder="e.g. Senior Software Engineer"
                  value={designation}
                  onChange={(e) => setDesignation(e.target.value)}
                  className="h-12 rounded-xl!"
                />
              </FormField>

              <FormField label="Department" required id="onboarding-dept">
                <Input
                  id="onboarding-dept"
                  value={department}
                  onChange={(e) => setDepartment(e.target.value)}
                  className="h-12 rounded-xl!"
                />
              </FormField>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <FormField label="Work Location / Office" required id="onboarding-location">
                <Input
                  id="onboarding-location"
                  value={workLocation}
                  onChange={(e) => setWorkLocation(e.target.value)}
                  placeholder="e.g. Remote / Headquarters"
                  className="h-12 rounded-xl!"
                />
              </FormField>

              <FormField label="Company Entity" required id="onboarding-company">
                <Input
                  id="onboarding-company"
                  value={company}
                  onChange={(e) => setCompany(e.target.value)}
                  className="h-12 rounded-xl!"
                />
              </FormField>
            </div>

            <div className="p-4 rounded-xl bg-surface-subtle border border-border-subtle flex flex-col gap-2 text-xs">
              <span className="font-bold text-foreground">Assigned Access Level:</span>
              <div className="flex items-center gap-2">
                <span className="px-2.5 py-1 rounded bg-primary/10 text-primary font-bold text-xs uppercase">
                  {role}
                </span>
                <span className="text-muted text-[11px]">
                  Configured by {invitationStatus.invitation?.invitedBy?.name || 'Administrator'}
                </span>
              </div>
            </div>

            <div className="flex items-center gap-3 pt-2">
              <Button
                type="button"
                variant="ghost"
                label="Back"
                icon="pi pi-arrow-left"
                onClick={() => setCurrentStep(2)}
                className="rounded-xl! h-12"
              />
              <Button
                type="button"
                variant="primary"
                label="Review & Activate"
                icon="pi pi-arrow-right"
                disabled={!isStep3Valid}
                onClick={() => setCurrentStep(4)}
                className="flex-1 rounded-xl! h-12 font-bold! shadow-lg shadow-primary/20"
              />
            </div>
          </motion.div>
        )}

        {/* STEP 4: REVIEW & POLICIES */}
        {currentStep === 4 && (
          <motion.div
            key="step4"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="flex flex-col gap-6">
            <div className="space-y-1">
              <h3 className="text-base font-black text-foreground">Review & Accept Terms</h3>
              <p className="text-xs text-muted">
                Confirm your details and accept security policies to activate your profile.
              </p>
            </div>

            {/* Profile Summary Card */}
            <div className="bg-surface-subtle/70 p-5 rounded-2xl border border-border-subtle space-y-3 text-xs">
              <div className="flex justify-between border-b border-border-subtle/60 pb-2">
                <span className="text-muted font-semibold">Full Name</span>
                <span className="font-bold text-foreground">{fullName}</span>
              </div>
              <div className="flex justify-between border-b border-border-subtle/60 pb-2">
                <span className="text-muted font-semibold">Work Email</span>
                <span className="font-bold text-foreground">{email}</span>
              </div>
              <div className="flex justify-between border-b border-border-subtle/60 pb-2">
                <span className="text-muted font-semibold">Contact Phone</span>
                <span className="font-bold text-foreground">{contactNo}</span>
              </div>
              <div className="flex justify-between border-b border-border-subtle/60 pb-2">
                <span className="text-muted font-semibold">Role & Dept</span>
                <span className="font-bold text-foreground">
                  {role} • {department}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted font-semibold">Address</span>
                <span className="font-medium text-foreground text-right truncate max-w-[200px]">
                  {streetAddress}, {city}, {country}
                </span>
              </div>
            </div>

            {/* Policies */}
            <div className="space-y-3">
              <label className="flex items-start gap-3 p-3 rounded-xl bg-surface-subtle border border-border-subtle cursor-pointer">
                <input
                  type="checkbox"
                  checked={acceptedTerms}
                  onChange={(e) => setAcceptedTerms(e.target.checked)}
                  className="mt-0.5 rounded text-primary focus:ring-primary h-4 w-4"
                />
                <span className="text-xs text-foreground/90">
                  I confirm that all personal and professional profile details provided are accurate
                  and current.
                </span>
              </label>

              <label className="flex items-start gap-3 p-3 rounded-xl bg-surface-subtle border border-border-subtle cursor-pointer">
                <input
                  type="checkbox"
                  checked={acceptedSecurityPolicy}
                  onChange={(e) => setAcceptedSecurityPolicy(e.target.checked)}
                  className="mt-0.5 rounded text-primary focus:ring-primary h-4 w-4"
                />
                <span className="text-xs text-foreground/90">
                  I agree to adhere to the organization's <strong>Acceptable Use Policy</strong>,
                  access controls, and <strong>Information Security Guidelines</strong>.
                </span>
              </label>
            </div>

            <div className="flex items-center gap-3 pt-2">
              <Button
                type="button"
                variant="ghost"
                label="Back"
                icon="pi pi-arrow-left"
                onClick={() => setCurrentStep(3)}
                className="rounded-xl! h-12"
              />
              <Button
                type="button"
                variant="primary"
                label={isSubmitting ? 'Finalizing...' : 'Complete Onboarding & Activate'}
                icon="pi pi-check"
                disabled={!isStep4Valid || isSubmitting}
                loading={isSubmitting}
                onClick={handleCompleteOnboarding}
                className="flex-1 rounded-xl! h-12 font-black! shadow-lg shadow-primary/20"
              />
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="mt-8 pt-6 border-t border-border-subtle text-center">
        <Link
          to="/auth/login"
          className="text-muted font-black text-xs uppercase tracking-widest hover:text-primary transition-colors">
          Already have an active account? Sign In
        </Link>
      </div>
    </AuthLayout>
  );
}

import { useState, useMemo, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { AuthLayout } from '@/components/layouts/AuthLayout';
import { FormField } from '@/components/ui/composed/FormField';
import { Input } from '@/components/ui/primitives/Input';
import { Button } from '@/components/ui/primitives/Button';
import { showToast } from '@/components/ui/composed/Toast.utils';
import {
  useChangeTemporaryPasswordMutation,
  useCompleteOnboardingMutation,
} from '@/store/api/authApiSlice';
import { useAuth } from '@/hooks/useAuth';
import { recordAuditLog, acceptInvitation } from '@/services/auditService';
import { ShieldCheck, Eye, EyeOff, Check, X, UserCircle, CheckCircle2, Lock } from 'lucide-react';

/** Determine the starting step from user's current onboarding_step */
function getInitialStep(
  user: { is_temporary_password?: boolean; is_onboarded?: boolean; onboarding_step?: number } | null
): 1 | 2 {
  if (!user) return 1;
  const step = user.onboarding_step ?? 1;
  if (user.is_temporary_password || step === 1) return 1;
  return 2;
}

export default function PostLoginOnboarding() {
  const navigate = useNavigate();
  const { user, updateUser, logout } = useAuth();

  const initialStep = getInitialStep(user);
  const [currentStep, setCurrentStep] = useState<1 | 2 | 3>(initialStep);

  // --- Step 1: Change Temp Password ---
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showCurrent, setShowCurrent] = useState(false);
  const [showNew, setShowNew] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);

  // --- Step 2: Complete Profile ---
  const [fullName, setFullName] = useState(user?.username || '');
  const [contactNo, setContactNo] = useState(user?.contact_number || '');
  const department = user?.department || 'Engineering';
  const designation = user?.designation || '';

  const [changeTemporaryPassword, { isLoading: isChangingPwd }] =
    useChangeTemporaryPasswordMutation();
  const [completeOnboarding, { isLoading: isCompletingOnboarding }] =
    useCompleteOnboardingMutation();

  // Password strength
  const passwordChecks = useMemo(
    () => ({
      minLength: newPassword.length >= 8,
      hasUpper: /[A-Z]/.test(newPassword),
      hasLower: /[a-z]/.test(newPassword),
      hasNumber: /[0-9]/.test(newPassword),
      hasSpecial: /[!@#$%^&*(),.?":{}|<>]/.test(newPassword),
      matches: newPassword.length > 0 && newPassword === confirmPassword,
    }),
    [newPassword, confirmPassword]
  );

  const strengthScore = useMemo(() => {
    return Object.values(passwordChecks).filter(Boolean).length - (passwordChecks.matches ? 0 : 0);
  }, [passwordChecks]);

  const isPasswordValid =
    passwordChecks.minLength &&
    passwordChecks.hasUpper &&
    passwordChecks.hasLower &&
    passwordChecks.hasNumber &&
    passwordChecks.hasSpecial &&
    passwordChecks.matches;

  const isProfileValid = fullName.trim().length >= 2 && contactNo.trim().length >= 7;

  const handleChangePassword = useCallback(async () => {
    if (!isPasswordValid) return;
    if (!currentPassword.trim()) {
      showToast({
        severity: 'error',
        summary: 'Missing Field',
        detail: 'Enter your temporary password.',
        life: 3000,
      });
      return;
    }
    try {
      const res = await changeTemporaryPassword({ currentPassword, newPassword }).unwrap();
      updateUser(
        {
          is_temporary_password: false,
          is_onboarded: res.user?.is_onboarded ?? false,
          onboarding_step: 2,
        },
        res.token
      );

      // ── Audit: Step 1 complete ──
      recordAuditLog({
        action: 'Temporary Password Changed',
        category: 'security',
        user: res.user?.username || user?.username || user?.email || 'Invited User',
        userEmail: res.user?.email || user?.email || '',
        target: `${res.user?.email || user?.email} (Account Security)`,
        targetEmail: res.user?.email || user?.email,
        status: 'Success',
        details: `Invited user successfully changed temporary password. Single-use credential invalidated. Onboarding step 1 of 2 complete.`,
      });

      showToast({
        severity: 'success',
        summary: 'Password Changed',
        detail: 'Temporary password invalidated. Now complete your profile.',
        life: 3000,
      });
      setCurrentStep(2);
    } catch (err: any) {
      // ── Audit: Failed attempt ──
      recordAuditLog({
        action: 'Temporary Password Change Failed',
        category: 'security',
        user: user?.username || user?.email || 'Invited User',
        userEmail: user?.email || '',
        target: `${user?.email} (Account Security)`,
        targetEmail: user?.email,
        status: 'Warning',
        details: `Failed attempt to change temporary password: ${err?.data?.message || 'Invalid current password provided.'}`,
      });
      showToast({
        severity: 'error',
        summary: 'Failed',
        detail: err?.data?.message || 'Could not change password. Please try again.',
        life: 4000,
      });
    }
  }, [isPasswordValid, currentPassword, newPassword, changeTemporaryPassword, updateUser, user]);

  const handleCompleteProfile = useCallback(async () => {
    if (!isProfileValid) return;
    try {
      const res = await completeOnboarding({
        username: fullName,
        contact_number: contactNo,
        department,
        designation,
      }).unwrap();
      updateUser(
        {
          username: fullName,
          contact_number: contactNo,
          department,
          designation,
          is_onboarded: true,
          onboarding_step: 3,
        },
        res.token
      );

      // ── Audit: Step 2 complete — full onboarding done ──
      const resolvedName = fullName || res.user?.username || user?.email || 'Invited User';
      const resolvedEmail = res.user?.email || user?.email || '';

      recordAuditLog({
        action: 'Onboarding Completed — Profile Activated',
        category: 'invitation',
        user: resolvedName,
        userEmail: resolvedEmail,
        target: `${resolvedName} (Account)`,
        targetEmail: resolvedEmail,
        status: 'Success',
        details: `User completed mandatory onboarding. Profile details submitted and account fully activated. Department: ${department}${designation ? `, Designation: ${designation}` : ''}.`,
        changes: [
          { field: 'Full Name', from: user?.username || '(not set)', to: fullName },
          { field: 'Contact Number', from: user?.contact_number || '(not set)', to: contactNo },
          { field: 'Department', from: user?.department || '(not set)', to: department },
          ...(designation
            ? [{ field: 'Designation', from: user?.designation || '(not set)', to: designation }]
            : []),
          { field: 'Onboarding Status', from: 'Incomplete', to: 'Fully Activated' },
        ],
      });

      // ── Also mark invitation accepted ──
      acceptInvitation('__post_login__', {
        name: resolvedName,
        email: resolvedEmail,
        role: res.user?.role || user?.role || 'Employee',
        department,
      });

      showToast({
        severity: 'success',
        summary: 'Onboarding Complete',
        detail: 'Welcome to AetherERP! Your account is fully activated.',
        life: 3500,
      });
      setCurrentStep(3);
    } catch (err: any) {
      showToast({
        severity: 'error',
        summary: 'Failed',
        detail: err?.data?.message || 'Could not save profile. Please try again.',
        life: 4000,
      });
    }
  }, [
    isProfileValid,
    fullName,
    contactNo,
    department,
    designation,
    completeOnboarding,
    updateUser,
    user,
  ]);

  const handleGoToDashboard = () => {
    navigate('/', { replace: true });
  };

  // ─── Success Screen ────────────────────────────────────────────
  if (currentStep === 3) {
    return (
      <AuthLayout title="You're all set!" subtitle="ACCOUNT ACTIVATION COMPLETE">
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="bg-white rounded-3xl p-8 border border-border-subtle shadow-soft flex flex-col items-center text-center gap-6">
          <div className="w-20 h-20 rounded-full bg-success/10 text-success flex items-center justify-center">
            <CheckCircle2 size={44} strokeWidth={1.5} />
          </div>
          <div className="space-y-2">
            <h3 className="text-2xl font-black text-foreground">
              Welcome, {fullName || user?.username}!
            </h3>
            <p className="text-xs text-muted leading-relaxed max-w-sm">
              Your password is secured and your profile is active. You now have full access to
              AetherERP.
            </p>
          </div>
          <div className="w-full p-4 rounded-xl bg-surface-subtle border border-border-subtle text-left text-xs space-y-2">
            <div className="flex justify-between">
              <span className="text-muted font-semibold">Name:</span>
              <span className="font-bold text-foreground">{fullName || user?.username}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted font-semibold">Email:</span>
              <span className="font-bold text-foreground">{user?.email}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted font-semibold">Department:</span>
              <span className="font-bold text-foreground">{department}</span>
            </div>
          </div>
          <div className="flex flex-col gap-3 w-full">
            <Button
              variant="primary"
              label="Complete Profile"
              icon="pi pi-check"
              onClick={() => {
                sessionStorage.setItem('newly_invited_user_onboarded', 'true');
                navigate('/profile-completion', { replace: true });
              }}
              className="w-full h-12 rounded-xl! font-bold! shadow-lg shadow-primary/20"
            />
            <Button
              variant="ghost"
              label="Go to Dashboard"
              icon="pi pi-arrow-right"
              onClick={() => {
                sessionStorage.setItem('newly_invited_user_onboarded', 'true');
                handleGoToDashboard();
              }}
              className="w-full h-10 rounded-xl! font-semibold! text-muted hover:text-foreground"
            />
          </div>
        </motion.div>
      </AuthLayout>
    );
  }

  // ─── Main Onboarding Flow ──────────────────────────────────────
  return (
    <AuthLayout
      title="Complete Account Setup"
      subtitle={`MANDATORY ONBOARDING — STEP ${currentStep} OF 2`}>
      {/* Progress */}
      <div className="mb-8">
        <div className="flex items-center justify-between text-[10px] font-extrabold uppercase tracking-wider text-muted mb-2">
          <span className={currentStep >= 1 ? 'text-primary font-black' : ''}>
            1. Secure Password
          </span>
          <span className={currentStep >= 2 ? 'text-primary font-black' : ''}>2. Your Profile</span>
        </div>
        <div className="h-1.5 w-full bg-surface-subtle rounded-full overflow-hidden flex gap-1">
          {[1, 2].map((s) => (
            <div
              key={s}
              className={`h-full flex-1 rounded-full transition-all duration-500 ${
                currentStep > s
                  ? 'bg-success'
                  : currentStep === s
                    ? 'bg-primary'
                    : 'bg-border-subtle/40'
              }`}
            />
          ))}
        </div>
      </div>

      {/* User badge */}
      <div className="mb-6 p-3 rounded-2xl bg-primary/5 border border-primary/10 flex items-center gap-3">
        <div className="w-9 h-9 rounded-full bg-primary/10 text-primary flex items-center justify-center font-bold text-sm">
          {(user?.username || user?.email || 'U').charAt(0).toUpperCase()}
        </div>
        <div>
          <div className="text-xs font-black text-foreground">{user?.email}</div>
          <div className="text-[10px] text-warning font-semibold uppercase tracking-wider">
            Onboarding Required
          </div>
        </div>
      </div>

      <AnimatePresence mode="wait">
        {/* ── STEP 1: Change Temporary Password ── */}
        {currentStep === 1 && (
          <motion.div
            key="step1"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="flex flex-col gap-5">
            <div className="space-y-1">
              <h3 className="text-base font-black text-foreground flex items-center gap-2">
                <Lock size={16} className="text-primary" />
                Change Your Temporary Password
              </h3>
              <p className="text-xs text-muted">
                Your account was created with a single-use temporary password. Set a strong
                permanent password to continue.
              </p>
            </div>

            {/* Current (Temp) Password */}
            <FormField label="Temporary Password" required id="onboarding-current-pwd">
              <div className="relative">
                <input
                  id="onboarding-current-pwd"
                  type={showCurrent ? 'text' : 'password'}
                  placeholder="Enter the temporary password from your email"
                  value={currentPassword}
                  onChange={(e) => setCurrentPassword(e.target.value)}
                  className="w-full pr-11 pl-4 py-3 rounded-xl bg-surface-subtle border border-border-subtle text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20"
                />
                <button
                  type="button"
                  onClick={() => setShowCurrent(!showCurrent)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted hover:text-foreground p-1 cursor-pointer">
                  {showCurrent ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </FormField>

            {/* New Password */}
            <FormField label="New Password" required id="onboarding-new-pwd">
              <div className="relative">
                <input
                  id="onboarding-new-pwd"
                  type={showNew ? 'text' : 'password'}
                  placeholder="Create a strong password"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  className="w-full pr-11 pl-4 py-3 rounded-xl bg-surface-subtle border border-border-subtle text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20"
                />
                <button
                  type="button"
                  onClick={() => setShowNew(!showNew)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted hover:text-foreground p-1 cursor-pointer">
                  {showNew ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </FormField>

            {/* Strength meter */}
            {newPassword.length > 0 && (
              <div className="flex flex-col gap-1.5 -mt-1">
                <div className="flex items-center justify-between text-xs">
                  <span className="text-[10px] font-extrabold uppercase text-muted tracking-wider">
                    Strength:
                  </span>
                  <span
                    className={`text-[10px] font-black uppercase px-2 py-0.5 rounded-full ${
                      strengthScore <= 2
                        ? 'bg-error/10 text-error'
                        : strengthScore <= 4
                          ? 'bg-warning/10 text-warning'
                          : 'bg-success/10 text-success'
                    }`}>
                    {strengthScore <= 2 ? 'Weak' : strengthScore <= 4 ? 'Moderate' : 'Strong'}
                  </span>
                </div>
                <div className="h-1.5 w-full bg-surface-subtle rounded-full overflow-hidden flex gap-1">
                  {[1, 2, 3, 4, 5].map((s) => (
                    <div
                      key={s}
                      className={`h-full flex-1 rounded-full transition-all duration-300 ${
                        s <= strengthScore
                          ? strengthScore <= 2
                            ? 'bg-error'
                            : strengthScore <= 4
                              ? 'bg-warning'
                              : 'bg-success'
                          : 'bg-border-subtle/50'
                      }`}
                    />
                  ))}
                </div>
              </div>
            )}

            {/* Confirm Password */}
            <FormField label="Confirm New Password" required id="onboarding-confirm-pwd">
              <div className="relative">
                <input
                  id="onboarding-confirm-pwd"
                  type={showConfirm ? 'text' : 'password'}
                  placeholder="Re-enter new password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="w-full pr-11 pl-4 py-3 rounded-xl bg-surface-subtle border border-border-subtle text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20"
                />
                <button
                  type="button"
                  onClick={() => setShowConfirm(!showConfirm)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted hover:text-foreground p-1 cursor-pointer">
                  {showConfirm ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </FormField>

            {/* Password checklist */}
            <div className="p-4 rounded-xl bg-surface-subtle/60 border border-border-subtle flex flex-col gap-2 text-xs">
              <span className="font-bold text-foreground text-[11px] uppercase tracking-wider flex items-center gap-1.5">
                <ShieldCheck size={14} className="text-primary" /> Requirements
              </span>
              <div className="grid grid-cols-2 gap-1.5 pt-1 text-[11px]">
                {[
                  { key: 'minLength', label: '8+ characters' },
                  { key: 'hasUpper', label: 'Uppercase (A-Z)' },
                  { key: 'hasLower', label: 'Lowercase (a-z)' },
                  { key: 'hasNumber', label: 'Number (0-9)' },
                  { key: 'hasSpecial', label: 'Special (!@#$)' },
                  { key: 'matches', label: 'Passwords match' },
                ].map(({ key, label }) => {
                  const ok = passwordChecks[key as keyof typeof passwordChecks];
                  return (
                    <div
                      key={key}
                      className={`flex items-center gap-1.5 ${ok ? 'text-success font-semibold' : 'text-muted'}`}>
                      {ok ? <Check size={12} /> : <X size={12} />}
                      <span>{label}</span>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="flex gap-3">
              <Button
                type="button"
                variant="ghost"
                label="Sign Out"
                onClick={logout}
                className="rounded-xl! h-12"
              />
              <Button
                type="button"
                variant="primary"
                label={isChangingPwd ? 'Saving...' : 'Set Password & Continue'}
                icon="pi pi-arrow-right"
                disabled={!isPasswordValid || !currentPassword.trim() || isChangingPwd}
                loading={isChangingPwd}
                onClick={handleChangePassword}
                className="flex-1 h-12 rounded-xl! font-bold! shadow-lg shadow-primary/20"
              />
            </div>
          </motion.div>
        )}

        {/* ── STEP 2: Complete Profile ── */}
        {currentStep === 2 && (
          <motion.div
            key="step2"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="flex flex-col gap-5">
            <div className="space-y-1">
              <h3 className="text-base font-black text-foreground flex items-center gap-2">
                <UserCircle size={16} className="text-primary" />
                Complete Your Profile
              </h3>
              <p className="text-xs text-muted">
                Fill in your details to activate your account. You can update these later in your
                profile settings.
              </p>
            </div>

            <FormField label="Full Name" required id="onboarding-fullname">
              <Input
                id="onboarding-fullname"
                placeholder="e.g. John Smith"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                className="h-12 rounded-xl!"
              />
            </FormField>

            <FormField label="Contact / Phone Number" required id="onboarding-contact">
              <Input
                id="onboarding-contact"
                placeholder="+1 (555) 012-3456"
                value={contactNo}
                onChange={(e) => setContactNo(e.target.value)}
                className="h-12 rounded-xl!"
              />
            </FormField>

            <div className="flex items-center gap-3 pt-2">
              <Button
                type="button"
                variant="ghost"
                label="Sign Out"
                onClick={logout}
                className="rounded-xl! h-12"
              />
              <Button
                type="button"
                variant="primary"
                label={isCompletingOnboarding ? 'Saving...' : 'Complete Setup'}
                loading={isCompletingOnboarding}
                disabled={!isProfileValid || isCompletingOnboarding}
                onClick={handleCompleteProfile}
                className="flex-1 h-12 rounded-xl! font-bold! shadow-lg shadow-primary/20"
              />
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </AuthLayout>
  );
}

