              placeholder="Select Category"
              className="h-12! rounded-2xl! border-border-subtle! bg-surface-subtle/40!"
            />
          </FormField>

          <FormField
            label="Story Tags"
            description="Type tag name and press Enter or comma"
            className="text-[10px]! font-black! uppercase! tracking-[0.15em]! text-muted!">
            <div className="flex flex-col gap-3">
              <div className="relative">
                <Tag size={14} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-muted" />
                <input
                  type="text"
                  value={tagInput}
                  onChange={(e) => setTagInput(e.target.value)}
                  onKeyDown={handleAddTag}
                  placeholder="E.g. AI, ERP, Leadership..."
                  className="w-full pl-9 pr-4 py-3 rounded-2xl border border-border-subtle bg-surface-subtle/40 focus:bg-white focus:ring-2 focus:ring-primary/20 outline-none text-xs font-bold text-foreground placeholder:text-muted/60"
                />
              </div>

              {formData.tags && formData.tags.length > 0 && (
                <div className="flex flex-wrap gap-1.5 pt-1">
                  {formData.tags.map((tag) => (
                    <span
                      key={tag}
                      className="inline-flex items-center gap-1 px-3 py-1 rounded-xl bg-primary/10 text-primary text-[10px] font-black uppercase tracking-wider">
                      #{tag}
                      <button
                        type="button"
                        onClick={() => handleRemoveTag(tag)}
                        className="hover:text-red-500 ml-0.5"
                        title="Remove tag">
                        <X size={12} />
                      </button>
                    </span>
                  ))}
                </div>
              )}
            </div>
          </FormField>

          <div className="p-4 rounded-2xl bg-surface-subtle/50 border border-border-subtle/50 flex items-center gap-3">
            <CheckCircle2 size={16} className="text-emerald-500 shrink-0" />
            <span className="text-[11px] font-medium text-muted">
              Auto-saved locally â€¢ Backups preserved on draft edit
            </span>
          </div>
        </div>
      </motion.div>
    </form>
  );
};

import { useNavigate } from 'react-router-dom';
import { showToast } from '@/components/ui/composed/Toast.utils';
import { showConfirm } from '@/components/ui/composed/ConfirmDialog.utils';
import {
  useGetBlogsQuery,
  useGetBlogQuery,
  useCreateBlogMutation,
  useUpdateBlogMutation,
  useDeleteBlogMutation,
} from '@/store/api/blogSlice';
import type { Blog } from '@/types/models';

export const useBlogs = (id?: string) => {
  const navigate = useNavigate();

  // Queries
  const { data: blogs = [], isLoading: isFetchingList, isError: isListError } = useGetBlogsQuery();
  const {
    data: fetchedBlog,
    isLoading: isFetchingSingle,
    isError: isSingleError,
  } = useGetBlogQuery(id as string, { skip: !id });

  // Fallback to list cache if single query isn't populated
  const blog =
    fetchedBlog ||
    (id ? blogs.find((b) => String(b.id) === String(id)) : undefined);

  // Mutations
  const [createBlog, { isLoading: isCreating }] = useCreateBlogMutation();
  const [updateBlog, { isLoading: isUpdating }] = useUpdateBlogMutation();
  const [deleteBlog] = useDeleteBlogMutation();

  const handleSave = async (data: Partial<Blog>) => {
    try {
      if (id) {
        await updateBlog({ ...data, id }).unwrap();
      } else {
        await createBlog(data).unwrap();
      }
      showToast({
        severity: 'success',
        summary: 'Success',
        detail: `Post ${id ? 'updated' : 'created'} successfully!`,
        life: 3000,
      });
      setTimeout(() => {
        navigate('/social/blogs');
      }, 300);
    } catch (error: unknown) {
      const apiError = error as { data?: { message?: string } };
      console.error('Failed to save blog:', error);
      showToast({
        severity: 'error',
        summary: 'Error',
        detail: apiError.data?.message || 'Failed to save post',
        life: 3000,
      });
    }
  };

  const handleDelete = async (blogId: string) => {
    showConfirm({
      message: 'Are you sure you want to delete this story?',
      header: 'Confirm Deletion',
      accept: async () => {
        try {
          await deleteBlog(blogId).unwrap();
          showToast({
            severity: 'success',
            summary: 'Success',
            detail: 'Post deleted successfully!',
            life: 3000,
          });
        } catch (error: unknown) {
          const apiError = error as { data?: { message?: string } };
          console.error('Failed to delete blog:', error);
          showToast({
            severity: 'error',
            summary: 'Error',
            detail: apiError.data?.message || 'Failed to delete post',
            life: 3000,
          });
        }
      },
    });
  };

  return {
    blogs,
    blog,
    isLoading:
      isFetchingList || (Boolean(id) && isFetchingSingle && !blog) || isCreating || isUpdating,
    isError: Boolean(id) ? isSingleError && !blog : isListError,
    handleSave,
    handleDelete,
    navigate,
  };
};

