  const onBreakMembers = useMemo(() => {
    return (data?.active_breaks && data.active_breaks.length > 0)
      ? data.active_breaks
      : members.filter((m) => m.availability_status === 'ON_BREAK');
  }, [data?.active_breaks, members]);

