  selectedOfficeId: number | null;
  setSelectedOfficeId: (id: number | null) => void;
  activeOffice: Office | null;
  distanceToOffice: number | null;
  isInsideGeofence: boolean | null;
  isVerifyingGeofence: boolean;
}

const MOODS = [
  { value: 1, icon: Frown, label: 'Awful' },
  { value: 2, icon: Frown, label: 'Bad' },
  { value: 3, icon: Meh, label: 'Okay' },
  { value: 4, icon: Smile, label: 'Good' },
  { value: 5, icon: Smile, label: 'Great' },
];

export const TodayAttendanceSummary: React.FC<TodayAttendanceSummaryProps> = ({
  time,
  status,
  selectedMood,
  isLoading,
  isSubmittingMood,
  isBreakLoading,
  handleAttendance,
  handleBreak,
  logMood,
  liveWorkingTime,
  checkInTimeDisplay,
  checkOutTimeDisplay,
  totalBreakDisplay,
  netWorkingDisplay,
  isLate,
  lateDurationDisplay,
  earlyDurationDisplay,
  punctualityStatus,
  shiftTimingDisplay,
  workMode,
  setWorkMode,
  geoLocation,
  requestGeoLocation,
  breakNote,
  setBreakNote,
  offices,
  selectedOfficeId,
  setSelectedOfficeId,
  activeOffice,
  distanceToOffice,
  isInsideGeofence,
  isVerifyingGeofence,
}) => {
  const [showBreakTray, setShowBreakTray] = useState(false);
  const [showPinpointMap, setShowPinpointMap] = useState(false);

  const isCheckedIn = status?.status === 'checked-in';
  const isOnBreak = !!status?.onBreak;
  const isWfhCheckedIn = Boolean(status?.is_wfh || status?.work_mode === 'wfh');

  // Compute live seconds elapsed since check-in for real-time second-by-second ticking
  const checkInDate = useMemo(() => {
    const raw = status?.lastAction || (status?.record as any)?.check_in_time;
    if (!raw) return null;
    const d = new Date(raw);
    return isNaN(d.getTime()) ? null : d;
  }, [status?.lastAction, status?.record]);

  const elapsedSeconds = useMemo(() => {
    if (!isCheckedIn || !checkInDate) return 0;
    return Math.max(0, Math.floor((time.getTime() - checkInDate.getTime()) / 1000));
  }, [isCheckedIn, checkInDate, time]);

  // Compute active break seconds if currently on break
  const activeBreakSeconds = useMemo(() => {
    const raw = status?.activeBreak?.break_start;
    if (!isOnBreak || !raw) return 0;
    const d = new Date(raw);
    if (isNaN(d.getTime())) return 0;
    return Math.max(0, Math.floor((time.getTime() - d.getTime()) / 1000));
  }, [isOnBreak, status?.activeBreak?.break_start, time]);

  // Format seconds into HH:MM:SS
  const formatSecondsToHMS = (totalSec: number) => {
    const h = Math.floor(totalSec / 3600);
    const m = Math.floor((totalSec % 3600) / 60);
    const s = totalSec % 60;
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  };

  // Target standard shift: 8h 30m = 510 minutes = 30,600 seconds
  const TARGET_SHIFT_SECONDS = 510 * 60;
  const progressPercent = useMemo(() => {
    if (!isCheckedIn) return 0;
    const totalBreakSec = (status?.total_break_minutes ?? 0) * 60 + activeBreakSeconds;
    const netSec = Math.max(0, elapsedSeconds - totalBreakSec);
    return Math.min(100, Math.round((netSec / TARGET_SHIFT_SECONDS) * 100));
  }, [isCheckedIn, elapsedSeconds, activeBreakSeconds, status?.total_break_minutes]);

  // SVG Progress Ring calculations (radius 82, perimeter ~515)
  const RING_RADIUS = 82;
  const RING_CIRCUMFERENCE = 2 * Math.PI * RING_RADIUS;
  const strokeDashoffset = RING_CIRCUMFERENCE - (progressPercent / 100) * RING_CIRCUMFERENCE;

  // Active status badge helper
  const renderStatusBadge = () => {
    if (isOnBreak) {
      return (
        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-amber-500/15 border border-amber-500/30 text-amber-600 dark:text-amber-400 font-black text-[11px] uppercase tracking-wider animate-pulse">
          <span className="w-2 h-2 rounded-full bg-amber-500" />
          On Break
        </span>
      );
    }
    if (isCheckedIn) {
      if (isWfhCheckedIn) {
        return (
          <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-indigo-500/15 border border-indigo-500/30 text-indigo-600 dark:text-indigo-400 font-black text-[11px] uppercase tracking-wider">
            <span className="w-2 h-2 rounded-full bg-indigo-500 animate-ping" />
            Active · Remote
          </span>
        );
      }
      return (
        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-emerald-500/15 border border-emerald-500/30 text-emerald-600 dark:text-emerald-400 font-black text-[11px] uppercase tracking-wider">
          <span className="w-2 h-2 rounded-full bg-emerald-500 animate-ping" />
          Active · Office
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-surface-subtle border border-border-subtle text-muted font-bold text-[11px] uppercase tracking-wider">
        <span className="w-2 h-2 rounded-full bg-muted/60" />
        Not Punched
      </span>
    );
  };

  return (
    <div className="bg-surface-elevated/90 backdrop-blur-md rounded-3xl border border-border-subtle shadow-sm p-5 sm:p-7 space-y-6 relative overflow-hidden transition-all">
      {/* Ambient background glow according to status */}
      <div
        className={`absolute -top-24 -right-24 w-80 h-80 rounded-full blur-3xl pointer-events-none opacity-20 transition-all duration-700 ${
          isOnBreak
            ? 'bg-amber-500'
            : isCheckedIn
            ? isWfhCheckedIn
              ? 'bg-indigo-500'
              : 'bg-emerald-500'
            : 'bg-primary'
        }`}
      />

      {/* Top Header: Date, Shift timing, and Live Presence Status */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 pb-4 border-b border-border-subtle/70">
        <div>
          <div className="flex items-center gap-2.5 flex-wrap">
            <h2 className="text-lg font-black text-foreground tracking-tight">
              {formatFullDate(time)}
            </h2>
            {renderStatusBadge()}
          </div>
          <p className="text-xs font-semibold text-muted mt-0.5 flex items-center gap-2">
            <span>Shift Window: <strong className="text-foreground">{shiftTimingDisplay}</strong></span>
            {isCheckedIn && status?.check_in_location && (
              <>
                <span>&bull;</span>
                <span className="inline-flex items-center gap-1 text-primary">
                  <MapPin size={12} />
                  {status.check_in_location}
                </span>
              </>
            )}
          </p>
        </div>

        {/* GPS Status & Refresh */}
        <div className="flex flex-col items-end gap-1.5 self-start sm:self-auto">
          {geoLocation.latitude && geoLocation.longitude ? (
            <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl bg-surface-subtle border border-border-subtle text-[11px] font-bold text-foreground/80">
              <Navigation size={12} className="text-primary" />
              <span>
                GPS: {geoLocation.latitude.toFixed(4)}°, {geoLocation.longitude.toFixed(4)}°
                {geoLocation.accuracy !== null && (
                  <span className={`ml-1 font-extrabold ${
                    geoLocation.accuracy <= 20
                      ? 'text-emerald-500'
                      : geoLocation.accuracy <= 50
                      ? 'text-primary'
                      : 'text-amber-500'
                  }`}>
                    ±{Math.round(geoLocation.accuracy)}m
                    {geoLocation.accuracy <= 20 ? ' (High Precision)' : ''}
                  </span>
                )}
              </span>
              <button
                type="button"
                onClick={requestGeoLocation}
                disabled={geoLocation.isFetching}
                title="Refresh GPS"
                className="text-muted hover:text-primary transition-colors p-0.5 cursor-pointer">
                <RefreshCw size={11} className={geoLocation.isFetching ? 'animate-spin text-primary' : ''} />
              </button>
            </div>
          ) : geoLocation.error ? (
            <div className="inline-flex items-center gap-1 px-2.5 py-1 rounded-xl bg-amber-500/10 text-amber-600 dark:text-amber-400 text-[11px] font-bold">
              <AlertTriangle size={12} />
              <span>GPS: {geoLocation.error}</span>
              <button
                type="button"
                onClick={requestGeoLocation}
                className="ml-1 text-primary underline cursor-pointer text-[10px]">
                Retry
              </button>
            </div>
          ) : (
            <button
              type="button"
              onClick={requestGeoLocation}
              disabled={geoLocation.isFetching}
              className="inline-flex items-center gap-1 px-2.5 py-1 rounded-xl bg-surface-subtle border border-border-subtle text-muted text-[11px] font-bold hover:text-foreground transition-colors cursor-pointer">
              <Navigation size={12} className={geoLocation.isFetching ? 'animate-spin text-primary' : ''} />
              <span>{geoLocation.isFetching ? 'Locking High-Accuracy GPS...' : 'Acquire High-Accuracy GPS'}</span>
            </button>
          )}
          {/* Geofence status badge */}
          {workMode === 'office' && !isCheckedIn && (
            isInsideGeofence === true ? (
              <div className="inline-flex items-center gap-1 px-2.5 py-1 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-600 dark:text-emerald-400 text-[11px] font-bold">
                <CheckCircle2 size={12} />
                <span>Inside geofence · {distanceToOffice !== null ? `${Math.round(distanceToOffice)}m` : ''} from {activeOffice?.name || 'office'}</span>
              </div>
            ) : isInsideGeofence === false ? (
              <div className="inline-flex items-center gap-1 px-2.5 py-1 rounded-xl bg-red-500/10 border border-red-500/30 text-red-600 dark:text-red-400 text-[11px] font-bold">
                <AlertTriangle size={12} />
                <span>Outside zone · {distanceToOffice !== null ? `${Math.round(distanceToOffice)}m` : '?'} from {activeOffice?.name || 'office'} (radius: {activeOffice?.radius ?? '?'}m)</span>
              </div>
            ) : (
              <div className="inline-flex items-center gap-1 px-2.5 py-1 rounded-xl bg-amber-500/10 border border-amber-500/30 text-amber-600 dark:text-amber-400 text-[11px] font-bold">
                <MapPin size={12} />
                <span>Enable GPS to verify office location</span>
              </div>
            )
          )}
        </div>
      </div>

      {/* Live Pinpoint Location Strip & Map Drawer */}
      {(geoLocation.latitude !== null && geoLocation.longitude !== null) && (
        <div className="bg-surface-subtle/70 rounded-2xl border border-border-subtle p-3.5 space-y-3">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2">
            <div className="flex items-center gap-2 min-w-0">
              <div className="w-8 h-8 rounded-xl bg-primary/10 flex items-center justify-center text-primary shrink-0">
                <Compass size={16} />
              </div>
              <div className="min-w-0">
                <span className="text-[10px] font-black uppercase text-muted tracking-wider block">
                  Current Pinpoint Location
                </span>
                <span className="text-xs font-bold text-foreground truncate block">
                  {geoLocation.locationName || `${geoLocation.latitude.toFixed(4)}°, ${geoLocation.longitude.toFixed(4)}°`}
                </span>
              </div>
            </div>

            <div className="flex items-center gap-2 self-end sm:self-auto shrink-0">
              {distanceToOffice !== null && activeOffice && (
                <span className="text-[11px] font-bold text-muted bg-surface-elevated px-2.5 py-1 rounded-xl border border-border-subtle">
                  <strong>{Math.round(distanceToOffice)}m</strong> to {activeOffice.name}
                </span>
              )}

              <button
                type="button"
                onClick={() => setShowPinpointMap(!showPinpointMap)}
                className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl bg-primary/10 hover:bg-primary/20 text-primary text-xs font-black transition-colors cursor-pointer">
                <MapPin size={12} />
                <span>{showPinpointMap ? 'Hide Map' : 'View Pinpoint Map'}</span>
              </button>
            </div>
          </div>

          {/* Expandable Interactive Map Pinpoint */}
          {showPinpointMap && (
            <div className="space-y-1.5 pt-1 animate-in fade-in duration-200">
              <LocationPinpointMap
                latitude={geoLocation.latitude}
                longitude={geoLocation.longitude}
                accuracy={geoLocation.accuracy}
                radius={workMode === 'office' ? activeOffice?.radius : undefined}
                locationName={geoLocation.locationName || 'Your Current Position'}
                height="190px"
              />
              {/* <p className="text-[10px] text-muted text-right">
                Real-time device GPS coordinates mapped with high-accuracy satellite geocoding
              </p> */}
            </div>
          )}
        </div>
      )}

      {/* Main Dynamic Centerpiece Hero: Progress Orb + Action Hub */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-center py-2">
        {/* Left: Dynamic SVG Progress Orb (5 cols) */}
        <div className="lg:col-span-5 flex flex-col items-center justify-center">
          <div className="relative w-48 h-48 flex items-center justify-center">
            {/* SVG Progress Ring */}
            <svg className="w-full h-full -rotate-90 transform" viewBox="0 0 190 190">
              {/* Background Track */}
              <circle
                cx="95"
                cy="95"
                r={RING_RADIUS}
                className="stroke-surface-subtle dark:stroke-border-subtle"
                strokeWidth="10"
                fill="transparent"
              />
              {/* Dynamic Animated Progress Stroke */}
              <circle
                cx="95"
                cy="95"
                r={RING_RADIUS}
                className={`transition-all duration-1000 ease-out ${
                  isOnBreak
                    ? 'stroke-amber-500'
                    : isCheckedIn
                    ? isWfhCheckedIn
                      ? 'stroke-indigo-500'
                      : 'stroke-emerald-500'
                    : 'stroke-primary/40'
                }`}
                strokeWidth="10"
                strokeDasharray={RING_CIRCUMFERENCE}
                strokeDashoffset={isCheckedIn ? strokeDashoffset : RING_CIRCUMFERENCE}
                strokeLinecap="round"
                fill="transparent"
              />
            </svg>

            {/* Inner Content of Ring */}
            <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-4">
              {isOnBreak ? (
                <>
                  <span className="inline-flex items-center gap-1 text-[10px] font-black uppercase tracking-wider text-amber-500 mb-0.5">
                    <Coffee size={12} className="animate-pulse" />
                    On Break
                  </span>
                  <span className="font-mono text-2xl font-black text-foreground tracking-tight">
                    {formatSecondsToHMS(activeBreakSeconds)}
                  </span>
                  <span className="text-[10px] font-bold text-muted mt-0.5">
                    {status?.activeBreak?.break_type || 'Break Session'}
                  </span>
                </>
              ) : isCheckedIn ? (
                <>
                  <span className="inline-flex items-center gap-1 text-[10px] font-black uppercase tracking-wider text-emerald-500 mb-0.5">
                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-ping" />
                    Live Working
                  </span>
                  <span className="font-mono text-2xl font-black text-foreground tracking-tight">
                    {formatSecondsToHMS(elapsedSeconds)}
                  </span>
                  <span className="text-[10px] font-bold text-muted mt-0.5">
                    {progressPercent}% of 8.5h shift
                  </span>
                </>
              ) : (
                <>
                  <span className="text-[10px] font-black uppercase tracking-widest text-primary/80 mb-0.5">
                    Current Time
                  </span>
                  <span className="font-mono text-2xl font-black text-foreground tracking-tight">
                    {formatTime(time)}
                  </span>
                  <span className="text-[10px] font-bold text-muted mt-0.5">
                    Ready to punch in
                  </span>
                </>
              )}
            </div>
          </div>
        </div>

        {/* Right: Primary Action Console & Controls (7 cols) */}
        <div className="lg:col-span-7 flex flex-col justify-center space-y-4">
          <div>
            <span className="text-[10px] font-black uppercase tracking-widest text-primary block mb-1">
              Attendance Action
            </span>
            <h3 className="text-xl sm:text-2xl font-black text-foreground tracking-tight">
              {isOnBreak
                ? 'Break In Progress'
                : isCheckedIn
                ? 'Your Shift is Active'
                : 'Ready to Start Your Workday?'}
            </h3>
            <p className="text-xs text-muted font-medium mt-0.5">
              {isOnBreak
                ? `Taking ${status?.activeBreak?.break_type || 'break'}${status?.activeBreak?.break_note ? `: "${status.activeBreak.break_note}"` : ''}. Resume whenever you're back.`
                : isCheckedIn
                ? `Punched in at ${checkInTimeDisplay}. Track breaks or punch out at shift end.`
                : 'Select your work location mode and punch in to start recording your shift.'}
            </p>
          </div>

          {/* Location Mode Segmented Pill (only visible/interactable before punch-in) */}
          {!isCheckedIn && (
            <div className="inline-flex p-1 bg-surface-subtle rounded-2xl border border-border-subtle self-start gap-1">
              <button
                type="button"
                onClick={() => setWorkMode('office')}
                className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl text-xs font-black transition-all cursor-pointer ${
                  workMode === 'office'
                    ? 'bg-surface-elevated text-foreground shadow-xs border border-border-subtle'
                    : 'text-muted hover:text-foreground'
                }`}>
                <Building size={14} className={workMode === 'office' ? 'text-primary' : 'text-muted'} />
                <span>In-Office</span>
              </button>
              <button
                type="button"
                onClick={() => setWorkMode('wfh')}
                className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl text-xs font-black transition-all cursor-pointer ${
                  workMode === 'wfh'
                    ? 'bg-surface-elevated text-foreground shadow-xs border border-border-subtle'
                    : 'text-muted hover:text-foreground'
                }`}>
                <Home size={14} className={workMode === 'wfh' ? 'text-indigo-500' : 'text-muted'} />
                <span>Remote / WFH</span>
              </button>
            </div>
          )}

          {/* Office selector — shown when mode=office, not yet checked in, offices available */}
          {!isCheckedIn && workMode === 'office' && offices.length > 1 && (
            <div className="flex items-center gap-2 self-start">
              <MapPin size={13} className="text-primary shrink-0" />
              <select
                value={selectedOfficeId ?? ''}
                onChange={(e) => setSelectedOfficeId(e.target.value ? Number(e.target.value) : null)}
                className="bg-surface-subtle border border-border-subtle rounded-xl px-3 py-1.5 text-xs font-bold text-foreground focus:outline-none focus:border-primary/50 cursor-pointer transition-colors">
                <option value="">Auto-detect nearest office</option>
                {offices.map((o) => (
                  <option key={o.id} value={o.id}>{o.name}{o.address ? ` – ${o.address}` : ''}</option>
                ))}
              </select>
            </div>
          )}

          {/* Active office info strip when one office */}
          {!isCheckedIn && workMode === 'office' && offices.length === 1 && (
            <div className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-surface-subtle border border-border-subtle text-[11px] font-bold text-foreground/80 self-start">
              <Building size={12} className="text-primary" />
              <span>{offices[0].name}</span>
              <span className="text-muted">· radius {offices[0].radius}m</span>
            </div>
          )}

          {/* Action Buttons Row */}
          <div className="flex flex-wrap items-center gap-3 pt-1">
            {!isCheckedIn ? (
              <>
                {/* Geofence warning when outside */}
                {workMode === 'office' && isInsideGeofence === false && !isVerifyingGeofence && (
                  <p className="w-full text-[11px] font-bold text-red-500 flex items-center gap-1">
                    <AlertTriangle size={12} /> You are outside the permitted office zone. Move closer to check in.
                  </p>
                )}
                <button
                  type="button"
                  onClick={handleAttendance}
                  disabled={isLoading || isVerifyingGeofence || (workMode === 'office' && isInsideGeofence === false)}
                  title={workMode === 'office' && isInsideGeofence === false ? 'You are outside the office geofence' : undefined}
                  className={`w-full sm:w-auto min-w-[210px] h-13 px-8 rounded-2xl font-black text-xs sm:text-sm tracking-wider uppercase shadow-lg hover:-translate-y-0.5 active:translate-y-0 active:scale-98 transition-all flex items-center justify-center gap-2.5 ${
                    workMode === 'office' && isInsideGeofence === false
                      ? 'bg-red-500/20 border border-red-500/40 text-red-500 cursor-not-allowed shadow-none'
                      : 'bg-primary hover:bg-primary-hover text-white shadow-primary/25 hover:shadow-xl hover:shadow-primary/35 cursor-pointer'
                  }`}>
                  {isVerifyingGeofence ? (
                    <RefreshCw size={18} className="animate-spin" />
                  ) : isLoading ? (
                    <RefreshCw size={18} className="animate-spin" />
                  ) : workMode === 'office' && isInsideGeofence === false ? (
                    <AlertTriangle size={18} />
                  ) : (
                    <LogIn size={18} />
                  )}
                  <span>
                    {isVerifyingGeofence
                      ? 'Verifying location...'
                      : workMode === 'wfh'
                      ? 'Punch In (Remote)'
                      : workMode === 'office' && isInsideGeofence === false
                      ? 'Outside Office Zone'
                      : 'Punch In (Office)'}
                  </span>
                </button>
              </>
            ) : isOnBreak ? (
              /* RESUME FROM BREAK BUTTON */
              <button
                type="button"
                onClick={() => handleBreak()}
                disabled={isBreakLoading}
                className="w-full sm:w-auto min-w-[210px] h-13 px-8 rounded-2xl bg-amber-500 hover:bg-amber-600 text-white font-black text-xs sm:text-sm tracking-wider uppercase shadow-lg shadow-amber-500/30 hover:shadow-xl hover:shadow-amber-500/40 hover:-translate-y-0.5 active:translate-y-0 active:scale-98 transition-all cursor-pointer flex items-center justify-center gap-2.5 animate-pulse">
                {isBreakLoading ? (
                  <RefreshCw size={18} className="animate-spin" />
                ) : (
                  <Coffee size={18} />
                )}
                <span>Resume Work (End Break)</span>
              </button>
            ) : (
              /* ACTIVE SHIFT: CHECK OUT + BREAK BUTTONS */
              <>
                <button
                  type="button"
                  onClick={handleAttendance}
                  disabled={isLoading || isOnBreak}
                  className="h-12 px-6 rounded-2xl bg-surface-subtle hover:bg-surface-elevated border border-border-strong text-foreground font-black text-xs tracking-wider uppercase hover:border-primary/40 hover:text-primary active:scale-95 transition-all cursor-pointer flex items-center justify-center gap-2 shadow-xs">
                  {isLoading ? (
                    <RefreshCw size={16} className="animate-spin" />
                  ) : (
                    <LogOut size={16} />
                  )}
                  <span>Check Out</span>
                </button>

                <button
                  type="button"
                  onClick={() => setShowBreakTray(!showBreakTray)}
                  disabled={isBreakLoading}
                  className="h-12 px-6 rounded-2xl bg-amber-500/10 hover:bg-amber-500/15 border border-amber-500/30 text-amber-600 dark:text-amber-400 font-black text-xs tracking-wider uppercase active:scale-95 transition-all cursor-pointer flex items-center justify-center gap-2 shadow-xs">
                  <Coffee size={16} />
                  <span>Take Break</span>
                  {showBreakTray ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
                </button>
              </>
            )}
          </div>

          {/* Contextual Expandable Break Drawer when taking a break */}
          {isCheckedIn && !isOnBreak && showBreakTray && (
            <div className="p-3.5 rounded-2xl bg-surface-subtle border border-border-subtle space-y-3 animate-in fade-in duration-200">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-black uppercase tracking-wider text-muted flex items-center gap-1.5">
                  <Coffee size={12} className="text-amber-500" />
                  Select Break Type
                </span>
                <span className="text-[10px] font-bold text-muted">1-Tap Start</span>
              </div>

              {/* 1-Tap Break Presets */}
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                <button
                  type="button"
                  disabled={isBreakLoading}
                  onClick={() => {
                    handleBreak('Tea Break', breakNote || 'Tea Break');
                    setShowBreakTray(false);
                  }}
                  className="flex items-center justify-center gap-1.5 py-2 px-3 rounded-xl bg-surface-elevated hover:bg-amber-500/15 border border-border-subtle hover:border-amber-500/40 text-xs font-bold text-foreground transition-all cursor-pointer shadow-xs active:scale-95">
                  <Coffee size={13} className="text-amber-500" />
                  <span>Tea Break</span>
                  <span className="text-[10px] text-muted">(15m)</span>
                </button>

                <button
                  type="button"
                  disabled={isBreakLoading}
                  onClick={() => {
                    handleBreak('Lunch Break', breakNote || 'Lunch Break');
                    setShowBreakTray(false);
                  }}
                  className="flex items-center justify-center gap-1.5 py-2 px-3 rounded-xl bg-surface-elevated hover:bg-amber-500/15 border border-border-subtle hover:border-amber-500/40 text-xs font-bold text-foreground transition-all cursor-pointer shadow-xs active:scale-95">
                  <Coffee size={13} className="text-amber-500" />
                  <span>Lunch Break</span>
                  <span className="text-[10px] text-muted">(45m)</span>
                </button>

                <button
                  type="button"
                  disabled={isBreakLoading}
                  onClick={() => {
                    handleBreak('Short Break', breakNote || 'Short Break');
                    setShowBreakTray(false);
                  }}
                  className="col-span-2 sm:col-span-1 flex items-center justify-center gap-1.5 py-2 px-3 rounded-xl bg-surface-elevated hover:bg-amber-500/15 border border-border-subtle hover:border-amber-500/40 text-xs font-bold text-foreground transition-all cursor-pointer shadow-xs active:scale-95">
                  <Zap size={13} className="text-amber-500" />
                  <span>Short Break</span>
                  <span className="text-[10px] text-muted">(10m)</span>
                </button>
              </div>

              {/* Custom Note Input */}
              <div className="flex items-center gap-2 pt-1">
                <input
                  type="text"
                  value={breakNote}
                  onChange={(e) => setBreakNote(e.target.value)}
                  placeholder="Optional break note (e.g. coffee with client)..."
                  maxLength={80}
                  className="flex-1 bg-surface-elevated border border-border-subtle rounded-xl px-3 py-1.5 text-xs text-foreground placeholder:text-muted focus:outline-none focus:border-primary/50 transition-colors"
                />
                <button
                  type="button"
                  disabled={isBreakLoading}
                  onClick={() => {
                    handleBreak(breakNote || 'Break');
                    setShowBreakTray(false);
                  }}
                  className="px-4 py-1.5 rounded-xl bg-amber-500 text-white text-xs font-black uppercase tracking-wider hover:bg-amber-600 active:scale-95 transition-all cursor-pointer">
                  Start
                </button>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Unified Consolidated Metrics Strip (Replaces 6 boxy cards) */}
      <div className="p-4 sm:p-5 rounded-2xl bg-surface-subtle/80 border border-border-subtle grid grid-cols-2 md:grid-cols-4 gap-4 sm:gap-6 divide-y md:divide-y-0 md:divide-x divide-border-subtle/70">
        {/* Metric 1: First Punch (Check-In) */}
        <div className="flex flex-col justify-between pt-2 md:pt-0 md:px-3 first:px-0">
          <div className="flex items-center justify-between text-muted">
            <span className="text-[10px] font-black uppercase tracking-wider">Punch In</span>
            <LogIn size={14} className={isLate ? 'text-amber-500' : 'text-primary'} />
          </div>
          <div className="mt-2">
            <span className={`text-base sm:text-lg font-black block ${
              isLate ? 'text-amber-600 dark:text-amber-400' : 'text-foreground'
            }`}>
              {checkInTimeDisplay}
            </span>
            <div className="flex items-center gap-1 mt-0.5">
              {punctualityStatus === 'late' ? (
                <span className="inline-flex items-center gap-1 text-[10px] font-black text-amber-500 uppercase tracking-wide">
                  <AlertTriangle size={10} /> {lateDurationDisplay || 'Late'}
                </span>
              ) : punctualityStatus === 'early' ? (
                <span className="inline-flex items-center gap-1 text-[10px] font-black text-blue-500 uppercase tracking-wide">
                  <Zap size={10} /> {earlyDurationDisplay || 'Early'}
                </span>
              ) : punctualityStatus === 'on-time' ? (
                <span className="inline-flex items-center gap-1 text-[10px] font-bold text-emerald-500">
                  <CheckCircle2 size={10} /> On Time
                </span>
              ) : (
                <span className="text-[10px] font-bold text-muted">Not punched</span>
              )}
            </div>
          </div>
        </div>

        {/* Metric 2: Live Active Session */}
        <div className="flex flex-col justify-between pt-2 md:pt-0 md:px-3">
          <div className="flex items-center justify-between text-muted">
            <span className="text-[10px] font-black uppercase tracking-wider">Live Session</span>
            <Activity size={14} className={isCheckedIn ? 'text-emerald-500 animate-pulse' : 'text-muted'} />
          </div>
          <div className="mt-2">
            <span className="text-base sm:text-lg font-black text-foreground block">
              {liveWorkingTime}
            </span>
            <span className="text-[10px] font-bold text-muted mt-0.5 block">
              {isCheckedIn ? 'Active shift elapsed' : 'No active session'}
            </span>
          </div>
        </div>

        {/* Metric 3: Total Break */}
        <div className="flex flex-col justify-between pt-2 md:pt-0 md:px-3">
          <div className="flex items-center justify-between text-muted">
            <span className="text-[10px] font-black uppercase tracking-wider">Breaks</span>
            <Coffee size={14} className={isOnBreak ? 'text-amber-500 animate-pulse' : 'text-muted'} />
          </div>
          <div className="mt-2">
            <span className="text-base sm:text-lg font-black text-foreground block">
              {totalBreakDisplay}
            </span>
            <span className="text-[10px] font-bold text-muted mt-0.5 block">
              {isOnBreak ? 'Break currently active' : 'Total break time'}
            </span>
          </div>
        </div>

        {/* Metric 4: Net Productive Working Time */}
        <div className="flex flex-col justify-between pt-2 md:pt-0 md:px-3">
          <div className="flex items-center justify-between text-primary">
            <span className="text-[10px] font-black uppercase tracking-wider">Net Working</span>
            <Hourglass size={14} className="text-primary" />
          </div>
          <div className="mt-2">
            <span className="text-base sm:text-lg font-black text-primary block">
              {netWorkingDisplay}
            </span>
            <span className="text-[10px] font-bold text-muted mt-0.5 block">
              {checkOutTimeDisplay !== '—' && checkOutTimeDisplay !== 'In Progress' ? `Out: ${checkOutTimeDisplay}` : 'Gross minus breaks'}
            </span>
          </div>
        </div>
      </div>

      {/* Minimal Micro-Interactive Mood Selector */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 pt-3 border-t border-border-subtle/50">
        <div className="flex items-center gap-1.5">
          <Sparkles size={13} className="text-primary" />
          <span className="text-[11px] font-black uppercase tracking-wider text-muted">
            How are you feeling today?
          </span>
          {selectedMood && (
            <span className="text-[10px] font-bold text-emerald-500 flex items-center gap-1 ml-2">
              <CheckCircle2 size={11} /> Saved
            </span>
          )}
        </div>

        <div className="flex items-center gap-1.5 w-full sm:w-auto">
          {MOODS.map((m) => {
            const isSelected = selectedMood === m.value;
            return (
              <button
                key={m.value}
                type="button"
                onClick={() => logMood(m.value, m.label)}
                disabled={isSubmittingMood}
                title={`Feeling ${m.label}`}
                className={`flex-1 sm:flex-none flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-black transition-all cursor-pointer ${
                  isSelected
                    ? 'bg-primary/15 border border-primary/40 text-primary shadow-xs scale-105'
                    : 'bg-surface-subtle hover:bg-surface-elevated border border-border-subtle text-muted hover:text-foreground'
                }`}>
                <m.icon size={13} className={isSelected ? 'text-primary' : 'text-muted'} />
                <span className="text-[11px] font-bold">{m.label}</span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import { useState, useEffect, useMemo } from 'react';
import {
  useCheckInMutation,
  useCheckOutMutation,
  useGetAttendanceStatusQuery,
  useTakeBreakMutation,
  useEndBreakMutation,
  useGetAttendanceHistoryQuery,
  useGetActiveOfficesQuery,
  type Office,
} from '@/store/api/attendanceSlice';
import { useSubmitMoodMutation } from '@/store/api/moodSlice';
import { showToast } from '@/components/ui/composed/Toast.utils';
import { generateMonthAttendanceRecords, calculateMonthSummary } from '../utils/attendanceUtils';
import { reverseGeocode } from '@/services/geocodingService';
import { getUltraAccuratePosition } from '@/utils/highAccuracyGeolocation';

// ---------- helpers ----------

/** Format a Date/ISO string to "10:45 AM" style */
function formatTimeDisplay(dateOrIso: string | Date | null | undefined): string {
  if (!dateOrIso) return '—';
  const d = typeof dateOrIso === 'string' ? new Date(dateOrIso) : dateOrIso;
  if (isNaN(d.getTime())) return '—';
  return d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
}

/** Format elapsed minutes → "4h 45m" */
function formatElapsed(totalMinutes: number): string {
  if (totalMinutes <= 0) return '0m';
  const h = Math.floor(totalMinutes / 60);
  const m = totalMinutes % 60;
  if (h === 0) return `${m}m`;
  if (m === 0) return `${h}h`;
  return `${h}h ${m}m`;
}

/** Shift config — keep centralised for future config-based shifts */
const SHIFT_START_HOUR = 10;
const SHIFT_START_MIN = 0;
const SHIFT_DISPLAY = '10:00 AM – 05:00 PM';

/**
 * Haversine distance calculator between two GPS points in meters.
 */
export function computeDistanceMeters(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371e3;
  const p1 = (lat1 * Math.PI) / 180;
  const p2 = (lat2 * Math.PI) / 180;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;

  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(p1) * Math.cos(p2) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return Math.round(R * c * 10) / 10;
}


export interface GeoLocationState {
  latitude: number | null;
  longitude: number | null;
  accuracy: number | null;
  error: string | null;
  isFetching: boolean;
  locationName: string | null;
  permissionGranted: boolean;
}


/**
 * Acquire high-accuracy position promise compatible with incognito and private browsing.
 */
async function acquireHighAccuracyPosition(timeoutMs = 7000): Promise<GeolocationPosition> {
  const accurate = await getUltraAccuratePosition({ timeoutMs, desiredAccuracyMeters: 10 });
  return accurate.rawPosition;
}

export const useAttendance = () => {
  const [time, setTime] = useState(new Date());
  const [selectedMood, setSelectedMood] = useState<number | null>(null);
  const [currentMonth, setCurrentMonth] = useState<Date>(new Date());
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  // Office Geofencing & Location states
  const { data: offices = [] } = useGetActiveOfficesQuery();
  const [selectedOfficeId, setSelectedOfficeId] = useState<number | null>(null);
  const [isVerifyingGeofence, setIsVerifyingGeofence] = useState<boolean>(false);


  // WFH vs Office Work Mode toggle (defaults to 'office')
  const [workMode, setWorkMode] = useState<'office' | 'wfh'>('office');

  // Break note state (employee types reason before taking break)
  const [breakNote, setBreakNote] = useState<string>('');

  // Real-time Geo-Tagging state
  const [geoLocation, setGeoLocation] = useState<GeoLocationState>({
    latitude: null,
    longitude: null,
    accuracy: null,
    error: null,
    isFetching: false,
    locationName: null,
    permissionGranted: false,
  });

  const { data: status, isLoading: isFetching } = useGetAttendanceStatusQuery();
  const { data: history = [] } = useGetAttendanceHistoryQuery();

  const [checkIn, { isLoading: isCheckingIn }] = useCheckInMutation();
  const [checkOut, { isLoading: isCheckingOut }] = useCheckOutMutation();
  const [submitMood, { isLoading: isSubmittingMood }] = useSubmitMoodMutation();

  const [takeBreak, { isLoading: isStartingBreak }] = useTakeBreakMutation();
  const [endBreak, { isLoading: isEndingBreak }] = useEndBreakMutation();

  // Sync workMode with backend status if already checked in
  useEffect(() => {
    if (status?.work_mode) {
      setWorkMode(status.work_mode === 'wfh' ? 'wfh' : 'office');
    }
  }, [status?.work_mode]);

  // Request ultra-accurate browser geolocation with multi-sampling
  const requestGeoLocation = async () => {
    if (!navigator.geolocation) {
      setGeoLocation((prev) => ({
        ...prev,
        error: 'Geolocation is not supported by your browser',
        isFetching: false,
      }));
      return;
    }

    setGeoLocation((prev) => ({ ...prev, isFetching: true, error: null }));

    try {
      const best = await getUltraAccuratePosition({ timeoutMs: 5000, desiredAccuracyMeters: 15 });
      setGeoLocation({
        latitude: best.latitude,
        longitude: best.longitude,
        accuracy: best.accuracy,
        error: null,
        isFetching: false,
        locationName: `${best.latitude.toFixed(4)}°, ${best.longitude.toFixed(4)}° (GPS)`,
        permissionGranted: true,
      });

      // Asynchronously fetch human-readable street address for pinpoint display
      reverseGeocode(best.latitude, best.longitude).then((addr) => {
        if (addr) {
          setGeoLocation((prev) => ({
            ...prev,
            locationName: addr,
          }));
        }
      }).catch(() => {});
    } catch (err: any) {
      let msg = 'Failed to get location';
      if (err.code === 1) {
        msg = 'Location permission denied';
      } else if (err.code === 2) {
        msg = 'Location information unavailable. Check device GPS.';
      } else if (err.code === 3) {
        msg = 'Location request timed out';
      } else if (err.message) {
        msg = err.message;
      }
      setGeoLocation((prev) => ({
        ...prev,
        error: msg,
        isFetching: false,
        permissionGranted: false,
      }));
    }
  };

  // Auto-detect geolocation on mount
  useEffect(() => {
    requestGeoLocation();
  }, []);

  // Clock Ticker
  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Generate monthly records (merging API data if present with standard month generator)
  const monthRecords = useMemo(() => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const generated = generateMonthAttendanceRecords(year, month);

    // Overlay real API history items if date matches
    if (Array.isArray(history) && history.length > 0) {
      history.forEach((h: any) => {
        const matchingIndex = generated.findIndex((g) => g.date === h.date);
        if (matchingIndex !== -1) {
          const checkInStr = h.check_in_time ? formatTimeDisplay(h.check_in_time) : (h.checkIn || generated[matchingIndex].checkIn);
          const checkOutStr = h.check_out_time ? formatTimeDisplay(h.check_out_time) : (h.checkOut || generated[matchingIndex].checkOut);
          const workMins = h.work_duration != null ? Number(h.work_duration) : null;
          const breakMins = h.total_break_minutes != null ? Number(h.total_break_minutes) : null;

          generated[matchingIndex] = {
            ...generated[matchingIndex],
            checkIn: checkInStr,
            checkOut: checkOutStr,
            status: (h.status as any) || generated[matchingIndex].status,
            work_mode: h.work_mode || (h.is_wfh ? 'wfh' : 'office'),
            is_wfh: Boolean(h.is_wfh || h.work_mode === 'wfh'),
            check_in_latitude: h.check_in_latitude,
            check_in_longitude: h.check_in_longitude,
            check_in_location: h.check_in_location,
            check_out_latitude: h.check_out_latitude,
            check_out_longitude: h.check_out_longitude,
            check_out_location: h.check_out_location,
            totalBreakMinutes: breakMins != null ? breakMins : generated[matchingIndex].totalBreakMinutes,
            netWorkingHours: workMins != null ? Number((workMins / 60).toFixed(2)) : generated[matchingIndex].netWorkingHours,
          };
        }
      });
    }

    return generated;
  }, [currentMonth, history]);

  // Aggregate monthly stats summary
  const monthSummary = useMemo(() => {
    return calculateMonthSummary(monthRecords);
  }, [monthRecords]);


  // Target office for geofence verification (selected or closest)
  const activeOffice: Office | null = useMemo(() => {
    if (offices.length === 0) return null;
    if (selectedOfficeId) {
      const found = offices.find((o) => o.id === selectedOfficeId);
      if (found) return found;
    }
    // If user has coords, find closest office automatically
    if (geoLocation.latitude && geoLocation.longitude) {
      let closest = offices[0];
      let minDist = Infinity;
      for (const off of offices) {
        const d = computeDistanceMeters(
          geoLocation.latitude,
          geoLocation.longitude,
          off.latitude,
          off.longitude
        );
        if (d < minDist) {
          minDist = d;
          closest = off;
        }
      }
      return closest;
    }
    return offices[0];
  }, [offices, selectedOfficeId, geoLocation.latitude, geoLocation.longitude]);

  // Live distance from active office
  const distanceToOffice: number | null = useMemo(() => {
    if (!activeOffice || geoLocation.latitude === null || geoLocation.longitude === null) {
      return null;
    }
    return computeDistanceMeters(
      geoLocation.latitude,
      geoLocation.longitude,
      activeOffice.latitude,
      activeOffice.longitude
    );
  }, [activeOffice, geoLocation.latitude, geoLocation.longitude]);

  // Whether employee is inside the active office's geofence
  const isInsideGeofence: boolean | null = useMemo(() => {
    if (distanceToOffice === null || !activeOffice) return null;
    return distanceToOffice <= activeOffice.radius;
  }, [distanceToOffice, activeOffice]);

  // Live session metrics calculation
  const isCheckedIn = status?.status === 'checked-in';
  const isOnBreak = !!status?.onBreak;

  // ── Check-in time (from API lastAction / record) ──
  const checkInDate: Date | null = useMemo(() => {
    const raw = status?.lastAction || (status?.record as any)?.check_in_time;
    if (!raw) return null;
    const d = new Date(raw);
    return isNaN(d.getTime()) ? null : d;
  }, [status?.lastAction, status?.record]);

  // ── Check-out time ──
  const checkOutDate: Date | null = useMemo(() => {
    const raw = (status?.record as any)?.check_out_time;
    if (!raw) return null;
    const d = new Date(raw);
    return isNaN(d.getTime()) ? null : d;
  }, [status?.record]);

  const checkInTimeDisplay = checkInDate ? formatTimeDisplay(checkInDate) : '—';
  const checkOutTimeDisplay = isCheckedIn ? 'In Progress' : (checkOutDate ? formatTimeDisplay(checkOutDate) : '—');
  const shiftTimingDisplay = SHIFT_DISPLAY;

  // Currently selected date detail record
  const selectedDayRecord = useMemo(() => {
    const dateStr = `${selectedDate.getFullYear()}-${String(selectedDate.getMonth() + 1).padStart(2, '0')}-${String(selectedDate.getDate()).padStart(2, '0')}`;
    const baseRecord = monthRecords.find((r) => r.date === dateStr);
    if (!baseRecord) return undefined;

    const todayStr = `${time.getFullYear()}-${String(time.getMonth() + 1).padStart(2, '0')}-${String(time.getDate()).padStart(2, '0')}`;

    if (dateStr === todayStr && (status?.record || (status?.breaks && status.breaks.length > 0))) {
      const rawBreaks = Array.isArray(status?.breaks) ? status.breaks : [];
      let mappedBreaks = baseRecord.breaks;

      if (rawBreaks.length > 0 || status?.activeBreak) {
        mappedBreaks = rawBreaks.map((b: any, idx: number) => {
          const s = b.break_start ? new Date(b.break_start) : null;
          const e = b.break_end ? new Date(b.break_end) : null;
          const startTimeStr = s && !isNaN(s.getTime()) ? formatTimeDisplay(s) : '—';
          const isOngoing = b.status === 'IN_PROGRESS' || b.break_end === null;
          const endTimeStr = isOngoing ? 'In Progress' : (e && !isNaN(e.getTime()) ? formatTimeDisplay(e) : '—');
          const duration = b.duration != null && b.duration >= 0 ? b.duration : (s && !isNaN(s.getTime()) ? Math.max(0, Math.floor((time.getTime() - s.getTime()) / 60000)) : 0);
          const breakType = b.break_type || (b.break_note ? b.break_note : `Break #${idx + 1}`);
          const label = breakType.toLowerCase().includes('break') ? breakType : `${breakType} Break`;
          const maxAllowed = breakType.toLowerCase().includes('tea') ? 15 : (breakType.toLowerCase().includes('lunch') ? 45 : 30);
          return {
            id: `real-break-${b.id || idx}`,
            label,
            break_type: breakType,
            status: isOngoing ? 'IN_PROGRESS' : 'COMPLETED',
            date: b.date || todayStr,
            startTime: startTimeStr,
            endTime: endTimeStr,
            durationMinutes: duration,
            break_note: b.break_note || undefined,
            maxAllowedMinutes: maxAllowed,
            isOverTime: duration > maxAllowed,
          };
        });
      }

      const completedBreakMins = status?.total_break_minutes ?? 0;
      const activeBreakStart = (status?.activeBreak as any)?.break_start || (status?.activeBreak as any)?.start_time;
      let activeBreakMins = 0;
      if (status?.onBreak && activeBreakStart) {
        const started = new Date(activeBreakStart);
        if (!isNaN(started.getTime())) {
          activeBreakMins = Math.max(0, Math.floor((time.getTime() - started.getTime()) / 60000));
        }
      }
      const totalBreakMins = completedBreakMins + activeBreakMins;

      // Calculate real gross and net working hours
      let grossHours = baseRecord.grossWorkingHours;
      let netHours = baseRecord.netWorkingHours;
      if (checkInDate) {
        const endRef = checkOutDate || time;
        const grossMs = Math.max(0, endRef.getTime() - checkInDate.getTime());
        const grossMins = Math.floor(grossMs / 60000);
        grossHours = Number((grossMins / 60).toFixed(2));

        const storedWorkDuration = (status?.record as any)?.work_duration;
        if (checkOutDate && storedWorkDuration != null && Number(storedWorkDuration) > 0) {
          netHours = Number((Number(storedWorkDuration) / 60).toFixed(2));
        } else {
          const netMins = Math.max(0, grossMins - totalBreakMins);
          netHours = Number((netMins / 60).toFixed(2));
        }
      }

      return {
        ...baseRecord,
        checkIn: (status?.record as any)?.check_in_time ? formatTimeDisplay((status.record as any).check_in_time) : baseRecord.checkIn,
        checkOut: (status?.record as any)?.check_out_time ? formatTimeDisplay((status.record as any).check_out_time) : (status?.status === 'checked-in' ? 'In Progress' : baseRecord.checkOut),
        check_in_location: (status?.record as any)?.check_in_location || baseRecord.check_in_location,
        check_out_location: (status?.record as any)?.check_out_location || baseRecord.check_out_location,
        breaks: mappedBreaks,
        totalBreakMinutes: totalBreakMins,
        grossWorkingHours: grossHours,
        netWorkingHours: netHours,
      };
    }

    return baseRecord;
  }, [selectedDate, monthRecords, time, status, checkInDate, checkOutDate]);

  // ── 3-state Punctuality: early | on-time | late ──
  // Grace window: ±5 min around shift start counts as 'on-time'
  const GRACE_MINUTES = 5;
  const { punctualityStatus, isLate, lateDurationDisplay, earlyDurationDisplay } = useMemo(() => {
    if (!checkInDate) {
      return {
        punctualityStatus: 'unknown' as const,
        isLate: false,
        lateDurationDisplay: '',
        earlyDurationDisplay: '',
      };
    }
    const shiftStartMinutes = SHIFT_START_HOUR * 60 + SHIFT_START_MIN;
    const checkInMinutes = checkInDate.getHours() * 60 + checkInDate.getMinutes();
    const diffMinutes = checkInMinutes - shiftStartMinutes; // positive = late, negative = early

    if (diffMinutes > GRACE_MINUTES) {
      // LATE
      const h = Math.floor(diffMinutes / 60);
      const m = diffMinutes % 60;
      const display = h > 0 ? `${h}h ${m}m late` : `${m} min late`;
      return { punctualityStatus: 'late' as const, isLate: true, lateDurationDisplay: display, earlyDurationDisplay: '' };
    } else if (diffMinutes < -GRACE_MINUTES) {
      // EARLY
      const absDiff = Math.abs(diffMinutes);
      const h = Math.floor(absDiff / 60);
      const m = absDiff % 60;
      const display = h > 0 ? `${h}h ${m}m early` : `${m} min early`;
      return { punctualityStatus: 'early' as const, isLate: false, lateDurationDisplay: '', earlyDurationDisplay: display };
    } else {
      // ON TIME (within grace window)
      return { punctualityStatus: 'on-time' as const, isLate: false, lateDurationDisplay: '', earlyDurationDisplay: '' };
    }
  }, [checkInDate]);


  // ── Live elapsed working time (ticks every second via `time`) ──
  const liveWorkingTime = useMemo(() => {
    if (!isCheckedIn || !checkInDate) return '—';
    const elapsedMs = time.getTime() - checkInDate.getTime();
    const totalMinutes = Math.floor(elapsedMs / 60000);
    return formatElapsed(Math.max(0, totalMinutes));
  }, [isCheckedIn, checkInDate, time]);

  // ── Break & net working ──
  const totalBreakDisplay = useMemo(() => {
    const activeBreakStart =
      (status?.activeBreak as any)?.break_start || (status?.activeBreak as any)?.start_time;
    let activeBreakMins = 0;
    if (isOnBreak && activeBreakStart) {
      const started = new Date(activeBreakStart);
      if (!isNaN(started.getTime())) {
        activeBreakMins = Math.max(0, Math.floor((time.getTime() - started.getTime()) / 60000));
      }
    }
    const completedMins = status?.total_break_minutes ?? 0;
    const totalMins = completedMins + activeBreakMins;
    if (totalMins > 0) {
      return `${formatElapsed(totalMins)}${isOnBreak ? ' (Active)' : ''}`;
    }
    return isOnBreak ? 'On Break' : '—';
  }, [isOnBreak, status?.activeBreak, status?.total_break_minutes, time]);

  const netWorkingDisplay = useMemo(() => {
    if (!isCheckedIn || !checkInDate) return '—';
    const elapsedMs = time.getTime() - checkInDate.getTime();
    const grossMins = Math.floor(elapsedMs / 60000);
    // Subtract cumulative + active break
    const activeBreakStart =
      (status?.activeBreak as any)?.break_start || (status?.activeBreak as any)?.start_time;
    let activeBreakMins = 0;
    if (isOnBreak && activeBreakStart) {
      const started = new Date(activeBreakStart);
      if (!isNaN(started.getTime())) {
        activeBreakMins = Math.max(0, Math.floor((time.getTime() - started.getTime()) / 60000));
      }
    }
    const totalBreakMins = (status?.total_break_minutes ?? 0) + activeBreakMins;
    return formatElapsed(Math.max(0, grossMins - totalBreakMins));
  }, [isCheckedIn, checkInDate, isOnBreak, status?.activeBreak, status?.total_break_minutes, time]);

  const handleAttendance = async () => {
    try {
      if (status?.status === 'checked-in') {
        let checkoutLat = geoLocation.latitude;
        let checkoutLon = geoLocation.longitude;

        try {
          const freshPos = await acquireHighAccuracyPosition(4000);
          checkoutLat = freshPos.coords.latitude;
          checkoutLon = freshPos.coords.longitude;
        } catch {
          // fallback to current cached position
        }

        await checkOut({
          latitude: checkoutLat,
          longitude: checkoutLon,
          location_name: geoLocation.locationName,
          check_out_latitude: checkoutLat,
          check_out_longitude: checkoutLon,
          check_out_location:
            geoLocation.locationName || (workMode === 'wfh' ? 'Remote / Home' : (activeOffice?.name || 'Office HQ')),
        }).unwrap();

        showToast({
          severity: 'success',
          summary: 'Checked Out',
          detail: 'You have been successfully checked out with location verification.',
          life: 3000,
        });
      } else {
        const isWfhSelected = workMode === 'wfh';
        setIsVerifyingGeofence(true);

        let finalLat = geoLocation.latitude;
        let finalLon = geoLocation.longitude;
        let finalAcc = geoLocation.accuracy;

        // For Office check-in: require fresh high-accuracy location
        if (!isWfhSelected) {
          try {
            showToast({
              severity: 'info',
              summary: 'Verifying Location',
              detail: 'Verifying your office location with GPS...',
              life: 2500,
            });
            const freshPos = await acquireHighAccuracyPosition(10000);
            finalLat = freshPos.coords.latitude;
            finalLon = freshPos.coords.longitude;
            finalAcc = freshPos.coords.accuracy;

            setGeoLocation({
              latitude: finalLat,
              longitude: finalLon,
              accuracy: finalAcc,
              error: null,
              isFetching: false,
              locationName: `${finalLat.toFixed(4)}°, ${finalLon.toFixed(4)}° (GPS)`,
              permissionGranted: true,
            });

            try {
              const placeAddr = await reverseGeocode(finalLat, finalLon);
              if (placeAddr) {
                setGeoLocation((prev) => ({ ...prev, locationName: placeAddr }));
              }
            } catch {}
          } catch (posErr: any) {
            setIsVerifyingGeofence(false);
            let userMsg = 'Unable to determine your current location.';
            if (posErr?.code === 1) {
              userMsg = 'Please enable location permission to check in.';
            } else if (posErr?.code === 2) {
              userMsg = 'Unable to determine your current location. Please verify device GPS is active.';
            } else if (posErr?.code === 3) {
              userMsg = 'Location request timed out. Please try again.';
            }
            showToast({
              severity: 'error',
              summary: 'Location Required',
              detail: userMsg,
              life: 5000,
            });
            return;
          }
        }

        const deviceInfo = [
          navigator.userAgent.slice(0, 120),
          `${screen.width}x${screen.height}`,
        ].join(' | ');

        const res: any = await checkIn({
          remark: isWfhSelected ? 'WFH Check-in' : 'Office Check-in',
          work_mode: workMode,
          is_wfh: isWfhSelected,
          latitude: finalLat,
          longitude: finalLon,
          check_in_latitude: finalLat,
          check_in_longitude: finalLon,
          location_accuracy: finalAcc,
          accuracy: finalAcc,
          office_id: activeOffice?.id || null,
          device_info: deviceInfo,
        }).unwrap();

        showToast({
          severity: 'success',
          summary: 'Check-in Successful',
          detail: isWfhSelected
            ? 'Checked in successfully as Remote / WFH.'
            : `Verified inside ${res?.office_name || activeOffice?.name || 'Office'} (${Math.round(res?.distance_from_office || distanceToOffice || 0)}m from center).`,
          life: 4000,
        });
      }
    } catch (error: unknown) {
      console.error('Attendance action failed:', error);
      const apiErr = error as { data?: { message?: string; code?: string; data?: any } };
      const errCode = apiErr?.data?.code;
      const errMsg = apiErr?.data?.message || 'Check-in failed. Please try again.';

      if (errCode === 'OUTSIDE_GEOFENCE') {
        showToast({
          severity: 'error',
          summary: 'Outside Office Geofence',
          detail: errMsg,
          life: 7000,
        });
      } else if (errCode === 'INACCURATE_LOCATION') {
        showToast({
          severity: 'warn',
          summary: 'Inaccurate Location',
          detail: errMsg,
          life: 6000,
        });
      } else {
        showToast({
          severity: 'error',
          summary: 'Check-in Failed',
          detail: errMsg,
          life: 4000,
        });
      }
    } finally {
      setIsVerifyingGeofence(false);
    }
  };

  const handleBreak = async (breakTypeOrRemark?: string, customRemark?: string) => {
    try {
      if (status?.onBreak) {
        const res = await endBreak().unwrap();
        setBreakNote('');
        showToast({
          severity: 'success',
          summary: 'Break Ended',
          detail: res.message || 'Welcome back! Break time has been recorded in database.',
          life: 3000,
        });
      } else {
        let break_type = 'Break';
        let break_note = '';

        if (breakTypeOrRemark) {
          if (breakTypeOrRemark.toLowerCase().includes('tea')) {
            break_type = 'Tea Break';
            break_note = customRemark || breakNote || 'Tea Break';
          } else if (breakTypeOrRemark.toLowerCase().includes('lunch')) {
            break_type = 'Lunch Break';
            break_note = customRemark || breakNote || 'Lunch Break';
          } else {
            break_type = breakTypeOrRemark;
            break_note = customRemark || breakTypeOrRemark;
          }
        } else if (breakNote && breakNote.trim()) {
          const trimmed = breakNote.trim();
          if (trimmed.toLowerCase().includes('tea')) break_type = 'Tea Break';
          else if (trimmed.toLowerCase().includes('lunch')) break_type = 'Lunch Break';
          else break_type = trimmed;
          break_note = trimmed;
        }

        const effectiveNote = break_note || break_type;
        const break_status_message = customRemark || breakNote || (effectiveNote.toLowerCase().includes(break_type.toLowerCase()) ? effectiveNote : `${break_type}: ${effectiveNote}`);
       
        const res = await takeBreak({
          break_type,
          break_note: effectiveNote,
          break_status_message,
        }).unwrap();
        setBreakNote('');
        showToast({
          severity: 'success',
          summary: `${break_type} Started`,
          detail: res.message || `${break_type} started: "${break_note || break_type}"`,
          life: 3000,
        });
      }
    } catch (error: unknown) {
      const apiError = error as { data?: { message?: string } };
      console.error('Break action failed:', error);
      showToast({
        severity: 'error',
        summary: 'Break Error',
        detail: apiError.data?.message || 'Action failed',
        life: 3000,
      });
    }
  };

  const logMood = async (score: number, label: string) => {
    setSelectedMood(score);
    try {
      await submitMood({
        mood_score: score,
        stress_level: 3,
        comments: `Feeling ${label}`,
      }).unwrap();
      showToast({
        severity: 'success',
        summary: 'Mood Logged',
        detail: `You're feeling ${label.toLowerCase()} today. Thanks for sharing!`,
        life: 3000,
      });
    } catch (err: unknown) {
      const apiError = err as { data?: { message?: string } };
      console.error('Mood submission failed:', err);
      showToast({
        severity: 'error',
        summary: 'Mood Logging Error',
        detail: apiError.data?.message || 'Failed to log mood',
        life: 3000,
      });
    }
  };

  return {
    time,
    status,
    selectedMood,
    isLoading: isFetching || isCheckingIn || isCheckingOut,
    isBreakLoading: isStartingBreak || isEndingBreak,
    isSubmittingMood,
    handleAttendance,
    handleBreak,
    logMood,
    currentMonth,
    setCurrentMonth,
    selectedDate,
    setSelectedDate,
    monthRecords,
    monthSummary,
    selectedDayRecord,
    breakNote,
    setBreakNote,
    liveWorkingTime,
    checkInTimeDisplay,
    checkOutTimeDisplay,
    totalBreakDisplay,
    netWorkingDisplay,
    isLate,
    lateDurationDisplay,
    earlyDurationDisplay,
    punctualityStatus,
    shiftTimingDisplay,
    workMode,
    setWorkMode,
    geoLocation,
    requestGeoLocation,
    offices,
    selectedOfficeId,
    setSelectedOfficeId,
    activeOffice,
    distanceToOffice,
    isInsideGeofence,
    isVerifyingGeofence,
  };
};

export interface BreakItem {
  id: string | number;
  label: string;
  startTime: string;
  endTime: string;
  durationMinutes: number;
  status?: 'IN_PROGRESS' | 'COMPLETED' | string;
  break_type?: string;
  date?: string;
  break_note?: string | null;     // What employee noted when taking break
  maxAllowedMinutes?: number;     // Policy limit (e.g. Tea: 15m, Lunch: 45m)
  isOverTime?: boolean;           // true if durationMinutes > maxAllowedMinutes
}

export interface DayDetailedRecord {
  id: string | number;
  date: string; // YYYY-MM-DD
  status: 'Present' | 'Late' | 'Absent' | 'On Leave' | 'Holiday' | 'Weekend' | 'Half Day';
  shift: string; // e.g. "10:00 AM – 05:00 PM"
  shiftStart: string; // e.g. "10:00 AM"
  shiftEnd: string; // e.g. "05:00 PM"
  checkIn?: string; // e.g. "10:05 AM"
  checkOut?: string; // e.g. "05:04 PM"
  breaks: BreakItem[];
  totalBreakMinutes: number;
  grossWorkingHours: number; // decimal hours
  netWorkingHours: number; // decimal hours
  isLate: boolean;
  lateMinutes: number;
  earlyDepartureMinutes: number;
  overtimeHours: number;
  location?: string;
  notes?: string;
  work_mode?: 'office' | 'wfh' | 'field';
  is_wfh?: boolean;
  check_in_latitude?: number | null;
  check_in_longitude?: number | null;
  check_in_location?: string | null;
  check_out_latitude?: number | null;
  check_out_longitude?: number | null;
  check_out_location?: string | null;
}

export interface MonthAttendanceSummary {
  presentDays: number;
  lateDays: number;
  absentDays: number;
  leaveDays: number;
  holidayDays: number;
  weekendDays: number;
  avgWorkingHours: string;
  avgBreakMinutes: number;
  totalOvertimeHours: number;
  attendancePercentage: number;
}

// Convert "10:15 AM" or "17:30" to minutes from midnight
export function parseTimeToMinutes(timeStr: string): number {
  if (!timeStr) return 0;
  const clean = timeStr.trim().toUpperCase();
  const isPM = clean.includes('PM');
  const isAM = clean.includes('AM');

  let [hoursStr, minutesStr] = clean
    .replace(/(AM|PM)/g, '')
    .trim()
    .split(':');
  let hours = parseInt(hoursStr, 10) || 0;
  const minutes = parseInt(minutesStr, 10) || 0;

  if (isPM && hours < 12) hours += 12;
  if (isAM && hours === 12) hours = 0;

  return hours * 60 + minutes;
}

// Format decimal hours to readable string like "6h 35m" or "0h 0m"
export function formatHoursAndMinutes(decimalHours: number): string {
  if (!decimalHours || decimalHours <= 0) return '0h 0m';
  const totalMinutes = Math.round(decimalHours * 60);
  const hrs = Math.floor(totalMinutes / 60);
  const mins = totalMinutes % 60;
  if (hrs === 0) return `${mins}m`;
  if (mins === 0) return `${hrs}h`;
  return `${hrs}h ${mins}m`;
}

// Format minutes to readable string like "25m" or "1h 15m"
export function formatMinutes(totalMinutes: number): string {
  if (!totalMinutes || totalMinutes <= 0) return '0m';
  const hrs = Math.floor(totalMinutes / 60);
  const mins = totalMinutes % 60;
  if (hrs === 0) return `${mins}m`;
  if (mins === 0) return `${hrs}h`;
  return `${hrs}h ${mins}m`;
}

// Generate realistic records for past & present days ONLY (Shift: 10:00 AM – 05:00 PM)
export function generateMonthAttendanceRecords(
  year: number,
  monthZeroIndexed: number
): DayDetailedRecord[] {
  const records: DayDetailedRecord[] = [];
  const daysInMonth = new Date(year, monthZeroIndexed + 1, 0).getDate();

  const now = new Date();
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth();
  const currentDay = now.getDate();

  for (let day = 1; day <= daysInMonth; day++) {
    const d = new Date(year, monthZeroIndexed, day);
    const dayOfWeek = d.getDay(); // 0 = Sun, 6 = Sat
    const dateStr = `${year}-${String(monthZeroIndexed + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

    // Weekend check
    if (dayOfWeek === 0 || dayOfWeek === 6) {
      records.push({
        id: `day-${dateStr}`,
        date: dateStr,
        status: 'Weekend',
        shift: '10:00 AM – 05:00 PM',
        shiftStart: '10:00 AM',
        shiftEnd: '05:00 PM',
        breaks: [],
        totalBreakMinutes: 0,
        grossWorkingHours: 0,
        netWorkingHours: 0,
        isLate: false,
        lateMinutes: 0,
        earlyDepartureMinutes: 0,
        overtimeHours: 0,
      });
      continue;
    }

    // STRICT FUTURE DATE CHECK: No future attendance punches
    const isFuture =
      year > currentYear ||
      (year === currentYear && monthZeroIndexed > currentMonth) ||
      (year === currentYear && monthZeroIndexed === currentMonth && day > currentDay);

    if (isFuture) {
      if (day === 15) {
        records.push({
          id: `day-${dateStr}`,
          date: dateStr,
          status: 'Holiday',
          shift: '10:00 AM – 05:00 PM',
          shiftStart: '10:00 AM',
          shiftEnd: '05:00 PM',
          breaks: [],
          totalBreakMinutes: 0,
          grossWorkingHours: 0,
          netWorkingHours: 0,
          isLate: false,
          lateMinutes: 0,
          earlyDepartureMinutes: 0,
          overtimeHours: 0,
          notes: 'Upcoming Holiday: Foundation Day',
        });
      }
      continue;
    }

    // Past Holidays or Leaves
    if (day === 15) {
      records.push({
        id: `day-${dateStr}`,
        date: dateStr,
        status: 'Holiday',
        shift: '10:00 AM – 05:00 PM',
        shiftStart: '10:00 AM',
        shiftEnd: '05:00 PM',
        breaks: [],
        totalBreakMinutes: 0,
        grossWorkingHours: 0,
        netWorkingHours: 0,
        isLate: false,
        lateMinutes: 0,
        earlyDepartureMinutes: 0,
        overtimeHours: 0,
        notes: 'Company Foundation Day',
      });
      continue;
    }

    if (day === 8 && day <= currentDay) {
      records.push({
        id: `day-${dateStr}`,
        date: dateStr,
        status: 'On Leave',
        shift: '10:00 AM – 05:00 PM',
        shiftStart: '10:00 AM',
        shiftEnd: '05:00 PM',
        breaks: [],
        totalBreakMinutes: 0,
        grossWorkingHours: 0,
        netWorkingHours: 0,
        isLate: false,
        lateMinutes: 0,
        earlyDepartureMinutes: 0,
        overtimeHours: 0,
        notes: 'Approved Casual Leave',
      });
      continue;
    }

    // Past / Today Days: Generate attendance record (Shift Start: 10:00 AM)
    const isLate = day % 4 === 0;
    const lateMins = isLate ? 10 + (day % 3) * 5 : 0;
    // const checkInHour = 10;
    const checkInMin = isLate ? lateMins : day % 5;
    const checkInTimeStr = `10:${String(checkInMin).padStart(2, '0')} AM`;

    const checkOutMin = day % 15;
    const checkOutTimeStr = `05:${String(checkOutMin).padStart(2, '0')} PM`;

    const breaks: BreakItem[] = [
      {
        id: `b1-${day}`,
        label: 'Tea Break',
        startTime: '11:30 AM',
        endTime: '11:42 AM',
        durationMinutes: 12,
        break_note: 'Quick tea break',
        maxAllowedMinutes: 15,
        isOverTime: false,
      },
      {
        id: `b2-${day}`,
        label: 'Lunch Break',
        startTime: '01:30 PM',
        endTime: '02:00 PM',
        durationMinutes: day % 5 === 0 ? 55 : 30, // some days over limit
        break_note: day % 5 === 0 ? 'Had lunch outside, took a bit longer' : 'Lunch break',
        maxAllowedMinutes: 45,
        isOverTime: day % 5 === 0,
      },
    ];

    const totalBreakMinutes = 42;
    const grossWorkingHours = 7.0;
    const netWorkingHours = 6.3;
    const overtimeHours = day % 6 === 0 ? 1.0 : 0;

    records.push({
      id: `day-${dateStr}`,
      date: dateStr,
      status: isLate ? 'Late' : 'Present',
      shift: '10:00 AM – 05:00 PM',
      shiftStart: '10:00 AM',
      shiftEnd: '05:00 PM',
      checkIn: checkInTimeStr,
      checkOut: checkOutTimeStr,
      breaks,
      totalBreakMinutes,
      grossWorkingHours,
      netWorkingHours,
      isLate,
      lateMinutes: lateMins,
      earlyDepartureMinutes: 0,
      overtimeHours,
      location: 'Main Office',
    });
  }

  return records;
}

// Compute aggregate metrics from a month's records
export function calculateMonthSummary(records: DayDetailedRecord[]): MonthAttendanceSummary {
  let presentDays = 0;
  let lateDays = 0;
  let absentDays = 0;
  let leaveDays = 0;
  let holidayDays = 0;
  let weekendDays = 0;
  let totalNetHours = 0;
  let totalBreakMins = 0;
  let totalOvertimeHours = 0;

  records.forEach((r) => {
    switch (r.status) {
      case 'Present':
        presentDays++;
        break;
      case 'Late':
        presentDays++;
        lateDays++;
        break;
      case 'Absent':
        absentDays++;
        break;
      case 'On Leave':
        leaveDays++;
        break;
      case 'Holiday':
        holidayDays++;
        break;
      case 'Weekend':
        weekendDays++;
        break;
      case 'Half Day':
        presentDays += 0.5;
        break;
    }

    if (r.netWorkingHours > 0) {
      totalNetHours += r.netWorkingHours;
    }
    totalBreakMins += r.totalBreakMinutes || 0;
    totalOvertimeHours += r.overtimeHours || 0;
  });

  const workingDaysCount = Math.max(1, presentDays);
  const avgWorkingHours = formatHoursAndMinutes(totalNetHours / workingDaysCount);
  const avgBreakMinutes = Math.round(totalBreakMins / workingDaysCount);

  const totalExpectedWorkingDays = records.length - (weekendDays + holidayDays);
  const attendancePercentage =
    totalExpectedWorkingDays > 0 ? Math.round((presentDays / totalExpectedWorkingDays) * 100) : 100;

  return {
    presentDays,
    lateDays,
    absentDays,
    leaveDays,
    holidayDays,
    weekendDays,
    avgWorkingHours,
    avgBreakMinutes,
    totalOvertimeHours: Math.round(totalOvertimeHours * 10) / 10,
    attendancePercentage,
  };
}

