              <span>Deployable</span> <ArrowUpRight size={10} />
            </span>
          </div>

          {/* Assigned */}
          <div
            onClick={() => navigate('/inventory?status=Assigned')}
            className="p-3.5 rounded-2xl bg-surface-subtle border border-border-subtle hover:border-purple-400 transition-all cursor-pointer group">
            <span className="text-[9px] font-black uppercase tracking-wider text-muted block mb-1">
              Assigned
            </span>
            <div className="text-xl font-black text-purple-600">{assignedItems}</div>
            <span className="text-[10px] text-muted font-bold group-hover:text-purple-600 transition-colors flex items-center gap-0.5 mt-0.5">
              <span>With staff</span> <ArrowUpRight size={10} />
            </span>
          </div>

          {/* Under Maintenance / Low Stock */}
          <div
            onClick={() => navigate('/inventory?status=Under+Maintenance')}
            className="p-3.5 rounded-2xl bg-surface-subtle border border-border-subtle hover:border-amber-400 transition-all cursor-pointer group">
            <span className="text-[9px] font-black uppercase tracking-wider text-muted block mb-1">
              Maintenance
            </span>
            <div className="text-xl font-black text-amber-600">{maintenanceItems}</div>
            <span className="text-[10px] text-muted font-bold group-hover:text-amber-600 transition-colors flex items-center gap-0.5 mt-0.5">
              <span>In service</span> <ArrowUpRight size={10} />
            </span>
          </div>
        </div>

        {/* My Assigned Assets Strip */}
        <div className="mb-5">
          <div className="flex items-center justify-between mb-2">
            <span className="text-[10px] font-black uppercase tracking-wider text-muted flex items-center gap-1.5">
              <Laptop size={12} className="text-primary" />
              <span>My Assigned Devices ({myAssignedCount})</span>
            </span>
            {myAssignedCount > 0 && (
              <span className="text-[10px] font-bold text-primary hover:underline cursor-pointer" onClick={() => navigate('/inventory')}>
                Manage
              </span>
            )}
          </div>

          {myAssignedAssets.length > 0 ? (
            <div className="space-y-2">
              {myAssignedAssets.map((asset) => (
                <div
                  key={`asset-${asset.id}`}
                  onClick={() => navigate('/inventory')}
                  className="p-3 rounded-2xl bg-surface-subtle border border-border-subtle hover:border-primary/30 transition-all flex items-center justify-between cursor-pointer">
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-xl bg-primary/10 text-primary flex items-center justify-center font-black text-xs">
                      <Cpu size={18} />
                    </div>
                    <div>
                      <h4 className="text-xs font-black text-foreground">{asset.name}</h4>
                      <p className="text-[10px] text-muted font-medium">
                        {asset.assetId} · Serial: {asset.serialNumber || 'N/A'}
                      </p>
                    </div>
                  </div>
                  <span className="text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200">
                    {asset.conditionStatus || 'Good'}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <div className="p-4 rounded-2xl bg-surface-subtle/60 border border-border-subtle text-center">
              <p className="text-xs text-muted font-medium">No company assets currently assigned to your account.</p>
            </div>
          )}
        </div>

        {/* Barcode/QR Recent Scan History */}
        <div className="p-4 rounded-2xl bg-surface-subtle/80 border border-border-subtle">
          <div className="flex items-center justify-between mb-2">
            <span className="text-[10px] font-black uppercase tracking-wider text-muted flex items-center gap-1.5">
              <Barcode size={14} className="text-primary" />
              <span>Latest Barcode / QR Scan Activity</span>
            </span>
            {recentScan && (
              <span className="text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200">
                VERIFIED
              </span>
            )}
          </div>

          {recentScan ? (
            <div className="flex items-center justify-between">
              <div>
                <h5 className="text-xs font-black text-foreground">{recentScan.itemName}</h5>
                <p className="text-[11px] text-muted font-medium mt-0.5">
                  Asset ID: <span className="font-bold text-foreground">{recentScan.assetId || 'ID #' + recentScan.itemId}</span> · Scanned by {recentScan.userName}
                </p>
                <span className="text-[10px] text-muted/70 block mt-0.5">
                  {new Date(recentScan.timestamp).toLocaleString('en-US', {
                    month: 'short',
                    day: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit',
                  })}
                </span>
              </div>
              <button
                onClick={() => navigate('/inventory')}
                className="p-2 rounded-xl bg-surface-elevated border border-border-subtle hover:border-primary/40 text-muted hover:text-primary transition-colors cursor-pointer"
                title="View in inventory">
                <ArrowUpRight size={14} />
              </button>
            </div>
          ) : (
            <div className="flex items-center justify-between text-xs text-muted">
              <span>No recent asset scans logged in the database yet.</span>
              <button
                onClick={() => setShowScanModal(true)}
                className="text-primary font-bold text-[10px] uppercase tracking-wider hover:underline cursor-pointer">
                Scan Now
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Footer */}
      <div className="mt-5 pt-4 border-t border-border-subtle flex items-center justify-between text-[11px] text-muted">
        <span className="font-medium">
          {lowStockItems > 0 ? (
            <span className="text-amber-600 font-bold flex items-center gap-1">
              <AlertTriangle size={12} /> {lowStockItems} items require restocking
            </span>
          ) : (
            'Inventory stock records synced'
          )}
        </span>
        <button
          onClick={() => navigate('/inventory')}
          className="text-primary hover:underline font-black text-[10px] uppercase tracking-wider cursor-pointer flex items-center gap-1">
          <span>Go to Inventory</span>
          <ArrowUpRight size={12} />
        </button>
      </div>

      {/* Quick Barcode/QR Verification Modal */}
      <AnimatePresence>
        {showScanModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-xs">
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className="w-full max-w-md bg-surface-elevated rounded-3xl p-6 border border-border-subtle shadow-2xl relative">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-2">
                  <div className="w-9 h-9 rounded-xl bg-primary/10 text-primary flex items-center justify-center">
                    <QrCode size={18} />
                  </div>
                  <div>
                    <h3 className="text-lg font-black text-foreground">Verify Asset / Barcode</h3>
                    <p className="text-[11px] text-muted">Records verified scan in inventory audit trail</p>
                  </div>
                </div>
                <button
                  onClick={() => setShowScanModal(false)}
                  className="w-8 h-8 rounded-full bg-surface-subtle flex items-center justify-center text-muted hover:text-foreground cursor-pointer">
                  <X size={16} />
                </button>
              </div>

              <div className="space-y-4 my-4">
                <div>
                  <label className="text-[11px] font-black uppercase tracking-wider text-muted block mb-1.5">
                    Select Asset to Verify
                  </label>
                  <select
                    value={selectedItemId || ''}
                    onChange={(e) => setSelectedItemId(Number(e.target.value))}
                    className="w-full px-3.5 py-2.5 rounded-2xl bg-surface-subtle border border-border-subtle text-xs font-bold text-foreground outline-none focus:border-primary">
                    <option value="">-- Choose an item from database --</option>
                    {inventoryData?.items?.map((item) => (
                      <option key={item.id} value={item.id}>
                        {item.name} ({item.asset_id || '#' + item.id}) - {item.status}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="text-[11px] font-black uppercase tracking-wider text-muted block mb-1.5">
                    Scan Location
                  </label>
                  <input
                    type="text"
                    value={scanLocation}
                    onChange={(e) => setScanLocation(e.target.value)}
                    className="w-full px-3.5 py-2 rounded-2xl bg-surface-subtle border border-border-subtle text-xs font-bold text-foreground outline-none focus:border-primary"
                    placeholder="e.g. HQ - 2nd Floor Workshop"
                  />
                </div>
              </div>

              <div className="flex items-center justify-end gap-3 mt-6 pt-4 border-t border-border-subtle">
                <button
                  onClick={() => setShowScanModal(false)}
                  className="px-4 py-2 rounded-2xl bg-surface-subtle text-muted text-xs font-bold hover:text-foreground cursor-pointer">
                  Cancel
                </button>
                <button
                  onClick={handlePerformScan}
                  disabled={isScanning || !selectedItemId}
                  className="px-5 py-2 rounded-2xl bg-primary text-white text-xs font-black uppercase tracking-wider hover:bg-primary-hover disabled:opacity-50 cursor-pointer shadow-sm">
                  {isScanning ? 'Recording Scan...' : 'Record Verified Scan'}
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

import React from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  LogIn,
  LogOut,
  Calendar,
  Home,
  FileText,
  Package,
} from 'lucide-react';
import { useCheckInMutation, useCheckOutMutation } from '@/store/api/attendanceSlice';
import { showToast } from '@/components/ui/composed/Toast.utils';
import { broadcastSync } from '@/services/syncService';

interface QuickActionsBarProps {
  isCheckedIn: boolean;
  onOpenScanModal?: () => void;
}

export const QuickActionsBar: React.FC<QuickActionsBarProps> = ({ isCheckedIn, onOpenScanModal }) => {
  const navigate = useNavigate();
  const [checkIn, { isLoading: isCheckingIn }] = useCheckInMutation();
  const [checkOut, { isLoading: isCheckingOut }] = useCheckOutMutation();

  const handleToggleAttendance = async () => {
    try {
      if (isCheckedIn) {
        await checkOut().unwrap();
        showToast.success('Successfully checked out');
      } else {
        await checkIn({ work_mode: 'office' }).unwrap();
        showToast.success('Successfully checked in');
      }
      broadcastSync('attendance');
    } catch (err: any) {
      showToast.error(err?.data?.message || 'Attendance action failed');
    }
  };

  const actions = [
    {
      id: 'attendance',
      label: isCheckedIn ? 'Check Out' : 'Check In',
      subtitle: isCheckedIn ? 'End Shift' : 'Punch Now',
      icon: isCheckedIn ? LogOut : LogIn,
      onClick: handleToggleAttendance,
      isLoading: isCheckingIn || isCheckingOut,
      primary: true,
      color: isCheckedIn ? 'bg-amber-500 hover:bg-amber-600' : 'bg-primary hover:bg-primary-hover',
    },
    {
      id: 'leave',
      label: 'Apply for Leave',
      subtitle: 'Day Off / Sick',
      icon: Calendar,
      onClick: () => navigate('/calendar'),
      color: 'bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-foreground',
    },
    {
      id: 'wfh',
      label: 'Request WFH',
      subtitle: 'Remote Work',
      icon: Home,
      onClick: () => navigate('/calendar'),
      color: 'bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-foreground',
    },
    {
      id: 'payslip',
      label: 'View Payslips',
      subtitle: 'Salary & Taxes',
      icon: FileText,
      onClick: () => navigate('/finance/my-payslip'),
      color: 'bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-foreground',
    },
    {
      id: 'calendar',
      label: 'Events & Meet',
      subtitle: 'All Schedules',
      icon: Calendar,
      onClick: () => navigate('/events'),
      color: 'bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-foreground',
    },
    {
      id: 'inventory',
      label: 'Inventory & Assets',
      subtitle: 'Scan & Track',
      icon: Package,
      onClick: onOpenScanModal || (() => navigate('/inventory')),
      color: 'bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-foreground',
    },
  ];

  return (
    <div className="mb-8">
      <div className="flex items-center gap-2 mb-3">
        <span className="text-[10px] font-black uppercase tracking-[0.25em] text-muted">
          Quick Workflow Actions
        </span>
        <div className="h-px bg-border-subtle flex-1" />
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
        {actions.map((act) => (
          <motion.button
            key={act.id}
            whileHover={{ y: -3 }}
            whileTap={{ scale: 0.98 }}
            onClick={act.onClick}
            disabled={act.isLoading}
            className={`p-4 rounded-2xl flex flex-col items-start justify-between min-h-[92px] transition-all cursor-pointer shadow-soft group ${
              act.primary ? `${act.color} text-white` : `${act.color}`
            }`}>
            <div className="flex items-center justify-between w-full">
              <div
                className={`w-8 h-8 rounded-xl flex items-center justify-center ${
                  act.primary ? 'bg-white/20 text-white' : 'bg-surface-subtle text-primary group-hover:scale-110 transition-transform'
                }`}>
                <act.icon size={16} />
              </div>
              <span className={`text-[9px] font-bold ${act.primary ? 'text-white/80' : 'text-muted'}`}>
                {act.subtitle}
              </span>
            </div>

            <div className="mt-3 text-left">
              <span className="text-xs font-black tracking-tight block">
                {act.isLoading ? 'Processing...' : act.label}
              </span>
            </div>
          </motion.button>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  Clock,
  Flame,
  CalendarCheck,
  CalendarDays,
  FileCheck2,
  Calendar,
  Home,
  Package,
  ArrowUpRight,
  LogIn,
  LogOut,
} from 'lucide-react';
import type { DashboardSummaryData } from '@/types/dashboard';
import { useCheckInMutation, useCheckOutMutation } from '@/store/api/attendanceSlice';
import { showToast } from '@/components/ui/composed/Toast.utils';
import { broadcastSync } from '@/services/syncService';

interface TopKpiCardsProps {
  data: DashboardSummaryData | null;
  isLoading: boolean;
}

export const TopKpiCards: React.FC<TopKpiCardsProps> = ({ data, isLoading }) => {
  const navigate = useNavigate();
  const [checkIn, { isLoading: isCheckingIn }] = useCheckInMutation();
  const [checkOut, { isLoading: isCheckingOut }] = useCheckOutMutation();

  const handleQuickCheckIn = async (e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      await checkIn({ work_mode: 'office' }).unwrap();
      showToast.success('Checked in successfully!');
      broadcastSync('attendance');
    } catch (err: any) {
      showToast.error(err?.data?.message || 'Check-in failed');
    }
  };

  const handleQuickCheckOut = async (e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      await checkOut().unwrap();
      showToast.success('Checked out successfully!');
      broadcastSync('attendance');
    } catch (err: any) {
      showToast.error(err?.data?.message || 'Check-out failed');
    }
  };

  if (isLoading || !data) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-5">
        {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
          <div
            key={i}
            className="h-32 rounded-2xl bg-surface-elevated border border-border-subtle p-4 animate-pulse flex flex-col justify-between shadow-soft">
            <div className="flex items-center justify-between">
              <div className="w-9 h-9 rounded-xl bg-surface-subtle" />
              <div className="w-16 h-3.5 rounded-full bg-surface-subtle" />
            </div>
            <div>
              <div className="w-24 h-5 rounded-lg bg-surface-subtle mb-1.5" />
              <div className="w-32 h-3 rounded-md bg-surface-subtle" />
            </div>
          </div>
        ))}
      </div>
    );
  }

  const { attendance, payroll, calendarAndLeave, inventory } = data;
  const isCheckedIn = attendance.todayStatus === 'checked-in';
  const isCheckedOut = attendance.todayStatus === 'checked-out';

  // Format check-in/out times
  const checkInTimeStr = attendance.todayRecord?.checkInTime
    ? new Date(attendance.todayRecord.checkInTime).toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        hour12: true,
      })
    : null;

  const checkOutTimeStr = attendance.todayRecord?.checkOutTime
    ? new Date(attendance.todayRecord.checkOutTime).toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        hour12: true,
      })
    : null;

  const nextSalarySchedule = payroll.nextSalarySchedule;
  const payslip = payroll.currentMonthPayslip;

  // WFH details
  const isTodayWfh = attendance.todayRecord?.workMode === 'wfh' || calendarAndLeave.wfhStats?.isTodayWfh;
  const wfhDaysMonth = calendarAndLeave.wfhStats?.approvedWfhDaysThisMonth ?? 0;
  const pendingWfhLeaves = calendarAndLeave.myUpcomingLeaves.filter(
    (l) => l.type === 'Work from home' && l.status === 'Pending'
  );
  const upcomingApprovedWfh = calendarAndLeave.myUpcomingLeaves.filter(
    (l) => l.type === 'Work from home' && l.status === 'Approved'
  );

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-5">
      {/* 1. Today's Attendance Status */}
      <motion.div
        whileHover={{ y: -3 }}
        transition={{ duration: 0.15 }}
        onClick={() => navigate('/checkin')}
        className="group relative bg-surface-elevated rounded-2xl p-4 border border-border-subtle shadow-soft hover:shadow-md hover:border-primary/30 transition-all cursor-pointer flex flex-col justify-between overflow-hidden min-h-[145px]">
        <div className="flex items-start justify-between">
          <div
            className={`w-9 h-9 rounded-xl flex items-center justify-center transition-colors ${
              isCheckedIn
                ? 'bg-emerald-500/10 text-emerald-600'
                : isCheckedOut
                  ? 'bg-blue-500/10 text-blue-600'
                  : 'bg-amber-500/10 text-amber-600'
            }`}>
            <Clock size={18} />
          </div>
          <span
            className={`text-[8.5px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full border ${
              isCheckedIn
                ? 'bg-emerald-50 text-emerald-700 border-emerald-200'
                : isCheckedOut
                  ? 'bg-blue-50 text-blue-700 border-blue-200'
                  : 'bg-amber-50 text-amber-700 border-amber-200'
            }`}>
            {isCheckedIn ? 'ACTIVE' : isCheckedOut ? 'COMPLETED' : 'OFFLINE'}
          </span>
        </div>

        <div className="mt-2.5">
          <span className="text-[9.5px] font-black text-muted uppercase tracking-[0.16em]">
            Today's Attendance
          </span>
          <h3 className="text-lg font-black text-foreground tracking-tight mt-0.5">
            {isCheckedIn ? 'Checked In' : isCheckedOut ? 'Checked Out' : 'Not Checked In'}
          </h3>
          <p className="text-[11px] font-medium text-muted mt-0.5 truncate">
            {checkInTimeStr
              ? `In: ${checkInTimeStr}${checkOutTimeStr ? ` · Out: ${checkOutTimeStr}` : ''}`
              : 'Tap to punch attendance'}
          </p>
        </div>

        {/* Quick Punch Button inside card */}
        <div className="mt-2.5 pt-2 border-t border-border-subtle flex items-center justify-between">
          <span className="text-[9.5px] font-bold text-muted">
            {isTodayWfh ? 'WFH Shift' : 'Office Shift'}
          </span>
          {isCheckedIn ? (
            <button
              onClick={handleQuickCheckOut}
              disabled={isCheckingOut}
              className="px-2.5 py-0.5 rounded-lg bg-amber-500 hover:bg-amber-600 text-white text-[9.5px] font-black uppercase tracking-wider flex items-center gap-1 transition-colors cursor-pointer">
              <LogOut size={11} />
              <span>{isCheckingOut ? '...' : 'Check Out'}</span>
            </button>
          ) : (
            <button
              onClick={handleQuickCheckIn}
              disabled={isCheckingIn || isCheckedOut}
              className="px-2.5 py-0.5 rounded-lg bg-primary hover:bg-primary-hover text-white text-[9.5px] font-black uppercase tracking-wider flex items-center gap-1 transition-colors cursor-pointer disabled:opacity-50">
              <LogIn size={11} />
              <span>{isCheckingIn ? '...' : isCheckedOut ? 'Punched' : 'Check In'}</span>
            </button>
          )}
        </div>
      </motion.div>

      {/* 2. Attendance Streak */}
      <motion.div
        whileHover={{ y: -3 }}
        transition={{ duration: 0.15 }}
        onClick={() => navigate('/checkin')}
        className="group relative bg-surface-elevated rounded-2xl p-4 border border-border-subtle shadow-soft hover:shadow-md hover:border-primary/30 transition-all cursor-pointer flex flex-col justify-between overflow-hidden min-h-[145px]">
        <div className="flex items-start justify-between">
          <div className="w-9 h-9 rounded-xl bg-orange-500/10 text-orange-600 flex items-center justify-center">
            <Flame size={18} className="animate-pulse" />
          </div>
          <span className="text-[8.5px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full bg-orange-50 text-orange-700 border border-orange-200">
            STREAK
          </span>
        </div>

        <div className="mt-2.5">
          <span className="text-[9.5px] font-black text-muted uppercase tracking-[0.16em]">
            Current Streak
          </span>
          <div className="flex items-baseline gap-1.5 mt-0.5">
            <h3 className="text-xl font-black text-foreground tracking-tight">
              {attendance.currentStreak} {attendance.currentStreak === 1 ? 'Day' : 'Days'}
            </h3>
            <span className="text-[9.5px] font-bold text-emerald-600">active</span>
          </div>
          <p className="text-[11px] font-medium text-muted mt-0.5">
            Longest record: <span className="font-bold text-foreground">{attendance.longestStreak} days</span>
          </p>
        </div>

        <div className="mt-2.5 pt-2 border-t border-border-subtle flex items-center justify-between text-[9.5px]">
          <span className="text-muted font-bold capitalize">{attendance.streakType} streak</span>
          <ArrowUpRight size={13} className="text-muted group-hover:text-primary transition-colors" />
        </div>
      </motion.div>

      {/* 3. Monthly Attendance Summary */}
      <motion.div
        whileHover={{ y: -3 }}
        transition={{ duration: 0.15 }}
        onClick={() => navigate('/checkin')}
        className="group relative bg-surface-elevated rounded-2xl p-4 border border-border-subtle shadow-soft hover:shadow-md hover:border-primary/30 transition-all cursor-pointer flex flex-col justify-between overflow-hidden min-h-[145px]">
        <div className="flex items-start justify-between">
          <div className="w-9 h-9 rounded-xl bg-blue-500/10 text-blue-600 flex items-center justify-center">
            <CalendarCheck size={18} />
          </div>
          <span className="text-[8.5px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full bg-blue-50 text-blue-700 border border-blue-200">
            {attendance.monthlyStats.attendancePercentage}% RATE
          </span>
        </div>

        <div className="mt-2.5">
          <span className="text-[9.5px] font-black text-muted uppercase tracking-[0.16em]">
            Monthly Attendance
          </span>
          <div className="flex items-baseline gap-1.5 mt-0.5">
            <h3 className="text-xl font-black text-foreground tracking-tight">
              {attendance.monthlyStats.totalCheckedInDays} Days
            </h3>
            <span className="text-[9.5px] font-bold text-muted">
              of {attendance.monthlyStats.workingDaysSoFar} working
