            <CalendarDays size={18} />
          </div>
          <span
            className={`text-[8.5px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full border ${
              nextSalarySchedule.status === 'Paid'
                ? 'bg-emerald-50 text-emerald-700 border-emerald-200'
