          </div>
          <p className="text-[11px] font-medium text-muted mt-0.5 truncate">
            {inventory.lowStockItems > 0 ? (
              <span className="text-amber-600 font-bold">
                {inventory.lowStockItems} low stock alert
              </span>
            ) : (
              'All stock levels optimal'
            )}
          </p>
        </div>

        <div className="mt-2.5 pt-2 border-t border-border-subtle flex items-center justify-between text-[9.5px]">
          <span className="text-muted font-bold">Asset Logistics</span>
          <ArrowUpRight size={13} className="text-muted group-hover:text-primary transition-colors" />
        </div>
      </motion.div>
    </div>
  );
};

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  Calendar,
  Clock,
  MapPin,
  Home,
  AlertCircle,
  ArrowUpRight,
  Plane,
} from 'lucide-react';
import type { DashboardCalendarAndLeave } from '@/types/dashboard';

interface UpcomingActivitiesCardProps {
  data: DashboardCalendarAndLeave | null;
  isLoading: boolean;
}

export const UpcomingActivitiesCard: React.FC<UpcomingActivitiesCardProps> = ({ data, isLoading }) => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'all' | 'events' | 'leaves' | 'wfh'>('all');

  if (isLoading || !data) {
    return (
      <div className="bg-surface-elevated rounded-3xl p-7 border border-border-subtle shadow-soft animate-pulse h-full">
        <div className="w-28 h-4 rounded-md bg-surface-subtle mb-3" />
        <div className="w-48 h-7 rounded-xl bg-surface-subtle mb-6" />
        <div className="space-y-3">
          <div className="h-16 rounded-2xl bg-surface-subtle" />
          <div className="h-16 rounded-2xl bg-surface-subtle" />
          <div className="h-16 rounded-2xl bg-surface-subtle" />
        </div>
      </div>
    );
  }

  const { upcomingEvents = [], myUpcomingLeaves = [], pendingLeavesCount = 0, wfhStats } = data;

  // Filter items based on activeTab
  const showEvents = activeTab === 'all' || activeTab === 'events';
  const showLeaves = activeTab === 'all' || activeTab === 'leaves';
  const showWfh = activeTab === 'all' || activeTab === 'wfh';

  const wfhLeaves = myUpcomingLeaves.filter((l) => l.type === 'Work from home');
  const regularLeaves = myUpcomingLeaves.filter((l) => l.type !== 'Work from home');

  const totalActivitiesCount = upcomingEvents.length + myUpcomingLeaves.length;

  return (
    <div className="bg-surface-elevated rounded-3xl p-5 sm:p-6 border border-border-subtle shadow-soft hover:shadow-md transition-all duration-300 flex flex-col justify-between">
      <div>
        {/* Top Header */}
        <div className="flex items-start justify-between mb-3">
          <div>
            <span className="text-[10px] font-black text-primary uppercase tracking-[0.25em]">
              Schedules & Leaves
            </span>
            <h2 className="text-xl font-black text-foreground tracking-tight mt-0.5">
              Events & Schedules
            </h2>
          </div>

          <div className="flex items-center gap-2">
            {pendingLeavesCount > 0 && (
              <span className="px-2.5 py-1 rounded-full bg-amber-50 text-amber-700 border border-amber-200 text-[10px] font-black uppercase tracking-wider flex items-center gap-1">
                <AlertCircle size={11} />
                <span>{pendingLeavesCount} Pending</span>
              </span>
            )}
            <button
              onClick={() => navigate('/events')}
              className="px-3.5 py-1.5 rounded-2xl bg-surface-subtle hover:bg-surface-elevated border border-border-subtle text-[11px] font-black text-foreground uppercase tracking-wider flex items-center gap-1.5 transition-colors cursor-pointer shadow-xs">
              <span>View All</span>
              <ArrowUpRight size={13} className="text-muted" />
            </button>
          </div>
        </div>

        {/* Filter Pills */}
        <div className="flex items-center gap-1.5 p-1 rounded-2xl bg-surface-subtle border border-border-subtle mb-5 overflow-x-auto">
          {[
            { key: 'all', label: `All (${totalActivitiesCount})` },
            { key: 'events', label: `Events (${upcomingEvents.length})` },
            { key: 'leaves', label: `Leaves (${regularLeaves.length})` },
            { key: 'wfh', label: `WFH (${wfhLeaves.length || wfhStats.approvedWfhDaysThisMonth})` },
          ].map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key as any)}
              className={`px-3 py-1.5 rounded-xl text-[11px] font-black tracking-wide transition-all cursor-pointer whitespace-nowrap ${
                activeTab === tab.key
                  ? 'bg-primary text-white shadow-xs'
                  : 'text-muted hover:text-foreground hover:bg-surface-elevated'
              }`}>
              {tab.label}
            </button>
          ))}
        </div>

        {/* Activity List */}
        <div className="space-y-3 max-h-[360px] overflow-y-auto pr-1">
          {/* Empty State */}
          {totalActivitiesCount === 0 && (
            <div className="py-12 flex flex-col items-center justify-center text-center">
              <div className="w-12 h-12 rounded-2xl bg-surface-subtle border border-border-subtle flex items-center justify-center text-muted mb-3">
                <Calendar size={22} />
              </div>
              <h4 className="text-sm font-bold text-foreground">No Upcoming Activities</h4>
              <p className="text-xs text-muted mt-1 max-w-xs">
                There are no scheduled company events, approved leaves, or WFH dates for your account.
              </p>
              <button
                onClick={() => navigate('/calendar')}
                className="mt-4 px-4 py-2 rounded-2xl bg-primary text-white text-[11px] font-black uppercase tracking-wider hover:bg-primary-hover transition-colors shadow-xs cursor-pointer">
                Apply for Leave or WFH
              </button>
            </div>
          )}

          {/* Company Events */}
          {showEvents &&
            upcomingEvents.map((event) => (
              <motion.div
                key={`event-${event.id}`}
                whileHover={{ x: 2 }}
                onClick={() => navigate('/events')}
                className="p-3.5 sm:p-4 rounded-2xl bg-surface-subtle/80 hover:bg-surface-subtle border border-border-subtle hover:border-primary/30 transition-all cursor-pointer flex items-center justify-between gap-4 group">
                <div className="flex items-center gap-3 min-w-0">
                  <div className="w-11 h-11 rounded-2xl bg-primary/10 text-primary flex flex-col items-center justify-center shrink-0 border border-primary/20">
                    <span className="text-[9px] font-black uppercase leading-none">
                      {new Date(event.eventDate).toLocaleDateString('en-US', { month: 'short' })}
                    </span>
                    <span className="text-sm font-black leading-none mt-0.5">
                      {new Date(event.eventDate).getDate()}
                    </span>
                  </div>

                  <div className="min-w-0">
                    <div className="flex items-center gap-2 mb-0.5">
                      <span className="text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full bg-primary/10 text-primary border border-primary/20">
                        {event.category || 'Event'}
                      </span>
                      {event.time && (
                        <span className="text-[10px] text-muted font-medium flex items-center gap-1">
                          <Clock size={10} /> {event.time}
                        </span>
                      )}
                    </div>
                    <h4 className="text-xs font-black text-foreground truncate group-hover:text-primary transition-colors">
                      {event.title}
                    </h4>
                    {event.location && (
                      <p className="text-[10px] text-muted flex items-center gap-1 truncate mt-0.5">
                        <MapPin size={10} /> {event.location}
                      </p>
                    )}
                  </div>
                </div>

                <div className="shrink-0 flex items-center gap-1">
                  <span className="text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200">
                    {event.status || 'Upcoming'}
                  </span>
                  <ArrowUpRight size={14} className="text-muted group-hover:text-primary transition-colors" />
                </div>
              </motion.div>
            ))}

          {/* Leaves */}
          {showLeaves &&
            regularLeaves.map((leave) => (
              <motion.div
                key={`leave-${leave.id}`}
                whileHover={{ x: 2 }}
                onClick={() => navigate('/calendar')}
                className="p-3.5 sm:p-4 rounded-2xl bg-surface-subtle/80 hover:bg-surface-subtle border border-border-subtle hover:border-amber-300 transition-all cursor-pointer flex items-center justify-between gap-4 group">
                <div className="flex items-center gap-3 min-w-0">
                  <div className="w-11 h-11 rounded-2xl bg-amber-500/10 text-amber-600 flex items-center justify-center shrink-0 border border-amber-500/20">
                    <Plane size={18} />
                  </div>

                  <div className="min-w-0">
                    <div className="flex items-center gap-2 mb-0.5">
                      <span className="text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full bg-amber-50 text-amber-700 border border-amber-200">
                        {leave.type}
                      </span>
                      <span className="text-[10px] text-muted font-medium">
                        {leave.startDate} to {leave.endDate}
                      </span>
                    </div>
                    <h4 className="text-xs font-black text-foreground truncate group-hover:text-amber-600 transition-colors">
                      {leave.reason || 'Leave requested'}
                    </h4>
                  </div>
                </div>

                <div className="shrink-0 flex items-center gap-1">
                  <span
                    className={`text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full border ${
                      leave.status === 'Approved'
                        ? 'bg-emerald-50 text-emerald-700 border-emerald-200'
                        : leave.status === 'Rejected'
                          ? 'bg-red-50 text-red-700 border-red-200'
                          : 'bg-amber-50 text-amber-700 border-amber-200'
                    }`}>
                    {leave.status}
                  </span>
                  <ArrowUpRight size={14} className="text-muted group-hover:text-amber-600 transition-colors" />
                </div>
              </motion.div>
            ))}

          {/* WFH Items */}
          {showWfh &&
            wfhLeaves.map((wfh) => (
              <motion.div
                key={`wfh-${wfh.id}`}
                whileHover={{ x: 2 }}
                onClick={() => navigate('/calendar')}
                className="p-3.5 sm:p-4 rounded-2xl bg-surface-subtle/80 hover:bg-surface-subtle border border-border-subtle hover:border-teal-300 transition-all cursor-pointer flex items-center justify-between gap-4 group">
                <div className="flex items-center gap-3 min-w-0">
                  <div className="w-11 h-11 rounded-2xl bg-teal-500/10 text-teal-600 flex items-center justify-center shrink-0 border border-teal-500/20">
                    <Home size={18} />
                  </div>

                  <div className="min-w-0">
                    <div className="flex items-center gap-2 mb-0.5">
                      <span className="text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full bg-teal-50 text-teal-700 border border-teal-200">
                        Work From Home
                      </span>
                      <span className="text-[10px] text-muted font-medium">
                        {wfh.startDate} to {wfh.endDate}
                      </span>
                    </div>
                    <h4 className="text-xs font-black text-foreground truncate group-hover:text-teal-600 transition-colors">
                      {wfh.reason || 'Remote work arrangement'}
                    </h4>
                  </div>
                </div>

                <div className="shrink-0 flex items-center gap-1">
                  <span
                    className={`text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full border ${
                      wfh.status === 'Approved'
                        ? 'bg-emerald-50 text-emerald-700 border-emerald-200'
                        : 'bg-amber-50 text-amber-700 border-amber-200'
                    }`}>
                    {wfh.status}
                  </span>
                  <ArrowUpRight size={14} className="text-muted group-hover:text-teal-600 transition-colors" />
                </div>
              </motion.div>
            ))}
        </div>
      </div>

      {/* Card Footer Quick Links */}
      <div className="mt-5 pt-4 border-t border-border-subtle flex items-center justify-between">
        <button
          onClick={() => navigate('/calendar')}
          className="text-[11px] font-bold text-muted hover:text-foreground flex items-center gap-1.5 transition-colors cursor-pointer">
          <Calendar size={13} />
          <span>Apply Leave / WFH</span>
        </button>
        <button
          onClick={() => navigate('/events')}
          className="text-[11px] font-black text-primary hover:underline flex items-center gap-1 cursor-pointer">
          <span>Full Event Schedule →</span>
        </button>
      </div>
    </div>
  );
};

import { useState, useEffect } from 'react';
import { useGetProjectsQuery } from '@/store/api/projectSlice';
import { useGetTasksQuery } from '@/store/api/taskSlice';
import { useGetReimbursementsQuery } from '@/store/api/financeApiSlice';
import { useGetUsersQuery } from '@/store/api/userSlice';
import { useGetDashboardSummaryQuery } from '@/store/api/dashboardSlice';

const PRESET_COLORS = ['#e8583a', '#3B82F6', '#6366F1', '#9747ff', '#34d399', '#fb7185', '#06B6D4'];

export const useDashboardData = () => {
  const {
    data: summary,
    isLoading: isLoadingSummary,
    isFetching: isFetchingSummary,
    isError: isSummaryError,
    refetch: refetchSummary,
  } = useGetDashboardSummaryQuery(undefined, {
    pollingInterval: 30000, // Background revalidation every 30s
  });

  const { data: rawProjects, isLoading: isLoadingProjects } = useGetProjectsQuery();
  const { data: rawTasks, isLoading: isLoadingTasks } = useGetTasksQuery();
  const { data: rawReimbursements } = useGetReimbursementsQuery();
  const { data: rawUsers } = useGetUsersQuery();

  const [lastSyncedTime, setLastSyncedTime] = useState<string>('Just now');

  useEffect(() => {
    if (summary) {
      setLastSyncedTime(
        new Date().toLocaleTimeString('en-US', {
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit',
        })
      );
    }
  }, [summary]);

  // Projects strictly from database
  const projects = Array.isArray(rawProjects)
    ? (rawProjects as any[]).map((p: any, idx: number) => {
        const pId = p?.id || p?.project_id || idx + 1;
        const matchingTasks = Array.isArray(rawTasks)
          ? (rawTasks as any[]).filter((t: any) => String(t?.project_id) === String(pId))
          : [];

        return {
          id: String(pId),
          title: p?.title || p?.project_name || p?.name || `Project #${pId}`,
          tasks: matchingTasks.length,
          value: p?.value || p?.project_status || p?.status || 'Active',
          color: p?.color || PRESET_COLORS[idx % PRESET_COLORS.length],
          category: (p?.category || p?.project_status || p?.status || 'Enterprise').toUpperCase(),
          participants: p?.participants || (Array.isArray(rawUsers) ? Math.min(rawUsers.length, 6) : 0),
          startDate: p?.startDate || p?.start_date,
          endDate: p?.endDate || p?.end_date,
          status: p?.status || p?.project_status || 'Active',
          progress: p?.progress ?? 0,
        };
      })
    : [];

  // Live real task metrics
  const totalTasksCount = Array.isArray(rawTasks) ? rawTasks.length : summary?.projects?.totalTasks || 0;
  const completedTasksCount = Array.isArray(rawTasks)
    ? rawTasks.filter((t) => t?.task_status === 'Completed').length
    : summary?.projects?.completedTasks || 0;
  const taskCompletionRate = totalTasksCount > 0 ? Math.round((completedTasksCount / totalTasksCount) * 100) : 0;

  // Real financial claims
  const totalReimbursementAmount = Array.isArray(rawReimbursements)
    ? rawReimbursements.reduce((sum, r) => sum + (Number(r?.amount) || 0), 0)
    : 0;

  const totalUsersCount = Array.isArray(rawUsers) ? rawUsers.length : 0;
  const isCheckedIn = summary?.attendance?.todayStatus === 'checked-in';

  const stats = {
    averageValue: `₹ ${Math.round(totalReimbursementAmount).toLocaleString('en-IN')}`,
    valueVsLy: `${totalReimbursementAmount > 0 ? '₹ ' + totalReimbursementAmount.toLocaleString('en-IN') : 'No Claims'}`,
    averageTasks: projects.length > 0 ? Math.round((totalTasksCount / projects.length) * 10) / 10 : 0,
    tasksVsLy: `${taskCompletionRate}% DONE`,
    totalProjects: projects.length,
    completedTasks: completedTasksCount,
    totalTasks: totalTasksCount,
    totalUsers: totalUsersCount,
    isCheckedIn,
    attendanceStats: summary?.attendance || null,
  };

  const handleRefreshAll = () => {
    refetchSummary();
  };

  return {
    summary,
    projects,
    tasks: Array.isArray(rawTasks) ? rawTasks : [],
    stats,
    isLoading: isLoadingSummary || isLoadingProjects || isLoadingTasks,
    isFetching: isFetchingSummary,
    isError: isSummaryError,
    lastSyncedTime,
    handleRefreshAll,
    liveCounts: {
      projects: projects.length,
      tasks: totalTasksCount,
      reimbursements: Array.isArray(rawReimbursements) ? rawReimbursements.length : 0,
      users: totalUsersCount,
      isCheckedIn,
    },
  };
};

import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import {
  User,
  CreditCard,
  Shield,
  Briefcase,
  GraduationCap,
  Award,
  Camera,
  ChevronRight,
  ChevronLeft,
  Send,
  CheckCircle2,
  AlertCircle,
  Clock,
  FileText,
  X,
  Check,
} from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { usePersistedTab } from '@/hooks/usePersistedTab';
import { showToast } from '@/components/ui/composed/Toast.utils';
import {
  getEmployeeProfile,
  saveEmployeeProfile,
  updateProfileSection,
  submitProfileForReview,
  getFormConfiguration,
  calculateCompletionPercentage,
  getIncompleteRequiredSections,
  isSectionValidAndComplete,
  syncProfilesFromBackend,
  type ProfileCompletionData,
  type ProfileStatus,
  type FormSectionConfig,
} from '@/services/employeeProfileService';
import {
  saveFormDraft,
  getFormDraft,
  clearFormDraft,
} from '@/utils/formDraftManager';
import { SmartAlertBanner } from '@/components/common/SmartAlertBanner';
import { AutosaveStatusBadge, type AutosaveStatus } from '@/components/common/AutosaveStatusBadge';

import { PersonalDetailsSection } from './components/PersonalDetailsSection';
import { BankDetailsSection } from './components/BankDetailsSection';
import { IdentityDocumentsSection } from './components/IdentityDocumentsSection';
import { PreviousEmploymentSection } from './components/PreviousEmploymentSection';
import { EducationSection } from './components/EducationSection';
import { CertificationsSection } from './components/CertificationsSection';
import { ProfilePictureSection } from './components/ProfilePictureSection';

const SECTION_ICONS: Record<string, any> = {
  personal: User,
  bank: CreditCard,
  identity: Shield,
  employment: Briefcase,
  education: GraduationCap,
  certifications: Award,
  profile_picture: Camera,
};

const STATUS_CONFIG: Record<
  ProfileStatus,
  { label: string; color: string; bg: string; icon: any }
> = {
  incomplete: {
    label: 'Incomplete',
    color: 'text-error',
    bg: 'bg-error/10 border-error/20',
    icon: AlertCircle,
  },
  in_progress: {
    label: 'In Progress',
    color: 'text-warning',
    bg: 'bg-warning/10 border-warning/20',
    icon: Clock,
  },
  submitted: {
    label: 'Submitted for Review',
    color: 'text-info',
    bg: 'bg-info/10 border-info/20',
    icon: Send,
  },
  changes_required: {
    label: 'Changes Required',
    color: 'text-warning',
    bg: 'bg-warning/10 border-warning/20',
    icon: AlertCircle,
  },
  approved: {
    label: 'Approved',
    color: 'text-success',
    bg: 'bg-success/10 border-success/20',
    icon: CheckCircle2,
  },
  id_assigned: {
    label: 'Employee ID Assigned',
    color: 'text-success',
    bg: 'bg-success/10 border-success/20',
    icon: CheckCircle2,
  },
};

interface EmployeeProfileCompletionProps {
  onClose?: () => void;
  fullPage?: boolean;
}

export default function EmployeeProfileCompletion({
  onClose,
  fullPage = false,
}: EmployeeProfileCompletionProps) {
  const { user } = useAuth();
  const navigate = useNavigate();

  // 1. Tab Persistence across refresh and direct links
  const [activeSection, setActiveSection] = usePersistedTab<string>({
    paramName: 'section',
    defaultTab: 'personal',
    storageKey: 'aether_profile_completion_active_section',
  });

  const [profile, setProfile] = useState<ProfileCompletionData | null>(null);
  const [formConfig, setFormConfig] = useState<FormSectionConfig[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // 2. Draft & Autosave State
  const [isCurrentSectionDirty, setIsCurrentSectionDirty] = useState(false);
  const [hasRestoredDraft, setHasRestoredDraft] = useState(false);
  const [autosaveStatus, setAutosaveStatus] = useState<AutosaveStatus>('idle');
  const [lastSavedTimestamp, setLastSavedTimestamp] = useState<string | null>(null);
  const [sectionRefreshKey, setSectionRefreshKey] = useState(0);

  // Autosave debounce timer ref
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Load profile and form configuration
  useEffect(() => {
    if (!user) return;
    const config = getFormConfiguration();
    setFormConfig(config);

    const savedProfile =
      (user.email ? getEmployeeProfile(user.email) : null) ?? getEmployeeProfile(user.id);

    if (savedProfile) {
      setProfile(savedProfile);
    } else {
      const newProfile: ProfileCompletionData = {
        userId: user.id,
        userEmail: user.email,
        status: user.employee_id || user.employee_code ? 'id_assigned' : 'incomplete',
        employeeId: user.employee_id || user.employee_code,
        lastSavedAt: new Date().toISOString(),
        completedSections: {},
        personal: {
          fullName: user.username || '',
          contactNumber: user.contact_number || '',
          email: user.email,
          currentAddress: '',
          permanentAddress: '',
        },
      };
      setProfile(newProfile);
      saveEmployeeProfile(newProfile);
    }

    syncProfilesFromBackend().then(() => {
      const fresh =
        (user.email ? getEmployeeProfile(user.email) : null) ?? getEmployeeProfile(user.id);
      if (fresh) setProfile(fresh);
    });
  }, [user]);

  // Check for restored draft when active section changes
  useEffect(() => {
    if (!user) return;
    const draft = getFormDraft(user.id, activeSection);
    if (draft && draft.data) {
      setHasRestoredDraft(true);
      setIsCurrentSectionDirty(true);
      setAutosaveStatus('restored');
      setLastSavedTimestamp(new Date(draft.timestamp).toISOString());
    } else {
      setHasRestoredDraft(false);
      setIsCurrentSectionDirty(false);
      setAutosaveStatus('idle');
    }
  }, [user, activeSection, sectionRefreshKey]);

  const completionPercentage = useMemo(
    () => calculateCompletionPercentage(profile, formConfig),
    [profile, formConfig]
  );

  const incompleteSections = useMemo(
    () => getIncompleteRequiredSections(profile, formConfig),
    [profile, formConfig]
  );

  const activeSections = useMemo(() => formConfig.filter((s) => !s.hidden), [formConfig]);
  const activeIdx = activeSections.findIndex((s) => s.id === activeSection);

  // Resolves effective section data: draft takes precedence over saved profile
  const getEffectiveSectionData = useCallback(
    (sectionId: string) => {
      if (!user) return null;
      const draft = getFormDraft(user.id, sectionId);
      if (draft && draft.data) {
        return draft.data;
      }
      return profile ? (profile as any)[sectionId] : null;
    },
    [user, profile, sectionRefreshKey]
  );

  // Debounced draft autosave and parent state synchronization (prevents typing lag)
  const handleDraftChange = useCallback(
    (sectionId: string, _data: any, isDirty: boolean) => {
      if (!user) return;
      setIsCurrentSectionDirty(isDirty);

      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
      }

      if (isDirty) {
        setAutosaveStatus('saving');
      }

      // Debounce updating parent profile & saving draft by 250ms so typing remains 100% fluid (60fps)
      debounceTimerRef.current = setTimeout(() => {
        setProfile((prev) => {
          if (!prev) return prev;
          const candidate = {
            ...prev,
            [sectionId]: _data,
          };
          const isValid = isSectionValidAndComplete(sectionId, candidate);
          return {
            ...candidate,
            completedSections: {
              ...prev.completedSections,
              [sectionId]: isValid,
            },
          };
        });

        if (isDirty) {
          saveFormDraft(user.id, sectionId, _data);
          setAutosaveStatus('saved');
          setLastSavedTimestamp(new Date().toISOString());
        } else {
          setAutosaveStatus('idle');
        }
      }, 250);
    },
    [user]
  );

  // Explicit Save as Draft button action (no popups)
  const handleSaveDraft = useCallback(
    (data: any) => {
      if (!user) return;
      saveFormDraft(user.id, activeSection, data);
      setIsCurrentSectionDirty(false);
      setHasRestoredDraft(false);
      setAutosaveStatus('saved');
      setLastSavedTimestamp(new Date().toISOString());
      showToast({
        severity: 'success',
        summary: 'Draft Saved',
        detail: 'Your entries have been saved as draft. You can continue anytime.',
        life: 2500,
      });
    },
    [user, activeSection]
  );

  // Discard draft action
  const handleDiscardDraft = useCallback(() => {
    if (!user) return;
    clearFormDraft(user.id, activeSection);
    setHasRestoredDraft(false);
    setIsCurrentSectionDirty(false);
    setAutosaveStatus('idle');
    setSectionRefreshKey((k) => k + 1);
    showToast({
      severity: 'info',
      summary: 'Draft Discarded',
      detail: 'Restored original saved profile data.',
      life: 2500,
    });
  }, [user, activeSection]);

  // Tab switch without interrupting confirmation popups
  const handleSectionSwitch = useCallback(
    (targetSectionId: string) => {
      if (targetSectionId === activeSection) return;
      setActiveSection(targetSectionId);
    },
    [activeSection, setActiveSection]
  );

  const handleSaveSection = useCallback(
    async (sectionId: string, data: any) => {
      if (!user || !profile) return;
      setIsSaving(true);
      try {
        updateProfileSection(
          user.id,
          user.email,
          sectionId as keyof ProfileCompletionData,
          data,
          sectionId,
          user.username || user.email
        );

        // Clear draft on successful persistent save
        clearFormDraft(user.id, sectionId);
        setIsCurrentSectionDirty(false);
        setHasRestoredDraft(false);
        setAutosaveStatus('saved');
        setLastSavedTimestamp(new Date().toISOString());

        const updated = getEmployeeProfile(user.id);
        setProfile(updated);

        const updatedPct = calculateCompletionPercentage(updated, formConfig);
        window.dispatchEvent(new CustomEvent('aether_employee_profiles_updated'));

        if (updatedPct >= 100) {
          showToast({
            severity: 'success',
            summary: 'Profile 100% Complete!',
            detail: 'All required sections are verified and saved.',
            life: 3000,
          });
        } else {
          showToast({
            severity: 'success',
            summary: 'Saved Successfully',
            detail: 'Section saved! Moving to the next step.',
            life: 2500,
          });
        }

        // Advance to next section automatically
        const currentIndex = activeSections.findIndex((s) => s.id === sectionId);
        if (currentIndex >= 0 && currentIndex < activeSections.length - 1) {
          setActiveSection(activeSections[currentIndex + 1].id);
        }
      } catch {
        setAutosaveStatus('error');
        showToast({
          severity: 'error',
          summary: 'Save Failed',
          detail: 'Could not save section. Please try again.',
          life: 3000,
        });
      } finally {
        setIsSaving(false);
      }
    },
    [user, profile, activeSections, formConfig, setActiveSection]
  );

  const handleSubmit = useCallback(async () => {
    if (!user || !profile) return;

    if (!profile.personal?.fullName?.trim()) {
      showToast({
        severity: 'warn',
        summary: 'Personal Details Required',
        detail: 'Please provide your full name before submitting.',
        life: 3500,
      });
      setActiveSection('personal');
      return;
    }

    setIsSubmitting(true);
    try {
      if (profile.status === 'id_assigned' || profile.status === 'approved') {
        saveEmployeeProfile(profile);
        window.dispatchEvent(new CustomEvent('aether_employee_profiles_updated'));
        const updatedPct = calculateCompletionPercentage(profile, formConfig);

        if (updatedPct >= 100) {
          showToast({
            severity: 'success',
            summary: 'Profile 100% Complete!',
            detail: 'Your profile updates have been saved. Redirecting to Profile...',
            life: 3500,
          });
          setTimeout(() => {
            if (onClose) onClose();
            if (fullPage) navigate('/profile');
          }, 1500);
          return;
        }

        showToast({
          severity: 'success',
          summary: 'Profile Updated!',
          detail: 'Your profile changes have been saved successfully.',
          life: 3500,
        });
      } else {
        submitProfileForReview(user.id, user.email, user.username || user.email);
        const updated = getEmployeeProfile(user.id);
        setProfile(updated);
        const updatedPct = calculateCompletionPercentage(updated, formConfig);
        window.dispatchEvent(new CustomEvent('aether_employee_profiles_updated'));

        if (updatedPct >= 100) {
          showToast({
            severity: 'success',
            summary: 'Profile 100% Complete!',
            detail: 'Your complete profile has been submitted. Redirecting to Profile...',
            life: 3500,
          });
          setTimeout(() => {
            if (onClose) onClose();
            if (fullPage) navigate('/profile');
          }, 1500);
          return;
        } else if (incompleteSections.length > 0) {
          showToast({
            severity: 'success',
            summary: 'Profile Submitted!',
            detail:
              'Your profile has been submitted for review. Remaining documents can be uploaded anytime.',
            life: 4500,
          });
        } else {
          showToast({
            severity: 'success',
            summary: 'Profile Submitted!',
            detail:
              'Your complete profile has been submitted for review. The HR team will review it shortly.',
            life: 4000,
          });
        }
      }
    } catch {
      showToast({
        severity: 'error',
        summary: 'Update Failed',
        detail: 'Could not save profile. Please try again.',
        life: 3000,
      });
    } finally {
      setIsSubmitting(false);
    }
  }, [user, profile, incompleteSections, formConfig, onClose, fullPage, navigate, setActiveSection]);

  const goToNext = () => {
    if (activeIdx < activeSections.length - 1) {
      handleSectionSwitch(activeSections[activeIdx + 1].id);
    }
  };

  const goToPrev = () => {
    if (activeIdx > 0) {
      handleSectionSwitch(activeSections[activeIdx - 1].id);
    }
  };

  if (!user || !profile) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="flex flex-col items-center gap-3">
          <div className="w-10 h-10 rounded-2xl bg-primary/10 flex items-center justify-center">
            <i className="pi pi-spin pi-spinner text-primary text-lg" />
          </div>
          <span className="text-xs text-muted font-bold uppercase tracking-wider">
            Loading profile...
          </span>
        </div>
      </div>
    );
  }

  const statusCfg = STATUS_CONFIG[profile.status];
  const StatusIcon = statusCfg.icon;
  const isReadOnly = false;

  const containerClass = fullPage
    ? 'min-h-screen bg-background'
    : 'fixed inset-0 z-50 bg-black/40 backdrop-blur-sm flex items-center justify-center p-4';

  const innerClass = fullPage
    ? 'w-full w-full mx-auto px-2 py-8'
    : 'bg-white rounded-3xl w-full max-w-6xl max-h-[92vh] overflow-hidden flex flex-col shadow-2xl';

  return (
    <div className={containerClass}>
      <div className={innerClass}>
        {/* ── Header ── */}
        <div className="flex items-center justify-between px-8 pt-8 pb-6 border-b border-border-subtle shrink-0">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-primary/20 to-primary/5 flex items-center justify-center">
              <FileText size={22} className="text-primary" />
            </div>
            <div>
              <div className="flex items-center gap-3">
                <h2 className="text-xl font-black text-foreground">Complete Your Profile</h2>
                <AutosaveStatusBadge status={autosaveStatus} lastSavedAt={lastSavedTimestamp} />
              </div>
              <p className="text-xs text-muted mt-0.5">
                Fill in all sections to activate your account fully
              </p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            {/* Status badge */}
            <div
              className={`flex items-center gap-2 px-3 py-1.5 rounded-xl border text-xs font-bold ${statusCfg.bg} ${statusCfg.color}`}>
              <StatusIcon size={14} />
              {statusCfg.label}
            </div>

            {/* Progress ring */}
            <div className="relative w-14 h-14">
              <svg viewBox="0 0 36 36" className="w-full h-full -rotate-90">
                <circle
                  cx="18"
                  cy="18"
                  r="15.5"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="3"
                  className="text-border-subtle/40"
                />
                <circle
                  cx="18"
                  cy="18"
                  r="15.5"
                  fill="none"
                  stroke={completionPercentage === 100 ? '#22c55e' : '#6366f1'}
                  strokeWidth="3"
                  strokeDasharray={`${(completionPercentage / 100) * 97.4} 97.4`}
                  strokeLinecap="round"
                  className="transition-all duration-700"
                />
              </svg>
              <span className="absolute inset-0 flex items-center justify-center text-[11px] font-black text-foreground">
                {completionPercentage}%
              </span>
            </div>

            {onClose && (
              <button
                onClick={onClose}
                className="w-9 h-9 rounded-xl flex items-center justify-center text-muted hover:text-foreground hover:bg-surface-subtle transition-all">
                <X size={18} />
              </button>
            )}
          </div>
        </div>

        {/* ── Status Alert Banners ── */}
        {profile.status === 'changes_required' && profile.reviewNotes && (
          <div className="mx-8 mt-4 p-4 rounded-2xl bg-warning/10 border border-warning/20 flex items-start gap-3">
            <AlertCircle size={18} className="text-warning shrink-0 mt-0.5" />
            <div>
              <div className="text-sm font-bold text-warning">Changes Requested by Hiring Team</div>
              <p className="text-xs text-warning/80 mt-1">{profile.reviewNotes}</p>
            </div>
          </div>
        )}

        {profile.status === 'submitted' && (
          <div className="mx-8 mt-4 p-4 rounded-2xl bg-info/10 border border-info/20 flex items-start gap-3">
            <Clock size={18} className="text-info shrink-0 mt-0.5" />
            <div>
              <div className="text-sm font-bold text-info">Profile Under Review</div>
              <p className="text-xs text-info/80 mt-1">
                Submitted on {new Date(profile.submittedAt || '').toLocaleDateString()} at{' '}
                {new Date(profile.submittedAt || '').toLocaleTimeString([], {
                  hour: '2-digit',
                  minute: '2-digit',
                })}
                . The hiring team will review your profile and get back to you.
              </p>
            </div>
          </div>
        )}

        {(profile.status === 'approved' || profile.status === 'id_assigned') && (
          <div className="mx-8 mt-4 p-4 rounded-2xl bg-success/10 border border-success/20 flex items-start gap-3">
            <CheckCircle2 size={18} className="text-success shrink-0 mt-0.5" />
            <div>
              <div className="text-sm font-bold text-success">
                {profile.status === 'id_assigned'
                  ? 'Profile Approved & Employee ID Assigned'
                  : 'Profile Approved'}
              </div>
              {profile.employeeId && (
                <p className="text-xs text-success/80 mt-1">
                  Your Employee ID: <strong className="font-black">{profile.employeeId}</strong>
                  {profile.employeeIdAssignedBy &&
                    ` — Assigned by ${profile.employeeIdAssignedBy.name} (${profile.employeeIdAssignedBy.role})`}
                </p>
              )}
            </div>
          </div>
        )}

        {/* ── Main Body ── */}
        <div className="flex flex-1 min-h-0 overflow-hidden">
          {/* ── Sidebar Navigation ── */}
          <div className="w-72 border-r border-border-subtle bg-surface-subtle/30 flex flex-col overflow-y-auto shrink-0">
            <div className="p-4 space-y-1">
              {/* Profile picture quick link */}
              <button
                onClick={() => handleSectionSwitch('profile_picture')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl text-left transition-all group ${
                  activeSection === 'profile_picture'
                    ? 'bg-primary text-white shadow-md shadow-primary/20'
                    : 'hover:bg-white hover:shadow-sm text-foreground'
                }`}>
                <div
                  className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 ${
                    activeSection === 'profile_picture' ? 'bg-white/20' : 'bg-primary/10'
                  }`}>
                  <Camera
                    size={16}
                    className={activeSection === 'profile_picture' ? 'text-white' : 'text-primary'}
                  />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-xs font-bold truncate">Profile Picture</div>
                </div>
                {profile.profilePictureUrl && (
                  <div
                    className={`w-5 h-5 rounded-full flex items-center justify-center shrink-0 ${
                      activeSection === 'profile_picture' ? 'bg-white/20' : 'bg-success/10'
                    }`}>
                    <Check
                      size={11}
                      className={
                        activeSection === 'profile_picture' ? 'text-white' : 'text-success'
                      }
                    />
                  </div>
                )}
              </button>

              {/* Dynamic sections */}
              {activeSections.map((section) => {
                const IconComp = SECTION_ICONS[section.id] || FileText;
                const isActive = activeSection === section.id;
                const isCompleted = isSectionValidAndComplete(section.id, profile);

                return (
                  <button
                    key={section.id}
                    onClick={() => handleSectionSwitch(section.id)}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl text-left transition-all ${
                      isActive
                        ? 'bg-primary text-white shadow-md shadow-primary/20'
                        : 'hover:bg-white hover:shadow-sm text-foreground'
                    }`}>
                    <div
                      className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 ${
                        isActive ? 'bg-white/20' : isCompleted ? 'bg-success/10' : 'bg-primary/10'
                      }`}>
                      <IconComp
                        size={16}
                        className={
                          isActive ? 'text-white' : isCompleted ? 'text-success' : 'text-primary'
                        }
                      />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-xs font-bold truncate">{section.label}</div>
                      {section.description && (
                        <div
                          className={`text-[10px] truncate mt-0.5 ${isActive ? 'text-white/70' : 'text-muted'}`}>
                          {section.description}
                        </div>
                      )}
                    </div>
                    {isCompleted && (
                      <div
                        className={`w-5 h-5 rounded-full flex items-center justify-center shrink-0 ${
                          isActive ? 'bg-white/20' : 'bg-success/10'
                        }`}>
                        <Check size={11} className={isActive ? 'text-white' : 'text-success'} />
                      </div>
                    )}
                  </button>
                );
              })}
            </div>

            {/* Summary / Progress section */}
            <div className="p-4 mt-auto border-t border-border-subtle">
              <div className="p-4 rounded-2xl bg-white border border-border-subtle">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-[11px] font-black uppercase tracking-wider text-muted">
                    Progress
                  </span>
                  <span className="text-sm font-black text-primary">{completionPercentage}%</span>
                </div>
                <div className="h-2 rounded-full bg-surface-subtle overflow-hidden">
                  <motion.div
                    className="h-full rounded-full bg-gradient-to-r from-primary to-primary/80"
                    initial={{ width: 0 }}
                    animate={{ width: `${completionPercentage}%` }}
                    transition={{ duration: 0.5, ease: 'easeOut' }}
                  />
                </div>
                <div className="mt-2 text-[10px] text-muted">
                  {activeSections.filter((s) => isSectionValidAndComplete(s.id, profile)).length} of{' '}
                  {activeSections.length} sections completed
                </div>

                {profile.status === 'in_progress' && profile.lastSavedAt && (
                  <div className="mt-3 flex items-center gap-1.5 text-[10px] text-muted">
                    <Check size={10} className="text-success" />
                    Saved{' '}
                    {new Date(profile.lastSavedAt).toLocaleTimeString([], {
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* ── Section Content ── */}
          <div className="flex-1 overflow-y-auto">
            {/* Contextual Smart Alert Banner */}
            <div className="pt-6">
              <SmartAlertBanner
                completionPercentage={completionPercentage}
                incompleteSections={incompleteSections}
                activeSection={activeSection}
                onSelectSection={handleSectionSwitch}
                hasRestoredDraft={hasRestoredDraft}
                onDiscardDraft={handleDiscardDraft}
                isDirty={isCurrentSectionDirty}
              />
            </div>

            <div key={activeSection} className="px-8 pb-8 transition-opacity duration-150">
              {activeSection === 'profile_picture' && (
                <ProfilePictureSection
                  profile={profile}
                  onSave={(url) => {
                    if (!user) return;
                    const updated = getEmployeeProfile(user.id) || profile;
                    const newProfile = { ...updated, profilePictureUrl: url };
                    saveEmployeeProfile(newProfile);
                    setProfile(newProfile);
                  }}
                  onContinue={goToNext}
                  readOnly={isReadOnly}
                />
              )}

              {activeSection === 'personal' && (
                <PersonalDetailsSection
                  data={getEffectiveSectionData('personal')}
                  onSave={(data) => handleSaveSection('personal', data)}
                  onSaveDraft={handleSaveDraft}
                  onDraftChange={(data, isDirty) => handleDraftChange('personal', data, isDirty)}
                  isSaving={isSaving}
                  readOnly={isReadOnly}
                />
              )}

              {activeSection === 'bank' && (
                <BankDetailsSection
                  data={getEffectiveSectionData('bank')}
                  onSave={(data) => handleSaveSection('bank', data)}
                  onSaveDraft={handleSaveDraft}
                  onDraftChange={(data, isDirty) => handleDraftChange('bank', data, isDirty)}
                  isSaving={isSaving}
                  readOnly={isReadOnly}
                />
              )}

              {activeSection === 'identity' && (
                <IdentityDocumentsSection
                  data={getEffectiveSectionData('identity')}
                  documents={profile.documents || []}
                  userId={user.id}
                  onSave={(data) => handleSaveSection('identity', data)}
                  onSaveDraft={handleSaveDraft}
                  onDraftChange={(data, isDirty) => handleDraftChange('identity', data, isDirty)}
                  onDocumentAdded={(doc) => {
                    const updated = getEmployeeProfile(user.id) || profile;
                    setProfile({ ...updated, documents: [...(updated.documents || []), doc] });
                  }}
                  isSaving={isSaving}
                  readOnly={isReadOnly}
                />
              )}

              {activeSection === 'employment' && (
                <PreviousEmploymentSection
                  data={getEffectiveSectionData('employment') || []}
                  documents={profile.documents || []}
                  userId={user.id}
                  onSave={(data) => handleSaveSection('employment', data)}
                  onSaveDraft={handleSaveDraft}
                  onDraftChange={(data, isDirty) => handleDraftChange('employment', data, isDirty)}
                  isSaving={isSaving}
                  readOnly={isReadOnly}
                />
              )}

              {activeSection === 'education' && (
                <EducationSection
                  data={getEffectiveSectionData('education') || []}
                  documents={profile.documents || []}
                  userId={user.id}
                  onSave={(data) => handleSaveSection('education', data)}
                  onSaveDraft={handleSaveDraft}
                  onDraftChange={(data, isDirty) => handleDraftChange('education', data, isDirty)}
                  isSaving={isSaving}
                  readOnly={isReadOnly}
                />
              )}

              {activeSection === 'certifications' && (
                <CertificationsSection
                  data={getEffectiveSectionData('certifications') || []}
                  documents={profile.documents || []}
                  userId={user.id}
                  onSave={(data) => handleSaveSection('certifications', data)}
                  onSaveDraft={handleSaveDraft}
                  onDraftChange={(data, isDirty) => handleDraftChange('certifications', data, isDirty)}
                  isSaving={isSaving}
                  readOnly={isReadOnly}
                />
              )}
            </div>
          </div>
        </div>

        {/* ── Footer Actions ── */}
        <div className="flex items-center justify-between px-8 py-5 border-t border-border-subtle bg-surface-subtle/20 shrink-0">
          <div className="flex items-center gap-3">
            <button
              onClick={goToPrev}
              disabled={activeIdx <= 0 && activeSection !== 'profile_picture'}
              className="flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold text-muted hover:text-foreground hover:bg-surface-subtle transition-all disabled:opacity-30 disabled:cursor-not-allowed">
              <ChevronLeft size={16} />
              Previous
            </button>
            <button
              onClick={goToNext}
              disabled={activeIdx >= activeSections.length - 1}
              className="flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold text-muted hover:text-foreground hover:bg-surface-subtle transition-all disabled:opacity-30 disabled:cursor-not-allowed">
              Next
              <ChevronRight size={16} />
            </button>
          </div>

          <div className="flex items-center gap-3">
            {isSaving && (
              <div className="flex items-center gap-2 text-xs text-muted">
                <i className="pi pi-spin pi-spinner text-xs" />
                Saving...
              </div>
            )}

            {/* If profile is 100% complete and approved or on last step, provide one-click Finish / View Profile */}
            {(completionPercentage >= 100 || activeIdx === activeSections.length - 1) && (
              <button
                onClick={handleSubmit}
                disabled={isSubmitting}
                className="flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-bold bg-primary text-white shadow-md shadow-primary/25 hover:shadow-lg hover:shadow-primary/30 hover:-translate-y-0.5 transition-all disabled:opacity-50">
                {isSubmitting ? (
                  <>
                    <i className="pi pi-spin pi-spinner" /> Saving...
                  </>
                ) : profile.status === 'id_assigned' || profile.status === 'approved' ? (
                  <>
                    <CheckCircle2 size={15} /> Finish & View Profile
                  </>
                ) : profile.status === 'submitted' ? (
                  <>
                    <Send size={15} /> Update Submission
                  </>
                ) : incompleteSections.length > 0 ? (
                  <>
                    <Send size={15} /> Submit for Review (Docs Later)
                  </>
                ) : (
                  <>
                    <Send size={15} /> Submit for Review
                  </>
                )}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

