import { useState, useEffect } from 'react';
import { resolveImageUrl } from '@/utils/imageUrl';
import { Badge } from '@/components/ui/primitives/Badge';
import { Button } from '@/components/ui/primitives/Button';
import {
  Clock,
  Edit2,
  MapPin,
  Trash2,
  Users,
  Tag,
  Building2,
  ArrowUpRight,
  ExternalLink,
  AlertCircle,
  Calendar as CalendarIcon,
  CheckCircle2,
  Radio,
} from 'lucide-react';
import type { ERPEvent } from '@/types/models';
import { useAuth } from '@/hooks/useAuth';
import {
  formatEventTime,
  getEventStatusInfo,
  getDynamicAttendeesCount,
  isUserRegisteredForEvent,
} from '../utils/eventUtils';

interface EventCardProps {
  event: ERPEvent;
  onCardClick?: (event: ERPEvent) => void;
  onEdit: (id: string) => void;
  onDelete: (id: string) => void;
  onRegister?: (event: ERPEvent) => void;
  onTagClick?: (tag: string) => void;
  isRegistering?: boolean;
}

const CATEGORY_IMAGES: Record<string, string> = {
  Conference:
    'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=800&auto=format&fit=crop&q=60',
  Workshop:
    'https://images.unsplash.com/photo-1531482615713-2afd69097998?w=800&auto=format&fit=crop&q=60',
  Social:
    'https://images.unsplash.com/photo-1511795409834-ef04bbd61622?w=800&auto=format&fit=crop&q=60',
  Meeting:
    'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=800&auto=format&fit=crop&q=60',
};

const DEFAULT_IMAGE =
  'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?w=800&auto=format&fit=crop&q=60';

export const EventCard = ({
  event,
  onCardClick,
  onEdit,
  onDelete,
  onRegister,
  onTagClick,
  isRegistering,
}: EventCardProps) => {
  const { user } = useAuth();
  const fallbackCategoryImg = CATEGORY_IMAGES[event.category] || DEFAULT_IMAGE;
  const initialImage = resolveImageUrl(event.image) || fallbackCategoryImg;

  const [imageSrc, setImageSrc] = useState(initialImage);
  const [imageError, setImageError] = useState(false);

  useEffect(() => {
    setImageSrc(resolveImageUrl(event.image) || CATEGORY_IMAGES[event.category] || DEFAULT_IMAGE);
    setImageError(false);
  }, [event.image, event.category]);

  const handleImageError = () => {
    const fallback = CATEGORY_IMAGES[event.category] || DEFAULT_IMAGE;
    if (imageSrc !== fallback) {
      setImageSrc(fallback);
    } else {
      setImageError(true);
    }
  };

  const categoryVariants: Record<string, 'primary' | 'success' | 'warning' | 'secondary'> = {
    Conference: 'primary',
    Workshop: 'success',
    Social: 'warning',
    Meeting: 'secondary',
  };

  const statusInfo = getEventStatusInfo(event);
  const attendeesCount = getDynamicAttendeesCount(event);
  const isRegistered = isUserRegisteredForEvent(event.id, user?.email || user?.username, event);

  const eventDate = new Date(event.event_date || event.date || '');
  const month = Number.isNaN(eventDate.getTime())
    ? 'EVENT'
    : eventDate.toLocaleString('en-US', { month: 'short' }).toUpperCase();
  const day = Number.isNaN(eventDate.getDate()) ? '--' : eventDate.getDate();
  const formattedTime = formatEventTime(event);

  const handleCardClick = () => {
    onCardClick?.(event);
  };

  return (
    <div
      onClick={handleCardClick}
      className="group bg-white rounded-3xl border border-border-subtle overflow-hidden hover:shadow-2xl hover:shadow-primary/10 transition-all duration-300 flex flex-col h-full hover:-translate-y-1.5 cursor-pointer relative">
      {/* Visual Header */}
      <div className="relative h-52 overflow-hidden bg-zinc-900">
        {!imageError ? (
          <img
            src={imageSrc}
            alt={event.title}
            onError={handleImageError}
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
          />
        ) : (
          <div className="w-full h-full bg-linear-to-br from-primary/30 via-zinc-800 to-zinc-900 flex items-center justify-center">
            <CalendarIcon size={48} className="text-white/20" />
          </div>
        )}

        {/* Gradient Overlay */}
        <div className="absolute inset-0 bg-linear-to-t from-black/85 via-black/30 to-black/30" />

        {/* Top Floating Bar: Date Pill & Action Buttons */}
        <div className="absolute top-3.5 inset-x-3.5 flex items-center justify-between z-10">
          {/* Glass Date Pill */}
          <div className="bg-black/50 backdrop-blur-md border border-white/20 rounded-2xl px-3 py-1.5 flex items-center gap-2 text-white shadow-lg">
            <span className="text-[10px] font-black text-primary uppercase tracking-wider bg-white/15 px-1.5 py-0.5 rounded-lg">
              {month}
            </span>
            <span className="text-sm font-black tracking-tight">{day}</span>
          </div>

          {/* Glass Action Capsule */}
          <div className="flex items-center gap-1 p-1 bg-black/40 backdrop-blur-md rounded-2xl border border-white/20 shadow-lg">
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                onEdit(String(event.id));
              }}
              className="w-8 h-8 rounded-xl bg-white/10 text-white hover:bg-white hover:text-primary flex items-center justify-center transition-all cursor-pointer"
              title="Edit Event">
              <Edit2 size={14} />
            </button>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                onDelete(String(event.id));
              }}
              className="w-8 h-8 rounded-xl bg-white/10 text-rose-300 hover:bg-rose-500 hover:text-white flex items-center justify-center transition-all cursor-pointer"
              title="Delete Event">
              <Trash2 size={14} />
            </button>
          </div>
        </div>

        {/* Bottom Floating Bar: Category & Status */}
        <div className="absolute bottom-3.5 inset-x-3.5 flex items-center justify-between z-10">
          <Badge
            variant={categoryVariants[event.category] || 'primary'}
            className="rounded-xl px-3 py-1 text-[10px] font-black tracking-wider uppercase backdrop-blur-md bg-white/20 text-white border border-white/20 shadow-md">
            {event.category || 'General'}
          </Badge>

          {/* Status Display: Inactive, Completed, Active, or Upcoming */}
          {statusInfo.isInactive ? (
            <span className="text-[10px] font-black px-2.5 py-1 rounded-xl backdrop-blur-md bg-rose-500/90 text-white uppercase tracking-wider flex items-center gap-1 border border-rose-400/40 shadow-md">
              <AlertCircle size={12} />
              {statusInfo.label}
            </span>
          ) : statusInfo.isPast ? (
            <span className="text-[10px] font-black px-2.5 py-1 rounded-xl backdrop-blur-md bg-zinc-700/80 text-zinc-200 uppercase tracking-wider flex items-center gap-1 border border-zinc-500/30 shadow-md">
              <CheckCircle2 size={12} />
              Completed
            </span>
          ) : statusInfo.isLive || (event.status || '').toLowerCase() === 'active' ? (
            <span className="text-[10px] font-black px-2.5 py-1 rounded-xl backdrop-blur-md bg-emerald-500/90 text-white uppercase tracking-wider flex items-center gap-1 border border-emerald-400/30 shadow-md animate-pulse">
              <Radio size={12} />
              Active
            </span>
          ) : (
            <span className="text-[10px] font-black px-2.5 py-1 rounded-xl backdrop-blur-md bg-sky-500/90 text-white uppercase tracking-wider flex items-center gap-1 border border-sky-400/30 shadow-md">
              <CalendarIcon size={12} />
              {event.status || 'Upcoming'}
            </span>
          )}
        </div>
      </div>

      {/* Content Area */}
      <div className="p-6 flex flex-col flex-1 gap-4">
        <div className="flex flex-col gap-1.5">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-black text-foreground leading-snug tracking-tight group-hover:text-primary transition-colors line-clamp-1">
              {event.title}
            </h3>
          </div>
          <p className="text-xs text-muted font-medium line-clamp-2 leading-relaxed">
            {event.description || 'No additional description provided for this event.'}
          </p>
        </div>

        {/* Linkable Event Tag */}
        {event.event_link && (
          <a
            href={event.event_link}
            target="_blank"
            rel="noopener noreferrer"
            onClick={(e) => e.stopPropagation()}
            className="flex items-center gap-1.5 text-[11px] font-bold text-indigo-500 hover:text-indigo-600 bg-indigo-50 hover:bg-indigo-100 dark:bg-indigo-950/40 dark:hover:bg-indigo-900/50 dark:text-indigo-300 px-3 py-1.5 rounded-xl border border-indigo-200 dark:border-indigo-800 transition-colors truncate">
            <ExternalLink size={12} className="shrink-0" />
            <span className="truncate">
              Resource: {event.event_link.replace(/^https?:\/\//, '')}
            </span>
          </a>
        )}

        {/* Tags */}
        {event.tags && event.tags.length > 0 && (
          <div className="flex flex-wrap gap-1.5">
            {event.tags.map((tag) => (
              <button
                key={tag}
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onTagClick?.(tag);
                }}
                className="inline-flex items-center gap-1 text-[10px] font-bold text-primary bg-primary/8 hover:bg-primary/15 transition-colors px-2.5 py-0.5 rounded-lg border border-primary/15 cursor-pointer">
                <Tag size={9} /> #{tag}
              </button>
            ))}
          </div>
        )}

        {/* Info Grid */}
        <div className="mt-auto grid grid-cols-2 gap-y-2.5 pt-4 border-t border-border-subtle">
          {/* Time */}
          <div className="flex items-center gap-2 text-foreground font-bold text-xs">
            <Clock size={14} className="text-primary flex-shrink-0" />
            <span className="truncate">{formattedTime}</span>
          </div>

          {/* Location */}
          <div className="flex items-center gap-2 text-foreground font-bold text-xs">
            <MapPin size={14} className="text-primary flex-shrink-0" />
            <span className="truncate">
              {event.location?.split(',')[0] || event.location || 'Company HQ'}
            </span>
          </div>

          {/* Participants Count */}
          <div className="flex items-center gap-2 text-muted font-bold text-[11px]">
            <Users size={13} className="text-primary flex-shrink-0" />
            <span>
              {attendeesCount} Joined
              {event.max_participants ? ` / ${event.max_participants}` : ''}
            </span>
          </div>

          {/* Department / Organizer */}
          <div className="flex items-center gap-2 text-muted font-bold text-[11px] truncate">
            {event.author_department ? (
              <>
                <Building2 size={13} className="text-primary flex-shrink-0" />
                <span className="truncate">{event.author_department}</span>
              </>
            ) : (
              <>
                <span className="w-1.5 h-1.5 rounded-full bg-primary/50 flex-shrink-0" />
                <span className="truncate">{event.organizer || 'Team Event'}</span>
              </>
            )}
          </div>
        </div>

        {/* CTA Button according to button_type */}
        {event.button_type === 'Mandatory' ? (
          <Button
            variant="primary"
            onClick={(e) => {
              e.stopPropagation();
              onRegister?.(event);
            }}
            disabled={isRegistering}
            className="w-full mt-2 h-11 rounded-2xl! gap-2 font-black text-xs uppercase tracking-wider bg-amber-500 hover:bg-amber-600 text-white shadow-md hover:shadow-lg transition-all cursor-pointer">
            <div className="flex items-center gap-1.5">
              <AlertCircle size={15} />
              <span>Mandatory Attendance</span>
            </div>
          </Button>
        ) : event.button_type === 'View Details' ? (
          <Button
            variant="secondary"
            onClick={(e) => {
              e.stopPropagation();
              if (event.event_link) {
                window.open(event.event_link, '_blank', 'noopener,noreferrer');
              } else {
                onRegister?.(event);
              }
            }}
            className="w-full mt-2 h-11 rounded-2xl! gap-2 font-black text-xs uppercase tracking-wider border border-border-subtle hover:bg-surface-subtle transition-all cursor-pointer">
            <div className="flex items-center gap-1.5">
              <span>View Details</span>
              {event.event_link ? <ExternalLink size={14} /> : <ArrowUpRight size={14} />}
            </div>
          </Button>
        ) : isRegistered ? (
          <Button
            variant="secondary"
            onClick={(e) => {
              e.stopPropagation();
              onRegister?.(event);
            }}
            className="w-full mt-2 h-11 rounded-2xl! gap-2 font-black text-xs uppercase tracking-wider bg-emerald-50 text-emerald-600 border border-emerald-200 hover:bg-emerald-100 transition-all cursor-pointer">
            <div className="flex items-center gap-1.5">
              <CheckCircle2 size={15} />
              <span>Registered</span>
            </div>
          </Button>
        ) : (
          <Button
            variant="primary"
            onClick={(e) => {
              e.stopPropagation();
              onRegister?.(event);
            }}
            disabled={isRegistering}
            className="w-full mt-2 h-11 rounded-2xl! gap-2 font-black text-xs uppercase tracking-wider shadow-md hover:shadow-lg transition-all cursor-pointer disabled:opacity-60 disabled:cursor-not-allowed">
            {isRegistering ? (
              <>
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                <span>Registering...</span>
              </>
            ) : (
              <div className="flex items-center gap-1">
                <span>Register Now</span>
                <ArrowUpRight size={14} />
              </div>
            )}
          </Button>
        )}
      </div>
    </div>
  );
};

import { useState, useMemo } from 'react';
import { Dialog } from '@/components/ui/composed/Dialog';
import { Button } from '@/components/ui/primitives/Button';
import { Badge } from '@/components/ui/primitives/Badge';
import { Input } from '@/components/ui/primitives/Input';
import {
  Calendar,
  Clock,
  MapPin,
  Users,
  Building2,
  Tag,
  CheckCircle2,
  ArrowUpRight,
  Edit2,
  Trash2,
  ClockAlert,
  Sparkles,
  Info,
  Layers,
  X,
  Search,
  UserCheck,
  Mail,
  ChevronRight,
} from 'lucide-react';
import type { ERPEvent } from '@/types/models';
import { useAuth } from '@/hooks/useAuth';
import {
  formatEventTime,
  getEventStatusInfo,
  getDynamicAttendeesCount,
  isUserRegisteredForEvent,
  isPastEvent,
  getEventParticipantsList,
} from '../utils/eventUtils';
import { EventMediaUploader } from './EventMediaUploader';

interface EventDetailsModalProps {
  event: ERPEvent | null;
  visible: boolean;
  onHide: () => void;
  onRegister: (event: ERPEvent) => void;
  isRegistering?: boolean;
  onEdit?: (id: string) => void;
  onDelete?: (id: string) => void;
  onViewPass?: (event: ERPEvent) => void;
}

const CATEGORY_IMAGES: Record<string, string> = {
  Conference:
    'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=1200&auto=format&fit=crop&q=80',
  Workshop:
    'https://images.unsplash.com/photo-1531482615713-2afd69097998?w=1200&auto=format&fit=crop&q=80',
  Social:
    'https://images.unsplash.com/photo-1511795409834-ef04bbd61622?w=1200&auto=format&fit=crop&q=80',
  Meeting:
    'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=1200&auto=format&fit=crop&q=80',
};

const DEFAULT_IMAGE =
  'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?w=1200&auto=format&fit=crop&q=80';

const AVATAR_COLORS = [
  'bg-emerald-500 text-white',
  'bg-indigo-500 text-white',
  'bg-amber-500 text-white',
  'bg-rose-500 text-white',
  'bg-sky-500 text-white',
  'bg-purple-500 text-white',
  'bg-orange-500 text-white',
];

export const EventDetailsModal = ({
  event,
  visible,
  onHide,
  onRegister,
  isRegistering = false,
  onEdit,
  onDelete,
}: EventDetailsModalProps) => {
  const { user } = useAuth();
  const isAdmin = Boolean(
    user?.role &&
    ['admin', 'superadmin', 'hradmin', 'financeadmin', 'manager'].some((r) =>
      String(user.role).toLowerCase().includes(r)
    )
  );
  const [activeTab, setActiveTab] = useState<'details' | 'participants' | 'media'>('details');
  const [participantSearch, setParticipantSearch] = useState('');

  const statusInfo = event ? getEventStatusInfo(event) : null;
  const attendeesCount = event ? getDynamicAttendeesCount(event) : 0;
  const isRegistered = event
    ? isUserRegisteredForEvent(event.id, user?.email || user?.username, event)
    : false;
  const isPast = event ? isPastEvent(event) : false;
  const maxCapacity = event?.max_participants || 100;
  const capacityPct = Math.min(100, Math.round((attendeesCount / maxCapacity) * 100));

  const participantsList = useMemo(() => {
    if (!event) return [];
    return getEventParticipantsList(event);
  }, [event, attendeesCount]);

  const filteredParticipants = useMemo(() => {
    if (!participantSearch.trim()) return participantsList;
    const q = participantSearch.toLowerCase();
    return participantsList.filter(
      (p) =>
        p.name.toLowerCase().includes(q) ||
        p.email.toLowerCase().includes(q) ||
        p.department?.toLowerCase().includes(q)
    );
  }, [participantsList, participantSearch]);

  if (!event || !statusInfo) return null;

  const eventDateObj = new Date(event.event_date || event.date || '');
  const formattedDate = !Number.isNaN(eventDateObj.getTime())
    ? eventDateObj.toLocaleDateString('en-US', {
        weekday: 'short',
        month: 'short',
        day: 'numeric',
        year: 'numeric',
      })
    : event.date || event.event_date || 'Date TBD';

  const timeRange = formatEventTime(event);
  const imageBanner = event.image || CATEGORY_IMAGES[event.category] || DEFAULT_IMAGE;

  return (
    <Dialog
      visible={visible}
      onHide={onHide}
      modal
      header={null}
      footer={null}
      width={860}
      className="max-w-[92vw] mx-auto rounded-[36px] overflow-hidden"
      contentClassName="p-0 overflow-hidden"
      pt={{
        root: { className: 'rounded-[36px] overflow-hidden border-none shadow-2xl bg-white' },
        mask: { className: 'backdrop-blur-md bg-black/60' },
      }}>
      <div className="flex flex-col max-h-[88vh] overflow-y-auto bg-white rounded-[36px]">
        {/* Visual Banner Header */}
        <div className="relative h-60 sm:h-68 w-full bg-zinc-950 overflow-hidden flex-shrink-0">
          <img
            src={imageBanner}
            alt={event.title}
            onError={(e) => {
              (e.target as HTMLImageElement).src = CATEGORY_IMAGES[event.category] || DEFAULT_IMAGE;
            }}
            className="w-full h-full object-cover opacity-85"
          />
          <div className="absolute inset-0 bg-linear-to-t from-black via-black/40 to-black/30" />

          {/* Top Controls: Status Badges & Action Buttons */}
          <div className="absolute top-5 inset-x-6 flex items-center justify-between z-10">
            {/* Status Badges */}
            <div className="flex flex-wrap items-center gap-2">
              <span
                className={`px-3.5 py-1.5 rounded-2xl backdrop-blur-md border text-xs font-black uppercase tracking-wider flex items-center gap-1.5 shadow-md ${statusInfo.colorClasses}`}>
                <statusInfo.icon size={13} />
                <span>{statusInfo.label}</span>
              </span>

              {statusInfo.isLeave && (
                <span className="px-3.5 py-1.5 rounded-2xl backdrop-blur-md bg-amber-500/90 text-white border border-amber-400/40 text-xs font-black uppercase tracking-wider flex items-center gap-1.5 shadow-md">
                  <ClockAlert size={13} />
                  <span>Host On Leave</span>
                </span>
              )}
            </div>

            {/* Action Buttons & Close */}
            <div className="flex items-center gap-2">
              {isAdmin && onEdit && (
                <button
                  type="button"
                  onClick={() => {
                    onHide();
                    onEdit(String(event.id));
                  }}
                  className="w-9 h-9 rounded-2xl bg-black/50 backdrop-blur-md text-white border border-white/20 hover:bg-white hover:text-primary flex items-center justify-center transition-all cursor-pointer shadow-lg"
                  title="Edit Event">
                  <Edit2 size={15} />
                </button>
              )}
              {isAdmin && onDelete && (
                <button
                  type="button"
                  onClick={() => {
                    onHide();
                    onDelete(String(event.id));
                  }}
                  className="w-9 h-9 rounded-2xl bg-black/50 backdrop-blur-md text-rose-300 border border-white/20 hover:bg-rose-500 hover:text-white flex items-center justify-center transition-all cursor-pointer shadow-lg"
                  title="Delete Event">
                  <Trash2 size={15} />
                </button>
              )}
              <button
                type="button"
                onClick={onHide}
                className="w-9 h-9 rounded-2xl bg-black/50 backdrop-blur-md text-white border border-white/20 hover:bg-white hover:text-foreground flex items-center justify-center transition-all cursor-pointer shadow-lg"
                title="Close">
                <X size={17} />
              </button>
            </div>
          </div>

          {/* Bottom Banner Title & Category */}
          <div className="absolute bottom-5 inset-x-6 z-10 flex flex-col gap-2">
            <div className="flex flex-wrap items-center gap-2">
              <Badge
                variant="primary"
                className="bg-primary backdrop-blur-md text-white border border-white/20 text-[11px] font-black uppercase tracking-wider px-3 py-1 rounded-xl">
                {event.category || 'General'}
              </Badge>
              {event.author_department && (
                <span className="text-xs font-bold text-white bg-white/15 backdrop-blur-md px-3 py-1 rounded-xl border border-white/20 flex items-center gap-1.5">
                  <Building2 size={13} /> {event.author_department}
                </span>
              )}
            </div>
            <h1 className="text-2xl sm:text-3xl font-black text-white leading-snug tracking-tight">
              {event.title}
            </h1>
          </div>
        </div>

        {/* Navigation Switcher Tabs */}
        <div className="flex items-center gap-2.5 px-6 sm:px-8 pt-5 pb-3 border-b border-border-subtle bg-surface-subtle/30 flex-shrink-0 overflow-x-auto">
          <button
            type="button"
            onClick={() => setActiveTab('details')}
            className={`px-4.5 py-2.5 rounded-2xl font-black text-xs uppercase tracking-wider transition-all cursor-pointer flex items-center gap-2 whitespace-nowrap ${
              activeTab === 'details'
                ? 'bg-primary text-white shadow-md'
                : 'text-muted hover:text-foreground bg-white border border-border-subtle hover:bg-surface-subtle'
            }`}>
            <Info size={14} />
            <span>Event Information</span>
          </button>

          <button
            type="button"
            onClick={() => setActiveTab('participants')}
            className={`px-4.5 py-2.5 rounded-2xl font-black text-xs uppercase tracking-wider transition-all cursor-pointer flex items-center gap-2 whitespace-nowrap ${
              activeTab === 'participants'
                ? 'bg-primary text-white shadow-md'
                : 'text-muted hover:text-foreground bg-white border border-border-subtle hover:bg-surface-subtle'
            }`}>
            <Users size={14} />
            <span>Joined Participants ({attendeesCount})</span>
          </button>

          <button
            type="button"
            onClick={() => setActiveTab('media')}
            className={`px-4.5 py-2.5 rounded-2xl font-black text-xs uppercase tracking-wider transition-all cursor-pointer flex items-center gap-2 whitespace-nowrap ${
              activeTab === 'media'
                ? 'bg-primary text-white shadow-md'
                : 'text-muted hover:text-foreground bg-white border border-border-subtle hover:bg-surface-subtle'
            }`}>
            <Sparkles size={14} />
            <span>Recap, Photos & Files</span>
          </button>
        </div>

        {/* Tab Content Body */}
        <div className="p-6 sm:p-8 flex flex-col gap-6 flex-1">
          {activeTab === 'details' ? (
            <>
              {/* Highlight Stat Cards */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {/* Date & Schedule */}
                <div className="p-5 rounded-3xl bg-surface-subtle/70 border border-border-subtle flex items-center gap-4">
                  <div className="w-12 h-12 rounded-2xl bg-primary/10 text-primary flex items-center justify-center flex-shrink-0 shadow-xs">
                    <Calendar size={22} />
                  </div>
                  <div className="min-w-0 flex-1">
                    <span className="text-[10px] font-black text-muted uppercase tracking-wider block">
                      Date & Schedule
                    </span>
                    <p className="text-xs font-black text-foreground truncate mt-0.5">
                      {formattedDate}
                    </p>
                    <p className="text-[11px] font-bold text-primary flex items-center gap-1 mt-0.5 truncate">
                      <Clock size={11} className="flex-shrink-0" />
                      <span>{timeRange}</span>
                    </p>
                  </div>
                </div>

                {/* Venue & Location */}
                <div className="p-5 rounded-3xl bg-surface-subtle/70 border border-border-subtle flex items-center gap-4">
                  <div className="w-12 h-12 rounded-2xl bg-primary/10 text-primary flex items-center justify-center flex-shrink-0 shadow-xs">
                    <MapPin size={22} />
                  </div>
                  <div className="min-w-0 flex-1">
                    <span className="text-[10px] font-black text-muted uppercase tracking-wider block">
                      Venue & Location
                    </span>
                    <p className="text-xs font-black text-foreground truncate mt-0.5">
                      {event.location || 'Executive Headquarters'}
                    </p>
                    <span className="text-[11px] text-muted font-medium block mt-0.5 truncate">
                      Check in upon arrival
                    </span>
                  </div>
                </div>

                {/* Participants Joined & Capacity (Clickable to switch tab!) */}
                <div
                  onClick={() => setActiveTab('participants')}
                  className="p-5 rounded-3xl bg-surface-subtle/70 border border-border-subtle flex items-center gap-4 hover:border-primary/40 hover:bg-primary/5 transition-all cursor-pointer group/stat"
                  title="Click to view joined participants list">
                  <div className="w-12 h-12 rounded-2xl bg-primary/10 text-primary group-hover/stat:bg-primary group-hover/stat:text-white flex items-center justify-center flex-shrink-0 shadow-xs transition-colors">
                    <Users size={22} />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center justify-between">
                      <span className="text-[10px] font-black text-muted uppercase tracking-wider block">
                        Participants Joined
                      </span>
                      <span className="text-[10px] font-bold text-primary group-hover/stat:underline flex items-center gap-0.5">
                        View List <ChevronRight size={10} />
                      </span>
                    </div>
                    <div className="flex items-center justify-between mt-0.5">
                      <p className="text-sm font-black text-foreground">{attendeesCount} Joined</p>
                      {event.max_participants && (
                        <span className="text-[10px] font-bold text-muted">
                          / {event.max_participants} Max
                        </span>
                      )}
                    </div>
                    {event.max_participants && (
                      <div className="w-full bg-border-subtle h-1.5 rounded-full overflow-hidden mt-1.5">
                        <div
                          className="bg-primary h-full rounded-full transition-all duration-500"
                          style={{ width: `${capacityPct}%` }}
                        />
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {/* Description Section */}
              <div className="flex flex-col gap-2.5">
                <h3 className="text-xs font-black uppercase tracking-wider text-foreground flex items-center gap-2">
                  <Layers size={15} className="text-primary" />
                  <span>About This Event</span>
                </h3>
                <div className="p-6 rounded-3xl bg-surface-subtle/40 border border-border-subtle">
                  <p className="text-sm text-foreground/80 font-medium leading-relaxed whitespace-pre-line">
                    {event.description ||
                      'No detailed description has been added for this event. Join in and be part of the experience!'}
                  </p>
                </div>
              </div>

              {/* Quick Joined Participants Banner Preview */}
              <div
                onClick={() => setActiveTab('participants')}
                className="p-5 rounded-3xl bg-linear-to-r from-primary/10 via-surface-subtle to-primary/5 border border-primary/20 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 cursor-pointer hover:shadow-md transition-all group/part">
                <div className="flex items-center gap-3">
                  <div className="flex -space-x-2.5 overflow-hidden py-1">
                    {participantsList.slice(0, 4).map((p, idx) => (
                      <div
                        key={p.id}
                        className={`w-9 h-9 rounded-full border-2 border-white flex items-center justify-center text-xs font-black shadow-xs ${
                          AVATAR_COLORS[idx % AVATAR_COLORS.length]
                        }`}>
                        {p.name.charAt(0).toUpperCase()}
                      </div>
                    ))}
                    {attendeesCount > 4 && (
                      <div className="w-9 h-9 rounded-full border-2 border-white bg-zinc-800 text-white flex items-center justify-center text-[10px] font-black shadow-xs">
                        +{attendeesCount - 4}
                      </div>
                    )}
                  </div>
                  <div>
                    <h4 className="text-xs font-black text-foreground group-hover/part:text-primary transition-colors">
                      {attendeesCount} Registered{' '}
                      {attendeesCount === 1 ? 'Colleague' : 'Colleagues'}
                    </h4>
                    <p className="text-[11px] text-muted font-medium">
                      See who is attending from Engineering, Product, HR and other teams.
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-1.5 text-xs font-black text-primary group-hover/part:translate-x-1 transition-transform">
                  <span>View Full Roster</span>
                  <ChevronRight size={14} />
                </div>
              </div>

              {/* Host & Department Metadata */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="p-5 rounded-3xl bg-surface-subtle/50 border border-border-subtle flex items-center justify-between gap-4">
                  <div className="min-w-0">
                    <span className="text-[10px] font-black text-muted uppercase tracking-wider block">
                      Organized By
                    </span>
                    <p className="text-sm font-black text-foreground mt-0.5 truncate">
                      {event.organizer || event.author_name || 'AetherERP Events Team'}
                    </p>
                    {event.author_email && (
                      <span className="text-xs text-muted font-medium truncate block mt-0.5">
                        {event.author_email}
                      </span>
                    )}
                  </div>
                </div>

                <div className="p-5 rounded-3xl bg-surface-subtle/50 border border-border-subtle flex items-center justify-between gap-4">
                  <div className="min-w-0">
                    <span className="text-[10px] font-black text-muted uppercase tracking-wider block">
                      Department / Wing
                    </span>
                    <p className="text-sm font-black text-foreground mt-0.5 truncate">
                      {event.author_department || 'All Company Departments'}
                    </p>
                    <span className="text-xs text-muted font-medium block mt-0.5">
                      Internal Corporate Event
                    </span>
                  </div>
                  <div className="w-11 h-11 rounded-2xl bg-white flex items-center justify-center text-primary border border-border-subtle shadow-xs flex-shrink-0">
                    <Building2 size={18} />
                  </div>
                </div>
              </div>

              {/* Tags */}
              {event.tags && event.tags.length > 0 && (
                <div className="flex flex-wrap items-center gap-2">
                  <span className="text-xs font-black text-muted uppercase tracking-wider mr-1 flex items-center gap-1">
                    <Tag size={12} /> Tags:
                  </span>
                  {event.tags.map((tag) => (
                    <span
                      key={tag}
                      className="px-3 py-1 rounded-xl text-xs font-bold text-primary bg-primary/10 border border-primary/20">
                      #{tag}
                    </span>
                  ))}
                </div>
              )}
            </>
          ) : activeTab === 'participants' ? (
            /* Joined Participants Roster View */
            <div className="flex flex-col gap-6 animate-in fade-in duration-200">
              {/* Header with Search & Stats */}
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-5 rounded-3xl bg-surface-subtle/70 border border-border-subtle">
                <div className="flex items-center gap-3">
                  <div className="w-11 h-11 rounded-2xl bg-primary/10 text-primary flex items-center justify-center flex-shrink-0 shadow-xs">
                    <UserCheck size={22} />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="text-sm font-black text-foreground uppercase tracking-wider">
                        Registered Participants
                      </h3>
                      <Badge
                        variant="primary"
                        className="text-[10px] font-black px-2 py-0.5 rounded-lg">
                        {attendeesCount} Joined
                      </Badge>
                    </div>
                    <p className="text-xs text-muted font-medium mt-0.5">
                      Live attendee roster for {event.title}
                    </p>
                  </div>
                </div>

                <div className="relative w-full sm:w-64">
                  <Search
                    size={15}
                    className="absolute left-3.5 top-1/2 -translate-y-1/2 text-muted"
                  />
                  <Input
                    value={participantSearch}
                    onChange={(e) => setParticipantSearch(e.target.value)}
                    placeholder="Search by name, email..."
                    className="pl-10! h-10! text-xs! bg-white! rounded-xl!"
                  />
                </div>
              </div>

              {/* Participant Cards List */}
              {filteredParticipants.length === 0 ? (
                <div className="py-14 px-6 rounded-3xl border-2 border-dashed border-border-strong bg-surface-subtle/50 flex flex-col items-center justify-center text-center gap-3">
                  <div className="w-14 h-14 rounded-2xl bg-white flex items-center justify-center text-muted border border-border-subtle shadow-xs">
                    <Users size={26} className="text-primary/70" />
                  </div>
                  <div>
                    <h4 className="text-sm font-black text-foreground">
                      {participantSearch
                        ? 'No matching participants found'
                        : 'No participants registered yet'}
                    </h4>
                    <p className="text-xs text-muted font-medium mt-0.5">
                      {participantSearch
                        ? 'Try searching with another name or department.'
                        : 'Be the first to confirm attendance for this event!'}
                    </p>
                  </div>
                  {!isRegistered && !isPast && (
                    <Button
                      variant="primary"
                      onClick={() => onRegister(event)}
                      disabled={isRegistering}
                      className="mt-2 h-10 rounded-xl font-bold text-xs gap-1.5 cursor-pointer">
                      <ArrowUpRight size={14} />
                      <span>Register Now</span>
                    </Button>
                  )}
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
                  {filteredParticipants.map((participant, index) => {
                    const isCurrentUser =
                      user?.email && participant.email.toLowerCase() === user.email.toLowerCase();
                    const avatarBg = AVATAR_COLORS[index % AVATAR_COLORS.length];

                    return (
                      <div
                        key={participant.id}
                        className={`p-4 rounded-2xl border transition-all flex items-center justify-between gap-3 ${
                          isCurrentUser
                            ? 'bg-primary/5 border-primary/30 shadow-sm'
                            : 'bg-white border-border-subtle shadow-xs hover:border-primary/20 hover:shadow-sm'
                        }`}>
                        <div className="flex items-center gap-3.5 min-w-0">
                          <div
                            className={`w-11 h-11 rounded-2xl flex items-center justify-center text-sm font-black shadow-xs flex-shrink-0 ${avatarBg}`}>
                            {participant.name.charAt(0).toUpperCase()}
                          </div>
                          <div className="min-w-0 flex-1">
                            <div className="flex items-center gap-1.5">
                              <h4 className="text-xs font-black text-foreground truncate">
                                {participant.name}
                              </h4>
                              {isCurrentUser && (
                                <span className="text-[10px] font-black px-1.5 py-0.2 rounded-md bg-primary text-white uppercase tracking-wider">
                                  You
                                </span>
                              )}
                            </div>
                            <div className="flex items-center gap-1.5 text-[11px] text-muted truncate mt-0.5 font-medium">
                              <Mail size={11} className="flex-shrink-0" />
                              <span className="truncate">{participant.email}</span>
                            </div>
                            <span className="text-[10px] text-muted/80 block mt-0.5">
                              {participant.joinedAt}
                            </span>
                          </div>
                        </div>

                        <div className="flex flex-col items-end gap-1.5 flex-shrink-0">
                          <span className="px-2.5 py-0.8 rounded-lg text-[10px] font-bold bg-surface-subtle text-foreground border border-border-subtle whitespace-nowrap">
                            {participant.department || 'Corporate'}
                          </span>
                          <span className="flex items-center gap-1 text-[10px] font-extrabold text-emerald-600 bg-emerald-500/10 border border-emerald-500/20 px-2 py-0.5 rounded-md whitespace-nowrap">
                            <CheckCircle2 size={10} /> Confirmed
                          </span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          ) : (
            <EventMediaUploader
              eventId={event.id}
              eventTitle={event.title}
              initialAttachments={event.media_attachments}
            />
          )}
        </div>

        {/* Modal Footer Action Bar */}
      </div>
    </Dialog>
  );
};

import { useState, useMemo } from 'react';
import { Dialog } from '@/components/ui/composed/Dialog';
import { Button } from '@/components/ui/primitives/Button';
import { Input } from '@/components/ui/primitives/Input';
import {
  Filter,
  Calendar as CalendarIcon,
  Tag,
  UserCheck,
  Building2,
  RotateCcw,
  Plus,
} from 'lucide-react';
import type { EventFilters, FilterOptions } from '@/types/models';

interface EventFilterDrawerProps {
  visible: boolean;
  onHide: () => void;
  filters: EventFilters;
  filterOptions?: FilterOptions;
  onFilterChange: (newFilters: EventFilters) => void;
  onResetFilters: () => void;
}

export const EventFilterDrawer = ({
  visible,
  onHide,
  filters,
  filterOptions,
  onFilterChange,
  onResetFilters,
}: EventFilterDrawerProps) => {
  const [customTags, setCustomTags] = useState<string[]>([]);
  const [customTagInput, setCustomTagInput] = useState('');

  const categories = filterOptions?.categories || [];
  const initialTags = filterOptions?.tags || [];
  const employeeStatuses = filterOptions?.employeeStatuses || [];
  const departments = filterOptions?.departments || [];

  const allTags = useMemo(
    () => Array.from(new Set([...initialTags, ...customTags, ...(filters.tags || [])])),
    [initialTags, customTags, filters.tags]
  );

  const handleAddCustomTag = () => {
    const trimmed = customTagInput.trim();
    if (trimmed && !allTags.includes(trimmed)) {
      setCustomTags((prev) => [...prev, trimmed]);
      onFilterChange({ ...filters, tags: [...(filters.tags || []), trimmed] });
    }
    setCustomTagInput('');
  };

  const handleTagToggle = (tag: string) => {
    const currentTags = filters.tags || [];
    const newTags = currentTags.includes(tag)
      ? currentTags.filter((t) => t !== tag)
      : [...currentTags, tag];
    onFilterChange({ ...filters, tags: newTags });
  };

  const handleStatusToggle = (status: string) => {
    const currentStatuses = filters.employee_statuses || [];
    const newStatuses = currentStatuses.includes(status)
      ? currentStatuses.filter((s) => s !== status)
      : [...currentStatuses, status];
    onFilterChange({ ...filters, employee_statuses: newStatuses });
  };

  const handleDepartmentToggle = (dept: string) => {
    const currentDepts = filters.departments || [];
    const newDepts = currentDepts.includes(dept)
      ? currentDepts.filter((d) => d !== dept)
      : [...currentDepts, dept];
    onFilterChange({ ...filters, departments: newDepts });
  };

  const activeCount =
    (filters.category && filters.category !== 'All' ? 1 : 0) +
    (filters.tags?.length || 0) +
    (filters.employee_statuses?.length || 0) +
    (filters.departments?.length || 0) +
    (filters.start_date ? 1 : 0) +
    (filters.end_date ? 1 : 0) +
    (filters.search ? 1 : 0);

  return (
    <Dialog
      visible={visible}
      onHide={onHide}
      header="Filter Calendar & Events"
      modal
      className="w-full max-w-2xl mx-4"
      contentClassName="p-8"
      headerClassName="px-8 pt-8 pb-4 text-2xl font-black tracking-tight border-none"
      pt={{
        root: { className: 'rounded-[40px] overflow-hidden border-none shadow-2xl bg-white' },
        mask: { className: 'backdrop-blur-md bg-black/40' },
      }}>
      <div className="flex flex-col gap-6">
        {/* Subtitle & Active Filters Bar */}
        <div className="flex items-center justify-between pb-4 border-b border-border-subtle">
          <div className="flex items-center gap-2 text-xs font-bold text-muted uppercase tracking-wider">
            <Filter size={16} className="text-primary" />
            <span>Refine event results with active database dynamic filters</span>
          </div>
          {activeCount > 0 && (
            <Button
              variant="ghost"
              onClick={onResetFilters}
              className="text-xs font-black text-red-500 hover:text-red-600 gap-1.5 p-0! h-auto!">
              <RotateCcw size={14} />
              Reset All ({activeCount})
            </Button>
          )}
        </div>

        {/* Categories */}
        {categories.length > 0 && (
          <div className="flex flex-col gap-3">
            <label className="text-xs font-black text-foreground uppercase tracking-wider flex items-center gap-2">
              <Tag size={14} className="text-primary" />
              Category
            </label>
            <div className="flex flex-wrap gap-2">
              <button
                type="button"
                className={`px-4 py-2 rounded-2xl font-black text-xs transition-all border ${
                  !filters.category || filters.category === 'All'
                    ? 'bg-primary text-white border-primary'
                    : 'bg-surface-subtle text-foreground border-border-subtle hover:border-primary/40'
                }`}
                onClick={() => onFilterChange({ ...filters, category: 'All' })}>
                All Categories
              </button>
              {categories.map((cat) => (
                <button
                  key={cat}
                  type="button"
                  className={`px-4 py-2 rounded-2xl font-bold text-xs transition-all border ${
                    filters.category === cat
                      ? 'bg-primary text-white border-primary font-black'
                      : 'bg-surface-subtle text-foreground border-border-subtle hover:border-primary/40'
                  }`}
                  onClick={() => onFilterChange({ ...filters, category: cat })}>
                  {cat}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Employee Status (Single Source of Truth) */}
        {employeeStatuses.length > 0 && (
          <div className="flex flex-col gap-3">
            <label className="text-xs font-black text-foreground uppercase tracking-wider flex items-center gap-2">
              <UserCheck size={14} className="text-primary" />
              Employee Status Filter
            </label>
            <p className="text-[11px] text-muted font-medium">
              Dynamically matches author status in real-time
            </p>
            <div className="flex flex-wrap gap-2">
              {employeeStatuses.map((st) => {
                const isSelected = filters.employee_statuses?.includes(st);
                return (
                  <button
                    key={st}
                    type="button"
                    onClick={() => handleStatusToggle(st)}
                    className={`px-3 py-1.5 rounded-2xl text-xs font-black tracking-wide border transition-all ${
                      isSelected
                        ? 'bg-primary text-white border-primary shadow-sm'
                        : 'bg-surface-subtle text-foreground border-border-subtle hover:border-primary/30'
                    }`}>
                    {st}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Event Tags */}
        <div className="flex flex-col gap-3">
          <div className="flex items-center justify-between">
            <label className="text-xs font-black text-foreground uppercase tracking-wider flex items-center gap-2">
              <Tag size={14} className="text-primary" />
              Event Tags & Dynamic Filters
            </label>
            <span className="text-[11px] text-muted font-medium">Click to toggle filter</span>
          </div>

          {/* Quick Add Custom Filter Tag */}
          <div className="flex gap-2">
            <Input
              id="filter-custom-tag"
              value={customTagInput}
              onChange={(e) => setCustomTagInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleAddCustomTag();
                }
              }}
              placeholder="Add new filter tag (e.g. AI, Q4)..."
              className="flex-1 text-xs"
            />
            <Button
              type="button"
              variant="secondary"
              onClick={handleAddCustomTag}
              className="rounded-xl! px-3.5! text-xs font-bold gap-1 cursor-pointer">
              <Plus size={14} /> Add Tag
            </Button>
          </div>

          {allTags.length > 0 && (
            <div className="flex flex-wrap gap-2 max-h-36 overflow-y-auto p-1.5 border border-border-subtle/50 rounded-2xl bg-surface-subtle/30">
              {allTags.map((t) => {
                const isSelected = filters.tags?.includes(t);
                return (
                  <button
                    key={t}
                    type="button"
                    onClick={() => handleTagToggle(t)}
                    className={`px-3 py-1 rounded-xl text-[11px] font-bold border transition-all cursor-pointer ${
                      isSelected
                        ? 'bg-primary text-white border-primary shadow-xs font-black'
                        : 'bg-white text-muted border-border-subtle hover:text-foreground hover:border-primary/40'
                    }`}>
                    #{t}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Department Filter */}
        {departments.length > 0 && (
          <div className="flex flex-col gap-3">
            <label className="text-xs font-black text-foreground uppercase tracking-wider flex items-center gap-2">
              <Building2 size={14} className="text-primary" />
              Department
            </label>
            <div className="flex flex-wrap gap-2">
              {departments.map((dept) => {
                const isSelected = filters.departments?.includes(dept);
                return (
                  <button
                    key={dept}
                    type="button"
                    onClick={() => handleDepartmentToggle(dept)}
                    className={`px-3.5 py-1.5 rounded-2xl text-xs font-bold border transition-all ${
                      isSelected
                        ? 'bg-foreground text-white border-foreground font-black'
                        : 'bg-surface-subtle text-muted border-border-subtle hover:text-foreground'
                    }`}>
                    {dept}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Date Range Filter */}
        <div className="flex flex-col gap-3">
          <label className="text-xs font-black text-foreground uppercase tracking-wider flex items-center gap-2">
            <CalendarIcon size={14} className="text-primary" />
            Date Range
          </label>
          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-1">
              <span className="text-[10px] font-bold text-muted uppercase">From</span>
              <Input
                type="date"
                value={filters.start_date || ''}
                onChange={(e) => onFilterChange({ ...filters, start_date: e.target.value })}
                className="h-10! text-xs!"
              />
            </div>
            <div className="flex flex-col gap-1">
              <span className="text-[10px] font-bold text-muted uppercase">To</span>
              <Input
                type="date"
                value={filters.end_date || ''}
                onChange={(e) => onFilterChange({ ...filters, end_date: e.target.value })}
                className="h-10! text-xs!"
              />
            </div>
          </div>
        </div>

        {/* Actions */}
        <div className="flex items-center justify-end gap-3 pt-6 border-t border-border-subtle">
          <Button
            variant="secondary"
            onClick={onHide}
            className="h-11 rounded-2xl! px-6 font-bold text-xs border-border-subtle!">
            Close
          </Button>
          <Button
            onClick={onHide}
            className="h-11 rounded-2xl! px-8 font-black text-xs uppercase tracking-wider bg-primary text-white">
            Apply Filters {activeCount > 0 ? `(${activeCount})` : ''}
          </Button>
        </div>
      </div>
    </Dialog>
  );
};

import { resolveImageUrl } from '@/utils/imageUrl';
import { FormField } from '@/components/ui/composed/FormField';
import { Button } from '@/components/ui/primitives/Button';
import { Calendar } from '@/components/ui/primitives/Calendar';
import { Input } from '@/components/ui/primitives/Input';
import { Select } from '@/components/ui/primitives/Select';
import { Textarea } from '@/components/ui/primitives/Textarea';
import { useEffect, useState, useRef, useMemo } from 'react';
import {
  Sparkles,
  PartyPopper,
  Wrench,
  Mic,
  Rocket,
  Plus,
  X,
  Image as ImageIcon,
  Loader2,
  Upload,
  PlusCircle,
  Mail,
} from 'lucide-react';
import type { ERPEvent } from '@/types/models';
import { useUploadFileMutation } from '@/store/api/eventSlice';
import { showToast } from '@/components/ui/composed/Toast.utils';
import { TimePicker } from 'antd';
import dayjs from 'dayjs';
import customParseFormat from 'dayjs/plugin/customParseFormat';

dayjs.extend(customParseFormat);

interface EventFormProps {
  initialData?: ERPEvent | null;
  onSubmit: (data: Partial<ERPEvent>) => void;
  onCancel: () => void;
  availableCategories?: string[];
}

const DEFAULT_CATEGORIES = ['Conference', 'Workshop', 'Social', 'Meeting'];

interface EventTemplatePreset {
  label: string;
  icon: typeof PartyPopper;
  category: string;
  title: string;
  description: string;
  location: string;
  organizer: string;
  author_department: string;
  time: string;
  start_time: string;
  end_time: string;
  max_participants: number;
  image: string;
}

const TEMPLATE_PRESETS: EventTemplatePreset[] = [
  {
    label: 'Social Party',
    icon: PartyPopper,
    category: 'Social',
    title: 'Team Social Celebration',
    description: 'Monthly team gathering to celebrate wins, birthdays, and milestones together.',
    location: 'Rooftop Lounge & Terrace',
    organizer: 'Culture & Welfare Team',
    author_department: 'People Operations',
    time: '5:00 PM - 8:00 PM',
    start_time: '05:00 PM',
    end_time: '08:00 PM',
    max_participants: 100,
    image:
      'https://images.unsplash.com/photo-1511795409834-ef04bbd61622?w=800&auto=format&fit=crop&q=60',
  },
  {
    label: 'Tech Workshop',
    icon: Wrench,
    category: 'Workshop',
    title: 'Frontend & AI Engineering Workshop',
    description:
      'Interactive hands-on session exploring next-gen frontend tools and LLM integrations.',
    location: 'Innovation Lab Room 4',
    organizer: 'Engineering Team',
    author_department: 'Engineering',
    time: '2:00 PM - 5:00 PM',
    start_time: '02:00 PM',
    end_time: '05:00 PM',
    max_participants: 50,
    image:
      'https://images.unsplash.com/photo-1531482615713-2afd69097998?w=800&auto=format&fit=crop&q=60',
  },
  {
    label: 'Town Hall',
    icon: Mic,
    category: 'Meeting',
    title: 'Quarterly All-Hands Town Hall',
    description:
      'Company-wide updates, strategic roadmap overview, and open Q&A session with leadership.',
    location: 'Main Auditorium / Hybrid',
    organizer: 'Executive Board',
    author_department: 'Executive',
    time: '11:00 AM - 1:00 PM',
    start_time: '11:00 AM',
    end_time: '01:00 PM',
    max_participants: 250,
    image:
      'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=800&auto=format&fit=crop&q=60',
  },
  {
    label: 'Product Launch',
    icon: Rocket,
    category: 'Conference',
    title: 'AetherERP v2.0 Keynote Launch',
    description: 'Official unveiling of the next-generation ERP platform and feature showcase.',
    location: 'Grand Conference Center',
    organizer: 'Product Operations',
    author_department: 'Product',
    time: '10:00 AM - 12:30 PM',
    start_time: '10:00 AM',
    end_time: '12:30 PM',
    max_participants: 500,
    image:
      'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=800&auto=format&fit=crop&q=60',
  },
];

export const EventForm = ({
  initialData,
  onSubmit,
  onCancel,
  availableCategories,
}: EventFormProps) => {
  const [uploadFile, { isLoading: isUploadingImage }] = useUploadFileMutation();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [newTagInput, setNewTagInput] = useState('');

  const STANDARD_STATUSES = ['Upcoming', 'Active', 'Completed', 'Inactive'];

  const baseCategoryList = useMemo(() => {
    const list =
      availableCategories && availableCategories.length > 0
        ? availableCategories
        : DEFAULT_CATEGORIES;
    return Array.from(new Set([...list, ...DEFAULT_CATEGORIES]));
  }, [availableCategories]);

  const [selectedCategoryType, setSelectedCategoryType] = useState<string>(
    initialData?.category && !baseCategoryList.includes(initialData.category)
      ? 'Other'
      : initialData?.category || 'Workshop'
  );
  const [customCategoryInput, setCustomCategoryInput] = useState<string>(
    initialData?.category && !baseCategoryList.includes(initialData.category)
      ? initialData.category
      : ''
  );

  const [selectedStatusType, setSelectedStatusType] = useState<string>(() => {
    const st = initialData?.status;
    if (!st) return 'Upcoming';
    const match = STANDARD_STATUSES.find((s) => s.toLowerCase() === st.toLowerCase());
    return match || 'Custom';
  });

  const [customStatusInput, setCustomStatusInput] = useState<string>(() => {
    const st = initialData?.status;
    if (!st) return '';
    const isStd = STANDARD_STATUSES.some((s) => s.toLowerCase() === st.toLowerCase());
    return isStd ? '' : st;
  });

  const handleStatusSelection = (val: string) => {
    setSelectedStatusType(val);
    if (val !== 'Custom') {
      setFormData((prev) => ({ ...prev, status: val }));
    } else {
      setFormData((prev) => ({ ...prev, status: customStatusInput.trim() || 'Custom' }));
    }
  };

  const handleCustomStatusChange = (val: string) => {
    setCustomStatusInput(val);
    setFormData((prev) => ({ ...prev, status: val.trim() || 'Custom' }));
  };

  const categoryOptions = useMemo(() => {
    const opts = baseCategoryList.map((cat) => ({ label: cat, value: cat }));
    return [...opts, { label: 'Other (Enter Custom)', value: 'Other' }];
  }, [baseCategoryList]);

  const [formData, setFormData] = useState<Partial<ERPEvent>>({
    title: '',
    description: '',
    category: 'Workshop',
    date: '',
    time: '10:00 AM - 1:00 PM',
    start_time: '10:00 AM',
    end_time: '01:00 PM',
    location: '',
    organizer: '',
    author_department: '',
    status: 'Upcoming',
    employee_status: 'Active',
    attendees: 0,
    button_type: 'Register Now',
    event_link: '',
    broadcast: true,
    tags: [],
    image:
      'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=1200&auto=format&fit=crop&q=80',
  });

  const handleImageFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const res = await uploadFile(file).unwrap();
      if (res.url) {
        setFormData((prev) => ({
          ...prev,
          image: res.url,
          image_url: res.url,
        }));
        showToast({
          severity: 'success',
          summary: 'Banner Uploaded',
          detail: 'Event banner image uploaded successfully!',
          life: 3000,
        });
      }
    } catch (err: unknown) {
      const apiError = err as { data?: { message?: string }; message?: string };
      console.error('Failed to upload image:', err);
      showToast({
        severity: 'error',
        summary: 'Upload Failed',
        detail: apiError?.data?.message || apiError?.message || 'Failed to upload banner image',
        life: 3500,
      });
    }
  };

  useEffect(() => {
    if (initialData) {
      queueMicrotask(() => {
        const rawDate = initialData.event_date || initialData.date || '';
        let startTime = initialData.start_time || '';
        let endTime = initialData.end_time || '';
        if ((!startTime || !endTime) && initialData.time) {
          const parts = initialData.time.split('-');
          if (!startTime && parts[0]) startTime = parts[0].trim();
          if (!endTime && parts[1]) endTime = parts[1].trim();
        }

        setFormData({
          ...initialData,
          date: rawDate,
          event_date: rawDate,
          start_time: startTime || '10:00 AM',
          end_time: endTime || '01:00 PM',
          status: initialData.status || 'Upcoming',
          max_participants: initialData.max_participants,
          employee_status: initialData.employee_status || 'Active',
        });

        // Check if existing category matches standard categories or if it is a custom category
        const initialCat = initialData.category || 'Workshop';
        if (baseCategoryList.includes(initialCat)) {
          setSelectedCategoryType(initialCat);
          setCustomCategoryInput('');
        } else {
          setSelectedCategoryType('Other');
          setCustomCategoryInput(initialCat);
        }

        const rawStatus = initialData.status || 'Upcoming';
        const stdMatch = STANDARD_STATUSES.find((s) => s.toLowerCase() === rawStatus.toLowerCase());
        if (stdMatch) {
          setSelectedStatusType(stdMatch);
          setCustomStatusInput('');
        } else {
          setSelectedStatusType('Custom');
          setCustomStatusInput(rawStatus);
        }
      });
    }
  }, [initialData, baseCategoryList.join(',')]);

  const handleCategorySelection = (val: string) => {
    setSelectedCategoryType(val);
    if (val !== 'Other') {
      setFormData((prev) => ({ ...prev, category: val }));
    } else {
      setFormData((prev) => ({ ...prev, category: customCategoryInput.trim() || 'Other' }));
    }
  };

  const handleCustomCategoryChange = (val: string) => {
    setCustomCategoryInput(val);
    setFormData((prev) => ({ ...prev, category: val.trim() || 'Other' }));
  };

  const applyTemplate = (preset: (typeof TEMPLATE_PRESETS)[0]) => {
    setSelectedStatusType('Upcoming');
    setCustomStatusInput('');
    setFormData((prev) => ({
      ...prev,
      title: preset.title,
      category: preset.category,
      description: preset.description,
      location: preset.location,
      organizer: preset.organizer,
      author_department: preset.author_department,
      time: preset.time,
      start_time: preset.start_time,
      end_time: preset.end_time,
      max_participants: preset.max_participants,
      status: 'Upcoming',
      image: preset.image,
    }));
  };

  const handleAddTag = () => {
    const raw = newTagInput.trim();
    if (!raw) return;
    const tokens = raw
      .split(/[,]+/)
      .map((t) => t.trim().replace(/^#/, ''))
      .filter((t) => t.length > 0);
    if (tokens.length === 0) return;

    const currentTags = formData.tags || [];
    const merged = Array.from(new Set([...currentTags, ...tokens]));
    setFormData((prev) => ({ ...prev, tags: merged }));
    setNewTagInput('');
  };

  const handleToggleTag = (tag: string) => {
    const clean = tag.replace(/^#/, '').trim();
    const current = formData.tags || [];
    if (current.includes(clean)) {
      setFormData((prev) => ({ ...prev, tags: current.filter((t) => t !== clean) }));
    } else {
      setFormData((prev) => ({ ...prev, tags: [...current, clean] }));
    }
  };

  const handleRemoveTag = (tagToRemove: string) => {
    setFormData((prev) => ({
      ...prev,
      tags: (prev.tags || []).filter((t) => t !== tagToRemove),
    }));
  };

  const buttonTypeOptions = [
    { label: 'Register Now (Standard RSVP)', value: 'Register Now' },
    { label: 'Mandatory (Required Attendance)', value: 'Mandatory' },
    { label: 'View Details (Informational / External)', value: 'View Details' },
  ];

  return (
    <div className="flex flex-col gap-6">
      {/* Quick Presets Bar */}
      {!initialData && (
        <div className="p-4 rounded-2xl bg-primary/5 border border-primary/15 flex flex-col gap-2.5">
          <div className="flex items-center gap-1.5 text-xs font-black text-primary uppercase tracking-wider">
            <Sparkles size={14} />
            <span>Quick Event Presets (Click to autofill)</span>
          </div>
          <div className="flex flex-wrap gap-2">
            {TEMPLATE_PRESETS.map((preset) => {
              const IconComponent = preset.icon;
              return (
                <button
                  key={preset.label}
                  type="button"
                  onClick={() => applyTemplate(preset)}
                  className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-white hover:bg-primary hover:text-white text-xs font-bold text-foreground border border-border-subtle shadow-xs transition-all cursor-pointer group">
                  <IconComponent
                    size={14}
                    className="text-primary group-hover:text-white transition-colors"
                  />
                  <span>{preset.label}</span>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Banner Image Uploader & Preview Box */}
      <div className="p-4.5 rounded-3xl bg-surface-subtle/70 border border-border-subtle flex flex-col gap-3">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <label className="text-xs font-black text-foreground uppercase tracking-wider flex items-center gap-1.5">
            <ImageIcon size={15} className="text-primary" />
            <span>Event Banner Image (Upload to Hostinger)</span>
          </label>
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleImageFileChange}
            accept="image/*"
            className="hidden"
          />
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={isUploadingImage}
            className="px-3.5 py-1.5 rounded-xl bg-primary text-white hover:bg-primary/90 text-xs font-black uppercase tracking-wider flex items-center gap-1.5 shadow-md cursor-pointer transition-all disabled:opacity-50">
            {isUploadingImage ? (
              <>
                <Loader2 size={13} className="animate-spin" />
                <span>Uploading Image...</span>
              </>
            ) : (
              <>
                <Upload size={13} />
                <span>Upload New Banner Image</span>
              </>
            )}
          </button>
        </div>

        {/* Live Banner Preview */}
        <div className="relative h-44 w-full rounded-2xl overflow-hidden bg-zinc-900 border border-border-subtle group/banner">
          <img
            src={
              resolveImageUrl(formData.image || formData.image_url || '') ||
              'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?w=800&auto=format&fit=crop&q=60'
            }
            alt="Event banner preview"
            className="w-full h-full object-cover group-hover/banner:scale-105 transition-transform duration-500"
            onError={(e) => {
              (e.target as HTMLImageElement).src =
                'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?w=800&auto=format&fit=crop&q=60';
            }}
          />
          <div className="absolute inset-0 bg-linear-to-t from-black/80 via-black/20 to-transparent flex items-end justify-between p-3.5">
            <span className="text-[11px] font-bold text-white/90 bg-black/50 backdrop-blur-md px-2.5 py-1 rounded-lg truncate max-w-[80%] border border-white/10">
              {formData.image || formData.image_url || 'Default Banner Image'}
            </span>
            {isUploadingImage && (
              <span className="text-[10px] font-black text-amber-300 bg-black/60 px-2 py-1 rounded-md animate-pulse">
                Saving to Hostinger...
              </span>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="flex flex-col gap-5">
          <FormField label="Event Title" required id="event-title">
            <Input
              id="event-title"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              placeholder="e.g. Annual Tech Summit"
            />
          </FormField>

          <FormField label="Description" id="event-description">
            <Textarea
              id="event-description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="Tell us what this event is about..."
              rows={3}
            />
          </FormField>

          {/* Category Dropdown + Dynamic "Other" Custom Category Input */}
          <div className="flex flex-col gap-3 p-4 rounded-2xl bg-surface-subtle/70 border border-border-subtle">
            <FormField label="Category" required id="event-category">
              <Select
                id="event-category"
                options={categoryOptions}
                value={selectedCategoryType}
                onChange={(e) => handleCategorySelection(e.value)}
              />
            </FormField>

            {/* Dynamic Custom Category Text Input */}
            {selectedCategoryType === 'Other' && (
              <div className="flex flex-col gap-1.5 pt-2 border-t border-border-subtle/80 animate-in fade-in slide-in-from-top-2 duration-200">
                <label
                  htmlFor="custom-category-input"
                  className="text-xs font-black text-primary uppercase tracking-wider flex items-center gap-1.5">
                  <PlusCircle size={13} />
                  <span>Enter Custom Category</span>
                </label>
                <Input
                  id="custom-category-input"
                  value={customCategoryInput}
                  onChange={(e) => handleCustomCategoryChange(e.target.value)}
                  placeholder="e.g., Hackathon, Product Showcase, Webinar"
                  className="bg-white! border-primary/40! focus:border-primary! ring-primary/20!"
                  autoFocus
                />
                <span className="text-[11px] text-muted font-medium">
                  This custom category will be saved and dynamically attached to your event.
                </span>
              </div>
            )}
          </div>

          {/* Event Status — Dropdown + optional Manual input */}
          <div className="flex flex-col gap-2.5 p-4 rounded-2xl bg-surface-subtle/70 border border-border-subtle">
            <FormField label="Event Status" id="event-status">
              <Select
                id="event-status"
                options={[
                  { label: 'Upcoming', value: 'Upcoming' },
                  { label: 'Active', value: 'Active' },
                  { label: 'Completed', value: 'Completed' },
                  { label: 'Inactive', value: 'Inactive' },
                  { label: 'Other', value: 'Other' },
                ]}
                value={selectedStatusType}
                onChange={(e) => handleStatusSelection(e.value)}
              />
            </FormField>

            {/* Custom text input — only shown when Manual is selected */}
            {selectedStatusType === 'Other' && (
              <div className="flex flex-col gap-1.5 pt-2 border-t border-border-subtle/80 animate-in fade-in slide-in-from-top-2 duration-200">
                <label
                  htmlFor="custom-status-input"
                  className="text-xs font-black text-primary uppercase tracking-wider flex items-center gap-1.5">
                  <PlusCircle size={13} />
                  <span>Add Status</span>
                </label>
                <Input
                  id="custom-status-input"
                  value={customStatusInput}
                  onChange={(e) => handleCustomStatusChange(e.target.value)}
                  placeholder="e.g. Postponed, Draft, Registrations Full…"
                  className="bg-white! border-primary/40! focus:border-primary! ring-primary/20!"
                  autoFocus
                />
                <span className="text-[11px] text-muted font-medium">
                  This status will appear live on the event card badge.
                </span>
              </div>
            )}
          </div>
        </div>

        {/* Right Column: Schedule, Location, Host & Capacity */}
        <div className="flex flex-col gap-5">
          <FormField label="Event Date" required id="event-date">
            <Calendar
              id="event-date"
              value={
                formData.date || formData.event_date
                  ? new Date(formData.date || formData.event_date || '')
                  : null
              }
              onChange={(e) => {
                const selected = e.value as Date | null;
                if (selected) {
                  const year = selected.getFullYear();
                  const month = String(selected.getMonth() + 1).padStart(2, '0');
                  const day = String(selected.getDate()).padStart(2, '0');
                  const formatted = `${year}-${month}-${day} 10:00:00`;
                  setFormData((prev) => ({
                    ...prev,
                    date: formatted,
                    event_date: formatted,
                  }));
                } else {
                  setFormData((prev) => ({
                    ...prev,
                    date: '',
                    event_date: '',
                  }));
                }
              }}
              placeholder="Select event date"
              dateFormat="yy-mm-dd"
            />
          </FormField>

          <div className="grid grid-cols-2 gap-4">
            <FormField label="Start Time" id="event-start-time">
              <TimePicker
                id="event-start-time"
                use12Hours
                format="hh:mm A"
                minuteStep={15}
                needConfirm={false}
                value={
                  formData.start_time
                    ? dayjs(formData.start_time, ['hh:mm A', 'h:mm A', 'HH:mm', 'H:mm'])
                    : null
                }
                onChange={(_time: dayjs.Dayjs | null, dateString: string | null) => {
                  const str = typeof dateString === 'string' ? dateString : '';
                  setFormData((prev) => ({
                    ...prev,
                    start_time: str,
                    time: str && prev.end_time ? `${str} - ${prev.end_time}` : str || prev.time,
                  }));
                }}
                placeholder="Start time"
                className="w-full h-11 rounded-xl border border-border-subtle bg-white font-medium hover:border-primary/50 focus:border-primary shadow-xs"
              />
            </FormField>
            <FormField label="End Time" id="event-end-time">
              <TimePicker
                id="event-end-time"
                use12Hours
                format="hh:mm A"
                minuteStep={15}
                needConfirm={false}
                value={
                  formData.end_time
                    ? dayjs(formData.end_time, ['hh:mm A', 'h:mm A', 'HH:mm', 'H:mm'])
                    : null
                }
                onChange={(_time: dayjs.Dayjs | null, dateString: string | null) => {
                  const str = typeof dateString === 'string' ? dateString : '';
                  setFormData((prev) => ({
                    ...prev,
                    end_time: str,
                    time: prev.start_time && str ? `${prev.start_time} - ${str}` : str || prev.time,
                  }));
                }}
                placeholder="End time"
                className="w-full h-11 rounded-xl border border-border-subtle bg-white font-medium hover:border-primary/50 focus:border-primary shadow-xs"
              />
            </FormField>
          </div>

          <FormField label="Location / Venue" id="event-location">
            <Input
              id="event-location"
              value={formData.location}
              onChange={(e) => setFormData({ ...formData, location: e.target.value })}
              placeholder="e.g. SFA Technologies, 2nd Floor / Remote"
            />
          </FormField>

          <div className="grid grid-cols-2 gap-4">
            <FormField label="Organizer / Host" id="event-organizer">
              <Input
                id="event-organizer"
                value={formData.organizer}
                onChange={(e) => setFormData({ ...formData, organizer: e.target.value })}
                placeholder="Team / Host Name"
              />
            </FormField>
            <FormField label="Department" id="event-department">
              <Input
                id="event-department"
                value={formData.author_department || ''}
                onChange={(e) => setFormData({ ...formData, author_department: e.target.value })}
                placeholder="e.g. Engineering, HR"
              />
            </FormField>
          </div>

          <FormField label="Max Capacity (Limit)" id="event-max-capacity">
            <Input
              id="event-max-capacity"
              type="number"
              value={formData.max_participants?.toString() || ''}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  max_participants: parseInt(e.target.value, 10) || undefined,
                })
              }
              placeholder="e.g. 50 (Leave empty for unlimited attendance)"
            />
          </FormField>
        </div>
      </div>

      {/* Button Action Type & URL — full width */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 p-4 rounded-2xl bg-surface-subtle/70 border border-border-subtle">
        <div className="flex flex-col gap-1">
          <FormField label="Button Action Type" id="event-button-type">
            <Select
              id="event-button-type"
              options={buttonTypeOptions}
              value={formData.button_type || 'Register Now'}
              onChange={(e) => setFormData({ ...formData, button_type: e.value })}
            />
          </FormField>
          <span className="text-[10px] text-muted font-medium">
            Button attendees see on event card
          </span>
        </div>
        <div className="flex flex-col gap-1">
          <FormField label="Registration / External URL" id="event-link">
            <Input
              id="event-link"
              value={formData.event_link || ''}
              onChange={(e) => setFormData({ ...formData, event_link: e.target.value })}
              placeholder="https://... (Optional link)"
            />
          </FormField>
          <span className="text-[10px] text-muted font-medium">Zoom, Meet or external link</span>
        </div>

        {/* Instant Broadcast Notification Toggle */}
        <div className="sm:col-span-2 pt-3 mt-1 border-t border-border-subtle/80 flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-xl bg-primary/10 text-primary flex items-center justify-center flex-shrink-0">
              <Mail size={15} />
            </div>
            <div className="flex flex-col">
              <span className="text-xs font-black text-foreground flex items-center gap-1.5">
                <span>Broadcast Event to All Employees</span>
                <span className="text-[9px] font-black uppercase tracking-wider bg-emerald-500/15 text-emerald-600 border border-emerald-300 px-1.5 py-0.2 rounded-md">
                  Email &amp; Bell Alert
                </span>
              </span>
              <span className="text-[11px] text-muted font-medium">
                Sends an email invitation to all 18+ active employees and highlights this in their
                notification bell.
              </span>
            </div>
          </div>
          <label className="relative inline-flex items-center cursor-pointer ml-3 flex-shrink-0">
            <input
              type="checkbox"
              checked={formData.broadcast !== false}
              onChange={(e) => setFormData((prev) => ({ ...prev, broadcast: e.target.checked }))}
              className="sr-only peer"
            />
            <div className="w-11 h-6 bg-zinc-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-zinc-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary shadow-xs"></div>
          </label>
        </div>
      </div>

      {/* Tags — full width below the grid */}
      <div className="flex flex-col gap-2 p-4 rounded-2xl bg-surface-subtle/70 border border-border-subtle">
        <div className="flex items-center justify-between">
          <label className="text-[10px] font-black uppercase tracking-widest text-muted">
            Event Tags &amp; Dynamic Filters
          </label>
          <span className="text-[10px] font-bold text-primary bg-primary/10 px-2 py-0.5 rounded-md">
            Multi-tag supported (use comma)
          </span>
        </div>
        <div className="flex gap-2">
          <Input
            id="event-new-tag"
            value={newTagInput}
            onChange={(e) => setNewTagInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ',') {
                e.preventDefault();
                handleAddTag();
              }
            }}
            placeholder="Type multiple tags e.g. Payroll, Tech, Annual — press Enter or comma to add"
            className="flex-1 bg-white!"
          />
          <Button
            type="button"
            variant="secondary"
            onClick={handleAddTag}
            className="rounded-xl! px-4! text-xs font-bold gap-1 cursor-pointer bg-white!">
            <Plus size={14} /> Add
          </Button>
        </div>

        {/* Quick Tag Suggestions */}
        <div className="flex flex-wrap items-center gap-1.5 pt-1">
          <span className="text-[10px] font-bold text-muted uppercase tracking-wider mr-1">
            Suggestions:
          </span>
          {['Payroll', 'Finance', 'Tech', 'Workshop', 'AllHands', 'Culture', 'HR'].map((sug) => {
            const isAdded = (formData.tags || []).includes(sug);
            return (
              <button
                key={sug}
                type="button"
                onClick={() => handleToggleTag(sug)}
                className={`text-[10px] font-bold px-2 py-0.5 rounded-lg border transition-all cursor-pointer ${
                  isAdded
                    ? 'bg-primary text-white border-primary shadow-xs'
                    : 'bg-white hover:bg-primary/10 text-muted hover:text-primary border-border-subtle'
                }`}>
                #{sug}
              </button>
            );
          })}
        </div>

        {formData.tags && formData.tags.length > 0 && (
          <div className="flex flex-wrap gap-1.5 mt-2 pt-2 border-t border-border-subtle/80">
            {formData.tags.map((tag) => (
              <span
                key={tag}
                className="inline-flex items-center gap-1.5 text-xs font-bold text-primary bg-primary/10 px-2.5 py-1 rounded-xl border border-primary/20 shadow-xs">
                <span>#{tag}</span>
                <button
                  type="button"
                  onClick={() => handleRemoveTag(tag)}
                  className="hover:text-rose-500 cursor-pointer p-0.5 rounded-full hover:bg-black/10 transition-colors"
                  title="Remove tag">
                  <X size={12} />
                </button>
              </span>
            ))}
          </div>
        )}
      </div>

      <div className="flex items-center justify-end gap-3 pt-6 border-t border-border-subtle">
        <Button
          variant="ghost"
          onClick={onCancel}
          className="px-8! rounded-3xl! font-bold text-muted!"
          aria-label="Discard event details">
          Discard
        </Button>
        <Button
          variant="primary"
          onClick={() => onSubmit(formData)}
          className="px-10! h-12 rounded-3xl! font-black tracking-wide shadow-lg shadow-primary/20"
          aria-label={initialData ? 'Save changes to event' : 'Schedule this event'}>
          {initialData ? 'Save Changes' : 'Schedule Event'}
        </Button>
      </div>
    </div>
  );
};

import { useAuth } from '@/hooks/useAuth';
import { showConfirm } from '@/components/ui/composed/ConfirmDialog.utils';
import { Dialog } from '@/components/ui/composed/Dialog';
import { PageHeader } from '@/components/ui/composed/PageHeader';
import { ProgressSpinner } from '@/components/ui/composed/ProgressSpinner';
import { showToast } from '@/components/ui/composed/Toast.utils';
import { Button } from '@/components/ui/primitives/Button';
import { Input } from '@/components/ui/primitives/Input';
import { Tabs } from '@/components/ui/primitives/Tabs';
import {
  useCreateEventMutation,
  useUpdateEventMutation,
  useDeleteEventMutation,
  useGetEventsQuery,
  useGetFilterOptionsQuery,
  useRegisterEventMutation,
  type EventPassData,
} from '@/store/api/eventSlice';
import type { ERPEvent, EventFilters } from '@/types/models';
import {
  Building2,
  Calendar as CalendarIcon,
  CalendarDays,
  Filter,
  History as HistoryIcon,
  RotateCcw,
  Search,
  Tag,
  UserCheck,
  X,
  AlertCircle,
} from 'lucide-react';
import { useMemo, useState } from 'react';
import { EventCard } from './components/EventCard';
import { EventFilterDrawer } from './components/EventFilterDrawer';
import { EventForm } from './components/EventForm';
import { EventPassModal } from './components/EventPassModal';
import { EventDetailsModal } from './components/EventDetailsModal';
import {
  isPastEvent,
  registerUserForEventLocally,
  isUserRegisteredForEvent,
  formatEventTime,
} from './utils/eventUtils';

const Events = () => {
  const { user } = useAuth();
  const isAdmin = Boolean(
    user?.role &&
    ['admin', 'superadmin', 'hradmin', 'financeadmin', 'manager'].some((r) =>
      String(user.role).toLowerCase().includes(r)
    )
  );
  const [registeringEventId, setRegisteringEventId] = useState<string | number | null>(null);
  const [showFilterDrawer, setShowFilterDrawer] = useState(false);
  const [eventScope, setEventScope] = useState<'upcoming' | 'previous' | 'all'>('upcoming');
  const [filters, setFilters] = useState<EventFilters>({
    category: 'All',
    search: '',
  });

  const { data: filterOptions } = useGetFilterOptionsQuery();
  const { data: events = [], isLoading } = useGetEventsQuery(filters);
  const [createEvent] = useCreateEventMutation();
  const [updateEvent] = useUpdateEventMutation();
  const [deleteEvent] = useDeleteEventMutation();
  const [registerEvent] = useRegisterEventMutation();

  const [showForm, setShowForm] = useState(false);
  const [editingEvent, setEditingEvent] = useState<ERPEvent | null>(null);

  const [selectedEventForDetails, setSelectedEventForDetails] = useState<ERPEvent | null>(null);
  const [showDetailsModal, setShowDetailsModal] = useState(false);

  const [passModalData, setPassModalData] = useState<EventPassData | null>(null);
  const [showPassModal, setShowPassModal] = useState(false);

  // Force re-render key when local registrations change
  const [localUpdateTick, setLocalUpdateTick] = useState(0);

  // Dynamically aggregate categories from filterOptions + active events
  const categories = useMemo(() => {
    const list = filterOptions?.categories || ['Conference', 'Workshop', 'Social', 'Meeting'];
    const eventCats = events.map((e) => e.category).filter(Boolean);
    const combined = Array.from(new Set([...list, ...eventCats]));
    return ['All', ...combined];
  }, [filterOptions, events]);

  const activeCategory = filters.category || 'All';

  // Partition events into Upcoming vs Previous vs All
  const { upcomingEvents, previousEvents, displayedEvents, mandatoryUpcomingEvents } =
    useMemo(() => {
      const upcoming: ERPEvent[] = [];
      const previous: ERPEvent[] = [];

      events.forEach((evt) => {
        const st = (evt.status || '').toLowerCase();
        if (st === 'completed' || isPastEvent(evt)) {
          previous.push(evt);
        } else {
          upcoming.push(evt);
        }
      });

      let currentList = events;
      if (eventScope === 'upcoming') {
        currentList = upcoming;
      } else if (eventScope === 'previous') {
        currentList = previous;
      }

      const mandatory = upcoming.filter((e) => e.button_type === 'Mandatory');

      return {
        upcomingEvents: upcoming,
        previousEvents: previous,
        displayedEvents: currentList,
        mandatoryUpcomingEvents: mandatory,
      };
    }, [events, eventScope, localUpdateTick]);

  const handleCategoryChange = (cat: string) => {
    setFilters((prev) => ({ ...prev, category: cat }));
  };

  const handleSearchChange = (query: string) => {
    setFilters((prev) => ({ ...prev, search: query }));
  };

  const handleResetFilters = () => {
    setFilters({ category: 'All', search: '' });
  };

  const activeFilterCount = useMemo(() => {
    let count = 0;
    if (filters.category && filters.category !== 'All') count++;
    if (filters.tags && filters.tags.length > 0) count += filters.tags.length;
    if (filters.employee_statuses && filters.employee_statuses.length > 0)
      count += filters.employee_statuses.length;
    if (filters.departments && filters.departments.length > 0) count += filters.departments.length;
    if (filters.start_date) count++;
    if (filters.end_date) count++;
    if (filters.search) count++;
    return count;
  }, [filters]);

  const handleCreate = () => {
    setEditingEvent(null);
    setShowForm(true);
  };

  const handleEdit = (id: string) => {
    const event = events.find((e: ERPEvent) => String(e.id) === String(id));
    if (event) {
      setEditingEvent(event);
      setShowForm(true);
    }
  };

  const handleCardClick = (event: ERPEvent) => {
    setSelectedEventForDetails(event);
    setShowDetailsModal(true);
  };

  const handleViewPass = (event: ERPEvent) => {
    setShowDetailsModal(false);
    const passCode = `AETH-PASS-${String(event.id).slice(-4).toUpperCase() || 'VIP'}-${Math.floor(1000 + Math.random() * 9000)}`;
    const passData: EventPassData = {
      passCode,
      eventId: event.id,
      eventTitle: event.title,
      category: event.category,
      eventDate: event.date || event.event_date,
      time: formatEventTime(event),
      location: event.location,
      username: user?.username || user?.email?.split('@')[0] || 'Employee Participant',
      recipientEmail: user?.email || 'employee@aether-erp.internal',
      emailSent: true,
    };
    setPassModalData(passData);
    setShowPassModal(true);
  };

  const handleRegister = async (event: ERPEvent) => {
    const userIdentifier = user?.email || user?.username || 'current_user';

    // Duplicate registration prevention
    if (isUserRegisteredForEvent(event.id, userIdentifier, event)) {
      showToast({
        severity: 'info',
        summary: 'Already Registered',
        detail: `You have already confirmed your spot for "${event.title}".`,
        life: 3500,
      });
      handleViewPass(event);
      return;
    }

    try {
      setRegisteringEventId(event.id);
      let passResultData: EventPassData | null = null;

      try {
        const result = await registerEvent({
          id: event.id,
          email: user?.email,
          username: user?.username,
        }).unwrap();
        if (result.data) {
          passResultData = result.data;
        }
      } catch (apiErr: unknown) {
        const err = apiErr as { status?: number; data?: { message?: string } };
        const errMsg = err?.data?.message || '';
        // Surface "already registered" error immediately — do not proceed
        if (err?.status === 400 || errMsg.toLowerCase().includes('already registered')) {
          showToast({
            severity: 'warn',
            summary: 'Already Registered',
            detail: errMsg || `You have already registered for "${event.title}".`,
            life: 4000,
          });
          handleViewPass(event);
          setRegisteringEventId(null);
          return;
        }
        // For network/server failures, fallback to local-only registration (no email)
        console.warn('API registration failed, falling back to local registration:', errMsg);
      }

      // Record local registration to dynamically update attendee count & prevent duplicates with full participant info
      registerUserForEventLocally(event.id, {
        userIdentifier,
        name: user?.username || user?.email?.split('@')[0] || 'Confirmed User',
        email: user?.email || userIdentifier,
        department: user?.department || 'Corporate',
        avatar: user?.image_url,
        passCode: passResultData?.passCode,
      });
      setLocalUpdateTick((t) => t + 1);

      const emailRecipient =
        passResultData?.recipientEmail || user?.email || 'your registered email';
      const emailSentByServer = passResultData?.emailSent === true;

      showToast({
        severity: 'success',
        summary: 'Registration Confirmed!',
        detail: emailSentByServer
          ? `VIP entry pass emailed to ${emailRecipient}!`
          : `Pass generated for ${emailRecipient}. Check your inbox shortly.`,
        life: 5000,
      });

      if (passResultData) {
        setPassModalData(passResultData);
      } else {
        const passCode = `AETH-PASS-${String(event.id).slice(-4).toUpperCase() || 'VIP'}-${Math.floor(1000 + Math.random() * 9000)}`;
        setPassModalData({
          passCode,
          eventId: event.id,
          eventTitle: event.title,
          category: event.category,
          eventDate: event.date || event.event_date,
          time: formatEventTime(event),
          location: event.location,
          username: user?.username || user?.email?.split('@')[0] || 'VIP Participant',
          recipientEmail: user?.email || 'employee@aether-erp.internal',
          emailSent: true,
        });
      }

      setShowDetailsModal(false);
      setShowPassModal(true);
    } catch (err: unknown) {
      const apiError = err as { data?: { message?: string } };
      showToast({
        severity: 'error',
        summary: 'Registration Failed',
        detail: apiError.data?.message || 'Could not register for this event.',
        life: 3000,
      });
    } finally {
      setRegisteringEventId(null);
    }
  };

  const handleDelete = async (id: string) => {
    showConfirm({
      message: 'Are you sure you want to cancel this event?',
      header: 'Confirm Deletion',
      accept: async () => {
        try {
          await deleteEvent(id).unwrap();
          showToast({
            severity: 'success',
            summary: 'Cancelled',
            detail: 'Event cancelled successfully.',
            life: 3000,
          });
        } catch (err: unknown) {
          const apiError = err as { data?: { message?: string } };
          console.error('Failed to delete event:', err);
          showToast({
            severity: 'error',
            summary: 'Error',
            detail: apiError.data?.message || 'Failed to cancel event',
            life: 3000,
          });
        }
      },
    });
  };

  const handleSubmit = async (data: Partial<ERPEvent>) => {
    try {
      if (editingEvent) {
        await updateEvent({ id: editingEvent.id, data }).unwrap();
        showToast({
          severity: 'success',
          summary: 'Updated',
          detail: `Event "${data.title}" updated successfully!`,
          life: 3500,
        });
      } else {
        await createEvent(data).unwrap();
        showToast({
          severity: 'success',
          summary: 'Scheduled',
          detail: `Event "${data.title}" scheduled successfully with category "${data.category}"!`,
          life: 3500,
        });
      }
      setShowForm(false);
      setEditingEvent(null);
    } catch (err: unknown) {
      const apiError = err as { data?: { message?: string } };
      console.error('Failed to save event:', err);
      showToast({
        severity: 'error',
        summary: 'Error',
        detail: apiError.data?.message || 'Failed to save event',
        life: 3000,
      });
    }
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <ProgressSpinner />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 pb-12">
      <PageHeader
        title="Event Planner & Directory"
        description="Streamline hostings, manage real-time registrations, dynamic categories, and event memories across the team."
        primaryAction={
