          <div className="flex items-center gap-3.5">
            <div className="w-10 h-10 rounded-2xl bg-amber-500 text-white flex items-center justify-center flex-shrink-0 shadow-md shadow-amber-500/30">
              <AlertCircle size={20} />
            </div>
            <div>
              <div className="flex items-center gap-2 flex-wrap">
                <span className="text-[10px] font-black uppercase tracking-wider bg-amber-500 text-white px-2 py-0.5 rounded-md">
                  ⚠️ Company Broadcast
                </span>
                <span className="text-sm font-black text-amber-950 dark:text-amber-100">
                  {mandatoryUpcomingEvents[0].title}
                </span>
              </div>
              <p className="text-xs text-amber-900/80 dark:text-amber-300 font-medium mt-0.5">
                Mandatory Attendance required for all employees on{' '}
                {new Date(
                  mandatoryUpcomingEvents[0].date || mandatoryUpcomingEvents[0].event_date
                ).toLocaleDateString('en-US', {
                  weekday: 'short',
                  month: 'short',
                  day: 'numeric',
                })}{' '}
                ({mandatoryUpcomingEvents[0].time || 'Scheduled'}).
              </p>
            </div>
          </div>
          <Button
            variant="primary"
            onClick={() => handleCardClick(mandatoryUpcomingEvents[0])}
            className="rounded-2xl! text-xs font-black px-5 h-10 bg-amber-600 hover:bg-amber-700 text-white border-none shadow-md shadow-amber-600/20 whitespace-nowrap cursor-pointer">
            View &amp; Confirm
          </Button>
        </div>
      )}

      {/* Scope Selector: Upcoming vs Previous vs All */}
      <div className="flex flex-wrap items-center gap-3">
        <button
          type="button"
          onClick={() => setEventScope('upcoming')}
          className={`px-5 py-3 rounded-2xl font-black text-xs uppercase tracking-wider transition-all cursor-pointer flex items-center gap-2 ${
            eventScope === 'upcoming'
              ? 'bg-primary text-white shadow-lg shadow-primary/20 scale-102'
              : 'bg-white hover:bg-surface-subtle text-foreground border border-border-subtle shadow-xs'
          }`}>
          <CalendarDays size={16} />
          <span>Upcoming & Active Events</span>
          <span
            className={`px-2 py-0.5 rounded-full text-[10px] font-black ${
              eventScope === 'upcoming' ? 'bg-white text-primary' : 'bg-primary/10 text-primary'
            }`}>
            {upcomingEvents.length}
          </span>
        </button>

        <button
          type="button"
          onClick={() => setEventScope('previous')}
          className={`px-5 py-3 rounded-2xl font-black text-xs uppercase tracking-wider transition-all cursor-pointer flex items-center gap-2 ${
            eventScope === 'previous'
              ? 'bg-primary text-white shadow-lg shadow-primary/20 scale-102'
              : 'bg-white hover:bg-surface-subtle text-foreground border border-border-subtle shadow-xs'
          }`}>
          <HistoryIcon size={16} />
          <span>Previous Events</span>
          <span
            className={`px-2 py-0.5 rounded-full text-[10px] font-black ${
              eventScope === 'previous' ? 'bg-white text-primary' : 'bg-zinc-200 text-zinc-700'
            }`}>
            {previousEvents.length}
          </span>
        </button>

        <button
          type="button"
          onClick={() => setEventScope('all')}
          className={`px-5 py-3 rounded-2xl font-black text-xs uppercase tracking-wider transition-all cursor-pointer flex items-center gap-2 ${
            eventScope === 'all'
              ? 'bg-primary text-white shadow-lg shadow-primary/20 scale-102'
              : 'bg-white hover:bg-surface-subtle text-foreground border border-border-subtle shadow-xs'
          }`}>
          <span>All Events</span>
          <span
            className={`px-2 py-0.5 rounded-full text-[10px] font-black ${
              eventScope === 'all' ? 'bg-white text-primary' : 'bg-zinc-200 text-zinc-700'
            }`}>
            {events.length}
          </span>
        </button>
      </div>

      {/* Toolbar: Category Tabs & Search Bar */}
      <div className="flex flex-col gap-4">
        <div className="flex flex-col lg:flex-row items-center justify-between gap-6 bg-white p-4 rounded-[40px] border border-border-subtle shadow-soft">
          <Tabs
            items={categories}
            activeItem={activeCategory}
            onItemChange={handleCategoryChange}
            className="w-full lg:w-auto"
          />

          <div className="flex items-center gap-3 w-full lg:w-auto">
            <div className="relative flex-1 lg:w-72 group">
              <Search
                className="absolute left-4 top-1/2 -translate-y-1/2 text-muted group-focus-within:text-primary transition-colors"
                size={18}
              />
              <Input
                value={filters.search || ''}
                onChange={(e) => handleSearchChange(e.target.value)}
                placeholder="Search events, organizers..."
                className="pl-12! pr-8! h-12! text-sm!"
              />
              {filters.search && (
                <button
                  type="button"
                  onClick={() => handleSearchChange('')}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted hover:text-foreground">
                  <X size={14} />
                </button>
              )}
            </div>
            <Button
              variant="secondary"
              onClick={() => setShowFilterDrawer(true)}
              className={`h-12 rounded-2xl! px-4 border-border-subtle! gap-2 font-bold text-xs ${
                activeFilterCount > 0
                  ? 'bg-primary text-white border-primary hover:bg-primary/90'
                  : 'text-foreground'
              }`}>
              <Filter size={18} />
              <span>Filters</span>
              {activeFilterCount > 0 && (
                <span className="w-5 h-5 rounded-full bg-white text-primary text-[10px] font-black flex items-center justify-center">
                  {activeFilterCount}
                </span>
              )}
            </Button>
          </div>
        </div>

        {/* Active Filter Badges */}
        {activeFilterCount > 0 && (
          <div className="flex flex-wrap items-center gap-2 px-4 py-3 bg-surface-subtle/80 rounded-2xl border border-border-subtle/60">
            <span className="text-[11px] font-black text-muted uppercase tracking-wider mr-1">
              Active Filters:
            </span>

            {filters.category && filters.category !== 'All' && (
              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-bold bg-white text-primary border border-primary/20 shadow-xs">
                <span>Category: {filters.category}</span>
                <button
                  type="button"
                  onClick={() => setFilters((p) => ({ ...p, category: 'All' }))}
                  className="hover:text-red-500">
                  <X size={12} />
                </button>
              </span>
            )}

            {filters.tags?.map((t) => (
              <span
                key={t}
                className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-bold bg-white text-primary border border-primary/20 shadow-xs">
                <Tag size={10} />
                <span>#{t}</span>
                <button
                  type="button"
                  onClick={() =>
                    setFilters((p) => ({
                      ...p,
                      tags: p.tags?.filter((tag) => tag !== t),
                    }))
                  }
                  className="hover:text-red-500">
                  <X size={12} />
                </button>
              </span>
            ))}

            {filters.employee_statuses?.map((st) => (
              <span
                key={st}
                className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-bold bg-white text-emerald-600 border border-emerald-500/20 shadow-xs">
                <UserCheck size={10} />
                <span>Status: {st}</span>
                <button
                  type="button"
                  onClick={() =>
                    setFilters((p) => ({
                      ...p,
                      employee_statuses: p.employee_statuses?.filter((s) => s !== st),
                    }))
                  }
                  className="hover:text-red-500">
                  <X size={12} />
                </button>
              </span>
            ))}

            {filters.departments?.map((d) => (
              <span
                key={d}
                className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-bold bg-white text-foreground border border-border-subtle shadow-xs">
                <Building2 size={10} />
                <span>{d}</span>
                <button
                  type="button"
                  onClick={() =>
                    setFilters((p) => ({
                      ...p,
                      departments: p.departments?.filter((dept) => dept !== d),
                    }))
                  }
                  className="hover:text-red-500">
                  <X size={12} />
                </button>
              </span>
            ))}

            {(filters.start_date || filters.end_date) && (
              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-bold bg-white text-foreground border border-border-subtle shadow-xs">
                <CalendarIcon size={10} />
                <span>
                  {filters.start_date || 'Start'} to {filters.end_date || 'End'}
                </span>
                <button
                  type="button"
                  onClick={() =>
                    setFilters((p) => ({ ...p, start_date: undefined, end_date: undefined }))
                  }
                  className="hover:text-red-500">
                  <X size={12} />
                </button>
              </span>
            )}

            <button
              type="button"
              onClick={handleResetFilters}
              className="ml-auto text-xs font-black text-red-500 hover:underline flex items-center gap-1">
              <RotateCcw size={12} />
              Clear All
            </button>
          </div>
        )}
      </div>

      {/* Events Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-8">
        {displayedEvents.map((event) => (
          <EventCard
            key={event.id}
            event={event}
            onCardClick={handleCardClick}
            onEdit={handleEdit}
            onDelete={handleDelete}
            onRegister={handleRegister}
            onTagClick={(tag) => {
              const currentTags = filters.tags || [];
              if (!currentTags.includes(tag)) {
                setFilters((prev) => ({ ...prev, tags: [...currentTags, tag] }));
              }
            }}
            isRegistering={registeringEventId === event.id}
          />
        ))}

        {displayedEvents.length === 0 && (
          <div className="col-span-full py-20 bg-surface-subtle rounded-4xl border-2 border-dashed border-border-strong flex flex-col items-center justify-center text-center gap-4">
            <div className="w-16 h-16 rounded-full bg-white flex items-center justify-center text-muted shadow-sm">
              <CalendarIcon size={32} />
            </div>
            <div>
              <h4 className="text-xl font-black text-foreground">
                {eventScope === 'previous'
                  ? 'No previous events found'
                  : eventScope === 'upcoming'
                    ? 'No upcoming events scheduled'
                    : 'No events match your criteria'}
              </h4>
              <p className="text-sm text-muted font-medium mt-1">
                {activeFilterCount > 0
                  ? 'Try adjusting your dynamic search filters or category selections.'
                  : eventScope === 'upcoming'
                    ? 'Click "Schedule New Event" to plan an upcoming company event.'
                    : 'Concluded events will appear here automatically.'}
              </p>
              {activeFilterCount > 0 && (
                <Button
                  variant="secondary"
                  onClick={handleResetFilters}
                  className="mt-4 h-10 rounded-2xl font-bold text-xs">
                  Reset All Filters
                </Button>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Event Details Modal Popup */}
      <EventDetailsModal
        event={selectedEventForDetails}
        visible={showDetailsModal}
        onHide={() => setShowDetailsModal(false)}
        onRegister={handleRegister}
        isRegistering={registeringEventId === selectedEventForDetails?.id}
        onEdit={handleEdit}
        onDelete={handleDelete}
        onViewPass={handleViewPass}
      />

      {/* Event Filter Drawer */}
      <EventFilterDrawer
        visible={showFilterDrawer}
        onHide={() => setShowFilterDrawer(false)}
        filters={filters}
        filterOptions={filterOptions}
        onFilterChange={setFilters}
        onResetFilters={handleResetFilters}
      />

      {/* Event Form Modal */}
      <Dialog
        visible={showForm}
        onHide={() => setShowForm(false)}
        header={editingEvent ? 'Revise Event Schedule' : 'Plan New Company Event'}
        modal
        width={900}
        footer={null}
        className="max-w-[92vw] mx-auto rounded-[40px] overflow-hidden"
        contentClassName="p-8 sm:p-10"
        headerClassName="px-8 sm:px-10 pt-8 sm:pt-10 pb-4 text-2xl font-black tracking-tight border-none"
        pt={{
          root: { className: 'rounded-[48px] overflow-hidden border-none shadow-2xl bg-white' },
          mask: { className: 'backdrop-blur-md bg-black/40' },
        }}>
        <EventForm
          initialData={editingEvent}
          availableCategories={categories}
          onSubmit={handleSubmit}
          onCancel={() => setShowForm(false)}
        />
      </Dialog>

      {/* VIP Event Pass Visual Ticket Modal */}
      <EventPassModal
        isOpen={showPassModal}
        onClose={() => setShowPassModal(false)}
        passData={passModalData}
      />
    </div>
  );
};

export default Events;

import { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  BookOpen,
  Download,
  TrendingUp,
  TrendingDown,
  IndianRupee,
  RefreshCw,
  ChevronDown,
  ChevronUp,
  AlertCircle,
  CheckCircle,
  Printer,
  Filter,
} from 'lucide-react';
import { message as antMessage, Table as AntTable } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { useGetInvoicesQuery } from '@/store/api/financeApiSlice';
import { useGetAllExpensesQuery } from '@/store/api/expenseSlice';

// ─── Types ──────────────────────────────────────────────────────────────────

interface FinancialEntry {
  particulars: string;
  currentPeriod: number;
  previousPeriod?: number;
  category: 'income' | 'expense' | 'asset' | 'liability';
}

const QUARTERS = ['Q1 (Jan–Mar)', 'Q2 (Apr–Jun)', 'Q3 (Jul–Sep)', 'Q4 (Oct–Dec)', 'Full Year'];
const YEARS = ['2026', '2025', '2024'];

// ─── Helpers ─────────────────────────────────────────────────────────────────

function fmt(n: number) {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(n);
}

// ─── KPI Card ────────────────────────────────────────────────────────────────

interface KPICardProps {
  label: string;
  value: string;
  sub?: string;
  trend?: 'up' | 'down' | 'neutral';
  icon: React.ReactNode;
  color: string;
}
function KPICard({ label, value, sub, trend, icon, color }: KPICardProps) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      style={{
        background: 'rgba(255,255,255,0.03)',
        border: '1px solid rgba(255,255,255,0.08)',
        borderRadius: 16,
        padding: '20px 24px',
        display: 'flex',
        flexDirection: 'column',
        gap: 12,
      }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <span style={{ fontSize: 13, color: '#64748b', fontWeight: 500 }}>{label}</span>
        <div
          style={{
            width: 36,
            height: 36,
            borderRadius: 10,
            background: `${color}22`,
            color,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}>
          {icon}
        </div>
      </div>
      <div>
        <div style={{ fontSize: 22, fontWeight: 800, color: '#f1f5f9', letterSpacing: '-0.5px' }}>
          {value}
        </div>
        {sub && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 4 }}>
            {trend === 'up' && <TrendingUp size={13} color="#22c55e" />}
            {trend === 'down' && <TrendingDown size={13} color="#f87171" />}
            <span
              style={{
                fontSize: 12,
                color: trend === 'up' ? '#22c55e' : trend === 'down' ? '#f87171' : '#64748b',
              }}>
              {sub}
            </span>
          </div>
        )}
      </div>
    </motion.div>
  );
}

// ─── Ledger Table ─────────────────────────────────────────────────────────────

interface LedgerTableProps {
  title: string;
  entries: FinancialEntry[];
  color: string;
  icon: React.ReactNode;
  defaultOpen?: boolean;
}
function LedgerTable({ title, entries, color, icon, defaultOpen = true }: LedgerTableProps) {
  const [open, setOpen] = useState(defaultOpen);
  const total = entries.reduce((sum, e) => sum + e.currentPeriod, 0);
  const columns: ColumnsType<FinancialEntry> = [
    {
      title: 'Particulars',
      dataIndex: 'particulars',
      key: 'particulars',
      render: (value: string) => <span style={{ color: '#cbd5e1' }}>{value}</span>,
    },
    {
      title: 'Current Period (₹)',
      dataIndex: 'currentPeriod',
      key: 'currentPeriod',
      align: 'right',
      render: (value: number) => <span style={{ color: '#f1f5f9', fontWeight: 600 }}>{fmt(value)}</span>,
    },
    {
      title: '% of Total',
      key: 'percentage',
      align: 'right',
      render: (_, entry) => <span style={{ color: '#64748b' }}>{total > 0 ? `${((entry.currentPeriod / total) * 100).toFixed(1)}%` : '—'}</span>,
    },
  ];

  return (
    <div
      style={{
        background: 'rgba(255,255,255,0.02)',
        border: '1px solid rgba(255,255,255,0.07)',
        borderRadius: 16,
        overflow: 'hidden',
      }}>
      <button
        onClick={() => setOpen(!open)}
        style={{
          width: '100%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '16px 20px',
          background: 'transparent',
          border: 'none',
          cursor: 'pointer',
        }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div
            style={{
              width: 32,
              height: 32,
              borderRadius: 8,
              background: `${color}22`,
              color,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}>
            {icon}
          </div>
          <div>
            <div style={{ fontWeight: 700, fontSize: 15, color: '#f1f5f9', textAlign: 'left' }}>
              {title}
            </div>
            <div style={{ fontSize: 12, color: '#64748b' }}>{entries.length} line items</div>
          </div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
          <div style={{ fontWeight: 800, fontSize: 16, color }}>{fmt(total)}</div>
          {open ? (
            <ChevronUp size={16} color="#64748b" />
          ) : (
            <ChevronDown size={16} color="#64748b" />
          )}
        </div>
      </button>

      <AnimatePresence initial={false}>
        {open && (
          <motion.div
            initial={{ height: 0 }}
            animate={{ height: 'auto' }}
            exit={{ height: 0 }}
            style={{ overflow: 'hidden' }}>
            <AntTable<FinancialEntry>
              columns={columns}
              dataSource={entries}
              rowKey="particulars"
              pagination={false}
              size="small"
              scroll={{ x: 'max-content' }}
              summary={() => (
                <AntTable.Summary.Row style={{ background: `${color}08` }}>
                  <AntTable.Summary.Cell index={0}>
                    <strong style={{ color }}>Total {title}</strong>
                  </AntTable.Summary.Cell>
                  <AntTable.Summary.Cell index={1} align="right">
                    <strong style={{ color }}>{fmt(total)}</strong>
                  </AntTable.Summary.Cell>
                  <AntTable.Summary.Cell index={2} align="right">
                    <span style={{ color: '#64748b' }}>100%</span>
                  </AntTable.Summary.Cell>
                </AntTable.Summary.Row>
              )}
            />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

// ─── Main Page ────────────────────────────────────────────────────────────────

export default function AuditBookPage() {
  const [selectedYear, setSelectedYear] = useState('2026');
  const [selectedQuarter, setSelectedQuarter] = useState('Q3 (Jul–Sep)');
  const [isGenerating, setIsGenerating] = useState(false);

  const { data: invoicesData = [] } = useGetInvoicesQuery();
  const { data: expensesData = [] } = useGetAllExpensesQuery();

  const { income, expenses: expenseEntries } = useMemo(() => {
    let startMonth = 0;
    let endMonth = 11;
    if (selectedQuarter.startsWith('Q1')) {
      startMonth = 0;
      endMonth = 2;
    } else if (selectedQuarter.startsWith('Q2')) {
      startMonth = 3;
      endMonth = 5;
    } else if (selectedQuarter.startsWith('Q3')) {
      startMonth = 6;
      endMonth = 8;
    } else if (selectedQuarter.startsWith('Q4')) {
      startMonth = 9;
      endMonth = 11;
    }

    const isMatch = (dateStr?: string) => {
      if (!dateStr) return false;
      const d = new Date(dateStr);
      if (isNaN(d.getTime())) return false;
      if (d.getFullYear().toString() !== selectedYear) return false;
      if (selectedQuarter === 'Full Year') return true;
      const m = d.getMonth();
      return m >= startMonth && m <= endMonth;
    };

    const incomeMap = new Map<string, number>();
    (invoicesData || []).forEach((inv: any) => {
      const date = inv.date || inv.invoice_date || inv.invoiceDate || inv.created_at;
      if (!isMatch(date)) return;
      const particulars = inv.client || inv.bill_to_name || inv.clientName || 'Invoice Revenue';
      const amt = Number(inv.amount || inv.total || 0);
      incomeMap.set(particulars, (incomeMap.get(particulars) || 0) + amt);
    });

    const incomeList: FinancialEntry[] = Array.from(incomeMap.entries()).map(([particulars, currentPeriod]) => ({
      particulars,
      currentPeriod,
      category: 'income',
    }));

    const expenseMap = new Map<string, number>();
    (expensesData || []).forEach((exp: any) => {
      const date = exp.expense_date || exp.created_at || exp.date;
      if (!isMatch(date)) return;
      const cat = exp.category || exp.title || exp.description || 'General Expense';
      const amt = Number(exp.amount || 0);
      expenseMap.set(cat, (expenseMap.get(cat) || 0) + amt);
    });

    const expList: FinancialEntry[] = Array.from(expenseMap.entries()).map(([particulars, currentPeriod]) => ({
      particulars,
      currentPeriod,
      category: 'expense',
    }));

    return { income: incomeList, expenses: expList };
  }, [invoicesData, expensesData, selectedYear, selectedQuarter]);

  const totalRevenue = income.reduce((s, e) => s + e.currentPeriod, 0);
  const totalExpenses = expenseEntries.reduce((s, e) => s + e.currentPeriod, 0);
  const netProfitLoss = totalRevenue - totalExpenses;
  const grossMargin = totalRevenue > 0 ? ((netProfitLoss / totalRevenue) * 100).toFixed(1) : '0';

  // ─── PDF Export ─────────────────────────────────────────────────────────────

  const handleExportPDF = async () => {
    setIsGenerating(true);
    try {
      const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pageW = doc.internal.pageSize.getWidth();

      // ── Header ──
      doc.setFillColor(10, 15, 30);
      doc.rect(0, 0, pageW, 40, 'F');
      doc.setTextColor(99, 102, 241);
      doc.setFontSize(18);
      doc.setFont('helvetica', 'bold');
      doc.text('FINANCIAL AUDIT BOOK', 20, 18);
      doc.setTextColor(148, 163, 184);
      doc.setFontSize(10);
      doc.setFont('helvetica', 'normal');
      doc.text(`Period: ${selectedQuarter} ${selectedYear}`, 20, 26);
      doc.text(`Generated: ${new Date().toLocaleDateString('en-IN')}`, 20, 32);
      doc.setTextColor(100, 116, 139);
      doc.text('CONFIDENTIAL — For Internal Use Only', pageW - 20, 32, { align: 'right' });

      // ── KPI Summary ──
      doc.setFillColor(30, 41, 59);
      doc.rect(0, 44, pageW, 28, 'F');
      const kpis = [
        { label: 'Total Revenue', value: fmt(totalRevenue) },
        { label: 'Total Expenses', value: fmt(totalExpenses) },
        {
          label: netProfitLoss >= 0 ? 'Net Profit' : 'Net Loss',
          value: fmt(Math.abs(netProfitLoss)),
        },
        { label: 'Gross Margin', value: `${grossMargin}%` },
      ];
      kpis.forEach((kpi, i) => {
        const x = 20 + i * (pageW / 4);
        doc.setTextColor(148, 163, 184);
        doc.setFontSize(8);
        doc.text(kpi.label, x, 52);
        doc.setTextColor(241, 245, 249);
        doc.setFontSize(12);
        doc.setFont('helvetica', 'bold');
        doc.text(kpi.value, x, 62);
      });

      let y = 80;

      // ── Income Statement ──
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(12);
      doc.setTextColor(99, 102, 241);
      doc.text('INCOME STATEMENT', 20, y);
      y += 8;

      autoTable(doc, {
        startY: y,
        head: [['Particulars', 'Amount (INR)', '% of Revenue']],
        body: [
          ...income.map((e) => [
            e.particulars,
            fmt(e.currentPeriod),
            totalRevenue > 0 ? `${((e.currentPeriod / totalRevenue) * 100).toFixed(1)}%` : '—',
          ]),
          ['TOTAL REVENUE', fmt(totalRevenue), '100%'],
        ],
        theme: 'striped',
        headStyles: {
          fillColor: [15, 23, 42],
          textColor: [99, 102, 241],
          fontStyle: 'bold',
          fontSize: 9,
        },
        bodyStyles: { textColor: [51, 65, 85], fontSize: 9 },
        alternateRowStyles: { fillColor: [248, 250, 252] },
        footStyles: { fillColor: [15, 23, 42], textColor: [255, 255, 255], fontStyle: 'bold' },
        didParseCell: (data) => {
          if (data.row.index === income.length) {
            data.cell.styles.fillColor = [15, 23, 42];
            data.cell.styles.textColor = [255, 255, 255];
            data.cell.styles.fontStyle = 'bold';
          }
        },
      });

      y = (doc as any).lastAutoTable.finalY + 14;

      // ── Expense Ledger ──
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(12);
      doc.setTextColor(239, 68, 68);
      doc.text('EXPENSE LEDGER', 20, y);
      y += 8;

      autoTable(doc, {
        startY: y,
        head: [['Particulars', 'Amount (INR)', '% of Expenses']],
        body: [
          ...expenseEntries.map((e) => [
            e.particulars,
            fmt(e.currentPeriod),
            totalExpenses > 0 ? `${((e.currentPeriod / totalExpenses) * 100).toFixed(1)}%` : '—',
          ]),
          ['TOTAL EXPENSES', fmt(totalExpenses), '100%'],
        ],
        theme: 'striped',
        headStyles: {
          fillColor: [127, 29, 29],
          textColor: [254, 202, 202],
          fontStyle: 'bold',
          fontSize: 9,
        },
        bodyStyles: { textColor: [51, 65, 85], fontSize: 9 },
        alternateRowStyles: { fillColor: [255, 247, 247] },
        didParseCell: (data) => {
          if (data.row.index === expenseEntries.length) {
            data.cell.styles.fillColor = [127, 29, 29];
            data.cell.styles.textColor = [255, 255, 255];
            data.cell.styles.fontStyle = 'bold';
          }
        },
      });

      y = (doc as any).lastAutoTable.finalY + 14;

      // ── P&L Summary ──
      if (y > 240) {
        doc.addPage();
        y = 20;
      }
      autoTable(doc, {
        startY: y,
        head: [['Profit & Loss Summary', 'Amount (INR)']],
        body: [
          ['Total Revenue', fmt(totalRevenue)],
          ['Less: Total Expenses', `(${fmt(totalExpenses)})`],
          [netProfitLoss >= 0 ? 'NET PROFIT BEFORE TAX' : 'NET LOSS', fmt(Math.abs(netProfitLoss))],
          ['Gross Margin %', `${grossMargin}%`],
        ],
        theme: 'plain',
        headStyles: {
          fillColor: netProfitLoss >= 0 ? [6, 78, 59] : [127, 29, 29],
          textColor: [255, 255, 255],
          fontStyle: 'bold',
          fontSize: 10,
        },
        bodyStyles: { textColor: [15, 23, 42], fontSize: 10 },
        didParseCell: (data) => {
          if (data.row.index === 2) {
            data.cell.styles.fontStyle = 'bold';
            data.cell.styles.fillColor = netProfitLoss >= 0 ? [220, 252, 231] : [254, 226, 226];
            data.cell.styles.textColor = netProfitLoss >= 0 ? [6, 78, 59] : [153, 27, 27];
          }
        },
      });

      // ── Footer ──
      const pageCount = doc.getNumberOfPages();
      for (let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(100, 116, 139);
        doc.text(
          `Page ${i} of ${pageCount} | Aetheradix ERP — Financial Audit Book ${selectedQuarter} ${selectedYear}`,
          pageW / 2,
          doc.internal.pageSize.getHeight() - 8,
          { align: 'center' }
        );
      }

      doc.save(`Audit_Book_${selectedYear}_${selectedQuarter.replace(/[^a-z0-9]/gi, '_')}.pdf`);
      antMessage.success('Audit Book PDF exported successfully!');
    } catch (err) {
      antMessage.error('Failed to generate PDF');
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  // ─── Render ───────────────────────────────────────────────────────────────

  return (
    <div style={{ padding: 'clamp(12px, 3vw, 24px) clamp(12px, 4vw, 32px)', maxWidth: 1200, margin: '0 auto', width: '100%', boxSizing: 'border-box' }}>
      {/* Header */}
      <div
        style={{
          display: 'flex',
          alignItems: 'flex-start',
          justifyContent: 'space-between',
          marginBottom: 32,
          flexWrap: 'wrap',
          gap: 16,
        }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 6 }}>
            <div
              style={{
                width: 44,
                height: 44,
                borderRadius: 12,
                background: 'rgba(99,102,241,0.15)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#6366f1',
              }}>
              <BookOpen size={22} />
            </div>
            <div>
              <h1
                style={{
                  margin: 0,
                  fontSize: 26,
                  fontWeight: 800,
                  color: '#f1f5f9',
                  letterSpacing: '-0.5px',
                }}>
                Financial Audit Book
              </h1>
              <p style={{ margin: 0, fontSize: 14, color: '#64748b' }}>
                CA-grade financial ledger and audit trail
              </p>
            </div>
          </div>
        </div>

        {/* Controls */}
        <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', alignItems: 'center' }}>
          {/* Year */}
          <select
            id="audit-year-select"
            value={selectedYear}
            onChange={(e) => setSelectedYear(e.target.value)}
            style={{
              padding: '9px 14px',
              borderRadius: 10,
              background: 'rgba(255,255,255,0.05)',
              border: '1px solid rgba(255,255,255,0.1)',
              color: '#f1f5f9',
              fontSize: 14,
              outline: 'none',
            }}>
            {YEARS.map((y) => (
              <option key={y} value={y} style={{ background: '#1e293b' }}>
                {y}
              </option>
            ))}
          </select>

          {/* Quarter */}
          <select
            id="audit-quarter-select"
            value={selectedQuarter}
            onChange={(e) => setSelectedQuarter(e.target.value)}
            style={{
              padding: '9px 14px',
              borderRadius: 10,
              background: 'rgba(255,255,255,0.05)',
              border: '1px solid rgba(255,255,255,0.1)',
              color: '#f1f5f9',
              fontSize: 14,
              outline: 'none',
            }}>
            {QUARTERS.map((q) => (
              <option key={q} value={q} style={{ background: '#1e293b' }}>
                {q}
              </option>
            ))}
          </select>

          <button
            id="audit-export-pdf-btn"
            onClick={handleExportPDF}
            disabled={isGenerating}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              padding: '9px 18px',
              borderRadius: 10,
              background: '#6366f1',
              color: '#fff',
              border: 'none',
              cursor: isGenerating ? 'default' : 'pointer',
              fontWeight: 600,
              fontSize: 14,
              opacity: isGenerating ? 0.7 : 1,
              transition: 'opacity 0.15s',
            }}>
            {isGenerating ? (
              <RefreshCw size={16} style={{ animation: 'spin 1s linear infinite' }} />
            ) : (
              <Download size={16} />
            )}
            {isGenerating ? 'Generating…' : 'Export PDF'}
          </button>

          <button
            id="audit-print-btn"
            onClick={() => window.print()}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              padding: '9px 14px',
              borderRadius: 10,
              background: 'rgba(255,255,255,0.05)',
              color: '#94a3b8',
              border: '1px solid rgba(255,255,255,0.1)',
              cursor: 'pointer',
              fontSize: 14,
            }}>
            <Printer size={16} />
          </button>
        </div>
      </div>

      {/* Period badge */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 10,
          marginBottom: 28,
          padding: '12px 20px',
          borderRadius: 12,
          background: 'rgba(99,102,241,0.08)',
          border: '1px solid rgba(99,102,241,0.2)',
        }}>
        <AlertCircle size={16} color="#6366f1" />
        <span style={{ fontSize: 13, color: '#94a3b8' }}>
          Audit Report for:{' '}
          <strong style={{ color: '#f1f5f9' }}>
            {selectedQuarter} {selectedYear}
          </strong>{' '}
          — Data is reconciled across Invoices, Expenses, Payroll, and Reimbursements.
        </span>
        <span
          style={{
            marginLeft: 'auto',
            display: 'flex',
            alignItems: 'center',
            gap: 6,
            fontSize: 12,
            color: '#22c55e',
          }}>
          <CheckCircle size={13} />
          Live data
        </span>
      </div>

      {/* KPI Grid */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
          gap: 16,
          marginBottom: 32,
        }}>
        <KPICard
          label="Total Revenue"
          value={fmt(totalRevenue)}
          sub="vs last period"
          trend="up"
          icon={<TrendingUp size={18} />}
          color="#22c55e"
        />
        <KPICard
          label="Total Expenses"
          value={fmt(totalExpenses)}
          sub={`${((totalExpenses / totalRevenue) * 100).toFixed(1)}% of revenue`}
          trend="down"
          icon={<TrendingDown size={18} />}
          color="#f87171"
        />
        <KPICard
          label={netProfitLoss >= 0 ? 'Net Profit' : 'Net Loss'}
          value={fmt(Math.abs(netProfitLoss))}
          sub={`${grossMargin}% margin`}
          trend={netProfitLoss >= 0 ? 'up' : 'down'}
          icon={<IndianRupee size={18} />}
          color={netProfitLoss >= 0 ? '#6366f1' : '#f87171'}
        />
        <KPICard
          label="Expense Ratio"
          value={`${totalRevenue > 0 ? ((totalExpenses / totalRevenue) * 100).toFixed(1) : '0'}%`}
          sub="of total revenue"
          trend="neutral"
          icon={<Filter size={18} />}
          color="#f59e0b"
        />
      </div>

      {/* Ledger Tables */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <LedgerTable
          title="Revenue / Income"
          entries={income}
          color="#22c55e"
          icon={<TrendingUp size={16} />}
          defaultOpen={true}
        />
        <LedgerTable
          title="Operating Expenses"
          entries={expenseEntries}
          color="#f87171"
          icon={<TrendingDown size={16} />}
          defaultOpen={true}
        />

        {/* P&L Summary box */}
        <div
          style={{
            background: netProfitLoss >= 0 ? 'rgba(34,197,94,0.06)' : 'rgba(248,113,113,0.06)',
            border: `1px solid ${netProfitLoss >= 0 ? 'rgba(34,197,94,0.2)' : 'rgba(248,113,113,0.2)'}`,
            borderRadius: 16,
            padding: '24px 28px',
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
            gap: 24,
          }}>
          <div>
            <div
              style={{
                fontSize: 12,
                color: '#64748b',
                fontWeight: 600,
                textTransform: 'uppercase',
                letterSpacing: '0.06em',
                marginBottom: 8,
              }}>
              Net Profit / Loss Summary
            </div>
            <AntTable
              size="small"
              pagination={false}
              showHeader={false}
              scroll={{ x: 'max-content' }}
              rowKey="label"
              dataSource={[
                ['Total Revenue', fmt(totalRevenue), '#22c55e'],
                ['Less: Expenses', `(${fmt(totalExpenses)})`, '#f87171'],
                [
                  netProfitLoss >= 0 ? 'Net Profit' : 'Net Loss',
                  fmt(Math.abs(netProfitLoss)),
                  netProfitLoss >= 0 ? '#6366f1' : '#f87171',
                ],
              ].map(([label, value, color], index) => ({ key: String(index), label, value, color, index }))}
              columns={[
                { title: 'Label', dataIndex: 'label', key: 'label', render: (value, record) => <span style={{ color: '#94a3b8', fontWeight: record.index === 2 ? 700 : 400 }}>{value}</span> },
                { title: 'Value', dataIndex: 'value', key: 'value', align: 'right' as const, render: (value, record) => <span style={{ color: record.color, fontWeight: 700 }}>{value}</span> },
              ]}
            />
          </div>
          <div>
            <div
              style={{
                fontSize: 12,
                color: '#64748b',
                fontWeight: 600,
                textTransform: 'uppercase',
                letterSpacing: '0.06em',
                marginBottom: 8,
              }}>
              Financial Health Indicators
            </div>
            {[
              {
                label: 'Gross Margin',
                value: `${grossMargin}%`,
                good: parseFloat(grossMargin) > 30,
              },
              {
                label: 'Expense Ratio',
                value: `${totalRevenue > 0 ? ((totalExpenses / totalRevenue) * 100).toFixed(1) : '0'}%`,
                good: totalExpenses / totalRevenue < 0.7,
              },
              { label: 'Revenue per Employee', value: fmt(totalRevenue / 24), good: true },
            ].map((item, i) => (
              <div
                key={i}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  padding: '7px 0',
                  borderBottom: i < 2 ? '1px solid rgba(255,255,255,0.06)' : 'none',
                }}>
                <span style={{ fontSize: 13, color: '#94a3b8' }}>{item.label}</span>
                <span
                  style={{
                    fontSize: 13,
                    fontWeight: 700,
                    color: item.good ? '#22c55e' : '#f87171',
                    background: item.good ? 'rgba(34,197,94,0.1)' : 'rgba(248,113,113,0.1)',
                    padding: '2px 8px',
                    borderRadius: 6,
                  }}>
                  {item.value}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Disclaimer */}
        <div
          style={{
            padding: '14px 20px',
            borderRadius: 12,
            background: 'rgba(255,255,255,0.02)',
            border: '1px solid rgba(255,255,255,0.06)',
            fontSize: 12,
            color: '#475569',
            lineHeight: 1.6,
          }}>
          <strong style={{ color: '#64748b' }}>Disclaimer:</strong> This financial audit book is
          generated from ERP system data and is for internal reference purposes. Figures are subject
          to review and reconciliation by a Chartered Accountant. This document does not constitute
          a certified audit report. All monetary values are in Indian Rupees (INR).
        </div>
      </div>

      <style>{`
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
}

