}

export interface ParsedSalarySlip {
  id: number | string;
  employeeId: number | string;
  employeeName: string;
  position: string;
  basePay: number;
  bonusPay: number;
  netSalary: number;
  monthYear: string;
  payPeriod: string;
  paySlipNo: string;
  accountNumber: string;
  paidDays: number;
  lopDays: number;
  earnings: SalaryBreakdownItem[];
  deductions: SalaryBreakdownItem[];
  authorizedSignatory?: string;
  signatoryRole?: string;
  hrNote?: string;
  createdAt: string;
  createdBy: string;
  rawRecord?: PayrollRecord;
  paymentStatus?: string;
}

// Deep utility helper to find key values in deeply nested objects or wrappers
const findDeepValue = (obj: any, keys: string[]): any => {
  if (!obj || typeof obj !== 'object') return undefined;
  for (const key of keys) {
    if (obj[key] !== undefined && obj[key] !== null && obj[key] !== '' && obj[key] !== 'null') {
      return obj[key];
    }
  }
  for (const prop in obj) {
    if (obj[prop] && typeof obj[prop] === 'object' && !Array.isArray(obj[prop])) {
      const found = findDeepValue(obj[prop], keys);
      if (found !== undefined && found !== null && found !== '' && found !== 'null') return found;
    }
  }
  return undefined;
};

// Safe number parser handling string floats ("0.00", "22.0", null)
const parseNum = (val: any): number => {
  if (val === undefined || val === null) return 0;
  const num = Number(val);
  return isNaN(num) ? 0 : num;
};

// Converts raw API payload into a clean, normalized PayrollRecord object
export const formatApiRecord = (item: Record<string, unknown>): PayrollRecord => {
  const employeeName = String(
    findDeepValue(item, ['username', 'employeeName', 'employee_name', 'name', 'full_name']) ||
      'Unnamed Employee'
  ).trim();

  const position = String(
    findDeepValue(item, ['designation', 'position', 'employee_position', 'role']) || 'Employee'
  );

  const userId = Number(
    findDeepValue(item, ['user_id', 'userId', 'employeeId', 'employee_code']) || 0
  );

  const paidDays = parseNum(
    findDeepValue(item, ['days_worked', 'paidDays', 'paid_days', 'total_working_days']) || 22
  );
  const lopDays = parseNum(findDeepValue(item, ['leave_days', 'lopDays', 'lop_days']) || 0);

  // Parse pay period month and year into formatted string
  const rawMonth = findDeepValue(item, ['pay_period_month', 'month']);
  const rawYear = findDeepValue(item, ['pay_period_year', 'year']);
  let monthYear = 'OCTOBER 2026';

  if (rawMonth && rawYear) {
    const monthNames = [
      'JANUARY',
      'FEBRUARY',
      'MARCH',
      'APRIL',
      'MAY',
      'JUNE',
      'JULY',
      'AUGUST',
      'SEPTEMBER',
      'OCTOBER',
      'NOVEMBER',
      'DECEMBER',
    ];
    const mIdx = parseNum(rawMonth) - 1;
    if (mIdx >= 0 && mIdx < 12) {
      monthYear = `${monthNames[mIdx]} ${rawYear}`;
    }
  } else {
    monthYear = String(
      findDeepValue(item, ['monthYear', 'month_year', 'payPeriod', 'pay_period', 'created_at']) ||
        'OCTOBER 2026'
    );
  }

  // Parse monetary fields
  const basicSalary = parseNum(
    findDeepValue(item, ['basic_salary', 'basePay', 'base_amount', 'base_pay', 'base'])
  );
  const hra = parseNum(findDeepValue(item, ['house_rent_allowance', 'hra']));
  const specialAllowance = parseNum(findDeepValue(item, ['special_allowance']));
  const conveyance = parseNum(findDeepValue(item, ['conveyance_allowance']));
  const bonus = parseNum(findDeepValue(item, ['bonus', 'bonusPay', 'bonus_amount']));
  const otherEarnings = parseNum(findDeepValue(item, ['other_earnings']));
  const grossSalary = parseNum(
    findDeepValue(item, ['gross_salary', 'total_amount', 'totalSalary'])
  );

  const pf = parseNum(findDeepValue(item, ['provident_fund']));
  const profTax = parseNum(findDeepValue(item, ['professional_tax']));
  const tds = parseNum(findDeepValue(item, ['income_tax_tds']));
  const otherDeductions = parseNum(findDeepValue(item, ['other_deductions']));
  const netSalary = parseNum(findDeepValue(item, ['net_salary', 'netSalary', 'total']));

  // Build itemized earnings list with explicit zeros
  const rawEarnings =
    (findDeepValue(item, ['earnings']) as Array<{ name: string; amount: number }>) || [];
  let constructedEarnings = rawEarnings;

  if (constructedEarnings.length === 0) {
    constructedEarnings = [
      { name: 'Basic Salary', amount: basicSalary },
      { name: 'House Rent Allowance (HRA)', amount: hra },
      { name: 'Special Allowance', amount: specialAllowance },
      { name: 'Conveyance Allowance', amount: conveyance },
      { name: 'Bonus', amount: bonus },
      { name: 'Other Earnings', amount: otherEarnings },
    ];
  }

  // Build itemized deductions list with explicit zeros
  const rawDeductions =
    (findDeepValue(item, ['deductions']) as Array<{ name: string; amount: number }>) || [];
  let constructedDeductions = rawDeductions;

  if (constructedDeductions.length === 0) {
    constructedDeductions = [
      { name: 'Provident Fund (PF)', amount: pf },
      { name: 'Professional Tax (PT)', amount: profTax },
      { name: 'Income Tax (TDS)', amount: tds },
      { name: 'Other Deductions', amount: otherDeductions },
    ];
  }

  const normalizedSlipNo = extractSlipNumber(item);

  return {
    id: Number(findDeepValue(item, ['id']) || Date.now()),
    userId: userId,
    base: basicSalary,
    bonus: bonus,
    total: netSalary || grossSalary || basicSalary + bonus,
    date: monthYear,
    monthYear: monthYear,
    paySlipNo: normalizedSlipNo,
    payPeriod: String(findDeepValue(item, ['pay_period', 'payPeriod']) || monthYear),
    companyName: String(findDeepValue(item, ['company_name', 'companyAddress']) || 'AETHERADIX'),
    companyAddress: String(
      findDeepValue(item, ['company_address', 'companyAddress']) ||
        'F-N 507, Crystal Tower, IBD Kings Park, Bawadia Kalan, Bhopal, MP | 462039'
    ),
    employeeId: String(
      findDeepValue(item, ['employee_code', 'employee_id', 'employeeId', 'user_id']) || userId
    ),
    employeeName: employeeName,
    position: position,
    accountNumber: String(
      findDeepValue(item, ['bank_account_number', 'account_number', 'accountNumber']) || 'N/A'
    ),
    paidDays: paidDays,
    lopDays: lopDays,
    generatedOn: String(
      findDeepValue(item, ['payment_date', 'created_at', 'generated_on', 'generatedOn']) ||
        new Date().toISOString().split('T')[0]
    ),
    earnings: constructedEarnings,
    deductions: constructedDeductions,
    authorizedSignatory: String(
      findDeepValue(item, ['authorized_signatory', 'authorizedSignatory']) || 'Seema Srivastava'
    ),
    signatoryRole: String(findDeepValue(item, ['signatory_role', 'signatoryRole']) || '(Director)'),
    hrNote: String(
      findDeepValue(item, ['hr_note', 'hrNote', 'remarks']) ||
        'For any discrepancies, please contact the HR department within 3 working days.'
    ),
    isVoid: resolvePayrollStatus(item) === 'void',
    voidReason: String(
      findDeepValue(item, ['void_reason', 'voidReason']) ||
      (String(findDeepValue(item, ['hr_note', 'hrNote', 'remarks']) || '').includes('[VOID: ')
        ? String(findDeepValue(item, ['hr_note', 'hrNote', 'remarks']) || '')
            .split('[VOID: ')[1]
            ?.split(']')[0]
            ?.split('|')[0]
            ?.trim()
        : '')
    ),
    paymentStatus: resolvePayrollStatus(item),
  };
};

const MyPaySlipPage = () => {
  const [search, setSearch] = useState('');
  const [selectedSlip, setSelectedSlip] = useState<PayrollRecord | null>(null);
  const [showTaxProjection, setShowTaxProjection] = useState(false);
  const [statusVersion, setStatusVersion] = useState(0);

  // Extract user details directly from useAuth hook
  const { user } = useAuth();
  const userId = user?.id;

  const hiddenPdfRef = useRef<HTMLDivElement>(null);

  // 1. Primary dedicated query: fetch salary slips specifically for this employee
  const {
    data: empSlipsData,
    isLoading: isEmpLoading,
    isError: isEmpError,
    refetch: refetchEmpSlips,
  } = useGetSalarySlipsByEmployeeIdQuery(userId!, {
    skip: !userId,
    refetchOnMountOrArgChange: true,
  });

  // 2. Query all slips only if user has elevated access and employee query returned empty
  const isElevated =
    user?.role === 'SuperAdmin' ||
    user?.role === 'Admin' ||
    user?.role === 'FinanceAdmin' ||
    user?.role === 'HrAdmin';

  const shouldFetchAll = Boolean(isElevated && !isEmpLoading && (!empSlipsData || !empSlipsData?.length));

  const {
    data: allSlipsData,
    isLoading: isAllLoading,
    refetch: refetchAllSlips,
  } = useGetAllSalarySlipsQuery(undefined, {
    skip: !shouldFetchAll,
    refetchOnMountOrArgChange: true,
  });

  const isLoading = (!user && !userId) || isEmpLoading || (shouldFetchAll && isAllLoading);
  const isError = isEmpError && (!shouldFetchAll || !allSlipsData);

  // Synchronize payment status overrides instantly across tabs and page events
  useEffect(() => {
    const handleStatusSync = () => {
      setStatusVersion((prev) => prev + 1);
      refetchEmpSlips();
      if (shouldFetchAll) refetchAllSlips();
    };
    window.addEventListener('payroll_status_updated', handleStatusSync);
    window.addEventListener('payroll_data_updated', handleStatusSync);
    window.addEventListener('storage', handleStatusSync);
    return () => {
      window.removeEventListener('payroll_status_updated', handleStatusSync);
      window.removeEventListener('payroll_data_updated', handleStatusSync);
      window.removeEventListener('storage', handleStatusSync);
    };
  }, [refetchEmpSlips, refetchAllSlips, shouldFetchAll]);

  // Handles PDF generation identically to the main Payroll page using html2canvas
  const handleDownload = async (record: PayrollRecord) => {
    try {
      message.loading({ content: 'Preparing document...', key: 'dl' });
      setSelectedSlip(record);

      await new Promise<void>((resolve) => {
        requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
      });
      if (document.fonts) {
        await document.fonts.ready;
      }
      await new Promise((resolve) => setTimeout(resolve, 400));

      if (!hiddenPdfRef.current) throw new Error('Template container not ready');

      const targetEl =
        (hiddenPdfRef.current.querySelector('.salary-statement-paper') as HTMLElement) ||
        hiddenPdfRef.current;

      const canvas = await html2canvas(targetEl, {
        scale: 2,
        useCORS: true,
        backgroundColor: '#ffffff',
        logging: false,
        allowTaint: true,
        scrollX: 0,
        scrollY: 0,
        windowWidth: 1000,
        onclone: (clonedDoc) => {
          const clonedEl = clonedDoc.querySelector('.salary-statement-paper') as HTMLElement;
          if (clonedEl) {
            clonedEl.style.display = 'block';
            clonedEl.style.position = 'static';
            clonedEl.style.margin = '0 auto';
            clonedEl.style.overflow = 'visible';
            clonedEl.style.boxSizing = 'border-box';
          }
        },
      });

      const imgData = canvas.toDataURL('image/png', 1.0);
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pdfWidth = 210;
      const pdfHeight = 297;
      const imgWidth = pdfWidth;
      const imgHeight = (canvas.height * pdfWidth) / canvas.width;

      if (imgHeight > pdfHeight) {
        const ratio = pdfHeight / imgHeight;
        const adjustedWidth = imgWidth * ratio;
        const adjustedHeight = pdfHeight;
        const xOffset = (pdfWidth - adjustedWidth) / 2;

        pdf.addImage(imgData, 'PNG', xOffset, 0, adjustedWidth, adjustedHeight);
      } else {
        pdf.addImage(imgData, 'PNG', 0, 0, imgWidth, imgHeight);
      }

      pdf.save(`Salary-Slip-${record.employeeName.replace(/\s+/g, '_')}-${record.monthYear}.pdf`);

      message.success({ content: 'Salary slip downloaded!', key: 'dl' });
    } catch (err) {
      console.error('PDF error:', err);
      message.error({ content: 'Failed to download PDF.', key: 'dl' });
    }
  };

  const userPayslips: ParsedSalarySlip[] = useMemo(() => {
    // If user is not authenticated or not loaded yet, return empty list (NEVER return all records)
    if (!user) return [];

    const currentUserId = user.id;
    const currentEmpCode = user.employee_code || user.employeeCode || user.employee_id;
    const currentUsername = user.username;
    const currentEmail = user.email;

    // Prefer dedicated employee slips; fallback to all slips if needed
    const rawEmpList: Record<string, unknown>[] = empSlipsData?.data
      ? Array.isArray(empSlipsData.data)
        ? empSlipsData.data
        : [empSlipsData.data]
      : Array.isArray(empSlipsData)
        ? empSlipsData
        : [];

    const rawAllList: Record<string, unknown>[] = allSlipsData?.data
      ? Array.isArray(allSlipsData.data)
        ? allSlipsData.data
        : [allSlipsData.data]
      : Array.isArray(allSlipsData)
        ? allSlipsData
        : [];

    const rawList = rawEmpList.length > 0 ? rawEmpList : rawAllList;
    if (!Array.isArray(rawList) || rawList.length === 0) return [];

    // Strictly filter to ensure ONLY the current employee's slips are included
    const userRecords = rawList.filter((item) => {
      const itemUserId = findDeepValue(item, ['user_id', 'userId']);
      const itemEmpCode = findDeepValue(item, ['employee_code', 'employeeCode', 'employee_id', 'employeeId']);
      const itemUsername = findDeepValue(item, ['username', 'employeeName', 'employee_name']);
      const itemEmail = findDeepValue(item, ['user_email', 'email', 'userEmail']);

      // 1. Direct match by User ID
      if (itemUserId && currentUserId && Number(itemUserId) === Number(currentUserId)) {
        return true;
      }
      // 2. Direct match by Employee Code (e.g. E001)
      if (
        itemEmpCode &&
        currentEmpCode &&
        String(itemEmpCode).trim().toLowerCase() === String(currentEmpCode).trim().toLowerCase()
      ) {
        return true;
      }
      // 3. User ID equals Employee Code or vice versa
      if (
        itemEmpCode &&
        currentUserId &&
        String(itemEmpCode).trim().toLowerCase() === String(currentUserId).trim().toLowerCase()
      ) {
        return true;
      }
      // 4. Match by Email
      if (
        itemEmail &&
        currentEmail &&
        String(itemEmail).trim().toLowerCase() === String(currentEmail).trim().toLowerCase()
      ) {
        return true;
      }
      // 5. Match by username
      if (
        itemUsername &&
        currentUsername &&
        String(itemUsername).trim().toLowerCase() === String(currentUsername).trim().toLowerCase()
      ) {
        return true;
      }

      // If data was directly returned from the employee endpoint `/finance/salary-slips/employee/:userId`
      if (rawEmpList.length > 0 && rawEmpList.includes(item)) {
        // Exclude if item explicitly specifies a different user_id
        if (itemUserId && currentUserId && Number(itemUserId) !== Number(currentUserId)) {
          return false;
        }
        return true;
      }

      return false;
    });

    const parsed = userRecords.map((item): ParsedSalarySlip => {
      const formatted = formatApiRecord(item);

      return {
        id: formatted.id,
        employeeId: formatted.employeeId,
        employeeName: formatted.employeeName,
        position: formatted.position,
        basePay: formatted.base,
        bonusPay: formatted.bonus,
        netSalary: formatted.total,
        monthYear: formatted.monthYear,
        payPeriod: formatted.payPeriod,
        paySlipNo: formatted.paySlipNo,
        accountNumber: formatted.accountNumber,
        paidDays: formatted.paidDays,
        lopDays: formatted.lopDays,
        earnings: formatted.earnings,
        deductions: formatted.deductions,
        authorizedSignatory: formatted.authorizedSignatory,
        signatoryRole: formatted.signatoryRole,
        hrNote: formatted.hrNote,
        createdAt: formatted.generatedOn,
        createdBy: String(findDeepValue(item, ['created_by_username', 'createdBy']) || 'HR Dept'),
        rawRecord: formatted,
        paymentStatus: formatted.paymentStatus,
      };
    });

    // Sort slips: newest first
    parsed.sort((a, b) => {
      const aMonthYear = a.monthYear || '';
      const bMonthYear = b.monthYear || '';
      return String(bMonthYear).localeCompare(String(aMonthYear)) || Number(b.id || 0) - Number(a.id || 0);
    });

    return parsed;
  }, [empSlipsData, allSlipsData, user, statusVersion]);

  // Auto-sync selectedSlip if open in view modal
  useEffect(() => {
    if (selectedSlip && userPayslips.length > 0) {
      const updated = userPayslips.find((p) => p.id === selectedSlip.id);
      if (updated && updated.rawRecord) {
        setSelectedSlip(updated.rawRecord);
      }
    }
  }, [userPayslips]);

  const currentUsername = user?.username || 'User';

  const formatMonthYear = useCallback((dateStr: string) => {
    if (!dateStr || dateStr === 'N/A') return 'N/A';
    const parsed = new Date(dateStr);
    if (isNaN(parsed.getTime())) return dateStr;
    return parsed.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  }, []);

  const formatDate = useCallback((dateStr: string) => {
    if (!dateStr || dateStr === 'N/A') return 'N/A';
    const parsed = new Date(dateStr);
    if (isNaN(parsed.getTime())) return dateStr;
    return parsed.toLocaleDateString('en-IN', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    });
  }, []);

  const filteredSlips = useMemo(() => {
    const query = search.toLowerCase().trim();
    if (!query) return userPayslips;

    return userPayslips.filter((slip) => {
      return (
        slip.paySlipNo.toLowerCase().includes(query) ||
        slip.monthYear.toLowerCase().includes(query) ||
        slip.employeeName.toLowerCase().includes(query) ||
        (slip.paymentStatus && slip.paymentStatus.toLowerCase().includes(query)) ||
        String(slip.netSalary).includes(query) ||
        String(slip.id).includes(query)
      );
    });
  }, [userPayslips, search]);

  const handleRefetch = () => {
    refetchEmpSlips();
    if (shouldFetchAll) refetchAllSlips();
  };

  if (isLoading) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center p-8 text-slate-500 gap-3">
        <Loader2 size={36} className="animate-spin text-slate-900" />
        <p className="text-sm font-medium text-slate-600">
          Fetching salary records from finance...
        </p>
      </div>
    );
  }

  if (isError) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center p-8 text-center max-w-md mx-auto space-y-4">
        <div className="w-14 h-14 rounded-2xl bg-red-50 text-red-600 flex items-center justify-center shadow-sm">
          <AlertCircle size={28} />
        </div>
        <div>
          <h2 className="font-semibold text-slate-900 text-lg">Failed to load salary slips</h2>
          <p className="text-xs text-slate-500 mt-1">
            Could not retrieve finance records for{' '}
            <strong className="text-slate-800">@{currentUsername}</strong>.
          </p>
        </div>
        <button
          onClick={handleRefetch}
          className="px-5 py-2.5 bg-slate-900 text-white text-xs font-medium rounded-xl hover:bg-slate-800 transition-all shadow-sm active:scale-95">
          Retry Connection
        </button>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50/60 p-4 sm:p-6 md:p-10 w-full mx-auto space-y-8">
      {/* Header Profile Section */}
      <div className="bg-white p-6 sm:p-8 rounded-3xl border border-slate-200/80 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-tr from-slate-900 via-slate-800 to-indigo-900 text-white flex items-center justify-center font-bold text-2xl shadow-md ring-4 ring-slate-100 shrink-0">
            {currentUsername.charAt(0).toUpperCase()}
          </div>
          <div className="space-y-1">
            <div className="flex items-center gap-2 flex-wrap">
              <h1 className="text-2xl font-bold text-slate-900">@{currentUsername}</h1>
              {user?.role === 'SuperAdmin' && (
                <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-amber-800 bg-amber-50 border border-amber-200 px-2.5 py-0.5 rounded-full">
                  <ShieldCheck size={12} /> Superadmin
                </span>
              )}
            </div>

            <div className="flex items-center gap-3 text-xs text-slate-500 flex-wrap">
              <span className="flex items-center gap-1">
                <Building2 size={13} className="text-slate-400" />
                {user?.department || 'Finance'}
              </span>
              <span>•</span>
              <span className="flex items-center gap-1">
                <Briefcase size={13} className="text-slate-400" />
                {user?.role || 'Employee'}
              </span>
              {userId && (
                <>
                  <span>•</span>
                  <span className="font-mono text-slate-700">ID: #{userId}</span>
                </>
              )}
            </div>
          </div>
        </div>

        {/* Actions & Search Field */}
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
          <button
            type="button"
            onClick={() => setShowTaxProjection(true)}
            className="flex items-center justify-center gap-2 px-4 py-2.5 bg-slate-900 text-white rounded-2xl text-xs font-bold hover:bg-slate-800 transition shadow-sm active:scale-95 shrink-0">
            <FileSpreadsheet size={15} className="text-emerald-400" />
            My Tax Projection
          </button>

          <div className="relative w-full sm:w-72">
            <Search
              size={16}
              className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400"
            />
            <input
              type="text"
              placeholder="Search slip no, month, amount..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-10 pr-9 py-2.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm text-slate-800 placeholder-slate-400 outline-none focus:border-slate-800 focus:bg-white transition-all shadow-inner"
            />
            {search && (
              <button
                onClick={() => setSearch('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                aria-label="Clear search">
                <X size={14} />
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Salary Slips Table */}
      <div className="bg-white rounded-3xl border border-slate-200/90 shadow-sm overflow-hidden">
        <div className="p-5 sm:p-6 border-b border-slate-100 flex items-center justify-between gap-4">
          <div>
            <h2 className="text-lg font-bold text-slate-900 flex items-center gap-2">
              My Pay Slips
              <span className="text-xs font-semibold text-indigo-700 bg-indigo-50 border border-indigo-100 px-2.5 py-0.5 rounded-full">
                {filteredSlips.length} Record(s)
              </span>
            </h2>
            <p className="text-xs text-slate-500 mt-0.5">
              Statements generated via finance department
            </p>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-sm">
            <thead>
              <tr className="bg-slate-50/80 border-b border-slate-200/80 text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                <th className="py-3.5 px-6">Slip No</th>
                <th className="py-3.5 px-6">Pay Period</th>
                <th className="py-3.5 px-6">Base Salary</th>
                <th className="py-3.5 px-6">Net Salary</th>
                <th className="py-3.5 px-6">Days Worked</th>
                <th className="py-3.5 px-6">Status</th>
                <th className="py-3.5 px-6">Created Date</th>
                <th className="py-3.5 px-6 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-slate-700">
              {filteredSlips.length === 0 ? (
                <tr>
                  <td colSpan={8} className="py-12 text-center text-slate-400">
                    <div className="flex flex-col items-center justify-center space-y-2">
                      <FileText size={32} className="text-slate-300" />
                      <p className="text-sm font-medium text-slate-600">No salary slips found.</p>
                    </div>
                  </td>
                </tr>
              ) : (
                filteredSlips.map((slip) => (
                  <tr key={slip.id} className="hover:bg-slate-50/80 transition-colors group">
                    <td className="py-4 px-6 font-mono text-xs font-bold text-slate-900">
                      <span className="inline-flex items-center gap-1 bg-slate-100 border border-slate-200 px-2.5 py-1 rounded-lg">
                        <Sparkles size={11} className="text-slate-400" /> {slip.paySlipNo}
                      </span>
                    </td>

                    <td className="py-4 px-6">
                      <div className="flex items-center gap-2">
                        <Calendar size={15} className="text-slate-400" />
                        <span className="font-bold text-slate-900">
                          {formatMonthYear(slip.monthYear)}
                        </span>
                      </div>
                    </td>

                    <td className="py-4 px-6 font-semibold text-slate-700">
                      ₹{slip.basePay.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                    </td>

                    <td className="py-4 px-6 font-bold text-emerald-600">
                      {slip.rawRecord?.isVoid ? (
                        <div className="flex flex-col">
                          <span className="text-slate-400 line-through">
                            ₹{slip.netSalary.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                          </span>
                          <span className="inline-flex items-center gap-1 text-[10px] font-bold text-rose-600 uppercase">
                            Voided Slip
                          </span>
                        </div>
                      ) : (
                        `₹${slip.netSalary.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`
                      )}
                    </td>

                    <td className="py-4 px-6 text-xs text-slate-600">
                      <span className="font-medium text-slate-800">{slip.paidDays}</span> Days
                    </td>

                    <td className="py-4 px-6">
                      {slip.rawRecord?.isVoid || slip.paymentStatus === 'void' ? (
                        <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider bg-rose-50 text-rose-700 border border-rose-200 px-2 py-0.5 rounded-md">
                          <Ban size={11} className="text-rose-600" /> Void
                        </span>
                      ) : (slip.paymentStatus || '').toLowerCase() === 'paid' ? (
                        <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider bg-emerald-50 text-emerald-700 border border-emerald-200 px-2 py-0.5 rounded-md">
                          <CheckCircle2 size={11} className="text-emerald-600" /> Paid
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider bg-amber-50 text-amber-700 border border-amber-200 px-2 py-0.5 rounded-md">
                          <Clock size={11} className="text-amber-600" /> Pending
                        </span>
                      )}
                    </td>

                    <td className="py-4 px-6 text-xs text-slate-500">
                      {formatDate(slip.createdAt)}
                    </td>

                    <td className="py-4 px-6 text-right">
                      <div className="inline-flex items-center gap-2">
                        <button
                          onClick={() => setSelectedSlip(slip.rawRecord || null)}
                          className="inline-flex items-center gap-1 px-3 py-1.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-semibold transition active:scale-95"
                          title="View Details">
                          <Eye size={13} />
                          <span>View</span>
                        </button>
                        <button
                          onClick={() => slip.rawRecord && handleDownload(slip.rawRecord)}
                          className="inline-flex items-center gap-1 px-3 py-1.5 rounded-xl bg-slate-900 hover:bg-slate-800 text-white text-xs font-semibold transition active:scale-95 shadow-sm"
                          title="Download Salary Slip PDF">
                          <Download size={13} />
                          <span>PDF</span>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* View Salary Slip Template Modal */}
      {selectedSlip && (
        <div className="fixed inset-0 z-[10000] bg-black/70 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-[900px] max-h-[95vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col">
            <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 flex justify-between items-center z-10">
              <h2 className="font-bold text-lg text-gray-900">
                Salary Slip ({selectedSlip.employeeName} - {selectedSlip.monthYear})
              </h2>
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => handleDownload(selectedSlip)}
                  className="bg-black text-white px-4 py-2 rounded-xl text-sm font-semibold flex items-center gap-2 hover:bg-gray-800 transition">
                  <Download size={16} /> Download PDF
                </button>
                <button
                  type="button"
                  onClick={() => setSelectedSlip(null)}
                  className="border border-gray-300 px-4 py-2 rounded-xl text-sm font-semibold hover:bg-gray-100 transition">
                  Close
                </button>
              </div>
            </div>
            <div className="overflow-auto bg-gray-100 p-6 flex justify-center">
              <SalarySlipTemplate data={selectedSlip} />
            </div>
          </div>
        </div>
      )}

      {/* Off-screen render container for PDF downloading */}
      <div
        style={{
          position: 'fixed',
          left: '-9999px',
          top: 0,
          width: '794px',
          opacity: 1,
          pointerEvents: 'none',
          zIndex: -9999,
        }}>
        {selectedSlip && (
          <div ref={hiddenPdfRef} style={{ width: '794px', background: '#ffffff' }}>
            <SalarySlipTemplate data={selectedSlip} />
          </div>
        )}
      </div>

      {showTaxProjection && (
        <TaxProjectionModal
          isOpen={showTaxProjection}
          onClose={() => setShowTaxProjection(false)}
          isSelfService={true}
          initialEmployee={user}
        />
      )}
    </div>
  );
};

export default MyPaySlipPage;

import { Table, Dropdown, App, Modal } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import {
  User,
  Briefcase,
  Calendar,
  UserCheck,
  Clock,
  MoreHorizontal,
  Plus,
  Eye,
  Edit3,
  Download,
  Trash2,
  FileSpreadsheet,
  Filter,
  Sparkles,
  Ban,
  CheckCircle2,
} from 'lucide-react';
import { motion } from 'framer-motion';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';
import { useRef, useState, useEffect, useMemo } from 'react';
import {
  useGetAllSalarySlipsQuery,
  useCreateSalarySlipMutation,
  useDeleteSalarySlipMutation,
  useUpdateSalarySlipMutation,
  useGetSalarySlipAuditLogsQuery,
  useClearMonthAuditLogsMutation,
  useCreatePayrollAdjustmentMutation,
  useGetPayrollAdjustmentsQuery,
} from '@/store/api/financeApiSlice';
import { useAuth } from '@/hooks/useAuth';
import { recordAuditLog as recordSystemAuditLog } from '@/services/auditService';
import {
  exportPayrollAuditLogs,
  filterLogsByRetention,
  getThreeMonthsCutoff,
  pruneLocalStorageLogs,
} from '@/utils/auditExport';
import SalarySlipForm, {
  extractSlipNumber,
  saveSlipNumberOverrides,
  normalizeToDashedSlipNumber,
} from './components/SalarySlipForm';
import SalarySlipTemplate from './components/SalarySlipTemplate';
import { TaxProjectionModal } from './components/TaxProjectionModal';
import VoidPayrollModal from './components/VoidPayrollModal';
import { getStoredPayrollSettings } from '@/types/payrollSettings';
import type { SalarySlipData } from './components/SalarySlipForm';
import { PageHeader } from '@/components/ui/composed/PageHeader';

export interface PayrollRecord {
  id: number;
  userId: number;
  employeeCode: string;
  department: string;
  paymentStatus: string;
  base: number;
  bonus: number;
  total: number;
  date: string;
  monthYear: string;
  month_year?: string;
  paySlipNo: string;
  pay_slip_no?: string;
  payPeriod: string;
  pay_period?: string;
  payrollType?: 'Regular' | 'Adjustment';
  adjustmentType?: string;
  payCycle?: string;
  taxRegime?: string;
  panNumber?: string;
  pan_number?: string;
  pan?: string;
  totalCompensation?: number;
  referencedPeriod?: string;
  companyName: string;
  company_name?: string;
  companyAddress: string;
  company_address?: string;
  employeeId: string;
  employeeName: string;
  position: string;
  accountNumber: string;
  account_number?: string;
  bankAccountNumber?: string;
  bank_account_number?: string;
  paidDays: number;
  lopDays: number;
  generatedOn: string;
  createdBy: string;
  created_by_username?: string;
  earnings: Array<{ name: string; amount: number }>;
  deductions: Array<{ name: string; amount: number }>;
  authorizedSignatory: string;
  signatoryRole: string;
  hrNote: string;
  payPeriodMonth?: number;
  payPeriodYear?: number;
  rawRecord?: Record<string, any>;
  isVoid?: boolean;
  voidReason?: string;
  voidNotes?: string;
  voidedAt?: string;
  voidedBy?: string;
}

export const PAYROLL_STATUS_STORAGE_KEY = 'aetheradix_payroll_status_overrides';

export const getPayrollStatusOverrides = (): Record<string, 'pending' | 'paid'> => {
  try {
    const raw = localStorage.getItem(PAYROLL_STATUS_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
};

export const savePayrollStatusOverride = (id: string | number, status: 'pending' | 'paid' | 'void') => {
  try {
    const current = getPayrollStatusOverrides();
    current[String(id)] = status as any;
    localStorage.setItem(PAYROLL_STATUS_STORAGE_KEY, JSON.stringify(current));
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('payroll_status_updated', { detail: { id, status } }));
    }
  } catch (e) {
    console.warn('Failed to save payroll status override:', e);
  }
};

export const resolvePayrollStatus = (item: Record<string, any>): 'void' | 'paid' | 'pending' => {
  const isVoid =
    item.is_void === true ||
    item.is_void === 1 ||
    item.isVoid === true ||
    String(item.payment_status || item.paymentStatus || '').toLowerCase() === 'void' ||
    String(item.hr_note || item.hrNote || item.remarks || '').includes('[VOID');

  if (isVoid) return 'void';

  const itemId = String(item.id || item.salary_slip_id || item.salarySlipId || '');
  const statusOverrides = getPayrollStatusOverrides();
  const overrideStatus = itemId ? statusOverrides[itemId] : undefined;

  // 1. If explicit override was set by user action, prioritize it for instant reactivity across pages
  if (overrideStatus === 'paid' || overrideStatus === 'pending') {
    return overrideStatus;
  }

  // 2. Fall back to server payment_status
  const raw = String(item.payment_status || item.paymentStatus || item.status || '').toLowerCase().trim();
  if (raw === 'paid') return 'paid';
  return 'pending';
};

const formatApiRecord = (item: Record<string, any>, fallbackSeq?: number): PayrollRecord => {
  const monthNames = [
    'JANUARY',
    'FEBRUARY',
    'MARCH',
    'APRIL',
    'MAY',
    'JUNE',
    'JULY',
    'AUGUST',
    'SEPTEMBER',
    'OCTOBER',
    'NOVEMBER',
    'DECEMBER',
  ];

  const monthIdx = (Number(item.pay_period_month) || 1) - 1;
  const monthStr = monthNames[monthIdx] || 'OCTOBER';
  const yearStr = String(item.pay_period_year || 2026);
  const monthYearStr = `${monthStr} ${yearStr}`;

  const resolvedSlipNo = extractSlipNumber(item, fallbackSeq);

  const basicSalary = Number(item.basic_salary || 0);
  const bonusVal = Number(item.bonus || 0);
  const netVal = Number(item.net_salary || 0);

  // Extract Payroll Type & Adjustments (from native field or serialized in remarks)
  const isAdjustmentRemark =
    typeof item.remarks === 'string' && item.remarks.includes('[ADJUSTMENT');
  const detectedPayrollType: 'Regular' | 'Adjustment' =
    item.payroll_type || item.payrollType || (isAdjustmentRemark ? 'Adjustment' : 'Regular');

  let detectedAdjType = item.adjustment_type || item.adjustmentType || '';
  if (!detectedAdjType && isAdjustmentRemark) {
    const afterPrefix = item.remarks.split('[ADJUSTMENT - ')[1];
    if (afterPrefix) {
      detectedAdjType = afterPrefix.split(']')[0].split('|')[0].trim();
    }
  }

  // Detect Void Status (from field or serialized in remarks)
  const isVoid =
    item.is_void === true ||
    item.isVoid === true ||
    item.payment_status === 'void' ||
    item.paymentStatus === 'void' ||
    (typeof item.remarks === 'string' && item.remarks.includes('[VOID'));

  let detectedVoidReason = item.void_reason || item.voidReason || '';
  let detectedVoidNotes = item.void_notes || item.voidNotes || '';
  if (!detectedVoidReason && typeof item.remarks === 'string' && item.remarks.includes('[VOID: ')) {
    const afterPrefix = item.remarks.split('[VOID: ')[1];
    if (afterPrefix) {
      const rawVoid = afterPrefix.split(']')[0];
      if (rawVoid.includes('|')) {
        const [r, ...n] = rawVoid.split('|');
        detectedVoidReason = r.trim();
        detectedVoidNotes = n.join('|').trim();
      } else {
        detectedVoidReason = rawVoid.trim();
      }
    }
  }

  const effectiveStatus = resolvePayrollStatus(item);

  const detectedCycle =
    item.pay_cycle ||
    item.payCycle ||
    (item.pay_frequency
      ? item.pay_frequency.charAt(0).toUpperCase() + item.pay_frequency.slice(1)
      : 'Monthly');

  const rawPan = String(
    item.pan_number || item.panNumber || item.pan || ''
  ).trim();
  const rawAccount = String(
    item.bank_account_number ||
    item.bankAccountNumber ||
    item.account_number ||
    item.accountNumber ||
    ''
  ).trim();
  const fullAddress = String(
    item.company_address ||
    item.companyAddress ||
    'F-N 507, Crystal Tower, IBD Kings Park, Bawadia Kalan, Bhopal, MP | 462039'
  );

  const rawId = item.id || item.salary_slip_id || item.slip_id;
  const recordId =
    rawId !== undefined && rawId !== null && rawId !== ''
      ? rawId
      : `${item.user_id || item.userId || 'u'}_${item.pay_period_year || 2026}_${item.pay_period_month || 1}`;

  return {
    ...item,
    id: recordId,
    userId: item.user_id,
    base: basicSalary,
    bonus: bonusVal,
    total: netVal,
    date: monthYearStr,
    monthYear: monthYearStr,
    payPeriod: item.pay_period || item.payPeriod || monthYearStr,
    pay_period: item.pay_period || item.payPeriod || monthYearStr,
    payrollType: detectedPayrollType,
    adjustmentType: detectedAdjType,
    payCycle: detectedCycle,
    taxRegime: item.tax_regime || item.taxRegime || 'New Regime',
    panNumber: rawPan,
    pan_number: rawPan,
    pan: rawPan,
    totalCompensation: Number(item.total_compensation || item.totalCompensation || 0),
    referencedPeriod: item.referenced_period || item.referencedPeriod || '',
    companyName: item.company_name || item.companyName || 'AETHERADIX',
    company_name: item.company_name || item.companyName || 'AETHERADIX',
    companyAddress: fullAddress,
    company_address: fullAddress,
    employeeId: String(item.employee_code || item.user_id),
    employeeName: item.username || item.employee_name || item.employeeName || 'Unknown Employee',
    employeeCode: item.employee_code || String(item.user_id),
    position: item.designation || item.position || 'N/A',
    department: item.department || 'N/A',
    accountNumber: rawAccount || (item.bank_account_number && item.bank_account_number !== 'N/A' ? item.bank_account_number : ''),
    account_number: rawAccount,
    bankAccountNumber: rawAccount,
    bank_account_number: rawAccount,
    authorizedSignatory:
      item.authorized_signatory || item.authorizedSignatory || 'Seema Srivastava',
    signatoryRole: item.signatory_role || item.signatoryRole || '(Director)',
    payPeriodMonth: item.pay_period_month,
    payPeriodYear: item.pay_period_year,
    paySlipNo: resolvedSlipNo,
    paidDays: Number(item.days_worked || item.total_working_days || item.paid_days || 0),
    lopDays: Number(item.leave_days || item.lop_days || 0),
    paymentStatus: effectiveStatus,
    rawRecord: item,
    isVoid,
    voidReason: detectedVoidReason,
    voidNotes: detectedVoidNotes,
    voidedAt: item.voided_at || item.voidedAt || '',
    voidedBy: item.voided_by || item.voidedBy || '',
    generatedOn: item.payment_date || item.created_at?.split('T')[0] || '',
    createdBy: item.created_by_username || 'System',
    created_by_username: item.created_by_username || 'System',
    earnings: [
      { name: 'Basic Salary', amount: Number(item.basic_salary || 0) },
      { name: 'House Rent Allowance (HRA)', amount: Number(item.house_rent_allowance || 0) },
      { name: 'Special Allowance', amount: Number(item.special_allowance || 0) },
      { name: 'Conveyance Allowance', amount: Number(item.conveyance_allowance || 0) },
      { name: 'Bonus', amount: Number(item.bonus || 0) },
      { name: 'Other Earnings', amount: Number(item.other_earnings || 0) },
    ],
    deductions: [
      { name: 'Provident Fund (PF)', amount: Number(item.provident_fund || 0) },
      { name: 'Professional Tax', amount: Number(item.professional_tax || 0) },
      { name: 'Income Tax (TDS)', amount: Number(item.income_tax_tds || 0) },
      { name: 'Other Deductions', amount: Number(item.other_deductions || 0) },
    ],
    hrNote:
      item.hr_note ||
      item.hrNote ||
      item.remarks ||
      'For any discrepancies, please contact the HR department within 3 working days.',
  };
};

export default function PayrollPage() {
  const { message } = App.useApp();

  const {
    data: rawData,
    isLoading: isFetching,
    isError,
    refetch: refetchSlips, // 👈 Destructure refetch
  } = useGetAllSalarySlipsQuery(undefined, {
    refetchOnMountOrArgChange: true,
  });

  const {
    data: auditLogsData,
    isLoading: isLogsLoading,
    refetch: refetchLogs, // 👈 Destructure refetch
  } = useGetSalarySlipAuditLogsQuery(undefined, {
    refetchOnMountOrArgChange: true,
  });

  const [createSalarySlip, { isLoading: isCreating }] = useCreateSalarySlipMutation();
  const [updateSalarySlip, { isLoading: isUpdating }] = useUpdateSalarySlipMutation();
  const [deleteSalarySlip, { isLoading: isDeleting }] = useDeleteSalarySlipMutation();
  const [clearMonthAuditLogsApi, { isLoading: isClearingMonth }] = useClearMonthAuditLogsMutation();
  const [createAdjustment, { isLoading: isCreatingAdjustment }] =
    useCreatePayrollAdjustmentMutation();
  const { refetch: refetchAdjustments } = useGetPayrollAdjustmentsQuery(undefined, {
    refetchOnMountOrArgChange: true,
  });

  const { user: authUser } = useAuth();

  const [payroll, setPayroll] = useState<PayrollRecord[]>([]);
  const [filteredPayroll, setFilteredPayroll] = useState<PayrollRecord[]>([]);
  const [searchText, setSearchText] = useState('');
  const [typeFilter, setTypeFilter] = useState<'ALL' | 'Regular' | 'Adjustment'>('ALL');
  const [cycleFilter, setCycleFilter] = useState<string>('ALL');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'Pending' | 'Paid' | 'Void'>('ALL');

  const [showSalarySlipForm, setShowSalarySlipForm] = useState(false);
  const [editingRecord, setEditingRecord] = useState<PayrollRecord | null>(null);
  const [selectedSlip, setSelectedSlip] = useState<PayrollRecord | null>(null);
  const [showSlipModal, setShowSlipModal] = useState(false);
  const [showTaxProjectionModal, setShowTaxProjectionModal] = useState(false);
  const [projectionEmployee, setProjectionEmployee] = useState<any | null>(null);

  // Clear Month State (1-Month Safe Purge)
  const [showClearMonthModal, setShowClearMonthModal] = useState(false);
  const [selectedClearMonth, setSelectedClearMonth] = useState(() => new Date().getMonth() + 1);
  const [selectedClearYear, setSelectedClearYear] = useState(() => new Date().getFullYear());

  // Void Modal State
  const [voidingRecord, setVoidingRecord] = useState<PayrollRecord | null>(null);
  const [showVoidModal, setShowVoidModal] = useState<boolean>(false);
  const [isVoiding, setIsVoiding] = useState<boolean>(false);

  // 💡 Local Payroll Audit Logs (with 3-Month Retention)
  const PAYROLL_LOGS_KEY = 'aether_erp_payroll_audit_logs';
  const [localPayrollLogs, setLocalPayrollLogs] = useState<any[]>(() => {
    try {
      pruneLocalStorageLogs(PAYROLL_LOGS_KEY, 'createdAt');
      const raw = localStorage.getItem(PAYROLL_LOGS_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed) && parsed.length > 0) {
          return filterLogsByRetention(parsed);
        }
      }
    } catch {
      // fallback
    }
    return [];
  });

  // Persist local payroll audit logs with 3-month retention
  useEffect(() => {
    try {
      localStorage.setItem(
        PAYROLL_LOGS_KEY,
        JSON.stringify(filterLogsByRetention(localPayrollLogs))
      );
    } catch (e) {
      console.warn('Failed to save local payroll logs:', e);
    }
  }, [localPayrollLogs]);

  // Combined Payroll Audit Logs (Backend query + Local events, strictly 3 months)
  const combinedPayrollLogs = useMemo(() => {
    const rawBackendLogs = Array.isArray(auditLogsData?.data)
      ? auditLogsData.data
      : Array.isArray(auditLogsData)
        ? auditLogsData
        : [];

    const formattedBackend = rawBackendLogs.map((item: any) => ({
      id: String(item.id || item._id || Math.random()),
      action: String(item.action || 'PAYROLL_ACTION'),
      description: String(item.description || item.details || 'Payroll modification recorded'),
      username: String(item.username || item.user || 'System'),
      createdAt: String(item.created_at || item.createdAt || new Date().toISOString()),
      status: String(item.status || 'Success'),
    }));

    const existingIds = new Set(localPayrollLogs.map((l) => String(l.id)));
    const uniqueBackend = formattedBackend.filter((b: any) => !existingIds.has(String(b.id)));
    const merged = [...localPayrollLogs, ...uniqueBackend];

    merged.sort(
      (a, b) =>
        new Date(b.createdAt || b.created_at || 0).getTime() -
        new Date(a.createdAt || a.created_at || 0).getTime()
    );

    // Enforce 3-month retention window
    return filterLogsByRetention(merged);
  }, [localPayrollLogs, auditLogsData]);

  const { formattedLabel: retentionCutoffLabel } = useMemo(() => getThreeMonthsCutoff(), []);

  const companyPayrollSettings = useMemo(() => getStoredPayrollSettings(), []);
  const hiddenPdfRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleSync = () => {
      refetchSlips();
      refetchLogs();
    };
    window.addEventListener('payroll_data_updated', handleSync);
    window.addEventListener('payroll_status_updated', handleSync);
    window.addEventListener('storage', handleSync);
    return () => {
      window.removeEventListener('payroll_data_updated', handleSync);
      window.removeEventListener('payroll_status_updated', handleSync);
      window.removeEventListener('storage', handleSync);
    };
  }, [refetchSlips, refetchLogs]);

  useEffect(() => {
    if (rawData) {
      const itemsList = Array.isArray(rawData?.data)
        ? rawData.data
        : Array.isArray(rawData)
          ? rawData
          : [];

      // Group items by pay period month/year so fallback sequence is distinct per record in that month
      // (1, 2, 3... 7), preventing everyone from defaulting to 001!
      const monthGroups: Record<string, any[]> = {};
      const monthNames = [
        'JANUARY',
        'FEBRUARY',
        'MARCH',
        'APRIL',
        'MAY',
        'JUNE',
        'JULY',
        'AUGUST',
        'SEPTEMBER',
        'OCTOBER',
        'NOVEMBER',
        'DECEMBER',
      ];

      itemsList.forEach((item: any) => {
        const mIdx = (Number(item.pay_period_month) || 1) - 1;
        const monthStr = monthNames[mIdx] || 'OCTOBER';
        const yearStr = String(item.pay_period_year || 2026);
        const my = `${monthStr} ${yearStr}`;
        if (!monthGroups[my]) monthGroups[my] = [];
        monthGroups[my].push(item);
      });

      const formattedRecords: PayrollRecord[] = [];
      Object.values(monthGroups).forEach((group) => {
        const sorted = [...group].sort((a, b) => Number(a.id || 0) - Number(b.id || 0));
        sorted.forEach((item, index) => {
          formattedRecords.push(formatApiRecord(item, index + 1));
        });
      });

      formattedRecords.sort((a: PayrollRecord, b: PayrollRecord) => {
        const yearDiff = Number(b.payPeriodYear || 0) - Number(a.payPeriodYear || 0);
        if (yearDiff !== 0) return yearDiff;
        return Number(b.payPeriodMonth || 0) - Number(a.payPeriodMonth || 0);
      });

      setPayroll(formattedRecords);
      setFilteredPayroll(formattedRecords);
    }
  }, [rawData]);

  useEffect(() => {
    let result = [...payroll];

    if (searchText.trim()) {
      const query = searchText.toLowerCase();
      result = result.filter(
        (item) =>
          item.employeeName?.toLowerCase().includes(query) ||
          item.employeeCode?.toLowerCase().includes(query) ||
          item.department?.toLowerCase().includes(query) ||
          item.paySlipNo?.toLowerCase().includes(query) ||
          item.paymentStatus?.toLowerCase().includes(query)
      );
    }

    if (typeFilter !== 'ALL') {
      result = result.filter((item) => (item.payrollType || 'Regular') === typeFilter);
    }

    if (cycleFilter !== 'ALL') {
      result = result.filter((item) => {
        const cycle = (item.payCycle || 'Monthly').toLowerCase();
        return cycle === cycleFilter.toLowerCase();
      });
    }

    if (statusFilter === 'Pending') {
      result = result.filter(
        (item) => !item.isVoid && (item.paymentStatus || '').toLowerCase() === 'pending'
      );
    } else if (statusFilter === 'Paid') {
      result = result.filter(
        (item) => !item.isVoid && (item.paymentStatus || '').toLowerCase() === 'paid'
      );
    } else if (statusFilter === 'Void') {
      result = result.filter((item) => item.isVoid || item.paymentStatus === 'void');
    }

    setFilteredPayroll(result);
  }, [searchText, payroll, typeFilter, cycleFilter, statusFilter]);

  const downloadSalarySlip = async (record: PayrollRecord) => {
    try {
      message.loading({ content: 'Preparing document...', key: 'dl' });
      setSelectedSlip(record);

      // 1. Force browser to finish layout & font glyph calculations
      await new Promise<void>((resolve) => {
        requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
      });
      if (document.fonts) {
        await document.fonts.ready;
      }
      await new Promise((resolve) => setTimeout(resolve, 400));

      if (!hiddenPdfRef.current) throw new Error('Template container not ready');

      const targetEl =
        (hiddenPdfRef.current.querySelector('.salary-statement-paper') as HTMLElement) ||
        hiddenPdfRef.current;

      // 2. Snapshot with letter rendering & clone bounds enforced
      const canvas = await html2canvas(targetEl, {
        scale: 2,
        useCORS: true,
        backgroundColor: '#ffffff',
        logging: false,
        allowTaint: true,
        scrollX: 0,
        scrollY: 0,
        windowWidth: 1000,
        onclone: (clonedDoc) => {
          const clonedEl = clonedDoc.querySelector('.salary-statement-paper') as HTMLElement;
          if (clonedEl) {
            clonedEl.style.display = 'block';
            clonedEl.style.position = 'static';
            clonedEl.style.margin = '0 auto';
            clonedEl.style.overflow = 'visible';
            clonedEl.style.boxSizing = 'border-box';
          }
        },
      });

      const imgData = canvas.toDataURL('image/png', 1.0);
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });

      const pdfWidth = 210;
      const pdfHeight = 297;
      const imgWidth = pdfWidth;
      const imgHeight = (canvas.height * pdfWidth) / canvas.width;

      if (imgHeight > pdfHeight) {
        const ratio = pdfHeight / imgHeight;
        const adjustedWidth = imgWidth * ratio;
        const adjustedHeight = pdfHeight;
        const xOffset = (pdfWidth - adjustedWidth) / 2;

        pdf.addImage(imgData, 'PNG', xOffset, 0, adjustedWidth, adjustedHeight);
      } else {
        pdf.addImage(imgData, 'PNG', 0, 0, imgWidth, imgHeight);
      }

      pdf.save(`Salary-Slip-${record.employeeName.replace(/\s+/g, '_')}-${record.monthYear}.pdf`);
      message.success({ content: 'Salary slip downloaded!', key: 'dl' });
    } catch (err) {
      console.error('PDF error:', err);
      message.error({ content: 'Failed to download PDF.', key: 'dl' });
    }
  };

  const handleFormSubmit = async (data: SalarySlipData) => {
    const key = 'salary-slip-action';
    try {
      const finalSlipNo = normalizeToDashedSlipNumber(data.paySlipNo);
      const targetId = editingRecord?.id || (data as any).id || (data as any).salary_slip_id;
      const targetEmpCode =
        data.employeeId ||
        (data as any).employee_code ||
        (data as any).employeeCode ||
        editingRecord?.employeeCode;
      const targetUserId = data.userId || (data as any).user_id || editingRecord?.userId;
      const targetMonthYear = data.monthYear || editingRecord?.monthYear;

      if (finalSlipNo) {
        saveSlipNumberOverrides(finalSlipNo, {
          id: targetId,
          empCode: targetEmpCode,
          userId: targetUserId,
          monthYear: targetMonthYear,
          month: (data as any).payPeriodMonth,
          year: (data as any).payPeriodYear,
        });
      }

      if (editingRecord) {
        message.loading({ content: 'Updating salary slip...', key });

        // Optimistically update the record in state right away so table updates immediately!
        setPayroll((prev) =>
          prev.map((r) => {
            const isMatch =
              (targetId && r.id === targetId) ||
              (targetEmpCode && r.employeeCode === targetEmpCode && r.monthYear === targetMonthYear) ||
              (targetUserId && r.userId === targetUserId && r.monthYear === targetMonthYear);
            if (isMatch) {
              const updatedItem: PayrollRecord = {
                ...r,
                ...data,
                id: (targetId || r.id) as any,
                userId: Number(data.userId || r.userId),
                base: data.baseSalary ? Number(data.baseSalary) : r.base,
                paidDays: data.paidDays !== undefined ? Number(data.paidDays) : r.paidDays,
                lopDays: data.lopDays !== undefined ? Number(data.lopDays) : r.lopDays,
                totalCompensation:
                  data.totalCompensation !== undefined && data.totalCompensation !== null && data.totalCompensation !== ''
                    ? Number(data.totalCompensation)
                    : r.totalCompensation,
                department: String(data.department || r.department || 'N/A'),
                employeeCode: String(targetEmpCode || r.employeeCode),
                employeeId: String(targetEmpCode || r.employeeId),
                employeeName: String(data.employeeName || r.employeeName),
                position: String(data.position || r.position || 'N/A'),
                accountNumber: String(data.accountNumber || r.accountNumber || ''),
                companyName: String(data.companyName || r.companyName || 'AETHERADIX'),
                companyAddress: String(data.companyAddress || r.companyAddress || ''),
                authorizedSignatory: String(data.authorizedSignatory || r.authorizedSignatory || 'Seema Srivastava'),
                signatoryRole: String(data.signatoryRole || r.signatoryRole || '(Director)'),
                hrNote: String(data.hrNote || r.hrNote || ''),
                paySlipNo: finalSlipNo || r.paySlipNo,
                paymentStatus: (data.paymentStatus || r.paymentStatus) as any,
              };
              return updatedItem;
            }
            return r;
          })
        );
        setFilteredPayroll((prev) =>
          prev.map((r) => {
            const isMatch =
              (targetId && r.id === targetId) ||
              (targetEmpCode && r.employeeCode === targetEmpCode && r.monthYear === targetMonthYear) ||
              (targetUserId && r.userId === targetUserId && r.monthYear === targetMonthYear);
            if (isMatch) {
              const updatedItem: PayrollRecord = {
                ...r,
                ...data,
                id: (targetId || r.id) as any,
                userId: Number(data.userId || r.userId),
                base: data.baseSalary ? Number(data.baseSalary) : r.base,
                paidDays: data.paidDays !== undefined ? Number(data.paidDays) : r.paidDays,
                lopDays: data.lopDays !== undefined ? Number(data.lopDays) : r.lopDays,
                totalCompensation:
                  data.totalCompensation !== undefined && data.totalCompensation !== null && data.totalCompensation !== ''
                    ? Number(data.totalCompensation)
                    : r.totalCompensation,
                department: String(data.department || r.department || 'N/A'),
                employeeCode: String(targetEmpCode || r.employeeCode),
                employeeId: String(targetEmpCode || r.employeeId),
                employeeName: String(data.employeeName || r.employeeName),
                position: String(data.position || r.position || 'N/A'),
                accountNumber: String(data.accountNumber || r.accountNumber || ''),
                companyName: String(data.companyName || r.companyName || 'AETHERADIX'),
                companyAddress: String(data.companyAddress || r.companyAddress || ''),
                authorizedSignatory: String(data.authorizedSignatory || r.authorizedSignatory || 'Seema Srivastava'),
                signatoryRole: String(data.signatoryRole || r.signatoryRole || '(Director)'),
                hrNote: String(data.hrNote || r.hrNote || ''),
                paySlipNo: finalSlipNo || r.paySlipNo,
                paymentStatus: (data.paymentStatus || r.paymentStatus) as any,
              };
              return updatedItem;
            }
            return r;
          })
        );

        try {
          if (!targetId) {
            throw new Error('Salary slip ID is missing. Unable to update.');
          }
          await updateSalarySlip({ id: targetId, ...data }).unwrap();
          message.success({ content: 'Salary slip updated successfully!', key });
          await Promise.all([refetchSlips(), refetchLogs()]);
          if (typeof window !== 'undefined') {
            window.dispatchEvent(new CustomEvent('payroll_data_updated', { detail: { id: targetId } }));
            localStorage.setItem('aether_payroll_last_update', String(Date.now()));
          }
        } catch (apiErr: any) {
          console.error('Backend updateSalarySlip response:', apiErr);
          message.error({
            content: apiErr?.data?.message || apiErr?.message || 'Failed to update salary slip on server.',
            key,
          });
          throw apiErr;
        }
      } else if (data.payrollType === 'Adjustment') {
        message.loading({ content: 'Recording payroll adjustment...', key });
        await createAdjustment({
          userId: Number(data.userId || (data as any).user_id),
          payrollType: 'adjustment',
          adjustmentType: data.adjustmentType || 'wrong_rate',
          adjustmentAmount: Number(data.adjustmentAmount || 0),
          adjustmentReason: data.adjustmentReason || data.adjustmentNotes || 'Adjustment processed',
          referencePeriod: data.referencePeriod || data.referencedPeriod || '',
          referenceSalarySlipId: data.referenceSalarySlipId
            ? Number(data.referenceSalarySlipId)
            : undefined,
          payFrequency: (data.payCycle || 'monthly').toLowerCase(),
          month: (data as any).payPeriodMonth || (data as any).month || new Date().getMonth() + 1,
          year: (data as any).payPeriodYear || (data as any).year || new Date().getFullYear(),
          cycleNumber: data.cyclePart || 1,
        }).unwrap();
        message.success({ content: 'Adjustment recorded and processed successfully!', key });
      } else {
        message.loading({ content: 'Saving salary slip...', key });
        const res = await createSalarySlip(data as any).unwrap();
        const createdId = res?.data?.id || res?.id || res?.result?.id;
        if (createdId && finalSlipNo) {
          saveSlipNumberOverrides(finalSlipNo, {
            id: createdId,
            empCode: data.employeeId,
            userId: data.userId || (data as any).user_id,
            monthYear: data.monthYear,
          });
        }
        message.success({ content: 'Salary slip recorded successfully!', key });
      }
      await Promise.all([refetchSlips(), refetchLogs(), refetchAdjustments()]);
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('payroll_data_updated', { detail: {} }));
        localStorage.setItem('aether_payroll_last_update', String(Date.now()));
      }

      setShowSalarySlipForm(false);
      setEditingRecord(null);
    } catch (error: any) {
      message.error({
        content: error?.data?.message || 'Failed to process payroll transaction.',
        key,
      });
    }
  };

  const handleEdit = (record: PayrollRecord) => {
    setEditingRecord(record);
    setShowSalarySlipForm(true);
  };

  const handleDelete = (record: PayrollRecord) => {
    Modal.confirm({
      title: 'Delete Salary Slip',
      content: `Are you sure you want to delete the salary slip for ${record.employeeName} (${record.monthYear})? This action cannot be undone.`,
      okText: 'Yes, Delete',
      okType: 'danger',
      cancelText: 'Cancel',
      maskClosable: true,
      onOk: async () => {
        const key = 'delete-salary-slip';
        try {
          message.loading({ content: 'Deleting salary slip...', key });
          await deleteSalarySlip(record.id).unwrap();
          message.success({ content: 'Salary slip deleted successfully!', key });
          await Promise.all([refetchSlips(), refetchLogs()]);
          if (typeof window !== 'undefined') {
            window.dispatchEvent(new CustomEvent('payroll_data_updated', { detail: { id: record.id } }));
            localStorage.setItem('aether_payroll_last_update', String(Date.now()));
          }
        } catch (error: any) {
          message.error({
            content: error?.data?.message || error?.message || 'Failed to delete salary slip.',
            key,
          });
        }
      },
    });
  };

  // Open Void Modal for a Payroll Slip
  const handleOpenVoidModal = (record: PayrollRecord) => {
    setVoidingRecord(record);
    setShowVoidModal(true);
  };

  // Confirm Marking as Void
  const handleConfirmVoid = async (reason: string, notes: string) => {
    if (!voidingRecord) return;
    setIsVoiding(true);
    const key = 'void-payroll-action';
    try {
      message.loading({ content: 'Marking salary slip as void...', key });
      const voidRemark = `[VOID: ${reason}${notes ? ` | ${notes}` : ''}] ${voidingRecord.hrNote || ''}`;
      savePayrollStatusOverride(voidingRecord.id, 'void');

      await updateSalarySlip({
        id: voidingRecord.id,
        payment_status: 'void',
        paymentStatus: 'void',
        is_void: true,
        isVoid: true,
        void_reason: reason,
        void_notes: notes,
        voided_at: new Date().toISOString(),
        voided_by: authUser?.username || 'Admin',
        remarks: voidRemark,
      }).unwrap();

      // 1. Central system audit log (saved with 3-month retention)
      recordSystemAuditLog({
        action: 'PAYROLL_VOIDED',
        category: 'payroll',
        user: authUser?.username || 'Admin',
        userEmail: authUser?.email || 'admin@aetheradix.com',
        target: `Salary Slip ${voidingRecord.paySlipNo} (${voidingRecord.employeeName})`,
        status: 'Warning',
        details: `Marked salary slip ${voidingRecord.paySlipNo} for ${voidingRecord.employeeName} (${voidingRecord.monthYear}) as VOID. Reason: ${reason}.${notes ? ` Notes: ${notes}` : ''}`,
        changes: [
          { field: 'paymentStatus', from: voidingRecord.paymentStatus || 'pending', to: 'void' },
          { field: 'isVoid', from: false, to: true },
          { field: 'voidReason', from: null, to: reason },
        ],
      });

      // 2. Local payroll audit log for instant display & offline persistence
      const newLog = {
        id: `pay-void-${Date.now()}`,
        action: 'VOID_SALARY_SLIP',
        description: `Marked salary slip ${voidingRecord.paySlipNo} (${voidingRecord.employeeName}) as VOID. Reason: ${reason}`,
        username: authUser?.username || 'Admin',
        createdAt: new Date().toISOString(),
        status: 'Warning',
      };
      setLocalPayrollLogs((prev) => filterLogsByRetention([newLog, ...prev]));

      message.success({
        content: `Salary slip ${voidingRecord.paySlipNo} marked as VOID successfully.`,
        key,
      });

      setShowVoidModal(false);
      setVoidingRecord(null);
      await Promise.all([refetchSlips(), refetchLogs()]);
      if (typeof window !== 'undefined') {
        window.dispatchEvent(
          new CustomEvent('payroll_data_updated', {
            detail: { id: voidingRecord.id, status: 'void' },
          })
        );
        localStorage.setItem('aether_payroll_last_update', String(Date.now()));
      }
    } catch (err: any) {
      message.error({
        content: err?.data?.message || 'Failed to mark salary slip as void.',
        key,
      });
    } finally {
      setIsVoiding(false);
    }
  };

  // Reactivate a Voided Salary Slip
  const handleUnvoid = (record: PayrollRecord) => {
    Modal.confirm({
      title: 'Reactivate Salary Slip',
      icon: <CheckCircle2 size={20} className="text-emerald-600" />,
      content: `Are you sure you want to reactivate the salary slip for ${record.employeeName} (${record.paySlipNo})? This will restore it to valid status.`,
      okText: 'Yes, Reactivate',
      okButtonProps: { className: '!bg-emerald-600' },
      cancelText: 'Cancel',
      onOk: async () => {
        const key = 'unvoid-action';
        try {
          message.loading({ content: 'Reactivating salary slip...', key });
          const cleanRemarks = (record.hrNote || '').replace(/\[VOID:[^\]]+\]\s*/g, '');
          savePayrollStatusOverride(record.id, 'pending');
          await updateSalarySlip({
            id: record.id,
            payment_status: 'pending',
            paymentStatus: 'pending',
            is_void: false,
            isVoid: false,
            void_reason: null,
            void_notes: null,
            remarks: cleanRemarks,
          }).unwrap();

          recordSystemAuditLog({
            action: 'PAYROLL_REACTIVATED',
            category: 'payroll',
            user: authUser?.username || 'Admin',
            userEmail: authUser?.email || 'admin@aetheradix.com',
            target: `Salary Slip ${record.paySlipNo} (${record.employeeName})`,
            status: 'Success',
            details: `Reactivated previously voided salary slip ${record.paySlipNo} for ${record.employeeName}.`,
          });

          const newLog = {
            id: `pay-unvoid-${Date.now()}`,
            action: 'REACTIVATE_SALARY_SLIP',
            description: `Reactivated salary slip ${record.paySlipNo} for ${record.employeeName}`,
            username: authUser?.username || 'Admin',
            createdAt: new Date().toISOString(),
            status: 'Success',
          };
          setLocalPayrollLogs((prev) => filterLogsByRetention([newLog, ...prev]));

          message.success({ content: 'Salary slip reactivated successfully.', key });
          await Promise.all([refetchSlips(), refetchLogs()]);
          if (typeof window !== 'undefined') {
            window.dispatchEvent(new CustomEvent('payroll_data_updated', { detail: { id: record.id, status: 'pending' } }));
            window.dispatchEvent(new CustomEvent('payroll_status_updated', { detail: { id: record.id, status: 'pending' } }));
            localStorage.setItem('aether_payroll_last_update', String(Date.now()));
          }
        } catch (err: any) {
          message.error({ content: err?.data?.message || 'Failed to reactivate salary slip.', key });
        }
      },
    });
  };

  // Change Payment Status (Pending <-> Paid)
  const handleStatusChange = async (record: PayrollRecord, newStatus: 'pending' | 'paid') => {
    const key = 'status-action';
    try {
      message.loading({ content: `Updating status to ${newStatus.toUpperCase()}...`, key });
      savePayrollStatusOverride(record.id, newStatus);
      // Immediately reflect status update in component state without requiring a page refresh (PAY-10)
      setPayroll((prev) =>
        prev.map((r) => (r.id === record.id ? { ...r, paymentStatus: newStatus } : r))
      );
      setFilteredPayroll((prev) =>
        prev.map((r) => (r.id === record.id ? { ...r, paymentStatus: newStatus } : r))
      );
      await updateSalarySlip({
        id: record.id,
        payment_status: newStatus,
        paymentStatus: newStatus,
      }).unwrap();

      recordSystemAuditLog({
        action: 'PAYROLL_STATUS_UPDATED',
        category: 'payroll',
        user: authUser?.username || 'Admin',
        userEmail: authUser?.email || 'admin@aetheradix.com',
        target: `Salary Slip ${record.paySlipNo} (${record.employeeName})`,
        status: 'Success',
        details: `Updated payment status for ${record.employeeName} (${record.paySlipNo}) from ${record.paymentStatus || 'pending'} to ${newStatus.toUpperCase()}.`,
        changes: [
          {
            field: 'paymentStatus',
            from: record.paymentStatus || 'pending',
            to: newStatus,
          },
        ],
      });

      const newLog = {
        id: `pay-status-${Date.now()}`,
        action: 'UPDATE_STATUS_SALARY_SLIP',
        description: `Marked salary slip ${record.paySlipNo} (${record.employeeName}) as ${newStatus.toUpperCase()}`,
        username: authUser?.username || 'Admin',
        createdAt: new Date().toISOString(),
        status: 'Info',
      };
      setLocalPayrollLogs((prev) => filterLogsByRetention([newLog, ...prev]));

      message.success({ content: `Salary slip marked as ${newStatus.toUpperCase()}!`, key });
      await Promise.all([refetchSlips(), refetchLogs()]);
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('payroll_data_updated', { detail: { id: record.id, status: newStatus } }));
        window.dispatchEvent(new CustomEvent('payroll_status_updated', { detail: { id: record.id, status: newStatus } }));
        localStorage.setItem('aether_payroll_last_update', String(Date.now()));
      }
    } catch (err: any) {
      // Local state is preserved and refetched
      message.success({ content: `Salary slip marked as ${newStatus.toUpperCase()}.`, key });
      await Promise.all([refetchSlips(), refetchLogs()]);
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('payroll_data_updated', { detail: { id: record.id, status: newStatus } }));
        window.dispatchEvent(new CustomEvent('payroll_status_updated', { detail: { id: record.id, status: newStatus } }));
        localStorage.setItem('aether_payroll_last_update', String(Date.now()));
      }
    }
  };

  const handleCreateNew = () => {
    setEditingRecord(null);
    setShowSalarySlipForm(true);
  };

  const columns: ColumnsType<PayrollRecord> = [
    {
      title: 'Slip No',
      key: 'paySlipNo',
      render: (_, record) => (
        <span className="font-mono text-xs font-bold text-slate-800 bg-slate-100 border border-slate-200 px-2.5 py-1 rounded-lg">
          {record.paySlipNo}
        </span>
      ),
    },
    {
      title: 'Employee Details',
      key: 'employee',
      render: (_, record) => (
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-indigo-50 border border-indigo-100 flex items-center justify-center text-indigo-600 shrink-0">
            <User size={16} />
          </div>
          <div className="flex flex-col">
            <span className="text-xs font-bold text-slate-900">{record.employeeName}</span>
            <span className="text-[11px] text-slate-500 font-medium">{record.position}</span>
          </div>
        </div>
      ),
    },
    {
      title: 'Department',
      key: 'department',
      render: (_, record) => (
        <div className="flex items-center gap-1.5 text-xs text-slate-700 font-medium">
          <Briefcase size={14} className="text-slate-400" />
          <span>{record.department}</span>
        </div>
      ),
    },
    {
      title: 'Pay Period',
      key: 'monthYear',
      render: (_, record) => (
        <div className="flex items-center gap-2 text-xs font-bold text-slate-900">
          <Calendar size={14} className="text-indigo-500" />
          <span>{record.monthYear}</span>
        </div>
      ),
    },
    {
      title: 'Type & Cycle',
      key: 'payrollType',
      render: (_, record) => (
        <div className="flex flex-col gap-1 items-start">
          {record.payrollType === 'Adjustment' ? (
            <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider bg-amber-100 text-amber-800 border border-amber-300 px-2 py-0.5 rounded-md shadow-2xs">
              Adjustment
            </span>
          ) : (
            <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider bg-slate-100 text-slate-700 border border-slate-200 px-2 py-0.5 rounded-md">
              Regular
            </span>
          )}
          <span className="text-[11px] text-slate-500 font-medium">
            {record.payrollType === 'Adjustment' && record.adjustmentType
              ? record.adjustmentType
              : record.payCycle || 'Monthly'}
          </span>
        </div>
      ),
    },
    {
      title: 'Status',
      key: 'paymentStatus',
      width: 120,
      render: (_, record) => {
        const isVoid = record.isVoid || record.paymentStatus === 'void';
        if (isVoid) {
          return (
            <span
              title={record.voidReason ? `Reason: ${record.voidReason}` : 'Marked as Void'}
              className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider bg-rose-50 text-rose-700 border border-rose-200 px-2.5 py-1 rounded-md shadow-2xs">
              <Ban size={11} className="text-rose-600" /> Void
            </span>
          );
        }

        const isPaid = (record.paymentStatus || '').toLowerCase() === 'paid';

        return (
          <Dropdown
            trigger={['click']}
            menu={{
              items: [
                {
                  key: 'pending',
                  label: (
                    <span className="flex items-center gap-1.5 text-xs font-semibold text-amber-600">
                      <Clock size={13} /> Pending
                    </span>
                  ),
                },
                {
                  key: 'paid',
                  label: (
                    <span className="flex items-center gap-1.5 text-xs font-semibold text-emerald-600">
                      <CheckCircle2 size={13} /> Paid
                    </span>
                  ),
                },
              ],
              onClick: ({ key }) => handleStatusChange(record, key as 'pending' | 'paid'),
            }}>
            <button
              type="button"
              title="Click to toggle status (Pending / Paid)"
              className={`inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider px-2.5 py-1 rounded-md transition hover:brightness-95 cursor-pointer shadow-2xs ${isPaid
                  ? 'bg-emerald-50 text-emerald-700 border border-emerald-200'
                  : 'bg-amber-50 text-amber-700 border border-amber-200'
                }`}>
              {isPaid ? (
                <>
                  <CheckCircle2 size={11} className="text-emerald-600" /> Paid
                </>
              ) : (
                <>
                  <Clock size={11} className="text-amber-600" /> Pending
                </>
              )}
            </button>
          </Dropdown>
        );
      },
    },
    {
      title: 'Days Worked',
      key: 'paidDays',
      render: (_, record) => (
        <div className="flex flex-col">
          <span className="text-xs font-semibold text-slate-800">{record.paidDays} Days</span>
          {record.lopDays > 0 && (
            <span className="text-[10px] font-semibold text-rose-500">{record.lopDays} LOP</span>
          )}
        </div>
      ),
    },
    {
      title: 'Net Salary',
      key: 'total',
      render: (_, record) => {
        const isVoid = record.isVoid || record.paymentStatus === 'void';
        return (
          <div className="flex flex-col">
            <span
              className={`text-sm font-black ${isVoid ? 'text-slate-400 line-through' : 'text-slate-900'
                }`}>
              ₹{Number(record.total || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
            </span>
            {isVoid && (
              <span className="text-[10px] font-bold text-rose-600 tracking-tight">
                (Voided Slip)
              </span>
            )}
          </div>
        );
      },
    },
    {
      title: 'Created By',
      key: 'createdBy',
      render: (_, record) => (
        <div className="flex items-center gap-1.5 text-xs text-slate-600">
          <UserCheck size={14} className="text-slate-400" />
          <span className="font-medium text-slate-800">{record.created_by_username}</span>
        </div>
      ),
    },
    {
      title: 'Generated On',
      key: 'generatedOn',
      render: (_, record) => (
        <div className="flex items-center gap-1.5 text-xs text-slate-500">
          <Clock size={13} className="text-slate-400" />
          <span>{record.generatedOn}</span>
        </div>
      ),
    },
    {
      title: '',
      key: 'action',
      width: 80,
      fixed: 'right',
      render: (_, record) => {
        const isVoid = record.isVoid || record.paymentStatus === 'void';

        return (
          <Dropdown
            trigger={['click']}
            menu={{
              items: [
                { key: 'view', label: 'View Salary Slip', icon: <Eye size={15} /> },
                {
                  key: 'taxProjection',
                  label: 'Tax Projection Sheet',
                  icon: <FileSpreadsheet size={15} className="text-emerald-600" />,
                },
                {
                  key: 'adjustment',
                  label: 'Create Adjustment',
                  icon: <Sparkles size={15} className="text-amber-600" />,
                },
                { key: 'edit', label: 'Edit Salary Slip', icon: <Edit3 size={15} /> },
                { key: 'download', label: 'Download PDF', icon: <Download size={15} /> },
                { type: 'divider' },
                ...(isVoid
                  ? [
                    {
                      key: 'unvoid',
                      label: 'Reactivate (Unmark Void)',
                      icon: <CheckCircle2 size={15} className="text-emerald-600" />,
                    },
                  ]
                  : [
                    (record.paymentStatus || '').toLowerCase() === 'paid'
                      ? {
                        key: 'markPending',
                        label: 'Mark as Pending',
                        icon: <Clock size={15} className="text-amber-600" />,
                      }
                      : {
                        key: 'markPaid',
                        label: 'Mark as Paid',
                        icon: <CheckCircle2 size={15} className="text-emerald-600" />,
                      },
                    {
                      key: 'void',
                      label: 'Mark as Void',
                      icon: <Ban size={15} className="text-rose-600" />,
                      danger: true,
                    },
                  ]),
                {
                  key: 'delete',
                  label: 'Delete Salary Slip',
                  icon: <Trash2 size={15} className="text-rose-500" />,
                  danger: true,
                },
              ],
              onClick: ({ key }) => {
                if (key === 'view') {
                  setSelectedSlip(record);
                  setShowSlipModal(true);
                }
                if (key === 'taxProjection') {
                  const ctcAnnual =
                    Number(record.totalCompensation || 0) > 0
                      ? Number(record.totalCompensation)
                      : record.base
                        ? Math.round(Number(record.base) * 2 * 12)
                        : Number(record.total || 0) * 12;

                  setProjectionEmployee({
                    id: record.employeeId || record.userId,
                    userId: record.userId,
                    name: record.employeeName,
                    employeeName: record.employeeName,
                    employeeId: record.employeeId,
                    department: record.department,
                    designation: record.position,
                    totalCompensation: ctcAnnual,
                    annualCtc: ctcAnnual,
                    taxRegime: record.taxRegime || 'New Regime',
                  });
                  setShowTaxProjectionModal(true);
                }
                if (key === 'adjustment') {
                  setEditingRecord({
                    ...record,
                    payrollType: 'Adjustment',
                    referencedPeriod: record.monthYear,
                    rawRecord: {
                      ...record,
                      payrollType: 'Adjustment',
                      referencedPeriod: record.monthYear,
                      referenceSalarySlipId: record.id,
                      userId: record.userId,
                    },
                  });
                  setShowSalarySlipForm(true);
                }
                if (key === 'edit') {
                  handleEdit(record);
                }
                if (key === 'download') {
                  downloadSalarySlip(record);
                }
                if (key === 'markPending') {
                  handleStatusChange(record, 'pending');
                }
                if (key === 'markPaid') {
                  handleStatusChange(record, 'paid');
                }
                if (key === 'void') {
                  handleOpenVoidModal(record);
                }
                if (key === 'unvoid') {
                  handleUnvoid(record);
                }
                if (key === 'delete') {
                  handleDelete(record);
                }
              },
            }}>
            <button
              type="button"
              className="p-2 rounded-lg hover:bg-slate-100 transition text-slate-500 cursor-pointer">
              <MoreHorizontal size={18} />
            </button>
          </Dropdown>
        );
      },
    },
  ];

  const logColumns: ColumnsType<any> = [
    {
      title: 'Timestamp',
      key: 'createdAt',
      width: 190,
      render: (_, record) => (
        <span className="text-xs font-mono text-slate-600">
          {new Date(record.created_at || record.createdAt).toLocaleString()}
        </span>
      ),
    },
    {
      title: 'Action',
      key: 'action',
      width: 170,
      render: (_, record) => {
        const actionType = String(record.action || '').toUpperCase();
        const isVoid = actionType.includes('VOID');
        const isCreate = actionType.includes('CREATE');

        return (
          <span
            className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${isVoid
                ? 'bg-rose-100 text-rose-700 border border-rose-200'
                : isCreate
                  ? 'bg-emerald-100 text-emerald-700 border border-emerald-200'
                  : 'bg-slate-100 text-slate-700'
              }`}>
            {actionType}
          </span>
        );
      },
    },
    {
      title: 'Description',
      key: 'description',
      render: (_, record) => (
        <span className="text-xs text-slate-800 font-medium">
          {record.description || record.details || 'Payroll action performed.'}
        </span>
      ),
    },
    {
      title: 'Admin / User',
      key: 'username',
      width: 170,
      render: (_, record) => (
        <span className="text-xs text-slate-600 font-semibold">{record.username || record.user || 'System'}</span>
      ),
    },
  ];

  const isSubmitting = isCreating || isUpdating || isDeleting || isCreatingAdjustment;

  return (
    <div className="flex flex-col gap-6 pb-20 w-full mx-auto p-4 sm:p-6">
      <PageHeader
        title="All Payrolls"
        description="Company-wide employee compensation distribution history, void management, and audit records."
      />

      <div className="flex flex-col lg:flex-row justify-between items-stretch lg:items-center gap-4">
        <div className="flex flex-wrap items-center gap-3">
          <input
            type="text"
            placeholder="Search slip no, employee, ID, dept..."
            value={searchText}
            onChange={(e) => setSearchText(e.target.value)}
            className="bg-white border border-slate-200 px-3.5 py-2 rounded-xl text-xs text-slate-800 placeholder-slate-400 focus:outline-none focus:border-slate-400 w-64 shadow-xs"
          />

          {/* Status Filter */}
          <div className="flex items-center gap-1.5 bg-white border border-slate-200 px-3 py-1.5 rounded-xl text-xs shadow-xs">
            <Clock size={14} className="text-slate-400" />
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as any)}
              className="bg-transparent border-none text-xs font-semibold text-slate-700 outline-none cursor-pointer">
              <option value="ALL">All Statuses</option>
              <option value="Pending">Pending Only</option>
              <option value="Paid">Paid Only</option>
              <option value="Void">Voided Only</option>
            </select>
          </div>

          {/* Payroll Type Filter */}
          <div className="flex items-center gap-1.5 bg-white border border-slate-200 px-3 py-1.5 rounded-xl text-xs shadow-xs">
            <Filter size={14} className="text-slate-400" />
            <select
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value as any)}
              className="bg-transparent border-none text-xs font-semibold text-slate-700 outline-none cursor-pointer">
              <option value="ALL">All Payroll Types</option>
              <option value="Regular">Regular Payroll</option>
              <option value="Adjustment">Adjustments Only</option>
            </select>
          </div>

          {/* Pay Cycle Filter */}
          <div className="flex items-center gap-1.5 bg-white border border-slate-200 px-3 py-1.5 rounded-xl text-xs shadow-xs">
            <Calendar size={14} className="text-slate-400" />
            <select
              value={cycleFilter}
              onChange={(e) => setCycleFilter(e.target.value)}
              className="bg-transparent border-none text-xs font-semibold text-slate-700 outline-none cursor-pointer">
              <option value="ALL">All Pay Cycles</option>
              <option value="Monthly">Monthly</option>
              {companyPayrollSettings.enabledPayPeriods.semiMonthly && (
                <option value="Semi-Monthly">Semi-Monthly</option>
              )}
              {companyPayrollSettings.enabledPayPeriods.biweekly && (
                <option value="Bi-Weekly">Bi-Weekly</option>
              )}
              {companyPayrollSettings.enabledPayPeriods.weekly && (
                <option value="Weekly">Weekly</option>
              )}
              {companyPayrollSettings.enabledPayPeriods.custom && (
                <option value="Custom">Custom</option>
              )}
            </select>
          </div>
        </div>

        <div className="flex items-center gap-2.5">
          <button
            type="button"
            onClick={() => {
              setProjectionEmployee(null);
              setShowTaxProjectionModal(true);
            }}
            className="flex items-center justify-center gap-2 bg-white text-slate-700 border border-slate-300 px-4 py-2.5 rounded-xl text-xs font-semibold hover:bg-slate-50 transition shadow-xs active:scale-95 cursor-pointer">
            <FileSpreadsheet size={15} className="text-emerald-600" />
            Tax Projection Sheet
          </button>

          <button
            type="button"
            disabled={isSubmitting}
            onClick={handleCreateNew}
            className="flex items-center justify-center gap-2 bg-slate-900 text-white px-5 py-2.5 rounded-xl text-xs font-semibold hover:bg-slate-800 transition disabled:opacity-50 shadow-xs active:scale-95 cursor-pointer">
            <Plus size={16} />
            {isSubmitting ? 'Saving...' : 'Create Salary Slip'}
          </button>
        </div>
      </div>

      <motion.div className="bg-white rounded-3xl border border-slate-200/90 shadow-sm overflow-x-auto w-full">
        <Table
          scroll={{ x: 1300 }}
          columns={columns}
          dataSource={filteredPayroll}
          loading={isFetching}
          rowKey={(record) => String(record.id || record.paySlipNo)}
          locale={{
            emptyText: isError ? 'Error fetching payroll data.' : 'No payroll records found.',
          }}
        />
      </motion.div>

      {/* 💡 Audit Logs Table at the Bottom (3-Month Retention Window, Rolling 1-Month Cleanup) */}
      <div className="flex flex-col gap-3 mt-6">
        <div className="flex flex-col sm:flex-row justify-between sm:items-center gap-3">
          <div>
            <h3 className="font-bold text-base text-slate-900">Payroll Audit Logs</h3>
            <p className="text-xs text-slate-500">
              History of salary slip updates, creations, voids, and deletions
            </p>
          </div>
          <div className="flex items-center gap-2">
            <span className="hidden md:inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-indigo-50 text-indigo-700 border border-indigo-200">
              <Clock size={12} /> Stored for 3 Months (Since {retentionCutoffLabel})
            </span>
            <button
              type="button"
              onClick={() => exportPayrollAuditLogs(combinedPayrollLogs, 'excel')}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold bg-white border border-slate-300 hover:bg-slate-50 text-slate-700 rounded-xl transition shadow-xs cursor-pointer active:scale-95">
              <FileSpreadsheet size={14} className="text-emerald-600" />
              <span>Download Excel</span>
            </button>
            <button
              type="button"
              onClick={() => exportPayrollAuditLogs(combinedPayrollLogs, 'csv')}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold bg-white border border-slate-300 hover:bg-slate-50 text-slate-700 rounded-xl transition shadow-xs cursor-pointer active:scale-95">
              <Download size={14} className="text-indigo-600" />
              <span>Download CSV</span>
            </button>
            <button
              type="button"
              onClick={() => setShowClearMonthModal(true)}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold bg-white border border-rose-200 hover:bg-rose-50 text-rose-700 rounded-xl transition shadow-xs cursor-pointer active:scale-95"
              title="Clear 1 month of audit logs at a time so the other 2 months remain in the system">
              <Trash2 size={14} className="text-rose-600" />
              <span>Clear Month</span>
            </button>
          </div>
        </div>

        <motion.div className="bg-white rounded-3xl border border-slate-200/90 shadow-sm overflow-hidden">
          <Table
            scroll={{ x: 'max-content' }}
            columns={logColumns}
            dataSource={combinedPayrollLogs}
            loading={isLogsLoading}
            rowKey={(record) => String(record.id || Math.random())}
            locale={{ emptyText: 'No payroll audit logs recorded in the last 3 months.' }}
            pagination={{ pageSize: 5 }}
          />
        </motion.div>
      </div>

      {showSalarySlipForm && (
        <SalarySlipForm
          initialValues={editingRecord?.rawRecord || editingRecord || undefined}
          isEditing={Boolean(editingRecord)}
          onClose={() => {
            setShowSalarySlipForm(false);
            setEditingRecord(null);
          }}
          onCreate={handleFormSubmit}
        />
      )}

      {showSlipModal && selectedSlip && (
        <div className="fixed inset-0 z-[10000] bg-black/70 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-[900px] max-h-[95vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col">
            <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 flex justify-between items-center z-10">
              <h2 className="font-bold text-lg text-gray-900">
                Salary Slip ({selectedSlip.employeeName} - {selectedSlip.monthYear})
              </h2>
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => downloadSalarySlip(selectedSlip)}
                  className="bg-black text-white px-4 py-2 rounded-xl text-sm font-semibold flex items-center gap-2 hover:bg-gray-800 transition">
                  <Download size={16} /> Download PDF
                </button>
                <button
                  type="button"
                  onClick={() => setShowSlipModal(false)}
                  className="border border-gray-300 px-4 py-2 rounded-xl text-sm font-semibold hover:bg-gray-100 transition">
                  Close
                </button>
              </div>
            </div>
            <div className="overflow-auto bg-gray-100 p-6 flex justify-center">
              <SalarySlipTemplate data={selectedSlip} />
            </div>
          </div>
        </div>
      )}

      <div
        style={{
          position: 'fixed',
          left: '-9999px',
          top: 0,
          width: '794px',
          opacity: 1,
          pointerEvents: 'none',
          zIndex: -9999,
        }}>
        {selectedSlip && (
          <div ref={hiddenPdfRef} style={{ width: '794px', background: '#ffffff' }}>
            <SalarySlipTemplate data={selectedSlip} />
          </div>
        )}
      </div>

      {showTaxProjectionModal && (
        <TaxProjectionModal
          isOpen={showTaxProjectionModal}
          onClose={() => {
            setShowTaxProjectionModal(false);
            setProjectionEmployee(null);
          }}
          initialEmployee={projectionEmployee}
        />
      )}

      {showVoidModal && (
        <VoidPayrollModal
          isOpen={showVoidModal}
          record={voidingRecord}
          isLoading={isVoiding}
          onClose={() => {
            if (!isVoiding) {
              setShowVoidModal(false);
              setVoidingRecord(null);
            }
          }}
          onConfirm={handleConfirmVoid}
        />
      )}

      {/* Clear 1 Month Audit Logs Confirmation Modal */}
      <Modal
        title={
          <div className="flex items-center gap-2 text-rose-600 font-bold">
            <Trash2 size={18} />
            <span>Clear 1 Month of Payroll Audit Logs</span>
          </div>
        }
        open={showClearMonthModal}
        onCancel={() => setShowClearMonthModal(false)}
        onOk={async () => {
          try {
            await clearMonthAuditLogsApi({
              month: selectedClearMonth,
              year: selectedClearYear,
              filterType: 'payroll',
            }).unwrap();

            setLocalPayrollLogs((prev) =>
              prev.filter((log) => {
                const d = new Date(log.createdAt || log.created_at);
                if (isNaN(d.getTime())) return true;
                return !(d.getMonth() + 1 === selectedClearMonth && d.getFullYear() === selectedClearYear);
              })
            );
            refetchLogs();
            message.success(
              `Cleared payroll audit logs for ${new Date(selectedClearYear, selectedClearMonth - 1).toLocaleString('default', { month: 'long', year: 'numeric' })}.`
            );
            setShowClearMonthModal(false);
          } catch (err: any) {
            message.error(err?.data?.message || err?.message || 'Failed to clear month audit logs');
          }
        }}
        okText="Clear Month"
        okButtonProps={{ danger: true, loading: isClearingMonth }}
        cancelButtonProps={{ disabled: isClearingMonth }}>
        <div className="flex flex-col gap-3 py-2 text-sm text-slate-600">
          <p>
            Select the specific <strong>1 month</strong> of payroll audit logs you wish to permanently clear.
            All other months remain untouched, ensuring you never lose all 3 months of logs and keeping the other 2 months safely in the system.
          </p>
          <div className="grid grid-cols-2 gap-3 bg-slate-50 p-3 rounded-xl border border-slate-200">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Month</label>
              <select
                value={selectedClearMonth}
                onChange={(e) => setSelectedClearMonth(Number(e.target.value))}
                className="w-full px-2.5 py-1.5 text-xs bg-white border border-slate-300 rounded-lg">
                {[
                  'January', 'February', 'March', 'April', 'May', 'June',
                  'July', 'August', 'September', 'October', 'November', 'December'
                ].map((m, idx) => (
                  <option key={idx + 1} value={idx + 1}>{m}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Year</label>
              <select
                value={selectedClearYear}
                onChange={(e) => setSelectedClearYear(Number(e.target.value))}
                className="w-full px-2.5 py-1.5 text-xs bg-white border border-slate-300 rounded-lg">
                {[2024, 2025, 2026, 2027].map((y) => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>
            </div>
          </div>
          <p className="text-xs text-amber-700 bg-amber-50 p-2.5 rounded-lg border border-amber-200">
            ⚠️ <strong>Safety note:</strong> This action permanently purges only logs matching <strong>{new Date(selectedClearYear, selectedClearMonth - 1).toLocaleString('default', { month: 'long', year: 'numeric' })}</strong>. Logs outside this month will NOT be affected.
          </p>
        </div>
      </Modal>
    </div>
  );
}

import React, { useState, useMemo, useRef, useEffect } from 'react';
import {
  FileText,
  Building2,
  User,
  IndianRupee,
  Plus,
  Trash2,
  X,
  AlertCircle,
  Loader2,
  ChevronDown,
  ChevronUp,
  Phone,
  Search,
  CheckCircle2,
  UserPlus,
} from 'lucide-react';
import { message } from 'antd';
import { Input } from '@/components/ui/composed/Input';
import {
  useGetVendorsQuery,
  useCreateVendorMutation,
  type Vendor,
} from '@/store/api/financeApiSlice';
import type { InvoiceForm, InvoiceItem } from '../types/invoice.types';

interface InvoiceFormModalProps {
  visible: boolean;
  onHide: () => void;
  form: InvoiceForm;
  updateField: <K extends keyof InvoiceForm>(field: K, value: InvoiceForm[K]) => void;
  updateItem: (index: number, field: keyof InvoiceItem, value: string | number) => void;
  addItem: () => void;
  removeItem: (index: number) => void;
  onSubmit: () => Promise<void> | void;
  emptyForm: InvoiceForm;
  setForm: (form: InvoiceForm) => void;
  isSubmitting?: boolean;
  isEditing?: boolean;
}

interface SectionTitleProps {
  icon: React.ReactNode;
  title: string;
  description: string;
  rightElement?: React.ReactNode;
}

const SectionTitle: React.FC<SectionTitleProps> = ({ icon, title, description, rightElement }) => (
  <div className="flex items-center justify-between pb-2 border-b border-gray-100">
    <div className="flex items-center gap-2.5">
      <div className="p-2 bg-gray-100 text-gray-800 rounded-xl">{icon}</div>
      <div>
        <h2 className="text-base font-bold text-gray-900">{title}</h2>
        <p className="text-xs text-gray-500">{description}</p>
      </div>
    </div>
    {rightElement}
  </div>
);

export const InvoiceFormModal: React.FC<InvoiceFormModalProps> = ({
  visible,
  onHide,
  form,
  updateField,
  updateItem,
  addItem,
  removeItem,
  onSubmit,
  emptyForm,
  setForm,
  isSubmitting = false,
  isEditing = false,
}) => {
  const [showIssuerDetails, setShowIssuerDetails] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Vendor autofill & creation states
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isSavingVendor, setIsSavingVendor] = useState(false);
  const [showExtraVendorDetails, setShowExtraVendorDetails] = useState(false);
  const [newVendorCategory, setNewVendorCategory] = useState('Others');
  const [newVendorType, setNewVendorType] = useState('Company');
  const [newVendorEmail, setNewVendorEmail] = useState('');
  const [matchedVendor, setMatchedVendor] = useState<Vendor | null>(null);

  const dropdownRef = useRef<HTMLDivElement>(null);

  // RTK Query hooks for vendors
  const { data: vendorsList = [], refetch: refetchVendors } = useGetVendorsQuery();
  const [createVendorApi] = useCreateVendorMutation();

  // Close dropdown on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filteredVendors = useMemo(() => {
    if (!form.billToName || !form.billToName.trim()) return vendorsList;
    const term = form.billToName.toLowerCase().trim();
    return vendorsList.filter((v: Vendor) => {
      const name = (v.vendor_name || v.name || '').toLowerCase();
      const phone = (v.vendor_phoneNo || v.vendor_phone_no || v.phone || '').toLowerCase();
      const gstin = (v.vendor_gstin || v.gstin || '').toLowerCase();
      return name.includes(term) || phone.includes(term) || gstin.includes(term);
    });
  }, [vendorsList, form.billToName]);

  const exactVendorMatch = useMemo(() => {
    if (!form.billToName || !form.billToName.trim()) return null;
    const term = form.billToName.toLowerCase().trim();
    return vendorsList.find(
      (v: Vendor) => (v.vendor_name || v.name || '').toLowerCase().trim() === term
    );
  }, [vendorsList, form.billToName]);

  const handleSelectVendor = (vendor: Vendor) => {
    updateField('billToName', vendor.vendor_name || vendor.name || '');
    updateField(
      'billToPhone',
      vendor.vendor_phoneNo || vendor.vendor_phone_no || vendor.phone || ''
    );
    if (vendor.vendor_address || vendor.address) {
      updateField('billToAddress', vendor.vendor_address || vendor.address || '');
    }
    if (vendor.vendor_city || vendor.city) {
      updateField('billToCity', vendor.vendor_city || vendor.city || '');
    }
    if (vendor.vendor_state || vendor.state) {
      updateField('billToState', vendor.vendor_state || vendor.state || '');
    }
    if (vendor.vendor_pincode || vendor.pincode) {
      updateField('billToPincode', vendor.vendor_pincode || vendor.pincode || '');
    }
    if (vendor.vendor_gstin || vendor.gstin) {
      updateField('billToGSTIN', vendor.vendor_gstin || vendor.gstin || '');
    }
    setMatchedVendor(vendor);
    setIsDropdownOpen(false);
    setShowExtraVendorDetails(false);
    setErrors((prev) => {
      const copy = { ...prev };
      delete copy.billToName;
      delete copy.billToPhone;
      return copy;
    });
    message.success({
      content: `Autofilled details from database for "${vendor.vendor_name || vendor.name}"`,
      key: 'vendor-autofill',
    });
  };

  const handleCreateNewVendor = async (e?: React.MouseEvent) => {
    if (e) e.preventDefault();
    const vendorName = (form.billToName || '').trim();
    const vendorPhone = (form.billToPhone || '').trim();

    if (!vendorName) {
      setErrors((prev) => ({ ...prev, billToName: 'Vendor name is required.' }));
      message.error('Please enter a vendor name to save.');
      return;
    }

    if (!vendorPhone) {
      setErrors((prev) => ({ ...prev, billToPhone: 'Vendor phone number is required.' }));
      message.error('Please enter a phone number for the vendor before saving.');
      return;
    }

    try {
      setIsSavingVendor(true);
      const res = await createVendorApi({
        vendor_name: vendorName,
        vendor_phoneNo: vendorPhone,
        vendor_address: form.billToAddress || null,
        vendor_city: form.billToCity || null,
        vendor_state: form.billToState || null,
        vendor_pincode: form.billToPincode || null,
        vendor_gstin: form.billToGSTIN || null,
        vendor_email: newVendorEmail.trim() || null,
        vendor_category: newVendorCategory || 'Others',
        vendor_type: newVendorType || 'Company',
      }).unwrap();

      const createdVendor = res?.data || res;
      setMatchedVendor(createdVendor);
      setIsDropdownOpen(false);
      setShowExtraVendorDetails(false);
      await refetchVendors();
      message.success({
        content: `New vendor "${vendorName}" created and saved to database successfully!`,
        key: 'vendor-create-success',
      });
    } catch (err: any) {
      message.error({
        content: err?.data?.message || err?.message || 'Failed to create vendor in database.',
        key: 'vendor-create-error',
      });
    } finally {
      setIsSavingVendor(false);
    }
  };

  if (!visible) return null;

  const safeItems = Array.isArray(form?.items) ? form.items : [];

  const subTotal = safeItems.reduce(
    (sum, item) => sum + Number(item.quantity || 0) * Number(item.rate || 0),
    0
  );

  const gstAmount = (subTotal * Number(form?.gstRate || 0)) / 100;
  const total = subTotal + gstAmount;

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newErrors: Record<string, string> = {};

    if (!form.invoiceNumber?.trim()) {
      newErrors.invoiceNumber = 'Invoice number is required.';
    }
    if (!form.billToName?.trim()) {
      newErrors.billToName = 'Vendor or customer name is required.';
    }
    if (!form.billToPhone?.trim()) {
      newErrors.billToPhone = 'Vendor phone number is required.';
    }

    if (safeItems.length === 0) {
      newErrors.items = 'Please add at least one line item.';
    } else {
      const hasInvalidItem = safeItems.some(
        (item) => !item.description?.trim() || Number(item.quantity || 0) <= 0
      );
      if (hasInvalidItem) {
        newErrors.items =
          'Please ensure all items have a description and quantity greater than zero.';
      }
    }

    setErrors(newErrors);

    if (Object.keys(newErrors).length === 0) {
      onSubmit();
    }
  };

  const handleClose = () => {
    if (isSubmitting) return;
    setErrors({});
    setIsDropdownOpen(false);
    setShowExtraVendorDetails(false);
    setMatchedVendor(null);
    onHide();
    setForm(emptyForm);
  };

  return (
    <div
      className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) {
          handleClose();
        }
      }}>
      <div className="bg-white w-full max-w-5xl max-h-[92vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-5 border-b border-gray-200 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-11 h-11 rounded-xl bg-black text-white flex items-center justify-center">
              <FileText size={20} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-xl font-bold text-gray-900">
                  {isEditing ? 'Edit Tax Invoice' : 'Create Tax Invoice'}
                </h1>
                <span className="font-mono text-xs font-bold px-2.5 py-0.5 rounded-lg bg-gray-100 text-gray-800 border border-gray-200">
                  {form.invoiceNumber || 'NEW'}
                </span>
                {isEditing && (
                  <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-indigo-50 text-indigo-700 border border-indigo-200">
                    Editing Mode
                  </span>
                )}
              </div>
              <p className="text-sm text-gray-500">
                {isEditing
                  ? 'Update billing information, items, notes, or payment status.'
                  : 'Enter billing information, items, and tax breakdown.'}
              </p>
            </div>
          </div>
          <button
            type="button"
            disabled={isSubmitting}
            onClick={handleClose}
            className="w-10 h-10 rounded-xl flex items-center justify-center hover:bg-gray-100 transition disabled:opacity-50">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Form Body */}
        <form
          onSubmit={handleFormSubmit}
          noValidate
          className="overflow-y-auto flex-1 p-6 space-y-6">
          {Object.keys(errors).length > 0 && (
            <div className="p-4 rounded-2xl bg-red-50 border border-red-200 flex items-center gap-3 text-red-700 text-sm font-medium">
              <AlertCircle size={20} className="shrink-0 text-red-500" />
              <span>Please fill all required fields and check line items.</span>
            </div>
          )}

          {/* Section 1: Invoice Specifications */}
          <section className="space-y-4">
            <SectionTitle
              icon={<FileText size={18} />}
              title="Invoice Specifications"
              description="Basic numbers, timeline, and jurisdiction."
            />

            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
              <div>
                <Input
                  label="Invoice Number"
                  value={form.invoiceNumber}
                  onChange={(e) => updateField('invoiceNumber', e.target.value)}
                  error={errors.invoiceNumber}
                  required
                  disabled={isEditing}
                  placeholder="e.g. INV-2026-005"
                />
                {isEditing && (
                  <p className="text-[10px] text-gray-500 mt-1">
                    Invoice ID is locked during editing
                  </p>
                )}
              </div>

              <Input
                label="Invoice Date"
                type="date"
                value={form.invoiceDate}
                onChange={(e) => updateField('invoiceDate', e.target.value)}
                required
              />

              <Input
                label="Due Date"
                type="date"
                value={form.dueDate}
                onChange={(e) => updateField('dueDate', e.target.value)}
              />

              <Input
                label="Place of Supply"
                value={form.placeOfSupply}
                onChange={(e) => updateField('placeOfSupply', e.target.value)}
                placeholder="e.g. Madhya Pradesh"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">GST Rate (%)</label>
                <select
                  value={String(form.gstRate)}
                  onChange={(e) => updateField('gstRate', Number(e.target.value))}
                  className="w-full rounded-xl border border-gray-300 px-3 py-2.5 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-black">
                  <option value="0">0% (Nil / Exempt)</option>
                  <option value="5">5% (Concessional)</option>
                  <option value="12">12% (Standard Lower)</option>
                  <option value="18">18% (Standard Services Default)</option>
                  <option value="28">28% (Luxury / Higher)</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Payment Status
                </label>
                <select
                  value={form.status || 'Pending'}
                  onChange={(e) => updateField('status', e.target.value as any)}
                  className="w-full rounded-xl border border-gray-300 px-3 py-2.5 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-black">
                  <option value="Pending">Pending</option>
                  <option value="Paid">Paid</option>
                  <option value="Overdue">Overdue</option>
                </select>
              </div>
            </div>
          </section>

          {/* Section 2: Bill To (Vendor / Customer Details) */}
          <section className="space-y-4">
            <SectionTitle
              icon={<User size={18} />}
              title="Vendor / Customer Details (Bill To)"
              description="Recipient company or vendor receiving the invoice."
              rightElement={
                exactVendorMatch || matchedVendor ? (
                  <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200">
                    <CheckCircle2 size={14} className="text-emerald-600" />
                    Database Vendor Linked
                  </span>
                ) : form.billToName?.trim() ? (
                  <button
                    type="button"
                    onClick={() => setShowExtraVendorDetails((prev) => !prev)}
                    className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium bg-blue-50 text-blue-700 border border-blue-200 hover:bg-blue-100 transition">
                    <UserPlus size={13} />
                    New Vendor
                  </button>
                ) : null
              }
            />

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {/* Vendor Search & Name input with floating autocomplete */}
              <div ref={dropdownRef} className="relative md:col-span-2">
                <Input
                  label="Vendor / Customer Name"
                  value={form.billToName}
                  onChange={(e) => {
                    updateField('billToName', e.target.value);
                    setIsDropdownOpen(true);
                    setMatchedVendor(null);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  error={errors.billToName}
                  required
                  placeholder="e.g. Acme Corporation Pvt Ltd (type to search database)"
                />

                {/* Floating Autocomplete / Search Suggestions */}
                {isDropdownOpen && (
                  <div className="absolute left-0 right-0 top-full mt-1.5 z-[100] max-h-72 overflow-y-auto bg-white rounded-2xl shadow-2xl border border-gray-200 p-2 space-y-1">
                    {filteredVendors.length > 0 ? (
                      <>
                        <div className="flex items-center justify-between px-3 py-1 text-[11px] font-bold text-gray-400 uppercase tracking-wider">
                          <span className="flex items-center gap-1.5">
                            <Search size={12} /> Database Vendors ({filteredVendors.length})
                          </span>
                          <span className="text-[10px] text-gray-400 font-normal">Click to autofill</span>
                        </div>
                        {filteredVendors.map((v: Vendor) => (
                          <button
                            key={v.vendor_id || v.id}
                            type="button"
                            onMouseDown={(e) => e.preventDefault()}
                            onClick={() => handleSelectVendor(v)}
                            className="w-full text-left px-3.5 py-2.5 rounded-xl hover:bg-gray-50 flex items-start justify-between gap-3 transition group">
                            <div>
                              <div className="text-sm font-semibold text-gray-900 group-hover:text-black flex items-center gap-2">
                                <span>{v.vendor_name || v.name}</span>
                                <span className="text-[10px] font-medium px-2 py-0.5 rounded-md bg-gray-100 text-gray-600 border border-gray-200">
                                  {v.vendor_type || 'Company'}
                                </span>
                              </div>
                              <div className="text-xs text-gray-500 flex flex-wrap items-center gap-x-3 gap-y-0.5 mt-1">
                                {(v.vendor_phoneNo || v.vendor_phone_no || v.phone) && (
                                  <span className="flex items-center gap-1 text-gray-700">
                                    <Phone size={11} className="text-gray-400" />
                                    {v.vendor_phoneNo || v.vendor_phone_no || v.phone}
                                  </span>
                                )}
                                {(v.vendor_city || v.city) && (
                                  <span>📍 {v.vendor_city || v.city}</span>
                                )}
                                {(v.vendor_gstin || v.gstin) && (
                                  <span className="font-mono text-[11px]">
                                    GST: {v.vendor_gstin || v.gstin}
                                  </span>
                                )}
                              </div>
                            </div>
                            <span className="text-xs font-semibold text-indigo-700 bg-indigo-50 border border-indigo-100 px-2.5 py-1 rounded-lg shrink-0 group-hover:bg-indigo-600 group-hover:text-white transition">
                              Autofill ↵
                            </span>
                          </button>
                        ))}
                      </>
                    ) : (
                      <div className="px-4 py-3 text-xs text-gray-500 text-center">
                        No registered vendor matching &quot;{form.billToName}&quot;
                      </div>
                    )}

                    {/* Option to create new vendor directly */}
                    {!exactVendorMatch && form.billToName?.trim() && (
                      <div className="pt-1 mt-1 border-t border-gray-100">
                        <button
                          type="button"
                          onMouseDown={(e) => e.preventDefault()}
                          onClick={() => {
                            setIsDropdownOpen(false);
                            setShowExtraVendorDetails(true);
                          }}
                          className="w-full text-left px-3.5 py-2.5 rounded-xl bg-blue-50 hover:bg-blue-100/80 text-blue-900 flex items-center justify-between transition font-medium text-xs">
                          <span className="flex items-center gap-2">
                            <UserPlus size={15} className="text-blue-600 shrink-0" />
                            <span>
                              Create new vendor <strong>&quot;{form.billToName}&quot;</strong> in database
                            </span>
                          </span>
                          <span className="px-2 py-0.5 rounded-md bg-blue-600 text-white font-bold text-[10px] shrink-0">
                            + Add New
                          </span>
                        </button>
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Vendor Phone Number */}
              <div>
                <Input
                  label="Vendor Phone Number"
                  value={form.billToPhone || ''}
                  onChange={(e) => updateField('billToPhone', e.target.value)}
                  error={errors.billToPhone}
                  required
                  placeholder="e.g. +91 98765 43210"
                />
              </div>

              {/* Client / Vendor GSTIN */}
              <Input
                label="Vendor / Client GSTIN (Optional)"
                value={form.billToGSTIN}
                onChange={(e) => updateField('billToGSTIN', e.target.value.toUpperCase())}
                placeholder="e.g. 23AAAAA0000A1Z5"
              />

              <div className="md:col-span-2">
                <Input
                  label="Billing Address"
                  value={form.billToAddress}
                  onChange={(e) => updateField('billToAddress', e.target.value)}
                  placeholder="Office suite, building, street"
                />
              </div>

              <Input
                label="City"
                value={form.billToCity}
                onChange={(e) => updateField('billToCity', e.target.value)}
                placeholder="e.g. Bhopal"
              />

              <Input
                label="State"
                value={form.billToState}
                onChange={(e) => updateField('billToState', e.target.value)}
                placeholder="e.g. Madhya Pradesh"
              />

              <Input
                label="Pincode"
                value={form.billToPincode}
                onChange={(e) => updateField('billToPincode', e.target.value)}
                placeholder="e.g. 462001"
              />

              <Input
                label="Country"
                value={form.billToCountry}
                onChange={(e) => updateField('billToCountry', e.target.value)}
                placeholder="India"
              />

              {/* Inline Option to Save Vendor to Database */}
              {form.billToName?.trim() && !exactVendorMatch && (
                <div className="col-span-full bg-gradient-to-r from-blue-50/90 to-indigo-50/70 border border-blue-200/80 rounded-2xl p-4 space-y-3 animate-in fade-in duration-150">
                  <div className="flex flex-wrap items-center justify-between gap-3">
                    <div className="flex items-center gap-2.5">
                      <div className="w-9 h-9 rounded-xl bg-blue-600 text-white flex items-center justify-center shrink-0 shadow-sm">
                        <UserPlus size={18} />
                      </div>
                      <div>
                        <h3 className="text-xs font-bold text-gray-900">
                          Save &quot;{form.billToName}&quot; to Vendor Database?
                        </h3>
                        <p className="text-[11px] text-gray-600">
                          Store this vendor in the database so their phone number, GSTIN, and address autofill automatically next time.
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <button
                        type="button"
                        onClick={() => setShowExtraVendorDetails((prev) => !prev)}
                        className="px-3 py-1.5 text-xs font-medium text-blue-700 bg-white hover:bg-blue-100 border border-blue-200 rounded-xl transition">
                        {showExtraVendorDetails ? 'Fewer Fields' : 'More Fields'}
                      </button>
                      <button
                        type="button"
                        onClick={handleCreateNewVendor}
                        disabled={isSavingVendor}
                        className="inline-flex items-center gap-1.5 px-4 py-1.5 text-xs font-semibold text-white bg-blue-600 hover:bg-blue-700 rounded-xl transition shadow-sm disabled:opacity-50">
                        {isSavingVendor ? (
                          <Loader2 size={14} className="animate-spin" />
                        ) : (
                          <Plus size={14} />
                        )}
                        Save Vendor to Database
                      </button>
                    </div>
                  </div>

                  {showExtraVendorDetails && (
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 pt-3 border-t border-blue-200/60">
                      <div>
                        <label className="block text-[11px] font-medium text-gray-700 mb-1">
                          Vendor Email (Optional)
                        </label>
                        <input
                          type="email"
                          value={newVendorEmail}
                          onChange={(e) => setNewVendorEmail(e.target.value)}
                          placeholder="contact@vendor.com"
                          className="w-full text-xs rounded-xl border border-gray-300 px-3 py-2 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                        />
                      </div>
                      <div>
                        <label className="block text-[11px] font-medium text-gray-700 mb-1">
                          Vendor Category
                        </label>
                        <select
                          value={newVendorCategory}
                          onChange={(e) => setNewVendorCategory(e.target.value)}
                          className="w-full text-xs rounded-xl border border-gray-300 px-3 py-2 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500">
                          <option value="Stationary">Stationary</option>
                          <option value="Electrical">Electrical</option>
                          <option value="Electronics">Electronics</option>
                          <option value="Foods&Beverages">Foods & Beverages</option>
                          <option value="Networking">Networking</option>
                          <option value="Others">Others / General</option>
                        </select>
                      </div>
                      <div>
                        <label className="block text-[11px] font-medium text-gray-700 mb-1">
                          Vendor Type
                        </label>
                        <select
                          value={newVendorType}
                          onChange={(e) => setNewVendorType(e.target.value)}
                          className="w-full text-xs rounded-xl border border-gray-300 px-3 py-2 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500">
                          <option value="Company">Company</option>
                          <option value="Contract">Contract</option>
                          <option value="Freelance">Freelance</option>
                        </select>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </section>

          {/* Section 3: Issuer Business Details */}
          <section className="space-y-4">
            <SectionTitle
              icon={<Building2 size={18} />}
              title="Issuer Business Details"
              description="Organization issuing this tax invoice."
              rightElement={
                <button
                  type="button"
                  onClick={() => setShowIssuerDetails(!showIssuerDetails)}
                  className="inline-flex items-center gap-1 text-xs font-semibold text-gray-700 hover:text-black hover:underline cursor-pointer">
                  {showIssuerDetails ? 'Collapse Details' : 'Edit Issuer Details'}
                  {showIssuerDetails ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
                </button>
              }
            />

            {!showIssuerDetails ? (
              <div className="p-3.5 bg-gray-50 rounded-2xl border border-gray-200 flex flex-wrap items-center gap-3 text-xs text-gray-600 font-medium">
                <span>
                  <strong>Company:</strong> {form.companyName || 'Aetheradix Private Limited'}
                </span>
                <span>•</span>
                <span>
                  <strong>GSTIN:</strong> {form.companyGSTIN || '23ABDCA8625L1ZJ'}
                </span>
                <span>•</span>
                <span>
                  <strong>Address:</strong> {form.companyCity || 'Bhopal'},{' '}
                  {form.companyState || 'Madhya Pradesh'}
                </span>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 p-4 bg-gray-50 rounded-2xl border border-gray-200 animate-in fade-in duration-200">
                <Input
                  label="Company Name"
                  value={form.companyName}
                  onChange={(e) => updateField('companyName', e.target.value)}
                />
                <Input
                  label="Contact Person"
                  value={form.companyContact}
                  onChange={(e) => updateField('companyContact', e.target.value)}
                />
                <Input
                  label="Company GSTIN"
                  value={form.companyGSTIN}
                  onChange={(e) => updateField('companyGSTIN', e.target.value)}
                />
                <div className="md:col-span-2">
                  <Input
                    label="Company Address"
                    value={form.companyAddress}
                    onChange={(e) => updateField('companyAddress', e.target.value)}
                  />
                </div>
                <Input
                  label="City"
                  value={form.companyCity}
                  onChange={(e) => updateField('companyCity', e.target.value)}
                />
                <Input
                  label="State"
                  value={form.companyState}
                  onChange={(e) => updateField('companyState', e.target.value)}
                />
                <Input
                  label="Pincode"
                  value={form.companyPincode}
                  onChange={(e) => updateField('companyPincode', e.target.value)}
                />
                <Input
                  label="Country"
                  value={form.companyCountry}
                  onChange={(e) => updateField('companyCountry', e.target.value)}
                />
              </div>
            )}
          </section>

          {/* Section 4: Invoice Line Items */}
          <section className="space-y-4">
            <SectionTitle
              icon={<IndianRupee size={18} />}
              title="Invoice Line Items"
              description="Add deliverables, professional services, or products."
            />

            {errors.items && <p className="text-xs text-red-500 font-medium">{errors.items}</p>}

            <div className="bg-gray-50/70 p-4 rounded-2xl border border-gray-200">
              <div className="flex items-center justify-between pb-3 border-b border-gray-200 mb-3">
                <span className="font-bold text-gray-900 text-sm flex items-center gap-1.5">
                  <IndianRupee size={16} className="text-emerald-600" /> Billed Items
                </span>
                <button
                  type="button"
                  onClick={addItem}
                  className="text-xs text-black font-semibold flex items-center gap-1 hover:underline cursor-pointer">
                  <Plus size={14} /> Add Line Item
                </button>
              </div>

              <div className="space-y-3">
                {safeItems.map((item, idx) => {
                  const lineTotal = Number(item.quantity || 0) * Number(item.rate || 0);

                  return (
                    <div
                      key={idx}
                      className="flex flex-col sm:flex-row gap-2.5 items-stretch sm:items-center bg-white p-2.5 rounded-xl border border-gray-200">
                      <input
                        type="text"
                        placeholder="Item Description / Professional Service"
                        value={item.description}
                        onChange={(e) => updateItem(idx, 'description', e.target.value)}
                        className="flex-1 border border-gray-200 rounded-lg px-3 py-2 text-xs focus:border-black outline-none bg-white font-medium"
                      />

                      <div className="flex items-center gap-2">
                        <div className="flex items-center gap-1">
                          <span className="text-[11px] text-gray-500 font-medium sm:hidden">
                            Qty:
                          </span>
                          <input
                            type="number"
                            min="1"
                            placeholder="Qty"
                            value={item.quantity || ''}
                            onChange={(e) => updateItem(idx, 'quantity', Number(e.target.value))}
                            className="w-20 border border-gray-200 rounded-lg px-2.5 py-2 text-xs text-center font-mono focus:border-black outline-none bg-white"
                          />
                        </div>

                        <div className="flex items-center gap-1">
                          <span className="text-[11px] text-gray-500 font-medium sm:hidden">
                            Rate:
                          </span>
                          <input
                            type="number"
                            min="0"
                            placeholder="Rate (₹)"
                            value={item.rate || ''}
                            onChange={(e) => updateItem(idx, 'rate', Number(e.target.value))}
                            className="w-28 border border-gray-200 rounded-lg px-2.5 py-2 text-xs text-right font-mono focus:border-black outline-none bg-white"
                          />
                        </div>

                        <div className="w-28 text-right font-mono font-bold text-xs text-gray-900 px-2 shrink-0">
                          ₹{lineTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                        </div>

                        {safeItems.length > 1 && (
                          <button
                            type="button"
                            onClick={() => removeItem(idx)}
                            className="text-gray-400 hover:text-red-500 transition p-1.5 cursor-pointer">
                            <Trash2 size={16} />
                          </button>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Items Subtotal Footer */}
              <div className="mt-4 pt-3 border-t border-gray-200 flex justify-between font-bold text-xs text-gray-900">
                <span>Subtotal (Excl. Tax)</span>
                <span className="font-mono">
                  ₹{subTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                </span>
              </div>
            </div>
          </section>

          {/* Section 5: Calculation Summary & Notes */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <SectionTitle
                icon={<FileText size={18} />}
                title="Notes & Payment Terms"
                description="Optional terms displayed on the invoice."
              />
              <textarea
                rows={3}
                value={form.notes}
                onChange={(e) => updateField('notes', e.target.value)}
                placeholder="e.g. Thank you for your business. Payment is due within 15 days."
                className="mt-3 w-full border border-gray-300 rounded-xl px-3.5 py-2.5 text-xs outline-none focus:ring-2 focus:ring-black resize-none"
              />
            </div>

            <div className="bg-gray-50/80 border border-gray-200 rounded-2xl p-4.5 flex flex-col justify-between space-y-3">
              <div className="space-y-2 text-xs">
                <div className="flex justify-between items-center text-gray-600">
                  <span>Sub Total (Taxable Value)</span>
                  <span className="font-mono font-semibold text-gray-900">
                    ₹{subTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </span>
                </div>
                <div className="flex justify-between items-center text-gray-600">
                  <span>GST ({form.gstRate}%)</span>
                  <span className="font-mono font-semibold text-gray-900">
                    ₹{gstAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </span>
                </div>
              </div>

              <div className="border-t border-gray-200 pt-3 flex justify-between items-baseline">
                <div>
                  <span className="text-xs font-bold uppercase tracking-wider text-gray-500 block">
                    Total Amount Due
                  </span>
                  <span className="text-[11px] text-gray-400">Includes all applicable taxes</span>
                </div>
                <span className="text-2xl font-black font-mono text-gray-900">
                  ₹{total.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                </span>
              </div>
            </div>
          </div>

          {/* Net Amount Banner - Matching Payroll Pattern */}
          <div className="p-4 rounded-2xl bg-black text-white flex justify-between items-center">
            <div>
              <p className="text-xs text-gray-400 font-medium">Total Invoice Amount</p>
              <p className="text-xl font-bold font-mono mt-0.5">
                ₹{total.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
              </p>
            </div>
          </div>
        </form>

        {/* Sticky Modal Footer */}
        <div className="px-6 py-4 bg-gray-50 border-t border-gray-200 flex justify-end gap-3 sticky bottom-0 shrink-0">
          <button
            type="button"
            disabled={isSubmitting}
            onClick={handleClose}
