const formatCurrency = (amount: number, currencySymbol = '₹'): string => {
  const value = Number(amount || 0);

  return `${currencySymbol}${value.toLocaleString('en-IN', {
    maximumFractionDigits: 0,
  })}`;
};

const getAmountInWords = (amount: number): string => {
  if (amount === 0) return 'Zero Rupees Only';

  const ones = [
    '',
    'One',
    'Two',
    'Three',
    'Four',
    'Five',
    'Six',
    'Seven',
    'Eight',
    'Nine',
    'Ten',
    'Eleven',
    'Twelve',
    'Thirteen',
    'Fourteen',
    'Fifteen',
    'Sixteen',
    'Seventeen',
    'Eighteen',
    'Nineteen',
  ];

  const tens = [
    '',
    '',
    'Twenty',
    'Thirty',
    'Forty',
    'Fifty',
    'Sixty',
    'Seventy',
    'Eighty',
    'Ninety',
  ];

  const convertBelowThousand = (num: number): string => {
    let result = '';

    if (num >= 100) {
      result += `${ones[Math.floor(num / 100)]} Hundred `;
      num %= 100;
    }

    if (num >= 20) {
      result += tens[Math.floor(num / 10)];

      if (num % 10) {
        result += ` ${ones[num % 10]}`;
      }
    } else if (num > 0) {
      result += ones[num];
    }

    return result.trim();
  };

  let number = Math.floor(Math.abs(amount));

  const parts: string[] = [];

  const crore = Math.floor(number / 10000000);
  number %= 10000000;

  const lakh = Math.floor(number / 100000);
  number %= 100000;

  const thousand = Math.floor(number / 1000);
  number %= 1000;

  if (crore) {
    parts.push(`${convertBelowThousand(crore)} Crore`);
  }

  if (lakh) {
    parts.push(`${convertBelowThousand(lakh)} Lakh`);
  }

  if (thousand) {
    parts.push(`${convertBelowThousand(thousand)} Thousand`);
  }

  if (number) {
    parts.push(convertBelowThousand(number));
  }

  return `${parts.join(' ')} Rupees Only`;
};

export const formatPayPeriodDisplay = (payPeriod?: string, monthYear?: string): string => {
  if (payPeriod && payPeriod.trim() && (payPeriod.includes('-') || payPeriod.includes('–'))) {
    return payPeriod;
  }
  const source = monthYear || payPeriod || '';
  const months = [
    'JANUARY',
    'FEBRUARY',
    'MARCH',
    'APRIL',
    'MAY',
    'JUNE',
    'JULY',
    'AUGUST',
    'SEPTEMBER',
    'OCTOBER',
    'NOVEMBER',
    'DECEMBER',
  ];
  const parts = source.trim().split(/[\s\/\-]+/).filter(Boolean);
  let foundMonth = 'DECEMBER';
  let foundYear = new Date().getFullYear();
  for (const p of parts) {
    const num = Number(p);
    if (!isNaN(num) && num >= 1900 && num <= 2100) {
      foundYear = num;
    } else {
      const idx = months.findIndex((m) => m === p.toUpperCase() || m.startsWith(p.toUpperCase().slice(0, 3)));
      if (idx !== -1) foundMonth = months[idx];
    }
  }
  const mIndex = months.indexOf(foundMonth);
  const totalDays = new Date(foundYear, mIndex + 1, 0).getDate();
  const capMonth = foundMonth.charAt(0) + foundMonth.slice(1).toLowerCase();
  return `01 ${capMonth} – ${totalDays} ${capMonth} ${foundYear}`;
};

