                  padding: '6px 15px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  boxSizing: 'border-box',
                }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <span
                    className="netpay-label"
                    style={{
                      fontSize: '13px',
                      fontWeight: 700,
                      lineHeight: '1.3',
                      paddingBottom: '2px',
                    }}>
                    Net Pay
                  </span>
                  {isVoid && (
                    <span
                      style={{
                        background: '#fca5a5',
                        color: '#7f1d1d',
                        fontSize: '10px',
                        fontWeight: 900,
                        padding: '1px 6px',
                        borderRadius: '4px',
                        letterSpacing: '0.5px',
