            className="totals-right"
            style={{
              display: 'flex',
              boxSizing: 'border-box',
            }}>
            <div
              className="net-pay-card"
              style={{
                width: '100%',
                background: '#111111',
                color: '#ffffff',
                padding: '16px 18px',
                boxSizing: 'border-box',
              }}>
              <div
                className="net-pay-amount"
                style={{
                  fontSize: '25px',
                  fontWeight: 800,
                  lineHeight: '1.25',
                  paddingBottom: '3px',
                }}>
                {formatCurrency(netPay, currencySymbol)}
              </div>

              <div
                className="net-pay-subtext"
                style={{
                  marginTop: '3px',
                  fontSize: '9px',
                  color: '#bdbdbd',
                  textTransform: 'uppercase',
                  letterSpacing: '0.6px',
                  lineHeight: '1.3',
                  paddingBottom: '2px',
                }}>
                Total Net Pay
              </div>

              <div
                className="card-divider"
                style={{
                  height: '1px',
                  background: '#444444',
                  margin: '12px 0',
                }}
              />

              <DaysRow label="Paid Days" value={String(data.paidDays ?? 22).padStart(2, '0')} />
              <DaysRow label="LOP Days" value={String(data.lopDays ?? 0).padStart(2, '0')} />
            </div>
          </div>
        </div>

        <div
          className="preview-footer-section"
          style={{
            marginTop: '20px',
            boxSizing: 'border-box',
          }}>
          <div
            className="footer-line"
            style={{
              height: '1px',
              background: '#111111',
              marginBottom: '14px',
            }}
          />

          <div
            className="footer-cols"
            style={{
              display: 'grid',
              gridTemplateColumns: '1fr 1fr',
              gap: '30px',
              boxSizing: 'border-box',
