            {/* SIGNATORY */}
            <div className="footer-col-left">
              <div
                className="signatory-row"
                style={{
                  display: 'grid',
                  gridTemplateColumns: '112px 10px 1fr',
                  fontSize: '10px',
                  lineHeight: '1.5',
                  alignItems: 'start',
                }}>
                <span
                  className="sign-label"
                  style={{
                    color: '#555555',
                    lineHeight: '1.5',
                  }}>
                  Authorized Signatory
                </span>

                <span className="sign-colon" style={{ lineHeight: '1.5' }}>
                  :
                </span>

                <span
                  className="sign-value"
                  style={{
                    fontWeight: 700,
                    lineHeight: '1.5',
                    paddingBottom: '2px',
                  }}>
                  {data.authorizedSignatory || 'Seema Srivastava'}
                  <br />
                  <small
                    className="sign-title"
                    style={{
                      color: '#555555',
                      fontWeight: 400,
                      lineHeight: '1.5',
                      display: 'inline-block',
                      paddingBottom: '2px',
                    }}>
                    {data.signatoryRole || '(Director)'}
                  </small>
                </span>
              </div>
            </div>

            {/* HR NOTE */}
            <div className="footer-col-right">
              <div
                className="hr-note-box"
                style={{
                  fontSize: '10px',
                  lineHeight: '1.45',
                  boxSizing: 'border-box',
