                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
});

interface MetaItemProps {
  label: string;
  value: string | number;
  bold?: boolean;
}

function MetaItem({ label, value, bold = false }: MetaItemProps) {
  return (
    <div
      className="meta-col"
      style={{
        display: 'grid',
        gridTemplateColumns: '92px 10px 1fr',
        alignItems: 'center',
        padding: '4px 0',
        fontSize: '10px',
        lineHeight: '1.35',
        boxSizing: 'border-box',
      }}>
      <span
        className="meta-label"
        style={{
          color: '#666666',
          lineHeight: '1.35',
          paddingBottom: '1px',
        }}>
        {label}
      </span>

      <span className="meta-colon" style={{ lineHeight: '1.35' }}>
        :
      </span>

      <span
        className={`meta-value ${bold ? 'font-bold' : ''}`}
        style={{
          fontWeight: bold ? 700 : 400,
          wordBreak: 'break-word',
          lineHeight: '1.35',
          paddingBottom: '1px',
        }}>
        {value || '-'}
      </span>
    </div>
  );
}

interface SalaryTableProps {
  title: string;
  rows: EarningsItem[] | DeductionItem[];
  totalLabel: string;
  total: number;
  currencySymbol: string;
}

function SalaryTable({ title, rows, totalLabel, total, currencySymbol }: SalaryTableProps) {
  return (
    <div
      className="table-col"
      style={{
        border: '1px solid #111111',
        background: '#ffffff',
        boxSizing: 'border-box',
      }}>
      <div
        className="table-header-bar"
        style={{
          minHeight: '31px',
          background: '#111111',
          color: '#ffffff',
          display: 'flex',
          alignItems: 'center',
          padding: '4px 13px',
          fontSize: '10px',
          fontWeight: 800,
          letterSpacing: '0.5px',
          lineHeight: '1.3',
          boxSizing: 'border-box',
        }}>
        <span style={{ lineHeight: '1.3', paddingBottom: '1px' }}>{title}</span>
      </div>

      <div className="table-body">
        {rows.map((item, index) => (
          <div
            key={item.id || `${title}-${item.name}-${index}`}
            className="table-row"
            style={{
              minHeight: '30px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              padding: '4px 13px',
              borderBottom: '1px solid #e5e5e5',
              boxSizing: 'border-box',
              fontSize: '10px',
              lineHeight: '1.3',
            }}>
            <span
              className="item-name"
              style={{
                overflow: 'visible',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
                paddingRight: '10px',
                lineHeight: '1.3',
                paddingBottom: '1px',
              }}>
              {item.name}
            </span>

            <span
              className="item-amount"
              style={{
                flexShrink: 0,
                fontWeight: item.name ? 600 : 400,
                lineHeight: '1.3',
                paddingBottom: '1px',
              }}>
              {item.name ? formatCurrency(item.amount, currencySymbol) : ''}
            </span>
          </div>
        ))}
      </div>

      <div
        className="table-total-row"
        style={{
          minHeight: '35px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '4px 13px',
          background: '#eeeeee',
          fontSize: '10px',
          fontWeight: 800,
          lineHeight: '1.3',
          boxSizing: 'border-box',
        }}>
        <span className="total-label" style={{ lineHeight: '1.3', paddingBottom: '1px' }}>
          {totalLabel}
        </span>

        <span className="total-amount" style={{ lineHeight: '1.3', paddingBottom: '1px' }}>
          {formatCurrency(total, currencySymbol)}
        </span>
      </div>
    </div>
  );
}

function DetailRow({ label, value }: { label: string; value: string }) {
  return (
    <div
      className="detail-row"
      style={{
        display: 'grid',
        gridTemplateColumns: '105px 10px 1fr',
        alignItems: 'center',
        minHeight: '26px',
        padding: '3px 0',
        fontSize: '10px',
        lineHeight: '1.35',
        boxSizing: 'border-box',
      }}>
      <span
        className="detail-label"
        style={{
          color: '#555555',
          lineHeight: '1.35',
          paddingBottom: '1px',
        }}>
        {label}
      </span>

      <span className="detail-colon" style={{ lineHeight: '1.35' }}>
        :
      </span>

      <span
        className="detail-value"
        style={{
          fontWeight: 600,
          wordBreak: 'break-word',
          lineHeight: '1.35',
          paddingBottom: '1px',
        }}>
        {value || '-'}
      </span>
    </div>
  );
}

function DaysRow({ label, value }: { label: string; value: string }) {
  return (
    <div
      className="days-row"
      style={{
        display: 'grid',
        gridTemplateColumns: '65px 8px 1fr',
        alignItems: 'center',
        fontSize: '9px',
        lineHeight: '1.4',
        padding: '2px 0',
      }}>
      <span
        className="days-label"
        style={{
          color: '#bbbbbb',
          lineHeight: '1.4',
        }}>
        {label}
      </span>

      <span className="days-colon" style={{ lineHeight: '1.4' }}>
        :
      </span>

      <span
        className="days-value"
        style={{
          fontWeight: 700,
          lineHeight: '1.4',
        }}>
        {value}
      </span>
    </div>
  );
}

SalarySlipTemplate.displayName = 'SalarySlipTemplate';

export default SalarySlipTemplate;

