import React, { useState, useEffect } from 'react';
import { Modal } from 'antd';
import { AlertTriangle, User, Calendar, Ban, IndianRupee } from 'lucide-react';
import type { PayrollRecord } from '../PayrollPage';

interface VoidPayrollModalProps {
  isOpen: boolean;
  record: PayrollRecord | null;
  isLoading?: boolean;
  onClose: () => void;
  onConfirm: (reason: string, notes: string) => Promise<void>;
}

const VOID_REASONS = [
  'Incorrect tax calculation (TDS / Deductions)',
  'Wrong base salary or allowance amount',
  'Incorrect working days / LOP calculation',
  'Wrong tax regime applied (Old vs New Regime)',
  'Duplicate payroll slip generated',
  'Clerical / manual entry error',
  'Other calculation discrepancy',
];

export const VoidPayrollModal: React.FC<VoidPayrollModalProps> = ({
  isOpen,
  record,
  isLoading = false,
  onClose,
  onConfirm,
}) => {
  const [selectedReason, setSelectedReason] = useState<string>(VOID_REASONS[0]);
  const [customNotes, setCustomNotes] = useState<string>('');
  const [confirmChecked, setConfirmChecked] = useState<boolean>(false);

  useEffect(() => {
    if (isOpen) {
      setSelectedReason(VOID_REASONS[0]);
      setCustomNotes('');
      setConfirmChecked(false);
    }
  }, [isOpen]);

  if (!record) return null;

  const handleSubmit = async () => {
    if (!selectedReason) return;
    await onConfirm(selectedReason, customNotes.trim());
  };

  return (
    <Modal
      open={isOpen}
      onCancel={() => {
        if (!isLoading) onClose();
      }}
      footer={null}
      width={560}
      centered
      destroyOnClose
      className="void-payroll-modal">
      <div className="flex flex-col gap-5 p-1 sm:p-2">
        {/* Header */}
        <div className="flex items-start gap-3.5 border-b border-rose-100 pb-4">
          <div className="w-11 h-11 rounded-2xl bg-rose-50 border border-rose-200 flex items-center justify-center text-rose-600 shrink-0 shadow-xs">
            <AlertTriangle size={22} />
          </div>
          <div className="flex flex-col">
            <h3 className="text-base font-bold text-slate-900 flex items-center gap-2">
              Mark Payroll as Void
              <span className="text-[10px] font-bold uppercase bg-rose-100 text-rose-700 px-2 py-0.5 rounded-full border border-rose-200">
                Action Required
              </span>
            </h3>
            <p className="text-xs text-slate-500 mt-0.5">
              Invalidate incorrect salary computations, wrong TDS deductions, or clerical errors.
            </p>
          </div>
        </div>

        {/* Record Overview Card */}
        <div className="bg-slate-50 border border-slate-200 rounded-2xl p-4 flex flex-col gap-3">
          <div className="flex items-center justify-between pb-2.5 border-b border-slate-200/80">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 rounded-xl bg-indigo-50 border border-indigo-100 flex items-center justify-center text-indigo-600">
                <User size={15} />
              </div>
              <div className="flex flex-col">
                <span className="text-xs font-bold text-slate-900">{record.employeeName}</span>
                <span className="text-[11px] text-slate-500">ID: {record.employeeCode} • {record.department}</span>
              </div>
            </div>
            <span className="font-mono text-xs font-bold bg-white text-slate-800 px-2.5 py-1 rounded-lg border border-slate-200 shadow-2xs">
              {record.paySlipNo}
            </span>
          </div>

          <div className="grid grid-cols-2 gap-3 text-xs">
            <div className="flex items-center gap-2 text-slate-600">
              <Calendar size={14} className="text-slate-400" />
              <span>Period: <strong>{record.monthYear}</strong></span>
            </div>
            <div className="flex items-center gap-2 text-slate-600">
              <IndianRupee size={14} className="text-slate-400" />
              <span>Net Pay: <strong className="text-slate-900">₹{Number(record.total || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</strong></span>
            </div>
          </div>
        </div>

        {/* Reason Selector */}
        <div className="flex flex-col gap-1.5">
          <label className="text-xs font-bold text-slate-700">
            Reason for Voiding <span className="text-rose-500">*</span>
          </label>
          <select
            value={selectedReason}
            onChange={(e) => setSelectedReason(e.target.value)}
            disabled={isLoading}
            className="w-full bg-white border border-slate-300 rounded-xl px-3.5 py-2.5 text-xs font-medium text-slate-800 focus:outline-none focus:border-rose-500 focus:ring-1 focus:ring-rose-500 shadow-xs cursor-pointer">
            {VOID_REASONS.map((reason) => (
              <option key={reason} value={reason}>
                {reason}
              </option>
            ))}
          </select>
        </div>

        {/* Additional Explanation / Details */}
        <div className="flex flex-col gap-1.5">
          <label className="text-xs font-bold text-slate-700">
            Discrepancy Details & Justification <span className="text-slate-400 font-normal">(Optional)</span>
          </label>
          <textarea
            rows={3}
            value={customNotes}
            onChange={(e) => setCustomNotes(e.target.value)}
            disabled={isLoading}
            placeholder="e.g. TDS was computed under Old Tax Regime instead of New Regime rebate, or base salary miscalculated by ₹10,000. Replacement payslip to be issued."
            className="w-full bg-white border border-slate-300 rounded-xl px-3.5 py-2 text-xs text-slate-800 placeholder-slate-400 focus:outline-none focus:border-rose-500 focus:ring-1 focus:ring-rose-500 resize-none shadow-xs"
          />
        </div>

        {/* Consequence Notice */}
        <div className="bg-rose-50/70 border border-rose-200/90 rounded-2xl p-3.5 text-xs text-rose-800 flex items-start gap-2.5">
          <Ban size={16} className="text-rose-600 shrink-0 mt-0.5" />
          <div className="flex flex-col gap-1 text-[11px] leading-relaxed">
            <span className="font-bold text-rose-900">What happens when marked as Void:</span>
            <ul className="list-disc list-inside space-y-0.5 text-rose-700">
              <li>This payslip is flagged as <strong>VOID</strong> across financial records and reports.</li>
              <li>A diagonal <strong>VOID watermark</strong> and cancellation banner will appear on the payslip.</li>
              <li>An official audit log entry is saved under the <strong>3-month retention policy</strong>.</li>
            </ul>
          </div>
        </div>

        {/* Confirmation Checkbox */}
        <label className="flex items-center gap-2.5 text-xs text-slate-700 font-medium cursor-pointer select-none">
          <input
            type="checkbox"
            checked={confirmChecked}
            onChange={(e) => setConfirmChecked(e.target.checked)}
            disabled={isLoading}
            className="w-4 h-4 text-rose-600 rounded border-slate-300 focus:ring-rose-500 cursor-pointer"
          />
          <span>I confirm this payroll contains calculation errors and should be marked void.</span>
        </label>

        {/* Actions */}
        <div className="flex items-center justify-end gap-3 pt-2 border-t border-slate-100">
          <button
            type="button"
            disabled={isLoading}
            onClick={onClose}
            className="px-4 py-2 text-xs font-semibold text-slate-600 hover:text-slate-800 hover:bg-slate-100 rounded-xl transition cursor-pointer">
            Cancel
          </button>
          <button
            type="button"
            disabled={isLoading || !confirmChecked}
            onClick={handleSubmit}
            className="px-5 py-2.5 text-xs font-bold text-white bg-rose-600 hover:bg-rose-700 rounded-xl transition shadow-xs disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 cursor-pointer active:scale-95">
            <Ban size={15} />
            {isLoading ? 'Voiding Payroll...' : 'Confirm & Mark as Void'}
          </button>
        </div>
      </div>
    </Modal>
  );
};
export default VoidPayrollModal;

import { useRef, useState } from 'react';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import type { InvoiceForm } from '../types/invoice.types';

/**
 * Direct jsPDF generator:
 * High-performance vector PDF rendering using jsPDF & autoTable.
 * Serves as an instant, infallible fallback if DOM canvas snapshot fails.
 */
export function generateDirectInvoicePdf(invoice: InvoiceForm): jsPDF {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const pageW = doc.internal.pageSize.getWidth(); // 210mm
  const margin = 14;

  // Header background
  doc.setFillColor(17, 24, 39); // #111827 (dark slate)
  doc.rect(0, 0, pageW, 36, 'F');

  // Brand Name
  doc.setTextColor(186, 230, 253); // #BAE6FD
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text('AETHERADIX', margin, 18);

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(209, 213, 219);
  doc.text('Enterprise Cloud & ERP Solutions', margin, 26);

  // TAX INVOICE title right-aligned
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.text('TAX INVOICE', pageW - margin, 16, { align: 'right' });

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(186, 230, 253);
  doc.text(`INVOICE: ${invoice.invoiceNumber || 'INV-000'}`, pageW - margin, 24, {
    align: 'right',
  });

  // Reset text color to dark
  doc.setTextColor(31, 41, 55);

  // Two columns: Issuer Details (Left) and Bill To (Right)
  const y = 48;

  // Left: Issuer Company
  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  doc.text('ISSUER DETAILS:', margin, y);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  doc.text(invoice.companyName || 'Aetheradix Private Limited', margin, y + 6);
  if (invoice.companyContact) doc.text(`Contact: ${invoice.companyContact}`, margin, y + 11);
  if (invoice.companyAddress) doc.text(invoice.companyAddress, margin, y + 16);
  const compLoc = [invoice.companyCity, invoice.companyState, invoice.companyPincode]
    .filter(Boolean)
    .join(', ');
  if (compLoc) doc.text(compLoc, margin, y + 21);
  if (invoice.companyGSTIN) doc.text(`GSTIN: ${invoice.companyGSTIN}`, margin, y + 26);

  // Right: Bill To
  const rightX = pageW / 2 + 5;
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10);
  doc.text('BILL TO:', rightX, y);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  doc.text(invoice.billToName || 'Client Name', rightX, y + 6);
  if (invoice.billToAddress) doc.text(invoice.billToAddress, rightX, y + 11);
  const billLoc = [invoice.billToCity, invoice.billToState, invoice.billToPincode]
    .filter(Boolean)
    .join(', ');
  if (billLoc) doc.text(billLoc, rightX, y + 16);
  if (invoice.billToCountry) doc.text(invoice.billToCountry, rightX, y + 21);
  if (invoice.billToGSTIN) doc.text(`GSTIN: ${invoice.billToGSTIN}`, rightX, y + 26);

  // Dates & Supply bar
  const barY = 82;
  doc.setFillColor(243, 244, 246);
  doc.roundedRect(margin, barY, pageW - margin * 2, 14, 2, 2, 'F');
  doc.setFontSize(8.5);
  doc.setFont('helvetica', 'bold');
  doc.text('Invoice Date:', margin + 4, barY + 6);
  doc.setFont('helvetica', 'normal');
  doc.text(invoice.invoiceDate || '-', margin + 25, barY + 6);

  doc.setFont('helvetica', 'bold');
  doc.text('Due Date:', margin + 65, barY + 6);
  doc.setFont('helvetica', 'normal');
  doc.text(invoice.dueDate || '-', margin + 82, barY + 6);

  doc.setFont('helvetica', 'bold');
  doc.text('Place of Supply:', margin + 125, barY + 6);
  doc.setFont('helvetica', 'normal');
  doc.text(invoice.placeOfSupply || 'Madhya Pradesh', margin + 152, barY + 6);

  doc.setFont('helvetica', 'bold');
  doc.text('Status:', margin + 4, barY + 11);
  doc.setFont('helvetica', 'normal');
  doc.text(invoice.status || 'Pending', margin + 25, barY + 11);

  // Line items table
  const items = Array.isArray(invoice.items) ? invoice.items : [];
  const tableRows = items.map((it, idx) => [
    String(idx + 1),
    it.description || 'Professional Services',
    String(it.quantity || 1),
    `₹${Number(it.rate || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}`,
    `₹${(Number(it.quantity || 1) * Number(it.rate || 0)).toLocaleString('en-IN', { minimumFractionDigits: 2 })}`,
  ]);

  autoTable(doc, {
    startY: 102,
    margin: { left: margin, right: margin },
    head: [['#', 'Description', 'Qty', 'Rate', 'Total']],
    body: tableRows,
    theme: 'grid',
    headStyles: {
      fillColor: [17, 24, 39],
      textColor: [255, 255, 255],
      fontStyle: 'bold',
      fontSize: 9,
    },
    bodyStyles: { fontSize: 8.5, textColor: [31, 41, 55] },
    columnStyles: {
      0: { cellWidth: 10, halign: 'center' },
      1: { cellWidth: 'auto' },
      2: { cellWidth: 20, halign: 'center' },
      3: { cellWidth: 35, halign: 'right' },
      4: { cellWidth: 35, halign: 'right' },
    },
  });

  const finalY = (doc as any).lastAutoTable?.finalY || 150;

  // Totals Breakdown
  const subTotal = items.reduce(
    (sum, it) => sum + Number(it.quantity || 0) * Number(it.rate || 0),
    0
  );
  const gstAmount = (subTotal * Number(invoice.gstRate || 0)) / 100;
  const grandTotal = subTotal + gstAmount;

  const summaryX = pageW - margin - 75;
  let totY = finalY + 8;

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.text('Subtotal:', summaryX, totY);
  doc.text(
    `₹${subTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`,
    pageW - margin,
    totY,
    { align: 'right' }
  );

  totY += 6;
  doc.text(`GST (${invoice.gstRate || 0}%):`, summaryX, totY);
  doc.text(
    `₹${gstAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`,
    pageW - margin,
    totY,
    { align: 'right' }
  );

  totY += 7;
  doc.setDrawColor(209, 213, 219);
  doc.line(summaryX, totY - 4, pageW - margin, totY - 4);

  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text('Total Amount:', summaryX, totY);
  doc.text(
    `₹${grandTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`,
    pageW - margin,
    totY,
    { align: 'right' }
  );

  // Notes
  if (invoice.notes) {
    doc.setFontSize(8.5);
    doc.setFont('helvetica', 'bold');
    doc.text('Notes / Payment Terms:', margin, totY + 14);
    doc.setFont('helvetica', 'normal');
    doc.text(invoice.notes, margin, totY + 19, { maxWidth: pageW - margin * 2 });
  }

  // Footer
  const pageH = doc.internal.pageSize.getHeight();
  doc.setFontSize(8);
  doc.setTextColor(156, 163, 175);
  doc.text(
    'Thank you for your business! This is a system-generated computer invoice.',
    pageW / 2,
    pageH - 10,
    { align: 'center' }
  );

  return doc;
}

export function useInvoicePdf() {
  const invoicePdfRef = useRef<HTMLDivElement>(null);
  const [pdfInvoice, setPdfInvoice] = useState<InvoiceForm | null>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  /**
   * Internal generator: attempts DOM snapshot first, falls back to direct jsPDF
   */
  const createInvoicePdfDocument = async (invoiceData: InvoiceForm): Promise<jsPDF> => {
    setIsGeneratingPdf(true);
    setPdfInvoice(invoiceData);

    // 1. Force layout flush & wait for web fonts
    await new Promise<void>((resolve) => {
      requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
    });
    if (document.fonts) {
      await document.fonts.ready;
    }
    await new Promise((resolve) => setTimeout(resolve, 250));

    let element = invoicePdfRef.current;
    for (let attempt = 0; attempt < 12 && !element; attempt++) {
      await new Promise((resolve) => setTimeout(resolve, 80));
      element = invoicePdfRef.current;
    }

    if (!element) {
      throw new Error('Invoice template DOM element not ready');
    }

    const canvas = await html2canvas(element, {
      scale: 2, // Keeps image resolution crisp
      useCORS: true,
      allowTaint: true,
      backgroundColor: '#ffffff',
      logging: false,
      scrollX: 0,
      scrollY: 0,
      onclone: (clonedDoc) => {
        const hiddenContainer = clonedDoc.getElementById('invoice-pdf-hidden-container');
        if (hiddenContainer) {
          hiddenContainer.style.opacity = '1';
          hiddenContainer.style.position = 'static';
          hiddenContainer.style.visibility = 'visible';
          hiddenContainer.style.zIndex = '1';
        }
        const target = clonedDoc.querySelector('[data-invoice-template="true"]') as HTMLElement;
        if (target) {
          target.style.position = 'static';
          target.style.display = 'block';
          target.style.margin = '0 auto';
          target.style.opacity = '1';
          target.style.visibility = 'visible';
        }
      },
    });

    if (!canvas || canvas.width === 0 || canvas.height === 0) {
      throw new Error('Canvas rendering produced zero-dimension output');
    }

    const pdf = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: 'a4',
      compress: true,
    });

    const pdfWidth = pdf.internal.pageSize.getWidth(); // 210mm
    const pdfHeight = pdf.internal.pageSize.getHeight(); // 297mm

    let imageWidth = pdfWidth;
    let imageHeight = (canvas.height * pdfWidth) / canvas.width;

    if (imageHeight > pdfHeight) {
      const ratio = pdfHeight / imageHeight;
      imageWidth = imageWidth * ratio;
      imageHeight = pdfHeight;
    }

    const xOffset = (pdfWidth - imageWidth) / 2;
    const imageData = canvas.toDataURL('image/png', 1.0);

    pdf.addImage(imageData, 'PNG', xOffset, 0, imageWidth, imageHeight);
    return pdf;
  };

  /**
   * Generates a Blob (for uploading to remote server or attachments)
   */
  const generateInvoicePDF = async (invoiceData: InvoiceForm): Promise<Blob> => {
    try {
      const pdf = await createInvoicePdfDocument(invoiceData);
      return pdf.output('blob');
    } catch (html2canvasErr) {
      console.warn(
        'html2canvas snapshot failed, using direct jsPDF generator fallback:',
        html2canvasErr
      );
      const directPdf = generateDirectInvoicePdf(invoiceData);
      return directPdf.output('blob');
    } finally {
      setIsGeneratingPdf(false);
      setPdfInvoice(null);
    }
  };

  /**
   * Direct download triggering jsPDF's built-in file saver:
   * Guarantees file is downloaded immediately with zero popup/blob revoke issues.
   */
  const downloadInvoicePDF = async (invoiceData: InvoiceForm, fileName: string): Promise<void> => {
    try {
      const pdf = await createInvoicePdfDocument(invoiceData);
      pdf.save(fileName);
    } catch (html2canvasErr) {
      console.warn(
        'html2canvas snapshot failed, using direct jsPDF download fallback:',
        html2canvasErr
      );
      const directPdf = generateDirectInvoicePdf(invoiceData);
      directPdf.save(fileName);
    } finally {
      setIsGeneratingPdf(false);
      setPdfInvoice(null);
    }
  };

  return {
    invoicePdfRef,
    pdfInvoice,
    isGeneratingPdf,
    generateInvoicePDF,
    downloadInvoicePDF,
  };
}

import { useMemo, useState } from 'react';
import {
  useGetAllSalarySlipsQuery,
  useCreateSalarySlipMutation,
} from '@/store/api/financeApiSlice';
import type { CreateSalarySlipPayload } from '@/store/api/financeApiSlice';
import { showToast } from '@/components/ui/composed/Toast.utils';
import { generateSlipNumber, extractSlipNumber } from '@/utils/payroll';
import {
  isProfessionalTaxName,
  isIncomeTaxTdsName,
  isProvidentFundName,
} from '../components/SalarySlipForm';

export interface BreakdownItem {
  name: string;
  amount: number;
}

export interface PayrollRecord {
  id: number | string;
  employeeId: number | string;
  employeeName: string;
  position: string;
  base: number;
  bonus: number;
  total: number;
  date: string; // monthYear
  payPeriod?: string;
  paySlipNo?: string;
  accountNumber?: string;
  paidDays: number;
  lopDays: number;
  earnings: BreakdownItem[];
  deductions: BreakdownItem[];
  authorizedSignatory?: string;
  signatoryRole?: string;
  hrNote?: string;
}

export interface SalarySlipFormData {
  employeeId: number | string;
  userId?: number | string;
  employeeName: string;
  position?: string;
  monthYear: string;
  payPeriod?: string;
  paySlipNo?: string;
  accountNumber?: string;
  paidDays: number | string;
  lopDays?: number | string;
  basePay?: number;
  bonusPay?: number;
  earnings: BreakdownItem[];
  deductions: BreakdownItem[];
  authorizedSignatory?: string;
  signatoryRole?: string;
  hrNote?: string;
}

export interface PayrollStats {
  totalPayroll: number;
  totalBasePay: number;
  totalBonus: number;
  recordCount: number;
}

export const usePayrollPage = () => {
  // 1. Fetch Salary Slips Query
  const {
    data: rawData,
    isLoading,
    isFetching,
    isError,
    error,
    refetch,
  } = useGetAllSalarySlipsQuery();

  // 2. Create Salary Slip Mutation
  const [createSalarySlip, { isLoading: isCreatingSlip }] = useCreateSalarySlipMutation();

  // 3. Local UI States
  const [showSalarySlipForm, setShowSalarySlipForm] = useState<boolean>(false);
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [selectedSlip, setSelectedSlip] = useState<PayrollRecord | null>(null);
  const [showSlipModal, setShowSlipModal] = useState<boolean>(false);

  // 4. Memoized Formatting for Database Records
  const payrollRecords: PayrollRecord[] = useMemo(() => {
    const itemsList = rawData?.data || (Array.isArray(rawData) ? rawData : []);
    if (!Array.isArray(itemsList)) return [];

    return itemsList.map((item: any, index: number) => {
      const rawEarnings: BreakdownItem[] = Array.isArray(item.earnings) ? item.earnings : [];
      const rawDeductions: BreakdownItem[] = Array.isArray(item.deductions) ? item.deductions : [];

      const basePay = Number(
        item.base_amount ||
          item.basePay ||
          rawEarnings.find((e) => e.name?.toLowerCase().includes('basic'))?.amount ||
          0
      );

      const bonusPay = Number(
        item.bonus_amount ||
          item.bonusPay ||
          rawEarnings.find((e) => e.name?.toLowerCase().includes('bonus'))?.amount ||
          0
      );

      const netSalary = Number(item.total_amount || item.net_salary || item.netSalary || 0);
      const monthYear = String(item.month_year || item.monthYear || item.created_at || 'N/A');

      return {
        id: item.id || Date.now(),
        employeeId: item.employee_id || item.employeeId || item.user_id || '0',
        employeeName: item.employee_name || item.employeeName || 'Unnamed Employee',
        position: item.position || item.employee_position || 'Employee',
        base: basePay,
        bonus: bonusPay,
        total: netSalary,
        date: monthYear,
        payPeriod: item.pay_period || item.payPeriod || monthYear,
        paySlipNo:
          extractSlipNumber(item, index + 1) ||
          item.pay_slip_no ||
          item.paySlipNo ||
          generateSlipNumber(
            item.employee_code || item.employee_id || item.employeeId || item.user_id,
            monthYear,
            index + 1
          ),
        accountNumber: item.account_number || item.accountNumber || 'N/A',
        paidDays: Number(item.paid_days || item.paidDays || 0),
        lopDays: Number(item.lop_days || item.lopDays || 0),
        earnings: rawEarnings.length > 0 ? rawEarnings : [{ name: 'Basic Pay', amount: basePay }],
        deductions: rawDeductions,
        authorizedSignatory: item.authorized_signatory || item.authorizedSignatory,
        signatoryRole: item.signatory_role || item.signatoryRole,
        hrNote: item.hr_note || item.hrNote,
      };
    });
  }, [rawData]);

  // 5. Search Filtering
  const filteredPayroll = useMemo(() => {
    const searchLower = searchQuery.toLowerCase().trim();
    if (!searchLower) return payrollRecords;

    return payrollRecords.filter((record) => {
      return (
        record.employeeName?.toLowerCase().includes(searchLower) ||
        record.position?.toLowerCase().includes(searchLower) ||
        record.date?.toLowerCase().includes(searchLower) ||
        String(record.total).includes(searchLower)
      );
    });
  }, [payrollRecords, searchQuery]);

  // 6. Summary Stats
  const stats: PayrollStats = useMemo(() => {
    return payrollRecords.reduce(
      (acc, curr) => {
        acc.totalPayroll += Number(curr.total || 0);
        acc.totalBasePay += Number(curr.base || 0);
        acc.totalBonus += Number(curr.bonus || 0);
        acc.recordCount += 1;
        return acc;
      },
      {
        totalPayroll: 0,
        totalBasePay: 0,
        totalBonus: 0,
        recordCount: 0,
      }
    );
  }, [payrollRecords]);

  // 7. Handler for Form Submit -> Triggers DB Insertion Network Call
  const handleCreateSalarySlip = async (formData: SalarySlipFormData) => {
    try {
      const safeEarnings = Array.isArray(formData.earnings) ? formData.earnings : [];
      const safeDeductions = Array.isArray(formData.deductions) ? formData.deductions : [];

      const basePay =
        formData.basePay ??
        Number(safeEarnings.find((i) => i.name?.toLowerCase().includes('basic'))?.amount || 0);
      const bonusPay =
        formData.bonusPay ??
        Number(safeEarnings.find((i) => i.name?.toLowerCase().includes('bonus'))?.amount || 0);

      const targetUserId =
        Number(formData.userId) ||
        (Number(formData.employeeId) > 0 ? Number(formData.employeeId) : 0);
      const targetEmpCode = String(formData.employeeId || targetUserId || '').trim();

      const payload: CreateSalarySlipPayload = {
        // Target Employee & Creator
        user_id: targetUserId,
        created_by: null,

        // Pay Period & Schedule
        month_year: formData.monthYear || 'OCTOBER 2026',
        pay_frequency: 'monthly',
        cycle_number: 1,
        pay_slip_no: formData.paySlipNo || null,
        paySlipNo: formData.paySlipNo || null,

        // Attendance
        paid_days: Number(formData.paidDays) || 0,
        lop_days: Number(formData.lopDays) || 0,
        totalWorkingDays: Number(formData.paidDays || 0) + Number(formData.lopDays || 0) || 30,

        // Employee Profile Details
        employee_code: targetEmpCode,
        designation: formData.position || 'Employee',
        bank_account_number: formData.accountNumber || null,

        // Financial Breakdown Arrays
        earnings: safeEarnings,
        deductions: safeDeductions,

        // Numerical Totals
        basicSalary: basePay,
        bonus: bonusPay,
        providentFund: safeDeductions.find((d) => isProvidentFundName(d.name))?.amount || 0,
        professionalTax: safeDeductions.find((d) => isProfessionalTaxName(d.name))?.amount || 0,
        incomeTaxTds: safeDeductions.find((d) => isIncomeTaxTdsName(d.name))?.amount || 0,

        // Metadata & Status
        paymentStatus: 'pending',
        paymentDate: new Date().toISOString().split('T')[0],
        remarks: formData.hrNote || null,
        authorized_signatory: formData.authorizedSignatory || 'Seema Srivastava',
        authorizedSignatory: formData.authorizedSignatory || 'Seema Srivastava',
        signatory_role: formData.signatoryRole || '(Director)',
        signatoryRole: formData.signatoryRole || '(Director)',
      };

      // Direct RTK Query Mutation Call
      const response = await createSalarySlip(payload).unwrap();

      setShowSalarySlipForm(false);

      showToast({
        severity: 'success',
        summary: 'Success',
        detail: 'Salary slip created successfully in the database.',
        life: 3000,
      });

      return response;
    } catch (err: unknown) {
      const apiError = err as { data?: { message?: string } };

      console.error('Failed to create salary slip:', err);

      showToast({
        severity: 'error',
        summary: 'Creation Error',
        detail: apiError.data?.message || 'Failed to create salary slip record.',
        life: 3000,
      });

      throw err;
    }
  };

  const resetFilters = () => {
    setSearchQuery('');
  };

  const openSlipDetail = (record: PayrollRecord) => {
    setSelectedSlip(record);
    setShowSlipModal(true);
  };

  const closeSlipDetail = () => {
    setSelectedSlip(null);
    setShowSlipModal(false);
  };

  return {
    // Data & Metrics
    payrollRecords,
    filteredPayroll,
    stats,

    // Query States
    isLoading,
    isFetching,
    isCreatingSlip,
    isError,
    error,

    // Actions & Mutation
    handleCreateSalarySlip,
    refetch,

    // Form Modal State
    showSalarySlipForm,
    setShowSalarySlipForm,

    // Detail Modal State
    selectedSlip,
    setSelectedSlip,
    showSlipModal,
    setShowSlipModal,
    openSlipDetail,
    closeSlipDetail,

    // Search & Helpers
    searchQuery,
    setSearchQuery,
    resetFilters,
  };
};

