// Compact section completion badge
function SectionBadge({
  sectionId,
  sectionLabel,
  completed,
}: {
  sectionId: string;
  sectionLabel: string;
  completed: boolean;
}) {
  const Icon = SECTION_ICON_MAP[sectionId] || FileText;
  return (
    <div
      className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl border text-[10px] font-bold transition-all ${
        completed
          ? 'bg-success/10 border-success/25 text-success'
          : 'bg-surface-subtle border-border-subtle text-muted'
      }`}>
      <Icon size={11} />
      <span>{sectionLabel}</span>
      {completed ? <CheckCircle2 size={10} className="text-success" /> : <Clock size={10} />}
    </div>
  );
}

// Onboarding Progress Panel — shows each employee's section-by-section status
function OnboardingProgressPanel({
  profiles,
  formConfig,
}: {
  profiles: ProfileCompletionData[];
  formConfig: FormSectionConfig[];
}) {
  const [expanded, setExpanded] = useState<number | null>(null);

  const onboardingProfiles = profiles.filter(
    (p) =>
      p.status === 'in_progress' ||
      p.status === 'incomplete' ||
      p.status === 'submitted' ||
      p.status === 'changes_required'
  );

  if (onboardingProfiles.length === 0) {
    return (
      <div className="p-6 text-center text-xs text-muted italic">
        No employees currently in the onboarding process.
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {onboardingProfiles.map((profile) => {
        const pct = calculateCompletionPercentage(profile, formConfig);
        const isExpanded = expanded === profile.userId;
        const conf = STATUS_MAP[profile.status] || STATUS_MAP.incomplete;
        const Icon = conf.icon;
        const totalSections = formConfig.filter((s) => !s.hidden).length;
        const completedCount = formConfig.filter(
          (s) => !s.hidden && profile.completedSections?.[s.id]
        ).length;

        return (
          <div
            key={profile.userId}
            className="border border-border-subtle rounded-2xl overflow-hidden bg-white hover:shadow-sm transition-all">
            {/* Row header */}
            <button
              type="button"
              onClick={() => setExpanded(isExpanded ? null : profile.userId)}
              className="w-full flex items-center justify-between px-5 py-4 text-left group">
              <div className="flex items-center gap-4 flex-1 min-w-0">
                {/* Avatar */}
                <div className="w-9 h-9 rounded-full bg-primary/10 border border-border-subtle flex items-center justify-center shrink-0 overflow-hidden">
                  {profile.profilePictureUrl ? (
                    <img
                      src={profile.profilePictureUrl}
                      alt=""
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <User size={16} className="text-primary" />
                  )}
                </div>

                {/* Name + email */}
                <div className="min-w-0">
                  <div className="text-sm font-bold text-foreground truncate">
                    {profile.personal?.fullName || profile.userEmail}
                  </div>
                  <div className="text-[11px] text-muted truncate">{profile.userEmail}</div>
                </div>

                {/* Status badge */}
                <span
                  className={`hidden md:inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold border ${conf.bg} shrink-0`}
                  style={{ lineHeight: '1' }}>
                  <Icon size={10} style={{ display: 'block', flexShrink: 0 }} />
                  <span>{conf.label}</span>
                </span>

                {/* Progress bar */}
                <div className="hidden lg:flex items-center gap-3 flex-1 max-w-xs">
                  <div className="flex-1 h-1.5 bg-surface-subtle rounded-full overflow-hidden">
                    <div
                      className={`h-full rounded-full transition-all duration-500 ${
                        pct === 100 ? 'bg-success' : pct > 50 ? 'bg-primary' : 'bg-warning'
                      }`}
                      style={{ width: `${pct}%` }}
                    />
                  </div>
                  <span className="text-xs font-bold text-foreground shrink-0">{pct}%</span>
                  <span className="text-[10px] text-muted shrink-0">
                    {completedCount}/{totalSections} sections
                  </span>
                </div>
              </div>

              <div className="flex items-center gap-2 shrink-0 ml-3">
                <span className="text-[11px] text-muted hidden md:block">
                  Updated{' '}
                  {profile.lastSavedAt ? new Date(profile.lastSavedAt).toLocaleDateString() : '—'}
                </span>
                {isExpanded ? (
                  <ChevronUp
                    size={16}
                    className="text-muted group-hover:text-foreground transition-colors"
                  />
                ) : (
                  <ChevronDown
                    size={16}
                    className="text-muted group-hover:text-foreground transition-colors"
                  />
                )}
              </div>
            </button>

            {/* Expanded detail */}
            {isExpanded && (
              <div className="border-t border-border-subtle px-5 py-4 bg-surface-subtle/50 space-y-4">
                {/* Section completion grid */}
                <div>
                  <div className="text-[10px] font-bold text-muted uppercase tracking-wider mb-2 flex items-center gap-1.5">
                    <ListChecks size={11} />
                    Section Completion Status
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {formConfig
                      .filter((s) => !s.hidden)
                      .sort((a, b) => a.order - b.order)
                      .map((section) => (
                        <SectionBadge
                          key={section.id}
                          sectionId={section.id}
                          sectionLabel={section.label}
                          completed={!!profile.completedSections?.[section.id]}
                        />
                      ))}
                  </div>
                </div>

                {/* Quick data highlights */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  <div className="p-3 rounded-xl bg-white border border-border-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase mb-1">Full Name</div>
                    <div className="text-xs font-semibold text-foreground">
                      {profile.personal?.fullName || '—'}
                    </div>
                  </div>
                  <div className="p-3 rounded-xl bg-white border border-border-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase mb-1">Contact</div>
                    <div className="text-xs font-semibold text-foreground">
                      {profile.personal?.contactNumber || '—'}
                    </div>
                  </div>
                  <div className="p-3 rounded-xl bg-white border border-border-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase mb-1">Bank</div>
                    <div className="text-xs font-semibold text-foreground">
                      {profile.bank?.bankName || '—'}
                    </div>
                  </div>
                  <div className="p-3 rounded-xl bg-white border border-border-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase mb-1">Documents</div>
                    <div className="text-xs font-semibold text-foreground">
                      {profile.documents?.length
                        ? `${profile.documents.length} uploaded`
                        : 'None yet'}
                    </div>
                  </div>
                  <div className="p-3 rounded-xl bg-white border border-border-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase mb-1">PAN</div>
                    <div className="text-xs font-mono font-semibold text-foreground">
                      {profile.identity?.panNumber || '—'}
                    </div>
                  </div>
                  <div className="p-3 rounded-xl bg-white border border-border-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase mb-1">Aadhaar</div>
                    <div className="text-xs font-mono font-semibold text-foreground">
                      {profile.identity?.aadhaarNumber
                        ? `•••• ${profile.identity.aadhaarNumber.slice(-4)}`
                        : '—'}
                    </div>
                  </div>
                  <div className="p-3 rounded-xl bg-white border border-border-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase mb-1">
                      Employment Entries
                    </div>
                    <div className="text-xs font-semibold text-foreground">
                      {profile.employment?.length ? `${profile.employment.length} entries` : 'None'}
                    </div>
                  </div>
                  <div className="p-3 rounded-xl bg-white border border-border-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase mb-1">
                      Education Entries
                    </div>
                    <div className="text-xs font-semibold text-foreground">
                      {profile.education?.length ? `${profile.education.length} entries` : 'None'}
                    </div>
                  </div>
                </div>

                {/* Review notes if present */}
                {profile.reviewNotes && (
                  <div className="p-3 rounded-xl bg-warning/5 border border-warning/20">
                    <div className="text-[10px] font-bold text-warning uppercase mb-1">
                      Pending Revision Notes
                    </div>
                    <div className="text-xs text-foreground">{profile.reviewNotes}</div>
                  </div>
                )}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

export default function HiringTeamDashboard() {
  const { user, isSuperadmin } = useAuth();
  const {
    data: dbUsers = [],
    isLoading: isUsersLoading,
    refetch: refetchDbUsers,
  } = useGetUsersQuery();
  const [updateStaff] = useUpdateStaffMutation();
  const [profiles, setProfiles] = useState<ProfileCompletionData[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState('All');
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [mainView, setMainView] = useState<'table' | 'onboarding'>('table');

  // Modals state
  const [selectedProfile, setSelectedProfile] = useState<ProfileCompletionData | null>(null);
  const [isReviewOpen, setIsReviewOpen] = useState(false);
  const [reviewTab, setReviewTab] = useState<
    'overview' | 'personal' | 'bank' | 'identity' | 'employment' | 'education' | 'certifications'
  >('overview');

  // Request changes modal state
  const [isChangesModalOpen, setIsChangesModalOpen] = useState(false);
  const [changesNotes, setChangesNotes] = useState('');
  const [targetUserId, setTargetUserId] = useState<number | null>(null);

  // Assign Employee Profile Details (ID, Role, Department, Designation) modal state
  const [isAssignIdModalOpen, setIsAssignIdModalOpen] = useState(false);
  const [empIdInput, setEmpIdInput] = useState('');
  const [roleInput, setRoleInput] = useState('Employee');
  const [departmentInput, setDepartmentInput] = useState('');
  const [designationInput, setDesignationInput] = useState('');
  const [assignError, setAssignError] = useState('');
  const [isAssigning, setIsAssigning] = useState(false);

  const formConfig = useMemo(() => getFormConfiguration(), []);

  // Sync DB users list to local storage for persistence & cross-component access
  useEffect(() => {
    if (dbUsers && dbUsers.length > 0) {
      try {
        localStorage.setItem('aether_staff_list', JSON.stringify(dbUsers));
      } catch {}
    }
  }, [dbUsers]);

  // Current user info
  const userRole = user?.role || (isSuperadmin ? 'SuperAdmin' : 'Employee');
  const userName = user?.username || (user as any)?.name || 'HR Admin';
  const userEmail = user?.email || '';
  const normalizedUserRole = (userRole || '').toLowerCase().replace(/[\s_-]/g, '');
  const canAssignId =
    isSuperadmin ||
    ['superadmin', 'admin', 'hradmin', 'hr', 'hiringmanager', 'hiringteam'].includes(
      normalizedUserRole
    ) ||
    ['SuperAdmin', 'Admin', 'HrAdmin'].includes(userRole);

  // Initial sync from backend database and periodic polling
  useEffect(() => {
    syncProfilesFromBackend();
    const interval = setInterval(() => {
      syncProfilesFromBackend();
    }, 8000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (dbUsers && dbUsers.length > 0) {
      syncProfilesFromBackend();
    }
  }, [dbUsers]);

  // Listen to cross-module employee profile and invitation updates
  useEffect(() => {
    const handleUpdate = () => setRefreshTrigger((prev) => prev + 1);
    window.addEventListener('aether_employee_profiles_updated', handleUpdate);
    window.addEventListener('storage', handleUpdate);
    return () => {
      window.removeEventListener('aether_employee_profiles_updated', handleUpdate);
      window.removeEventListener('storage', handleUpdate);
    };
  }, []);

  // Load profiles from local storage
  useEffect(() => {
    const list = getAllEmployeeProfiles();
    setProfiles(list);
  }, [refreshTrigger]);

  // Merge database users with onboarding profiles so ALL DB users appear with their form status
  const combinedProfiles = useMemo<ProfileCompletionData[]>(() => {
    const list: ProfileCompletionData[] = [];
    const seenEmails = new Set<string>();
    const seenUserIds = new Set<string>();

    // 1. Process all registered users from database (/users)
    for (const dbUser of dbUsers) {
      if (!dbUser.email && !dbUser.id) continue;
      const emailLower = (dbUser.email || '').toLowerCase().trim();
      const userIdStr = String(dbUser.id);
      if (emailLower) seenEmails.add(emailLower);
      seenUserIds.add(userIdStr);

      // Match with existing onboarding profile if available
      const existingProfile = profiles.find(
        (p) =>
          String(p.userId) === userIdStr ||
          (Boolean(emailLower) && p.userEmail?.toLowerCase().trim() === emailLower)
      );

      if (existingProfile) {
        list.push({
          ...existingProfile,
          userId: typeof dbUser.id === 'number' ? dbUser.id : existingProfile.userId || Date.now(),
          userEmail: emailLower || existingProfile.userEmail,
          employeeId:
            existingProfile.employeeId &&
            existingProfile.employeeId !== 'N/A' &&
            existingProfile.employeeId !== 'NA'
              ? existingProfile.employeeId
              : dbUser.employee_id || dbUser.employee_code || undefined,
          role: existingProfile.role || dbUser.role || 'Employee',
          department: existingProfile.department || dbUser.department || '',
          designation: existingProfile.designation || dbUser.designation || '',
          personal: {
            ...existingProfile.personal,
            fullName:
              existingProfile.personal?.fullName ||
              dbUser.name ||
              dbUser.username ||
              'Unnamed Employee',
            email: emailLower || existingProfile.personal?.email || '',
            contactNumber:
              existingProfile.personal?.contactNumber || dbUser.contact_no || dbUser.phone || '',
          },
        });
      } else {
        // User registered in DB but hasn't submitted onboarding yet
        list.push({
          userId: typeof dbUser.id === 'number' ? dbUser.id : Date.now(),
          userEmail: emailLower,
          status: 'incomplete',
          employeeId: dbUser.employee_id || dbUser.employee_code,
          role: dbUser.role || 'Employee',
          department: dbUser.department || '',
          designation: dbUser.designation || '',
          completedSections: {},
          lastSavedAt: dbUser.join_date || dbUser.joinDate || new Date().toISOString(),
          personal: {
            fullName: dbUser.name || dbUser.username || 'Unnamed Employee',
            email: emailLower,
            contactNumber: dbUser.contact_no || dbUser.phone || '',
          },
        });
      }
    }

    // 2. Also preserve any local/seeded profiles not present in dbUsers (e.g., test candidates)
    for (const p of profiles) {
      const emailLower = (p.userEmail || '').toLowerCase().trim();
      const userIdStr = String(p.userId);
      if ((emailLower && seenEmails.has(emailLower)) || (userIdStr && seenUserIds.has(userIdStr))) {
        continue;
      }
      if (emailLower) seenEmails.add(emailLower);
      seenUserIds.add(userIdStr);
      list.push(p);
    }

    return list;
  }, [dbUsers, profiles]);

  // Keep selectedProfile fresh if list changes
  useEffect(() => {
    if (selectedProfile) {
      const fresh = combinedProfiles.find(
        (p) =>
          String(p.userId) === String(selectedProfile.userId) ||
          (Boolean(p.userEmail) &&
            p.userEmail.toLowerCase() === selectedProfile.userEmail?.toLowerCase())
      );
      if (fresh) setSelectedProfile(fresh);
    }
  }, [combinedProfiles]);

  const refreshList = () => {
    refetchDbUsers();
    setRefreshTrigger((prev) => prev + 1);
  };

  // Summary Metrics
  const metrics = useMemo(
    () => ({
      total: combinedProfiles.length,
      pending: combinedProfiles.filter((p) => p.status === 'submitted').length,
      changes: combinedProfiles.filter((p) => p.status === 'changes_required').length,
      approved: combinedProfiles.filter((p) => p.status === 'approved').length,
      assigned: combinedProfiles.filter((p) => p.status === 'id_assigned').length,
      onboarding: combinedProfiles.filter(
        (p) => p.status === 'in_progress' || p.status === 'incomplete'
      ).length,
    }),
    [combinedProfiles]
  );

  // Tab Filtering
  const filteredProfiles = useMemo(() => {
    return combinedProfiles.filter((p) => {
      const matchesSearch =
        p.personal?.fullName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.userEmail?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.employeeId?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.role?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.department?.toLowerCase().includes(searchQuery.toLowerCase());

      if (!matchesSearch) return false;

      if (activeTab === 'Pending Review') return p.status === 'submitted';
      if (activeTab === 'Changes Required') return p.status === 'changes_required';
      if (activeTab === 'Approved') return p.status === 'approved';
      if (activeTab === 'ID Assigned') return p.status === 'id_assigned';
      if (activeTab === 'Incomplete')
        return p.status === 'incomplete' || p.status === 'in_progress';
      return true;
    });
  }, [combinedProfiles, searchQuery, activeTab]);

  // Actions
  const handleApprove = (
    userId: number | string,
    employeeEmail?: string,
    employeeName?: string
  ) => {
    try {
      approveProfile(userId, userName, userEmail, userRole, employeeEmail, employeeName);
      showToast.success('Employee profile approved!');
      const fresh = getEmployeeProfile(userId);
      if (fresh) setSelectedProfile(fresh);
      refreshList();
    } catch (err) {
      console.error('Error in handleApprove:', err);
      showToast.error('Failed to approve profile.');
    }
  };

  const handleOpenChangesModal = (userId: number) => {
    setTargetUserId(userId);
    setChangesNotes('');
    setIsChangesModalOpen(true);
  };

  const handleSubmitChanges = () => {
    if (!targetUserId) return;
    if (!changesNotes.trim()) {
      showToast.error('Please provide details on what changes are needed.');
      return;
    }
    try {
      requestProfileChanges(targetUserId, userName, userEmail, userRole, changesNotes.trim());
      showToast.warning('Requested changes sent to employee.');
      setIsChangesModalOpen(false);
      refreshList();
    } catch (err) {
      console.error('Error in handleSubmitChanges:', err);
      showToast.error('Failed to request changes.');
    }
  };

  const handleOpenAssignIdModal = (profile: ProfileCompletionData) => {
    setSelectedProfile(profile);
    setEmpIdInput(profile.employeeId || `EMP-${String(profile.userId).padStart(4, '0')}`);
    setRoleInput(profile.role || 'Employee');
    setDepartmentInput(profile.department || '');
    setDesignationInput(profile.designation || '');
    setAssignError('');
    setIsAssignIdModalOpen(true);
  };

  const handleConfirmAssignId = async () => {
    if (!selectedProfile || isAssigning) return;
    if (!empIdInput.trim()) {
      setAssignError('Employee ID cannot be empty');
      return;
    }

    setIsAssigning(true);
    setAssignError('');

    try {
      const cleanId = empIdInput.trim();
      const cleanRole = roleInput.trim() || 'Employee';
      const cleanDept = departmentInput.trim();
      const cleanDesig = designationInput.trim();

      const result = assignEmployeeId(
        selectedProfile.userId,
        cleanId,
        userName,
        userEmail,
        userRole,
        selectedProfile.userEmail,
        selectedProfile.personal?.fullName,
        {
          role: cleanRole,
          department: cleanDept,
          designation: cleanDesig,
        }
      );

      if (result.success) {
        // Also persist to backend MySQL users table if userId exists
        try {
          const targetDbUser = dbUsers.find(
            (u) =>
              (selectedProfile.userEmail &&
                u.email?.toLowerCase().trim() === selectedProfile.userEmail.toLowerCase().trim()) ||
              String(u.id) === String(selectedProfile.userId)
          );
          const targetUserId = targetDbUser?.id || selectedProfile.userId;

          if (targetUserId) {
            await updateStaff({
              id: targetUserId,
              employee_id: cleanId,
              employee_code: cleanId,
              role: cleanRole as any,
              department: cleanDept,
              designation: cleanDesig,
            }).unwrap();

            if (typeof refetchDbUsers === 'function') {
              refetchDbUsers();
            }

            // Sync auth session if the assigned user is the currently logged-in user
            const savedUserRaw = localStorage.getItem('user');
            if (savedUserRaw) {
              try {
                const currentAuthUser = JSON.parse(savedUserRaw);
                if (
                  (currentAuthUser.email &&
                    selectedProfile.userEmail &&
                    currentAuthUser.email.toLowerCase() ===
                      selectedProfile.userEmail.toLowerCase()) ||
                  String(currentAuthUser.id) === String(targetUserId)
                ) {
                  const updatedAuthUser = {
                    ...currentAuthUser,
                    employee_id: cleanId,
                    employee_code: cleanId,
                    employeeId: cleanId,
                    role: cleanRole,
                    department: cleanDept,
                    designation: cleanDesig,
                  };
                  localStorage.setItem('user', JSON.stringify(updatedAuthUser));
                  window.dispatchEvent(
                    new CustomEvent('auth_user_updated', { detail: updatedAuthUser })
                  );
                  window.dispatchEvent(
                    new CustomEvent('aether_user_updated', { detail: updatedAuthUser })
                  );
                }
              } catch {}
            }
          }
        } catch (apiErr) {
          console.warn('Backend updateStaff note:', apiErr);
        }

        showToast.success(
          `Employee ID "${cleanId}", Role "${cleanRole}" and details assigned successfully!`
        );
        setIsAssignIdModalOpen(false);
        const fresh = getEmployeeProfile(selectedProfile.userId);
        if (fresh) setSelectedProfile(fresh);
        refreshList();
      } else {
        const errMsg = result.error || 'Failed to assign employee details.';
        setAssignError(errMsg);
        showToast.error(errMsg);
      }
    } catch (err: any) {
      console.error('Error in handleConfirmAssignId:', err);
      const msg = err?.data?.message || err?.message || 'An unexpected error occurred.';
      setAssignError(msg);
      showToast.error(msg);
    } finally {
      setIsAssigning(false);
    }
  };

  // Ant Design Table Columns
  const columns: ColumnsType<ProfileCompletionData> = [
    {
      title: 'Employee',
      key: 'employee',
      render: (_, record) => (
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full overflow-hidden bg-primary/10 flex items-center justify-center shrink-0 border border-border-subtle">
            {record.profilePictureUrl ? (
              <img src={record.profilePictureUrl} alt="" className="w-full h-full object-cover" />
            ) : (
              <User size={18} className="text-primary" />
            )}
          </div>
          <div>
            <div className="font-bold text-foreground text-sm">
              {record.personal?.fullName || 'Unnamed Employee'}
            </div>
            <div className="text-xs text-muted">{record.userEmail}</div>
            <div className="flex flex-wrap items-center gap-1.5 mt-1">
              {record.role && (
                <span className="text-[10px] font-bold px-2 py-0.5 rounded-md bg-primary/10 text-primary border border-primary/20">
                  {record.role}
                </span>
              )}
              {record.department && (
                <span className="text-[10px] font-semibold px-2 py-0.5 rounded-md bg-surface-subtle text-muted border border-border-subtle">
                  {record.department}
                </span>
              )}
            </div>
          </div>
        </div>
      ),
    },
    {
      title: 'Status',
      key: 'status',
      render: (_, record) => {
        const conf = STATUS_MAP[record.status] || STATUS_MAP.incomplete;
        const Icon = conf.icon;
        return (
          <span
            className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${conf.bg}`}
            style={{ lineHeight: '1' }}>
            <Icon size={12} style={{ display: 'block', flexShrink: 0 }} />
            <span>{conf.label}</span>
          </span>
        );
      },
    },
    {
      title: 'Completion',
      key: 'completion',
      render: (_, record) => {
        const pct = calculateCompletionPercentage(record, formConfig);
        const totalSections = formConfig.filter((s) => !s.hidden).length;
        const completedCount = formConfig.filter(
          (s) => !s.hidden && record.completedSections?.[s.id]
        ).length;
        return (
          <div className="w-36">
            <div className="flex justify-between items-center text-xs mb-1">
              <span className="font-semibold text-foreground">{pct}%</span>
              <span className="text-[10px] text-muted">
                {completedCount}/{totalSections} secs
              </span>
            </div>
            <div className="h-1.5 w-full bg-surface-subtle rounded-full overflow-hidden">
              <div
                className={`h-full transition-all duration-500 ${
                  pct === 100 ? 'bg-success' : pct > 50 ? 'bg-primary' : 'bg-warning'
                }`}
                style={{ width: `${pct}%` }}
              />
            </div>
            {/* Mini section dots */}
            <div className="flex gap-1 mt-1.5">
              {formConfig
                .filter((s) => !s.hidden)
                .map((section) => (
                  <div
                    key={section.id}
                    title={section.label}
                    className={`w-2 h-2 rounded-full transition-colors ${
                      record.completedSections?.[section.id]
                        ? 'bg-success'
                        : 'bg-surface-subtle border border-border-subtle'
                    }`}
                  />
                ))}
            </div>
          </div>
        );
      },
    },
    {
      title: 'Employee ID',
      key: 'employeeId',
      render: (_, record) =>
        record.employeeId ? (
          <span className="inline-flex items-center gap-1 font-mono text-xs font-bold text-primary bg-primary/10 px-2.5 py-1 rounded-lg border border-primary/20">
            <KeyRound size={12} />
            {record.employeeId}
          </span>
        ) : (
          <span className="text-xs text-muted italic">Not Assigned</span>
        ),
    },
    {
      title: 'Last Updated',
      key: 'lastSavedAt',
      render: (_, record) => (
        <span className="text-xs text-muted">
          {record.lastSavedAt ? new Date(record.lastSavedAt).toLocaleDateString() : '—'}
        </span>
      ),
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => {
              setSelectedProfile(record);
              setReviewTab('overview');
              setIsReviewOpen(true);
            }}
            className="px-3 py-1.5 rounded-xl border border-border-subtle bg-white hover:bg-surface-subtle text-foreground text-xs font-bold transition-all flex items-center gap-1">
            <Eye size={13} />
            Review
          </button>

          {(record.status === 'submitted' ||
            record.status === 'changes_required' ||
            record.status === 'in_progress') && (
            <button
              type="button"
              onClick={() =>
                handleApprove(record.userId, record.userEmail, record.personal?.fullName)
              }
              className="px-3 py-1.5 rounded-xl bg-success text-white hover:bg-success/90 text-xs font-bold transition-all flex items-center gap-1 shadow-xs">
              <CheckCircle2 size={13} />
              Approve
            </button>
          )}

          {record.status === 'approved' && (
            <span className="px-2.5 py-1 rounded-xl bg-success/10 text-success text-[11px] font-bold flex items-center gap-1 border border-success/20">
              <CheckCircle2 size={12} />
              Approved
            </span>
          )}

          {canAssignId && (
            <button
              type="button"
              onClick={() => handleOpenAssignIdModal(record)}
              className="px-3 py-1.5 rounded-xl bg-primary text-white hover:bg-primary/90 text-xs font-bold transition-all flex items-center gap-1 shadow-xs">
              <KeyRound size={13} />
              {record.employeeId ? 'Edit ID & Role' : 'Assign ID & Role'}
            </button>
          )}
        </div>
      ),
    },
  ];

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <PageHeader
        title="Hiring & Onboarding Management"
        subtitle="Review employee profile submissions, track onboarding progress, and assign official Employee IDs."
        actions={
          <div className="flex items-center gap-3">
            <Link
              to="/hiring-team/form-builder"
              className="px-4 py-2 rounded-xl bg-surface-subtle border border-border-subtle text-foreground hover:bg-white text-xs font-bold transition-all flex items-center gap-1.5">
              <Building size={14} className="text-primary" />
              Configure Form Fields
            </Link>
            <button
              type="button"
              onClick={refreshList}
              className="p-2.5 rounded-xl border border-border-subtle bg-white hover:bg-surface-subtle text-muted hover:text-foreground transition-all"
              title="Refresh profiles">
              <RefreshCw size={15} />
            </button>
          </div>
        }
      />

      {/* Summary KPI Cards */}
      <div className="grid grid-cols-2 md:grid-cols-6 gap-4">
        <div className="p-5 rounded-2xl bg-surface-subtle border border-border-subtle">
          <div className="text-xs font-bold text-muted uppercase tracking-wider mb-1">Total</div>
          <div className="text-2xl font-black text-foreground">{metrics.total}</div>
        </div>
        <div
          className={`p-5 rounded-2xl border cursor-pointer transition-all ${mainView === 'onboarding' ? 'bg-warning/10 border-warning/30 ring-2 ring-warning/20' : 'bg-warning/5 border-warning/20 hover:bg-warning/10'}`}
          onClick={() => setMainView(mainView === 'onboarding' ? 'table' : 'onboarding')}>
          <div className="text-xs font-bold text-warning uppercase tracking-wider mb-1 flex items-center gap-1.5">
            <TrendingUp size={12} />
            In Onboarding
          </div>
          <div className="text-2xl font-black text-warning">{metrics.onboarding}</div>
          <div className="text-[10px] text-warning/70 mt-0.5">
            {mainView === 'onboarding' ? '▲ Click to hide' : 'Click to view'}
          </div>
        </div>
        <div className="p-5 rounded-2xl bg-info/5 border border-info/20">
          <div className="text-xs font-bold text-info uppercase tracking-wider mb-1 flex items-center gap-1.5">
            <Clock size={12} />
            Pending Review
          </div>
          <div className="text-2xl font-black text-info">{metrics.pending}</div>
        </div>
        <div className="p-5 rounded-2xl bg-warning/5 border border-warning/20">
          <div className="text-xs font-bold text-warning uppercase tracking-wider mb-1 flex items-center gap-1.5">
            <AlertCircle size={12} />
            Changes Needed
          </div>
          <div className="text-2xl font-black text-warning">{metrics.changes}</div>
        </div>
        <div className="p-5 rounded-2xl bg-success/5 border border-success/20">
          <div className="text-xs font-bold text-success uppercase tracking-wider mb-1 flex items-center gap-1.5">
            <CheckCircle2 size={12} />
            Approved
          </div>
          <div className="text-2xl font-black text-success">{metrics.approved}</div>
        </div>
        <div className="p-5 rounded-2xl bg-primary/5 border border-primary/20">
          <div className="text-xs font-bold text-primary uppercase tracking-wider mb-1 flex items-center gap-1.5">
            <KeyRound size={12} />
            ID Assigned
          </div>
          <div className="text-2xl font-black text-primary">{metrics.assigned}</div>
        </div>
      </div>

      {/* ── ONBOARDING PROGRESS PANEL ── */}
      {mainView === 'onboarding' && (
        <div className="bg-white rounded-3xl border border-border-subtle overflow-hidden shadow-xs">
          <div className="px-6 py-4 border-b border-border-subtle flex items-center justify-between">
            <div className="flex items-center gap-2">
              <TrendingUp size={16} className="text-warning" />
              <h2 className="text-sm font-black text-foreground">Live Onboarding Progress</h2>
              <span className="text-[10px] font-bold text-muted bg-surface-subtle border border-border-subtle px-2 py-0.5 rounded-full">
                {metrics.onboarding + metrics.pending + metrics.changes} employees
              </span>
            </div>
            <div className="text-xs text-muted">Click any row to see filled section details</div>
          </div>
          <div className="p-5">
            <OnboardingProgressPanel profiles={combinedProfiles} formConfig={formConfig} />
          </div>
        </div>
      )}

      {/* Controls & Search */}
      <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-4">
        <Tabs
          items={[
            'All',
            'Pending Review',
            'Changes Required',
            'Approved',
            'ID Assigned',
            'Incomplete',
          ]}
          activeItem={activeTab}
          onItemChange={setActiveTab}
        />
        <div className="relative min-w-[280px]">
          <Search size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-muted" />
          <input
            type="text"
            placeholder="Search by name, email, ID..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-4 py-2.5 rounded-xl border border-border-subtle bg-white text-xs text-foreground placeholder:text-muted focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all"
          />
        </div>
      </div>

      {/* Main Table */}
      <div className="bg-white rounded-3xl border border-border-subtle overflow-hidden shadow-xs">
        <Table
          scroll={{ x: 'max-content' }}
          columns={columns}
          dataSource={filteredProfiles}
          rowKey="userId"
          loading={isUsersLoading}
          pagination={{ pageSize: 10, showSizeChanger: true }}
          locale={{ emptyText: 'No employee profile submissions found' }}
        />
      </div>

      {/* ── DETAIL REVIEW DIALOG ── */}
      <Dialog
        visible={isReviewOpen}
        onHide={() => setIsReviewOpen(false)}
        width={900}
        header={
          <div className="flex items-center justify-between pr-8">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-primary/10 overflow-hidden flex items-center justify-center">
                {selectedProfile?.profilePictureUrl ? (
                  <img
                    src={selectedProfile.profilePictureUrl}
                    alt=""
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <User size={20} className="text-primary" />
                )}
              </div>
              <div>
                <h3 className="text-base font-black text-foreground">
                  {selectedProfile?.personal?.fullName || 'Employee Profile'}
                </h3>
                <p className="text-xs text-muted">{selectedProfile?.userEmail}</p>
              </div>
            </div>
            {selectedProfile && (
              <span
                className={`px-3 py-1 rounded-full text-xs font-bold border ${STATUS_MAP[selectedProfile.status]?.bg}`}>
                {STATUS_MAP[selectedProfile.status]?.label}
              </span>
            )}
          </div>
        }>
        {selectedProfile && (
          <div className="space-y-6 pt-2">
            {/* Review Section Navigation */}
            <div className="flex items-center gap-2 border-b border-border-subtle pb-3 overflow-x-auto">
              {[
                { id: 'overview', label: 'Overview', icon: ListChecks },
                { id: 'personal', label: 'Personal & Contact', icon: User },
                { id: 'bank', label: 'Bank Details', icon: CreditCard },
                { id: 'identity', label: 'Identity Documents', icon: FileText },
                { id: 'employment', label: 'Employment History', icon: Briefcase },
                { id: 'education', label: 'Education', icon: GraduationCap },
                { id: 'certifications', label: 'Certifications', icon: Award },
              ].map((tab) => {
                const Icon = tab.icon;
                const isActive = reviewTab === tab.id;
                // Mark completion status for non-overview tabs
                const isDone = tab.id !== 'overview' && selectedProfile.completedSections?.[tab.id];
                return (
                  <button
                    key={tab.id}
                    type="button"
                    onClick={() => setReviewTab(tab.id as any)}
                    className={`flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs font-bold whitespace-nowrap transition-all relative ${
                      isActive
                        ? 'bg-primary text-white shadow-xs'
                        : 'bg-surface-subtle text-muted hover:text-foreground'
                    }`}>
                    <Icon size={14} />
                    {tab.label}
                    {tab.id !== 'overview' && (
                      <span
                        className={`w-1.5 h-1.5 rounded-full ${isDone ? 'bg-success' : 'bg-muted/40'} ${isActive ? 'bg-white/50' : ''}`}
                      />
                    )}
                  </button>
                );
              })}
            </div>

            {/* ── Tab: Overview (Section Completion Summary) ── */}
            {reviewTab === 'overview' && (
              <div className="space-y-5">
                {/* Completion progress */}
                <div className="p-5 rounded-2xl bg-surface-subtle border border-border-subtle">
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-sm font-bold text-foreground">
                      Overall Profile Completion
                    </span>
                    <span className="text-xl font-black text-primary">
                      {calculateCompletionPercentage(selectedProfile, formConfig)}%
                    </span>
                  </div>
                  <div className="h-2.5 w-full bg-white rounded-full overflow-hidden border border-border-subtle">
                    <div
                      className="h-full bg-gradient-to-r from-primary to-primary/70 rounded-full transition-all duration-700"
                      style={{
                        width: `${calculateCompletionPercentage(selectedProfile, formConfig)}%`,
                      }}
                    />
                  </div>
                </div>

                {/* Section-by-section status */}
                <div>
                  <div className="text-xs font-bold text-muted uppercase tracking-wider mb-3 flex items-center gap-1.5">
                    <ListChecks size={13} />
                    Section Completion Status
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    {formConfig
                      .filter((s) => !s.hidden)
                      .sort((a, b) => a.order - b.order)
                      .map((section) => {
                        const SectionIcon = SECTION_ICON_MAP[section.id] || FileText;
                        const done = !!selectedProfile.completedSections?.[section.id];
                        return (
                          <div
                            key={section.id}
                            onClick={() => setReviewTab(section.id as any)}
                            className={`flex items-center gap-3 p-3.5 rounded-2xl border cursor-pointer transition-all hover:shadow-xs ${
                              done
                                ? 'bg-success/5 border-success/25'
                                : 'bg-surface-subtle border-border-subtle'
                            }`}>
                            <div
                              className={`w-8 h-8 rounded-xl flex items-center justify-center ${done ? 'bg-success/15' : 'bg-surface-subtle border border-border-subtle'}`}>
                              <SectionIcon
                                size={15}
                                className={done ? 'text-success' : 'text-muted'}
                              />
                            </div>
                            <div className="flex-1 min-w-0">
                              <div className="text-xs font-bold text-foreground">
                                {section.label}
                              </div>
                              <div className="text-[10px] text-muted">{section.description}</div>
                            </div>
                            <div className="shrink-0">
                              {done ? (
                                <CheckCircle2 size={16} className="text-success" />
                              ) : (
                                <Clock size={16} className="text-muted" />
                              )}
                            </div>
                          </div>
                        );
                      })}
                  </div>
                </div>

                {/* Key data summary */}
                <div>
                  <div className="text-xs font-bold text-muted uppercase tracking-wider mb-3">
                    Quick Data Summary
                  </div>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                    {[
                      { label: 'Full Name', value: selectedProfile.personal?.fullName },
                      { label: 'Assigned ID', value: selectedProfile.employeeId },
                      { label: 'System Role', value: selectedProfile.role || 'Employee' },
                      { label: 'Department', value: selectedProfile.department || 'Not Assigned' },
                      { label: 'Designation', value: selectedProfile.designation || '—' },
                      { label: 'Contact', value: selectedProfile.personal?.contactNumber },
                      { label: 'Date of Birth', value: selectedProfile.personal?.dateOfBirth },
                      { label: 'Gender', value: selectedProfile.personal?.gender },
                      { label: 'Bank', value: selectedProfile.bank?.bankName },
                      { label: 'Account Type', value: selectedProfile.bank?.accountType },
                      { label: 'PAN Number', value: selectedProfile.identity?.panNumber },
                      {
                        label: 'Documents',
                        value: selectedProfile.documents?.length
                          ? `${selectedProfile.documents.length} file(s)`
                          : 'None',
                      },
                      {
                        label: 'Employment Entries',
                        value: selectedProfile.employment?.length
                          ? `${selectedProfile.employment.length} jobs`
                          : 'None',
                      },
                      {
                        label: 'Education Entries',
                        value: selectedProfile.education?.length
                          ? `${selectedProfile.education.length} qualifications`
                          : 'None',
                      },
                      {
                        label: 'Certifications',
                        value: selectedProfile.certifications?.length
                          ? `${selectedProfile.certifications.length} certs`
                          : 'None',
                      },
                      {
                        label: 'Submitted At',
                        value: selectedProfile.submittedAt
                          ? new Date(selectedProfile.submittedAt).toLocaleString()
                          : 'Not yet',
                      },
                    ].map((item) => (
                      <div
                        key={item.label}
                        className="p-3 rounded-xl bg-surface-subtle border border-border-subtle">
                        <div className="text-[10px] font-bold text-muted uppercase mb-0.5">
                          {item.label}
                        </div>
                        <div className="text-xs font-semibold text-foreground">
                          {item.value || '—'}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Review notes if any */}
                {selectedProfile.reviewNotes && (
                  <div className="p-4 rounded-2xl bg-warning/5 border border-warning/20">
                    <div className="text-[10px] font-bold text-warning uppercase mb-1 flex items-center gap-1.5">
                      <AlertCircle size={11} />
                      Revision Notes (sent to employee)
                    </div>
                    <div className="text-xs text-foreground">{selectedProfile.reviewNotes}</div>
                  </div>
                )}
              </div>
            )}

            {/* ── Tab: Personal ── */}
            {reviewTab === 'personal' && (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">Full Name</div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.personal?.fullName || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">Contact Phone</div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.personal?.contactNumber || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">Email</div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.personal?.email || selectedProfile.userEmail || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">
                      Date of Birth / Gender
                    </div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.personal?.dateOfBirth || '—'} (
                      {selectedProfile.personal?.gender || '—'})
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">
                      Nationality / Marital Status
                    </div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.personal?.nationality || '—'} /{' '}
                      {selectedProfile.personal?.maritalStatus || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">
                      Alternate Contact
                    </div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.personal?.alternateContact || '—'}
                    </div>
                  </div>
                  <div className="col-span-2 p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">
                      Current Address
                    </div>
                    <div className="text-sm text-foreground mt-1">
                      {selectedProfile.personal?.currentAddress || '—'}
                    </div>
                  </div>
                  <div className="col-span-2 p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">
                      Permanent Address
                    </div>
                    <div className="text-sm text-foreground mt-1">
                      {selectedProfile.personal?.permanentAddress || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">
                      Emergency Contact Name
                    </div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.personal?.emergencyContactName || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">
                      Emergency Contact Phone
                    </div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.personal?.emergencyContactPhone || '—'}
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* ── Tab: Bank ── */}
            {reviewTab === 'bank' && (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">
                      Account Holder Name
                    </div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.bank?.accountHolderName || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">Bank Name</div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.bank?.bankName || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">Account Number</div>
                    <div className="text-sm font-mono font-semibold text-foreground mt-1">
                      {selectedProfile.bank?.accountNumber
                        ? `••••••••${selectedProfile.bank.accountNumber.slice(-4)}`
                        : '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">IFSC Code</div>
                    <div className="text-sm font-mono font-semibold text-foreground mt-1">
                      {selectedProfile.bank?.ifscCode || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">Branch Name</div>
                    <div className="text-sm font-semibold text-foreground mt-1">
                      {selectedProfile.bank?.branchName || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">Account Type</div>
                    <div className="text-sm font-semibold text-foreground mt-1 capitalize">
                      {selectedProfile.bank?.accountType || '—'}
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* ── Tab: Identity ── */}
            {reviewTab === 'identity' && (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">PAN Number</div>
                    <div className="text-sm font-mono font-semibold text-foreground mt-1">
                      {selectedProfile.identity?.panNumber || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">Aadhaar Number</div>
                    <div className="text-sm font-mono font-semibold text-foreground mt-1">
                      {selectedProfile.identity?.aadhaarNumber
                        ? `•••• •••• ${selectedProfile.identity.aadhaarNumber.slice(-4)}`
                        : '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">
                      Passport Number
                    </div>
                    <div className="text-sm font-mono font-semibold text-foreground mt-1">
                      {selectedProfile.identity?.passportNumber || '—'}
                    </div>
                  </div>
                  <div className="p-4 rounded-2xl bg-surface-subtle">
                    <div className="text-[10px] font-bold text-muted uppercase">
                      Driving License
                    </div>
                    <div className="text-sm font-mono font-semibold text-foreground mt-1">
                      {selectedProfile.identity?.drivingLicense || '—'}
                    </div>
                  </div>
                </div>

                <div className="pt-2">
                  <div className="text-xs font-bold text-foreground mb-3">
                    Uploaded Identity Documents:
                  </div>
                  {selectedProfile.documents && selectedProfile.documents.length > 0 ? (
                    <div className="space-y-2">
                      {selectedProfile.documents.map((doc) => (
                        <div
                          key={doc.id}
                          className="p-3 rounded-xl border border-border-subtle bg-white flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            <FileText size={16} className="text-primary" />
                            <div>
                              <div className="text-xs font-bold text-foreground">
                                {doc.fileName || doc.label}
                              </div>
                              <div className="text-[10px] text-muted capitalize">
                                {doc.type} •{' '}
                                {doc.fileSize ? `${(doc.fileSize / 1024).toFixed(0)} KB` : ''} •
                                Uploaded {new Date(doc.uploadedAt).toLocaleDateString()}
                              </div>
                            </div>
                          </div>
                          <div className="flex items-center gap-2">
                            <span
                              className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${
                                doc.status === 'verified'
                                  ? 'bg-success/10 border-success/25 text-success'
                                  : doc.status === 'rejected'
                                    ? 'bg-error/10 border-error/25 text-error'
                                    : 'bg-surface-subtle border-border-subtle text-muted'
                              }`}>
                              {doc.status}
                            </span>
                            <a
                              href={doc.url}
                              target="_blank"
                              rel="noreferrer"
                              className="px-3 py-1 rounded-lg bg-surface-subtle text-primary hover:bg-primary/10 text-xs font-bold transition-all flex items-center gap-1">
                              <ExternalLink size={12} />
                              View
                            </a>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="text-xs text-muted italic p-4 bg-surface-subtle rounded-xl text-center">
                      No documents attached yet.
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* ── Tab: Employment ── */}
            {reviewTab === 'employment' && (
              <div className="space-y-3">
                {selectedProfile.employment && selectedProfile.employment.length > 0 ? (
                  selectedProfile.employment.map((emp, i) => (
                    <div
                      key={emp.id || i}
                      className="p-4 rounded-2xl bg-surface-subtle border border-border-subtle space-y-2">
                      <div className="flex justify-between items-start">
                        <div>
                          <div className="text-sm font-bold text-foreground">{emp.designation}</div>
                          <div className="text-xs text-muted">{emp.employer}</div>
                        </div>
                        <span className="text-[11px] font-mono text-muted">
                          {emp.startDate} — {emp.isCurrent ? 'Present' : emp.endDate}
                        </span>
                      </div>
                      {emp.salary && <div className="text-xs text-muted">Salary: {emp.salary}</div>}
                      {emp.responsibilities && (
                        <div className="text-xs text-muted border-t border-border-subtle pt-2">
                          {emp.responsibilities}
                        </div>
                      )}
                    </div>
                  ))
                ) : (
                  <div className="text-xs text-muted italic p-4 bg-surface-subtle rounded-xl text-center">
                    No previous employment recorded.
                  </div>
                )}
              </div>
            )}

            {/* ── Tab: Education ── */}
            {reviewTab === 'education' && (
              <div className="space-y-3">
                {selectedProfile.education && selectedProfile.education.length > 0 ? (
                  selectedProfile.education.map((edu, i) => (
                    <div
                      key={edu.id || i}
                      className="p-4 rounded-2xl bg-surface-subtle border border-border-subtle space-y-1">
                      <div className="flex justify-between items-start">
                        <div>
                          <div className="text-sm font-bold text-foreground">
                            {edu.degree}
                            {edu.field ? ` in ${edu.field}` : ''}
                          </div>
                          <div className="text-xs text-muted">{edu.institution}</div>
                        </div>
                        <span className="text-[11px] font-mono text-muted">
                          {edu.startYear} – {edu.endYear}
                        </span>
                      </div>
                      {edu.grade && (
                        <div className="text-xs text-muted">Grade / Percentage: {edu.grade}</div>
                      )}
                    </div>
                  ))
                ) : (
                  <div className="text-xs text-muted italic p-4 bg-surface-subtle rounded-xl text-center">
                    No education history recorded.
                  </div>
                )}
              </div>
            )}

            {/* ── Tab: Certifications ── */}
            {reviewTab === 'certifications' && (
              <div className="space-y-3">
                {selectedProfile.certifications && selectedProfile.certifications.length > 0 ? (
                  selectedProfile.certifications.map((cert, i) => (
                    <div
                      key={cert.id || i}
                      className="p-4 rounded-2xl bg-surface-subtle border border-border-subtle space-y-1">
                      <div className="flex justify-between items-start">
                        <div>
                          <div className="text-sm font-bold text-foreground">{cert.title}</div>
                          <div className="text-xs text-muted">{cert.issuingOrganization}</div>
                        </div>
                        <span className="text-[11px] font-mono text-muted">
                          Issued: {cert.issueDate}
                        </span>
                      </div>
                      {cert.credentialId && (
                        <div className="text-xs text-muted">Credential ID: {cert.credentialId}</div>
                      )}
                      {cert.expiryDate && (
                        <div className="text-xs text-muted">Expires: {cert.expiryDate}</div>
                      )}
                    </div>
                  ))
                ) : (
                  <div className="text-xs text-muted italic p-4 bg-surface-subtle rounded-xl text-center">
                    No certifications recorded.
                  </div>
                )}
              </div>
            )}

            {/* Action Bar inside Dialog */}
            <div className="border-t border-border-subtle pt-4 flex items-center justify-between">
              <div>
                {selectedProfile.employeeId && (
                  <span className="text-xs font-bold text-primary">
                    Assigned ID: {selectedProfile.employeeId}
                  </span>
                )}
              </div>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => handleOpenChangesModal(selectedProfile.userId)}
                  className="px-4 py-2 rounded-xl border border-warning/30 bg-warning/5 text-warning hover:bg-warning/10 text-xs font-bold transition-all flex items-center gap-1.5">
                  <AlertCircle size={14} />
                  Request Revisions
                </button>
                {selectedProfile.status !== 'approved' &&
                selectedProfile.status !== 'id_assigned' ? (
                  <button
                    type="button"
                    onClick={() =>
                      handleApprove(
                        selectedProfile.userId,
                        selectedProfile.userEmail,
                        selectedProfile.personal?.fullName
                      )
                    }
                    className="px-4 py-2 rounded-xl bg-success text-white hover:bg-success/90 text-xs font-bold transition-all flex items-center gap-1.5 shadow-xs">
                    <CheckCircle2 size={14} />
                    Approve Profile
                  </button>
                ) : (
                  <span className="px-3 py-2 rounded-xl bg-success/10 text-success border border-success/20 text-xs font-bold flex items-center gap-1.5">
                    <CheckCircle2 size={14} />
                    Approved
                  </span>
                )}
                {canAssignId && (
                  <button
                    type="button"
                    onClick={() => handleOpenAssignIdModal(selectedProfile)}
                    className="px-4 py-2 rounded-xl bg-primary text-white hover:bg-primary/90 text-xs font-bold transition-all flex items-center gap-1.5 shadow-xs">
                    <KeyRound size={14} />
                    {selectedProfile.employeeId ? 'Edit ID & Role' : 'Assign ID & Role'}
                  </button>
                )}
              </div>
            </div>
          </div>
        )}
      </Dialog>

      {/* ── REQUEST CHANGES MODAL ── */}
      <Dialog
        visible={isChangesModalOpen}
        onHide={() => setIsChangesModalOpen(false)}
        width={500}
        header={<h3 className="text-base font-black text-foreground">Request Profile Changes</h3>}>
        <div className="space-y-4 pt-2">
          <p className="text-xs text-muted">
            Explain what documents or fields the employee needs to update or re-upload. The employee
            will see this message upon logging in.
          </p>
          <div>
            <label className="block text-xs font-bold text-foreground mb-1 uppercase tracking-wider">
              Feedback & Correction Instructions *
            </label>
            <textarea
              rows={4}
              value={changesNotes}
              onChange={(e) => setChangesNotes(e.target.value)}
              placeholder="e.g. Please upload a clear photo of your PAN card, and verify your bank account number."
              className="w-full px-4 py-3 rounded-xl border border-border-subtle text-sm text-foreground placeholder:text-muted focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary"
            />
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <button
              type="button"
              onClick={() => setIsChangesModalOpen(false)}
              className="px-4 py-2 rounded-xl border border-border-subtle bg-white text-foreground text-xs font-bold">
              Cancel
            </button>
            <button
              type="button"
              onClick={handleSubmitChanges}
              className="px-5 py-2 rounded-xl bg-warning text-white hover:bg-warning/90 text-xs font-bold shadow-xs flex items-center gap-1.5">
              <Send size={13} />
              Send to Employee
            </button>
          </div>
        </div>
      </Dialog>

      {/* ── ASSIGN OFFICIAL PROFILE DETAILS (ID, ROLE, DEPARTMENT, DESIGNATION) MODAL ── */}
      <Dialog
        visible={isAssignIdModalOpen}
        onHide={() => setIsAssignIdModalOpen(false)}
        width={560}
        header={
          <div className="flex items-center gap-2">
            <KeyRound size={18} className="text-primary" />
            <h3 className="text-base font-black text-foreground">
              {selectedProfile?.employeeId
                ? 'Manage Official Profile & Role'
                : 'Assign Official ID & Role'}
            </h3>
          </div>
        }>
        <div className="space-y-4 pt-2">
          {/* Target employee summary card */}
          {selectedProfile && (
            <div className="p-3.5 rounded-2xl bg-surface-subtle border border-border-subtle flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-primary/10 overflow-hidden flex items-center justify-center shrink-0 border border-primary/20">
                {selectedProfile.profilePictureUrl ? (
                  <img
                    src={selectedProfile.profilePictureUrl}
                    alt=""
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <User size={18} className="text-primary" />
                )}
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-bold text-foreground truncate">
                  {selectedProfile.personal?.fullName || 'Unnamed Employee'}
                </div>
                <div className="text-xs text-muted truncate">{selectedProfile.userEmail}</div>
              </div>
              <span
                className={`shrink-0 px-2.5 py-0.5 rounded-full text-[10px] font-bold border ${STATUS_MAP[selectedProfile.status]?.bg || 'bg-surface-subtle'}`}>
                {STATUS_MAP[selectedProfile.status]?.label || selectedProfile.status}
              </span>
            </div>
          )}

          <div className="p-3 rounded-2xl bg-primary/5 border border-primary/20 flex items-center gap-3">
            <div className="text-xs text-primary leading-relaxed">
              <strong>Role Verified:</strong> You are authorized ({userRole}) to assign or update
              official employee identifiers, system roles, and department affiliations.
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-bold text-foreground mb-1 uppercase tracking-wider">
                Official Employee ID *
              </label>
              <input
                type="text"
                value={empIdInput}
                onChange={(e) => {
                  setEmpIdInput(e.target.value);
                  setAssignError('');
                }}
                placeholder="e.g. EMP-0042 or ARX-01"
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-subtle font-mono text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-foreground mb-1 uppercase tracking-wider">
                System Role *
              </label>
              <select
                value={roleInput}
                onChange={(e) => setRoleInput(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-subtle text-xs font-semibold text-foreground bg-white focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary">
                {AVAILABLE_ROLES.map((r) => (
                  <option key={r} value={r}>
                    {r}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-bold text-foreground mb-1 uppercase tracking-wider">
                Department
              </label>
              <select
                value={departmentInput}
                onChange={(e) => setDepartmentInput(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-subtle text-xs font-semibold text-foreground bg-white focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary">
                <option value="">-- Select Department --</option>
                {AVAILABLE_DEPTS.map((d) => (
                  <option key={d} value={d}>
                    {d}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-bold text-foreground mb-1 uppercase tracking-wider">
                Designation / Job Title
              </label>
              <input
                type="text"
                value={designationInput}
                onChange={(e) => setDesignationInput(e.target.value)}
                placeholder="e.g. Frontend Developer"
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-subtle text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary"
              />
            </div>
          </div>

          {assignError && <p className="text-xs text-error font-medium">{assignError}</p>}

          <div className="flex justify-end gap-2 pt-2">
            <button
              type="button"
              onClick={() => setIsAssignIdModalOpen(false)}
              className="px-4 py-2 rounded-xl border border-border-subtle bg-white text-foreground text-xs font-bold hover:bg-surface-subtle transition-all">
              Cancel
            </button>
            <button
              type="button"
              disabled={isAssigning}
              onClick={handleConfirmAssignId}
              className="px-5 py-2 rounded-xl bg-primary text-white hover:bg-primary/90 text-xs font-bold shadow-xs flex items-center gap-1.5 disabled:opacity-50 disabled:cursor-not-allowed transition-all">
              <CheckCircle2 size={13} />
              {isAssigning ? 'Saving Profile...' : 'Confirm & Save Details'}
            </button>
          </div>
        </div>
      </Dialog>
    </div>
  );
}

import { lazy, Suspense, useMemo } from 'react';
import { Route, Routes, Navigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import { useGetMyPermissionsQuery } from '@/store/api/permissionSlice';
import { extractUserRoles, isUserSuperadmin } from '@/utils/rbac';

const BlogsModule = lazy(() => import('@/pages/blogs'));
const Dashboard = lazy(() => import('@/pages/dashboard/Dashboard'));
const EventsModule = lazy(() => import('@/pages/events'));
const GalleryModule = lazy(() => import('@/pages/gallery'));
const CareersModule = lazy(() => import('@/pages/careers'));
const StaffModule = lazy(() => import('@/pages/staff'));
const CheckInModule = lazy(() => import('@/pages/checkin'));
const AttendanceModule = lazy(() => import('@/pages/calendar'));
const FinanceModule = lazy(() => import('@/pages/finance'));
const GrievanceModule = lazy(() => import('@/pages/grievances'));
const AnalyticsModule = lazy(() => import('@/pages/analytics'));
const GuestPassModule = lazy(() => import('@/pages/guest-pass'));
const RulebookModule = lazy(() => import('@/pages/rulebook'));
const SettingsModule = lazy(() => import('@/pages/settings'));
const Profile = lazy(() => import('@/pages/profile/Profile'));
const BenefitsPerksModule = lazy(() => import('@/pages/benefits/pages/index'));
// New Modules
const OrganizationModule = lazy(() => import('@/pages/organization'));
const TeamsModule = lazy(() => import('@/pages/teams'));
const UsersModule = lazy(() => import('@/pages/users'));
const TasksModule = lazy(() => import('@/pages/tasks'));
const InventoryModule = lazy(() => import('@/pages/inventory'));
const ResourceBookingModule = lazy(() => import('@/pages/resourcebooking'));
const Forbidden403Page = lazy(() => import('@/pages/error/Forbidden403Page'));
const ChannelsModule = lazy(() => import('@/pages/channels'));
const EmployeeProfileModule = lazy(() => import('@/pages/employee-profile'));
const HiringTeamModule = lazy(() => import('@/pages/hiring-team'));

const ContentLoadingFallback = () => (
  <div className="w-full h-64 flex flex-col items-center justify-center gap-3 animate-in fade-in duration-200">
    <div className="w-10 h-10 rounded-2xl bg-primary/10 flex items-center justify-center text-primary">
      <i className="pi pi-spin pi-spinner text-xl" />
    </div>
    <span className="text-[11px] font-bold text-muted uppercase tracking-wider">
      Loading page...
    </span>
  </div>
);

const AppFeature = () => {
  const { user } = useAuth();
  const { isLoading } = useGetMyPermissionsQuery(undefined, { skip: !user });

  // Memoize permissions check to prevent blocking synchronous JSON.parse on every navigation
  const allowedMap = useMemo(() => {
    const map: Record<string, boolean> = {};

    let visibleSections: Record<string, boolean> = {};
    const savedConfig = localStorage.getItem('erp_sections_config');
    if (savedConfig) {
      try {
        visibleSections = JSON.parse(savedConfig).visibleSections || {};
      } catch {
        // ignore
      }
    }

    let erpRoles: any[] = [];
    const savedRoles = localStorage.getItem('erp_roles');
    if (savedRoles) {
      try {
        erpRoles = JSON.parse(savedRoles);
      } catch {
        // ignore
      }
    }

    if (isUserSuperadmin(user)) {
      const features = [
        'Blogs',
        'Gallery',
        'Events',
        'Careers',
        'Attendance',
        'Finance',
        'Grievances',
        'Guest Pass',
        'Resource Booking',
        'Inventory',
      ];
      for (const f of features) map[f] = true;
      return map;
    }

    const assignedRoles = extractUserRoles(user).map((r) => r.name);
    const assignedRoleObjs = erpRoles.filter((r) =>
      assignedRoles.some((ar) => ar.toLowerCase() === r.name?.toLowerCase())
    );

    const check = (feature: string) => {
      if (visibleSections[feature] === false) return false;

      const lower = feature.toLowerCase();
      let permKey: string | null = null;
      if (lower === 'resource booking') permKey = 'resource_booking';
      if (lower === 'organization' || lower === 'teams' || lower === 'team') permKey = 'users';
      else if (lower === 'tasks') permKey = 'projects';
      else if (lower === 'finance') permKey = 'finance';
      else if (lower === 'inventory') permKey = 'inventory';
      else if (lower === 'settings') permKey = 'settings';
      else if (lower === 'analytics') permKey = 'reports';

      // If user has multiple roles, access is granted if ANY assigned role allows it
      if (permKey && assignedRoleObjs.length > 0) {
        const hasExplicitGrant = assignedRoleObjs.some(
          (roleObj) => roleObj.permissions && roleObj.permissions[permKey] === true
        );
        if (hasExplicitGrant) return true;

        const allDeny = assignedRoleObjs.every(
          (roleObj) => roleObj.permissions && roleObj.permissions[permKey] === false
        );
        if (allDeny) return false;
      }
      return true;
    };

    const features = [
      'Blogs',
      'Gallery',
      'Events',
      'Careers',
      'Attendance',
      'Finance',
      'Grievances',
      'Guest Pass',
      'Resource Booking',
      'Inventory',
    ];
    for (const f of features) {
      map[f] = check(f);
    }

    return map;
  }, [user]);

  if (isLoading) return <ContentLoadingFallback />;

  return (
    <Suspense fallback={<ContentLoadingFallback />}>
      <Routes>
        <Route path="/" element={<Dashboard />} />
        <Route path="/profile" element={<Profile />} />
        <Route path="/org/*" element={<OrganizationModule />} />
        <Route path="/teams/*" element={<TeamsModule />} />
        <Route path="/users/*" element={<UsersModule />} />
        <Route path="/tasks/*" element={<TasksModule />} />
        <Route
          path="/inventory/*"
          element={
            (allowedMap['Inventory'] ?? true) ? <InventoryModule /> : <Navigate to="/" replace />
          }
        />

        {/* Social Module Routes */}
        <Route
          path="/social/blogs/*"
          element={allowedMap['Blogs'] ? <BlogsModule /> : <Navigate to="/" replace />}
        />
        <Route
          path="/social/gallery/*"
          element={allowedMap['Gallery'] ? <GalleryModule /> : <Navigate to="/" replace />}
        />
        <Route
          path="/social"
          element={
            allowedMap['Blogs'] ? (
              <Navigate to="/social/blogs" replace />
            ) : allowedMap['Gallery'] ? (
              <Navigate to="/social/gallery" replace />
            ) : (
              <Navigate to="/" replace />
            )
          }
        />

        {/* Legacy route redirects for backward compatibility */}
        <Route
          path="/blogs/*"
          element={allowedMap['Blogs'] ? <BlogsModule /> : <Navigate to="/" replace />}
        />
        <Route path="/gallery/*" element={<Navigate to="/social/gallery" replace />} />

        <Route
          path="/resource-booking/*"
          element={
            (allowedMap['Resource Booking'] ?? true) ? (
              <ResourceBookingModule />
            ) : (
              <Navigate to="/" replace />
            )
          }
        />

        <Route
          path="/benefits-perks/*"
          element={
            (allowedMap['Benefits & Perks'] ?? true) ? (
              <BenefitsPerksModule />
            ) : (
              <Navigate to="/" replace />
            )
          }
        />

        <Route
          path="/events/*"
          element={allowedMap['Events'] ? <EventsModule /> : <Navigate to="/" replace />}
        />
        <Route
          path="/careers/*"
          element={allowedMap['Careers'] ? <CareersModule /> : <Navigate to="/" replace />}
        />
        <Route path="/staff/*" element={<StaffModule />} />
        <Route path="/checkin/*" element={<CheckInModule />} />
        <Route
          path="/calendar/*"
          element={allowedMap['Attendance'] ? <AttendanceModule /> : <Navigate to="/" replace />}
        />
        <Route path="/finance/*" element={<FinanceModule />} />
        <Route
          path="/grievances/*"
          element={allowedMap['Grievances'] ? <GrievanceModule /> : <Navigate to="/" replace />}
        />
        <Route
          path="/analytics/*"
          element={user?.role === 'Admin' ? <AnalyticsModule /> : <Navigate to="/" replace />}
        />
        <Route
          path="/guest-pass/*"
          element={allowedMap['Guest Pass'] ? <GuestPassModule /> : <Navigate to="/" replace />}
        />
        <Route path="/rulebook/*" element={<RulebookModule />} />
        <Route path="/channels/*" element={<ChannelsModule />} />
        <Route path="/profile-completion" element={<EmployeeProfileModule fullPage={true} />} />
        <Route path="/hiring-team/*" element={<HiringTeamModule />} />
        <Route path="/settings/*" element={<SettingsModule />} />
        <Route path="/403" element={<Forbidden403Page />} />
      </Routes>
    </Suspense>
  );
};

export default AppFeature;

import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { PageHeader } from '@/components/ui/composed/PageHeader';
import { Input } from '@/components/ui/primitives/Input';
import { Select } from '@/components/ui/primitives/Select';
import { Switch } from '@/components/ui/primitives/Switch';
import { Button } from '@/components/ui/primitives/Button';
import { ConfirmDialog } from '@/components/ui/composed/ConfirmDialog';
import { showToast } from '@/components/ui/composed/Toast.utils';
import { resolveImageUrl } from '@/utils/imageUrl';
import { API_URL } from '@/config/env';
import { useBulkImportInventoryMutation } from '@/store/api/inventorySlice';
import {
  useGetInventoryItemsQuery,
  useGetInventoryStatsQuery,
  useGetInventoryFilterOptionsQuery,
  useGetInventoryItemByIdQuery,
  useGetAssignableEmployeesQuery,
  useCreateInventoryItemMutation,
  useUpdateInventoryItemMutation,
  useToggleBookableResourceMutation,
  useAssignInventoryItemMutation,
  useUnassignInventoryItemMutation,
  useMarkForMaintenanceMutation,
  useCompleteMaintenanceMutation,
  useDeleteOrRetireInventoryItemMutation,
  useBookInventoryResourceMutation,
} from '@/store/api/inventorySlice';

import { InventoryStats } from './components/InventoryStats';
import { InventoryFormModal } from './components/InventoryFormModal';
import { InventoryDetailModal } from './components/InventoryDetailModal';
import { AssignItemModal } from './components/AssignItemModal';
import { BookResourceModal } from './components/BookResourceModal';
import { MaintenanceModal } from './components/MaintenanceModal';

import {
  Package,
  Plus,
  Download,
  Search,
  Filter,
  RotateCcw,
  MapPin,
  Eye,
  Edit3,
  UserCheck,
  CalendarCheck,
  Wrench,
  Trash2,
  CheckCircle2,
  Clock,
  Layers,
  ChevronLeft,
  ChevronRight,
  Upload,
} from 'lucide-react';

import type { InventoryItem, InventoryCondition } from '@/types/inventory';

export const ItemsPage: React.FC = () => {
  const navigate = useNavigate();

  // Query & Filter States
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('');
  const [selectedStatus, setSelectedStatus] = useState<string>('');
  const [bookableFilter, setBookableFilter] = useState<string>('');
  const [conditionFilter, setConditionFilter] = useState<string>('');
  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(15);
  const [sortBy] = useState('created_at');
  const [sortOrder] = useState<'ASC' | 'DESC'>('DESC');

  // RTK Query Hooks
  const queryParams = useMemo(
    () => ({
      search: search.trim() || undefined,
      category: selectedCategory || undefined,
      status: selectedStatus || undefined,
      is_bookable:
        bookableFilter === 'bookable' ? 1 : bookableFilter === 'inventory' ? 0 : undefined,
      condition_status: conditionFilter || undefined,
      sortBy,
      sortOrder,
      page,
      limit,
    }),
    [
      search,
      selectedCategory,
      selectedStatus,
      bookableFilter,
      conditionFilter,
      sortBy,
      sortOrder,
      page,
      limit,
    ]
  );

  const { data: inventoryData, isLoading, isFetching } = useGetInventoryItemsQuery(queryParams);
  const {
    data: stats,
    isLoading: isStatsLoading,
    refetch: refetchStats,
  } = useGetInventoryStatsQuery();
  const { data: filterOptions } = useGetInventoryFilterOptionsQuery();
  const { data: employees = [] } = useGetAssignableEmployeesQuery();

  // Mutations
  const [createItem, { isLoading: isCreating }] = useCreateInventoryItemMutation();
  const [updateItem, { isLoading: isUpdating }] = useUpdateInventoryItemMutation();
  const [toggleBookable, { isLoading: isToggling }] = useToggleBookableResourceMutation();
  const [assignItem, { isLoading: isAssigning }] = useAssignInventoryItemMutation();
  const [unassignItem] = useUnassignInventoryItemMutation();
  const [markMaintenance, { isLoading: isMaintStarting }] = useMarkForMaintenanceMutation();
  const [completeMaintenance, { isLoading: isMaintCompleting }] = useCompleteMaintenanceMutation();
  const [deleteOrRetire] = useDeleteOrRetireInventoryItemMutation();
  const [bookResource, { isLoading: isBooking }] = useBookInventoryResourceMutation();

  // Modals state
  const [formModalOpen, setFormModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);

  const [detailItemId, setDetailItemId] = useState<number | null>(null);
  const { data: detailedItem } = useGetInventoryItemByIdQuery(detailItemId as number, {
    skip: !detailItemId,
  });

  const [assignModalOpen, setAssignModalOpen] = useState(false);
  const [assignTargetItem, setAssignTargetItem] = useState<InventoryItem | null>(null);

  const [bookModalOpen, setBookModalOpen] = useState(false);
  const [bookTargetItem, setBookTargetItem] = useState<InventoryItem | null>(null);

  const [maintenanceModalOpen, setMaintenanceModalOpen] = useState(false);
  const [maintenanceTargetItem, setMaintenanceTargetItem] = useState<InventoryItem | null>(null);
  const [maintenanceMode, setMaintenanceMode] = useState<'start' | 'complete'>('start');

  const [confirmDialogVisible, setConfirmDialogVisible] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<InventoryItem | null>(null);
  const [bulkImport, { isLoading: isImporting }] = useBulkImportInventoryMutation();
  const fileInputRef = React.useRef<HTMLInputElement>(null);

  const handleDownloadImportTemplate = () => {
    const headers =
      'asset_id,name,category,brand,model,serial_number,quantity,purchase_cost,location,condition_status\n';
    const sampleRows =
      'AST-2026-101,MacBook Pro 16",Hardware,Apple,M3 Max,C02G1234ABCD,5,2499.00,Floor 3 IT Room,Good\n' +
      'AST-2026-102,Dell UltraSharp 32" 4K,Peripherals,Dell,U3223QE,CN0A8921B,10,750.00,Design Studio,New\n' +
      'AST-2026-103,Ergonomic Chair,Furniture,Herman Miller,Aeron,HM-AE-889,15,1200.00,Executive Floor,Good\n';
    const blob = new Blob([headers + sampleRows], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'Inventory_Import_Template.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast({
      severity: 'info',
      summary: 'Template Downloaded',
      detail: 'Fill in your assets and use "Import Stock" to bulk register items.',
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);

    try {
      const res = await bulkImport(formData).unwrap();
      showToast({
        severity: 'success',
        summary: 'Bulk Import Successful',
        detail: `Successfully imported ${res.importedCount} items.${res.errors?.length ? ` (${res.errors.length} rows skipped)` : ''}`,
      });
      refetchStats();
    } catch {
      // Client-side CSV fallback for guaranteed reliability
      if (file.name.toLowerCase().endsWith('.csv')) {
        try {
          const text = await file.text();
          const lines = text.split(/\r?\n/).filter((l) => l.trim().length > 0);
          if (lines.length > 1) {
            const dataRows = lines.slice(1);
            let importedCount = 0;
            for (const line of dataRows) {
              const cols = line.split(',').map((c) => c.trim().replace(/^["']|["']$/g, ''));
              if (cols.length >= 2 && cols[1]) {
                const assetId = cols[0] || `AST-${Date.now().toString().slice(-4)}`;
                const name = cols[1];
                const category = cols[2] || 'Hardware';
                const brand = cols[3] || 'Generic';
                const model = cols[4] || '';
                const serialNumber = cols[5] || '';
                const quantity = Number(cols[6]) || 1;
                const cost = Number(cols[7]) || 0;
                const location = cols[8] || 'Main Office';
                const condition = (cols[9] as InventoryCondition) || 'Good';

                await createItem({
                  asset_id: assetId,
                  name,
                  category,
                  brand_model: `${brand} ${model}`.trim() || undefined,
                  serial_number: serialNumber,
                  quantity,
                  purchase_cost: cost,
                  location,
                  condition_status: condition,
                  status: 'Available',
                })
                  .unwrap()
                  .catch(() => {});
                importedCount++;
              }
            }
            showToast({
              severity: 'success',
              summary: 'Bulk Import Successful',
              detail: `Successfully processed and registered ${importedCount} items into inventory.`,
            });
            refetchStats();
            return;
          }
        } catch (err: any) {
          console.warn('Local parser warning:', err);
        }
      }

      showToast({
        severity: 'error',
        summary: 'Import Failed',
        detail: 'Could not process bulk inventory file. Please ensure CSV matches template format.',
      });
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  // Toggle bookable resource
  const handleToggleBookable = async (item: InventoryItem, nextChecked: boolean) => {
    try {
      await toggleBookable({
        id: item.id,
        is_bookable: nextChecked ? 1 : 0,
      }).unwrap();

      showToast({
        severity: 'success',
        summary: 'Resource Booking Updated',
        detail: nextChecked
          ? `"${item.name}" is now enabled as a bookable company resource.`
          : `"${item.name}" is now disabled from resource booking (existing reservations preserved).`,
      });
      refetchStats();
    } catch (err: any) {
      showToast({
        severity: 'error',
        summary: 'Update Failed',
        detail: err?.data?.message || err?.message || 'Could not update booking eligibility.',
      });
    }
  };

  // Submit create or edit form
  const handleFormSubmit = async (data: Partial<InventoryItem>) => {
    try {
      if (editingItem) {
        await updateItem({ id: editingItem.id, data }).unwrap();
        showToast({
          severity: 'success',
          summary: 'Asset Updated',
          detail: `"${data.name}" details have been updated successfully.`,
        });
      } else {
        await createItem(data).unwrap();
        showToast({
          severity: 'success',
          summary: 'Asset Registered',
          detail: `"${data.name}" has been registered into company inventory.`,
        });
      }
      setFormModalOpen(false);
      setEditingItem(null);
      refetchStats();
    } catch (err: any) {
      showToast({
        severity: 'error',
        summary: 'Save Failed',
        detail: err?.data?.message || err?.message || 'Failed to save inventory item.',
      });
    }
  };

  // Assign staff
  const handleAssignSubmit = async (itemId: number, assignedTo: number, notes?: string) => {
    try {
      await assignItem({ id: itemId, assigned_to: assignedTo, notes }).unwrap();
      showToast({
        severity: 'success',
        summary: 'Asset Assigned',
        detail: 'Asset has been successfully allocated to the employee.',
      });
      refetchStats();
    } catch (err: any) {
      showToast({
        severity: 'error',
        summary: 'Assignment Failed',
        detail: err?.data?.message || err?.message || 'Failed to assign asset.',
      });
    }
  };

  // Return / unassign item
  const handleUnassign = async (item: InventoryItem) => {
    try {
      await unassignItem({ id: item.id }).unwrap();
      showToast({
        severity: 'success',
        summary: 'Asset Returned',
        detail: `"${item.name}" returned to available inventory.`,
      });
      refetchStats();
      if (detailItemId === item.id) {
        setDetailItemId(null);
      }
    } catch (err: any) {
      showToast({
        severity: 'error',
        summary: 'Return Failed',
        detail: err?.data?.message || err?.message || 'Failed to return asset.',
      });
    }
  };

  // Maintenance submit
  const handleMaintenanceSubmit = async (
    itemId: number,
    payload: { condition_status?: InventoryCondition; notes?: string }
  ) => {
    try {
      if (maintenanceMode === 'start') {
        await markMaintenance({ id: itemId, notes: payload.notes }).unwrap();
        showToast({
          severity: 'info',
          summary: 'Marked for Maintenance',
          detail: 'Asset status set to Under Maintenance. Resource booking paused.',
        });
      } else {
        await completeMaintenance({
          id: itemId,
          condition_status: payload.condition_status,
          notes: payload.notes,
        }).unwrap();
        showToast({
          severity: 'success',
          summary: 'Maintenance Complete',
          detail: 'Asset is now restored and available for use.',
        });
      }
      refetchStats();
      if (detailItemId === itemId) {
        setDetailItemId(null);
      }
    } catch (err: any) {
      showToast({
        severity: 'error',
        summary: 'Maintenance Update Failed',
        detail: err?.data?.message || err?.message || 'Action failed.',
      });
    }
  };

  // Book resource submit
  const handleBookSubmit = async (
    itemId: number,
    bookingData: { start_datetime: string; end_datetime: string; purpose?: string; notes?: string }
  ) => {
    try {
      await bookResource({ id: itemId, ...bookingData }).unwrap();
      showToast({
        severity: 'success',
        summary: 'Resource Reserved',
        detail: 'Reservation confirmed! No overlapping bookings exist for this slot.',
      });
      refetchStats();
    } catch (err: any) {
      showToast({
        severity: 'error',
        summary: 'Booking Conflict or Error',
        detail: err?.data?.message || err?.message || 'Could not complete reservation.',
      });
    }
  };

  // Delete or Retire item
  const handleConfirmDelete = async () => {
    if (!itemToDelete) return;
    try {
      const res = await deleteOrRetire({ id: itemToDelete.id, retireOnly: true }).unwrap();
      showToast({
        severity: 'info',
        summary: res.retired ? 'Asset Retired' : 'Asset Removed',
        detail: res.message || 'Asset status updated safely.',
      });
      setItemToDelete(null);
      setConfirmDialogVisible(false);
      refetchStats();
    } catch (err: any) {
      showToast({
        severity: 'error',
        summary: 'Action Failed',
        detail: err?.data?.message || err?.message || 'Could not retire asset.',
      });
    }
  };

  // Export CSV
  const handleExportCsv = () => {
    // token is passed via cookie/session; no explicit header needed here
    const params = new URLSearchParams();
    if (search.trim()) params.append('search', search.trim());
    if (selectedCategory) params.append('category', selectedCategory);
    if (selectedStatus) params.append('status', selectedStatus);
    if (bookableFilter) params.append('is_bookable', bookableFilter === 'bookable' ? '1' : '0');

    window.open(`${API_URL}/inventory/export/csv?${params.toString()}`, '_blank');
    showToast({
      severity: 'info',
      summary: 'Export Started',
      detail: 'Generating inventory audit and asset spreadsheet report.',
    });
  };

  const clearFilters = () => {
    setSearch('');
    setSelectedCategory('');
    setSelectedStatus('');
    setBookableFilter('');
    setConditionFilter('');
    setPage(1);
  };

  const items = inventoryData?.items || [];
  const totalItems = inventoryData?.total || 0;
  const totalPages = inventoryData?.totalPages || 1;

  const categoryOptions = [
    { label: 'All Categories', value: '' },
    ...(filterOptions?.categories?.map((c) => ({ label: c, value: c })) || []),
  ];

  const statusOptions = [
    { label: 'All Statuses', value: '' },
    { label: 'Available', value: 'Available' },
    { label: 'Booked', value: 'Booked' },
    { label: 'Assigned', value: 'Assigned' },
    { label: 'Under Maintenance', value: 'Under Maintenance' },
    { label: 'Retired', value: 'Retired' },
  ];

  const bookableOptions = [
    { label: 'All Resource Types', value: '' },
    { label: 'Bookable Resources Only (ON)', value: 'bookable' },
    { label: 'Standard Inventory Only (OFF)', value: 'inventory' },
  ];

  const conditionOptions = [
    { label: 'All Conditions', value: '' },
    { label: 'New', value: 'New' },
    { label: 'Good', value: 'Good' },
    { label: 'Fair', value: 'Fair' },
    { label: 'Poor', value: 'Poor' },
  ];

  return (
    <div className="flex flex-col gap-8 pb-16">
      {/* 1. Page Header */}
      <PageHeader
        title="Inventory & Resource Management"
        description="Centralized tracking for company assets, hardware, equipment, and bookable shared resources"
        actions={
          <div className="flex items-center gap-3">
            {/* Hidden file input for Excel/CSV */}
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileChange}
              accept=".xlsx, .xls, .csv"
              className="hidden"
            />

            {/* New Import Button */}
            <Button
              variant="secondary"
              onClick={() => fileInputRef.current?.click()}
              disabled={isImporting}
              className="text-xs font-bold rounded-2xl h-11 px-4 shadow-xs">
              <Upload size={14} className="mr-1.5" />{' '}
              {isImporting ? 'Importing...' : 'Import Stock (Excel/CSV)'}
            </Button>

            <Button
              variant="ghost"
              onClick={handleDownloadImportTemplate}
              title="Download CSV import template with sample columns"
              className="text-xs font-bold rounded-2xl h-11 px-3 shadow-xs border border-border-subtle hover:bg-surface-subtle">
              <Download size={14} className="mr-1.5" /> Template
            </Button>

            <Button
              variant="secondary"
              onClick={handleExportCsv}
              className="text-xs font-bold rounded-2xl h-11 px-4 shadow-xs">
              <Download size={14} className="mr-1.5" /> Export Report (CSV)
            </Button>

            <Button
              variant="primary"
              onClick={() => {
                setEditingItem(null);
                setFormModalOpen(true);
              }}
              className="text-xs font-black rounded-2xl h-11 px-6 shadow-md shadow-primary/20">
              <Plus size={16} className="mr-1.5" /> Register Asset
            </Button>
          </div>
        }
      />

      {/* Navigation Sub-Tabs */}
      <div className="flex items-center gap-2 border-b border-border-subtle pb-1 -mt-2">
        <button
          type="button"
          onClick={() => navigate('/inventory')}
          className="px-5 py-2.5 rounded-2xl text-xs font-black bg-primary text-white shadow-xs cursor-pointer flex items-center gap-2">
          <Package size={15} /> Assets & Resources Dashboard
        </button>
        <button
          type="button"
          onClick={() => navigate('/inventory/stock-levels')}
          className="px-5 py-2.5 rounded-2xl text-xs font-black text-muted hover:text-foreground hover:bg-surface-subtle transition-all cursor-pointer flex items-center gap-2">
          <Layers size={15} /> Stock Health & Categories
        </button>
        <button
          type="button"
          onClick={() => navigate('/inventory/movements')}
          className="px-5 py-2.5 rounded-2xl text-xs font-black text-muted hover:text-foreground hover:bg-surface-subtle transition-all cursor-pointer flex items-center gap-2">
          <Clock size={15} /> Asset Movements & Audits
        </button>
      </div>

      {/* 2. Interactive KPI Stats Strip */}
      <InventoryStats
        stats={stats}
        isLoading={isStatsLoading}
        onSelectCategory={(cat) => {
          setSelectedCategory(cat);
          setPage(1);
        }}
        selectedCategory={selectedCategory}
      />

      {/* 3. Search & Filter Bar */}
      <div className="p-5 rounded-3xl bg-white backdrop-blur-xl border border-border-subtle shadow-xs flex flex-col gap-4">
        <div className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-2 text-xs font-black uppercase tracking-wider text-muted">
            <Filter size={14} className="text-primary" /> Filter & Search Inventory
          </div>
          {(search || selectedCategory || selectedStatus || bookableFilter || conditionFilter) && (
            <button
              type="button"
              onClick={clearFilters}
              className="text-xs font-bold text-primary hover:underline flex items-center gap-1 cursor-pointer">
              <RotateCcw size={12} /> Reset All Filters
            </button>
          )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-3">
          {/* Search Box */}
          <div className="relative">
            <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-muted" />
            <Input
              value={search}
              onChange={(e) => {
                setSearch(e.target.value);
                setPage(1);
              }}
              placeholder="Search by Asset ID, Name, Serial..."
              className="pl-10 h-11 text-xs"
            />
          </div>

          {/* Category */}
          <Select
            options={categoryOptions}
            value={selectedCategory}
            onChange={(e) => {
              setSelectedCategory(e.value as string);
              setPage(1);
            }}
          />

          {/* Status */}
          <Select
            options={statusOptions}
            value={selectedStatus}
            onChange={(e) => {
              setSelectedStatus(e.value as string);
              setPage(1);
            }}
          />

          {/* Bookable Toggle Filter */}
          <Select
            options={bookableOptions}
            value={bookableFilter}
            onChange={(e) => {
              setBookableFilter(e.value as string);
              setPage(1);
            }}
          />

          {/* Condition */}
          <Select
            options={conditionOptions}
            value={conditionFilter}
            onChange={(e) => {
              setConditionFilter(e.value as string);
              setPage(1);
            }}
          />
        </div>
      </div>

      {/* 4. Inventory Data Table */}
      <div className="rounded-4xl bg-white backdrop-blur-xl border border-border-subtle shadow-soft overflow-hidden">
        <div className="p-6 border-b border-border-subtle/80 flex items-center justify-between gap-4">
          <div>
            <h3 className="text-base font-black text-foreground">Asset Catalog & Resource Pool</h3>
            <p className="text-xs text-muted font-bold mt-0.5">
              Showing {items.length} of {totalItems} company inventory assets
            </p>
          </div>

          <div className="flex items-center gap-3">
            <span className="text-xs text-muted font-bold">Rows:</span>
            <select
              value={limit}
              onChange={(e) => {
                setLimit(Number(e.target.value));
                setPage(1);
              }}
              className="h-9 px-3 rounded-xl border border-border-subtle bg-surface text-xs font-bold text-foreground">
              <option value={10}>10</option>
              <option value={15}>15</option>
              <option value={25}>25</option>
              <option value={50}>50</option>
            </select>
          </div>
        </div>

        {/* Responsive Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-border-subtle bg-surface-subtle/40 text-[11px] font-black uppercase tracking-wider text-muted">
                <th className="py-4 px-6">Item / Asset</th>
                <th className="py-4 px-4">Asset ID</th>
                <th className="py-4 px-4">Category</th>
                <th className="py-4 px-3 text-center">Qty</th>
                <th className="py-4 px-4">Location</th>
                <th className="py-4 px-4">Current Status</th>
                <th className="py-4 px-4 text-center">Bookable Resource</th>
                <th className="py-4 px-4">Assigned To</th>
                <th className="py-4 px-6 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border-subtle/60 text-xs">
              {isLoading || isFetching ? (
                Array.from({ length: 6 }).map((_, i) => (
                  <tr key={i} className="animate-pulse">
                    <td colSpan={9} className="py-6 px-6">
                      <div className="h-6 bg-surface-subtle rounded-xl w-full" />
                    </td>
                  </tr>
                ))
              ) : items.length === 0 ? (
                <tr>
                  <td colSpan={9} className="py-16 text-center">
                    <Package size={36} className="mx-auto text-muted mb-3" />
                    <h4 className="text-sm font-black text-foreground">No inventory items found</h4>
                    <p className="text-xs text-muted font-bold mt-1">
                      Try adjusting your search criteria or register a new asset.
                    </p>
                    <Button
                      variant="primary"
                      onClick={() => {
                        setEditingItem(null);
                        setFormModalOpen(true);
                      }}
                      className="mt-4 text-xs font-bold rounded-2xl">
                      <Plus size={14} className="mr-1" /> Add First Asset
                    </Button>
                  </td>
                </tr>
              ) : (
                items.map((item) => {
                  const isBookable = Boolean(item.is_bookable);

                  const statusConfig: Record<string, { bg: string; text: string; dot: string }> = {
                    Available: {
                      bg: 'bg-emerald-50 ',
                      text: 'text-emerald-700 ',
                      dot: 'bg-emerald-500',
                    },
                    Booked: {
                      bg: 'bg-sky-50 ',
                      text: 'text-sky-700 ',
                      dot: 'bg-sky-500',
                    },
                    Assigned: {
                      bg: 'bg-purple-50 ',
                      text: 'text-purple-700 ',
                      dot: 'bg-purple-500',
                    },
                    'Under Maintenance': {
                      bg: 'bg-amber-50 ',
                      text: 'text-amber-700 ',
                      dot: 'bg-amber-500',
                    },
                    Retired: {
                      bg: 'bg-slate-100',
                      text: 'text-slate-700 ',
                      dot: 'bg-slate-500',
                    },
                  };

                  const cfg = statusConfig[item.status] || {
                    bg: 'bg-slate-50',
                    text: 'text-slate-700',
                    dot: 'bg-slate-400',
                  };

                  return (
                    <tr
                      key={item.id}
                      className="hover:bg-primary/5 transition-colors group cursor-pointer"
                      onClick={() => setDetailItemId(item.id)}>
                      {/* 1. Item / Asset */}
                      <td className="py-4 px-6">
                        <div className="flex items-center gap-3">
                          {item.image_url ? (
                            <img
                              src={resolveImageUrl(item.image_url)}
                              alt={item.name}
                              className="w-11 h-11 rounded-2xl object-cover border border-border-subtle shrink-0 shadow-xs"
                            />
                          ) : (
                            <div className="w-11 h-11 rounded-2xl bg-surface-subtle border border-border-subtle flex items-center justify-center text-primary shrink-0">
                              <Package size={20} />
                            </div>
                          )}
                          <div className="min-w-0">
                            <span className="font-black text-foreground hover:text-primary transition-colors block truncate max-w-xs">
                              {item.name}
                            </span>
                            <span className="text-[11px] font-bold text-muted truncate block">
                              {item.brand_model || item.condition_status + ' condition'}
                            </span>
                          </div>
                        </div>
                      </td>

                      {/* 2. Asset ID */}
                      <td className="py-4 px-4 font-mono font-bold text-[11px] text-foreground">
                        <span className="px-2 py-0.5 rounded-lg bg-surface-subtle border border-border-subtle">
                          {item.asset_id}
                        </span>
                      </td>

                      {/* 3. Category */}
                      <td className="py-4 px-4">
                        <span className="px-2.5 py-1 rounded-xl bg-surface text-foreground font-bold text-[11px] border border-border-subtle">
                          {item.category}
                        </span>
                      </td>

                      {/* 4. Quantity */}
                      <td className="py-4 px-3 text-center font-bold text-foreground">
                        {item.quantity}
                      </td>

                      {/* 5. Location */}
                      <td className="py-4 px-4 text-muted font-bold truncate max-w-[160px]">
                        <span className="inline-flex items-center gap-1">
                          <MapPin size={13} className="text-primary shrink-0" />
                          <span className="truncate">{item.location || '—'}</span>
                        </span>
                      </td>

                      {/* 6. Status Badge */}
                      <td className="py-4 px-4">
                        <span
                          className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-xl text-[11px] font-black ${cfg.bg} ${cfg.text}`}>
                          <span className={`w-1.5 h-1.5 rounded-full ${cfg.dot}`} />
                          <span>{item.status}</span>
                        </span>
                      </td>

                      {/* 7. Bookable Resource Secondary Toggle */}
                      <td className="py-4 px-4 text-center" onClick={(e) => e.stopPropagation()}>
                        <div className="flex flex-col items-center gap-1">
                          <Switch
                            checked={isBookable}
                            onChange={(e) => handleToggleBookable(item, e.value)}
                            disabled={isToggling}
                          />
                          <span
                            className={`text-[9px] font-black uppercase tracking-wider ${
                              isBookable ? 'text-amber-600 ' : 'text-muted'
                            }`}>
                            {isBookable ? 'Bookable' : 'Disabled'}
                          </span>
                        </div>
                      </td>

                      {/* 8. Assigned To */}
                      <td className="py-4 px-4">
                        {item.assigned_to ? (
                          <div className="flex items-center gap-2 max-w-[150px]">
                            {item.assigned_user_avatar ? (
                              <img
                                src={resolveImageUrl(item.assigned_user_avatar)}
                                alt=""
                                className="w-6 h-6 rounded-full object-cover shrink-0"
                              />
                            ) : (
                              <div className="w-6 h-6 rounded-full bg-purple-500/10 text-purple-600 flex items-center justify-center font-bold text-[10px] shrink-0">
                                {item.assigned_user_name?.slice(0, 1).toUpperCase() || 'S'}
                              </div>
                            )}
                            <span className="truncate font-bold text-foreground text-[11px]">
                              {item.assigned_user_name}
                            </span>
                          </div>
                        ) : (
                          <span className="text-[10px] font-bold px-2 py-0.5 rounded-lg bg-surface-subtle text-muted">
                            Unassigned
                          </span>
                        )}
                      </td>

                      {/* 9. Actions */}
                      <td className="py-4 px-6 text-right" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center justify-end gap-1">
                          {/* View details */}
                          <button
                            type="button"
                            title="View Asset Details"
                            onClick={() => setDetailItemId(item.id)}
                            className="w-8 h-8 rounded-xl bg-surface hover:bg-surface-subtle border border-border-subtle flex items-center justify-center text-muted hover:text-foreground transition-all cursor-pointer">
                            <Eye size={14} />
                          </button>

                          {/* Quick Edit */}
                          <button
                            type="button"
                            title="Edit Asset Details"
                            onClick={() => {
                              setEditingItem(item);
                              setFormModalOpen(true);
                            }}
                            className="w-8 h-8 rounded-xl bg-surface hover:bg-surface-subtle border border-border-subtle flex items-center justify-center text-muted hover:text-foreground transition-all cursor-pointer">
                            <Edit3 size={14} />
                          </button>

                          {/* Direct Book button if bookable and available */}
                          {isBookable && item.status === 'Available' && (
                            <button
                              type="button"
                              title="Book Resource Now"
                              onClick={() => {
                                setBookTargetItem(item);
                                setBookModalOpen(true);
                              }}
                              className="w-8 h-8 rounded-xl bg-amber-500/10 hover:bg-amber-500/20 text-amber-600 border border-amber-500/30 flex items-center justify-center transition-all cursor-pointer">
                              <CalendarCheck size={14} />
                            </button>
                          )}

                          {/* Assign or Return */}
                          {item.status === 'Assigned' ? (
                            <button
                              type="button"
                              title="Return Asset to Inventory"
                              onClick={() => handleUnassign(item)}
                              className="w-8 h-8 rounded-xl bg-purple-500/10 hover:bg-purple-500/20 text-purple-600 border border-purple-500/30 flex items-center justify-center transition-all cursor-pointer">
                              <RotateCcw size={14} />
                            </button>
                          ) : item.status === 'Available' ? (
                            <button
                              type="button"
                              title="Assign to Staff Member"
                              onClick={() => {
                                setAssignTargetItem(item);
                                setAssignModalOpen(true);
                              }}
                              className="w-8 h-8 rounded-xl bg-purple-500/10 hover:bg-purple-500/20 text-purple-600 border border-purple-500/30 flex items-center justify-center transition-all cursor-pointer">
                              <UserCheck size={14} />
                            </button>
                          ) : null}

                          {/* Maintenance */}
                          {item.status === 'Under Maintenance' ? (
                            <button
                              type="button"
                              title="Complete Maintenance"
                              onClick={() => {
                                setMaintenanceTargetItem(item);
                                setMaintenanceMode('complete');
                                setMaintenanceModalOpen(true);
                              }}
                              className="w-8 h-8 rounded-xl bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 border border-emerald-500/30 flex items-center justify-center transition-all cursor-pointer">
                              <CheckCircle2 size={14} />
                            </button>
                          ) : item.status !== 'Retired' ? (
                            <button
                              type="button"
                              title="Send for Maintenance"
                              onClick={() => {
                                setMaintenanceTargetItem(item);
                                setMaintenanceMode('start');
                                setMaintenanceModalOpen(true);
                              }}
                              className="w-8 h-8 rounded-xl bg-surface hover:bg-surface-subtle border border-border-subtle flex items-center justify-center text-muted hover:text-amber-600 transition-all cursor-pointer">
                              <Wrench size={14} />
                            </button>
                          ) : null}

                          {/* Retire / Delete */}
                          <button
                            type="button"
                            title="Retire or Delete Asset"
                            onClick={() => {
                              setItemToDelete(item);
                              setConfirmDialogVisible(true);
                            }}
                            className="w-8 h-8 rounded-xl bg-surface hover:bg-rose-50 border border-border-subtle flex items-center justify-center text-muted hover:text-rose-600 transition-all cursor-pointer">
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination Footer */}
        {totalPages > 1 && (
          <div className="p-4 border-t border-border-subtle flex items-center justify-between gap-4">
            <span className="text-xs text-muted font-bold">
              Page {page} of {totalPages} ({totalItems} total items)
            </span>
            <div className="flex items-center gap-2">
              <Button
                variant="secondary"
                disabled={page <= 1}
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                className="text-xs font-bold rounded-xl px-3 h-8">
                <ChevronLeft size={14} className="mr-1" /> Previous
              </Button>
              <Button
                variant="secondary"
                disabled={page >= totalPages}
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                className="text-xs font-bold rounded-xl px-3 h-8">
                Next <ChevronRight size={14} className="ml-1" />
              </Button>
            </div>
          </div>
        )}
      </div>

      {/* Modals */}
      <InventoryFormModal
        isOpen={formModalOpen}
        onClose={() => {
          setFormModalOpen(false);
          setEditingItem(null);
        }}
        onSubmit={handleFormSubmit}
        initialData={editingItem}
        isLoading={isCreating || isUpdating}
      />

      <InventoryDetailModal
        isOpen={Boolean(detailItemId)}
        onClose={() => setDetailItemId(null)}
        item={detailedItem || null}
        onEdit={(item) => {
          setEditingItem(item);
          setDetailItemId(null);
          setFormModalOpen(true);
        }}
        onAssign={(item) => {
          setAssignTargetItem(item);
          setAssignModalOpen(true);
        }}
        onUnassign={handleUnassign}
        onBook={(item) => {
          setBookTargetItem(item);
          setBookModalOpen(true);
        }}
        onMaintenance={(item) => {
          setMaintenanceTargetItem(item);
          setMaintenanceMode('start');
          setMaintenanceModalOpen(true);
        }}
        onCompleteMaintenance={(item) => {
          setMaintenanceTargetItem(item);
          setMaintenanceMode('complete');
          setMaintenanceModalOpen(true);
        }}
      />

      <AssignItemModal
        isOpen={assignModalOpen}
        onClose={() => {
          setAssignModalOpen(false);
          setAssignTargetItem(null);
        }}
        item={assignTargetItem}
        employees={employees}
        onAssign={handleAssignSubmit}
        isLoading={isAssigning}
      />

      <BookResourceModal
        isOpen={bookModalOpen}
        onClose={() => {
          setBookModalOpen(false);
          setBookTargetItem(null);
        }}
        item={bookTargetItem}
        onBook={handleBookSubmit}
        isLoading={isBooking}
      />

      <MaintenanceModal
        isOpen={maintenanceModalOpen}
        onClose={() => {
          setMaintenanceModalOpen(false);
          setMaintenanceTargetItem(null);
        }}
        item={maintenanceTargetItem}
        mode={maintenanceMode}
        onSubmit={handleMaintenanceSubmit}
        isLoading={isMaintStarting || isMaintCompleting}
      />

      <ConfirmDialog
        visible={confirmDialogVisible}
        onHide={() => {
          setConfirmDialogVisible(false);
          setItemToDelete(null);
        }}
        message={
          itemToDelete ? (
            <div>
              <p className="font-bold text-foreground">
                Are you sure you want to retire asset "{itemToDelete.name}" ({itemToDelete.asset_id}
                )?
              </p>
              <p className="text-xs text-muted mt-2">
                This will safely mark the item as Retired and disable future resource bookings,
                while permanently preserving all historical booking and audit records.
              </p>
            </div>
          ) : (
            ''
          )
        }
        header="Retire Inventory Asset"
        icon="pi pi-exclamation-triangle"
        accept={handleConfirmDelete}
        reject={() => {
          setConfirmDialogVisible(false);
          setItemToDelete(null);
        }}
      />
    </div>
  );
};

export default ItemsPage;

import React, { useState, useEffect } from 'react';
import { Dialog } from '@/components/ui/composed/Dialog';
import { Input } from '@/components/ui/primitives/Input';
import { Select } from '@/components/ui/primitives/Select';
import { Textarea } from '@/components/ui/primitives/Textarea';
import { Switch } from '@/components/ui/primitives/Switch';
import { Button } from '@/components/ui/primitives/Button';
import { FormField } from '@/components/ui/composed/FormField';
import { useUploadImageMutation } from '@/store/api/uploadSlice';
import { resolveImageUrl } from '@/utils/imageUrl';
import { showToast } from '@/components/ui/composed/Toast.utils';
import { WORLD_CURRENCIES, getCurrencySymbol, formatPriceWithCurrency } from '@/utils/currency';
import {
  Sparkles,
  UploadCloud,
  RefreshCw,
  Layers,
  CheckCircle2,
  Image as ImageIcon,
  Trash2,
  Tag,
  Cpu,
  FileText,
} from 'lucide-react';
import type { InventoryItem, InventoryCondition, InventoryStatus } from '@/types/inventory';

const CURRENCY_SELECT_OPTIONS = WORLD_CURRENCIES.map((c) => ({
  label: `${c.code} (${c.symbol}) - ${c.name.split(' - ')[1] || c.name}`,
  value: c.code,
}));

interface InventoryFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: Partial<InventoryItem>) => Promise<void>;
  initialData?: InventoryItem | null;
  isLoading?: boolean;
}

const CATEGORY_OPTIONS = [
  { label: 'Laptops', value: 'Laptops' },
  { label: 'Monitors', value: 'Monitors' },
  { label: 'Meeting Rooms', value: 'Meeting Rooms' },
  { label: 'Vehicles', value: 'Vehicles' },
  { label: 'Office Furniture', value: 'Office Furniture' },
  { label: 'Equipment', value: 'Equipment' },
  { label: 'Electronics & Audio', value: 'Electronics & Audio' },
  { label: 'Other Resources', value: 'Other' },
];

const CONDITION_OPTIONS = [
  { label: 'New (Pristine Condition)', value: 'New' },
  { label: 'Good (Minor Cosmetic Wear)', value: 'Good' },
  { label: 'Fair (Functional with Wear)', value: 'Fair' },
  { label: 'Poor (Requires Service)', value: 'Poor' },
];

const STATUS_OPTIONS = [
  { label: 'Available', value: 'Available' },
  { label: 'Booked', value: 'Booked' },
  { label: 'Assigned', value: 'Assigned' },
  { label: 'Under Maintenance', value: 'Under Maintenance' },
  { label: 'Retired', value: 'Retired' },
];

export const InventoryFormModal: React.FC<InventoryFormModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  initialData,
  isLoading,
}) => {
  const [uploadImage, { isLoading: isUploading }] = useUploadImageMutation();

  const [formData, setFormData] = useState<Partial<InventoryItem>>({
    name: '',
    asset_id: '',
    category: 'Laptops',
    description: '',
    brand_model: '',
    serial_number: '',
    quantity: 1,
    location: '',
    purchase_date: new Date().toISOString().slice(0, 10),
    purchase_cost: 0,
    currency: 'INR',
    condition_status: 'Good',
    image_url: '',
    status: 'Available',
    is_bookable: false,
    notes: '',
  });

  const [previewUrl, setPreviewUrl] = useState<string>('');

  useEffect(() => {
    if (initialData) {
      setFormData({
        ...initialData,
        currency: initialData.currency || 'INR',
        is_bookable: Boolean(initialData.is_bookable),
      });
      setPreviewUrl(initialData.image_url || '');
    } else {
      const randomSuffix = Math.floor(1000 + Math.random() * 9000);
      setFormData({
        name: '',
        asset_id: `AST-LAP-${randomSuffix}`,
        category: 'Laptops',
        description: '',
        brand_model: '',
        serial_number: '',
        quantity: 1,
        location: 'HQ - 3rd Floor',
        purchase_date: new Date().toISOString().slice(0, 10),
        purchase_cost: 0,
        currency: 'INR',
        condition_status: 'Good',
        image_url: '',
        status: 'Available',
        is_bookable: false,
        notes: '',
      });
      setPreviewUrl('');
    }
  }, [initialData, isOpen]);

  const handleGenerateAssetId = () => {
    const prefixMap: Record<string, string> = {
      Laptops: 'AST-LAP',
      Monitors: 'AST-MON',
      'Meeting Rooms': 'AST-ROM',
      Vehicles: 'AST-VEH',
      'Office Furniture': 'AST-FRN',
      Equipment: 'AST-EQP',
    };
    const prefix = prefixMap[formData.category || ''] || 'AST-ITM';
    const num = Math.floor(1000 + Math.random() * 9000);
    setFormData((prev) => ({ ...prev, asset_id: `${prefix}-${num}` }));
  };

  const handleImageFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const objectUrl = URL.createObjectURL(file);
    setPreviewUrl(objectUrl);

    showToast({
      severity: 'info',
      summary: 'Uploading...',
      detail: 'Uploading image to Hostinger storage.',
    });

    try {
      const res = await uploadImage({ file, category: 'general' }).unwrap();
      const serverUrl = res.data?.url;
      if (serverUrl) {
        setFormData((prev) => ({ ...prev, image_url: serverUrl }));
        showToast({
          severity: 'success',
          summary: 'Uploaded Successfully',
          detail: 'Asset image stored securely on server.',
        });
      }
    } catch {
      showToast({
        severity: 'error',
        summary: 'Upload Failed',
        detail: 'Failed to upload image. Please try again.',
      });
      setPreviewUrl(formData.image_url || '');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name?.trim()) {
      showToast({
        severity: 'warn',
        summary: 'Name Required',
        detail: 'Please provide an item or asset name.',
      });
      return;
    }

    if (!formData.asset_id?.trim()) {
      showToast({
        severity: 'warn',
        summary: 'Asset ID Required',
        detail: 'Every inventory item must have a unique Asset ID or SKU.',
      });
      return;
    }

    await onSubmit({
      ...formData,
      currency: formData.currency || 'INR',
      purchase_cost: parseFloat(String(formData.purchase_cost || 0)) || 0,
      quantity: parseInt(String(formData.quantity || 1), 10) || 1,
      is_bookable: Boolean(formData.is_bookable),
    });
  };

  return (
    <Dialog
      visible={isOpen}
      onHide={onClose}
      width="min(860px, 94vw)"
      header={
        <div className="flex items-center gap-3.5">
          <div className="w-11 h-11 rounded-2xl bg-primary/10 text-primary flex items-center justify-center shrink-0 border border-primary/20 shadow-xs">
            <Layers size={22} className="stroke-[2.2]" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-xl font-black text-foreground tracking-tight">
                {initialData ? 'Edit Inventory Asset' : 'Register New Inventory Asset'}
              </h2>
              {initialData?.asset_id && (
                <span className="text-[11px] font-mono font-bold px-2 py-0.5 rounded-md bg-surface-subtle text-muted border border-border-subtle">
                  {initialData.asset_id}
                </span>
              )}
            </div>
            <p className="text-xs text-muted font-medium mt-0.5">
              Track asset specs, location, and resource booking eligibility
            </p>
          </div>
        </div>
      }
      headerClassName="px-7 pt-6 pb-4 border-b border-border-subtle/80 bg-surface"
      className="rounded-3xl overflow-hidden shadow-2xl">
      <form onSubmit={handleSubmit} className="flex flex-col">
        {/* Scrollable Form Body with fixed height boundary */}
        <div className="max-h-[min(70vh,660px)] overflow-y-auto px-6 sm:px-8 py-6 space-y-6">
          {/* Section 1: Core Information */}
          <div className="space-y-4">
            <div className="flex items-center gap-2 text-xs font-black uppercase tracking-wider text-muted">
              <Tag size={13} className="text-primary" />
              <span>Core Identification</span>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-12 gap-4">
              <FormField
                label="Asset / Item Name"
                required
                id="inv-name"
                className="sm:col-span-7 mb-0">
                <Input
                  id="inv-name"
                  value={formData.name || ''}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="e.g. MacBook Pro 16 M3 Max"
                  className="h-11 rounded-xl"
                />
              </FormField>

              <FormField
                label="Unique Asset ID / SKU"
                required
                id="inv-asset-id"
                className="sm:col-span-5 mb-0">
                <div className="flex items-center gap-2">
                  <Input
                    id="inv-asset-id"
                    value={formData.asset_id || ''}
                    onChange={(e) => setFormData({ ...formData, asset_id: e.target.value })}
                    placeholder="e.g. AST-LAP-1029"
                    className="h-11 font-mono uppercase rounded-xl"
                  />
                  <Button
                    type="button"
                    variant="secondary"
                    onClick={handleGenerateAssetId}
                    title="Generate Unique Asset ID"
                    className="px-3! h-11! text-xs font-bold shrink-0 rounded-xl">
                    <RefreshCw size={14} className="mr-1" /> Auto
                  </Button>
                </div>
              </FormField>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <FormField label="Category" required id="inv-category" className="mb-0">
                <Select
                  id="inv-category"
                  options={CATEGORY_OPTIONS}
                  value={formData.category}
                  onChange={(e) => {
                    const newCat = e.value as string;
                    setFormData((prev) => ({ ...prev, category: newCat }));
                  }}
                />
              </FormField>

              <FormField label="Condition" required id="inv-condition" className="mb-0">
                <Select
                  id="inv-condition"
                  options={CONDITION_OPTIONS}
                  value={formData.condition_status}
                  onChange={(e) =>
                    setFormData({ ...formData, condition_status: e.value as InventoryCondition })
                  }
                />
              </FormField>

              <FormField label="Current Status" required id="inv-status" className="mb-0">
                <Select
                  id="inv-status"
                  options={STATUS_OPTIONS}
                  value={formData.status}
                  onChange={(e) => setFormData({ ...formData, status: e.value as InventoryStatus })}
                />
              </FormField>
            </div>
          </div>

          {/* Section 2: Bookable Resource Toggle Banner */}
          <div className="p-4 sm:p-4.5 rounded-2xl bg-gradient-to-r from-amber-500/10 via-orange-500/5 to-transparent border border-amber-500/30 flex items-start justify-between gap-4 transition-all">
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 rounded-xl bg-amber-500/15 text-amber-600 flex items-center justify-center shrink-0 mt-0.5 border border-amber-500/20">
                <Sparkles size={20} />
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-black text-foreground">
                    Available as a Bookable Resource
                  </span>
                  <span
                    className={`text-[10px] font-black uppercase tracking-wider px-2.5 py-0.5 rounded-full transition-colors ${
                      formData.is_bookable
                        ? 'bg-amber-500 text-white shadow-xs'
                        : 'bg-muted/15 text-muted'
                    }`}>
                    {formData.is_bookable ? 'BOOKABLE (ON)' : 'INVENTORY ONLY (OFF)'}
                  </span>
                </div>
                <p className="text-xs text-muted font-medium mt-1 leading-relaxed">
                  When enabled, employees can discover and reserve this resource via the Resource
                  Booking calendar. Overlapping reservations will be automatically prevented.
                </p>
              </div>
            </div>

            <div className="shrink-0 pt-1">
              <Switch
                checked={Boolean(formData.is_bookable)}
                onChange={(e) => setFormData({ ...formData, is_bookable: e.value })}
              />
            </div>
          </div>

          {/* Section 3: Hardware Specifications & Location */}
          <div className="space-y-4">
            <div className="flex items-center gap-2 text-xs font-black uppercase tracking-wider text-muted">
              <Cpu size={13} className="text-primary" />
              <span>Hardware & Allocation Details</span>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-12 gap-4">
              <FormField label="Brand / Model" id="inv-brand" className="sm:col-span-6 mb-0">
                <Input
                  id="inv-brand"
                  value={formData.brand_model || ''}
                  onChange={(e) => setFormData({ ...formData, brand_model: e.target.value })}
                  placeholder="e.g. Apple MacBook Pro 16"
                  className="h-11 rounded-xl"
                />
              </FormField>

              <FormField label="Serial Number" id="inv-serial" className="sm:col-span-6 mb-0">
                <Input
                  id="inv-serial"
                  value={formData.serial_number || ''}
                  onChange={(e) => setFormData({ ...formData, serial_number: e.target.value })}
                  placeholder="e.g. C02G901XMD6R"
                  className="h-11 font-mono uppercase rounded-xl"
                />
              </FormField>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-12 gap-4">
              <FormField label="Quantity" id="inv-quantity" className="sm:col-span-3 mb-0">
                <Input
                  id="inv-quantity"
                  type="number"
                  min="1"
                  value={String(formData.quantity || 1)}
                  onChange={(e) =>
                    setFormData({ ...formData, quantity: parseInt(e.target.value, 10) || 1 })
                  }
                  className="h-11 rounded-xl text-center"
                />
              </FormField>

              <FormField label="Location" id="inv-location" className="sm:col-span-5 mb-0">
                <Input
                  id="inv-location"
                  value={formData.location || ''}
                  onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                  placeholder="e.g. HQ - 3rd Floor Lab"
                  className="h-11 rounded-xl"
                />
              </FormField>

              <FormField label="Purchase Date" id="inv-pdate" className="sm:col-span-4 mb-0">
                <Input
                  id="inv-pdate"
                  type="date"
                  value={formData.purchase_date || ''}
                  onChange={(e) => setFormData({ ...formData, purchase_date: e.target.value })}
                  className="h-11 rounded-xl"
                />
              </FormField>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-12 gap-4">
              <div className="sm:col-span-8 flex flex-col gap-1.5">
                <label
                  htmlFor="inv-pcost"
                  className="text-sm font-semibold text-foreground/80 ml-1">
                  Purchase Cost / Valuation (Universal Currency)
                </label>
                <div className="flex items-center gap-2">
                  <div className="w-56 shrink-0">
                    <Select
                      id="inv-currency"
                      options={CURRENCY_SELECT_OPTIONS}
                      value={formData.currency || 'INR'}
                      onChange={(e) => setFormData({ ...formData, currency: e.value as string })}
                      className="h-11 rounded-xl"
                      placeholder="Currency"
                    />
                  </div>
                  <div className="relative flex-1">
                    <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-muted font-bold text-xs pointer-events-none select-none">
                      {getCurrencySymbol(formData.currency || 'INR')}
                    </span>
                    <Input
                      id="inv-pcost"
                      type="number"
                      step="0.01"
                      min="0"
                      value={String(formData.purchase_cost || 0)}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          purchase_cost: parseFloat(e.target.value) || 0,
                        })
                      }
                      placeholder="0.00"
                      className="h-11 rounded-xl font-mono pl-9"
                    />
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Section 4: Asset Visual / Image */}
          <div className="space-y-2">
            <div className="flex items-center gap-2 text-xs font-black uppercase tracking-wider text-muted">
              <ImageIcon size={13} className="text-primary" />
              <span>Asset Visual / Photograph</span>
            </div>

            <div className="p-4 rounded-2xl border border-dashed border-border-subtle bg-surface-subtle/40 flex flex-col sm:flex-row items-center gap-4">
              {previewUrl ? (
                <div className="w-24 h-24 rounded-2xl overflow-hidden border border-border-subtle shrink-0 relative group bg-surface">
                  <img
                    src={resolveImageUrl(previewUrl)}
                    alt="Asset Preview"
                    className="w-full h-full object-cover"
                  />
                  <button
                    type="button"
                    onClick={() => {
                      setPreviewUrl('');
                      setFormData({ ...formData, image_url: '' });
                    }}
                    className="absolute inset-0 bg-black/70 text-white opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-1 text-xs font-bold">
                    <Trash2 size={16} />
                    <span>Remove</span>
                  </button>
                </div>
              ) : (
                <div className="w-24 h-24 rounded-2xl bg-surface flex flex-col items-center justify-center text-muted border border-border-subtle shrink-0">
                  <UploadCloud size={24} className="text-muted/60 mb-1" />
                  <span className="text-[10px] font-bold text-muted/80">No Image</span>
                </div>
              )}

              <div className="flex-1 w-full flex flex-col gap-2.5">
                <div className="flex items-center gap-3">
                  <label className="cursor-pointer inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-primary text-white text-xs font-bold hover:bg-primary/90 transition-all shadow-xs">
                    <UploadCloud size={14} />
                    <span>{isUploading ? 'Uploading...' : 'Choose Image File'}</span>
                    <input
                      type="file"
                      accept="image/*"
                      className="hidden"
                      onChange={handleImageFileChange}
                      disabled={isUploading}
                    />
                  </label>
                  <span className="text-[11px] text-muted font-bold">or direct URL link</span>
                </div>
                <Input
                  value={formData.image_url || ''}
                  onChange={(e) => {
                    setFormData({ ...formData, image_url: e.target.value });
                    setPreviewUrl(e.target.value);
                  }}
                  placeholder="https://... direct image URL"
                  className="h-10 text-xs rounded-xl"
                />
              </div>
            </div>
          </div>

          {/* Section 5: Description & Internal Notes */}
          <div className="space-y-4">
            <div className="flex items-center gap-2 text-xs font-black uppercase tracking-wider text-muted">
              <FileText size={13} className="text-primary" />
              <span>Documentation & Notes</span>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <FormField label="Asset Description" id="inv-desc" className="mb-0">
                <Textarea
                  id="inv-desc"
                  rows={3}
                  value={formData.description || ''}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="Technical specifications, components, and hardware breakdown..."
                  className="rounded-xl min-h-[90px]! text-xs leading-relaxed"
                />
              </FormField>

              <FormField
                label="Internal Notes & Maintenance Instructions"
                id="inv-notes"
                className="mb-0">
                <Textarea
                  id="inv-notes"
                  rows={3}
                  value={formData.notes || ''}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  placeholder="Warranty expiry, maintenance cadence, service history, handling notes..."
                  className="rounded-xl min-h-[90px]! text-xs leading-relaxed"
                />
              </FormField>
            </div>
          </div>
        </div>

        {/* Sticky Footer with Actions */}
        <div className="px-6 sm:px-8 py-4 bg-surface-elevated/95 backdrop-blur-md border-t border-border-subtle flex items-center justify-between gap-4 sticky bottom-0 z-10">
          <div className="hidden sm:flex items-center gap-2.5 text-xs text-muted font-medium">
            <span
              className={`w-2 h-2 rounded-full ${
                formData.is_bookable ? 'bg-amber-500' : 'bg-emerald-500'
              }`}
            />
            <span>
              {formData.is_bookable
                ? 'Bookable Resource enabled'
                : 'Registered as standard inventory asset'}
            </span>
            {Number(formData.purchase_cost || 0) > 0 && (
              <span className="px-2.5 py-0.5 rounded-lg bg-surface-subtle font-black text-foreground border border-border-subtle flex items-center gap-1 shadow-2xs">
                <span className="text-muted font-bold text-[10px]">Valuation:</span>
                <span>{formatPriceWithCurrency(formData.purchase_cost, formData.currency)}</span>
              </span>
            )}
          </div>

          <div className="flex items-center gap-3 ml-auto">
            <Button
              type="button"
              variant="ghost"
              onClick={onClose}
              className="px-5 py-2.5 rounded-xl font-bold text-xs h-10">
              Cancel
            </Button>
            <Button
              type="submit"
              variant="primary"
              disabled={isLoading || isUploading}
              className="px-6 py-2.5 rounded-xl font-black text-xs h-10 shadow-lg shadow-primary/20 flex items-center gap-1.5">
              <CheckCircle2 size={15} />
              <span>
                {isLoading ? 'Saving...' : initialData ? 'Update Asset' : 'Save to Inventory'}
              </span>
            </Button>
          </div>
        </div>
      </form>
    </Dialog>
  );
};

import { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import { useAuth } from '@/hooks/useAuth';
import { usePermission } from '@/hooks/usePermission';
import { isSuperAdmin, getUserRoles } from '@/utils/pagePermissions';
import { usePendingUsers } from '../settings/hooks/usePendingUsers';
import { useGetRolesQuery } from '@/store/api/roleApiSlice';
import type { User } from '@/types/auth';
import type { UserRole } from '@/config/navItems';

function ApprovalPage() {
  const { user: currentAuthUser } = useAuth();
  const { isSuperadmin: isRbacSuperadmin, can } = usePermission();

  const isAuthorized = useMemo(() => {
    if (isSuperAdmin(currentAuthUser) || isRbacSuperadmin) return true;
    if (can('user:approve') || can('user:invite') || can('user:manage') || can('user:view')) return true;
    const userRoles = getUserRoles(currentAuthUser);
    return userRoles.some((r) => ['SuperAdmin', 'Admin', 'HrAdmin'].includes(r));
  }, [currentAuthUser, isRbacSuperadmin, can]);

  const { data: backendRolesData } = useGetRolesQuery();

  const userroles = useMemo(() => {
    if (backendRolesData?.data && backendRolesData.data.length > 0) {
      return backendRolesData.data.map((r) => r.name);
    }
    return ['SuperAdmin', 'Admin', 'HrAdmin', 'Manager', 'Employee'];
  }, [backendRolesData]);

  const {
    pendingUsers,
    logs,
    isLoading,
    isApproving,
    isRejecting,
    isSendingInvite,
    handleApproveUser,
    handleRejectUser,
    handleSendInvite,
  } = usePendingUsers();

  const [selectedRoles, setSelectedRoles] = useState<Record<number, UserRole>>({});

  // Invitation State
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteRole, setInviteRole] = useState<UserRole>('Employee');
  const [inviteStatus, setInviteStatus] = useState<{
    type: 'success' | 'error';
    message: string;
  } | null>(null);
  const [lastInviteTime, setLastInviteTime] = useState<number>(0);

  const handleRoleChange = (userId: number, role: UserRole) => {
    setSelectedRoles((prev) => ({
      ...prev,
      [userId]: role,
    }));
  };

  const handleSubmitInvite = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inviteEmail) return;

    // Rate-limit invitation dispatches: minimum 10 seconds between invites
    const now = Date.now();
    if (now - lastInviteTime < 10000) {
      setInviteStatus({
        type: 'error',
        message: 'Rate limit active: Please wait 10 seconds before dispatching another invitation.',
      });
      return;
    }

    // Basic email format check
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(inviteEmail.trim())) {
      setInviteStatus({
        type: 'error',
        message: 'Please provide a valid recipient email address.',
      });
      return;
    }

    setInviteStatus(null);
    setLastInviteTime(now);
    const success = await handleSendInvite(inviteEmail.trim(), inviteRole);

    if (success) {
      setInviteStatus({
        type: 'success',
        message: `Temporary credentials & login link sent to ${inviteEmail}`,
      });
      setInviteEmail('');
    } else {
      setInviteStatus({
        type: 'error',
        message: 'Failed to send invitation email. Please verify backend SMTP settings.',
      });
    }
  };

  if (!isAuthorized) {
    return (
      <div className="p-8 text-center bg-white rounded-2xl border border-border-subtle shadow-sm my-8">
        <h3 className="text-base font-bold text-foreground">Access Restricted</h3>
        <p className="text-xs text-muted-foreground mt-1">
          You do not have administrative privileges to manage user account approvals or dispatch invitations.
        </p>
      </div>
    );
  }

  if (isLoading) {
    return <div className="p-6 text-xs text-muted-foreground">Loading approval data...</div>;
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
      className="space-y-6">
      {/* SECTION 1: INVITATION EMAIL DISPATCH */}
      <div className="bg-white rounded-2xl border border-border-subtle shadow-soft p-6">
        <h2 className="text-lg font-black text-foreground">Invite New User</h2>
        <p className="text-xs text-muted-foreground mb-4">
          Send an automated email with temporary credentials and first-time login instructions
          directly to the recipient.
        </p>

        <form onSubmit={handleSubmitInvite} className="flex flex-col md:flex-row gap-3">
          <input
            type="email"
            placeholder="Recipient Email"
            value={inviteEmail}
            onChange={(e) => setInviteEmail(e.target.value)}
            required
            className="flex-1 text-xs border border-border-subtle rounded-lg px-3 py-2 outline-none focus:border-foreground"
          />

          <select
            value={inviteRole}
            onChange={(e) => setInviteRole(e.target.value as UserRole)}
            className="text-xs border border-border-subtle rounded-lg px-3 py-2 outline-none">
            {userroles.map((role) => (
              <option key={role} value={role}>
                {role}
              </option>
            ))}
          </select>

          <button
            type="submit"
            disabled={isSendingInvite}
            className="px-4 py-2 rounded-lg text-xs font-bold bg-foreground text-background hover:opacity-90 transition-all disabled:opacity-50">
            {isSendingInvite ? 'Sending Email...' : 'Send Invitation'}
          </button>
        </form>

        {inviteStatus && (
          <div
            className={`mt-4 p-3 rounded-xl border text-xs font-medium ${
              inviteStatus.type === 'success'
                ? 'bg-green-500/10 text-green-700 border-green-500/20'
                : 'bg-red-500/10 text-red-700 border-red-500/20'
            }`}>
            {inviteStatus.message}
          </div>
        )}
      </div>

      {/* SECTION 2: PENDING USERS APPROVAL SECTION */}
      <div className="bg-white rounded-2xl border border-border-subtle shadow-soft overflow-hidden">
        <div className="p-6 border-b border-border-subtle">
          <h2 className="text-lg font-black text-foreground">Pending Users</h2>
          <p className="text-xs text-muted-foreground">Approve or reject new user registrations.</p>
        </div>

        <div className="p-6 flex flex-col gap-4">
          {pendingUsers.length === 0 ? (
            <div className="text-center text-sm text-muted py-6">No pending users found</div>
          ) : (
            pendingUsers.map((user: User) => (
              <div
                key={user.id}
                className="flex items-center justify-between p-4 rounded-xl border border-border-subtle hover:bg-surface-subtle/50 transition-all">
                <div className="flex items-center gap-4">
                  <img
                    src={user.image_url || '/avatar.png'}
                    className="w-12 h-12 rounded-full object-cover border"
                  />

                  <div>
                    <h3 className="font-bold text-foreground">{user.username}</h3>
                    <p className="text-xs text-muted">{user.email}</p>
                    <p className="text-xs text-muted">
                      {user.department} • {user.role}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-3">
                  <select
                    value={selectedRoles[user.id] ?? ''}
                    onChange={(e) => handleRoleChange(user.id, e.target.value as UserRole)}
                    className="text-xs border rounded-lg px-3 py-2">
                    <option value="">Select Role</option>
                    {userroles.map((role) => (
                      <option key={role} value={role}>
                        {role}
                      </option>
                    ))}
                  </select>

                  <div className="flex gap-2">
                    <button
                      disabled={isApproving}
                      onClick={() => {
                        const role = selectedRoles[user.id];
                        if (!role) {
                          alert('Please select a role before approving');
                          return;
                        }
                        handleApproveUser(user.id, role);
                      }}
                      className="px-4 py-2 rounded-lg text-xs font-bold bg-green-500/10 text-green-600 border border-green-500/20 hover:bg-green-500 hover:text-white transition-all disabled:opacity-50">
                      Approve
                    </button>

                    <button
                      disabled={isRejecting}
                      onClick={() => handleRejectUser(user.id)}
                      className="px-4 py-2 rounded-lg text-xs font-bold bg-red-500/10 text-red-600 border border-red-500/20 hover:bg-red-500 hover:text-white transition-all disabled:opacity-50">
                      Reject
                    </button>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* SECTION 3: APPROVAL/REJECTION AUDIT LOG TABLE */}
      <div className="bg-white rounded-2xl border border-border-subtle shadow-soft overflow-hidden">
        <div className="p-6 border-b border-border-subtle flex items-center justify-between">
          <div>
            <div className="flex items-center gap-2.5">
              <h2 className="text-lg font-black text-foreground">Approval Logs</h2>
              {/* <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/10 text-emerald-600 border border-emerald-500/20">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                Live Auto-Sync
              </span> */}
            </div>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-border-subtle bg-surface-subtle/30 text-xs text-muted-foreground font-semibold">
                <th className="p-4">Target User</th>
                <th className="p-4">Action</th>
                <th className="p-4">Assigned Role</th>
                <th className="p-4">Action By</th>
                <th className="p-4">Date & Time</th>
              </tr>
            </thead>

            <tbody className="divide-y divide-border-subtle text-xs">
              {!Array.isArray(logs) || logs.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-6 text-center text-muted-foreground">
                    No approval logs available.
                  </td>
                </tr>
              ) : (
                logs.map((log) => {
                  const targetName =
                    log.targetUser?.name ||
                    (log as any).target_user_name ||
                    log.targetUser?.email ||
                    (log as any).target_user_email ||
                    'N/A';
                  const targetEmail = log.targetUser?.email || (log as any).target_user_email || '';
                  const role = log.assignedRole || (log as any).assigned_role || '—';
                  const actionRaw = (
                    log.action ||
                    (log as any).action ||
                    'INVITATION_SENT'
                  ).toUpperCase();
                  const actorName = log.actionBy?.name || (log as any).action_by_name || 'System';
                  const actorEmail = log.actionBy?.email || (log as any).action_by_email || '';

                  const rawDate = log.timestamp || (log as any).created_at;
                  let formattedDate = '—';
                  if (rawDate) {
                    const parsed = new Date(rawDate);
                    if (!isNaN(parsed.getTime())) {
                      formattedDate = parsed.toLocaleString('en-US', {
                        month: 'short',
                        day: 'numeric',
                        year: 'numeric',
                        hour: 'numeric',
                        minute: '2-digit',
                        hour12: true,
                      });
                    }
                  }

                  let badgeStyle = 'bg-primary/10 text-primary border border-primary/20';
                  let displayAction = actionRaw.replace(/_/g, ' ');
                  if (actionRaw === 'APPROVED') {
                    badgeStyle = 'bg-green-500/10 text-green-600 border border-green-500/20';
                    displayAction = 'Approved';
                  } else if (actionRaw === 'REJECTED') {
                    badgeStyle = 'bg-red-500/10 text-red-600 border border-red-500/20';
                    displayAction = 'Rejected';
                  } else if (
                    actionRaw === 'INVITATION' ||
                    actionRaw === 'INVITATION_SENT' ||
                    actionRaw === 'INVITED'
                  ) {
                    badgeStyle = 'bg-blue-500/10 text-blue-600 border border-blue-500/20';
                    displayAction = 'Invitation';
                  } else if (actionRaw === 'PENDING') {
                    badgeStyle = 'bg-amber-500/10 text-amber-600 border border-amber-500/20';
                    displayAction = 'Pending';
                  }

                  return (
                    <tr key={log.id} className="hover:bg-surface-subtle/40 transition-all">
                      <td className="p-4">
                        <div className="font-bold text-foreground">{targetName}</div>
                        {targetEmail && (
                          <div className="text-muted-foreground text-[11px]">{targetEmail}</div>
                        )}
                      </td>
                      <td className="p-4">
                        <span
                          className={`px-2.5 py-1 rounded-md text-[10px] font-black uppercase tracking-wider inline-block ${badgeStyle}`}>
                          {displayAction}
                        </span>
                      </td>
                      <td className="p-4 font-medium text-foreground">{role}</td>
                      <td className="p-4">
                        <div className="font-semibold text-foreground">{actorName}</div>
                        {actorEmail && (
                          <div className="text-muted-foreground text-[11px]">{actorEmail}</div>
                        )}
                      </td>
                      <td className="p-4 text-muted-foreground font-medium">{formattedDate}</td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </motion.div>
  );
}

export default ApprovalPage;

