              }
              dropdownRender={(menu) => (
                <div>
                  {menu}
                  <Divider style={{ margin: '4px 0' }} />
                  <div
                    className="px-3 py-2 flex items-center justify-between hover:bg-primary/5 cursor-pointer rounded-b transition-colors"
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={() => {
                      setShowEditProfileModal(false);
                      setActiveTab('Offices & Branches');
                      setAutoOpenCreate(true);
                    }}
                  >
                    <span className="text-xs font-bold text-primary flex items-center gap-1.5">
                      <Plus size={14} />
                      Add New Location
                    </span>
                    <span className="text-[10px] text-muted font-medium">Go to Offices & Branches</span>
                  </div>
                </div>
              )}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t border-border-subtle">
            <Button
              variant="ghost"
              label="Cancel"
              onClick={() => setShowEditProfileModal(false)}
              className="rounded-md!"
            />
            <Button
              label={isUpdatingProfile ? 'Saving...' : 'Save Changes'}
              disabled={isUpdatingProfile}
              onClick={handleSaveProfile}
              icon="pi pi-check"
              className="rounded-md! px-8!"
            />
          </div>
        </div>
      </Dialog>

      {/* ── UPLOAD DOCUMENT MODAL ── */}
      <Dialog
        visible={showUploadModal}
        onHide={() => setShowUploadModal(false)}
        header="Upload Document to Vault"
        modal
        className="w-full max-w-xl mx-4"
        contentClassName="p-8"
        headerClassName="px-8 pt-8 pb-4 text-xl font-black tracking-tight border-none"
        pt={{
          root: { className: 'rounded-2xl overflow-hidden border-none shadow-2xl bg-white' },
          mask: { className: 'backdrop-blur-md bg-black/40' },
        }}>
        <div className="flex flex-col gap-5">
          <div className="flex flex-col gap-2">
            <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
              Document Title
            </label>
            <Input
              placeholder="e.g. ISO 27001 Re-certification 2026"
              value={uploadDocForm.title}
              onChange={(e) => setUploadDocForm({ ...uploadDocForm, title: e.target.value })}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-2">
              <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
                Category
              </label>
              <Select
                options={[
                  { label: 'Certificate', value: 'Certificate' },
                  { label: 'Policy', value: 'Policy' },
                  { label: 'Legal Agreement', value: 'Legal' },
                  { label: 'Tax & Compliance', value: 'Tax' },
                  { label: 'Handbook', value: 'Handbook' },
                ]}
                value={uploadDocForm.category}
                onChange={(e) => setUploadDocForm({ ...uploadDocForm, category: e.value })}
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
                Visibility Level
              </label>
              <Select
                options={[
                  { label: 'Public (All Staff)', value: 'Public' },
                  { label: 'Private (Admins & C-Suite)', value: 'Private' },
                ]}
                value={uploadDocForm.visibility}
                onChange={(e) => setUploadDocForm({ ...uploadDocForm, visibility: e.value })}
              />
            </div>
          </div>

          <div className="flex flex-col gap-2">
            <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
              Description / Notes
            </label>
            <Input
              placeholder="Brief summary of document purpose..."
              value={uploadDocForm.description}
              onChange={(e) => setUploadDocForm({ ...uploadDocForm, description: e.target.value })}
            />
          </div>

          {/* File Picker */}
          <div className="flex flex-col gap-2">
            <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
              Select File (PDF, DOCX, PNG)
            </label>
            <label className="border-2 border-dashed border-border-subtle hover:border-primary/50 rounded-2xl p-6 flex flex-col items-center justify-center gap-2 cursor-pointer transition-colors bg-surface-subtle/50">
              <Upload size={28} className="text-primary" />
              <span className="text-xs font-semibold text-foreground">
                {selectedFile ? selectedFile.name : 'Click or drag file to attach'}
              </span>
              <span className="text-[11px] text-muted">Max file size 25MB</span>
              <input
                type="file"
                className="hidden"
                onChange={(e) => {
                  if (e.target.files?.[0]) setSelectedFile(e.target.files[0]);
                }}
              />
            </label>
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t border-border-subtle">
            <Button
              variant="ghost"
              label="Cancel"
              onClick={() => setShowUploadModal(false)}
              className="rounded-md!"
            />
            <Button
              label={isUploading ? 'Uploading...' : 'Upload & Index'}
              disabled={isUploading}
              onClick={handleUploadSubmit}
              icon="pi pi-upload"
              className="rounded-md! px-8!"
            />
          </div>
        </div>
      </Dialog>

      {/* ── DELETE DOCUMENT CONFIRMATION ── */}
      <ConfirmDialog
        visible={!!deleteDocId}
        onHide={() => setDeleteDocId(null)}
        header="Delete Document from Vault"
        message="Are you sure you want to delete this document? Any active employee links to this file will be permanently invalidated."
        accept={handleConfirmDelete}
        reject={() => setDeleteDocId(null)}
      />
    </div>
  );
}

import React, { useEffect, useMemo } from 'react';
import { Modal, Form, Select, Input, DatePicker, Alert, Button, Badge } from 'antd';
import dayjs from 'dayjs';
import { Users } from 'lucide-react';
import {
  useBulkHandoverMutation,
  type HierarchyNodeUser,
} from '@/store/api/organizationApiSlice';
import { showToast } from '@/components/ui/composed/Toast.utils';

interface BulkHandoverModalProps {
  open: boolean;
  onClose: () => void;
  preselectedManagerId?: number | null;
  flatUsers: HierarchyNodeUser[];
  onSuccess?: () => void;
}

export const BulkHandoverModal: React.FC<BulkHandoverModalProps> = ({
  open,
  onClose,
  preselectedManagerId,
  flatUsers,
  onSuccess,
}) => {
  const [form] = Form.useForm();
  const [bulkHandover, { isLoading }] = useBulkHandoverMutation();

  const fromManagerId = Form.useWatch('fromManagerId', form) || preselectedManagerId;
  const toManagerId = Form.useWatch('toManagerId', form);

  // Managers with reports
  const managersWithReports = useMemo(() => {
    return flatUsers.filter((u) => u.directReports && u.directReports.length > 0);
  }, [flatUsers]);

  // Current direct reports of fromManager
  const affectedReports = useMemo(() => {
    if (!fromManagerId) return [];
    const mgr = flatUsers.find((u) => u.id === fromManagerId);
    return mgr?.directReports || [];
  }, [fromManagerId, flatUsers]);

  useEffect(() => {
    if (open) {
      form.setFieldsValue({
        fromManagerId: preselectedManagerId || undefined,
        toManagerId: undefined,
        reason: '',
        effectiveDate: dayjs(),
      });
    }
  }, [open, preselectedManagerId, form]);

  const handleSubmit = async (values: any) => {
    try {
      const effectiveDateStr = values.effectiveDate
        ? dayjs(values.effectiveDate).format('YYYY-MM-DD')
        : undefined;

      const res = await bulkHandover({
        fromManagerId: Number(values.fromManagerId),
        toManagerId: Number(values.toManagerId),
        reason: values.reason?.trim(),
        effectiveDate: effectiveDateStr,
      }).unwrap();

      showToast({
        severity: 'success',
        summary: 'Handover Completed',
        detail: res.message || 'Team successfully transferred',
      });
      onClose();
      onSuccess?.();
    } catch (err: any) {
      showToast({
        severity: 'error',
        summary: 'Handover Failed',
        detail: err?.data?.message || 'Could not complete team handover',
      });
    }
  };

  return (
    <Modal
      title={
        <div className="flex items-center gap-2 text-foreground font-black">
          <Users size={18} className="text-primary" />
          <span>Bulk Team Handover</span>
        </div>
      }
      open={open}
      onCancel={onClose}
      footer={null}
      destroyOnClose
      width={600}>
      <Form form={form} layout="vertical" onFinish={handleSubmit} className="pt-2">
        <Alert
          message="Atomic Team Transfer"
          description="Transfers all direct reports from Manager A to Manager B simultaneously. Any existing sub-teams and subordinate tiers remain preserved."
          type="info"
          showIcon
          className="mb-4"
        />

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <Form.Item
            label="Source Manager (From)"
            name="fromManagerId"
            rules={[{ required: true, message: 'Select outgoing manager' }]}>
            <Select
              showSearch
              placeholder="Select current manager..."
              filterOption={(input, opt) =>
                (opt?.label ?? '').toLowerCase().includes(input.toLowerCase())
              }
              options={managersWithReports.map((m) => ({
                value: m.id,
                label: `${m.username} (${m.directReports.length} direct reports)`,
              }))}
            />
          </Form.Item>

          <Form.Item
            label="Destination Manager (To)"
            name="toManagerId"
            rules={[{ required: true, message: 'Select destination manager' }]}>
            <Select
              showSearch
              placeholder="Select receiving manager..."
              filterOption={(input, opt) =>
