import { useState, useEffect, useCallback, useMemo } from 'react';
import type { HierarchyNodeUser } from '@/store/api/organizationApiSlice';
import type { EmployeeInput } from '../types';

interface UseOrgNavigationProps {
  isOpen: boolean;
  employee: EmployeeInput | null | undefined;
  resolveUser: (target: EmployeeInput | null | undefined) => HierarchyNodeUser | null;
  flatUsersById: Map<number, HierarchyNodeUser>;
}

export const useOrgNavigation = ({
  isOpen,
  employee,
  resolveUser,
  flatUsersById,
}: UseOrgNavigationProps) => {
  const [focusedId, setFocusedId] = useState<number | null>(null);
  const [inspectedId, setInspectedId] = useState<number | null>(null);
  const [navHistory, setNavHistory] = useState<number[]>([]);
  const [showDetail, setShowDetail] = useState(true);
  const [expandedSubTrees, setExpandedSubTrees] = useState<Record<number, boolean>>({});

  useEffect(() => {
    if (isOpen && employee) {
      const u = resolveUser(employee);
      if (u) {
        setFocusedId(u.id);
        setInspectedId(u.id);
      }
      setNavHistory([]);
      setExpandedSubTrees({});
    }
  }, [isOpen, employee, resolveUser]);

  const focusedNode = useMemo(
    () =>
      focusedId ? flatUsersById.get(focusedId) || resolveUser(focusedId) : resolveUser(employee),
    [focusedId, employee, flatUsersById, resolveUser]
  );

  const inspectedNode = useMemo(
    () => (inspectedId ? flatUsersById.get(inspectedId) || resolveUser(inspectedId) : focusedNode),
    [inspectedId, focusedNode, flatUsersById, resolveUser]
  );

  const handleFocus = useCallback(
    (u: HierarchyNodeUser) => {
      if (u.id === focusedNode?.id) {
        setInspectedId(u.id);
        return;
      }
      if (focusedNode) setNavHistory((p) => [...p, focusedNode.id]);
      setFocusedId(u.id);
      setInspectedId(u.id);
    },
    [focusedNode]
  );

  const handleBack = useCallback(() => {
    if (!navHistory.length) return;
    const prev = navHistory[navHistory.length - 1];
    setNavHistory((p) => p.slice(0, -1));
    setFocusedId(prev);
    setInspectedId(prev);
  }, [navHistory]);

  const handleInspect = useCallback((u: HierarchyNodeUser) => {
    setInspectedId(u.id);
    setShowDetail(true);
  }, []);

  const toggleSubTree = useCallback((id: number, e: React.MouseEvent) => {
    e.stopPropagation();
    setExpandedSubTrees((p) => ({ ...p, [id]: !p[id] }));
  }, []);

  return {
    focusedNode,
    inspectedNode,
    navHistory,
    showDetail,
    setShowDetail,
    expandedSubTrees,
    handleFocus,
    handleBack,
    handleInspect,
    toggleSubTree,
  };
};

import React, { useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import type { EmployeeModelViewModalProps } from './types';
import { useOrgModel } from './hooks/useOrgModel';
import { useResolveUser } from './hooks/useResolveUser';
import { useOrgRelations } from './hooks/useOrgRelations';
import { useOrgLayout } from './hooks/useOrgLayout';
import { usePanZoom } from './hooks/usePanZoom';
import { useInspectedProfile } from './hooks/useInspectedProfile';
import { useModalBehavior } from './hooks/useModalBehavior';
import { useCopyToClipboard } from './hooks/useCopyToClipboard';
import { useOrgNavigation } from './hooks/useOrgNavigation';
import { ModalHeader } from './components/ModalHeader';
import { TreeCanvas } from './components/TreeCanvas';
import { DetailPanel } from './components/detail/DetailPanel';

export const EmployeeModelViewModal: React.FC<EmployeeModelViewModalProps> = ({
  isOpen,
  onClose,
  employee,
}) => {
  const navigate = useNavigate();
  const containerRef = useRef<HTMLDivElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);

  const { flatUsers, flatUsersById, childrenByManagerId, dbUsers, offices, companyProfile, isLoadingHierarchy } =
    useOrgModel();
  const resolveUser = useResolveUser(flatUsers, flatUsersById, dbUsers);
  useModalBehavior(isOpen, onClose, modalRef);
  const { copied: copiedEmail, copy: copyEmail } = useCopyToClipboard();

  const {
    focusedNode, inspectedNode, navHistory, showDetail, setShowDetail, expandedSubTrees,
    handleFocus, handleBack, handleInspect, toggleSubTree,
  } = useOrgNavigation({ isOpen, employee, resolveUser, flatUsersById });

  const relations = useOrgRelations({ focusedNode, flatUsers, flatUsersById, childrenByManagerId, resolveUser });
  const layout = useOrgLayout({ focusedNode, ...relations }, expandedSubTrees);
  const panZoom = usePanZoom({ containerRef, bounds: layout.bounds, centralPos: layout.centralPos, isOpen });
  const profile = useInspectedProfile({
    inspectedNode, dbUsers, offices, companyProfile, flatUsersById, childrenByManagerId, resolveUser,
  });

  useEffect(() => {
    if (isOpen && focusedNode && containerRef.current) {
      const observer = new ResizeObserver(() => panZoom.handleFit());
      observer.observe(containerRef.current);
      return () => observer.disconnect();
    }
  }, [isOpen, focusedNode, panZoom.handleFit]);

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-2 sm:p-4 md:p-6 bg-slate-950/45 backdrop-blur-[2px] animate-in fade-in duration-200 select-none font-sans"
      onClick={onClose}
    >
      <div
        ref={modalRef}
        role="dialog"
        aria-modal="true"
        aria-label="Employee Organizational Model"
        tabIndex={-1}
        className="w-full max-w-7xl h-[96vh] sm:h-[90vh] max-h-[940px] bg-white rounded-2xl sm:rounded-3xl shadow-2xl border border-slate-200/90 flex flex-col overflow-hidden animate-in zoom-in-95 duration-200 relative focus:outline-none"
        onClick={(e) => e.stopPropagation()}
      >
        <ModalHeader
          focusedNode={focusedNode}
          navigationHistoryLength={navHistory.length}
          showDetailPanel={showDetail}
          onBackNavigation={handleBack}
          onToggleDetailPanel={() => setShowDetail((p) => !p)}
          onViewFullTree={() => { onClose(); navigate('/org?tab=Organization+Hierarchy'); }}
          onClose={onClose}
        />
        <div className="flex-1 flex overflow-hidden relative">
          <TreeCanvas
            containerRef={containerRef}
            layout={layout}
            pan={panZoom.pan}
            zoom={panZoom.zoom}
            isLoading={isLoadingHierarchy}
            showDetailPanel={showDetail && Boolean(inspectedNode)}
            focusedNode={focusedNode}
            relations={{ focusedNode, ...relations }}
            expandedSubTrees={expandedSubTrees}
            inspectedUserId={inspectedNode?.id ?? null}
            resolvedOffice={profile.resolvedOffice}
            joinDateInfo={profile.joinDate}
            onPointerDown={panZoom.handlePointerDown}
            onPointerMove={panZoom.handlePointerMove}
            onPointerUp={panZoom.handlePointerUp}
            onInspectUser={handleInspect}
            onFocusUser={handleFocus}
            onToggleSubTree={toggleSubTree}
            onZoomIn={panZoom.zoomIn}
            onZoomOut={panZoom.zoomOut}
            onFit={panZoom.handleFit}
            onCenter={panZoom.handleCenter}
          />
          {showDetail && inspectedNode && (
            <>
              <div
                className="lg:hidden absolute inset-0 bg-slate-950/20 backdrop-blur-[1px] z-20"
                onClick={() => setShowDetail(false)}
              />
              <DetailPanel
                inspectedNode={inspectedNode}
                isCentral={inspectedNode.id === focusedNode?.id}
                resolvedOffice={profile.resolvedOffice}
                joinDateInfo={profile.joinDate}
                copiedEmail={copiedEmail}
                manager={profile.inspectedManager}
                directReports={profile.inspectedReports}
                peers={relations.peers}
                skills={profile.skills}
                dbUserStatus={profile.inspectedDbUser?.status}
                onSetCentral={() => handleFocus(inspectedNode)}
                onClosePanel={() => setShowDetail(false)}
                onScheduleClick={() => { onClose(); navigate(`/calendar?user=${encodeURIComponent(inspectedNode.username)}`); }}
                onCopyEmail={() => copyEmail(inspectedNode.email, `Copied ${inspectedNode.email} to clipboard!`)}
                onInspectUser={handleInspect}
              />
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default EmployeeModelViewModal;

import React, { useState } from 'react';
import {
  Table,
  Tag,
  Select,
  DatePicker,
  Button,
  Tooltip,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import dayjs from 'dayjs';
import {
  RefreshCw,
  ArrowRight,
  UserCheck,
  UserMinus,
  Users,
  Network,
  GitCommit,
  Building2,
} from 'lucide-react';
import {
  useGetHierarchyAuditTrailQuery,
  type HierarchyAuditLogItem,
  type HierarchyNodeUser,
} from '@/store/api/organizationApiSlice';

interface HierarchyAuditTrailViewProps {
  flatUsers: HierarchyNodeUser[];
}

const ACTION_TYPE_OPTIONS = [
  { value: '', label: 'All Action Types' },
  { value: 'ASSIGN', label: 'ASSIGN (Change Manager)' },
  { value: 'REPORTING_HIERARCHY_UPDATED', label: 'REPORTING_HIERARCHY_UPDATED' },
  { value: 'BULK_HANDOVER', label: 'BULK_HANDOVER (Team Transfer)' },
  { value: 'REPLACE', label: 'REPLACE (Succession)' },
  { value: 'OFFBOARD_ROLLUP', label: 'OFFBOARD_ROLLUP (Auto Grandparent)' },
  { value: 'MATRIX_ASSIGN', label: 'MATRIX_ASSIGN (Dotted Line)' },
  { value: 'MATRIX_REMOVE', label: 'MATRIX_REMOVE (Remove Dotted Line)' },
  { value: 'DEPARTMENT_HIERARCHY_UPDATED', label: 'DEPARTMENT_HIERARCHY_UPDATED' },
];

export const HierarchyAuditTrailView: React.FC<HierarchyAuditTrailViewProps> = ({
  flatUsers,
}) => {
  const [page, setPage] = useState<number>(1);
  const [pageSize, setPageSize] = useState<number>(15);
  const [selectedActionType, setSelectedActionType] = useState<string>('');
  const [selectedTargetUser, setSelectedTargetUser] = useState<number | undefined>();
  const [dateRange, setDateRange] = useState<[dayjs.Dayjs | null, dayjs.Dayjs | null] | null>(
    null
  );

  const queryParams = {
    page,
    limit: pageSize,
    actionType: selectedActionType || undefined,
    targetUserId: selectedTargetUser || undefined,
    startDate: dateRange?.[0] ? dateRange[0].format('YYYY-MM-DD') : undefined,
    endDate: dateRange?.[1] ? dateRange[1].format('YYYY-MM-DD') : undefined,
  };

  const { data, isLoading, isFetching, refetch } = useGetHierarchyAuditTrailQuery(queryParams);

  const auditData = data?.data;
  const logs = auditData?.logs || [];
  const total = auditData?.total || 0;

  const getActionBadge = (action: string) => {
    switch (action) {
      case 'ASSIGN':
      case 'REPORTING_HIERARCHY_UPDATED':
        return (
          <Tag color="blue" className="font-bold text-[10px] flex items-center gap-1 w-fit">
            <UserCheck size={10} />
            <span>CHANGE_MGR</span>
          </Tag>
        );
      case 'BULK_HANDOVER':
        return (
          <Tag color="orange" className="font-bold text-[10px] flex items-center gap-1 w-fit">
            <Users size={10} />
            <span>BULK_HANDOVER</span>
          </Tag>
        );
      case 'REPLACE':
        return (
          <Tag color="purple" className="font-bold text-[10px] flex items-center gap-1 w-fit">
            <GitCommit size={10} />
            <span>REPLACE_MGR</span>
          </Tag>
        );
      case 'OFFBOARD_ROLLUP':
        return (
          <Tag color="red" className="font-bold text-[10px] flex items-center gap-1 w-fit">
            <UserMinus size={10} />
            <span>OFFBOARD_ROLLUP</span>
          </Tag>
        );
      case 'MATRIX_ASSIGN':
        return (
          <Tag color="cyan" className="font-bold text-[10px] flex items-center gap-1 w-fit">
            <Network size={10} />
            <span>MATRIX_ADD</span>
          </Tag>
        );
      case 'MATRIX_REMOVE':
        return (
          <Tag color="default" className="font-bold text-[10px] flex items-center gap-1 w-fit">
            <Network size={10} />
            <span>MATRIX_DEL</span>
          </Tag>
        );
      case 'DEPARTMENT_HIERARCHY_UPDATED':
        return (
          <Tag color="gold" className="font-bold text-[10px] flex items-center gap-1 w-fit">
            <Building2 size={10} />
            <span>DEPT_UPDATE</span>
          </Tag>
        );
      default:
        return (
          <Tag color="default" className="font-bold text-[10px]">
            {action}
          </Tag>
        );
    }
  };

  const columns: ColumnsType<HierarchyAuditLogItem> = [
    {
      title: 'Timestamp',
      dataIndex: 'created_at',
      key: 'created_at',
      width: 140,
      render: (val: string) => (
        <div className="text-xs">
          <span className="font-bold text-foreground block">
            {val ? dayjs(val).format('YYYY-MM-DD') : '-'}
          </span>
          <span className="text-[10px] text-muted">
            {val ? dayjs(val).format('HH:mm:ss') : ''}
          </span>
        </div>
      ),
    },
    {
      title: 'Action & Operation',
      dataIndex: 'action_type',
      key: 'action_type',
      width: 160,
      render: (action: string) => getActionBadge(action),
    },
    {
      title: 'Target Employee',
      key: 'target',
      width: 180,
      render: (_, r) => (
        <div className="min-w-0">
          <span className="text-xs font-bold text-foreground block truncate">
            {r.target_user_name || (r.target_user_id ? `User #${r.target_user_id}` : 'N/A')}
          </span>
          {r.target_user_email && (
            <span className="text-[10px] text-muted truncate block">{r.target_user_email}</span>
          )}
        </div>
      ),
    },
    {
      title: 'Structural Transition Details',
      key: 'transition',
      render: (_, r) => {
        if (r.action_type === 'BULK_HANDOVER') {
          return (
            <div className="flex items-center gap-1.5 text-xs">
              <span className="font-medium text-muted">{r.from_manager_name || `ID:${r.from_manager_id}`}</span>
              <ArrowRight size={12} className="text-primary shrink-0" />
              <span className="font-bold text-foreground">{r.to_manager_name || `ID:${r.to_manager_id}`}</span>
              <Tag color="orange" className="text-[9px] font-bold border-none ml-1">
                {r.affected_count} transferred
              </Tag>
            </div>
          );
        }

        if (r.action_type === 'OFFBOARD_ROLLUP') {
          return (
            <div className="flex items-center gap-1.5 text-xs">
              <span className="text-rose-500 font-bold">Terminated</span>
              <ArrowRight size={12} className="text-muted shrink-0" />
              <span className="font-medium text-foreground">
                Rolled up to: {r.to_manager_name || 'Grandparent'}
              </span>
              <Tag color="red" className="text-[9px] font-bold border-none ml-1">
                {r.affected_count} reports
              </Tag>
            </div>
          );
        }

        if (r.from_manager_name || r.to_manager_name) {
          return (
            <div className="flex items-center gap-1.5 text-xs">
              <span className="text-muted">{r.from_manager_name || 'None'}</span>
              <ArrowRight size={12} className="text-muted shrink-0" />
              <span className="font-bold text-foreground">{r.to_manager_name || 'Top-level'}</span>
            </div>
          );
        }

        return <span className="text-xs text-muted">-</span>;
      },
    },
    {
      title: 'Reason / Justification',
      dataIndex: 'reason',
      key: 'reason',
      ellipsis: true,
      render: (reason: string | null) => (
        <Tooltip title={reason || 'No justification logged'}>
          <span className="text-xs text-muted italic">
            {reason ? `"${reason}"` : <span className="text-muted/60">No justification</span>}
          </span>
        </Tooltip>
      ),
    },
    {
      title: 'Actor (Executed By)',
      key: 'actor',
      width: 150,
      render: (_, r) => (
        <div className="text-xs">
          <span className="font-bold text-foreground block">
            {r.actor_name || (r.actor_id ? `User #${r.actor_id}` : 'System / Auto')}
          </span>
          {r.actor_email && <span className="text-[10px] text-muted block">{r.actor_email}</span>}
        </div>
      ),
    },
  ];

  return (
    <div className="space-y-4">
      {/* Filter Strip */}
      <div className="p-4 rounded-2xl bg-surface border border-border-subtle shadow-xs flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-2.5 flex-1 min-w-[280px]">
          <div className="w-52">
            <Select
              className="w-full text-xs"
              placeholder="Action Type..."
              value={selectedActionType}
              onChange={(v) => {
                setSelectedActionType(v);
                setPage(1);
              }}
              options={ACTION_TYPE_OPTIONS}
            />
          </div>

          <div className="w-56">
            <Select
              showSearch
              allowClear
              placeholder="Filter by target user..."
              className="w-full text-xs"
              value={selectedTargetUser}
              onChange={(v) => {
                setSelectedTargetUser(v);
                setPage(1);
              }}
              filterOption={(input, opt) =>
                (opt?.label ?? '').toLowerCase().includes(input.toLowerCase())
              }
              options={flatUsers.map((u) => ({
                value: u.id,
                label: `${u.username} (${u.email})`,
              }))}
            />
          </div>

          <div className="w-64">
            <DatePicker.RangePicker
              className="w-full text-xs"
              value={dateRange}
              onChange={(dates) => {
                setDateRange(dates as any);
                setPage(1);
              }}
              format="YYYY-MM-DD"
            />
          </div>
        </div>

        <div className="flex items-center gap-2">
          {(selectedActionType || selectedTargetUser || dateRange) && (
            <Button
              size="small"
              onClick={() => {
                setSelectedActionType('');
                setSelectedTargetUser(undefined);
                setDateRange(null);
                setPage(1);
              }}>
              Reset Filters
            </Button>
          )}

          <Button
            icon={<RefreshCw size={13} className={isFetching ? 'animate-spin' : ''} />}
            onClick={() => refetch()}
            className="flex items-center gap-1 text-xs">
            Refresh
          </Button>
        </div>
      </div>

      {/* Audit Table */}
      <div className="bg-surface rounded-2xl border border-border-subtle shadow-xs overflow-hidden">
        <Table
          columns={columns}
          dataSource={logs}
          rowKey="id"
          loading={isLoading || isFetching}
          pagination={{
            current: page,
            pageSize,
            total,
            onChange: (p, ps) => {
              setPage(p);
              setPageSize(ps);
            },
            showSizeChanger: true,
            pageSizeOptions: ['10', '15', '30', '50'],
            showTotal: (tot) => `Total ${tot} audit entries`,
          }}
          size="middle"
        />
      </div>
    </div>
  );
};

