import React, {
  useState,
  useRef,
  useEffect,
  useMemo,
  useCallback,
} from 'react';
import { Tooltip } from 'antd';
import {
  Crown,
  Search,
  UserPlus,
  Trash2,
  ChevronRight,
  UserCheck,
} from 'lucide-react';
import type { HierarchyNodeUser } from '@/store/api/organizationApiSlice';
import {
  computeHorizontalTreeLayout,
  buildParentMap,
  evaluateFilterAndSearch,
  type LayoutNode,
} from '../utils/orgLayoutEngine';

interface OrgCanvasMapProps {
  rootUsers: HierarchyNodeUser[];
  flatUsers: HierarchyNodeUser[];
  searchQuery: string;
  selectedDepartment: string;
  selectedUserId: number | null;
  onSelectUser: (user: HierarchyNodeUser) => void;
  onAddDirectReport: (user: HierarchyNodeUser) => void;
  onRemoveUser: (user: HierarchyNodeUser) => void;
  expandedNodes: Record<number, boolean>;
  onToggleNode: (nodeId: number) => void;
  onExpandAll: () => void;
  onCollapseAll: () => void;
  onHiddenCountChange?: (count: number) => void;
}

interface ContextMenuState {
  open: boolean;
  x: number;
  y: number;
  node: LayoutNode | null;
}

export const OrgCanvasMap: React.FC<OrgCanvasMapProps> = ({
  rootUsers,
  flatUsers,
  searchQuery,
  selectedDepartment,
  selectedUserId,
  onSelectUser,
  onAddDirectReport,
  onRemoveUser,
  expandedNodes,
  onToggleNode,
  onHiddenCountChange,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);

  // Transform state: pan & zoom
  const [pan, setPan] = useState({ x: 80, y: 140 });
  const [zoom, setZoom] = useState(1.0);
  const [isDragging, setIsDragging] = useState(false);
  const dragStartRef = useRef({ x: 0, y: 0, panX: 0, panY: 0 });
  const hasInitializedZoom = useRef(false);

  // Context Menu state
  const [contextMenu, setContextMenu] = useState<ContextMenuState>({
    open: false,
    x: 0,
    y: 0,
    node: null,
  });

  // Parent lookup map
  const parentMap = useMemo(() => buildParentMap(flatUsers), [flatUsers]);

  // Unified apex tree with dedicated Unassigned Personnel cluster
  const unifiedRoot = useMemo<HierarchyNodeUser | null>(() => {
    if (!rootUsers || rootUsers.length === 0) return null;
    if (rootUsers.length === 1) return rootUsers[0];

    // Find the real founder/CEO/executive apex leader
    const apexLeader =
      rootUsers.find(
        (u) =>
          u.designation?.toLowerCase().includes('founder') ||
          u.designation?.toLowerCase().includes('ceo') ||
          u.designation?.toLowerCase().includes('director') ||
          u.username?.toLowerCase().includes('pratyush') ||
          (u.directReports && u.directReports.length > 0)
      ) || rootUsers[0];

    const unassignedRoots = rootUsers.filter((u) => u.id !== apexLeader.id);

    if (unassignedRoots.length === 0) {
      return apexLeader;
    }

    // Best Practice: Cluster unassigned personnel into an explicit staging pool
    const unassignedGroupNode: HierarchyNodeUser = {
      id: -999,
      username: 'Unassigned Personnel',
      email: 'unassigned@organization.local',
      role: 'Staff Pool',
      department: 'Operations',
      designation: `${unassignedRoots.length} awaiting manager`,
      employee_code: 'POOL',
      reporting_manager_id: apexLeader.id,
      directReports: unassignedRoots,
      subordinatesCount: unassignedRoots.length,
    };

    return {
      ...apexLeader,
      directReports: [...(apexLeader.directReports || []), unassignedGroupNode],
    };
  }, [rootUsers]);

  // Filter & Search Evaluation
  const filterEval = useMemo(() => {
    return evaluateFilterAndSearch(
      flatUsers,
      searchQuery,
      selectedDepartment,
      parentMap
    );
  }, [flatUsers, searchQuery, selectedDepartment, parentMap]);

  // Compute Layout
  const layoutResult = useMemo(() => {
    if (!unifiedRoot) {
      return {
        nodes: [],
        nodeMap: new Map<number, LayoutNode>(),
        connectors: [],
        bounds: { minX: 0, minY: 0, maxX: 600, maxY: 400, width: 600, height: 400 },
        hiddenCount: 0,
      };
    }
    return computeHorizontalTreeLayout(
      unifiedRoot,
      expandedNodes,
      filterEval.highlightedIds
    );
  }, [unifiedRoot, expandedNodes, filterEval.highlightedIds]);

  // Notify parent of hidden count changes
  useEffect(() => {
    if (onHiddenCountChange) {
      onHiddenCountChange(layoutResult.hiddenCount);
    }
  }, [layoutResult.hiddenCount, onHiddenCountChange]);

  // Auto-fit function with high readability clamp
  const handleFit = useCallback(() => {
    if (!containerRef.current || layoutResult.nodes.length === 0) return;
    const { clientWidth, clientHeight } = containerRef.current;
    const padding = 100;
    const bounds = layoutResult.bounds;

    const availableWidth = Math.max(100, clientWidth - padding);
    const availableHeight = Math.max(100, clientHeight - padding);

    const scaleX = availableWidth / Math.max(bounds.width, 250);
    const scaleY = availableHeight / Math.max(bounds.height, 250);
    // Clamp so the chart stays comfortably readable (minimum 0.70x, max 1.1x)
    const fitScale = Math.min(Math.max(Math.min(scaleX, scaleY), 0.7), 1.1);

    const centerX = (bounds.minX + bounds.maxX) / 2;
    const centerY = (bounds.minY + bounds.maxY) / 2;

    const targetPanX = clientWidth / 2 - centerX * fitScale;
    const targetPanY = clientHeight / 2 - centerY * fitScale;

    setZoom(fitScale);
    setPan({ x: targetPanX, y: targetPanY });
  }, [layoutResult]);

  // Default initial zoom and position: centered vertically, readable 1.0 scale
  useEffect(() => {
    if (hasInitializedZoom.current || !containerRef.current || layoutResult.nodes.length === 0) return;
    const { clientWidth, clientHeight } = containerRef.current;
    const rootNode = layoutResult.nodes.find((n) => n.isRoot) || layoutResult.nodes[0];

    if (rootNode) {
      const defaultZoom = 1.0;
      const targetPanX = Math.max(60, clientWidth * 0.08);
      const targetPanY = clientHeight / 2 - (rootNode.y + rootNode.height / 2) * defaultZoom;
      setZoom(defaultZoom);
      setPan({ x: targetPanX, y: targetPanY });
      hasInitializedZoom.current = true;
    }
  }, [layoutResult.nodes]);

  // Center on selected node if changed
  useEffect(() => {
    if (!selectedUserId || !containerRef.current) return;
    const targetNode = layoutResult.nodeMap.get(selectedUserId);
    if (!targetNode) return;

    const { clientWidth, clientHeight } = containerRef.current;
    // Shift slightly to the left so drawer doesn't obstruct the node
    const targetX = clientWidth * 0.38 - (targetNode.x + targetNode.width / 2) * zoom;
    const targetY = clientHeight * 0.5 - (targetNode.y + targetNode.height / 2) * zoom;

    setPan({ x: targetX, y: targetY });
  }, [selectedUserId, layoutResult.nodeMap, zoom]);

  // Pointer/Mouse Drag Pan handlers
  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    // Don't drag or capture pointer if clicking directly on a node card or button
    const target = e.target as HTMLElement;
    if (target.closest('[data-node-card], button, a, input, select')) {
      return;
    }
    setIsDragging(true);
    dragStartRef.current = {
      x: e.clientX,
      y: e.clientY,
      panX: pan.x,
      panY: pan.y,
    };
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!isDragging) return;
    const dx = e.clientX - dragStartRef.current.x;
    const dy = e.clientY - dragStartRef.current.y;
    setPan({
      x: dragStartRef.current.panX + dx,
      y: dragStartRef.current.panY + dy,
    });
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    if (isDragging) {
      setIsDragging(false);
      try {
        (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
      } catch {}
    }
  };

  // Wheel Zoom toward cursor
  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    if (!containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    const zoomFactor = e.deltaY < 0 ? 1.12 : 0.89;
    const newZoom = Math.min(Math.max(zoom * zoomFactor, 0.35), 2.0);

    const newPanX = mouseX - (mouseX - pan.x) * (newZoom / zoom);
    const newPanY = mouseY - (mouseY - pan.y) * (newZoom / zoom);

    setZoom(newZoom);
    setPan({ x: newPanX, y: newPanY });
  };

  // Zoom buttons around center
  const zoomIn = () => {
    if (!containerRef.current) return;
    const { clientWidth, clientHeight } = containerRef.current;
    const newZoom = Math.min(zoom * 1.2, 2.0);
    const cx = clientWidth / 2;
    const cy = clientHeight / 2;
    setPan({
      x: cx - (cx - pan.x) * (newZoom / zoom),
      y: cy - (cy - pan.y) * (newZoom / zoom),
    });
    setZoom(newZoom);
  };

  const zoomOut = () => {
    if (!containerRef.current) return;
    const { clientWidth, clientHeight } = containerRef.current;
    const newZoom = Math.max(zoom * 0.8, 0.35);
    const cx = clientWidth / 2;
    const cy = clientHeight / 2;
    setPan({
      x: cx - (cx - pan.x) * (newZoom / zoom),
      y: cy - (cy - pan.y) * (newZoom / zoom),
    });
    setZoom(newZoom);
  };

  // Close context menu on outside clicks
  useEffect(() => {
    const handleCloseMenu = () => {
      if (contextMenu.open) {
        setContextMenu((prev) => ({ ...prev, open: false }));
      }
    };
    window.addEventListener('click', handleCloseMenu);
    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') handleCloseMenu();
    });
    return () => {
      window.removeEventListener('click', handleCloseMenu);
    };
  }, [contextMenu.open]);

  // Context menu trigger
  const handleNodeContextMenu = (e: React.MouseEvent, node: LayoutNode) => {
    e.preventDefault();
    e.stopPropagation();
    setContextMenu({
      open: true,
      x: e.clientX,
      y: e.clientY,
      node,
    });
  };

  return (
    <div
      ref={containerRef}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onWheel={handleWheel}
      className="relative w-full h-full min-h-[640px] flex-1 overflow-hidden select-none bg-[#faf9f8] text-slate-800 cursor-grab active:cursor-grabbing font-sans"
      style={{ touchAction: 'none' }}
    >
      {/* Professional Subtle Dot Grid on Light Canvas */}
      <svg
        className="absolute inset-0 w-full h-full pointer-events-none opacity-50"
        xmlns="http://www.w3.org/2000/svg"
      >
        <defs>
          <pattern
            id="light-dot-grid-pattern"
            width={24 * zoom}
            height={24 * zoom}
            patternUnits="userSpaceOnUse"
            patternTransform={`translate(${pan.x % (24 * zoom)}, ${pan.y % (24 * zoom)})`}
          >
            <circle cx="2" cy="2" r="1.2" fill="#cbd5e1" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#light-dot-grid-pattern)" />
      </svg>

      {/* Empty Search State Notice */}
      {filterEval.hasFilter && filterEval.isEmptyMatch && (
        <div className="absolute top-8 left-1/2 -translate-x-1/2 z-30 px-5 py-2.5 rounded-full bg-white/95 border border-slate-200 shadow-lg text-xs font-semibold text-slate-700 flex items-center gap-2 backdrop-blur-md animate-in fade-in">
          <Search size={14} className="text-[#e8583a]" />
          <span>No one matches &ldquo;{searchQuery}&rdquo;</span>
        </div>
      )}

      {/* Main Canvas Transform Layer */}
      <div
        className="absolute top-0 left-0 w-0 h-0 origin-top-left pointer-events-none"
        style={{
          transform: `translate3d(${pan.x}px, ${pan.y}px, 0px) scale(${zoom})`,
        }}
      >
        {/* SVG Bezier Connectors Layer (Clean light grey lines with orange highlights) */}
        <svg
          className="absolute overflow-visible pointer-events-none"
          style={{
            left: 0,
            top: 0,
            width: layoutResult.bounds.width + 600,
            height: layoutResult.bounds.height + 600,
          }}
        >
          {layoutResult.connectors.map((c) => (
            <path
              key={c.id}
              d={c.path}
              fill="none"
              stroke={c.isHighlighted ? '#e8583a' : '#cbd5e1'}
              strokeWidth={c.isHighlighted ? 2.5 : 2}
              strokeLinecap="round"
              className="transition-[stroke,stroke-width] duration-300"
            />
          ))}
        </svg>

        {/* Nodes Layer: Crisp White Cards with High Readability */}
        {layoutResult.nodes.map((node) => {
          const isSelected = selectedUserId === node.id;
          const isMatched = filterEval.matchedIds.has(node.id);
          const isPathHighlighted = filterEval.highlightedIds.has(node.id);

          // Dim nodes if filter/search is active and node is not in highlighted path
          const isDimmed = filterEval.hasFilter && !isPathHighlighted;

          const initials = node.user.username
            .split(' ')
            .map((w) => w[0])
            .filter(Boolean)
            .join('')
            .toUpperCase()
            .slice(0, 2);

          const isUnassignedPool = node.id === -999;

          // Only mark as Founder/CEO based on designation (job title), not RBAC role
          const isFounderOrCeoNode = Boolean(
            !isUnassignedPool &&
            !node.user.reporting_manager_id && (
              node.user.designation?.toLowerCase().includes('founder') ||
              node.user.designation?.toLowerCase().includes('ceo')
            )
          );

          return (
            <div
              key={node.id}
              data-node-card="true"
              tabIndex={0}
              role="button"
              onPointerDown={(e) => {
                e.stopPropagation();
              }}
              onClick={(e) => {
                e.stopPropagation();
                if (isUnassignedPool) {
                  onToggleNode(node.id);
                } else {
                  onSelectUser(node.user);
                }
              }}
              onContextMenu={(e) => {
                if (!isUnassignedPool) {
                  handleNodeContextMenu(e, node);
                }
              }}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.stopPropagation();
                  if (isUnassignedPool) {
                    onToggleNode(node.id);
                  } else {
                    onSelectUser(node.user);
                  }
                }
              }}
              style={{
                width: node.width,
                height: node.height,
                transform: `translate3d(${node.x}px, ${node.y}px, 0px)`,
                transition:
                  'transform 450ms cubic-bezier(0.16, 1, 0.3, 1), opacity 300ms ease, box-shadow 200ms ease',
                opacity: isDimmed ? 0.25 : 1,
                ...(node.isDeptHead ? { borderLeftColor: node.departmentColor.text } : {}),
              }}
              className={`absolute top-0 left-0 pointer-events-auto rounded-[16px] cursor-pointer outline-none select-none flex items-center justify-between px-3.5 transition-all bg-white text-slate-900 border border-slate-200/90 shadow-sm hover:shadow-md hover:border-slate-300 ${
                isUnassignedPool
                  ? 'border-2 border-dashed border-amber-400 bg-amber-50/70 hover:bg-amber-100/80 shadow-xs'
                  : isFounderOrCeoNode
                  ? 'border-2 border-amber-300 shadow-md hover:shadow-lg'
                  : ''
              } ${
                isSelected
                  ? 'ring-2 ring-[#e8583a] ring-offset-2 ring-offset-[#faf9f8] shadow-md border-[#e8583a]'
                  : ''
              } ${
                isMatched && !isSelected
                  ? 'ring-2 ring-primary/80 shadow-md'
                  : ''
              } ${
                node.isDeptHead
                  ? 'border-l-4'
                  : ''
              }`}
            >
              {/* Left Side: Avatar + Name & Designation */}
              <div className="flex items-center gap-3 min-w-0 flex-1 mr-2">
                {/* Circular Avatar */}
                {isUnassignedPool ? (
                  <div className="w-9 h-9 rounded-full bg-amber-500/15 border border-amber-300 flex items-center justify-center text-amber-700 shrink-0 shadow-xs">
                    <UserCheck size={16} className="text-amber-600" />
                  </div>
                ) : node.user.image_url ? (
                  <img
                    src={node.user.image_url}
                    alt={node.user.username}
                    className="w-9 h-9 rounded-full object-cover shrink-0 ring-1 ring-slate-200"
                  />
                ) : (
                  <div
                    className={`w-9 h-9 rounded-full flex items-center justify-center text-xs font-bold shrink-0 ${
                      isFounderOrCeoNode
                        ? 'bg-amber-500 text-white shadow-xs'
                        : 'text-white shadow-xs'
                    }`}
                    style={
                      !isFounderOrCeoNode
                        ? { backgroundColor: node.departmentColor.text }
                        : {}
                    }
                  >
                    {isFounderOrCeoNode ? <Crown size={15} className="text-white" /> : initials}
                  </div>
                )}

                {/* Name & Title */}
                <div className="min-w-0 flex-1">
                  <Tooltip title={node.user.username} placement="topLeft">
                    <span
                      className={`block font-bold text-[13px] truncate leading-tight ${
                        isUnassignedPool
                          ? 'text-amber-950 font-bold'
                          : isFounderOrCeoNode
                          ? 'text-slate-950 font-black'
                          : 'text-slate-900'
                      }`}
                    >
                      {node.user.username}
                    </span>
                  </Tooltip>

                  <Tooltip
                    title={
                      isUnassignedPool
                        ? `${node.user.directReports?.length || 0} employees awaiting manager assignment`
                        : `${node.user.designation || node.user.role || 'Member'}${
                            node.user.department ? ` · in ${node.user.department}` : ''
                          }`
                    }
                    placement="bottomLeft"
                  >
                    <span
                      className={`block text-[11px] truncate leading-tight mt-0.5 font-medium ${
                        isUnassignedPool
                          ? 'text-amber-700 font-semibold'
                          : 'text-slate-500'
                      }`}
                    >
                      {node.user.designation || node.user.role || (isFounderOrCeoNode ? 'Founder & CEO' : 'Member')}
                    </span>
                  </Tooltip>
                </div>
              </div>

              {/* Right Side: Team Size Badge (only if person has reports) */}
              {node.hasReports && (
                <Tooltip
                  title={
                    isUnassignedPool
                      ? node.isExpanded
                        ? 'Click to collapse unassigned staff'
                        : 'Click to expand unassigned staff'
                      : node.isExpanded
                      ? `Click to collapse branch (${node.directReportsCount} reports)`
                      : `Click to expand branch (${node.directReportsCount} reports)`
                  }
                >
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      onToggleNode(node.id);
                    }}
                    className={`shrink-0 min-w-[26px] h-6 px-1.5 rounded-full flex items-center justify-center text-[11px] font-bold transition-all cursor-pointer ${
                      isUnassignedPool
                        ? 'bg-amber-100 hover:bg-amber-200 text-amber-900 border border-amber-300 font-bold'
                        : isFounderOrCeoNode
                        ? 'bg-amber-50 hover:bg-amber-100 text-amber-900 border border-amber-200'
                        : node.isExpanded
                        ? 'bg-slate-100 hover:bg-slate-200 text-slate-700 border border-slate-200'
                        : 'bg-primary/10 hover:bg-primary/20 text-primary border border-primary/30 font-black'
                    }`}
                  >
                    {node.isExpanded ? (
                      <span>{node.totalTeamCount || node.directReportsCount}</span>
                    ) : (
                      <span>+{node.totalTeamCount || node.directReportsCount}</span>
                    )}
                  </button>
                </Tooltip>
              )}
            </div>
          );
        })}
      </div>

      {/* Floating Canvas Controls (Bottom-Left) on Clean Light Pill */}
      <div className="absolute bottom-6 left-6 z-20 flex flex-col gap-2">
        <div className="flex items-center rounded-full bg-white/95 border border-slate-200 p-1 shadow-md backdrop-blur-md">
          <button
            type="button"
            onClick={zoomOut}
            className="w-7 h-7 rounded-full hover:bg-slate-100 text-slate-700 flex items-center justify-center font-bold text-sm transition-colors cursor-pointer"
            title="Zoom out"
          >
            −
          </button>
          <button
            type="button"
            onClick={zoomIn}
            className="w-7 h-7 rounded-full hover:bg-slate-100 text-slate-700 flex items-center justify-center font-bold text-sm transition-colors cursor-pointer"
            title="Zoom in"
          >
            +
          </button>
          <div className="w-[1px] h-4 bg-slate-200 mx-1" />
          <button
            type="button"
            onClick={handleFit}
            className="px-2.5 h-7 rounded-full hover:bg-slate-100 text-slate-700 text-xs font-semibold flex items-center justify-center transition-colors cursor-pointer"
            title="Fit to screen"
          >
            Fit
          </button>
        </div>

        {/* Subtext under Zoom HUD */}
        <span className="text-[11px] text-slate-500 font-medium pl-1 select-none">
          Drag to pan · scroll to zoom · click node for details
        </span>
      </div>

      {/* Custom Right-Click Context Menu in Clean White SaaS Theme */}
      {contextMenu.open && contextMenu.node && (
        <div
          style={{ top: contextMenu.y, left: contextMenu.x }}
          className="fixed z-50 w-52 rounded-xl bg-white border border-slate-200 shadow-xl py-1.5 text-slate-700 text-xs font-medium backdrop-blur-md animate-in fade-in zoom-in-95 duration-150"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Header */}
          <div className="px-3 py-1.5 border-b border-slate-100 text-slate-400 font-bold text-[10px] uppercase tracking-wider truncate">
            {contextMenu.node.user.username}
          </div>

          {/* Action 1: View profile */}
          <button
            type="button"
            onClick={() => {
              if (contextMenu.node) onSelectUser(contextMenu.node.user);
              setContextMenu((prev) => ({ ...prev, open: false }));
            }}
            className="w-full px-3 py-2 text-left hover:bg-slate-50 hover:text-slate-900 flex items-center gap-2 transition-colors cursor-pointer"
          >
            <UserCheck size={14} className="text-slate-400" />
            <span>View details</span>
          </button>

          {/* Action 2: Add direct report */}
          <button
            type="button"
            onClick={() => {
              if (contextMenu.node) onAddDirectReport(contextMenu.node.user);
              setContextMenu((prev) => ({ ...prev, open: false }));
            }}
            className="w-full px-3 py-2 text-left hover:bg-slate-50 hover:text-slate-900 flex items-center gap-2 transition-colors cursor-pointer"
          >
            <UserPlus size={14} className="text-slate-400" />
            <span>Add direct report</span>
          </button>

          {/* Action 3: Collapse/Expand branch (if has reports) */}
          {contextMenu.node.hasReports && (
            <button
              type="button"
              onClick={() => {
                if (contextMenu.node) onToggleNode(contextMenu.node.id);
                setContextMenu((prev) => ({ ...prev, open: false }));
              }}
              className="w-full px-3 py-2 text-left hover:bg-slate-50 hover:text-slate-900 flex items-center gap-2 transition-colors cursor-pointer"
            >
              <ChevronRight
                size={14}
                className={`text-slate-400 transition-transform ${
                  contextMenu.node.isExpanded ? 'rotate-90' : ''
                }`}
              />
              <span>{contextMenu.node.isExpanded ? 'Collapse branch' : 'Expand branch'}</span>
            </button>
          )}

          {/* Action 4: Remove (not for root or unassigned pool) */}
          {!contextMenu.node.isRoot && contextMenu.node.id !== -999 && (
            <>
              <div className="my-1 border-t border-slate-100" />
              <button
                type="button"
                onClick={() => {
                  if (contextMenu.node) onRemoveUser(contextMenu.node.user);
                  setContextMenu((prev) => ({ ...prev, open: false }));
                }}
                className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-600 flex items-center gap-2 transition-colors cursor-pointer"
              >
                <Trash2 size={14} />
                <span>Remove employee</span>
              </button>
            </>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Tooltip, message } from 'antd';
import {
  Crown,
  ChevronRight,
  Mail,
  Copy,
  Calendar,
  Hash,
  Phone,
  UserPlus,
  Trash2,
  Edit2,
  Layers,
  Check,
  X,
} from 'lucide-react';
import type { HierarchyNodeUser } from '@/store/api/organizationApiSlice';
import { getDepartmentColor } from '../utils/orgLayoutEngine';

interface OrgEmployeeDrawerProps {
  user: HierarchyNodeUser | null;
  open: boolean;
  onClose: () => void;
  flatUsers: HierarchyNodeUser[];
  onSelectUser: (user: HierarchyNodeUser) => void;
  onAddDirectReport: (user: HierarchyNodeUser) => void;
  onRemoveUser: (user: HierarchyNodeUser) => void;
  onChangeManager?: (user: HierarchyNodeUser) => void;
  onMatrixManager?: (user: HierarchyNodeUser) => void;
  canManage: boolean;
}

export const OrgEmployeeDrawer: React.FC<OrgEmployeeDrawerProps> = ({
  user,
  open,
  onClose,
  flatUsers,
  onSelectUser,
  onAddDirectReport,
  onRemoveUser,
  onChangeManager,
  onMatrixManager,
  canManage,
}) => {
  const [copiedEmail, setCopiedEmail] = useState(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && open) {
        onClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [open, onClose]);

  if (!open || !user) return null;

  // Only mark as Founder/CEO if their actual job DESIGNATION says so —
  // NOT based on RBAC role (which can be "Founder" for permission purposes)
  // AND they must have no reporting manager (true organizational head)
  const isFounderOrCeo = Boolean(
    !user.reporting_manager_id && (
      user.designation?.toLowerCase().includes('founder') ||
      user.designation?.toLowerCase().includes('ceo')
    )
  );

  const deptColor = getDepartmentColor(user.department);

  // Manager
  const manager = flatUsers.find((u) => u.id === user.reporting_manager_id);
  const managerDeptColor = getDepartmentColor(manager?.department);

  // Direct Reports & Subtree Team Count
  const directReports = user.directReports || [];
  const teamOfM = (user.subordinatesCount ?? 0) || directReports.length;

  // Peers: share the same manager, exclude self, max 4
  const peers = user.reporting_manager_id
    ? flatUsers
        .filter((u) => u.id !== user.id && u.reporting_manager_id === user.reporting_manager_id)
        .slice(0, 4)
    : [];

  const initials = (user.username || 'User')
    .split(' ')
    .map((w) => w[0])
    .filter(Boolean)
    .join('')
    .toUpperCase()
    .slice(0, 2) || 'U';

  const employeeId = user.employee_code || `EMP-${String(user.id).padStart(4, '0')}`;
  const joinDate =
    (user as any).join_date ||
    (user as any).joinDate ||
    (user as any).created_at?.split('T')[0] ||
    (user as any).createdAt?.split('T')[0] ||
    'Active Member';

  const copyEmail = () => {
    if (user.email) {
      navigator.clipboard.writeText(user.email);
      setCopiedEmail(true);
      message.success('Email copied to clipboard');
      setTimeout(() => setCopiedEmail(false), 2000);
    }
  };

  return (
    <div
      onClick={onClose}
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-xs animate-in fade-in duration-200"
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="w-full max-w-[560px] max-h-[90vh] flex flex-col rounded-2xl bg-white border border-slate-200 shadow-2xl text-slate-800 font-sans overflow-hidden animate-in zoom-in-95 duration-150"
      >
        {/* Header Banner */}
        <div className="p-6 pb-4 border-b border-slate-100 bg-[#faf9f8] relative">
          <button
            type="button"
            onClick={onClose}
            className="absolute top-5 right-5 w-8 h-8 rounded-full bg-white border border-slate-200 text-slate-400 hover:text-slate-700 hover:bg-slate-100 flex items-center justify-center transition-colors text-sm font-bold cursor-pointer shadow-xs"
            aria-label="Close modal"
          >
            <X size={16} />
          </button>

          <div className="flex items-center gap-4">
            {/* Circular Avatar */}
            {user.image_url ? (
              <img
                src={user.image_url}
                alt={user.username}
                className="w-16 h-16 rounded-full object-cover ring-2 ring-white shadow-md"
              />
            ) : (
              <div
                className="w-16 h-16 rounded-full flex items-center justify-center text-xl font-bold tracking-wide shadow-md text-white shrink-0"
                style={{
                  backgroundColor: isFounderOrCeo ? '#f59e0b' : deptColor.text,
                }}
              >
                {isFounderOrCeo ? <Crown size={26} className="text-white" /> : initials}
              </div>
            )}

            <div className="min-w-0 flex-1 pr-6">
              <div className="flex items-center gap-2 flex-wrap">
                <h2 className="text-xl font-bold text-slate-900 tracking-tight leading-tight truncate">
                  {user.username}
                </h2>
                {isFounderOrCeo ? (
                  <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800 border border-amber-200">
                    Founder & CEO
                  </span>
                ) : user.role ? (
                  <span
                    className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                      user.role.toLowerCase().includes('admin')
                        ? 'bg-purple-100 text-purple-800 border border-purple-200'
                        : user.role.toLowerCase().includes('manager')
                        ? 'bg-blue-100 text-blue-800 border border-blue-200'
                        : 'bg-slate-100 text-slate-700 border border-slate-200'
                    }`}
                  >
                    {user.role}
                  </span>
                ) : null}
              </div>
              <p className="text-xs text-slate-500 font-medium truncate mt-0.5">
                {user.designation || user.role || 'Staff Member'}
              </p>
              {user.department && (
                <span
                  className="inline-block px-2.5 py-0.5 rounded-md text-[11px] font-semibold mt-1.5"
                  style={{
                    backgroundColor: deptColor.bg,
                    color: deptColor.text,
                  }}
                >
                  {user.department}
                </span>
              )}
            </div>
          </div>
        </div>

        {/* Scrollable Information Body */}
        <div className="flex-1 overflow-y-auto p-6 space-y-5">
          {/* Metadata Cards Grid */}
          <div className="grid grid-cols-2 gap-3 p-3.5 rounded-xl bg-[#faf9f8] border border-slate-200/80">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 rounded-lg bg-white border border-slate-200 flex items-center justify-center text-slate-500 shrink-0 shadow-xs">
                <Hash size={14} />
              </div>
              <div className="min-w-0">
                <span className="text-[10px] font-bold text-slate-400 block uppercase tracking-wider">
                  Employee ID
                </span>
                <span className="text-xs font-bold text-slate-800 truncate block">
                  {employeeId}
                </span>
              </div>
            </div>

            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 rounded-lg bg-white border border-slate-200 flex items-center justify-center text-slate-500 shrink-0 shadow-xs">
                <Calendar size={14} />
              </div>
              <div className="min-w-0">
                <span className="text-[10px] font-bold text-slate-400 block uppercase tracking-wider">
                  Joining Date
                </span>
                <span className="text-xs font-bold text-slate-800 truncate block">
                  {joinDate}
                </span>
              </div>
            </div>
          </div>

          {/* Contact Details */}
          <div className="space-y-1.5">
            <span className="text-[11px] font-bold tracking-wider text-slate-400 uppercase block">
              Contact Information
            </span>
            <div className="p-3.5 rounded-xl bg-white border border-slate-200 space-y-2 text-xs">
              <div className="flex items-center justify-between gap-2">
                <div className="flex items-center gap-2.5 min-w-0 text-slate-700">
                  <Mail size={14} className="text-[#e8583a] shrink-0" />
                  <span className="truncate font-medium">{user.email}</span>
                </div>
                <button
                  type="button"
                  onClick={copyEmail}
                  className="p-1 text-slate-400 hover:text-slate-700 transition-colors"
                  title="Copy email"
                >
                  {copiedEmail ? <Check size={13} className="text-emerald-600" /> : <Copy size={13} />}
                </button>
              </div>

              {user.contact_number && (
                <div className="flex items-center gap-2.5 text-slate-700 pt-2 border-t border-slate-100">
                  <Phone size={14} className="text-[#e8583a] shrink-0" />
                  <span className="font-medium">{user.contact_number}</span>
                </div>
              )}
            </div>
          </div>

          {/* Reports to Section */}
          <div>
            <span className="text-[11px] font-bold tracking-wider text-slate-400 uppercase block mb-1.5">
              Reports to
            </span>
            {manager ? (
              <div
                onClick={() => onSelectUser(manager)}
                className="p-3 rounded-xl bg-white hover:bg-slate-50 border border-slate-200 hover:border-slate-300 shadow-xs transition-all cursor-pointer flex items-center justify-between group"
              >
                <div className="flex items-center gap-3 min-w-0">
                  <div
                    className="w-9 h-9 rounded-full flex items-center justify-center text-xs font-bold text-white shrink-0 shadow-xs"
                    style={{ backgroundColor: managerDeptColor.text }}
                  >
                    {manager.username ? manager.username.slice(0, 2).toUpperCase() : 'MG'}
                  </div>
                  <div className="min-w-0">
                    <span className="text-xs font-bold text-slate-900 block truncate group-hover:text-[#e8583a] transition-colors">
                      {manager.username}
                    </span>
                    <span className="text-[11px] text-slate-500 block truncate">
                      {manager.designation || manager.role}
                    </span>
                  </div>
                </div>
                <ChevronRight
                  size={15}
                  className="text-slate-400 group-hover:text-[#e8583a] transition-transform group-hover:translate-x-0.5"
                />
              </div>
            ) : isFounderOrCeo ? (
              <div className="p-3 rounded-xl bg-amber-50/80 border border-amber-200/80 text-amber-900 text-xs flex items-center gap-2">
                <Crown size={15} className="text-amber-600 shrink-0" />
                <span className="font-semibold">Top of the organization (Leadership)</span>
              </div>
            ) : (
              <div className="p-3 rounded-xl bg-slate-50 border border-slate-200 text-slate-600 text-xs flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-slate-400 shrink-0" />
                  <span className="font-medium text-slate-600">No reporting manager assigned</span>
                </div>
                {canManage && onChangeManager && (
                  <button
                    type="button"
                    onClick={() => onChangeManager(user)}
                    className="text-[11px] text-[#e8583a] hover:underline font-semibold cursor-pointer"
                  >
                    Assign Manager
                  </button>
                )}
              </div>
            )}
          </div>

          {/* Direct reports Section */}
          <div>
            <div className="flex items-center justify-between mb-1.5">
              <span className="text-[11px] font-bold tracking-wider text-slate-400 uppercase block">
                Direct reports ({directReports.length}) · team of {teamOfM}
              </span>
            </div>

            {directReports.length === 0 ? (
              <div className="p-3.5 rounded-xl bg-[#faf9f8] border border-slate-200/80 text-center text-xs text-slate-500">
                No direct reports assigned
              </div>
            ) : (
              <div className="space-y-1.5 max-h-40 overflow-y-auto pr-1">
                {directReports.map((report) => {
                  const repColor = getDepartmentColor(report.department);
                  return (
                    <div
                      key={report.id}
                      onClick={() => onSelectUser(report)}
                      className="p-2.5 rounded-xl bg-white hover:bg-slate-50 border border-slate-200 hover:border-slate-300 shadow-xs transition-all cursor-pointer flex items-center justify-between group"
                    >
                      <div className="flex items-center gap-3 min-w-0">
                        <div
                          className="w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold text-white shrink-0 shadow-xs"
                          style={{ backgroundColor: repColor.text }}
                        >
                          {report.username ? report.username.slice(0, 2).toUpperCase() : 'DR'}
                        </div>
                        <div className="min-w-0">
                          <span className="text-xs font-bold text-slate-900 block truncate group-hover:text-[#e8583a] transition-colors">
                            {report.username}
                          </span>
                          <span className="text-[11px] text-slate-500 block truncate">
                            {report.designation || report.role}
                          </span>
                        </div>
                      </div>
                      <ChevronRight
                        size={14}
                        className="text-slate-400 group-hover:text-[#e8583a] transition-transform group-hover:translate-x-0.5"
                      />
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          {/* Peers Section */}
          {peers.length > 0 && (
            <div>
              <span className="text-[11px] font-bold tracking-wider text-slate-400 uppercase block mb-1.5">
                Peers ({peers.length})
              </span>
              <div className="space-y-1.5 max-h-32 overflow-y-auto pr-1">
                {peers.map((peer) => {
                  const peerColor = getDepartmentColor(peer.department);
                  return (
                    <div
                      key={peer.id}
                      onClick={() => onSelectUser(peer)}
                      className="p-2.5 rounded-xl bg-white hover:bg-slate-50 border border-slate-200 hover:border-slate-300 shadow-xs transition-all cursor-pointer flex items-center justify-between group"
                    >
                      <div className="flex items-center gap-3 min-w-0">
                        <div
                          className="w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold text-white shrink-0 shadow-xs"
                          style={{ backgroundColor: peerColor.text }}
                        >
                          {peer.username ? peer.username.slice(0, 2).toUpperCase() : 'PE'}
                        </div>
                        <div className="min-w-0">
                          <span className="text-xs font-bold text-slate-900 block truncate group-hover:text-[#e8583a] transition-colors">
                            {peer.username}
                          </span>
                          <span className="text-[11px] text-slate-500 block truncate">
                            {peer.designation || peer.role}
                          </span>
                        </div>
                      </div>
                      <ChevronRight
                        size={14}
                        className="text-slate-400 group-hover:text-[#e8583a] transition-transform group-hover:translate-x-0.5"
                      />
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* Footer Actions */}
        <div className="p-4 border-t border-slate-200 bg-[#faf9f8] flex items-center justify-between gap-2">
          <div className="flex items-center gap-2 flex-1">
            <button
              type="button"
              onClick={() => onAddDirectReport(user)}
              className="h-9 px-4 rounded-xl bg-[#e8583a] hover:bg-[#d04a2e] text-white font-bold text-xs flex items-center justify-center gap-1.5 transition-colors cursor-pointer shadow-xs"
            >
              <UserPlus size={14} />
              <span>Add direct report</span>
            </button>

            {canManage && onChangeManager && !isFounderOrCeo && (
              <Tooltip title="Edit / Change Manager">
                <button
                  type="button"
                  onClick={() => onChangeManager(user)}
                  className="h-9 px-3 rounded-xl bg-white hover:bg-slate-100 text-slate-700 border border-slate-200 font-semibold text-xs flex items-center gap-1.5 transition-colors cursor-pointer shadow-xs"
                >
                  <Edit2 size={13} />
                  <span>Edit line</span>
                </button>
              </Tooltip>
            )}
          </div>

          <div className="flex items-center gap-2">
            {canManage && onMatrixManager && (
              <Tooltip title="Manage Matrix / Dotted line">
                <button
                  type="button"
                  onClick={() => onMatrixManager(user)}
                  className="w-9 h-9 rounded-xl bg-white hover:bg-slate-100 text-slate-700 border border-slate-200 flex items-center justify-center transition-colors cursor-pointer shadow-xs"
                >
                  <Layers size={14} />
                </button>
              </Tooltip>
            )}

            {!isFounderOrCeo && (
              <Tooltip title="Remove employee from organization">
                <button
                  type="button"
                  onClick={() => onRemoveUser(user)}
                  className="w-9 h-9 rounded-xl bg-white hover:bg-red-50 text-slate-400 hover:text-red-600 border border-slate-200 hover:border-red-200 flex items-center justify-center transition-colors cursor-pointer shadow-xs"
                >
                  <Trash2 size={14} />
                </button>
              </Tooltip>
            )}

            <button
              type="button"
              onClick={onClose}
              className="h-9 px-3.5 rounded-xl bg-slate-200 hover:bg-slate-300 text-slate-700 text-xs font-bold transition-colors cursor-pointer"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Modal, message } from 'antd';
import { AlertTriangle, UserMinus, ShieldAlert } from 'lucide-react';
import { useOffboardRollupMutation } from '@/store/api/organizationApiSlice';
import { useDeleteUserMutation } from '@/store/api/userSlice';
import type { HierarchyNodeUser } from '@/store/api/organizationApiSlice';

interface OrgRemoveConfirmModalProps {
  open: boolean;
  onClose: () => void;
  user: HierarchyNodeUser | null;
  flatUsers: HierarchyNodeUser[];
  onSuccess: () => void;
}

export const OrgRemoveConfirmModal: React.FC<OrgRemoveConfirmModalProps> = ({
  open,
  onClose,
  user,
  flatUsers,
  onSuccess,
}) => {
  const [offboardRollup, { isLoading: isOffboarding }] = useOffboardRollupMutation();
  const [deleteUser, { isLoading: isDeleting }] = useDeleteUserMutation();

  if (!user) return null;

  const directReportsCount = user.directReports?.length || 0;
  const manager = flatUsers.find((u) => u.id === user.reporting_manager_id);
  const managerName = manager?.username || 'the upper executive';

  const handleConfirm = async () => {
    try {
      if (directReportsCount > 0) {
        // Roll up direct reports to parent manager, then offboard
        await offboardRollup({
          terminatingUserId: user.id,
          reason: `Removed via Organization Map - direct reports rolled up to ${managerName}`,
        }).unwrap();
      } else {
        // Direct leaf deletion
        await deleteUser(user.id).unwrap();
      }

      message.success(`Employee ${user.username} has been successfully removed.`);
      onClose();
      onSuccess();
    } catch (err: any) {
      console.error('Failed to remove employee:', err);
      message.error(err?.data?.message || err?.message || 'Failed to remove employee.');
    }
  };

  return (
    <Modal
      open={open}
      onCancel={onClose}
      onOk={handleConfirm}
      confirmLoading={isOffboarding || isDeleting}
      okText="Remove Employee"
      okButtonProps={{
        danger: true,
        className: 'font-bold bg-red-600! hover:bg-red-700!',
      }}
      cancelButtonProps={{ className: 'font-semibold' }}
      title={
        <div className="flex items-center gap-2 text-red-600 font-bold text-base">
          <div className="w-8 h-8 rounded-lg bg-red-100 dark:bg-red-950/40 text-red-600 flex items-center justify-center">
            <UserMinus size={18} />
          </div>
          <span>Remove Employee</span>
        </div>
      }
      centered
      destroyOnClose
      width={460}
    >
      <div className="py-3 space-y-4">
        <div className="p-4 rounded-xl bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-900/50 flex items-start gap-3">
          <AlertTriangle className="text-red-600 shrink-0 mt-0.5" size={20} />
          <div className="text-xs text-red-900 dark:text-red-200 space-y-1">
            <p className="font-bold text-sm">
              Confirm removal of {user.username}?
            </p>
            <p className="leading-relaxed">
              This action will remove the employee from the organization hierarchy and company staff directory.
            </p>
          </div>
        </div>

        {directReportsCount > 0 ? (
          <div className="p-3.5 rounded-xl bg-surface-subtle border border-border-subtle flex items-start gap-3">
            <ShieldAlert className="text-amber-600 shrink-0 mt-0.5" size={18} />
            <div className="text-xs space-y-1">
              <span className="font-bold text-foreground block">
                Automatic Team Rollup ({directReportsCount} Direct Reports)
              </span>
              <p className="text-muted-foreground leading-relaxed">
                All {directReportsCount} direct reports will be safely reassigned to report directly to{' '}
                <strong className="text-foreground">{managerName}</strong> to preserve organizational continuity.
              </p>
            </div>
          </div>
        ) : (
          <p className="text-xs text-muted-foreground">
            This employee currently has no direct reports assigned.
          </p>
        )}
      </div>
    </Modal>
  );
};

import { useState, useMemo } from 'react';
import {
  Building2,
  Search,
  Plus,
  Download,
  Maximize2,
  Minimize2,
  RefreshCw,
  Network,
  GitBranch,
  FolderTree,
  Crown,
  Edit2,
  UserCheck,
} from 'lucide-react';
import { Select, message, Table, Tree } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { Dialog } from '@/components/ui/composed/Dialog';
import { Button } from '@/components/ui/primitives/Button';
import {
  useGetOrganizationHierarchyQuery,
  useUpdateReportingManagerMutation,
  useUpdateDepartmentHierarchyMutation,
  type HierarchyNodeUser,
  type DepartmentHierarchyItem,
} from '@/store/api/organizationApiSlice';
import { usePermission } from '@/hooks/usePermission';
import { ChangeManagerModal } from './ChangeManagerModal';
import { BulkHandoverModal } from './BulkHandoverModal';
import { ReplaceManagerModal } from './ReplaceManagerModal';
import { OffboardRollupModal } from './OffboardRollupModal';
import { MatrixManagerModal } from './MatrixManagerModal';
import { HierarchyReorgStudio } from './HierarchyReorgStudio';
import { HierarchyAuditTrailView } from './HierarchyAuditTrailView';
import { OrgCanvasMap } from './OrgCanvasMap';
import { OrgEmployeeDrawer } from './OrgEmployeeDrawer';
import { OrgAddEmployeeModal } from './OrgAddEmployeeModal';
import { OrgRemoveConfirmModal } from './OrgRemoveConfirmModal';
import { getDepartmentColor } from '../utils/orgLayoutEngine';

export function OrganizationHierarchyView() {
  const { data: hierarchyResponse, isLoading, refetch } = useGetOrganizationHierarchyQuery();
  const [updateReportingManager, { isLoading: isUpdatingManager }] =
    useUpdateReportingManagerMutation();
  const [updateDepartmentHierarchy, { isLoading: isUpdatingDept }] =
    useUpdateDepartmentHierarchyMutation();

  const { can, isSuperadmin } = usePermission();
  const canManageHierarchy = isSuperadmin || can('organization:manage');

  // View mode: 'map' (interactive horizontal map), 'list' (tree list directory), 'departments', 'reorg', 'audit'
  const [viewMode, setViewMode] = useState<'map' | 'list' | 'departments' | 'reorg' | 'audit'>('map');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedDepartment, setSelectedDepartment] = useState('ALL');
  const [selectedEmployee, setSelectedEmployee] = useState<HierarchyNodeUser | null>(null);
  const [expandedNodes, setExpandedNodes] = useState<Record<number, boolean>>({});
  const [hiddenCount, setHiddenCount] = useState<number>(0);

  // ── Modals: Add & Remove Employee ──────────────────────────────────────────
  const [addEmployeeModal, setAddEmployeeModal] = useState<{
    open: boolean;
    preselectedManagerId: number | null;
  }>({ open: false, preselectedManagerId: null });

  const [removeEmployeeModal, setRemoveEmployeeModal] = useState<{
    open: boolean;
    user: HierarchyNodeUser | null;
  }>({ open: false, user: null });

  // ── Existing Enterprise Reorg Modals ────────────────────────────────────────
  const [editManagerModal, setEditManagerModal] = useState<{
    open: boolean;
    user: HierarchyNodeUser | null;
    selectedManagerId: number | null;
  }>({
    open: false,
    user: null,
    selectedManagerId: null,
  });

  const [editDeptModal, setEditDeptModal] = useState<{
    open: boolean;
    department: DepartmentHierarchyItem | null;
    selectedHeadId: number | null;
    parentDeptId: number | null;
  }>({
    open: false,
    department: null,
    selectedHeadId: null,
    parentDeptId: null,
  });

  const [changeManagerModal, setChangeManagerModal] = useState<{
    open: boolean;
    user: HierarchyNodeUser | null;
  }>({ open: false, user: null });

  const [bulkHandoverModal, setBulkHandoverModal] = useState(false);
  const [replaceManagerModal, setReplaceManagerModal] = useState(false);
  const [offboardRollupModal, setOffboardRollupModal] = useState(false);
  const [matrixModal, setMatrixModal] = useState<{
    open: boolean;
    userId: number | null;
  }>({ open: false, userId: null });

  // ── Derived data ─────────────────────────────────────────────────────────────
  const hierarchyData = hierarchyResponse?.data;
  const rootUsers = hierarchyData?.tree || [];
  const flatUsers = hierarchyData?.flatUsers || [];
  const departments = hierarchyData?.departments || [];
  const stats = hierarchyData?.stats || {
    totalEmployees: 0,
    totalManagers: 0,
    totalDepartments: 0,
    hierarchyDepth: 0,
  };

  const unassignedCount = useMemo(() => {
    return rootUsers.length > 1 ? rootUsers.length - 1 : 0;
  }, [rootUsers]);

  // Dynamic department filters with headcount
  const departmentFilters = useMemo(() => {
    const counts: Record<string, number> = {};
    flatUsers.forEach((u) => {
      if (u.department) {
        counts[u.department] = (counts[u.department] || 0) + 1;
      }
    });
    return Object.entries(counts)
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count);
  }, [flatUsers]);

  // Expand / Collapse Handlers
  const toggleNode = (id: number) => {
    setExpandedNodes((prev) => ({
      ...prev,
      [id]: prev[id] === undefined ? false : !prev[id],
    }));
  };

  const handleExpandAll = () => {
    const allExpanded: Record<number, boolean> = {};
    flatUsers.forEach((u) => {
      allExpanded[u.id] = true;
    });
    setExpandedNodes(allExpanded);
  };

  const handleCollapseAll = () => {
    const allCollapsed: Record<number, boolean> = {};
    flatUsers.forEach((u) => {
      allCollapsed[u.id] = false;
    });
    setExpandedNodes(allCollapsed);
  };

  // Export JSON handler
  const handleExportJson = () => {
    if (!hierarchyData) {
      message.warning('No organization data available to export.');
      return;
    }
    const dataStr =
      'data:text/json;charset=utf-8,' +
      encodeURIComponent(JSON.stringify(hierarchyData, null, 2));
    const downloadAnchor = document.createElement('a');
    downloadAnchor.setAttribute('href', dataStr);
    downloadAnchor.setAttribute(
      'download',
      `organization-map-${new Date().toISOString().split('T')[0]}.json`
    );
    document.body.appendChild(downloadAnchor);
    downloadAnchor.click();
    downloadAnchor.remove();
    message.success('Organization data exported successfully as JSON.');
  };

  // Flow handlers
  const handleOpenEditManager = (user: HierarchyNodeUser) => {
    setEditManagerModal({
      open: true,
      user,
      selectedManagerId: user.reporting_manager_id || null,
    });
  };

  const handleSaveManager = async () => {
    if (!editManagerModal.user) return;
    try {
      await updateReportingManager({
        userId: editManagerModal.user.id,
        reportingManagerId: editManagerModal.selectedManagerId,
        reason: 'Reporting line updated via Organization Chart',
      }).unwrap();
      message.success(`Reporting relationship updated for ${editManagerModal.user.username}`);
      setEditManagerModal({ open: false, user: null, selectedManagerId: null });
      refetch();
    } catch (err: any) {
      message.error(err?.data?.message || 'Failed to update reporting manager.');
    }
  };

  const handleOpenEditDept = (dept: DepartmentHierarchyItem) => {
    setEditDeptModal({
      open: true,
      department: dept,
      selectedHeadId: dept.head_user_id || null,
      parentDeptId: dept.parent_department_id || null,
    });
  };

  const handleSaveDept = async () => {
    if (!editDeptModal.department) return;
    try {
      await updateDepartmentHierarchy({
        departmentId: editDeptModal.department.id,
        headUserId: editDeptModal.selectedHeadId,
        parentDepartmentId: editDeptModal.parentDeptId,
      }).unwrap();
      message.success(`Department ${editDeptModal.department.department_name} updated successfully.`);
      setEditDeptModal({
        open: false,
        department: null,
        selectedHeadId: null,
        parentDeptId: null,
      });
      refetch();
    } catch (err: any) {
      message.error(err?.data?.message || 'Failed to update department leadership.');
    }
  };

  const handleOpenChangeManager = (user?: HierarchyNodeUser) => {
    setChangeManagerModal({
      open: true,
      user: user || null,
    });
  };

  const handleOpenMatrixModal = (user?: HierarchyNodeUser) => {
    setMatrixModal({
      open: true,
      userId: user?.id || null,
    });
  };

  // ── Establish Founder as Apex Root of Organization for Tree List ─────────────
  const unifiedTree = useMemo<HierarchyNodeUser[]>(() => {
    if (!rootUsers.length) return [];

    // Find the real founder/CEO/executive apex leader
    const apexLeader =
      rootUsers.find(
        (u) =>
          u.designation?.toLowerCase().includes('founder') ||
          u.designation?.toLowerCase().includes('ceo') ||
          u.designation?.toLowerCase().includes('director') ||
          u.username?.toLowerCase().includes('pratyush') ||
          (u.directReports && u.directReports.length > 0)
      ) ||
      flatUsers.find(
        (u) =>
          !u.reporting_manager_id && (
            u.designation?.toLowerCase().includes('founder') ||
            u.designation?.toLowerCase().includes('ceo') ||
            u.designation?.toLowerCase().includes('director') ||
            u.username?.toLowerCase().includes('pratyush') ||
            (u.directReports && u.directReports.length > 0)
          )
      ) ||
      rootUsers[0];

    const unassignedRoots = rootUsers.filter((u) => u.id !== apexLeader.id);

    if (unassignedRoots.length === 0) {
      return [apexLeader];
    }

    // Best Practice: Cluster unassigned personnel into an explicit staging pool
    const unassignedGroupNode: HierarchyNodeUser = {
      id: -999,
      username: 'Unassigned Personnel',
      email: 'unassigned@organization.local',
      role: 'Staff Pool',
      department: 'Operations',
      designation: `${unassignedRoots.length} awaiting manager`,
      employee_code: 'POOL',
      reporting_manager_id: apexLeader.id,
      directReports: unassignedRoots,
      subordinatesCount: unassignedRoots.length,
    };

    const unifiedApexNode: HierarchyNodeUser = {
      ...apexLeader,
      directReports: [...(apexLeader.directReports || []), unassignedGroupNode],
    };

    return [unifiedApexNode];
  }, [rootUsers, flatUsers]);

  // Filter tree nodes if search query or department filter is active
  const filteredTree = useMemo<HierarchyNodeUser[]>(() => {
    if (!searchQuery.trim() && selectedDepartment === 'ALL') return unifiedTree;
    const q = searchQuery.toLowerCase().trim();

    const filterNode = (node: HierarchyNodeUser): HierarchyNodeUser | null => {
      const nameMatch = !q || node.username.toLowerCase().includes(q);
      const emailMatch = !q || (node.email && node.email.toLowerCase().includes(q));
      const roleMatch = !q || (node.role && node.role.toLowerCase().includes(q));
      const desigMatch = !q || (node.designation && node.designation.toLowerCase().includes(q));
      const deptMatch =
        selectedDepartment === 'ALL' ||
        (node.department && node.department.toLowerCase() === selectedDepartment.toLowerCase());

      const selfMatch = (nameMatch || emailMatch || roleMatch || desigMatch) && deptMatch;

      const matchedChildren = (node.directReports || [])
        .map(filterNode)
        .filter(Boolean) as HierarchyNodeUser[];

      if (selfMatch || matchedChildren.length > 0) {
        return {
          ...node,
          directReports: matchedChildren,
        };
      }
      return null;
    };

    return unifiedTree.map(filterNode).filter(Boolean) as HierarchyNodeUser[];
  }, [unifiedTree, searchQuery, selectedDepartment]);

  // Ant Design Tree Data Format (Directory Mode matching Screenshot)
  const antdTreeData = useMemo(() => {
    const mapNode = (node: HierarchyNodeUser): any => {
      if (node.id === -999) {
        return {
          key: String(node.id),
          title: (
            <div className="inline-flex items-center justify-between gap-4 p-3 my-1 rounded-2xl bg-amber-50/70 border-2 border-dashed border-amber-300 hover:border-amber-400 transition-all w-full max-w-4xl shadow-xs">
              <div className="flex items-center gap-3 min-w-0 flex-1">
                <div className="w-10 h-10 rounded-xl bg-amber-100 border border-amber-300 font-bold text-xs flex items-center justify-center shrink-0 text-amber-800">
                  <UserCheck size={18} />
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="font-bold text-amber-950 text-xs">
                      {node.username}
                    </span>
                    <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-200/80 text-amber-900 border border-amber-300">
                      {node.directReports?.length || 0} Staff
                    </span>
                  </div>
                  <span className="text-[11px] text-amber-700 font-semibold block mt-0.5">
                    {node.designation}
                  </span>
                </div>
              </div>
            </div>
          ),
          children: (node.directReports || []).map(mapNode),
        };
      }

      // Only identify as Founder/CEO by designation (job title), not RBAC role
      const isFounder = Boolean(
        !node.reporting_manager_id && (
          node.designation?.toLowerCase().includes('founder') ||
          node.designation?.toLowerCase().includes('ceo')
        )
      );
      const hasReports = Boolean(node.directReports && node.directReports.length > 0);
      const deptColor = getDepartmentColor(node.department);

      return {
        key: String(node.id),
        title: (
          <div
            onClick={(e) => {
              e.stopPropagation();
              setSelectedEmployee(node);
            }}
            className="inline-flex items-center justify-between gap-4 p-3 my-1 rounded-2xl bg-white border border-slate-200 hover:border-slate-300 hover:shadow-md transition-all w-full max-w-4xl shadow-xs cursor-pointer group"
          >
            <div className="flex items-center gap-3 min-w-0 flex-1">
              {node.image_url ? (
                <img
                  src={node.image_url}
                  alt={node.username}
                  className="w-10 h-10 rounded-xl object-cover ring-1 ring-slate-200 shrink-0"
                />
              ) : (
                <div
                  className={`w-10 h-10 rounded-xl font-black text-xs flex items-center justify-center shrink-0 shadow-xs ${
                    isFounder
                      ? 'bg-amber-500 text-white shadow-amber-200'
                      : 'text-white'
                  }`}
                  style={!isFounder ? { backgroundColor: deptColor.text } : {}}
                >
                  {isFounder ? (
                    <Crown size={16} className="text-white" />
                  ) : (
                    node.username ? node.username.slice(0, 2).toUpperCase() : 'U'
                  )}
                </div>
              )}
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="font-bold text-slate-900 text-xs group-hover:text-primary transition-colors">
                    {node.username}
                  </span>
                  {isFounder ? (
                    <span className="text-[10px] font-black px-2 py-0.5 rounded-full bg-amber-100 text-amber-800 border border-amber-300 inline-flex items-center gap-1">
                      <Crown size={10} className="text-amber-600" /> {node.designation || 'Founder & CEO'}
                    </span>
                  ) : (
                    <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-slate-100 text-slate-700 border border-slate-200">
                      {node.role || node.designation || 'Staff'}
                    </span>
                  )}
                  {node.department && (
                    <span
                      className="text-[10px] font-semibold px-2 py-0.5 rounded-md"
                      style={{
                        backgroundColor: deptColor.bg,
                        color: deptColor.text,
                      }}
                    >
                      {node.department}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-2 mt-0.5 text-slate-500 text-[11px] truncate">
                  <span className="truncate">{node.email}</span>
                  {node.designation && (
                    <span className="text-slate-400 shrink-0">• {node.designation}</span>
                  )}
                </div>
              </div>
            </div>

            <div className="flex items-center gap-2.5 shrink-0" onClick={(e) => e.stopPropagation()}>
              {hasReports && (
                <span className="text-[11px] font-bold px-2.5 py-1 rounded-full bg-blue-50 text-blue-700 border border-blue-200/80">
                  {node.directReports!.length} {node.directReports!.length === 1 ? 'Direct Report' : 'Direct Reports'}
                </span>
              )}
              {canManageHierarchy && (
                <button
                  type="button"
                  onClick={() => handleOpenEditManager(node)}
                  title="Change Reporting Manager"
                  className="w-7 h-7 rounded-lg hover:bg-slate-100 text-slate-400 hover:text-slate-700 border border-slate-200 flex items-center justify-center transition-colors cursor-pointer"
                >
                  <Edit2 size={12} />
                </button>
              )}
            </div>
          </div>
        ),
        children: hasReports ? node.directReports!.map(mapNode) : undefined,
      };
    };

    return filteredTree.map(mapNode);
  }, [filteredTree, canManageHierarchy]);

  // Department Table Columns (for Department Heads view)
  const deptColumns: ColumnsType<DepartmentHierarchyItem> = [
    {
      title: 'Department',
      key: 'name',
      render: (_, r) => (
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-primary/10 flex items-center justify-center text-primary font-bold">
            <Building2 size={16} />
          </div>
          <div>
            <span className="font-bold text-foreground block">{r.department_name}</span>
            {r.parent_department_name && (
              <span className="text-[11px] text-muted-foreground flex items-center gap-1">
                <GitBranch size={10} /> Parent: {r.parent_department_name}
              </span>
            )}
          </div>
        </div>
      ),
    },
    {
      title: 'Department Head',
      key: 'head',
      render: (_, r) => (
        <div className="flex items-center gap-2.5">
          {r.head_name ? (
            <>
              <div className="w-8 h-8 rounded-full bg-emerald-500/10 text-emerald-600 font-bold flex items-center justify-center text-xs">
                {r.head_name.slice(0, 2).toUpperCase()}
              </div>
              <div>
                <span className="text-xs font-bold text-foreground block">{r.head_name}</span>
                <span className="text-[10px] text-muted-foreground">{r.head_email}</span>
              </div>
            </>
          ) : (
            <span className="text-xs text-muted-foreground italic">No Head Designated</span>
          )}
        </div>
      ),
    },
    {
      title: 'Headcount',
      key: 'count',
      render: (_, r) => (
        <span className="text-xs font-black px-2.5 py-1 rounded-full bg-surface-subtle text-foreground border border-border-subtle">
          {r.member_count} {r.member_count === 1 ? 'member' : 'members'}
        </span>
      ),
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, r) =>
        canManageHierarchy ? (
          <Button
            variant="outline"
            size="small"
            onClick={() => handleOpenEditDept(r)}
            className="text-xs">
            Configure Leadership
          </Button>
        ) : null,
    },
  ];

  return (
    <div className="space-y-4">
      {/* ── HEADER & WORKSPACE TOOLBAR (Matching Screenshot 1 & 2) ── */}
      <div className="flex flex-col gap-3">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          {/* Header Left: Title & Subtitle */}
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-xl font-bold tracking-tight text-foreground">
                Organization map
              </h1>

              {/* View Switcher Pill */}
              <div className="flex items-center p-0.5 bg-surface-subtle rounded-full border border-border-subtle text-xs font-medium">
                <button
                  type="button"
                  onClick={() => setViewMode('map')}
                  className={`px-3 py-1 rounded-full transition-all cursor-pointer flex items-center gap-1.5 ${
                    viewMode === 'map'
                      ? 'bg-white text-primary font-bold shadow-xs'
                      : 'text-muted-foreground hover:text-foreground'
                  }`}
                >
                  <GitBranch size={12} />
                  <span>Map</span>
                </button>
                <button
                  type="button"
                  onClick={() => setViewMode('list')}
                  className={`px-3 py-1 rounded-full transition-all cursor-pointer flex items-center gap-1.5 ${
                    viewMode === 'list'
                      ? 'bg-white text-primary font-bold shadow-xs'
                      : 'text-muted-foreground hover:text-foreground'
                  }`}
                >
                  <FolderTree size={12} />
                  <span>Tree List</span>
                </button>
                <button
                  type="button"
                  onClick={() => setViewMode('departments')}
                  className={`px-3 py-1 rounded-full transition-all cursor-pointer ${
                    viewMode === 'departments'
                      ? 'bg-white text-primary font-bold shadow-xs'
                      : 'text-muted-foreground hover:text-foreground'
                  }`}
                >
                  Teams
                </button>
                {canManageHierarchy && (
                  <button
                    type="button"
                    onClick={() => setViewMode('reorg')}
                    className={`px-3 py-1 rounded-full transition-all cursor-pointer ${
                      viewMode === 'reorg'
                        ? 'bg-white text-primary font-bold shadow-xs'
                        : 'text-muted-foreground hover:text-foreground'
                    }`}
                  >
                    Reorg Studio
                  </button>
                )}
                {canManageHierarchy && (
                  <button
                    type="button"
                    onClick={() => setViewMode('audit')}
                    className={`px-3 py-1 rounded-full transition-all cursor-pointer ${
                      viewMode === 'audit'
                        ? 'bg-white text-primary font-bold shadow-xs'
                        : 'text-muted-foreground hover:text-foreground'
                    }`}
                  >
                    Audit
                  </button>
                )}
              </div>
            </div>

            {/* Subtitle Stats Line */}
            <p className="text-xs text-muted-foreground font-medium mt-1">
              {stats.totalEmployees || flatUsers.length} people ·{' '}
              {stats.totalDepartments || departmentFilters.length} teams ·{' '}
              {hiddenCount} hidden in collapsed branches
              {unassignedCount > 0 && (
                <span className="text-amber-700 font-bold ml-1.5 px-2 py-0.5 rounded-full bg-amber-100/70 border border-amber-200">
                  {unassignedCount} awaiting manager
                </span>
              )}
            </p>
          </div>

          {/* Header Right: Floating Pill Toolbar Matching Screenshot 1 & 2 */}
          <div className="flex items-center gap-2 flex-wrap">
            {/* Search Pill */}
            <div className="relative">
              <Search
                size={13}
                className="text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none"
              />
              <input
                type="text"
                placeholder="Search name, role or team"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-56 text-xs pl-8 pr-7 py-1.5 rounded-full border border-border-subtle bg-surface-elevated text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 shadow-xs"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery('')}
                  className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground text-xs"
                >
                  ✕
                </button>
              )}
            </div>

            {/* Expand all */}
            <button
              type="button"
              onClick={handleExpandAll}
              className="h-8 px-3 rounded-full bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-foreground text-xs font-semibold flex items-center gap-1.5 transition-colors cursor-pointer shadow-xs"
            >
              <Maximize2 size={12} className="text-muted-foreground" />
              <span>Expand all</span>
            </button>

            {/* Collapse all */}
            <button
              type="button"
              onClick={handleCollapseAll}
              className="h-8 px-3 rounded-full bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-foreground text-xs font-semibold flex items-center gap-1.5 transition-colors cursor-pointer shadow-xs"
            >
              <Minimize2 size={12} className="text-muted-foreground" />
              <span>Collapse all</span>
            </button>

            {/* Export */}
            <button
              type="button"
              onClick={handleExportJson}
              className="h-8 px-3 rounded-full bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-foreground text-xs font-semibold flex items-center gap-1.5 transition-colors cursor-pointer shadow-xs"
            >
              <Download size={12} className="text-muted-foreground" />
              <span>Export</span>
            </button>

            {/* Add employee (Primary Button) */}
            {canManageHierarchy && (
              <button
                type="button"
                onClick={() =>
                  setAddEmployeeModal({
                    open: true,
                    preselectedManagerId: selectedEmployee?.id ?? null,
                  })
                }
                className="h-8 px-4 rounded-full bg-primary hover:bg-primary-hover text-white text-xs font-bold flex items-center gap-1.5 transition-colors cursor-pointer shadow-sm"
              >
                <Plus size={14} />
                <span>Add employee</span>
              </button>
            )}

            {/* Refresh */}
            <button
              type="button"
              onClick={() => refetch()}
              className="w-8 h-8 rounded-full bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-muted-foreground hover:text-foreground flex items-center justify-center transition-colors cursor-pointer shadow-xs"
              title="Refresh tree data"
            >
              <RefreshCw size={13} className={isLoading ? 'animate-spin' : ''} />
            </button>
          </div>
        </div>

        {/* Row of Department Filter Chips with Color Dots */}
        {(viewMode === 'map' || viewMode === 'list') && departmentFilters.length > 0 && (
          <div className="flex items-center gap-2 flex-wrap pt-1">
            <button
              type="button"
              onClick={() => setSelectedDepartment('ALL')}
              className={`h-7 px-3 rounded-full text-xs font-semibold flex items-center gap-1.5 transition-all cursor-pointer ${
                selectedDepartment === 'ALL'
                  ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-900 shadow-xs'
                  : 'bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-muted-foreground hover:text-foreground'
              }`}
            >
              <span>All Teams ({flatUsers.length})</span>
            </button>

            {departmentFilters.map((dept) => {
              const color = getDepartmentColor(dept.name);
              const isActive = selectedDepartment.toLowerCase() === dept.name.toLowerCase();
              return (
                <button
                  key={dept.name}
                  type="button"
                  onClick={() => setSelectedDepartment(isActive ? 'ALL' : dept.name)}
                  className={`h-7 px-3 rounded-full text-xs font-semibold flex items-center gap-1.5 transition-all cursor-pointer ${
                    isActive
                      ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-900 shadow-xs'
                      : 'bg-surface-elevated hover:bg-surface-subtle border border-border-subtle text-muted-foreground hover:text-foreground'
                  }`}
                >
                  <span
                    className="w-2 h-2 rounded-full shrink-0"
                    style={{ backgroundColor: color.dot }}
                  />
                  <span>{dept.name}</span>
                </button>
              );
            })}
          </div>
        )}
      </div>

      {/* ── MAIN CONTENT AREA ── */}
      {viewMode === 'map' && (
        <div className="w-full h-[calc(100vh-210px)] min-h-[640px] rounded-2xl overflow-hidden border border-slate-200 shadow-sm relative bg-[#faf9f8]">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center h-full gap-3 text-slate-500">
              <RefreshCw size={24} className="animate-spin text-[#e8583a]" />
              <span className="text-xs font-bold">Loading interactive organizational map...</span>
            </div>
          ) : rootUsers.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-center p-8 gap-2">
              <Network className="w-10 h-10 text-slate-400 opacity-50 mb-1" />
              <p className="text-sm font-bold text-slate-800">No personnel records found</p>
              <p className="text-xs text-slate-500 font-medium max-w-sm">
                No active employee hierarchy records were returned from the system.
              </p>
            </div>
          ) : (
            <OrgCanvasMap
              rootUsers={rootUsers}
              flatUsers={flatUsers}
              searchQuery={searchQuery}
              selectedDepartment={selectedDepartment}
              selectedUserId={selectedEmployee?.id ?? null}
              onSelectUser={(u) => {
                if (u.id !== -999) setSelectedEmployee(u);
              }}
              onAddDirectReport={(u) =>
                setAddEmployeeModal({ open: true, preselectedManagerId: u.id })
              }
              onRemoveUser={(u) => setRemoveEmployeeModal({ open: true, user: u })}
              expandedNodes={expandedNodes}
              onToggleNode={toggleNode}
              onExpandAll={handleExpandAll}
              onCollapseAll={handleCollapseAll}
              onHiddenCountChange={setHiddenCount}
            />
          )}
        </div>
      )}

      {/* VIEW: TREE LIST (Directory View matching user screenshot) */}
      {viewMode === 'list' && (
        <div className="rounded-2xl bg-white border border-slate-200/90 shadow-sm p-6 min-h-[640px] overflow-x-auto">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center h-64 gap-3 text-slate-500">
              <RefreshCw size={24} className="animate-spin text-[#e8583a]" />
              <span className="text-xs font-bold">Loading organization tree list...</span>
            </div>
          ) : filteredTree.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-center p-8 gap-2">
              <Network className="w-10 h-10 text-slate-400 opacity-50 mb-1" />
              <p className="text-sm font-bold text-slate-800">No personnel records found</p>
              <p className="text-xs text-slate-500 font-medium max-w-sm">
                No active employee records match your search query or department filter.
              </p>
            </div>
          ) : (
            <div className="py-2">
              <Tree
                showLine={{ showLeafIcon: false }}
                defaultExpandAll
                treeData={antdTreeData}
                blockNode
                className="bg-transparent"
              />
            </div>
          )}
        </div>
      )}

      {/* VIEW: DEPARTMENT HEADS TABLE */}
      {viewMode === 'departments' && (
        <div className="rounded-2xl bg-surface-elevated border border-border-subtle shadow-soft overflow-hidden p-3">
          <Table
            scroll={{ x: 'max-content' }}
            columns={deptColumns}
            dataSource={departments}
            rowKey="id"
            loading={isLoading}
            pagination={false}
            className="premium-table"
          />
        </div>
      )}

      {/* VIEW: REORG STUDIO */}
      {viewMode === 'reorg' && (
        <HierarchyReorgStudio
          onOpenFlowA={handleOpenChangeManager}
          onOpenFlowB1={() => setBulkHandoverModal(true)}
          onOpenFlowB2={() => setReplaceManagerModal(true)}
          onOpenFlowB3={() => setOffboardRollupModal(true)}
          onOpenFlowC={handleOpenMatrixModal}
          stats={stats}
        />
      )}

      {/* VIEW: AUDIT TRAIL */}
      {viewMode === 'audit' && (
        <HierarchyAuditTrailView flatUsers={flatUsers} />
      )}

      {/* ── CONTEXTUAL EMPLOYEE PROFILE DRAWER ── */}
      <OrgEmployeeDrawer
        user={selectedEmployee}
        open={Boolean(selectedEmployee)}
        onClose={() => setSelectedEmployee(null)}
        flatUsers={flatUsers}
        onSelectUser={(u) => setSelectedEmployee(u)}
        onAddDirectReport={(u) =>
          setAddEmployeeModal({ open: true, preselectedManagerId: u.id })
        }
        onRemoveUser={(u) => setRemoveEmployeeModal({ open: true, user: u })}
        onChangeManager={(u) => {
          setSelectedEmployee(null);
          handleOpenEditManager(u);
        }}
        onMatrixManager={(u) => {
          setSelectedEmployee(null);
          handleOpenMatrixModal(u);
        }}
        canManage={canManageHierarchy}
      />

      {/* ── ADD EMPLOYEE MODAL ── */}
      <OrgAddEmployeeModal
        open={addEmployeeModal.open}
        onClose={() => setAddEmployeeModal({ open: false, preselectedManagerId: null })}
        preselectedManagerId={addEmployeeModal.preselectedManagerId}
        flatUsers={flatUsers}
        departments={departments}
        onSuccess={async (newId) => {
          const res = await refetch();
          const updatedFlat = res.data?.data?.flatUsers || [];
          if (newId) {
            const found = updatedFlat.find((u) => u.id === newId);
            if (found) {
              if (found.reporting_manager_id) {
                setExpandedNodes((prev) => ({
                  ...prev,
                  [found.reporting_manager_id!]: true,
                }));
              }
              setSelectedEmployee(found);
            }
          }
        }}
      />

      {/* ── REMOVE EMPLOYEE CONFIRM MODAL ── */}
      <OrgRemoveConfirmModal
        open={removeEmployeeModal.open}
        onClose={() => setRemoveEmployeeModal({ open: false, user: null })}
        user={removeEmployeeModal.user}
        flatUsers={flatUsers}
        onSuccess={() => {
          setSelectedEmployee(null);
          refetch();
        }}
      />

      {/* ── MODAL: ASSIGN / CHANGE REPORTING MANAGER ── */}
      <Dialog
        visible={editManagerModal.open}
        onHide={() => setEditManagerModal({ open: false, user: null, selectedManagerId: null })}
        header="Change Reporting Manager"
        className="max-w-md">
        {editManagerModal.user && (
          <div className="space-y-4 pt-2">
            <div className="p-3.5 rounded-xl bg-muted/30 border border-border/60 flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-primary/10 text-primary font-black flex items-center justify-center text-xs">
                {editManagerModal.user.username.slice(0, 2).toUpperCase()}
              </div>
              <div>
                <span className="font-bold text-foreground text-sm block">
                  {editManagerModal.user.username}
                </span>
                <span className="text-xs text-muted-foreground">
                  {editManagerModal.user.designation || editManagerModal.user.role} • {editManagerModal.user.department}
                </span>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-foreground block">
                Select Direct Reporting Manager
              </label>
              <Select
                showSearch
                placeholder="Select manager (or leave empty for root/executive)..."
                allowClear
                className="w-full"
                value={editManagerModal.selectedManagerId || undefined}
                onChange={(val) =>
                  setEditManagerModal((prev) => ({
                    ...prev,
                    selectedManagerId: val ? Number(val) : null,
                  }))
                }
                filterOption={(input, option) =>
                  (option?.label ?? '').toLowerCase().includes(input.toLowerCase())
                }
                options={flatUsers
                  .filter((u) => u.id !== editManagerModal.user?.id)
                  .map((u) => ({
                    value: u.id,
                    label: `${u.username} (${u.email}) -- ${u.role}`,
                  }))}
              />
              <p className="text-[11px] text-muted-foreground mt-1">
                The selected manager will review this employee's leave and WFH requests when hierarchy-based approvals are active.
              </p>
            </div>

            <div className="flex items-center justify-end gap-3 pt-4 border-t border-border/60">
              <Button
                variant="ghost"
                onClick={() =>
                  setEditManagerModal({ open: false, user: null, selectedManagerId: null })
                }>
                Cancel
              </Button>
              <Button
                variant="primary"
                onClick={handleSaveManager}
                loading={isUpdatingManager}
                className="px-6">
                Update Manager
              </Button>
            </div>
          </div>
        )}
      </Dialog>

      {/* ── MODAL: ASSIGN DEPARTMENT HEAD ── */}
      <Dialog
        visible={editDeptModal.open}
        onHide={() =>
          setEditDeptModal({ open: false, department: null, selectedHeadId: null, parentDeptId: null })
        }
        header="Configure Department Leadership"
        className="max-w-md">
        {editDeptModal.department && (
          <div className="space-y-4 pt-2">
            <div>
              <label className="text-xs font-bold text-foreground block mb-1">
                Department Name
              </label>
              <p className="text-sm font-black text-foreground">
                {editDeptModal.department.department_name}
              </p>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-foreground block">
                Designate Department Head
              </label>
              <Select
                showSearch
                placeholder="Select an employee as Department Head..."
                allowClear
                className="w-full"
                value={editDeptModal.selectedHeadId || undefined}
                onChange={(val) =>
                  setEditDeptModal((prev) => ({
                    ...prev,
                    selectedHeadId: val ? Number(val) : null,
                  }))
                }
                filterOption={(input, option) =>
                  (option?.label ?? '').toLowerCase().includes(input.toLowerCase())
                }
                options={flatUsers.map((u) => ({
                  value: u.id,
                  label: `${u.username} (${u.email}) -- ${u.role}`,
                }))}
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-foreground block">
                Parent Department (Optional)
              </label>
              <Select
                placeholder="Select parent department..."
                allowClear
                className="w-full"
                value={editDeptModal.parentDeptId || undefined}
                onChange={(val) =>
                  setEditDeptModal((prev) => ({
                    ...prev,
                    parentDeptId: val ? Number(val) : null,
                  }))
                }
                options={departments
                  .filter((d) => d.id !== editDeptModal.department?.id)
                  .map((d) => ({
                    value: d.id,
                    label: d.department_name,
                  }))}
              />
            </div>

            <div className="flex items-center justify-end gap-3 pt-4 border-t border-border/60">
              <Button
                variant="ghost"
                onClick={() =>
                  setEditDeptModal({
                    open: false,
                    department: null,
                    selectedHeadId: null,
                    parentDeptId: null,
                  })
                }>
                Cancel
              </Button>
              <Button
                variant="primary"
                onClick={handleSaveDept}
                loading={isUpdatingDept}
                className="px-6">
                Save Department
              </Button>
            </div>
          </div>
        )}
      </Dialog>

      {/* ── ENTERPRISE REORG MODALS ── */}
      <ChangeManagerModal
        open={changeManagerModal.open}
        onClose={() => setChangeManagerModal({ open: false, user: null })}
        selectedUser={changeManagerModal.user}
        flatUsers={flatUsers}
        onSuccess={refetch}
      />

      <BulkHandoverModal
        open={bulkHandoverModal}
        onClose={() => setBulkHandoverModal(false)}
        flatUsers={flatUsers}
        onSuccess={refetch}
      />

      <ReplaceManagerModal
        open={replaceManagerModal}
        onClose={() => setReplaceManagerModal(false)}
        flatUsers={flatUsers}
        onSuccess={refetch}
      />

      <OffboardRollupModal
        open={offboardRollupModal}
        onClose={() => setOffboardRollupModal(false)}
        flatUsers={flatUsers}
        onSuccess={refetch}
      />

      <MatrixManagerModal
        open={matrixModal.open}
        onClose={() => setMatrixModal({ open: false, userId: null })}
        preselectedUserId={matrixModal.userId}
        flatUsers={flatUsers}
        onSuccess={refetch}
      />
    </div>
  );
}

import React, { useEffect } from 'react';
import { Modal, Form, Select, Input, DatePicker, Alert, Button } from 'antd';
import dayjs from 'dayjs';
import { GitCommit } from 'lucide-react';
import {
  useReplaceManagerMutation,
  type HierarchyNodeUser,
} from '@/store/api/organizationApiSlice';
import { showToast } from '@/components/ui/composed/Toast.utils';

interface ReplaceManagerModalProps {
  open: boolean;
  onClose: () => void;
  preselectedManagerId?: number | null;
  flatUsers: HierarchyNodeUser[];
  onSuccess?: () => void;
}

export const ReplaceManagerModal: React.FC<ReplaceManagerModalProps> = ({
  open,
  onClose,
  preselectedManagerId,
  flatUsers,
  onSuccess,
}) => {
  const [form] = Form.useForm();
  const [replaceManager, { isLoading }] = useReplaceManagerMutation();

  const currentManagerId = Form.useWatch('currentManagerId', form) || preselectedManagerId;
  const newManagerId = Form.useWatch('newManagerId', form);

  const currentManagerObj = flatUsers.find((u) => u.id === currentManagerId);
  const newManagerObj = flatUsers.find((u) => u.id === newManagerId);

  useEffect(() => {
    if (open) {
      form.setFieldsValue({
        currentManagerId: preselectedManagerId || undefined,
        newManagerId: undefined,
        reason: '',
        effectiveDate: dayjs(),
      });
    }
  }, [open, preselectedManagerId, form]);

  const handleSubmit = async (values: any) => {
    try {
      const effectiveDateStr = values.effectiveDate
        ? dayjs(values.effectiveDate).format('YYYY-MM-DD')
        : undefined;

      const res = await replaceManager({
        currentManagerId: Number(values.currentManagerId),
        newManagerId: Number(values.newManagerId),
        reason: values.reason?.trim(),
        effectiveDate: effectiveDateStr,
      }).unwrap();

      showToast({
        severity: 'success',
        summary: 'Success',
        detail: res.message || 'Manager replaced successfully',
      });
      onClose();
      onSuccess?.();
    } catch (err: any) {
      showToast({
        severity: 'error',
        summary: 'Replacement Failed',
        detail: err?.data?.message || 'Could not replace manager',
      });
    }
  };

  return (
    <Modal
      title={
        <div className="flex items-center gap-2 text-foreground font-black">
          <GitCommit size={18} className="text-primary" />
          <span>Replace Manager (Succession)</span>
        </div>
      }
      open={open}
      onCancel={onClose}
      footer={null}
      destroyOnClose
      width={600}>
      <Form form={form} layout="vertical" onFinish={handleSubmit} className="pt-2">
        <Alert
          message="Atomic Succession & Hierarchy Swap"
          description="Successor (Manager B) inherits Outgoing Manager's supervisor (parent) and all direct reporting lines (children) in a single atomic transaction."
          type="warning"
          showIcon
          className="mb-4"
        />

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <Form.Item
            label="Current Manager to Replace"
            name="currentManagerId"
            rules={[{ required: true, message: 'Select manager being replaced' }]}>
            <Select
              showSearch
              placeholder="Select current manager..."
              filterOption={(input, opt) =>
                (opt?.label ?? '').toLowerCase().includes(input.toLowerCase())
              }
              options={flatUsers
                .filter((u) => u.directReports && u.directReports.length > 0)
                .map((m) => ({
                  value: m.id,
                  label: `${m.username} (${m.directReports.length} direct reports)`,
                }))}
            />
          </Form.Item>

          <Form.Item
            label="Successor / New Manager"
            name="newManagerId"
            rules={[{ required: true, message: 'Select successor manager' }]}>
            <Select
              showSearch
              placeholder="Select successor..."
              filterOption={(input, opt) =>
                (opt?.label ?? '').toLowerCase().includes(input.toLowerCase())
              }
              options={flatUsers
                .filter((u) => u.id !== currentManagerId)
                .map((u) => ({
                  value: u.id,
                  label: `${u.username} (${u.role})`,
                }))}
            />
          </Form.Item>
        </div>

        {/* Transition Summary Preview */}
        {currentManagerObj && newManagerObj && (
          <div className="mb-4 p-3.5 rounded-xl bg-surface-subtle border border-border-subtle text-xs space-y-2">
            <span className="font-bold text-foreground block">Hierarchy Inheritance Preview</span>
            <div className="grid grid-cols-2 gap-2 text-[11px]">
              <div className="p-2 rounded-lg bg-surface border border-border-subtle">
                <span className="text-muted block">Supervisor Inherited:</span>
                <strong className="text-foreground">
                  {currentManagerObj.reporting_manager_name || 'None (Top Level)'}
                </strong>
              </div>
              <div className="p-2 rounded-lg bg-surface border border-border-subtle">
                <span className="text-muted block">Reports Transferred:</span>
                <strong className="text-foreground">
                  {currentManagerObj.directReports?.length || 0} Employees
                </strong>
              </div>
            </div>
          </div>
        )}

        <Form.Item
          label="Effective Date"
          name="effectiveDate"
          rules={[{ required: true, message: 'Effective date is required' }]}>
          <DatePicker className="w-full" format="YYYY-MM-DD" />
        </Form.Item>

        <Form.Item
          label="Mandatory Reason for Succession"
          name="reason"
          rules={[
            { required: true, message: 'Reason is required for audit verification' },
            { min: 5, message: 'Please provide at least 5 characters' },
          ]}>
          <Input.TextArea
            rows={3}
            placeholder="Document why this leadership position replacement is occurring (e.g. Promotion, Resignation, Succession Planning)..."
          />
        </Form.Item>

        <div className="flex items-center justify-end gap-2 pt-3 border-t border-border-subtle">
          <Button onClick={onClose}>Cancel</Button>
          <Button
            type="primary"
            htmlType="submit"
            loading={isLoading}
            disabled={!newManagerId || !currentManagerId}
            style={{ backgroundColor: '#E8583A' }}>
            Execute Manager Replacement
          </Button>
        </div>
      </Form>
    </Modal>
  );
};

import { useState, useMemo, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { PageHeader } from '@/components/ui/composed/PageHeader';
import { Dialog } from '@/components/ui/composed/Dialog';
import { useProfile } from './hooks/useProfile';
import { usePersistedTab } from '@/hooks/usePersistedTab';
import { AdminElevationRequest } from '../staff/components/AdminElevationRequest';
import { ProfileHeader, type TabType } from './components/ProfileHeader';
import { ProfileInfoTab } from './components/ProfileInfoTab';
import { OrganizationTab } from './components/OrganizationTab';
import { OverviewTab } from './components/OverviewTab';
import { ProfileForm } from './components/ProfileForm';
import { ChangePasswordModal } from '@/components/auth/ChangePasswordModal';
import { ManageUserRolesModal } from './components/ManageUserRolesModal';
import {
  getEmployeeProfile,
  getFormConfiguration,
  calculateCompletionPercentage,
  getIncompleteRequiredSections,
  syncProfilesFromBackend,
} from '@/services/employeeProfileService';
import { useGetMyProfileCompletionQuery } from '@/store/api/employeeProfileApiSlice';
import { FileCheck, ShieldCheck, KeyRound, ChevronRight } from 'lucide-react';

const Profile = () => {
  const {
    user,
    isEditing,
    setIsEditing,
    showElevationDialog,
    setShowElevationDialog,
    handleEditSave,
    addRole,
    removeRole,
    updateRolesLocally,
    handleAutoApproveToggle,
    isUpdatingAutoApprove,
    isLoadingAutoApprove,
  } = useProfile();

  const [showManageRolesModal, setShowManageRolesModal] = useState(false);

  const { data: myProfileRes } = useGetMyProfileCompletionQuery(undefined, {
    pollingInterval: 10000,
  });

  // Preserve current tab across browser refresh and direct URL links
  const [activeTab, setActiveTab] = usePersistedTab<TabType>({
    paramName: 'tab',
    defaultTab: 'profile',
    storageKey: 'aether_profile_active_tab',
    validTabs: ['overview', 'profile', 'organization'],
  });

  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [profileRefresh, setProfileRefresh] = useState(0);

  useEffect(() => {
    syncProfilesFromBackend();
  }, []);

  useEffect(() => {
    const handleUpdate = () => setProfileRefresh((p) => p + 1);
    window.addEventListener('aether_employee_profiles_updated', handleUpdate);
    window.addEventListener('auth_user_updated', handleUpdate);
    window.addEventListener('storage', handleUpdate);
    return () => {
      window.removeEventListener('aether_employee_profiles_updated', handleUpdate);
      window.removeEventListener('auth_user_updated', handleUpdate);
      window.removeEventListener('storage', handleUpdate);
    };
  }, []);

  const empProfile = useMemo(() => {
    if (myProfileRes?.data) return myProfileRes.data;
    if (!user) return null;
    const byEmail = user.email ? getEmployeeProfile(user.email) : null;
    return byEmail ?? (user.id ? getEmployeeProfile(user.id) : null);
  }, [myProfileRes, user?.id, user?.email, profileRefresh]);

  const effectiveUser = useMemo(() => {
    let id =
      empProfile?.employeeId && empProfile.employeeId !== 'N/A' && empProfile.employeeId !== 'NA'
        ? empProfile.employeeId
        : user.employeeId && user.employeeId !== 'N/A' && user.employeeId !== 'NA'
          ? user.employeeId
          : null;

    // Last resort: check staff list directly
    if (!id) {
      try {
        const staffStr = localStorage.getItem('aether_staff_list');
        if (staffStr) {
          const list = JSON.parse(staffStr);
          const found = list.find(
            (s: any) =>
              (user.email && s.email?.toLowerCase() === user.email.toLowerCase()) ||
              (user.id && String(s.id) === String(user.id))
          );
          if (found && (found.employee_code || found.employee_id || found.employeeId)) {
            id = found.employee_code || found.employee_id || found.employeeId;
          }
        }
      } catch {}
    }

    return {
      ...user,
      employeeId: id || 'N/A',
      address:
        user.address ||
        empProfile?.personal?.currentAddress ||
        empProfile?.personal?.permanentAddress ||
        '',
      contactNo: user.contactNo || empProfile?.personal?.contactNumber || '',
    };
  }, [user, empProfile]);

  const formConfig = useMemo(() => getFormConfiguration(), []);

  const completionPct = useMemo(() => {
    return calculateCompletionPercentage(empProfile, formConfig);
  }, [empProfile, formConfig]);

  const incompleteSections = useMemo(() => {
    return getIncompleteRequiredSections(empProfile, formConfig);
  }, [empProfile, formConfig]);

  return (
    <div className="flex flex-col gap-6 pb-20 animate-in fade-in slide-in-from-bottom-4 duration-500 mx-auto w-full">
      <PageHeader
        title="User Profile"
        description="View and edit your personal details, contact matrix, and organizational hierarchy."
        primaryAction={
          !isEditing
            ? {
                label: 'Edit Profile',
                onClick: () => setIsEditing(true),
                icon: 'pi pi-user-edit',
                className:
                  'px-6! py-3! rounded-2xl! font-bold! tracking-wide! shadow-md! shadow-primary/20!',
              }
            : undefined
        }
      />

      {/* Onboarding & Profile Verification Widget */}
      <div className="p-6 rounded-3xl bg-surface-subtle border border-border-subtle flex flex-col md:flex-row items-stretch md:items-center justify-between gap-5 shadow-xs">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-2xl bg-primary/10 flex items-center justify-center shrink-0 text-primary">
            {completionPct === 100 ? <ShieldCheck size={24} /> : <FileCheck size={24} />}
          </div>
          <div>
            <div className="flex items-center gap-2 flex-wrap">
              <h4 className="text-sm font-black text-foreground">
                Employee Verification & Profile Completion
              </h4>
              <span
                className={`text-[10px] font-bold px-2.5 py-0.5 rounded-full border ${
                  empProfile?.status === 'id_assigned' || empProfile?.status === 'approved'
                    ? 'bg-success/10 text-success border-success/20'
                    : empProfile?.status === 'submitted'
                      ? 'bg-info/10 text-info border-info/20'
                      : empProfile?.status === 'changes_required'
                        ? 'bg-warning/10 text-warning border-warning/20'
                        : 'bg-primary/10 text-primary border-primary/20'
                }`}>
                {empProfile?.status
                  ? empProfile.status.replace('_', ' ').toUpperCase()
                  : 'INCOMPLETE'}
              </span>
              {empProfile?.employeeId && (
                <span className="text-[11px] font-mono font-bold text-primary bg-primary/5 px-2 py-0.5 rounded-md border border-primary/15 flex items-center gap-1">
                  <KeyRound size={11} />
                  ID: {empProfile.employeeId}
                </span>
              )}
            </div>
            <p className="text-xs text-muted mt-1">
              {completionPct === 100
                ? 'All mandatory onboarding fields and documents have been submitted.'
                : `${incompleteSections.length} mandatory section${
                    incompleteSections.length === 1 ? '' : 's'
                  } pending verification (${incompleteSections.map((s) => s.label).join(', ')}).`}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-4 shrink-0">
          <div className="text-right hidden sm:block">
            <div className="text-xs font-bold text-foreground">{completionPct}% Completed</div>
            <div className="w-28 h-1.5 bg-border-subtle rounded-full overflow-hidden mt-1">
              <div
                className={`h-full ${
                  completionPct === 100 ? 'bg-success' : 'bg-primary'
                } transition-all duration-500`}
                style={{ width: `${completionPct}%` }}
              />
            </div>
          </div>

          <Link
            to="/profile-completion"
            className="px-5 py-2.5 rounded-xl bg-primary text-white hover:bg-primary/90 text-xs font-bold shadow-xs transition-all flex items-center gap-2 shrink-0">
            <span>{completionPct === 100 ? 'View Details' : 'Complete Profile'}</span>
            <ChevronRight size={14} />
          </Link>
        </div>
      </div>

      {/* Header Container & Navigation Tabs */}
      <ProfileHeader
        user={effectiveUser}
        isEditing={isEditing}
        activeTab={activeTab}
        onTabChange={setActiveTab}
        onStartEdit={() => setIsEditing(true)}
        onChangePassword={() => setShowPasswordModal(true)}
        onAddRole={addRole}
        onRemoveRole={removeRole}
        onManageRoles={() => setShowManageRolesModal(true)}
      />

      {/* Main Tab Content / Form View */}
      {isEditing ? (
        <div className="bg-surface-elevated rounded-3xl border border-border-subtle p-8 shadow-soft">
          <ProfileForm
            initialData={effectiveUser}
            onSave={handleEditSave}
            onCancel={() => setIsEditing(false)}
          />
        </div>
      ) : (
        <>
          {activeTab === 'profile' && (
            <ProfileInfoTab
              user={effectiveUser}
              empProfile={empProfile}
              isEditing={isEditing}
              onStartEdit={() => setIsEditing(true)}
              onElevationClick={() => setShowElevationDialog(true)}
            />
          )}

          {activeTab === 'organization' && <OrganizationTab user={effectiveUser} />}

          {activeTab === 'overview' && <OverviewTab user={effectiveUser} empProfile={empProfile} />}
        </>
      )}

      {/* Elevation Dialog */}
      <Dialog
        visible={showElevationDialog}
        onHide={() => setShowElevationDialog(false)}
        header="Request Admin Rights Elevation"
        style={{ width: 'min(450px, calc(100vw - 2rem))' }}>
        <AdminElevationRequest onSuccess={() => setShowElevationDialog(false)} />
      </Dialog>

      <div className="flex items-center gap-3">
        <span className="font-medium">Auto Approve</span>

        <button
          type="button"
          onClick={handleAutoApproveToggle}
          disabled={isUpdatingAutoApprove || isLoadingAutoApprove}
          className={`relative h-6 w-11 rounded-full transition-colors ${
            user.autoApprove ? 'bg-primary' : 'bg-gray-300'
          } ${
            isUpdatingAutoApprove || isLoadingAutoApprove ? 'cursor-not-allowed opacity-50' : ''
          }`}
          aria-pressed={user.autoApprove}
          aria-label="Toggle auto approve">
          <span
            className={`absolute top-1 left-1 h-4 w-4 rounded-full bg-white shadow transition-transform ${
              user.autoApprove ? 'translate-x-5' : 'translate-x-0'
            }`}
          />
        </button>

        <span className="text-sm text-muted-foreground">{user.autoApprove ? 'True' : 'False'}</span>
      </div>

      <ChangePasswordModal
        visible={showPasswordModal}
        onHide={() => setShowPasswordModal(false)}
        requireCurrentPassword={true}
      />

      {/* Role Management Dialog right on User Profile */}
      <ManageUserRolesModal
        visible={showManageRolesModal}
        onClose={() => setShowManageRolesModal(false)}
        user={effectiveUser}
        onSaved={updateRolesLocally}
      />
    </div>
  );
};

export default Profile;

