import { showToast } from '@/components/ui/composed/Toast.utils';
import { recordAuditLog } from '@/services/auditService';
import { getEmployeeProfile } from '@/services/employeeProfileService';
import { useUpdateProfileMutation } from '@/store/api/authApiSlice';
import { useGetAutoApproveQuery, useUpdateAutoApproveMutation } from '@/store/api/settingslice';
import { useGetUsersQuery, useUpdateStaffMutation } from '@/store/api/userSlice';
import { useEffect, useMemo, useState } from 'react';
import { useAuth } from '../../../hooks/useAuth';
import { isSuperAdmin, getUserRoles } from '@/utils/pagePermissions';

export interface ManagerInfo {
  name: string;
  role: string;
  code: string;
  reportsCount: number;
  image?: string;
}

export interface TeamMemberInfo {
  id: string;
  name: string;
  role: string;
  initials: string;
  image?: string;
}

export interface ProfileUserData {
  id?: number | string;
  name: string;
  designation: string;
  employeeId: string;
  employeeCode: string;
  email: string;
  contactNo: string;
  department: string;
  joinDate: string;
  image: string;
  workLocation: string;
  company: string;
  country: string;
  employeeType: string;
  tNumber: string;
  costCenter: string;
  subOrganization: string;
  statusText: string;
  lastSeen: string;
  workHours: string;
  autoApprove: boolean;
  address?: string;
  roles: Array<{
    id: string;
    name: string;
    color?: string;
  }>;
  manager: ManagerInfo | null;
  lineLeader: ManagerInfo | null;
  teamMembers: TeamMemberInfo[];
}

const resolveEmployeeCode = (
  auth: any,
  record?: Record<string, unknown> | null,
  fallbackStaff?: { employee_code?: string; employee_id?: string; id?: string | number } | null
): string => {
  const code =
    auth?.employee_code ||
    record?.employee_code ||
    auth?.employeeCode ||
    record?.employeeCode ||
    fallbackStaff?.employee_code ||
    auth?.employee_id ||
    record?.employee_id ||
    fallbackStaff?.employee_id ||
    (auth?.id ? `EMP-${String(auth.id).padStart(3, '0')}` : undefined) ||
    (fallbackStaff?.id ? `EMP-${String(fallbackStaff.id).padStart(3, '0')}` : undefined) ||
    'N/A';
  return String(code);
};

const resolveEmployeeId = (
  auth: any,
  record?: Record<string, unknown> | null,
  fallbackStaff?: { employee_id?: string; employee_code?: string; id?: string | number } | null
): string => {
  const idVal =
    auth?.employee_id ||
    record?.employee_id ||
    fallbackStaff?.employee_id ||
    auth?.employee_code ||
    record?.employee_code ||
    fallbackStaff?.employee_code ||
    (auth?.id ? String(auth.id) : undefined) ||
    (fallbackStaff?.id ? String(fallbackStaff.id) : undefined) ||
    'N/A';
  return String(idVal);
};

export const useProfile = () => {
  const { user: authUser, logout: authLogout, updateUser } = useAuth();
  const { data: usersList } = useGetUsersQuery(undefined, { skip: !authUser });

  const matchedStaff = usersList?.find(
    (u) =>
      (authUser?.id && String(u.id) === String(authUser.id)) ||
      (authUser?.email && u.email?.toLowerCase() === authUser.email.toLowerCase())
  );

  /**
   * Only these roles can manage Auto Approve.
   */
  const userRolesList = useMemo(() => getUserRoles(authUser), [authUser]);
  const isSuper = useMemo(() => isSuperAdmin(authUser), [authUser]);

  const canManageAutoApprove =
    isSuper || userRolesList.some((r) => ['Admin', 'SuperAdmin', 'HrAdmin'].includes(r));

  const isAdmin = isSuper || userRolesList.includes('Admin');

  const [updateProfile, { isLoading: isUpdating }] = useUpdateProfileMutation();
  const [updateStaff] = useUpdateStaffMutation();

  const [updateAutoApprove, { isLoading: isUpdatingAutoApprove }] = useUpdateAutoApproveMutation();

  /**
   * Get current Auto Approve setting.
   *
   * The query is skipped for users who don't have
   * permission to manage Auto Approve.
   */
  const { data: autoApproveFromApi, isLoading: isLoadingAutoApprove } = useGetAutoApproveQuery(
    undefined,
    {
      skip: !canManageAutoApprove,
    }
  );

  const [isEditing, setIsEditing] = useState(false);
  const [showElevationDialog, setShowElevationDialog] = useState(false);

  const { data: dbUsers = [] } = useGetUsersQuery();

  const currentDbUser = useMemo(() => {
    if (!authUser || !dbUsers || dbUsers.length === 0) return null;
    return (
      dbUsers.find(
        (u) =>
          (authUser.email &&
            u.email?.toLowerCase().trim() === authUser.email.toLowerCase().trim()) ||
          (authUser.id && String(u.id) === String(authUser.id))
      ) || null
    );
  }, [authUser, dbUsers]);

  const emp = useMemo(() => {
    if (!authUser) return null;
    return getEmployeeProfile(authUser.id) || getEmployeeProfile(authUser.email) || null;
  }, [authUser, dbUsers]);

  const authUserRecord = authUser as unknown as Record<string, unknown> | null;

  const [user, setUser] = useState<ProfileUserData>(() => {
    const name = authUser?.username || '';
    const email = authUser?.email || '';

    const userRole = authUser?.role || 'User';
    const dbRoles = (matchedStaff?.roles as any[]) || (currentDbUser?.roles as any);
    const initialRoles =
      (Array.isArray(dbRoles) && dbRoles.length > 0
        ? dbRoles.map((r: any) => ({
            id: String(r.id || r.name),
            name: typeof r === 'string' ? r : r.name,
            color:
              (r.name || r)?.toLowerCase().includes('admin') ||
              (r.name || r)?.toLowerCase().includes('founder')
                ? 'red'
                : 'blue',
          }))
        : null) ||
      (authUserRecord?.roles as Array<{
        id: string;
        name: string;
        color?: string;
      }>) || [
        {
          id: '1',
          name: userRole,
          color: userRole === 'SuperAdmin' ? 'red' : userRole === 'Admin' ? 'blue' : 'emerald',
        },
      ];

    const initialCode = resolveEmployeeCode(authUser, authUserRecord);
    const initialId = resolveEmployeeId(authUser, authUserRecord);

    return {
      id: authUser?.id,
      name: emp?.personal?.fullName || name,
      designation:
        currentDbUser?.designation ||
        emp?.designation ||
        authUser?.designation ||
        (isAdmin ? 'Administrator' : 'Staff Member'),

      employeeId: initialId,

      employeeCode: initialCode,

      email,

      contactNo:
        emp?.personal?.contactNumber ||
        currentDbUser?.contact_no ||
        currentDbUser?.phone ||
        authUser?.contact_number ||
        '',

      department: currentDbUser?.department || emp?.department || authUser?.department || '',

      joinDate: authUser?.join_date || '',

      image:
        emp?.profilePictureUrl ||
        authUser?.image_url ||
        `https://api.dicebear.com/7.x/notionists/svg?seed=${encodeURIComponent(name || 'User')}`,

      workLocation: (authUserRecord?.work_location as string) || emp?.department || '',

      company: (authUserRecord?.company as string) || '',

      country: (authUserRecord?.country as string) || '',

      employeeType:
        (authUserRecord?.employee_type as string) ||
        (authUser?.role === 'SuperAdmin' || authUser?.role === 'Admin' ? authUser.role : ''),

      tNumber: (authUserRecord?.t_number as string) || '',

      costCenter: (authUserRecord?.cost_center as string) || '',

      subOrganization: (authUserRecord?.sub_organization as string) || authUser?.department || '',

      statusText: (authUserRecord?.status_text as string) || 'Active',

      lastSeen: (authUserRecord?.last_seen as string) || 'Recently active',

      workHours: (authUserRecord?.work_hours as string) || 'Standard Hours',

      address:
        (authUserRecord?.address as string) ||
        emp?.personal?.currentAddress ||
        emp?.personal?.permanentAddress ||
        '',

      /**
       * This gets updated from useGetAutoApproveQuery()
       * after the API response arrives.
       */
      autoApprove: false,

      roles: initialRoles,

      manager: (authUserRecord?.manager as ManagerInfo) || null,

      lineLeader: (authUserRecord?.line_leader as ManagerInfo) || null,

      teamMembers: (authUserRecord?.team_members as TeamMemberInfo[]) || [],
    };
  });

  /**
   * Sync Auto Approve value from backend.
   */
  useEffect(() => {
    if (typeof autoApproveFromApi === 'boolean') {
      setUser((prev) => ({
        ...prev,
        autoApprove: autoApproveFromApi,
      }));
    }
  }, [autoApproveFromApi]);

  /**
   * Sync authenticated user data.
   */
  useEffect(() => {
    if (!authUser) return;

    const record = authUser as unknown as Record<string, unknown>;
    const code = resolveEmployeeCode(authUser, record, matchedStaff);
    const id = resolveEmployeeId(authUser, record, matchedStaff);

    setUser((prev) => ({
      ...prev,

      id: authUser.id ?? prev.id,

      designation: authUser.designation || (isAdmin ? 'Administrator' : prev.designation),

      employeeId: id !== 'N/A' ? id : prev.employeeId,

      employeeCode: code !== 'N/A' ? code : prev.employeeCode,

      email: authUser.email || prev.email,

      contactNo:
        emp?.personal?.contactNumber ||
        currentDbUser?.contact_no ||
        currentDbUser?.phone ||
        authUser.contact_number ||
        prev.contactNo,

      image: emp?.profilePictureUrl || authUser.image_url || prev.image,

      department:
        currentDbUser?.department || emp?.department || authUser.department || prev.department,

      joinDate: authUser.join_date || prev.joinDate,

      workLocation: (record.work_location as string) || emp?.department || prev.workLocation,

      company: (record.company as string) ?? prev.company,

      country: (record.country as string) ?? prev.country,

      employeeType: (record.employee_type as string) ?? prev.employeeType,

      tNumber: (record.t_number as string) ?? prev.tNumber,

      costCenter: (record.cost_center as string) ?? prev.costCenter,

      subOrganization: (record.sub_organization as string) ?? prev.subOrganization,

      statusText: (record.status_text as string) ?? prev.statusText,

      lastSeen: (record.last_seen as string) ?? prev.lastSeen,

      workHours: (record.work_hours as string) ?? prev.workHours,
      address:
        (record.address as string) ||
        emp?.personal?.currentAddress ||
        emp?.personal?.permanentAddress ||
        prev.address,

      manager: matchedStaff?.reporting_manager_name
        ? {
            name: matchedStaff.reporting_manager_name,
            role: matchedStaff.reporting_manager_role || 'Reporting Manager',
            code: matchedStaff.reporting_manager_email || '',
            reportsCount: 1,
            image: matchedStaff.reporting_manager_image || undefined,
          }
        : (record.manager as ManagerInfo) ?? prev.manager,

      roles: (() => {
        // Priority 1: matchedStaff.roles from database (Single source of truth!)
        if (matchedStaff?.roles && matchedStaff.roles.length > 0) {
          const seen = new Set<string>();
          const list: any[] = [];
          for (const r of matchedStaff.roles as any[]) {
            const name = typeof r === 'string' ? r : r.name;
            const id = typeof r === 'string' ? r : r.id;
            const k = (name || '').trim().toLowerCase();
            if (k && !seen.has(k)) {
              seen.add(k);
              list.push({
                id: String(id || k),
                name,
                color:
                  name?.toLowerCase().includes('admin') || name?.toLowerCase().includes('founder')
                    ? 'red'
                    : 'blue',
              });
            }
          }
          if (list.length > 0) return list;
        }

        // Priority 2: Check if in-memory user already has multiple assigned roles
        if (prev.roles && prev.roles.length > 1) {
          return prev.roles;
        }

        // Priority 3: authUser.roles from AuthContext / localStorage
        const authRoles = (authUserRecord?.roles as any[]) || (authUser as any)?.roles;
        if (Array.isArray(authRoles) && authRoles.length > 0) {
          const seen = new Set<string>();
          const list: any[] = [];
          for (const r of authRoles) {
            const name = typeof r === 'string' ? r : r.name;
            const id = typeof r === 'string' ? r : r.id;
            const k = (name || '').trim().toLowerCase();
            if (k && !seen.has(k)) {
              seen.add(k);
              list.push({
                id: String(id || k),
                name,
                color:
                  name?.toLowerCase().includes('admin') || name?.toLowerCase().includes('founder')
                    ? 'red'
                    : 'blue',
              });
            }
          }
          if (list.length > 0) return list;
        }

        return prev.roles;
      })(),

      lineLeader: (record.line_leader as ManagerInfo) ?? prev.lineLeader,

      teamMembers: (record.team_members as TeamMemberInfo[]) ?? prev.teamMembers,
    }));

    // If authUser does not yet have employee_code, populate it into AuthContext + localStorage
    if (code && code !== 'N/A' && !authUser.employee_code) {
      updateUser({ employee_code: code, employeeCode: code });
    }

    // Sync database roles into authUser if matchedStaff has fresh roles from DB
    if (matchedStaff?.roles && matchedStaff.roles.length > 0) {
      const authRoleCount = Array.isArray(authUser.roles) ? authUser.roles.length : 1;
      if (matchedStaff.roles.length !== authRoleCount) {
        updateUser({ roles: matchedStaff.roles as any });
      }
    }
  }, [authUser, matchedStaff, isAdmin, updateUser]);

  /**
   * Toggle Auto Approve.
   *
   * Backend mutation is only allowed for:
   * Admin
   * SuperAdmin
   * HrAdmin
   */
  const handleAutoApproveToggle = async () => {
    if (!canManageAutoApprove) {
      showToast({
        severity: 'warn',
        summary: 'Permission Denied',
        detail: 'You do not have permission to change Auto Approve.',
        life: 3000,
      });

      return;
    }

    const newValue = !user.autoApprove;

    try {
      await updateAutoApprove({
        autoapprove: newValue,
      }).unwrap();

      setUser((prev) => ({
        ...prev,
        autoApprove: newValue,
      }));

      showToast({
        severity: 'success',
        summary: 'Auto Approve Updated',
        detail: `Auto approve ${newValue ? 'enabled' : 'disabled'}`,
        life: 2500,
      });
    } catch (err: unknown) {
      const apiError = err as {
        data?: {
          message?: string;
        };
      };

      console.error('Failed to update auto approve:', err);

      showToast({
        severity: 'error',
        summary: 'Error',
        detail: apiError.data?.message || 'Failed to update auto approve',
        life: 3000,
      });
    }
  };

  /**
   * Add role.
   */
  const addRole = (roleName: string) => {
    if (!roleName.trim()) return;

    const colors = ['emerald', 'amber', 'indigo', 'rose', 'sky', 'purple', 'teal'];
    const randomColor = colors[Math.floor(Math.random() * colors.length)];

    const newRole = {
      id: Date.now().toString(),
      name: roleName.trim(),
      color: randomColor,
    };

    const updatedRoles = [
      ...user.roles.filter((r) => r.name.toLowerCase() !== roleName.trim().toLowerCase()),
      newRole,
    ];

    setUser((prev) => ({
      ...prev,
      roles: updatedRoles,
    }));

    // Persist in localStorage and AuthContext
    const existingUser = JSON.parse(localStorage.getItem('user') || '{}');
    const updatedUser = {
      ...existingUser,
      roles: updatedRoles,
    };
    updateUser(updatedUser);

    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('aether_user_updated', { detail: updatedUser }));
    }

    // Sync with database if user ID exists
    if (user.id) {
      const validRoleIds = updatedRoles
        .map((r) => Number(r.id))
        .filter((id) => !isNaN(id) && id > 0);
      updateStaff({
        id: user.id,
        roles: updatedRoles,
        ...(validRoleIds.length > 0 ? { roleIds: validRoleIds } : {}),
      } as any)
        .unwrap()
        .catch(() => {});
    }

    showToast({
      severity: 'success',
      summary: 'Role Added',
      detail: `Role "${roleName}" added successfully`,
      life: 2000,
    });
  };

  /**
   * Remove role.
   */
  const removeRole = (roleId: string) => {
    const updatedRoles = user.roles.filter((r) => r.id !== roleId);

    setUser((prev) => ({
      ...prev,
      roles: updatedRoles,
    }));

    // Persist in localStorage and AuthContext
    const existingUser = JSON.parse(localStorage.getItem('user') || '{}');
    const updatedUser = {
      ...existingUser,
      roles: updatedRoles,
    };
    updateUser(updatedUser);

    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('aether_user_updated', { detail: updatedUser }));
    }

    // Sync with database if user ID exists
    if (user.id) {
      const validRoleIds = updatedRoles
        .map((r) => Number(r.id))
        .filter((id) => !isNaN(id) && id > 0);
      updateStaff({
        id: user.id,
        roles: updatedRoles,
        ...(validRoleIds.length > 0 ? { roleIds: validRoleIds } : {}),
      } as any)
        .unwrap()
        .catch(() => {});
    }

    showToast({
      severity: 'info',
      summary: 'Role Removed',
      detail: 'Role removed from profile',
      life: 2000,
    });
  };

  /**
   * Save profile.
   */
  const handleEditSave = async (updatedData: {
    name: string;
    email: string;
    contactNo: string;
    designation: string;
    department: string;
    employeeCode?: string;
    workLocation?: string;
    company?: string;
    country?: string;
    employeeType?: string;
    subOrganization?: string;
    address?: string;
  }) => {
    try {
      // Calculate field diffs for audit log
      const changedFields: Array<{ field: string; from: any; to: any }> = [];
      if (user.name !== updatedData.name) {
        changedFields.push({ field: 'name', from: user.name, to: updatedData.name });
      }
      if (user.email !== updatedData.email) {
        changedFields.push({ field: 'email', from: user.email, to: updatedData.email });
      }
      if (user.contactNo !== updatedData.contactNo) {
        changedFields.push({ field: 'contactNo', from: user.contactNo, to: updatedData.contactNo });
      }
      if (user.designation !== updatedData.designation) {
        changedFields.push({
          field: 'designation',
          from: user.designation,
          to: updatedData.designation,
        });
      }
      if (user.department !== updatedData.department) {
        changedFields.push({
          field: 'department',
          from: user.department,
          to: updatedData.department,
        });
      }
      if (user.workLocation !== (updatedData.workLocation || '')) {
        changedFields.push({
          field: 'workLocation',
          from: user.workLocation,
          to: updatedData.workLocation || '',
        });
      }
      if (user.address !== (updatedData.address || '')) {
        changedFields.push({
          field: 'address',
          from: user.address || '',
          to: updatedData.address || '',
        });
      }
      if (user.company !== (updatedData.company || '')) {
        changedFields.push({ field: 'company', from: user.company, to: updatedData.company || '' });
      }

      const payload = {
        username: updatedData.name,
        email: updatedData.email,
        contact_no: updatedData.contactNo,
        designation: updatedData.designation,
        department: updatedData.department,
        work_location: updatedData.workLocation,
        company: updatedData.company,
        country: updatedData.country,
        employee_type: updatedData.employeeType,
        sub_organization: updatedData.subOrganization,
        address: updatedData.address,
      };

      const result = await updateProfile(payload)
        .unwrap()
        .catch(() => null);

      setUser((prev) => ({
        ...prev,
        ...updatedData,
        employeeCode: updatedData.employeeCode || prev.employeeCode,
      }));

      // Update stored user in AuthContext + localStorage
      const existingUser = JSON.parse(localStorage.getItem('user') || '{}');
      const updatedUser = {
        ...existingUser,
        username: updatedData.name,
        email: updatedData.email,
        contact_number: updatedData.contactNo,
        designation: updatedData.designation,
        department: updatedData.department,
        employee_code: updatedData.employeeCode || user.employeeCode,
        employeeCode: updatedData.employeeCode || user.employeeCode,
        work_location: updatedData.workLocation,
        address: updatedData.address,
        company: updatedData.company,
        country: updatedData.country,
        ...(result?.user || {}),
      };

      updateUser(updatedUser);

      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('aether_user_updated', { detail: updatedUser }));
      }

      // Record in centralized audit log
      if (changedFields.length > 0) {
        recordAuditLog({
          action: 'Profile Updated',
          category: 'profile',
          user: user.name || authUser?.username || 'User',
          userEmail: user.email || authUser?.email || '',
          target: `${updatedData.name} Profile`,
          targetEmail: updatedData.email,
          status: 'Success',
          details: `Updated personal information: ${changedFields.map((c) => c.field).join(', ')}.`,
          changes: changedFields,
        });
      }

      setIsEditing(false);

      showToast({
        severity: 'success',
        summary: 'Success',
        detail: 'Profile updated successfully and reflected across the application.',
        life: 3000,
      });
    } catch (err: unknown) {
      const apiError = err as {
        data?: {
          message?: string;
        };
      };

      console.error('Failed to update profile:', err);

      showToast({
        severity: 'error',
        summary: 'Error',
        detail: apiError.data?.message || 'Failed to update profile',
        life: 3000,
      });
    }
  };

  /**
   * Logout.
   */
  const handleLogout = async () => {
    try {
      await authLogout();
      window.location.href = '/auth/login';
    } catch (error) {
      console.error('Logout failed:', error);
    }
  };

  const updateRolesLocally = (newRoles: Array<{ id: string | number; name: string; color?: string }>) => {
    const formatted = newRoles.map((r) => ({
      id: String(r.id),
      name: r.name,
      color:
        r.name?.toLowerCase().includes('admin') || r.name?.toLowerCase().includes('founder')
          ? 'red'
          : 'blue',
    }));
    setUser((prev) => ({
      ...prev,
      roles: formatted,
    }));
    updateUser({
      roles: formatted as any,
    });
    try {
      const stored = JSON.parse(localStorage.getItem('user') || '{}');
      localStorage.setItem('user', JSON.stringify({ ...stored, roles: formatted }));
      window.dispatchEvent(
        new CustomEvent('aether_user_updated', {
          detail: { ...stored, roles: formatted },
        })
      );
    } catch {}
  };

  return {
    user,

    isAdmin,

    // Auto Approve
    canManageAutoApprove,
    isUpdatingAutoApprove,
    isLoadingAutoApprove,
    handleAutoApproveToggle,

    // Profile
    isUpdating,
    isEditing,
    setIsEditing,

    // Elevation
    showElevationDialog,
    setShowElevationDialog,

    // Actions
    handleEditSave,
    handleLogout,
    addRole,
    removeRole,
    updateRolesLocally,
  };
};

import { CalendarCheck, Clock3, CircleAlert, CheckCircle2 } from 'lucide-react';

interface BookingStatsProps {
  bookings: any[];
}

const BookingStats = ({ bookings }: BookingStatsProps) => {
  const total = bookings.length;

  const confirmed = bookings.filter(
    (booking) => booking.status?.toLowerCase() === 'confirmed'
  ).length;

  const pending = bookings.filter((booking) => booking.status?.toLowerCase() === 'pending').length;

  const cancelled = bookings.filter(
    (booking) => booking.status?.toLowerCase() === 'cancelled'
  ).length;

  const stats = [
    {
      label: 'My Bookings',
      value: total,
      icon: CalendarCheck,
      color: 'text-blue-600',
      bg: 'bg-blue-50',
    },
    {
      label: 'Confirmed',
      value: confirmed,
      icon: CheckCircle2,
      color: 'text-green-600',
      bg: 'bg-green-50',
    },
    {
      label: 'Pending',
      value: pending,
      icon: Clock3,
      color: 'text-yellow-600',
      bg: 'bg-yellow-50',
    },
    {
      label: 'Cancelled',
      value: cancelled,
      icon: CircleAlert,
      color: 'text-red-600',
      bg: 'bg-red-50',
    },
  ];

  return (
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
      {stats.map((stat) => {
        const Icon = stat.icon;

        return (
          <div key={stat.label} className="rounded-xl border bg-card p-5">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">{stat.label}</p>

                <p className="mt-2 text-2xl font-semibold">{stat.value}</p>
              </div>

              <div className={`flex h-10 w-10 items-center justify-center rounded-lg ${stat.bg}`}>
                <Icon className={`h-5 w-5 ${stat.color}`} />
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default BookingStats;

