import { Input } from '@/components/ui/primitives/Input';
import { Tabs } from '@/components/ui/primitives/Tabs';
import { useGetDepartmentsQuery } from '@/store/api/authApiSlice';
import { Search } from 'lucide-react';

interface StaffTableToolbarProps {
  searchQuery: string;
  onSearchChange: (value: string) => void;
  activeDepartment: string;
  onDepartmentChange: (value: string) => void;
}

export function StaffTableToolbar({
  searchQuery,
  onSearchChange,
  activeDepartment,
  onDepartmentChange,
}: StaffTableToolbarProps) {
  const { data: departmentsData } = useGetDepartmentsQuery({});
  const departments = departmentsData?.data ?? [];
  const DEPARTMENTS = ['All', ...departments.map((d: any) => d.department_name)];

  return (
    <div className="flex flex-col gap-6 bg-white p-6 rounded-[40px] border border-border-subtle shadow-soft hover:shadow-lg transition-all duration-500">
      <div className="flex flex-col lg:flex-row items-center justify-between gap-6">
        {/* Search Input */}
        <div className="relative w-full lg:max-w-md group">
          <Search
            className="absolute left-5 top-1/2 -translate-y-1/2 text-muted group-focus-within:text-primary transition-colors"
            size={20}
          />
          <Input
            value={searchQuery}
            onChange={(e: any) => onSearchChange(e.target.value)}
            placeholder="Search by name, role, or skills..."
            className="pl-14! h-14! rounded-2xl! text-sm! font-medium! border-border-subtle! group-hover:border-primary/30 transition-all duration-300"
          />
        </div>
      </div>

      {/* Department Tabs */}
      <div className="overflow-x-auto pb-2 no-scrollbar">
        <Tabs items={DEPARTMENTS} activeItem={activeDepartment} onItemChange={onDepartmentChange} />
      </div>
    </div>
  );
}

import { useState } from 'react';
import {
  useGetAdminElevationRequestsQuery,
  useProcessAdminElevationMutation,
} from '@/store/api/authApiSlice';
import { showToast } from '@/components/ui/composed/Toast.utils';

export const useAdminRequests = () => {
  const { data: requests = [], isLoading, refetch } = useGetAdminElevationRequestsQuery();
  const [processRequest] = useProcessAdminElevationMutation();

  const [selectedRequest, setSelectedRequest] = useState<any>(null);
  const [comment, setComment] = useState('');
  const [isApprove, setIsApprove] = useState(true);
  const [showDialog, setShowDialog] = useState(false);

  const handleAction = (request: any, approve: boolean) => {
    setSelectedRequest(request);
    setIsApprove(approve);
    setShowDialog(true);
  };

  const handleSubmit = async () => {
    try {
      await processRequest({
        requestId: selectedRequest.id,
        status: isApprove ? 'Approved' : 'Rejected',
        adminComment: comment,
      }).unwrap();
      showToast({
        severity: 'success',
        summary: 'Success',
        detail: `Request ${isApprove ? 'approved' : 'rejected'}.`,
        life: 3000,
      });
      setShowDialog(false);
      setComment('');
      refetch();
    } catch (error: any) {
      console.error('Failed to process request:', error);
      showToast({
        severity: 'error',
        summary: 'Error',
        detail: error.data?.message || 'Failed to process request.',
        life: 3000,
      });
    }
  };

  return {
    requests,
    isLoading,
    selectedRequest,
    comment,
    setComment,
    isApprove,
    showDialog,
    setShowDialog,
    handleAction,
    handleSubmit,
  };
};

import {
  useGetFeaturePermissionsQuery,
  useToggleFeatureMutation,
} from '@/store/api/permissionSlice';
import { showToast } from '@/components/ui/composed/Toast.utils';

export const useFeatureControl = () => {
  const { data: permissions = [], isLoading } = useGetFeaturePermissionsQuery();
  const [toggleFeature] = useToggleFeatureMutation();

  const handleToggle = async (feature_name: string, department: string, is_enabled: boolean) => {
    try {
      await toggleFeature({ feature_name, department, is_enabled }).unwrap();
      showToast({
        severity: 'success',
        summary: 'Success',
        detail: `Feature ${is_enabled ? 'enabled' : 'disabled'} for ${department}.`,
        life: 3000,
      });
    } catch (err: any) {
      console.error('Failed to toggle feature:', err);
      showToast({
        severity: 'error',
        summary: 'Error',
        detail: err.data?.message || 'Failed to toggle feature.',
        life: 3000,
      });
    }
  };

  const isEnabled = (feature: string, dept: string) => {
    return permissions.some(
      (p) => p.feature_name === feature && p.department === dept && p.is_enabled
    );
  };

  return {
    permissions,
    isLoading,
    handleToggle,
    isEnabled,
  };
};

import { useState } from 'react';
import { showToast } from '@/components/ui/composed/Toast.utils';
import { showConfirm } from '@/components/ui/composed/ConfirmDialog.utils';
import {
  useGetUsersQuery,
  useCreateStaffMutation,
  useUpdateStaffMutation,
  useDeleteUserMutation,
} from '@/store/api/userSlice';
import { usePromoteToAdminMutation } from '@/store/api/authApiSlice';
import { useSaveEmployeeCompensationMutation } from '@/store/api/financeApiSlice';
import { useStaffFilters } from './useStaffFilters';
import type { StaffMember } from '@/types/models';

export const useStaff = () => {
  const { data: staff = [], isLoading, isError } = useGetUsersQuery();
  const [createStaff] = useCreateStaffMutation();
  const [updateStaff] = useUpdateStaffMutation();
  const [deleteStaff] = useDeleteUserMutation();
  const [promoteToAdmin] = usePromoteToAdminMutation();
  const [saveEmployeeCompensation] = useSaveEmployeeCompensationMutation();

  const [showForm, setShowForm] = useState(false);
  const [editingMember, setEditingMember] = useState<StaffMember | null>(null);

  const { searchQuery, setSearchQuery, activeDepartment, setActiveDepartment } = useStaffFilters();

  const handlePromote = async (id: string) => {
    showConfirm({
      message: 'Are you sure you want to promote this member to Administrator?',
      header: 'Confirm Promotion',
      accept: async () => {
        try {
          await promoteToAdmin(id).unwrap();
          showToast({
            severity: 'success',
            summary: 'Success',
            detail: 'Member promoted to administrator successfully!',
            life: 3000,
          });
        } catch (err: unknown) {
          const apiError = err as { data?: { message?: string } };
          showToast({
            severity: 'error',
            summary: 'Error',
            detail: apiError.data?.message || 'Failed to promote member.',
            life: 3000,
          });
        }
      },
    });
  };

  const handleEdit = (id: string) => {
    const member = staff.find((m) => String(m.id) === String(id));
    if (member) {
      setEditingMember({
        ...member,
        name: member.username || member.name,
        role: member.designation || member.role,
        phone: member.contact_no || member.phone,
        image: member.image_url || member.image,
        joinDate: member.join_date || member.joinDate,
        totalCompensation:
          member.totalCompensation ||
          member.total_compensation ||
          member.annualCtc ||
          member.annual_ctc ||
          '',
        taxRegime: member.taxRegime || member.tax_regime || 'New Regime',
        isMidYearJoiner: Boolean(member.isMidYearJoiner ?? member.is_mid_year_joiner),
        previousEmployerYtd: member.previousEmployerYtd ||
          member.previous_employer_ytd || {
            grossPay: 0,
            tdsDeducted: 0,
            pfDeducted: 0,
            ptDeducted: 0,
          },
        panNumber: member.panNumber || member.pan_number || '',
      });
      setShowForm(true);
    }
  };

  const handleDelete = async (id: string) => {
    showConfirm({
      message: 'Are you sure you want to remove this staff member?',
      header: 'Confirm Deletion',
      accept: async () => {
        try {
          await deleteStaff(id).unwrap();
          showToast({
            severity: 'success',
            summary: 'Success',
            detail: 'Staff member removed successfully.',
            life: 3000,
          });
        } catch (err) {
          console.error('Failed to remove member', err);
          showToast({
            severity: 'error',
            summary: 'Error',
            detail: 'Failed to remove member.',
            life: 3000,
          });
        }
      },
    });
  };

  const handleSubmit = async (
    data: Partial<StaffMember> & { name?: string; role?: string; phone?: string; image?: string }
  ) => {
    try {
      const payload: Record<string, any> = {
        username: data.name,
        email: data.email,
        role: data.role || data.designation,
        department: data.department,
        contact_number: data.phone || data.contact_no,
        status: data.status,
        join_date: data.joinDate,
        skills: data.skills,
        image_url: data.image || data.image_url,
        total_compensation: data.totalCompensation || data.total_compensation,
        annual_ctc: data.totalCompensation || data.total_compensation,
        tax_regime: data.taxRegime || 'New Regime',
        is_mid_year_joiner: Boolean(data.isMidYearJoiner),
        previous_employer_ytd: data.previousEmployerYtd,
        pan_number: data.panNumber || data.pan_number,
      };

      let savedUserId = editingMember?.id;
      if (editingMember) {
        await updateStaff({ id: editingMember.id, ...payload }).unwrap();
        showToast({
          severity: 'success',
          summary: 'Success',
          detail: 'Staff member updated successfully.',
          life: 3000,
        });
      } else {
        const createRes: any = await createStaff(payload).unwrap();
        savedUserId = createRes?.id || createRes?.data?.id || createRes?.user?.id;
        showToast({
          severity: 'success',
          summary: 'Success',
          detail: 'Staff member added successfully.',
          life: 3000,
        });
      }

      // Also sync dedicated Employee Compensation endpoint if compensation entered
      if (savedUserId && data.totalCompensation) {
        try {
          await saveEmployeeCompensation({
            userId: Number(savedUserId),
            ctcAnnual: Number(data.totalCompensation),
            taxRegime: String(data.taxRegime || '')
              .toLowerCase()
              .includes('old')
              ? 'old'
              : 'new',
            payFrequency: (data.payFrequency || 'monthly').toLowerCase(),
            effectiveDate:
              data.effectiveDate || data.joinDate || new Date().toISOString().split('T')[0],
            isMidYearJoiner: Boolean(data.isMidYearJoiner),
            previousEmployerGross: Number(data.previousEmployerYtd?.grossPay || 0),
            previousEmployerTds: Number(data.previousEmployerYtd?.tdsDeducted || 0),
            previousEmployerPf: Number(data.previousEmployerYtd?.pfDeducted || 0),
            previousEmployerStandardDeduction: Number(
              data.previousEmployerStandardDeduction ||
                data.previousEmployerYtd?.standardDeduction ||
                0
            ),
            section80c: Number(data.section80c || 0),
            section80d: Number(data.section80d || 0),
            hraExemption: Number(data.hraExemption || 0),
          }).unwrap();
        } catch (compErr) {
          console.warn('Could not sync to dedicated compensation endpoint:', compErr);
        }
      }

      setShowForm(false);
    } catch (err: unknown) {
      console.error('Operation failed', err);
      showToast({ severity: 'error', summary: 'Error', detail: 'Operation failed.', life: 3000 });
    }
  };

  const filteredStaff = staff.filter((member) => {
    const matchesDepartment = activeDepartment === 'All' || member.department === activeDepartment;
    const name = member.username || member.name || '';
    const role = member.designation || member.role || '';
    const skills = member.skills || [];

    const matchesSearch =
      name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      role.toLowerCase().includes(searchQuery.toLowerCase()) ||
      skills.some((skill) => skill.toLowerCase().includes(searchQuery.toLowerCase()));
    return matchesDepartment && matchesSearch;
  });

  return {
    staff: filteredStaff,
    allStaffCount: staff.length,
    isLoading,
    isError,
    showForm,
    editingMember,
    setShowForm,
    searchQuery,
    setSearchQuery,
    activeDepartment,
    setActiveDepartment,
    handlePromote,
    handleEdit,
    handleDelete,
    handleSubmit,
    onAddMember: () => {
      setEditingMember(null);
      setShowForm(true);
    },
  };
};

