      status: form.status as Task['status'],
      project: form.project,
      duration: form.duration,
      assigneeTo: form.assigneeTo,
    };
    setTasks([newTask, ...tasks]);
    setForm(emptyForm);
    setSyncToJira(false);
    setIsSyncing(false);
    setShowForm(false);
  };

