  //     };

  //     try {
  //         const response = await createTask(payload).unwrap();

  //         setTasks([response, ...tasks]);

  //         setForm(emptyForm);
  //         setShowForm(false);

  //     } catch (error) {
  //         console.error("Task creation failed:", error);
  //     }
  // };

  return (
    <div className="flex flex-col gap-10 pb-20 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <PageHeader
        title="Tasks"
        description="Manage and track tasks across all projects."
        breadcrumbs={[{ label: 'Home', url: '/' }, { label: 'Tasks' }]}
        primaryAction={{ label: 'New Task', onClick: () => setShowForm(true), icon: 'pi pi-plus' }}
      />

      <div className="grid grid-cols-3 gap-6">
        {Object.entries(counts).map(([status, count]) => (
          <div
            key={status}
            className={`rounded-xl border p-6 shadow-soft flex items-center justify-between ${statusColors[status]}`}>
            <div className="flex flex-col gap-1">
              <span className="text-2xl font-black text-foreground">{count}</span>
              <span className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
                {status}
              </span>
            </div>
          </div>
        ))}
      </div>

      {/* Task Board Bar with Kanban vs Grid Switcher */}
      <div className="bg-white rounded-2xl border border-border-subtle shadow-soft p-4 px-6 flex flex-col sm:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <span className="text-sm font-black text-foreground uppercase tracking-wider">
            Pipeline View
          </span>
          <div className="flex items-center p-1 bg-surface-subtle rounded-xl border border-border-subtle">
            <button
              type="button"
              id="kanban-view-btn"
              onClick={() => setViewMode('kanban')}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-black transition-all cursor-pointer ${viewMode === 'kanban'
                  ? 'bg-white text-primary shadow-xs'
                  : 'text-muted hover:text-foreground'
                }`}>
              <Columns size={14} />
              <span>Kanban Board</span>
            </button>
            <button
              type="button"
              id="grid-view-btn"
              onClick={() => setViewMode('grid')}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-black transition-all cursor-pointer ${viewMode === 'grid'
                  ? 'bg-white text-primary shadow-xs'
                  : 'text-muted hover:text-foreground'
                }`}>
              <LayoutGrid size={14} />
              <span>Grid View</span>
            </button>
          </div>
        </div>
        {viewMode === 'grid' && (
          <Tabs items={TABS} activeItem={activeTab} onItemChange={setActiveTab} />
        )}
      </div>

      {viewMode === 'kanban' ? (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {(['To Do', 'In Progress', 'Done'] as const).map((status) => {
            const columnTasks = tasks.filter((t) => t.status === status);
            const statusConfig = {
              'To Do': { bar: 'bg-blue-500' },
              'In Progress': { bar: 'bg-amber-500' },
              Done: { bar: 'bg-emerald-500' },
            }[status];

            return (
              <div
                key={status}
                className="flex flex-col gap-4 p-5 rounded-3xl border border-border-subtle bg-surface-subtle/40 min-h-[500px]">
                {/* Column Header */}
                <div className="flex items-center justify-between pb-3 border-b border-border-subtle">
                  <div className="flex items-center gap-2">
                    <span className={`w-2.5 h-2.5 rounded-full ${statusConfig.bar}`} />
                    <h3 className="text-sm font-black text-foreground uppercase tracking-wider">
                      {status}
                    </h3>
                  </div>
                  <span className="w-6 h-6 rounded-full bg-white text-muted text-xs font-black flex items-center justify-center border border-border-subtle shadow-2xs">
                    {columnTasks.length}
                  </span>
                </div>

                {/* Column Cards */}
                <div className="flex flex-col gap-4 flex-1">
                  {columnTasks.map((task, i) => (
                    <motion.div
                      key={task.id}
                      initial={{ opacity: 0, y: 16 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ duration: 0.35, delay: i * 0.05 }}
                      className="bg-white rounded-2xl border border-border-subtle shadow-soft p-5 flex flex-col gap-3.5 hover:shadow-lg transition-all duration-300">
                      <div className="flex items-start justify-between gap-2">
                        <h4 className="text-sm font-bold text-foreground leading-snug flex-1">
                          {task.title}
                        </h4>
                        <span
                          className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider shrink-0 ${priorityColors[task.priority]}`}>
                          {task.priority}
                        </span>
                      </div>
                      <span className="text-[10px] font-medium text-primary/80 bg-primary/5 self-start px-2 py-0.5 rounded-md border border-primary/10">
                        {projects.find((p) => p.value === task.project)?.label || `Project #${task.project}`}
                      </span>
                      <p className="text-xs text-muted-foreground whitespace-pre-line leading-relaxed line-clamp-2">
                        {task.description}
                      </p>
                      <div className="flex items-center justify-between pt-2.5 border-t border-border-subtle/50 text-muted text-xs">
                        <div className="flex items-center gap-1.5">
                          <User size={12} />
                          <span>{users.find((u) => u.value === task.assignee)?.label || `User #${task.assignee}`}</span>
                        </div>
                        <div className="flex items-center gap-1.5">
                          <Calendar size={12} />
                          <span>
                            {new Date(task.dueDate).toLocaleDateString('en-US', {
                              month: 'short',
                              day: 'numeric',
                            })}
                          </span>
                        </div>
                      </div>

                      {/* Action Progression */}
                      <div className="flex items-center gap-2 pt-2 border-t border-border-subtle/30">
                        {task.status === 'To Do' && (
                          <button
                            type="button"
                            onClick={() => handleUpdateStatus(task.id, 'In Progress')}
                            className="flex-1 flex items-center justify-center gap-1 py-1.5 px-3 rounded-xl bg-primary/10 hover:bg-primary text-primary hover:text-white text-xs font-black transition-all cursor-pointer">
                            <span>Start Task</span>
                            <ArrowRight size={13} />
                          </button>
                        )}
                        {task.status === 'In Progress' && (
                          <>
                            <button
                              type="button"
                              onClick={() => handleUpdateStatus(task.id, 'To Do')}
                              className="py-1.5 px-2 rounded-xl bg-surface-subtle hover:bg-surface-elevated text-muted text-xs font-bold transition-all cursor-pointer">
                              &larr; To Do
                            </button>
                            <button
                              type="button"
                              onClick={() => handleUpdateStatus(task.id, 'Done')}
                              className="flex-1 flex items-center justify-center gap-1 py-1.5 px-3 rounded-xl bg-emerald-500 hover:bg-emerald-600 text-white text-xs font-black shadow-xs transition-all cursor-pointer">
                              <CheckCircle2 size={13} />
                              <span>Done</span>
                            </button>
                          </>
                        )}
                        {task.status === 'Done' && (
                          <button
                            type="button"
                            onClick={() => handleUpdateStatus(task.id, 'In Progress')}
                            className="flex-1 flex items-center justify-center gap-1 py-1.5 px-3 rounded-xl bg-surface-subtle hover:bg-surface-elevated text-muted hover:text-foreground text-xs font-bold transition-all cursor-pointer">
                            <Clock size={13} />
                            <span>Reopen Task</span>
                          </button>
                        )}
                      </div>
                    </motion.div>
                  ))}
                  {columnTasks.length === 0 && (
                    <div className="flex flex-col items-center justify-center flex-1 py-12 text-center text-muted border-2 border-dashed border-border-subtle rounded-2xl">
                      <span className="text-xs font-bold">No tasks in {status}</span>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filtered.map((task, i) => (
            <motion.div
              key={task.id}
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.35, delay: i * 0.05 }}
              className="bg-white rounded-xl border border-border-subtle shadow-soft p-7 flex flex-col gap-5 hover:shadow-lg transition-all duration-300">
              <div className="flex items-start justify-between">
                <h3 className="text-sm font-bold text-foreground leading-snug flex-1 pr-3">
                  {task.title}
                </h3>
                <span
                  className={`px-2.5 py-1 rounded text-[9px] font-bold uppercase tracking-wider shrink-0 ${priorityColors[task.priority]}`}>
                  {task.priority}
                </span>
              </div>
              <span className="text-xs font-medium text-primary/80 bg-primary/5 self-start px-3 py-1 rounded">
                {projects.find((p) => p.value === task.project)?.label || `Project #${task.project}`}
              </span>
              <p className="text-xs text-muted-foreground whitespace-pre-line leading-relaxed pt-1 line-clamp-3">
                {task.description}
              </p>
              <div className="flex items-center justify-between pt-3 border-t border-border-subtle/50">
                <div className="flex items-center gap-2 text-muted">
                  <User size={13} />
                  <span className="text-xs font-medium">{task.assignee}</span>
                </div>
                <div className="flex items-center gap-1.5 text-muted">
                  <Calendar size={13} />
                  <span className="text-xs font-medium">
                    {new Date(task.dueDate).toLocaleDateString('en-US', {
                      month: 'short',
                      day: 'numeric',
                    })}
                  </span>
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      )}

      {/* New Task Dialog */}
      <Dialog
        visible={showForm}
        onHide={() => setShowForm(false)}
        header="Create New Task"
        modal
        className="w-full max-w-xl mx-4"
        contentClassName="p-8"
        headerClassName="px-8 pt-8 pb-4 text-xl font-black tracking-tight border-none"
        pt={{
          root: { className: 'rounded-2xl overflow-hidden border-none shadow-2xl bg-white' },
          mask: { className: 'backdrop-blur-md bg-black/40' },
        }}>
        <div className="flex flex-col gap-5">
          <div className="flex flex-col gap-2">
            <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
              Task Title
            </label>
            <Input
              placeholder="e.g. Design new feature"
              value={form.title}
              onChange={(e) => setForm({ ...form, title: e.target.value })}
            />
          </div>

          <div className="flex flex-col gap-2">
            <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
              Task Description
            </label>
            <TextArea
              placeholder="e.g. Add a Sidebar"
              value={form.description}
              onChange={(e) => setForm({ ...form, description: e.target.value })}
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-2">
              <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
                Assignee
              </label>
              {/* <Input placeholder="e.g. John Doe" value={form.assignee} onChange={(e) => setForm({ ...form, assignee: e.target.value })} /> */}
              <Select
                options={users}
                value={form.assignee ?? undefined}
                onChange={(e) => setForm({ ...form, assignee: e.value })}
                placeholder="Assigned By"
                showSearch
                optionFilterProp="label"
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
                Due Date
              </label>
              <Input
                type="date"
                value={form.dueDate}
                onChange={(e) => setForm({ ...form, dueDate: e.target.value })}
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
                Task Duration
              </label>
              <Input
                placeholder="e.g. 7 Hours"
                value={form.duration}
                onChange={(e) => setForm({ ...form, duration: e.target.value })}
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
                Assiged To
              </label>
              {/* <Input placeholder="e.g. John Doe" value={form.assigneeTo} onChange={(e) => setForm({ ...form, assigneeTo: e.target.value })} /> */}
              <Select
                options={users}
                value={form.assigneeTo ?? undefined}
                onChange={(e) => setForm({ ...form, assigneeTo: e.value })}
                placeholder="Assigned To"
                showSearch
                optionFilterProp="label"
              />
            </div>
          </div>
          <div className="grid grid-cols-3 gap-4">
            <div className="flex flex-col gap-2">
              <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
                Priority
              </label>
              <Select
                options={PRIORITIES}
                value={form.priority}
                onChange={(e) => setForm({ ...form, priority: e.value })}
                placeholder="Priority"
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
                Status
              </label>
              <Select
                options={STATUSES}
                value={form.status}
                onChange={(e) => setForm({ ...form, status: e.value })}
                placeholder="Status"
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
                Project
              </label>
              <Select
                options={projects}
                value={form.project ?? undefined}
                onChange={(e) => setForm({ ...form, project: e.value })}
                placeholder="Project"
                showSearch
                optionFilterProp="label"
              />
            </div>
          </div>

          {isJiraConnected && jiraConfigStr && (
            <div className="flex items-center gap-3 p-4 rounded-xl bg-surface-subtle border border-border-subtle mt-2">
              <input
                type="checkbox"
                id="syncToJira"
                checked={syncToJira}
                onChange={(e) => setSyncToJira(e.target.checked)}
                disabled={isSyncing}
                className="w-4 h-4 cursor-pointer accent-primary"
              />
              <div className="flex flex-col gap-0.5">
                <label
                  htmlFor="syncToJira"
                  className="text-xs font-bold text-foreground cursor-pointer select-none">
                  Sync Task with Jira
                </label>
                <span className="text-[10px] text-muted italic">
                  Automatically generates a corresponding issue in Jira Cloud when created.
                </span>
              </div>
            </div>
          )}

          <div className="flex justify-end gap-3 pt-4 border-t border-border-subtle">
            <Button
              variant="ghost"
              label="Cancel"
              onClick={() => {
                setShowForm(false);
                setForm(emptyForm);
              }}
              className="rounded-md!"
              disabled={isSyncing}
            />
            <Button
              label={isSyncing ? 'Syncing...' : 'Create Task'}
              onClick={handleSubmit}
              icon={isSyncing ? 'pi pi-spin pi-spinner' : 'pi pi-check'}
              className="rounded-md! px-8!"
              disabled={isSyncing}
            />
          </div>
        </div>
      </Dialog>
    </div>
  );
}

import { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Dialog } from '@/components/ui/composed/Dialog';
import { Input } from '@/components/ui/primitives/Input';
import { Button } from '@/components/ui/primitives/Button';
import {
  Users,
  Crown,
  ArrowLeft,
  Plus,
  Trash2,
  UserCog,
  Search,
  Folder,
} from 'lucide-react';
import {
  useGetTeamByIdQuery,
  useGetTeamMembersQuery,
  useAddTeamMemberMutation,
  useRemoveTeamMemberMutation,
  useChangeTeamManagerMutation,
  type TeamMember,
} from '@/store/api/teamsApiSlice';
import { Table } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { useGetUsersQuery } from '@/store/api/userSlice';
import { useAuth } from '@/hooks/useAuth';
import type { StaffMember } from '@/types/models';

export function TeamDetailPage() {
  const { id } = useParams<{ id: string }>();
  const teamId = Number(id);
  const navigate = useNavigate();
  const { roles } = useAuth();

  const canManage = roles.some((r) =>
    ['Admin', 'SuperAdmin', 'HrAdmin', 'admin', 'superadmin', 'hradmin'].includes(r)
  );

  const { data: team, isLoading: teamLoading, isError: teamError } = useGetTeamByIdQuery(teamId, {
    skip: !teamId,
  });
  const { data: members = [], isLoading: membersLoading } = useGetTeamMembersQuery(teamId, {
    skip: !teamId,
  });
  const { data: allUsers = [] } = useGetUsersQuery();

  const [addTeamMember] = useAddTeamMemberMutation();
  const [removeTeamMember] = useRemoveTeamMemberMutation();
  const [changeTeamManager] = useChangeTeamManagerMutation();

  const [showAddMembers, setShowAddMembers] = useState(false);
  const [showChangeManager, setShowChangeManager] = useState(false);
  const [memberSearch, setMemberSearch] = useState('');
  const [selectedUserIds, setSelectedUserIds] = useState<number[]>([]);
  const [selectedManagerId, setSelectedManagerId] = useState<number | null>(null);
  const [addingMembers, setAddingMembers] = useState(false);
  const [changingManager, setChangingManager] = useState(false);

  const memberIds = new Set(members.map((m) => m.id));

  const availableUsers = allUsers.filter((u) => {
    const uid = Number(u.id);
    if (memberIds.has(uid)) return false;
    if (!memberSearch) return true;
    const q = memberSearch.toLowerCase();
    const name = (u.name || u.username || u.email || '').toLowerCase();
    return name.includes(q) || (u.email || '').toLowerCase().includes(q);
  });

  const toggleUserSelect = (uid: number) => {
    setSelectedUserIds((prev) =>
      prev.includes(uid) ? prev.filter((x) => x !== uid) : [...prev, uid]
    );
  };

  const handleAddMembers = async () => {
    if (!selectedUserIds.length) return;
    setAddingMembers(true);
    try {
      await Promise.all(selectedUserIds.map((userId) => addTeamMember({ teamId, userId }).unwrap()));
      setSelectedUserIds([]);
      setShowAddMembers(false);
    } catch {
      // silently ignore — RTK Query will mark error
    } finally {
      setAddingMembers(false);
    }
  };

  const handleRemoveMember = async (userId: number, name: string) => {
    if (!window.confirm(`Remove ${name} from this team?`)) return;
    await removeTeamMember({ teamId, userId }).unwrap().catch(() => null);
  };

  const handleChangeManager = async () => {
    if (!selectedManagerId) return;
    setChangingManager(true);
    try {
      await changeTeamManager({ teamId, managerId: selectedManagerId }).unwrap();
      setShowChangeManager(false);
      setSelectedManagerId(null);
    } catch {
      // silently ignore
    } finally {
      setChangingManager(false);
    }
  };

  const getInitials = (member: { name?: string; username?: string; email: string }) => {
    const src = member.name || member.username || member.email;
    return src.charAt(0).toUpperCase();
  };

  const getDisplayName = (member: { name?: string; username?: string; email: string }) =>
    member.name || member.username || member.email;

  const getUserDisplayName = (u: StaffMember) => u.name || u.username || u.email;

  const memberColumns: ColumnsType<TeamMember> = [
    {
      title: 'Member',
      key: 'member',
      render: (_, member) => {
        const displayName = getDisplayName(member);
        const initials = getInitials(member);
        const isManager = team && member.id === team.manager_id;
        return (
          <div className="flex items-center gap-3 py-1">
            {member.image_url || member.image ? (
              <img
                src={member.image_url || member.image}
                alt={displayName}
                className="w-9 h-9 rounded-full object-cover border border-border-subtle shrink-0"
              />
            ) : (
              <div
                className="w-9 h-9 rounded-full flex items-center justify-center font-black text-white text-xs shrink-0"
                style={{ backgroundColor: team?.color || '#3B82F6' }}
              >
                {initials}
              </div>
            )}
            <div className="flex flex-col">
              <div className="flex items-center gap-1.5">
                <span className="text-sm font-bold text-foreground">{displayName}</span>
                {isManager && (
                  <span title="Team Manager">
                    <Crown size={12} className="text-amber-500 shrink-0" />
                  </span>
                )}
              </div>
              {member.username && member.name && (
                <span className="text-xs text-muted">@{member.username}</span>
              )}
            </div>
          </div>
        );
      },
    },
    {
      title: 'Email',
      dataIndex: 'email',
      key: 'email',
      render: (email: string) => <span className="text-sm text-muted font-medium">{email}</span>,
    },
    {
      title: 'Designation',
      dataIndex: 'designation',
      key: 'designation',
      render: (desig: string) => <span className="text-sm text-muted font-medium">{desig || '—'}</span>,
    },
    {
      title: 'Role',
      dataIndex: 'role',
      key: 'role',
      render: (role: string) => (
        <span className="inline-block px-2.5 py-0.5 rounded-md bg-surface-subtle border border-border-subtle text-xs font-semibold text-foreground">
          {role || '—'}
        </span>
      ),
    },
    {
      title: 'Department',
      dataIndex: 'department',
      key: 'department',
      render: (dept: string) => <span className="text-sm text-muted font-medium">{dept || '—'}</span>,
    },
    {
      title: 'Joined',
      dataIndex: 'assigned_at',
      key: 'assigned_at',
      render: (date: string) => (
        <span className="text-xs text-muted font-medium">
          {date ? new Date(date).toLocaleDateString() : '—'}
        </span>
      ),
    },
    ...(canManage
      ? [
          {
            title: 'Action',
            key: 'action',
            align: 'right' as const,
            render: (_: any, member: TeamMember) => (
              <button
                type="button"
                onClick={() => handleRemoveMember(member.id, getDisplayName(member))}
                className="p-1.5 rounded-lg text-muted hover:text-red-500 hover:bg-red-50 transition-colors cursor-pointer"
                title="Remove member"
              >
                <Trash2 size={15} />
              </button>
            ),
          },
        ]
      : []),
  ];

  if (teamLoading || membersLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px] text-muted font-bold text-sm">
        <span className="animate-pulse">Loading team details...</span>
      </div>
    );
  }

  if (teamError || !team) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <span className="text-muted font-bold">Failed to load team details.</span>
        <Button label="Go Back" onClick={() => navigate('/teams')} variant="ghost" />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 pb-20 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Back button */}
      <div className="flex items-center gap-3">
        <button
          type="button"
          onClick={() => navigate('/teams')}
          className="flex items-center gap-2 text-sm font-bold text-muted hover:text-foreground transition-colors cursor-pointer"
        >
          <ArrowLeft size={16} />
          Back to Teams
        </button>
      </div>

      {/* Team Header Card */}
      <motion.div
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4 }}
        className="bg-white rounded-2xl border border-border-subtle shadow-soft relative overflow-hidden"
      >
        <div className="absolute top-0 left-0 right-0 h-2 rounded-t-2xl" style={{ backgroundColor: team.color }} />
        <div className="p-8 pt-10 flex flex-col md:flex-row md:items-start gap-6">
          <div
            className="w-16 h-16 rounded-xl flex items-center justify-center shrink-0"
            style={{ backgroundColor: `${team.color}20` }}
          >
            <Users size={30} style={{ color: team.color }} />
          </div>
          <div className="flex flex-col gap-2 flex-1">
            <div className="flex flex-col sm:flex-row sm:items-center gap-2">
              <h1 className="text-2xl font-black text-foreground tracking-tight">{team.name}</h1>
              <span
                className="text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md w-fit"
                style={{ backgroundColor: `${team.color}15`, color: team.color }}
              >
                {team.department}
              </span>
            </div>
            {team.description && (
              <p className="text-sm text-muted font-medium max-w-xl">{team.description}</p>
            )}
            <div className="flex flex-wrap items-center gap-5 mt-2 text-sm text-muted">
              {team.manager_name && (
                <div className="flex items-center gap-1.5">
                  <Crown size={14} className="text-amber-500" />
                  <span className="font-bold">{team.manager_name}</span>
                </div>
              )}
              <div className="flex items-center gap-1.5">
                <Users size={14} />
                <span className="font-bold">{team.member_count} members</span>
              </div>
              <div className="flex items-center gap-1.5">
                <Folder size={14} />
                <span className="font-bold">{team.project_count} projects</span>
              </div>
              {team.created_at && (
                <span className="text-xs">
                  Created {new Date(team.created_at).toLocaleDateString()}
                </span>
              )}
            </div>
          </div>
          {canManage && (
            <div className="flex items-center gap-3 shrink-0">
              <Button
                label="Change Manager"
                icon={<UserCog size={15} />}
                variant="ghost"
                onClick={() => {
                  setSelectedManagerId(null);
                  setShowChangeManager(true);
                }}
                className="rounded-xl! text-sm!"
              />
              <Button
                label="Add Members"
                icon={<Plus size={15} />}
                onClick={() => {
                  setMemberSearch('');
                  setSelectedUserIds([]);
                  setShowAddMembers(true);
                }}
                className="rounded-xl! text-sm!"
              />
            </div>
          )}
        </div>
      </motion.div>

      {/* Members Table */}
      <motion.div
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4, delay: 0.1 }}
        className="bg-white rounded-2xl border border-border-subtle shadow-soft overflow-hidden"
      >
        <div className="px-8 py-5 border-b border-border-subtle flex items-center justify-between">
          <span className="text-sm font-black text-foreground uppercase tracking-wider">
            Team Members
          </span>
          <span className="text-xs text-muted font-bold">{members.length} total</span>
        </div>
        {members.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-3 text-muted">
            <Users size={36} className="opacity-30" />
            <span className="text-sm font-bold">No members yet</span>
            {canManage && (
              <button
                type="button"
                onClick={() => setShowAddMembers(true)}
                className="text-xs font-bold text-primary hover:underline cursor-pointer"
              >
                Add the first member →
              </button>
            )}
          </div>
        ) : (
          <div className="p-2">
            <Table
              columns={memberColumns}
              dataSource={members}
              rowKey="id"
              pagination={{
                pageSize: 8,
                showSizeChanger: true,
                pageSizeOptions: ['5', '8', '15', '30'],
              }}
              className="premium-table"
              scroll={{ x: 'max-content' }}
            />
          </div>
        )}
      </motion.div>

      {/* Add Members Modal */}
      <Dialog
        visible={showAddMembers}
        onHide={() => setShowAddMembers(false)}
        header="Add Members"
        modal
        className="w-full max-w-lg mx-4"
        contentClassName="p-6"
        headerClassName="px-6 pt-6 pb-3 text-xl font-black tracking-tight border-none"
        pt={{
          root: { className: 'rounded-2xl overflow-hidden border-none shadow-2xl bg-white' },
          mask: { className: 'backdrop-blur-md bg-black/40' },
        }}
      >
        <div className="flex flex-col gap-4">
          <div className="relative">
            <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted pointer-events-none" />
            <Input
              placeholder="Search employees..."
              value={memberSearch}
              onChange={(e) => setMemberSearch(e.target.value)}
              className="pl-9!"
            />
          </div>
          <div className="max-h-72 overflow-y-auto flex flex-col gap-1 pr-1">
            {availableUsers.length === 0 ? (
              <div className="text-center text-sm text-muted py-8 font-medium">
                {memberSearch ? 'No matching employees found' : 'All employees are already in this team'}
              </div>
            ) : (
              availableUsers.map((u) => {
                const uid = Number(u.id);
                const isChecked = selectedUserIds.includes(uid);
                const displayName = getUserDisplayName(u);
                return (
                  <label
                    key={u.id}
                    className={`flex items-center gap-3 p-3 rounded-xl cursor-pointer transition-colors ${isChecked ? 'bg-primary/8 border border-primary/30' : 'hover:bg-surface-subtle border border-transparent'}`}
                  >
                    <input
                      type="checkbox"
                      checked={isChecked}
                      onChange={() => toggleUserSelect(uid)}
                      className="accent-primary w-4 h-4 cursor-pointer"
                    />
                    <div
                      className="w-8 h-8 rounded-full flex items-center justify-center font-bold text-white text-xs shrink-0"
                      style={{ backgroundColor: team.color }}
                    >
                      {displayName.charAt(0).toUpperCase()}
                    </div>
                    <div className="flex flex-col min-w-0">
                      <span className="text-sm font-bold text-foreground truncate">{displayName}</span>
                      <span className="text-xs text-muted truncate">{u.email}</span>
                    </div>
                    {u.designation && (
                      <span className="ml-auto text-[10px] font-bold text-muted bg-surface-subtle px-2 py-0.5 rounded-md whitespace-nowrap">
                        {u.designation}
                      </span>
                    )}
                  </label>
                );
              })
            )}
          </div>
          <div className="flex justify-between items-center pt-3 border-t border-border-subtle">
            <span className="text-xs text-muted font-bold">
              {selectedUserIds.length} selected
            </span>
            <div className="flex gap-3">
              <Button
                variant="ghost"
                label="Cancel"
                onClick={() => setShowAddMembers(false)}
                className="rounded-xl!"
              />
              <Button
                label={addingMembers ? 'Adding...' : 'Add Selected'}
                onClick={handleAddMembers}
                disabled={!selectedUserIds.length || addingMembers}
                className="rounded-xl!"
              />
            </div>
          </div>
        </div>
      </Dialog>

      {/* Change Manager Modal */}
      <Dialog
        visible={showChangeManager}
        onHide={() => setShowChangeManager(false)}
        header="Change Team Manager"
        modal
        className="w-full max-w-md mx-4"
        contentClassName="p-6"
        headerClassName="px-6 pt-6 pb-3 text-xl font-black tracking-tight border-none"
        pt={{
          root: { className: 'rounded-2xl overflow-hidden border-none shadow-2xl bg-white' },
          mask: { className: 'backdrop-blur-md bg-black/40' },
        }}
      >
        <div className="flex flex-col gap-4">
          <p className="text-sm text-muted font-medium">
            Select a team member to become the new manager.
          </p>
          <div className="max-h-64 overflow-y-auto flex flex-col gap-1 pr-1">
            {members.length === 0 ? (
              <div className="text-center text-sm text-muted py-8">No members in this team yet.</div>
            ) : (
              members.map((member) => {
                const displayName = getDisplayName(member);
                const isSelected = selectedManagerId === member.id;
                const isCurrentManager = member.id === team.manager_id;
                return (
                  <label
                    key={member.id}
                    className={`flex items-center gap-3 p-3 rounded-xl cursor-pointer transition-colors ${isSelected ? 'bg-primary/8 border border-primary/30' : 'hover:bg-surface-subtle border border-transparent'}`}
                  >
                    <input
                      type="radio"
                      name="manager"
                      checked={isSelected}
                      onChange={() => setSelectedManagerId(member.id)}
                      className="accent-primary w-4 h-4 cursor-pointer"
                    />
                    <div
                      className="w-8 h-8 rounded-full flex items-center justify-center font-bold text-white text-xs shrink-0"
                      style={{ backgroundColor: team.color }}
                    >
                      {getInitials(member)}
                    </div>
                    <div className="flex flex-col min-w-0">
                      <div className="flex items-center gap-1.5">
                        <span className="text-sm font-bold text-foreground">{displayName}</span>
                        {isCurrentManager && (
                          <span title="Current Manager">
                            <Crown size={12} className="text-amber-500" />
                          </span>
                        )}
                      </div>
                      <span className="text-xs text-muted">{member.designation || member.email}</span>
                    </div>
                  </label>
                );
              })
            )}
          </div>
          <div className="flex justify-end gap-3 pt-3 border-t border-border-subtle">
            <Button
              variant="ghost"
              label="Cancel"
              onClick={() => setShowChangeManager(false)}
              className="rounded-xl!"
            />
            <Button
              label={changingManager ? 'Saving...' : 'Confirm'}
              onClick={handleChangeManager}
              disabled={!selectedManagerId || changingManager}
              className="rounded-xl!"
            />
          </div>
        </div>
      </Dialog>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { PageHeader } from '@/components/ui/composed/PageHeader';
import {
  Users,
  Crown,
  Folder,
  Pencil,
  Trash2,
  Search,
  LayoutGrid,
  Table as TableIcon,
} from 'lucide-react';
import { Table } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { motion } from 'framer-motion';
import { Dialog } from '@/components/ui/composed/Dialog';
import { Input } from '@/components/ui/primitives/Input';
import { Select } from '@/components/ui/primitives/Select';
import { Button } from '@/components/ui/primitives/Button';
import {
  useGetTeamsQuery,
  useCreateTeamMutation,
  useUpdateTeamMutation,
  useDeleteTeamMutation,
} from '@/store/api/teamsApiSlice';
import type { Team, CreateTeamPayload } from '@/store/api/teamsApiSlice';
import { useGetUsersQuery } from '@/store/api/userSlice';
import { useGetOrganizationHierarchyQuery } from '@/store/api/organizationApiSlice';
import { useGetDepartmentsQuery } from '@/store/api/authApiSlice';
import { useAuth } from '@/hooks/useAuth';

const COLORS = [
  '#3B82F6',
  '#8B5CF6',
  '#10B981',
  '#F59E0B',
  '#EC4899',
  '#06B6D4',
  '#6366F1',
  '#14B8A6',
];

interface TeamFormState {
  name: string;
  department: string;
  description: string;
  manager_id: string;
  color: string;
}

const emptyForm: TeamFormState = {
  name: '',
  department: '',
  description: '',
  manager_id: '',
  color: COLORS[0],
};

export function TeamsPage() {
  const navigate = useNavigate();
  const { roles } = useAuth();

  const canManage = roles.some((r) =>
    ['Admin', 'SuperAdmin', 'HrAdmin', 'admin', 'superadmin', 'hradmin'].includes(r)
  );

  const { data: teams = [], isLoading, isError, refetch } = useGetTeamsQuery();
  const { data: users = [] } = useGetUsersQuery();
  const { data: hierarchyData } = useGetOrganizationHierarchyQuery();
  const { data: deptResponse } = useGetDepartmentsQuery();

  const [createTeam, { isLoading: creating }] = useCreateTeamMutation();
  const [updateTeam, { isLoading: updating }] = useUpdateTeamMutation();
  const [deleteTeam] = useDeleteTeamMutation();

  const [searchQuery, setSearchQuery] = useState('');
  const [selectedDeptFilter, setSelectedDeptFilter] = useState('ALL');
  const [viewMode, setViewMode] = useState<'table' | 'cards'>('table');

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingTeam, setEditingTeam] = useState<Team | null>(null);
  const [form, setForm] = useState<TeamFormState>(emptyForm);

  // Dynamic Departments from Database (departments table, hierarchy, users, teams)
  const departmentOptions = useMemo(() => {
    const list: string[] = [];

    // 1. From departments table via hierarchy
    if (hierarchyData?.data?.departments) {
      hierarchyData.data.departments.forEach((d) => {
        if (d.department_name && !list.includes(d.department_name)) {
          list.push(d.department_name);
        }
      });
    }

    // 2. From metadata departments
    const rawDepts = (deptResponse as any)?.data || deptResponse || [];
    if (Array.isArray(rawDepts)) {
      rawDepts.forEach((d: any) => {
        const name = d.department_name || d.name;
        if (name && !list.includes(name)) {
          list.push(name);
        }
      });
    }

    // 3. From users' departments
    users.forEach((u) => {
      if (u.department && !list.includes(u.department)) {
        list.push(u.department);
      }
    });

    // 4. From existing teams' departments
    teams.forEach((t) => {
      if (t.department && !list.includes(t.department)) {
        list.push(t.department);
      }
    });

    return list.sort().map((d) => ({ label: d, value: d }));
  }, [hierarchyData, deptResponse, users, teams]);

  // Dynamic User Options with real Roles and Designations from DB
  const userOptions = useMemo(() => {
    return users.map((u) => {
      const roleStr = [u.role, (u as any).designation].filter(Boolean).join(' • ');
      return {
        label: `${u.name || u.username || u.email}${roleStr ? ` (${roleStr})` : ''}`,
        value: String(u.id),
      };
    });
  }, [users]);

  const filteredTeams = teams.filter((t) => {
    if (selectedDeptFilter !== 'ALL' && t.department !== selectedDeptFilter) {
      return false;
    }
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return (
      t.name.toLowerCase().includes(q) ||
      t.department.toLowerCase().includes(q) ||
      (t.manager_name && t.manager_name.toLowerCase().includes(q))
    );
  });

  const totalMembers = teams.reduce((s, t) => s + t.member_count, 0);
  const totalProjects = teams.reduce((s, t) => s + t.project_count, 0);
  const uniqueDepts = new Set(teams.map((t) => t.department)).size;

  const openCreate = () => {
    setForm({ ...emptyForm, color: COLORS[teams.length % COLORS.length] });
    setShowCreateModal(true);
  };

  const openEdit = (team: Team) => {
    setEditingTeam(team);
    setForm({
      name: team.name,
      department: team.department,
      description: team.description || '',
      manager_id: team.manager_id ? String(team.manager_id) : '',
      color: team.color || COLORS[0],
    });
    setShowEditModal(true);
  };

  const handleCreate = async () => {
    if (!form.name || !form.department) return;
    const payload: CreateTeamPayload = {
      name: form.name,
      department: form.department,
      description: form.description || undefined,
      manager_id: form.manager_id ? Number(form.manager_id) : undefined,
      color: form.color,
      status: 'Active',
    };
    await createTeam(payload).unwrap().catch(() => null);
    setShowCreateModal(false);
    setForm(emptyForm);
  };

  const handleEdit = async () => {
    if (!editingTeam || !form.name || !form.department) return;
    await updateTeam({
      id: editingTeam.id,
      name: form.name,
      department: form.department,
      description: form.description || undefined,
      manager_id: form.manager_id ? Number(form.manager_id) : undefined,
      color: form.color,
    }).unwrap().catch(() => null);
    setShowEditModal(false);
    setEditingTeam(null);
  };

  const handleDelete = async (team: Team) => {
    if (!window.confirm(`Delete team "${team.name}"? This cannot be undone.`)) return;
    await deleteTeam(team.id).unwrap().catch(() => null);
  };

  const teamColumns: ColumnsType<Team> = [
    {
      title: 'Team',
      key: 'team',
      render: (_, team) => (
        <div className="flex items-center gap-3 py-1">
          <div
            className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0 font-black text-white text-xs shadow-xs"
            style={{ backgroundColor: team.color }}
          >
            <Users size={18} />
          </div>
          <div className="flex flex-col">
            <span
              onClick={() => navigate(`/teams/${team.id}`)}
              className="text-sm font-bold text-foreground hover:text-primary cursor-pointer transition-colors"
            >
              {team.name}
            </span>
            {team.description && (
              <span className="text-xs text-muted line-clamp-1 max-w-[280px]">
                {team.description}
              </span>
            )}
          </div>
        </div>
      ),
    },
    {
      title: 'Department',
      dataIndex: 'department',
      key: 'department',
      render: (dept: string) => (
        <span className="inline-block px-2.5 py-0.5 rounded-lg bg-surface-subtle border border-border-subtle text-xs font-bold text-foreground">
          {dept}
        </span>
      ),
    },
    {
      title: 'Manager',
      key: 'manager',
      render: (_, team) => (
        <div className="flex items-center gap-2">
          <Crown size={14} className="text-amber-500 shrink-0" />
          <div className="flex flex-col">
            <span className="text-xs font-bold text-foreground">
              {team.manager_name || 'No manager'}
            </span>
            {(team.manager_role || team.manager_designation) && (
              <span className="text-[10px] text-muted">
                {[team.manager_role, team.manager_designation].filter(Boolean).join(' • ')}
              </span>
            )}
          </div>
        </div>
      ),
    },
    {
      title: 'Members',
      dataIndex: 'member_count',
      key: 'member_count',
      align: 'center' as const,
      render: (count: number) => (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-surface-subtle text-xs font-bold text-foreground">
          <Users size={12} className="text-muted" />
          {count}
        </span>
      ),
    },
    {
      title: 'Projects',
      dataIndex: 'project_count',
      key: 'project_count',
      align: 'center' as const,
      render: (count: number) => (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-surface-subtle text-xs font-bold text-foreground">
          <Folder size={12} className="text-muted" />
          {count}
        </span>
      ),
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      render: (status: string) => (
        <span
          className={`inline-block px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider ${
            status === 'Active'
              ? 'bg-emerald-50 text-emerald-700 border border-emerald-200'
              : 'bg-muted/10 text-muted border border-border-subtle'
          }`}
        >
          {status || 'Active'}
        </span>
      ),
    },
    {
      title: 'Action',
      key: 'action',
      align: 'right' as const,
      render: (_, team) => (
        <div className="flex items-center justify-end gap-2">
          <button
            type="button"
            onClick={() => navigate(`/teams/${team.id}`)}
            className="text-xs font-bold text-primary hover:underline cursor-pointer px-2 py-1"
          >
            View →
          </button>
          {canManage && (
            <>
              <button
                type="button"
                onClick={() => openEdit(team)}
                className="p-1.5 rounded-lg text-muted hover:text-primary hover:bg-primary/10 transition-colors cursor-pointer"
                title="Edit team"
              >
                <Pencil size={14} />
              </button>
              <button
                type="button"
                onClick={() => handleDelete(team)}
                className="p-1.5 rounded-lg text-muted hover:text-red-500 hover:bg-red-50 transition-colors cursor-pointer"
                title="Delete team"
              >
                <Trash2 size={14} />
              </button>
            </>
          )}
        </div>
      ),
    },
  ];

  const TeamFormFields = () => (
    <div className="flex flex-col gap-5">
      <div className="flex flex-col gap-2">
        <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
          Team Name *
        </label>
        <Input
          placeholder="e.g. Engineering"
          value={form.name}
          onChange={(e) => setForm({ ...form, name: e.target.value })}
        />
      </div>
      <div className="flex flex-col gap-2">
        <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
          Department *
        </label>
        <Select
          options={departmentOptions}
          value={form.department}
          onChange={(e) => setForm({ ...form, department: e.value as string })}
          placeholder="Select department"
        />
      </div>
      <div className="flex flex-col gap-2">
        <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
          Description
        </label>
        <textarea
          placeholder="Optional team description..."
          value={form.description}
          onChange={(e) => setForm({ ...form, description: e.target.value })}
          rows={3}
          className="w-full px-3 py-2 rounded-xl border border-border-subtle bg-white text-sm text-foreground placeholder:text-muted resize-none focus:outline-none focus:ring-2 focus:ring-primary/30 font-medium"
        />
      </div>
      <div className="flex flex-col gap-2">
        <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
          Manager
        </label>
        <Select
          options={userOptions}
          value={form.manager_id}
          onChange={(e) => setForm({ ...form, manager_id: e.value as string })}
          placeholder="Select manager (optional)"
        />
      </div>
      <div className="flex flex-col gap-2">
        <label className="text-[10px] font-extrabold text-muted uppercase tracking-[0.2em]">
          Team Color
        </label>
        <div className="flex items-center gap-2 flex-wrap">
          {COLORS.map((c) => (
            <button
              key={c}
              type="button"
              onClick={() => setForm({ ...form, color: c })}
              className={`w-8 h-8 rounded-full border-2 transition-all cursor-pointer ${form.color === c ? 'border-foreground scale-110 shadow-md' : 'border-transparent hover:scale-105'}`}
              style={{ backgroundColor: c }}
              title={c}
            />
          ))}
        </div>
      </div>
    </div>
  );

  // Loading skeletons
  if (isLoading) {
    return (
      <div className="flex flex-col gap-10 pb-20">
        <div className="h-16 bg-surface-subtle/60 rounded-2xl animate-pulse" />
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
          {[...Array(4)].map((_, i) => (
            <div key={i} className="h-24 bg-surface-subtle/60 rounded-xl animate-pulse" />
          ))}
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="h-56 bg-surface-subtle/60 rounded-2xl animate-pulse" />
          ))}
        </div>
      </div>
    );
  }

  // Error state
  if (isError) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <span className="text-muted font-bold">Failed to load teams.</span>
        <Button label="Retry" onClick={() => refetch()} variant="ghost" />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-10 pb-20 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <PageHeader
        title="Teams"
        description="Manage teams across your organization."
        breadcrumbs={[{ label: 'Home', url: '/' }, { label: 'Teams' }]}
        primaryAction={canManage ? {
          label: 'Create Team',
          onClick: openCreate,
          icon: 'pi pi-plus',
        } : undefined}
      />

      {/* Stats */}
