/**
 * Form Draft and Autosave Manager
 * Provides debounced autosave, draft restoration, and change detection.
 *
 * Security Design:
 * - Sensitive credentials (bank account numbers, PAN, Aadhaar, Passport numbers)
 *   are stored ONLY in sessionStorage (tab memory, cleared on browser exit)
 *   and NEVER persisted to insecure localStorage.
 * - Non-sensitive sections (personal details, address, employment, education)
 *   are stored with timestamped drafts for disaster recovery.
 */

const DRAFT_PREFIX = 'aether_form_draft_';
const SENSITIVE_SECTIONS = new Set(['bank', 'identity']);

export interface StoredDraft<T = any> {
  data: T;
  timestamp: number;
  userId: string | number;
  section: string;
}

/**
 * Strips sensitive identification and bank numbers for disk storage
 */
function sanitizeForPersistentStorage(section: string, data: any): any {
  if (!data || typeof data !== 'object') return data;
  if (!SENSITIVE_SECTIONS.has(section)) return data;

  const clone = { ...data };
  if (section === 'bank') {
    delete clone.accountNumber;
    delete clone.confirmAccountNumber;
  } else if (section === 'identity') {
    delete clone.panNumber;
    delete clone.aadhaarNumber;
    delete clone.passportNumber;
  }
  return clone;
}

/**
 * Saves a form draft with timestamp
 */
export function saveFormDraft(
  userId: string | number,
  section: string,
  data: any
): void {
  if (!userId || !section || !data) return;

  const key = `${DRAFT_PREFIX}${userId}_${section}`;
  const draft: StoredDraft = {
    data,
    timestamp: Date.now(),
    userId,
    section,
  };

  try {
    // 1. SessionStorage always stores the current session draft (including in-memory sensitive fields for refresh recovery)
    sessionStorage.setItem(key, JSON.stringify(draft));

    // 2. LocalStorage stores persistent draft ONLY with sensitive fields sanitized
    const sanitizedData = sanitizeForPersistentStorage(section, data);
    const sanitizedDraft: StoredDraft = {
      ...draft,
      data: sanitizedData,
    };
    localStorage.setItem(key, JSON.stringify(sanitizedDraft));
  } catch (err) {
    console.warn('[FormDraftManager] Could not save draft:', err);
  }
}

/**
 * Retrieves the latest valid draft for a given user and section
 */
export function getFormDraft<T = any>(
  userId: string | number,
  section: string
): StoredDraft<T> | null {
  if (!userId || !section) return null;
  const key = `${DRAFT_PREFIX}${userId}_${section}`;

  try {
    // Check sessionStorage first (contains freshest in-session edits)
    const sessionRaw = sessionStorage.getItem(key);
    if (sessionRaw) {
      const parsed = JSON.parse(sessionRaw);
      if (parsed && parsed.data) return parsed;
    }

    // Fallback to localStorage
    const localRaw = localStorage.getItem(key);
    if (localRaw) {
      const parsed = JSON.parse(localRaw);
      if (parsed && parsed.data) return parsed;
    }
  } catch (err) {
    console.warn('[FormDraftManager] Could not load draft:', err);
  }
  return null;
}

/**
 * Clears draft upon successful save or submission
 */
export function clearFormDraft(userId: string | number, section: string): void {
  if (!userId || !section) return;
  const key = `${DRAFT_PREFIX}${userId}_${section}`;
  try {
    sessionStorage.removeItem(key);
    localStorage.removeItem(key);
  } catch {}
}

/**
 * Clears all drafts for a user
 */
export function clearAllUserDrafts(userId: string | number): void {
  if (!userId) return;
  const prefix = `${DRAFT_PREFIX}${userId}_`;

  try {
    Object.keys(sessionStorage).forEach((k) => {
      if (k.startsWith(prefix)) sessionStorage.removeItem(k);
    });
    Object.keys(localStorage).forEach((k) => {
      if (k.startsWith(prefix)) localStorage.removeItem(k);
    });
  } catch {}
}

/**
 * Fast change detection between saved state and current form state
 */
export function isDataModified(saved: any, current: any): boolean {
  if (saved === current) return false;
  if (!saved && !current) return false;
  if (!saved || !current) return true;

  if (typeof saved !== 'object' || typeof current !== 'object') {
    return saved !== current;
  }

  // Fast check for arrays
  if (Array.isArray(saved) || Array.isArray(current)) {
    if (!Array.isArray(saved) || !Array.isArray(current)) return true;
    if (saved.length !== current.length) return true;
  }

  try {
    return JSON.stringify(saved) !== JSON.stringify(current);
  } catch {
    return true;
  }
}

/**
 * Ultra-High Accuracy Geolocation Engine
 *
 * Browsers and mobile devices typically emit a coarse WiFi/cellular estimate first (50m-500m)
 * before satellite hardware achieves full lock (3m-15m).
 *
 * This utility uses `watchPosition` with `maximumAge: 0` to continuously sample
 * incoming GPS fixes and returns the highest precision (lowest accuracy radius) fix.
 */

export interface AccuratePositionResult {
  latitude: number;
  longitude: number;
  accuracy: number;
  timestamp: number;
  rawPosition: GeolocationPosition;
}

export function getUltraAccuratePosition(options?: {
  timeoutMs?: number;
  desiredAccuracyMeters?: number;
}): Promise<AccuratePositionResult> {
  const timeoutMs = options?.timeoutMs ?? 6000;
  const desiredAccuracy = options?.desiredAccuracyMeters ?? 15; // 15 meters or better target

  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) {
      return reject(new Error('Geolocation is not supported by your browser.'));
    }

    let bestSample: GeolocationPosition | null = null;
    let watchId: number | null = null;
    let isSettled = false;

    const cleanup = () => {
      if (watchId !== null) {
        navigator.geolocation.clearWatch(watchId);
        watchId = null;
      }
    };

    const settleSuccess = (pos: GeolocationPosition) => {
      if (isSettled) return;
      isSettled = true;
      cleanup();
      resolve({
        latitude: pos.coords.latitude,
        longitude: pos.coords.longitude,
        accuracy: pos.coords.accuracy,
        timestamp: pos.timestamp,
        rawPosition: pos,
      });
    };

    const settleFail = (err: GeolocationPositionError) => {
      if (isSettled) return;
      if (bestSample) {
        // If we captured any reading before failure/timeout, use best sample
        settleSuccess(bestSample);
      } else {
        isSettled = true;
        cleanup();
        reject(err);
      }
    };

    // Timeout fallback: after timeoutMs, return the best sample collected
    const timer = setTimeout(() => {
      if (!isSettled) {
        if (bestSample) {
          settleSuccess(bestSample);
        } else {
          isSettled = true;
          cleanup();
          reject(new Error('GPS acquisition timed out. Please check that Location Services are enabled.'));
        }
      }
    }, timeoutMs);

    try {
      watchId = navigator.geolocation.watchPosition(
        (pos) => {
          const currentAcc = pos.coords.accuracy;

          // Track the sample with the lowest accuracy error radius
          if (!bestSample || currentAcc < bestSample.coords.accuracy) {
            bestSample = pos;
          }

          // If we reached our target accuracy threshold (e.g. <= 15m), resolve immediately
          if (currentAcc <= desiredAccuracy) {
            clearTimeout(timer);
            settleSuccess(pos);
          }
        },
        (err) => {
          // If we already have a sample, ignore non-fatal watch error and use best sample
          if (bestSample) {
            clearTimeout(timer);
            settleSuccess(bestSample);
          } else {
            clearTimeout(timer);
            settleFail(err);
          }
        },
        {
          enableHighAccuracy: true,
          timeout: timeoutMs,
          maximumAge: 0, // Never use cached position!
        }
      );
    } catch (e: any) {
      clearTimeout(timer);
      cleanup();
      // Fallback to single getCurrentPosition if watchPosition fails
      navigator.geolocation.getCurrentPosition(
        (pos) => settleSuccess(pos),
        (err) => settleFail(err),
        { enableHighAccuracy: true, timeout: timeoutMs, maximumAge: 0 }
      );
    }
  });
}

import type { User } from '@/types/auth';

export const PAGE_PERMISSIONS_STORAGE_KEY = 'erp_page_permissions';
export const ERP_CONFIG_CHANGED_EVENT = 'erp_config_changed';
export const ERP_BROADCAST_CHANNEL = 'erp_permissions_channel';

export interface RoleDefinition {
  id: string;
  label: string;
  isSuperAdmin?: boolean;
}

export const AVAILABLE_ROLES: RoleDefinition[] = [
  { id: 'SuperAdmin', label: 'Super Admin', isSuperAdmin: true },
  { id: 'Admin', label: 'Admin' },
  { id: 'HrAdmin', label: 'HR' },
  { id: 'FinanceAdmin', label: 'Finance' },
  { id: 'Manager', label: 'Manager' },
  { id: 'Employee', label: 'Employee' },
];

/**
 * Check if the given user is a Super Admin.
 * Handles role names, designations, and legacy casing.
 */
export const isSuperAdmin = (user: User | null | undefined): boolean => {
  if (!user) return false;
  const role = (user.role || '').toLowerCase().replace(/[\s_-]/g, '');
  if (role === 'superadmin') return true;
  const designation = (user.designation || '').toLowerCase();
  if (designation.includes('super admin') || designation.includes('superadmin')) return true;
  return false;
};

/**
 * Normalizes user role or role identifier to standard comparison keys.
 */
export const normalizeRole = (roleStr: string | undefined): string => {
  if (!roleStr) return '';
  const clean = roleStr.toLowerCase().replace(/[\s_-]/g, '');
  if (clean === 'superadmin') return 'SuperAdmin';
  if (clean === 'admin') return 'Admin';
  if (clean === 'hr' || clean === 'hradmin' || clean === 'humanresources') return 'HrAdmin';
  if (clean === 'finance' || clean === 'financeadmin') return 'FinanceAdmin';
  if (clean === 'manager') return 'Manager';
  if (
    clean === 'employee' ||
    clean === 'staff' ||
    clean === 'user' ||
    clean === 'regular' ||
    clean === 'normal' ||
    clean === 'viewer'
  ) {
    return 'Employee';
  }
  return roleStr;
};

/**
 * Extracts all assigned normalized roles from a user object.
 */
export const getUserRoles = (user: User | null | undefined): string[] => {
  if (!user) return [];
  const roles: string[] = [];
  if (user.role) roles.push(String(user.role));
  if (Array.isArray((user as any).roles)) {
    (user as any).roles.forEach((r: any) => {
      if (typeof r === 'string') roles.push(r);
      else if (r && typeof r.name === 'string') roles.push(r.name);
    });
  }
  if (roles.length === 0) {
    roles.push('Employee');
  }
  return [...new Set(roles.map(normalizeRole))];
};

/**
 * Retrieve the saved page-level permissions map from localStorage.
 * Format: { [pagePath: string]: string[] (allowed role ids) }
 */
export const getStoredPagePermissions = (): Record<string, string[]> => {
  try {
    const raw = localStorage.getItem(PAGE_PERMISSIONS_STORAGE_KEY);
    if (raw) {
      return JSON.parse(raw);
    }
  } catch (err) {
    console.error('Failed to parse erp_page_permissions:', err);
  }
  return {};
};

/**
 * Save updated page permissions to localStorage, server sync endpoint, and broadcast across tabs.
 */
export const saveStoredPagePermissions = (permissions: Record<string, string[]>) => {
  try {
    localStorage.setItem(PAGE_PERMISSIONS_STORAGE_KEY, JSON.stringify(permissions));
    window.dispatchEvent(new Event(ERP_CONFIG_CHANGED_EVENT));

    // Broadcast across other browser tabs/windows
    if (typeof BroadcastChannel !== 'undefined') {
      try {
        const bc = new BroadcastChannel(ERP_BROADCAST_CHANNEL);
        bc.postMessage({ type: ERP_CONFIG_CHANGED_EVENT, timestamp: Date.now() });
        bc.close();
      } catch {
        // BroadcastChannel fallback ignored
      }
    }

    // Sync to dev server endpoint so Incognito and other browsers get the permissions
    if (typeof fetch !== 'undefined') {
      fetch('/__erp_permissions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(permissions),
      }).catch(() => {
        // server endpoint optional in pure static builds
      });
    }
  } catch (err) {
    console.error('Failed to save erp_page_permissions:', err);
  }
};

/**
 * Fetch permissions from the server endpoint (allows Incognito to receive permissions from Normal window)
 */
export const syncRemotePermissions = async () => {
  if (typeof fetch === 'undefined') return;
  try {
    const res = await fetch('/__erp_permissions');
    if (res.ok) {
      const serverPerms = await res.json();
      if (serverPerms && Object.keys(serverPerms).length > 0) {
        const local = getStoredPagePermissions();
        // If different from local, update localStorage and notify listeners
        if (JSON.stringify(serverPerms) !== JSON.stringify(local)) {
          localStorage.setItem(PAGE_PERMISSIONS_STORAGE_KEY, JSON.stringify(serverPerms));
          window.dispatchEvent(new Event(ERP_CONFIG_CHANGED_EVENT));
        }
      }
    }
  } catch {
    // ignore
  }
};

// Auto-sync permissions on startup and when user switches between windows/tabs (e.g. Incognito to Normal)
if (typeof window !== 'undefined') {
  syncRemotePermissions();
  window.addEventListener('focus', () => {
    syncRemotePermissions();
  });
  window.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') {
      syncRemotePermissions();
    }
  });
}

/**
 * Get active allowed roles for a given page path.
 * Falls back to default roles from nav items or standard default.
 */
export const getEffectivePageRoles = (path: string, defaultRoles?: string[]): string[] => {
  const stored = getStoredPagePermissions();
  if (stored[path] && Array.isArray(stored[path])) {
    const roles = stored[path];
    if (!roles.includes('SuperAdmin')) {
      return ['SuperAdmin', ...roles];
    }
    return roles;
  }

  // Fallback to defaultRoles or standard all-role default
  const defaults =
    defaultRoles && defaultRoles.length > 0
      ? defaultRoles
      : ['SuperAdmin', 'Admin', 'HrAdmin', 'FinanceAdmin', 'Employee', 'Manager'];

  if (!defaults.includes('SuperAdmin')) {
    return ['SuperAdmin', ...defaults];
  }
  return defaults;
};

/**
 * Checks whether a specific role (e.g. Employee) is allowed to access a given page path.
 */
export const isRoleAllowedForPage = (
  path: string,
  roleId: string,
  defaultRoles?: string[]
): boolean => {
  if (roleId === 'SuperAdmin') return true;
  const roles = getEffectivePageRoles(path, defaultRoles);
  const targetNorm = normalizeRole(roleId);
  return roles.some((r) => normalizeRole(r) === targetNorm);
};

/**
 * Checks whether the current user has access to a given page path.
 * Super Admin always has full access.
 */
export const canAccessPage = (
  pagePath: string,
  user: User | null | undefined,
  defaultRoles?: string[]
): boolean => {
  if (!user) return false;
  if (isSuperAdmin(user)) return true;

  const allowedRoles = getEffectivePageRoles(pagePath, defaultRoles).map(normalizeRole);
  const userRoles = getUserRoles(user);

  return userRoles.some((uRole) => allowedRoles.includes(uRole));
};

/**
 * Utility functions for payroll and salary slip generation.
 */

/**
 * Formats an employee code to preserve and clean its actual identifier (e.g. 'EMP1', 'X001').
 * - Preserves letter prefixes like 'EMP' or 'X' (e.g., 'EMP1', 'X001', 'EMP001').
 * - Strips old legacy wrapper prefixes like 'SLIP-'.
 * - Removes internal hyphens/spaces/underscores (e.g., 'EMP-1' -> 'EMP1', 'EMP-001' -> 'EMP001', 'X-001' -> 'X001').
 * - If purely numeric digits (e.g. '1', '2', '001'), prefixes with 'EMP' (e.g., 1 -> 'EMP1', '001' -> 'EMP001').
 */
export const formatEmployeeCode = (employeeCode?: string | number | null): string => {
  if (employeeCode === undefined || employeeCode === null) return '';
  const str = String(employeeCode).trim();
  if (!str) return '';

  // 1. Remove old legacy prefixes like 'SLIP-'
  let cleaned = str.replace(/^SLIP[-_]?/i, '').trim();

  // 2. Remove internal hyphens, underscores, or spaces (e.g. 'EMP-1' -> 'EMP1', 'X-001' -> 'X001')
  cleaned = cleaned.replace(/[-_\s]+/g, '');

  // Use employee code directly (preserve as uppercase e.g. 'X007', 'E007')
  return cleaned.toUpperCase();
};

/**
 * Parses a payslip number formatted as <EMPLOYEE_CODE><MM><YY><SLIP_NO>
 * e.g., 'EMP10926001' -> { employeeCode: 'EMP1', month: '09', year: '26', slipNo: '001', sequence: 1 }
 * e.g., 'X0010725001' -> { employeeCode: 'X001', month: '07', year: '25', slipNo: '001', sequence: 1 }
 * Also supports optional separator formats (e.g. 'EMP1-0926001', 'E002-0926001') and legacy 'SLIP-...'
 */
export const PAYROLL_SLIP_NO_STORAGE_KEY = 'aether_erp_payroll_slip_no_overrides';

/**
 * Retrieves all stored slip number overrides from localStorage.
 */
export const getPayrollSlipNoOverrides = (): Record<string, string> => {
  try {
    const raw = localStorage.getItem(PAYROLL_SLIP_NO_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
};

/**
 * Saves a slip number override for a given key in localStorage.
 */
export const setPayrollSlipNoOverride = (key: string | number, slipNo: string) => {
  if (!key || !slipNo) return;
  try {
    const current = getPayrollSlipNoOverrides();
    current[String(key)] = String(slipNo).trim();
    localStorage.setItem(PAYROLL_SLIP_NO_STORAGE_KEY, JSON.stringify(current));
  } catch (e) {
    console.warn('Failed to save payroll slip number override:', e);
  }
};

/**
 * Helper to save slip number under multiple lookup keys (id, empCode_monthYear, userId_monthYear).
 */
export const saveSlipNumberOverrides = (
  slipNo: string,
  options: {
    id?: string | number;
    empCode?: string | number | null;
    userId?: string | number | null;
    monthYear?: string | null;
    month?: number | string | null;
    year?: number | string | null;
  }
) => {
  if (!slipNo) return;
  const cleanSlipNo = String(slipNo).trim();
  if (options.id) {
    setPayrollSlipNoOverride(String(options.id), cleanSlipNo);
  }
  const cleanCode = options.empCode ? formatEmployeeCode(options.empCode) : '';
  const my = options.monthYear ? String(options.monthYear).trim() : '';
  if (cleanCode && my) {
    setPayrollSlipNoOverride(`${cleanCode}_${my}`, cleanSlipNo);
    setPayrollSlipNoOverride(`${cleanCode}_${my.toUpperCase()}`, cleanSlipNo);
  }
  if (options.userId && my) {
    setPayrollSlipNoOverride(`${options.userId}_${my}`, cleanSlipNo);
    setPayrollSlipNoOverride(`${options.userId}_${my.toUpperCase()}`, cleanSlipNo);
  }
  if (options.month && options.year) {
    const mStr = String(options.month).padStart(2, '0');
    const yStr = String(options.year).slice(-2);
    if (cleanCode) {
      setPayrollSlipNoOverride(`${cleanCode}_${mStr}_${yStr}`, cleanSlipNo);
    }
  }
};

/**
 * Extracts a slip number tagged in text (e.g. remarks or hr_note: '[SLIP_NO: EMP11026007]').
 */
export const extractSlipNoFromText = (text?: string | null): string | null => {
  if (!text || typeof text !== 'string') return null;
  const matches = [...text.matchAll(/\[SLIP_NO:\s*([^\]|]+)\]/gi)];
  if (matches.length > 0) {
    return matches[matches.length - 1][1].trim();
  }
  return null;
};

/**
 * Extracts a sequence number tagged in text (e.g. remarks or hr_note: '[SLIP_SEQ: 7]').
 */
export const extractSlipSeqFromText = (text?: string | null): number | null => {
  if (!text || typeof text !== 'string') return null;
  const matches = [...text.matchAll(/\[SLIP_SEQ:\s*(\d+)\]/gi)];
  if (matches.length > 0) {
    return parseInt(matches[matches.length - 1][1], 10);
  }
  return null;
};

/**
 * Parses a payslip number formatted as <EMPLOYEE_CODE><MM><YY><SLIP_NO>
 * e.g., 'EMP10926001' -> { employeeCode: 'EMP1', month: '09', year: '26', slipNo: '001', sequence: 1 }
 * e.g., 'X0010725007' -> { employeeCode: 'X001', month: '07', year: '25', slipNo: '007', sequence: 7 }
 * Also supports optional separator formats (e.g. 'EMP1-0926001', 'E002-0926001'), standalone digits ('007' or '7'), and legacy 'SLIP-...'
 */
export const parseSlipNumber = (
  slipNumber?: string | null
): { employeeCode: string; month: string; year: string; slipNo: string; sequence: number } | null => {
  if (!slipNumber) return null;
  const trimmed = String(slipNumber).trim();
  if (!trimmed) return null;

  // 0. Check if embedded in tags e.g. [SLIP_NO: EMP11026007]
  const tagSlip = extractSlipNoFromText(trimmed);
  if (tagSlip && tagSlip !== trimmed) {
    return parseSlipNumber(tagSlip);
  }

  // 1. Hyphen or underscore separated format: e.g. 'EMP1-0926001', 'X001-0926001', 'E002-0926001'
  const separatorMatch = trimmed.match(/^([A-Za-z0-9_-]+)[-_](\d{2})(\d{2})(\d{3,})$/);
  if (separatorMatch) {
    return {
      employeeCode: formatEmployeeCode(separatorMatch[1]),
      month: separatorMatch[2],
      year: separatorMatch[3],
      slipNo: separatorMatch[4],
      sequence: parseInt(separatorMatch[4], 10),
    };
  }

  // 2. Direct concatenated format without separator:
  // e.g. 'EMP10926001', 'X0010926001', 'EMP11026007'
  // Suffix is MM (2 digits) + YY (2 digits) + SSS (3 digits) = 7 digits at the end
  const directMatch = trimmed.match(/^([A-Za-z0-9]+?)(\d{2})(\d{2})(\d{3})$/);
  if (directMatch) {
    return {
      employeeCode: formatEmployeeCode(directMatch[1]),
      month: directMatch[2],
      year: directMatch[3],
      slipNo: directMatch[4],
      sequence: parseInt(directMatch[4], 10),
    };
  }

  // 3. Fallback for legacy format: SLIP-<EMP_CODE>-<YYYY><MM>
  const legacyMatch = trimmed.match(/^SLIP[-_]?([A-Za-z0-9_-]+)[-_](\d{4})(\d{2})$/i);
  if (legacyMatch) {
    return {
      employeeCode: formatEmployeeCode(legacyMatch[1]),
      month: legacyMatch[3],
      year: legacyMatch[2].slice(-2),
      slipNo: '001',
      sequence: 1,
    };
  }

  // 4. Standalone sequence digits e.g. '007', '7', '42'
  if (/^\d{1,4}$/.test(trimmed)) {
    const seq = parseInt(trimmed, 10);
    return {
      employeeCode: '',
      month: '',
      year: '',
      slipNo: String(seq).padStart(3, '0'),
      sequence: seq,
    };
  }

  return null;
};

/**
 * Generates payslip number according to the format:
 * <EMPLOYEE_CODE><MM><YY><SLIP_NO>
 * e.g., EMP10926001 (EMP1, September 2026, slip no 001)
 * e.g., X0010725001 (X001, July 2025, slip no 001)
 *
 * @param employeeCode Employee code directly from user/database (e.g. EMP1, X001, EMP001, EMP-001)
 * @param monthYearStr Month and year string or pay period (e.g. "SEPTEMBER 2026", "2026-09", "09/2026")
 * @param slipSequence Slip sequence number (default 1, produces "001", or 2 for "002", etc.)
 */
export const generateSlipNumber = (
  employeeCode?: string | number | null,
  monthYearStr?: string | null,
  slipSequence: number | string = 1
): string => {
  if (employeeCode === undefined || employeeCode === null || String(employeeCode).trim() === '') {
    return '';
  }

  const cleanEmpCode = formatEmployeeCode(employeeCode);
  if (!cleanEmpCode) return '';

  const parts = String(monthYearStr || '')
    .trim()
    .split(/[\s\/\-]+/)
    .filter(Boolean);
  const monthsList = [
    'JANUARY',
    'FEBRUARY',
    'MARCH',
    'APRIL',
    'MAY',
    'JUNE',
    'JULY',
    'AUGUST',
    'SEPTEMBER',
    'OCTOBER',
    'NOVEMBER',
    'DECEMBER',
  ];

  // 1. Dynamic Fallback to current system date
  const now = new Date();
  let year = now.getFullYear();
  let monthVal = now.getMonth() + 1;

  // 2. Parse selected year and month dynamically from input
  for (const part of parts) {
    const num = Number(part);
    if (!isNaN(num)) {
      if (num >= 1900 && num <= 2100) {
        year = num; // Dynamically sets the selected year (e.g., 2026 -> 26)
      } else if (num >= 1 && num <= 12) {
        monthVal = num; // Dynamically sets selected month if numeric (e.g., 09)
      }
    } else {
      const upper = part.toUpperCase();
      const idx = monthsList.findIndex((m) => m === upper || m.startsWith(upper.slice(0, 3)));
      if (idx !== -1) {
        monthVal = idx + 1; // Dynamically sets selected month (e.g., September -> 09)
      }
    }
  }

  const mm = String(monthVal).padStart(2, '0');
  const yy = String(year).slice(-2);
  const seqNum = Number(slipSequence) || 1;
  const seqStr = String(seqNum).padStart(3, '0');

  // Format: <employeeCode>-<MM><YY><SLIP_NO>
  // e.g. EMP1-1026001 or X001-0926001 or EMP1-1026007
  return `${cleanEmpCode}-${mm}${yy}${seqStr}`;
};

/**
 * Normalizes any payslip number string to the standard dashed format:
 * <EMPLOYEE_CODE>-<MM><YY><SLIP_NO>
 * e.g., 'EMP11026001' -> 'EMP1-1026001'
 * e.g., 'EMP1-1026001' -> 'EMP1-1026001'
 * e.g., 'X0010725007' -> 'X001-0725007'
 */
export const normalizeToDashedSlipNumber = (slipNumber?: string | null): string => {
  if (!slipNumber) return '';
  const trimmed = String(slipNumber).trim();
  if (!trimmed) return '';

  const parsed = parseSlipNumber(trimmed);
  if (parsed && parsed.employeeCode && parsed.month && parsed.year && parsed.slipNo) {
    return `${parsed.employeeCode}-${parsed.month}${parsed.year}${parsed.slipNo}`;
  }
  return trimmed;
};

/**
 * Resolves the payslip number for a salary slip record, prioritizing:
 * 1. Saved localStorage override by slip ID, empCode_monthYear, or userId_monthYear.
 * 2. Explicit direct slip number properties on the record.
 * 3. Serialized [SLIP_NO: ...] in remarks or hr_note.
 * 4. Serialized [SLIP_SEQ: ...] in remarks or hr_note -> generates with that sequence.
 * 5. Explicit sequence property on record (e.g. slip_sequence, sequence).
 * 6. Dynamic fallback sequence passed by the caller (fallbackSequence) or defaults.
 */
export const extractSlipNumber = (
  item: any,
  fallbackSequence?: number
): string => {
  if (!item || typeof item !== 'object') return '';

  const id = item.id || item.salary_slip_id || item.slip_id;
  const rawEmpCode =
    item.employee_code ||
    item.employeeCode ||
    item.employee_id ||
    item.employeeId ||
    item.user_id ||
    item.userId ||
    '';
  const cleanEmpCode = formatEmployeeCode(rawEmpCode);

  const monthsList = [
    'JANUARY',
    'FEBRUARY',
    'MARCH',
    'APRIL',
    'MAY',
    'JUNE',
    'JULY',
    'AUGUST',
    'SEPTEMBER',
    'OCTOBER',
    'NOVEMBER',
    'DECEMBER',
  ];
  let monthYearStr = String(item.monthYear || item.month_year || item.date || '').trim();
  if (!monthYearStr && item.pay_period_month && item.pay_period_year) {
    const mIdx = Number(item.pay_period_month) - 1;
    const mName = monthsList[mIdx] || 'OCTOBER';
    monthYearStr = `${mName} ${item.pay_period_year}`;
  }

  // 1. Check localStorage overrides
  const overrides = getPayrollSlipNoOverrides();
  if (id && overrides[String(id)]) {
    return normalizeToDashedSlipNumber(overrides[String(id)]);
  }
  if (cleanEmpCode && monthYearStr) {
    const key = `${cleanEmpCode}_${monthYearStr}`;
    if (overrides[key]) return normalizeToDashedSlipNumber(overrides[key]);
    if (overrides[key.toUpperCase()]) return normalizeToDashedSlipNumber(overrides[key.toUpperCase()]);
  }
  const uId = item.user_id || item.userId;
  if (uId && monthYearStr) {
    const key = `${uId}_${monthYearStr}`;
    if (overrides[key]) return normalizeToDashedSlipNumber(overrides[key]);
    if (overrides[key.toUpperCase()]) return normalizeToDashedSlipNumber(overrides[key.toUpperCase()]);
  }

  // 2. Check serialized tag in remarks or hr_note (the primary database persistence layer)
  const tagSlip =
    extractSlipNoFromText(item.remarks) ||
    extractSlipNoFromText(item.hr_note) ||
    extractSlipNoFromText(item.hrNote);
  if (tagSlip) return normalizeToDashedSlipNumber(tagSlip);

  // 3. Check serialized sequence in remarks or hr_note
  const tagSeq =
    extractSlipSeqFromText(item.remarks) ||
    extractSlipSeqFromText(item.hr_note) ||
    extractSlipSeqFromText(item.hrNote);
  if (tagSeq && tagSeq > 0) {
    return generateSlipNumber(cleanEmpCode || 'EMP1', monthYearStr, tagSeq);
  }

  // 4. Check explicit sequence fields on the record
  const explicitSeq = Number(
    item.slip_sequence || item.slipSequence || item.sequence || 0
  );
  if (explicitSeq && explicitSeq > 0) {
    return generateSlipNumber(cleanEmpCode || 'EMP1', monthYearStr, explicitSeq);
  }

  // 5. Check direct fields on the record
  const candidateSlip =
    item.paySlipNo ||
    item.pay_slip_no ||
    item.payslipNo ||
    item.payslip_no ||
    item.slipNo ||
    item.slip_no ||
    item.pay_slip_number ||
    item.payslip_number ||
    item.salary_slip_no ||
    item.salary_slip_number;

  if (candidateSlip && String(candidateSlip).trim() !== '' && String(candidateSlip).trim() !== 'null') {
    const trimmedCandidate = String(candidateSlip).trim();
    // If candidate defaulted to 001 but a distinct sequential fallback sequence is provided (>1),
    // prefer the sequential fallback so not everyone ends up with 001
    if (fallbackSequence && fallbackSequence > 1 && trimmedCandidate.endsWith('001')) {
      return generateSlipNumber(cleanEmpCode || 'EMP1', monthYearStr, fallbackSequence);
    }
    return normalizeToDashedSlipNumber(trimmedCandidate);
  }

  // 6. Final fallback sequence (e.g. index in the table) or default 1
  const effectiveSeq = fallbackSequence && fallbackSequence > 0 ? fallbackSequence : 1;
  return generateSlipNumber(cleanEmpCode || 'EMP1', monthYearStr, effectiveSeq);
};

/**
 * Role-Based Access Control (RBAC) Utility
 * Supports multi-role assignments, permission aggregation across roles,
 * and robust permission matching with backward compatibility.
 */

export interface PermissionDefinition {
  id: number | string;
  name: string;
  module: string;
  action: string;
  description?: string;
}

export interface RoleDefinition {
  id: number | string;
  name: string;
  description?: string;
  is_system?: boolean;
  permissions: Array<PermissionDefinition | string>;
  color?: string;
}

